window.DATA_ST={"chapters":[{"n":1,"level":"初级","title":"盲派体系总览","qs":[{"q":"按盲派的体用划分，下列哪一组全部属于「体」？","opts":["禄、比劫、印、官","日主、禄、比劫、印","日主、印、食神、官杀","日主、禄、比劫、财"],"ans":1,"exp":"体是日主、禄、比劫、印（我自己和我使用的工具）；用是财、官杀（我追求的目标）；食伤可体可用。","sec":"四、体与用","t":"rule"},{"q":"食神和伤官，在体用里各偏向哪边？","opts":["食神、伤官都只属用","食神、伤官都只属体","食神偏体，伤官偏用","食神偏用，伤官偏体"],"ans":2,"exp":"食伤属精神体验，可体可用，其中食神偏体，伤官偏用，要看命局需要。","sec":"四、体与用","t":"diff"},{"q":"大运流年出现命局中已有的同一个字，算宾吗？","opts":["算宾，但力量比原局更强","不算宾，但只主凶不主吉","算宾，是外来的别人之物","不算宾，是原局的字到了，多表示应期"],"ans":3,"exp":"大运流年是外来的，但出现命局中已有的同一个字时，不再算宾，而是命局中的字到了，一般表示原局的应期。","sec":"三、宾与主","t":"rule"},{"q":"年月上的财官，在什么情况下能成为自己的？","opts":["被主位所制，或被制后又被主位所得","年月上的财官一律是别人的","只要透出天干就是自己的","日主旺时就是自己的"],"ans":0,"exp":"年月为宾，但其财官若通过一定关系被主位所制，或被它制后又被主位所得，就能成为自己的；与旺衰无关。","sec":"三、宾与主","t":"calc"},{"q":"命中有财官，一定能得财当官吗？","opts":["一定能，财官透干即得","不一定，体必须与用发生刑冲合害破墓关系","一定能，只要日主旺","不一定，要日主旺才可"],"ans":1,"exp":"体必须与用发生刑、冲、合、害、破、墓等关系，财官才可能被日主得到；盲派不论日主旺衰。","sec":"四、体与用","t":"calc"},{"q":"正向做功与反向做功的区别是什么？","opts":["正向是宾位制主位；反向是主位制宾位","正向是主位用追宾位体；反向是主位体制宾位用","正向是主位体制宾位用；反向是主位用追宾位体","正向用刑冲克，反向用穿合墓"],"ans":2,"exp":"正向做功：主位的体去作用、追求或制去宾位的用；反向做功：主位的用去追求宾位的体，层次一般高于正向。","sec":"五、做功、功神、废神","t":"diff"},{"q":"贼捕结构的判定，关键看什么？","opts":["贼较旺捕较弱，捕被反制","贼被制但没制死也算","捕与贼势均力敌，互相制约","捕较旺贼较弱，贼被制死制净"],"ans":3,"exp":"贼捕要求捕旺贼弱、贼被制死制干净；某字被制但没制死，也做功，但不叫贼捕，分析方法不同。","sec":"七、贼神与捕神","t":"diff"},{"q":"贼捕的应期：局中捕旺而无贼，与运、流年一直只见捕不见贼，分别如何？","opts":["大运见贼为吉；运岁都只见捕不见贼应凶","大运见贼为凶；运岁都只见捕不见贼应吉","大运见贼与只见捕不见贼，都应凶","大运见贼为吉；运岁只见捕不见贼也为吉"],"ans":0,"exp":"局中捕旺喜大运贼神出现（运中捕旺喜流年贼神）；局中有捕无贼、运中见捕不见贼、局运流年都只见捕不见贼应凶。","sec":"七、贼神与捕神","t":"step"},{"q":"同样是「不好」，要判断是生病、破财还是官司，主要靠哪一法？","opts":["能量效率法","象法","宾主法","理法"],"ans":1,"exp":"理法只能断吉凶，断不到具体事件；象法把吉凶具体化、形象化，所以病、破财、官司要靠象。","sec":"二、论命三法：理法、象法、技法","t":"diff"},{"q":"八字中天干与地支的能量相比如何？","opts":["天干能量高，地支能量低","按日主旺衰而定，没有固定","天干能量低，地支能量高","天干地支能量相同"],"ans":2,"exp":"八字中每个字都有能量，天干能量低、地支能量高；功神耗散能量后产生了效率。","sec":"六、能量与效率","t":"rule"}],"fine":[{"q":"关于盲派对「日主旺衰」与「用神忌神」的态度，最准确的说法是哪项？","opts":["只看日主旺衰，不看用神忌神","体系里根本没有旺衰与用神这些概念","只用旺衰判断身体强弱，不用来断财官","先定格局与用神，再看结构做功"],"ans":1,"exp":"盲派严格说不是废弃旺衰与用神，而是体系里根本没有这些概念，只看结构（做功、宾主、体用）与象。","sec":"一、盲派与传统、新派命理的区别","t":"diff"},{"q":"把日主旺衰放在最重要位置、简单分成用神和忌神两个对立面的是哪一派？","opts":["盲派命理","传统命理","新派命理","格局派命理"],"ans":2,"exp":"传统命理讲用神与格局，《滴天髓》为其理法集大成；新派命理把日主旺衰放最重要位置，简单划分用神忌神。","sec":"一、盲派与传统、新派命理的区别","t":"diff"},{"q":"现代整理的「宾主、体用、功神废神、能量效率、贼捕」等概念，属于论命三法中的哪一类？","opts":["象法","技法","神煞法","理法"],"ans":3,"exp":"盲派传承历来口授心传，现代整理出的宾主、体用、功神废神、能量效率、贼捕等新概念属于理法范畴。","sec":"一、盲派与传统、新派命理的区别","t":"rule"},{"q":"在盲派论命三法中，「理法」能解决的核心问题是什么，其局限又在哪里？","opts":["能断富贵贫贱、职业大类与大致吉凶，断不到具体事件","只能断父母有无克，不能断大运流年吉凶","能断具体事件如生病破财，但断不出富贵层次","能直接定出婚姻次数，但看不出职业方向"],"ans":0,"exp":"理法能读懂八字吉凶、富贵贫贱与职业大类，但断不到生病、破财、官司、升官等具体事件。","sec":"理法","t":"rule"},{"q":"在盲派论命中，理法（做功）与象法的使用比例及先后顺序分别是怎样的？","opts":["做功与象法各占一半；先看象法再排宾主","约八成用做功、两成用象；先看做功再看象","约两成用做功、八成用象；先看象再看做功","全部八字都只用做功，象法仅作参考"],"ans":1,"exp":"约80%的八字用做功来表述，约20%用象来表述；原则是先看做功，再看象，有功有象则功象同看。","sec":"象法","t":"step"},{"q":"判断父母有无克、是否健在，以及婚姻质量高低、几次婚姻、终身无婚，最终靠什么定夺？","opts":["象法","能量效率","技法","理法"],"ans":2,"exp":"看父母有无克、婚姻质量与婚次、终身无婚等，虽用到理法与象法，但最后靠盲派历代相传的技法定夺。","sec":"技法","t":"rule"},{"q":"下列哪一句属于盲派历代相传的「技法」口诀？","opts":["日主得令为旺，失令为衰，衰则喜生扶","官杀混杂无制，必主终身孤贫贱命","财多身弱，富屋贫人，必以比劫为用","甲生酉月喜水润，乙生酉月宜火攻"],"ans":3,"exp":"盲派技法口诀包括「坐下财（官杀）库喜刑冲」「甲生酉月喜水润，乙生酉月宜火攻」「外食内杀是当教师的人」等。","sec":"技法","t":"rule"},{"q":"盲派中的「宾主」与「体用」分别从什么角度来划分命局？","opts":["宾主从宫位角度划分，体用从十神角度划分","宾主只看年柱月柱，体用只看日柱时柱","宾主从旺衰角度划分，体用从寒暖角度划分","宾主从十神角度划分，体用从宫位角度划分"],"ans":0,"exp":"宾主与体用都是分析八字的手段，角度不同：宾主论宫位，体用论十神。","sec":"三、宾与主","t":"diff"},{"q":"宾主共有四个层次，实际分析命局时通常以哪一层次为主？","opts":["第四层：大运流年为主，原局四柱为宾","第二层：日柱为主，年、月、时柱为宾","第一层：仅日干为主，日支及年月时全为宾","第三层：年柱月柱为主，日柱时柱为宾"],"ans":1,"exp":"分析时以第二层为主，即以日柱为自己小家（主），看日干及坐支与其他干支发生了什么关系。","sec":"四个层次","t":"step"},{"q":"主位通常重点在日柱，但时柱在什么条件下也可当作主位来看？","opts":["时柱见偏财或正财通根","时柱与年柱天合地合","时柱见禄，或见日主所生的食伤","时柱见正官或七杀透干"],"ans":2,"exp":"主位通常指日柱、时柱，重点在日柱；若时柱见禄，或见日主所生的食伤，也可把时柱当主位看。","sec":"四个层次","t":"rule"},{"q":"丁日主坐下酉财（主位），被午火与戌燥土制去，若宾位不透劫财，此结构如何断？","opts":["只要坐支有财，不做功也自然富贵","主位财被制死，主一生贫穷克妻","主位财不可被制，被制即等于被别人劫走","主位财被制去表示有财，并非财被劫走"],"ans":3,"exp":"坐支财官一定要用来做功，主位财被火土制去表示有财，不等于被劫走；但若宾位透劫财则财被别人劫。","sec":"宾主的用法","t":"calc"},{"q":"盲派体用中的「用」与传统命理中的「用神」有何关系？","opts":["两者毫无关系，盲派的「用」指财官等追求目标","两者完全相同，只是称呼不同","盲派的「用」就是传统命理中扶抑日主的用神","盲派的「用」特指日主坐支的印星和禄神"],"ans":0,"exp":"体用的「用」指财、官（杀）等命主追求的外物目标，与传统命理讲扶抑、平衡的「用神」是两回事。","sec":"四、体与用","t":"diff"},{"q":"关于不同的「体」做功对应的象法与层次，下列说法正确的是哪项？","opts":["印制财主体力劳动，比劫做功主考取功名","印制财多凭单位或学业取财；比劫做功有炒作之意","禄或比劫做功层次最高，绝对不会从事体力职业","比劫取财永远得不到大财，只能赚小钱"],"ans":1,"exp":"印制财凭单位、学业等手段取财；禄或比劫做功一般层次不高，但效率极高者也可发大财，且有炒作之意。","sec":"不同的体做功","t":"xiang"},{"q":"辛丑日主，月支酉为禄去冲年支卯，为何不主辛苦劳碌反主有福气？","opts":["因为酉卯相冲属于金克木，金旺则自然富贵","因为辛金日主生于酉月得令，身旺可任财官","日主坐丑为印，禄逢印主有福，印禄相随","因为年支卯木在宾位，被冲掉就不会克日主"],"ans":2,"exp":"单纯禄做功多主辛苦，但辛丑日主坐下丑为印，禄逢印主有福，印禄相随，故不主辛苦。","sec":"不同的体做功","t":"calc"},{"q":"从日柱入手看八字时，若日柱「占体」与日柱「占用」，各须如何才算好结构？","opts":["占体须安静不动，占用须孤立不被外神作用","无论占体还是占用，只要见食伤透干即可","占体和占用都必须被年柱冲克才能发贵","占体须去作用别神，占用须被外面的体制化合"],"ans":3,"exp":"占体如同人手，必须有事做去作用别神；占用是身外之物，必须被外面的体制、化或合，闲着则平庸或为凶。","sec":"五、做功、功神、废神","t":"step"},{"q":"在功神、辅神与废神（闲神）的区分中，互相制衡做功的双方属于什么神？","opts":["互制双方都是功神","力量大的是功神，力量小的是闲神","主动制方是功神，被制方是辅神","主动制方是功神，被制方是废神"],"ans":0,"exp":"参与做功的字（互制双方）都是功神；帮助功神做功的字是辅神；不参与做功的字才是废神（闲神）。","sec":"五、做功、功神、废神","t":"rule"},{"q":"正向做功与反向做功相比，通常哪种做功方式的命局层次更高？","opts":["两者层次完全相同，只看天干是否透出","反向做功层次一般高于正向，大格局多属反向","反向做功多主贫贱，只能做普通体力劳动","正向做功层次远高于反向，大格局皆属正向"],"ans":1,"exp":"主位的用去追求宾位的体称为反向做功，其层次一般高于正向做功，许多大格局都属于反向做功。","sec":"五、做功、功神、废神","t":"diff"},{"q":"从能量与效率的角度看，成功者八字与平庸者八字的根本区别是什么？","opts":["成功者只用相生不做功，平庸者只用相冲","成功者天干字数多，平庸者地支字数多","成功者功神多废神少或效率高，平庸者反之","成功者废神多而功神少，平庸者功神多而废神少"],"ans":2,"exp":"成功者的八字有效率地利用能量，功神多而废神少，或功神虽少但效率高；平庸者废神多功神少或效率低。","sec":"六、能量与效率","t":"diff"},{"q":"在主位或属「体」的字（例如印星），被宾位或属「用」的字制死制净，能否构成贼捕结构？","opts":["只有地支相冲才算贼捕，天干克合不算","不可以，只能是主位体制宾位用才算贼捕","不可以，印星属体，被制只主破印应凶","可以，主或体被宾或用制死制净也属贼捕"],"ans":3,"exp":"贼捕不仅指主或体制宾或用，在主或体的字被宾或用制死制净（如属体的印被制净），同样可构成贼捕结构。","sec":"七、贼神与捕神","t":"rule"},{"q":"若某命局表面看似贼捕结构，但行至捕神出现的运或流年反而应吉，这说明什么？","opts":["说明该字并没有被制死，不符合贼捕条件","说明该命局从贼捕变成了正向做功","说明原局的贼神太弱，需要捕神来帮扶","说明捕神运也能当成贼神运来使用"],"ans":0,"exp":"真贼捕见捕神运应凶；若表面像贼捕而捕神运或年反吉，说明该字并未被制死制净，不符合贼捕条件。","sec":"辨别要点","t":"calc"},{"q":"贼捕结构为什么普遍「喜走贼运」，而不喜走捕运？","opts":["因为捕神太旺容易耗尽日主元气导致身弱","捕旺贼弱效率不高，见贼运被制才能做高效之功","因为贼神出现后可以反过来把捕神克死","因为贼运能把原局的废神全部合化成用神"],"ans":1,"exp":"原局捕过旺而贼弱或无贼时，做功效率不高；走贼运使贼神出现并被强势制去，做出高效率的功，故应吉。","sec":"辨别要点","t":"rule"},{"q":"盲派入门中，「正用」与「反用」的核心区别是什么？","opts":["正用是先看象法；反用是先看理法","正用是天干做功；反用是地支做功","正用主位体宾位用；反用主位用宾位体","正用是相生相合；反用是相冲相穿"],"ans":2,"exp":"正用是主位为体、宾位为用，以主位体制宾位用；反用是主位为用、宾位落了体。","sec":"八、正用与反用、正局与反局（入门提示）","t":"diff"},{"q":"盲派取象把干支符号变成具体人事物，最主要依靠哪三种取象工具？","opts":["六爻卦象、奇门九宫、三合化局定象","日主旺衰、喜用神五行、十二长生宫","大运神煞、胎元命宫、纳音五行生克","干支本象、刑冲化合定象、干支配置互换"],"ans":3,"exp":"盲派取象的三种主要工具是：干支本身的象、刑冲化合定象、干支配置（天干地支一家可互换互代）。","sec":"九、象与取象的工具","t":"xiang"},{"q":"己丑日主坐丑食神库，食神辛酉冲官卯且丑合子财，断其职业为律师而非公检法官员的依据是？","opts":["坐库文书多，食神主自由且合财，合法对抗公检法","因为己土身弱不能任官，只能靠财星养命","因为卯酉冲破了官星根基，注定一生无官运","因为食神制官一律不当官，只能做自由职业"],"ans":0,"exp":"坐丑库表示法律文书多且是自己企业，食神主自由、合子财表示拿钱辩护，以文书合法与公检法对着干，故断律师。","sec":"取象命例：看出做律师","t":"xiang"}]},{"n":2,"level":"初级","title":"宫位取象与吉凶","qs":[{"q":"看六亲，宫位与六亲的亲缘由近至远，正确排序是哪个？","opts":["日支、时支、时干、月支、月干、年上","时干、时支、日支、月干、月支、年上","日支、时干、时支、月干、月支、年上","日支、月干、月支、时干、时支、年上"],"ans":2,"exp":"亲缘由近至远：日支——时干——时支——月干——月支——年上。","sec":"二、八类宫位取象","t":"step"},{"q":"断买房与买车，分别看哪个宫位？","opts":["房看日支，车看年柱","房看时柱，车看日支","房看月柱，车看日支","房看日支，车看时柱"],"ans":3,"exp":"日支是日主的根，代表家、房子；时为门户，代步工具看时柱。","sec":"二、八类宫位取象","t":"diff"},{"q":"身体取象中，年柱、日支、时柱各主什么部位？","opts":["年柱腿足，日支五脏六腑，时柱头面手眼","年柱躯干，日支腿足，时柱五脏六腑","年柱腿足，日支头面手眼，时柱五脏六腑","年柱头面，日支五脏六腑，时柱腿足"],"ans":0,"exp":"年柱离日干最远主腿足四肢，日支最重要主胸部五脏，时柱主露在外面的器官。","sec":"二、八类宫位取象","t":"xiang"},{"q":"日柱与年月柱受伤，对寿命的影响有何不同？","opts":["年月坏损寿，日柱坏无碍","日柱坏损寿，年月坏不碍寿","日柱年月坏都不影响寿命","日柱年月坏都同样损寿"],"ans":1,"exp":"口诀：日主坐根连体则不能坏；日柱代表五脏六腑，年月代表腿足躯干。","sec":"二、八类宫位取象","t":"rule"},{"q":"天干与地支在宫位取象中，分别代表什么？","opts":["天干为祖上，地支为后代","天干为动象，地支为静象","天干为表象，地支为内心","天干为内心，地支为表象"],"ans":2,"exp":"天干在外，代表性格表象；地支在内，代表内心世界和隐蔽的思想。","sec":"二、八类宫位取象","t":"diff"},{"q":"功神所在，出远门与在家哪个更好？","opts":["无论功神在哪，出远门都吉","功神在日支宜出远门，在年时宜在家","功神在月柱宜出远门，在日支宜在家","功神在日支宜在家，在年时宜出去"],"ans":3,"exp":"用的东西在日支，最好不要出去；在年、时两头，肯定出去好。","sec":"三、地域宫位的应用","t":"rule"},{"q":"月柱与日支相冲、相合，分别主什么？","opts":["冲主背井离乡，合主离不开祖籍","冲合都主离开祖籍，只是迟早不同","冲主离不开祖籍，合主背井离乡","冲主配偶同乡，合主远嫁异地"],"ans":0,"exp":"月日支一冲，必背井离乡；一合，自然离不开；配偶宫合到月令，多是同乡、同学、同事。","sec":"三、地域宫位的应用","t":"diff"},{"q":"日支（配偶宫）与年柱相合，配偶的特点如何论？","opts":["年大年长；合到月则最小","年大年长且远方；合到时则年小","年小且在本地；合到时则年大","年长但在本地；合到时则远方"],"ans":1,"exp":"年为大，时为小；配偶宫合到年则年龄大，且年代表远方。","sec":"四、宫位的年岁（大小）","t":"calc"},{"q":"盲派用生成之数断数目，水、木各主几？","opts":["水主三，木主六","水主一，木主八","水主六，木主三","水主六，木主八"],"ans":2,"exp":"生成之数：木上财主三，如3000万；水主六，如60岁、六千里。","sec":"四、宫位的年岁（大小）","t":"calc"},{"q":"年柱为功神，被哪一柱冲克才为忌？","opts":["被日柱冲克为忌，月时不为忌","被时柱冲克为忌，月日不为忌","被月日时三柱冲克都为忌","被月柱冲克为忌，日时不为忌"],"ans":3,"exp":"年柱功神被月柱冲克为忌，日时较远，冲克无力，一般不为忌。","sec":"五、宫位的吉凶","t":"rule"},{"q":"吉神所在柱被他柱忌神冲克，什么情形下此忌不为忌？","opts":["该忌神又被别的字制住","该忌神在年柱最远处","该忌神被大运冲合","该忌神与日主同柱"],"ans":0,"exp":"例外：忌神若又被别的字制住，则此忌不为忌，要细心辨识。","sec":"五、宫位的吉凶","t":"rule"}],"fine":[{"q":"用盲派方法看六亲或六亲所主之事，星位与宫位应以何为主、何为辅？","opts":["只看星位旺衰，不看宫位","以星位为主、宫位为辅","以宫位为主、星位为辅","天干看星位，地支才看宫位"],"ans":2,"exp":"盲派认为六亲信息重点体现在四柱宫位中，看六亲或六亲所主之事，以宫位为主、星位为辅。","sec":"一、为什么以宫位为主","t":"rule"},{"q":"若命局中父母星出现在日柱或时柱上，而非年月柱，断父母之事应以何为主？","opts":["改以日时宫位为父母宫","直接以日支代表父亲、时支代表母亲","父母星不在年月即主父母早亡","仍要以年月宫位为主"],"ans":3,"exp":"年、月为父母宫，即使父母星落在日、时柱上，断父母之事仍要以年月宫位为主。","sec":"一、为什么以宫位为主","t":"calc"},{"q":"岳父母、公婆等外戚长辈，在四柱六亲宫位中应看哪一柱？","opts":["年柱，不分年干或年支都算","日支，因为配偶宫连带配偶父母","时柱，代表外来的亲戚","月柱，只看月支不算月干"],"ans":0,"exp":"年柱代表祖上、父母、外戚长辈（如岳父母、公婆），且不分干支，在年干或年支都算。","sec":"1. 六亲","t":"xiang"},{"q":"在六亲宫位划分中，父母主要看哪几个宫位？","opts":["固定以年干为父、月支为母","统称年月为父母宫，年上月上都可体现","只看年柱，月柱只管兄弟姐妹","只看月柱，年柱只管祖上"],"ans":1,"exp":"父母既可在年上体现，也可在月上体现，统称年月为父母宫。","sec":"1. 六亲","t":"rule"},{"q":"在宫位对应的人生阶段中，月柱（青年）和日支（中年）分别大致对应多少岁？","opts":["月柱约15–30岁，日支约30–60岁","月柱约20–40岁，日支约40–65岁","月柱约18–35岁，日支约35–55岁","月柱约1–18岁，日支约18–35岁"],"ans":2,"exp":"年柱1–18岁（童年幼年），月柱18–35岁（青年），日支35–55岁（中年），时柱55岁以后（晚年）。","sec":"2. 时间（人生阶段）","t":"rule"},{"q":"宫位还代表事件发生的先后顺序，四柱的排列顺序代表什么规律？","opts":["从时到年，由小到大、由先到后","从日到年，由近到远、由先到后","从月到时，先内后外、先吉后凶","从年到时，由大到小、由先到后"],"ans":3,"exp":"四柱宫位代表事件发生的先后顺序，从年柱到时柱，呈由大到小、由先到后的规律。","sec":"2. 时间（人生阶段）","t":"step"},{"q":"在空间取象中，「祖籍、家乡、根」与「比年柱更远的地方」分别对应哪两个宫位？","opts":["月柱主祖籍家乡，时柱门户比年柱更远","月柱主远方海外，日支主祖籍家乡","日支主祖籍家乡，年柱比时柱更远","年柱主祖籍家乡，月柱比年柱更远"],"ans":0,"exp":"月柱代表祖籍、家乡、根；年柱代表远方海外；时柱为门户，代表比年柱更远的地方。","sec":"3. 空间","t":"xiang"},{"q":"要判断一个人一生是否容易出远门，最准确的是看哪两个宫位？","opts":["日干和日支","年柱和时柱","月柱和日支","年柱和月柱"],"ans":1,"exp":"年柱代表远方边缘，时柱为门户出门，断是否出远门看年柱和时柱非常准确。","sec":"3. 空间","t":"rule"},{"q":"在人物取象中，「同学、同事、老乡、领导」与「晚辈、学生、朋友、下属」分别看哪个宫位？","opts":["前者看日支，后者看年柱","前者看年柱，后者看日支","前者看月柱，后者看时柱","前者看时柱，后者看月柱"],"ans":2,"exp":"月柱主同学、同事、老乡、领导；时柱主晚辈、小孩、学生、朋友、下属。","sec":"4. 人物","t":"xiang"},{"q":"「外人、外戚、长辈、老人」在四柱人物取象中对应哪个宫位？","opts":["月柱","日支","时柱","年柱"],"ans":3,"exp":"年柱在人物取象中代表外人、外戚、长辈、老人。","sec":"4. 人物","t":"xiang"},{"q":"在身体部位取象中，「躯干、脊、肩、背」与「头面、手眼、生殖排泄器」分别看哪两柱？","opts":["月柱主躯干肩背，时柱主头面手眼及生殖排泄","月柱主腿足四肢，时柱主躯干脊柱","年柱主躯干肩背，月柱主头面手眼及生殖排泄","日支主躯干肩背，时柱主五脏六腑及脑髓"],"ans":0,"exp":"年柱主腿足四肢，月柱主躯干脊肩背，日支主胸五脏六腑脑髓，时柱主露在外面的头面手眼及生殖排泄器。","sec":"5. 身体","t":"xiang"},{"q":"在使用之物取象中，「鞋子、别人之物」与「工作单位、学业」分别对应哪个宫位？","opts":["鞋子看时柱，工作单位和学业看日支","鞋子看年柱，工作单位和学业看月柱","鞋子看月柱，工作单位和学业看时柱","鞋子看日支，工作单位和学业看年柱"],"ans":1,"exp":"年柱代表鞋子、祖先及别人之物；月柱代表祖产、家业、单位（如官星在月柱主工作单位）与学业。","sec":"6. 使用之物","t":"xiang"},{"q":"看房子时，若日支为寅，命局中又出现卯或另一个寅并发生关系，主什么象？","opts":["表示房子被他人强占，一生无房可住","表示房子漏水破败，必须立即搬家","「一家两处」，表示有两处或多处房子","表示只能租房居住，不能买属于自己的房"],"ans":2,"exp":"日支代表房子、家；日支是寅又出现卯或另一寅并发生关系，即「一家两处」，表示有多处房子。","sec":"6. 使用之物","t":"calc"},{"q":"时柱看车与丢车时，为什么说其体现具有相对性？","opts":["因为时柱有时看车，有时看房子，没有固定标准","因为男性看时柱，女性看年柱，男女标准不同","因为富贵人永远不会丢车，只有普通人才会丢车","富贵人丢自行车无关紧要难看出，普通人则是大事"],"ans":3,"exp":"时柱出问题主丢车，但这是相对的：富贵人丢自行车不算大事不一定看得出来，普通人则是大事。","sec":"6. 使用之物","t":"diff"},{"q":"「衣服、帽子、眼镜、化妆、进出之钱财」在物件取象中归属哪个宫位？","opts":["时柱","月柱","日支","年柱"],"ans":0,"exp":"时柱为门户，在物件取象中主车、门、衣服、帽子、眼镜、化妆以及进出之钱财。","sec":"6. 使用之物","t":"xiang"},{"q":"在心志与情商取象中，哪两个宫位分别反映人的「内心世界」和「交际能力及影响力」？","opts":["月柱主内心世界，日支主交际能力及影响力","日支主内心世界，时柱主交际能力及影响力","时柱主内心世界，年柱主交际能力及影响力","年柱主内心世界，月柱主交际能力及影响力"],"ans":1,"exp":"年柱主外部环境，月柱主父母的影响，日支主内心世界，时柱主交际能力和影响力。","sec":"7. 心志与情商","t":"xiang"},{"q":"在心志与情商取象中，年柱与月柱分别代表什么因素？","opts":["年柱代表内心世界，月柱代表交际能力","年柱代表父母的影响，月柱代表外部环境","年柱代表外部环境，月柱代表父母的影响","年柱代表祖上遗传，月柱代表配偶影响"],"ans":2,"exp":"心志与情商取象：年柱为外部环境，月柱为父母的影响，日支为内心世界，时柱为交际能力和影响力。","sec":"7. 心志与情商","t":"xiang"},{"q":"正印在天干透出且无伤为喜，但地支的禄却被穿坏，这在人的心性上主什么？","opts":["表面凶恶难相处，其实内心极为善良正直","表里如一，一生清正廉洁，毫无私心","主幼年愚钝，中年以后才突然开窍变聪明","表面像是好人，内心不好，暗地里什么坏事都做"],"ans":3,"exp":"天干为表，地支为里。正印在天干无伤只是表象好，地支禄被穿坏说明内在心性不好，暗地里做坏事。","sec":"8. 内外：天干为表，地支为里","t":"calc"},{"q":"在地域宫位应用中，若配偶宫（日支）合到月令，找的配偶多具有什么特点？","opts":["多是同乡、同学、同事之类","多是通过长辈介绍的豪门显贵","多是远方异国之人，且年龄相差极大","多是晚辈、学生或下属之类"],"ans":0,"exp":"月柱为祖籍、同学、同事；月日支一合，自然离不开，配偶宫合到月令，找的多是同乡、同学、同事。","sec":"三、地域宫位的应用","t":"xiang"},{"q":"「女犯重伤官找奇特婚姻」这句口诀的取象依据是什么？","opts":["伤官生财，所以只看重对方家产而不管年龄","伤官主离经叛道、与传统不同，故对象易偏大或偏小","伤官必定克夫，所以只能嫁给年老体弱之人","伤官代表远方海外，所以注定远嫁外国"],"ans":1,"exp":"伤官是离经叛道、与传统不同的星，重伤官者婚姻观念异于常人，对象或大或小，若再合到年上便易找老夫。","sec":"命例一：配偶宫合年，远方且年长","t":"rule"},{"q":"月柱为功神且得力时主受长辈庇荫、可承父业；若月柱功神被年柱或日柱冲克，主什么？","opts":["子女不孝、凶顽不尊、晚景凄凉","婚姻中途抛离、断弦再续","背祖离乡、六亲缘浅、同胞不和","祖辈在命主出生前破产败落"],"ans":2,"exp":"月柱功神被年柱或日柱冲克，主背祖离乡、六亲缘浅、同胞不和；日支被冲克才主婚姻中途抛离。","sec":"五、宫位的吉凶","t":"rule"},{"q":"日支为功神本主妻贤夫贵、能得配偶帮助，但若被他柱克、破或化合为忌，在婚姻上主什么？","opts":["终身无婚，绝无配偶缘分","必定背井离乡，与同胞兄弟不和","夫妻白头偕老，只是早年多口角","好而不久，婚姻中途抛离，断弦再续"],"ans":3,"exp":"日支功神得力主婚姻较好；若被克、破或化合为忌，则好而不久，婚姻中途抛离、断弦再续。","sec":"五、宫位的吉凶","t":"rule"},{"q":"时柱为功神被冲克，与「时柱本身为忌」在子孙与晚年上的应象有何不同？","opts":["前者主好而不久或远离，后者主子女不孝、晚景凄凉","前者主子女不孝，后者主子女早年离家出走","前者主早年克父，后者主中年克妻","两者完全相同，都主子女凶顽不尊"],"ans":0,"exp":"时柱功神得力主儿孙才能出众、孝敬；被冲克则好而不久或远离；时柱本身为忌则子女不孝、凶顽不尊、晚景凄凉。","sec":"五、宫位的吉凶","t":"diff"}]},{"n":3,"level":"初级","title":"十神类象与虚透","qs":[{"q":"按盲派，官杀虚透于天干（即使被制得很好），主什么？","opts":["主当官有权","主有文凭学历","主钱财丰厚","只主名气，不主有官"],"ans":3,"exp":"纯粹虚透的官杀被制是无用的，只表名声名气；真正当官要官杀实而被制净。","sec":"七、十神虚透","t":"rule"},{"q":"官杀被制，按盲派口径，「制净」与「制不净」分别主什么？","opts":["制净当官，制不净当有文化","制净得权力，制不净主小人","制净主名气，制不净主官非","制净有文化，制不净当官"],"ans":0,"exp":"口诀：官杀制净为当官，有化或制不净当文化看；制不净的官杀还可当财看。","sec":"看官杀的规则","t":"diff"},{"q":"官杀由实变虚、然后被制，一般怎么论？","opts":["一定有牢狱","容易有官","官杀被废当忌论","只主名气不主官"],"ans":1,"exp":"例外情形：年月官杀特别重到时上变轻而被制，或日时重到年月变轻而被制，实转虚再被制容易有官。","sec":"看官杀的规则","t":"rule"},{"q":"内食神格的成格条件是什么？","opts":["天干地支都透食神","地支食神被天干官杀所制","地支有食神，天干不透食神","天干透食神，地支无食神"],"ans":2,"exp":"天干为外、地支为内；内食神成格者多为企业家。个别天干透出者，地支食神必须旺相。","sec":"内食神格","t":"rule"},{"q":"天干透食神与内食神（地支食神不透）的职业倾向区别是？","opts":["透干多做企业，内食神多做教师","两者都主企业，只是大小不同","透干主辛劳职业，内食神主公职","透干靠技艺受人尊重，内食神多做企业"],"ans":3,"exp":"透干为「外吃人」，有一技之长；内食神为「被人吃」，养活他人，成格多为企业家。","sec":"内食神格","t":"diff"},{"q":"甲、丙、戊、庚、壬五个阳干，按盲派，羊刃依次落在哪个地支？","opts":["卯、午、未、酉、子","卯、午、辰、酉、子","寅、午、未、申、亥","卯、午、午、酉、子"],"ans":0,"exp":"盲派羊刃：甲在卯、丙在午、戊在未、庚在酉、壬在子，与传统略有差别（戊刃在未）。","sec":"羊刃","t":"calc"},{"q":"日主乙木，地支见卯，按盲派该论什么？","opts":["比肩禄，不论劫财","劫财，不论羊刃","食神","羊刃"],"ans":1,"exp":"阳干有刃、阴干无刃，阴干遇刃当劫财看。","sec":"羊刃","t":"calc"},{"q":"盲派用羊刃，什么情况下算吉？","opts":["羊刃被冲为吉","羊刃遇财星为吉","羊刃合杀为吉，其余都不吉","羊刃遇印生为吉"],"ans":2,"exp":"羊刃太旺太弱都不好，不能被刑冲合，唯独羊刃合杀例外；羊刃喜制服。","sec":"羊刃","t":"rule"},{"q":"某八字时柱为「甲申」，月柱为「丙寅」，时干甲（财）按盲派论虚还是透？","opts":["要看年柱有无根才定","月支寅是甲根，不论虚透","日主不论虚透，故甲不虚","仍论虚透，只论本柱"],"ans":3,"exp":"虚透只论本柱，一柱之干即使在他支见根，该干在此柱仍论虚透。","sec":"定义（只论天干，只论一柱）","t":"calc"},{"q":"下列哪一项不在虚透的判断范围内？","opts":["日主与比劫天干","年干","月干","时干"],"ans":0,"exp":"只论年、月、时三柱天干；地支都是实的，日主与比劫不论虚透。","sec":"定义（只论天干，只论一柱）","t":"rule"},{"q":"印星虚透，局中「用印」与「忌印」的学历判断有何不同？","opts":["两者都没文凭，忌印更差","用印虚透没文凭，忌印虚透有文凭","用印虚透有文凭，忌印虚透没文凭","两者都有文凭，只是高低不同"],"ans":1,"exp":"局中用印而虚透：没文化文凭；局中忌印而虚透，或虽忌被制去，反而有文化文凭。","sec":"各十神虚透的含义","t":"diff"},{"q":"十神虚透用于应期，原局「实而为用」时，大运怕见什么？","opts":["怕大运见合","怕大运见实","怕大运见虚","怕大运见冲"],"ans":2,"exp":"实而为用怕大运中虚，虚而为用怕大运见实；但大运之实若被原局制化则不怕。","sec":"虚透用于应期","t":"rule"}],"fine":[{"q":"在十神意向推演中，若命局中食神合了印星，命主通常适合从事哪类职业？","opts":["纯体力、机械类的职业","投机赌博、高风险炒作职业","武职、军警执法类职业","思想性、文化类的职业"],"ans":3,"exp":"食神代表头脑、智商、思想、想象力，印代表文化、权力、文类职业；食神合印，主从事思想性、文化类职业。","sec":"一、总则：十神的意向","t":"xiang"},{"q":"关于十神做功的「自合」口诀，下列哪项表述最准确？","opts":["自合双方都为有功，能量的流动就是功","自合属于内部消耗，双方都论作废神","只有天干制地支才算有功，地支制天干不算","只有日柱自合才算功，年月自合不算功"],"ans":0,"exp":"口诀：有用＝被制、被化、做功。被制＝有功；自合，双方都为有功，能量的流动就是功。","sec":"一、总则：十神的意向","t":"rule"},{"q":"正印与偏印在学术倾向和心性上的主要区别是什么？","opts":["偏印主懒惰呆滞，正印主心眼多、不随大流","正印主正统学术、稳重；偏印主非正统、精明机智","正印和偏印都只主正统教科书学术，毫无区别","正印主非正统学术、机智；偏印主正统学术、忠厚"],"ans":1,"exp":"正印为正统学术，心性内向稳重仁慈；偏印为非正统学术，不爱学教科书、不随大流、机智精明有谋略。","sec":"二、印星","t":"diff"},{"q":"八字中「印被制」一般当作什么看？而「年月有偏印」者又多主什么？","opts":["印被制主失学无靠；年月有偏印主受祖辈重用","印被制主多病寿短；年月有偏印主兄弟和睦","印被制主得权力；年月有偏印主与父母祖上缘浅","印被制主破财克妻；年月有偏印主早年得大财"],"ans":2,"exp":"印星代表权力，印被制一般当作得权力看；年月有偏印者，多数表示与祖上父母血缘远或缘分浅。","sec":"二、印星","t":"rule"},{"q":"正印太过且命局无官杀压力时，容易表现出哪种负面心性？","opts":["尖锐刻薄、嫉贤妒能、犯罪意识","风流多情、喜投机、不思正当谋生","暴躁好斗、匪气冲天、不计后果","依赖心强、惰性、无主见、流于懒惰"],"ans":3,"exp":"正印太过的负面心性是依赖心强、随大流、无主见、优柔寡断，尤其无官杀压力时易流于懒惰。","sec":"二、印星","t":"xiang"},{"q":"七杀合身时，「杀无功合身」与「杀有功合身」分别主什么？","opts":["杀无功合身主被人管，杀有功合身主有权力","两者都主官非牢狱，绝不能合身","杀无功合身主有权力，杀有功合身主被人管","两者都主当大官，只是级别高低不同"],"ans":0,"exp":"看官杀规则：杀无功合身代表被人管束压制；杀有功合身则代表掌权、有权力。","sec":"看官杀的规则","t":"diff"},{"q":"若命局中官杀本身没有被制化，但它去制别的字而做功了，且与主位有关，应如何论？","opts":["只主有文化，绝不能有工作或官职","论吉","仍论凶，官杀无制化必作小人忌神","论平庸废神，既不主吉也不主凶"],"ans":1,"exp":"官杀虽无制化，但若它去制别的字而做功，只要与主位有关，依然论吉。","sec":"看官杀的规则","t":"calc"},{"q":"七杀在天干虚透与在地支出现，各自主要表现什么象？","opts":["天干地支都只表官非小人，没有其他含义","天干虚透表懦弱无能，地支七杀表懒惰依赖","天干虚透表名声，地支七杀表心力强、有心劲","天干虚透表掌实权，地支七杀表有名无实"],"ans":2,"exp":"天干七杀虚透主名声、名气；地支七杀则表心力强、有心劲、有魄力。","sec":"看官杀的规则","t":"diff"},{"q":"断官命时为什么强调要结合生活实际，考虑国度与地域差别？","opts":["因为出国后原局八字就不再起作用","因为不同国家干支五行生克规律完全相反","因为国外没有官杀十神，只看财星和印星","同样高学历官命，在国内多当官，在国外或为高管"],"ans":3,"exp":"同样杀被印化、高学历兼官象的命局，在国内环境肯定当官，但在美国等环境则可能不以从政做官为主而任高管或学者。","sec":"命例：杀被化而有文化、官象","t":"rule"},{"q":"财星在身体类象中主什么？地支中哪两个字又特主「色欲」？","opts":["主分泌物排泄物饮食血液呼吸；寅申为色欲","主头面毛发皮肤；子午卯酉为色欲","主神经外伤四肢；辰戌丑未为色欲","主舌头乳房精子；巳亥为色欲"],"ans":0,"exp":"财星身体类象为一切分泌物与排泄物、饮食、血液、呼吸；地支之财为欲望象征，其中寅申为色欲。","sec":"四、财星","t":"xiang"},{"q":"男女命看感情各有侧重，男命与女命的感情一般分别与什么十神有关？","opts":["女命看比劫，男命只看正官七杀","女命看偏财（财星），男命一般与食伤有关","男女命都只看日支坐下的比肩禄神","女命看食伤，男命看正偏印"],"ans":1,"exp":"偏财在女命代表感情之星（财有用感情丰富、财被坏内心冷酷）；男人的感情一般与食伤有关。","sec":"四、财星","t":"diff"},{"q":"财星虚透在天干时一般不主钱财，若透在时上或构成「财合印」，各主什么？","opts":["无论透在哪里都只主暴富发大财","透时上主吝啬守财；财合印主不善言辞","透时上能花钱大方；财合印善沟通宜当讲师教师","透时上主晚年破产；财合印主弃文从武"],"ans":2,"exp":"财虚透主才华能力、会来事；透时上（门户）能花钱大方；财合印主会沟通、有调解表达能力，宜当讲师教师。","sec":"各十神虚透的含义","t":"xiang"},{"q":"正财与偏财在含义及职业倾向上的主要差异是什么？","opts":["正财偏财都只代表父亲，不代表职业","正财主浪漫风流轻财，偏财主节俭保守顾家","正财主股票博彩不义之财，偏财主工薪教师","正财主正当工薪与专一，偏财主风险投机与生意"],"ans":3,"exp":"正财受我支配、正当专一，宜工薪教师；偏财为非工薪、股票中介风险收益，多情交际，宜生意人、证券、咨询。","sec":"四、财星","t":"diff"},{"q":"在十神象法中，「印克坏有用的食伤」与「伤食见金受制」分别主什么象？","opts":["前者主牢狱之灾，后者有军人含义","前者主成为学者，后者主出家修行","前者主考取名牌大学，后者主从事律师","前者主发大财，后者主幼年缺乳难养"],"ans":0,"exp":"食伤代表自由，印克坏有用的食伤易失去自由，有牢狱之灾；伤食见金受制则有军人含义。","sec":"五、食伤","t":"xiang"},{"q":"食神在太旺或受克时的表现有何特点？","opts":["食神最怕太旺，一旺就犯罪且不守规矩","食神不怕旺，只怕受克；枭神夺食者爱抬杠","食神不怕受克，越克越聪明有口才","枭神夺食者最温和厚道、从不与人争辩"],"ans":1,"exp":"食神不怕旺，只怕受克（受克主幼年缺乳难养）；局中有枭神夺食者心性爱与人「抬杠」。","sec":"五、食伤","t":"rule"},{"q":"原局为食伤生财结构时，大运最喜见什么？若八字原局无财，什么十神可当财看？","opts":["只喜见劫财；八字无财时注定一生无财","喜见正印或偏印；八字无财时比劫当财看","喜见食伤或财星；八字无财时食伤当财看","喜见七杀或羊刃；八字无财时官杀当财看"],"ans":2,"exp":"原局为食伤生财结构，大运喜见食伤或财星；八字无财时，食伤（财之原神）可当财看，但虚透除外。","sec":"五、食伤","t":"rule"},{"q":"食伤「虚透」被制有功，与食伤「实」且被制化有功，在财运与才华上的主事有何不同？","opts":["虚透被制主自闭害羞，实而被制主牢狱之灾","虚透被制主发大财，实而被制主只爱讲话不赚钱","两者都只主口才好，与财运完全无关","虚透被制主才华口才，实而被制化有功主财运好"],"ans":3,"exp":"食伤虚透被制主才华、能说会道、有口才（不主钱财）；食伤实且被制化、有功，才主财运好。","sec":"各十神虚透的含义","t":"diff"},{"q":"比肩（禄）出现在年月柱与出现在日时柱，在六亲取象上有何不同？","opts":["年月的禄可当母亲看，日时的禄一般就是自己","无论在哪一柱，禄都只代表兄弟姐妹","年月的禄可当子女看，日时的禄可当祖父看","年月的禄代表自己，日时的禄代表外戚"],"ans":0,"exp":"禄是日主在地支的延伸，年月的禄还可当母亲看，日时的禄一般就是自己（身体、权力、寿元）。","sec":"六、比劫禄刃","t":"diff"},{"q":"关于盲派的「天干羊刃」，下列哪一项判定是正确的？","opts":["甲见庚、丙见壬，克日主之干才是天干羊刃","甲见乙、丙见丁为羊刃，乙见甲、丁见丙不是","阳干没有天干羊刃，只有地支才有羊刃","甲见乙、乙见甲互为羊刃，丙丁同理"],"ans":1,"exp":"阳干在天干见刃之原身也为天干羊刃（甲见乙、丙见丁、戊见己、庚见辛、壬见癸），反过来阴干见阳干不是。","sec":"羊刃","t":"calc"},{"q":"「金羊刃」在物象上有什么特殊含义？羊刃有制服与无制服的心性职业区分如何？","opts":["金羊刃为文书印章；制之主教师，无制主懒惰","金羊刃只主车祸，不能用来从事军警或医疗","金羊刃为刀为白虎；制之主军警外科，无制为匪","金羊刃为温和之象；无论有无制服都主发大财"],"ans":2,"exp":"金羊刃为刀、为白虎，较厉害。羊刃喜制服，制之用正主军人警察、外科大夫等；无制服则用偏成匪徒或非法谋利。","sec":"羊刃","t":"xiang"},{"q":"劫财本为凶神，在什么情况下「不忌」劫财？","opts":["只要劫财生出食伤，哪怕无功也不忌","只要日主身弱，见劫财帮身就绝对不忌","只要劫财落在年柱或时柱，就一律不忌","有功助我得财，或无用但虚透、被制则不忌"],"ans":3,"exp":"劫财为凶神：有功则助我得财，无功无用反致破财遭灾；若无用但虚透或被制，则不忌。","sec":"羊刃","t":"rule"},{"q":"戊辰、己丑两柱，天干戊己土坐下皆有辰丑土，按虚透规则该如何看待其强弱？","opts":["辰丑为湿土帮土无力，仍很虚弱","坐下比劫旺根，属于极强之实透","辰丑土生金泄土，完全等同于坐绝地","日主与比劫不论虚透，所以戊辰己丑必旺"],"ans":0,"exp":"戊辰、己丑柱，土虽坐根，但坐的是湿土，辰、丑土帮土无力，仍很虚弱。","sec":"定义（只论天干，只论一柱）","t":"calc"},{"q":"某八字月柱为「戊寅」（戊土为财星），按虚透只论本柱的规则，戊土论虚还是实？","opts":["若年支有戌土，月干戊土就不论虚透","寅虽为长生，仍以虚透论","只要地支有木生火，戊土就论实根","寅为戊土长生，故论实而不论虚"],"ans":1,"exp":"虚透只论本柱，戊土（或戌土）坐寅木长生亦以虚透论。","sec":"定义（只论天干，只论一柱）","t":"calc"},{"q":"从命局用神（功神）五行来辨别学科倾向时，理科与文科通常分别主什么五行？","opts":["木火主理科，金水主文科","土金主文科，水木主理科","金水主理科，木火主文科","火土主理科，金木主文科"],"ans":2,"exp":"在学科倾向取象中，金水主理科，木火主文科。","sec":"命例","t":"xiang"},{"q":"若原局喜某十神虚透（如忌印而印虚透），行至该十神「实」的大运，但被原局所制化，吉凶如何？","opts":["变成实而为用，大运过后立即破产","只要虚而为用见大运实，必然应大凶","虽然原局制化，仍主降职或退学","被原局制化则不怕实，仍以吉论"],"ans":3,"exp":"虚而为用怕大运见实，但若局中喜虚而大运虽实却被原局所制化，则不怕实，仍以吉论。","sec":"虚透用于应期","t":"calc"}]},{"n":4,"level":"初级","title":"入手方法与命局层次","qs":[{"q":"从日柱入手看做功，日干的三步顺序是什么？","opts":["先看有无合，再看有无生，最后看有无势","先看有无生，再看有无合，最后看有无势","先看有无势，再看有无合，最后看有无生","先看有无合，再看有无刑冲，最后看有无势"],"ans":0,"exp":"日干先看合（只合正官或正财），无合看生（食伤贴近日干），无生无合再看势。","sec":"日柱入手的顺序","t":"step"},{"q":"日干无合、无生，又不在势中，该怎么入手？","opts":["弃日柱，专看月柱","弃日干，专看日支","仍看日干，按日干旺衰定","改看时柱，时柱为子女宫"],"ans":1,"exp":"支是干的躯体，地支所做的功就是天干的，日干无功就看日支。","sec":"日柱入手的顺序","t":"rule"},{"q":"日柱干支都做功，但日干意向与日支意向不一致，以谁为主？","opts":["以日支为主，地支能量大","弃日干，以日支意向为主","弃地支之功，以日干意向为主","日柱各占一半，两边并看"],"ans":2,"exp":"日柱干支意向一致才以日柱论；不一致则弃地支之功，以日干意向为主。","sec":"谁为主","t":"calc"},{"q":"日干有合，但地支做了大功，该以谁的功为主？","opts":["以日干之合为主，合官即是官命","以月令之功为主，日柱都不算","合与地支功各占一半","以日支的功为主，日干之合只是表象"],"ans":3,"exp":"有的八字日干有合或生，但地支做了大功，这时以日支的功为主，干上的合生只是表象。","sec":"日柱入手的顺序","t":"calc"},{"q":"盲派判断富贵八字的两个条件是什么？","opts":["有势，并且做功","五行平衡，并且无冲克","有势，并且日主在势中","日主旺相，并且有官有印"],"ans":0,"exp":"口诀是一是有势、二要做功：只有势不做功不行，做了功没有势功又太小。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"以下哪组是盲派成一党的组合？","opts":["木火、金水、水木、火与湿土、金与燥土、水与燥土","木火、金水、水木、火与燥土、金与湿土、水与湿土","木火、金水、水木、火与燥土、金与燥土、水与湿土","木火、金水、木土、火与湿土、金与燥土、水与湿土"],"ans":1,"exp":"火配燥土，金、水配湿土；燥土与金、水，湿土与火不成党，别把燥湿弄反。","sec":"势的种类与成党规则","t":"diff"},{"q":"木火成势，所制的是什么？","opts":["水，水中含金也同制","土，土中遁藏也同制","金，金中含水也同制","火与燥土，同属一党"],"ans":2,"exp":"木火一党制金，金中含水同制；金水一党才制火与燥土。","sec":"势能制什么","t":"diff"},{"q":"下面哪两个字相见，不能看成一党？","opts":["午戌半合","巳午相邻","寅卯同木","未戌相刑"],"ans":3,"exp":"未戌刑、亥申穿都不能看成一党；卯午破单独存在也不成一家。","sec":"势的种类与成党规则","t":"rule"},{"q":"关于三会局，盲派有什么特别规定？","opts":["申酉戌、寅卯辰不论三会，巳午未、亥子丑才论","四方三会全都成局，只看是否透干","申酉戌、巳午未不论三会，寅卯辰、亥子丑才论","三会局都不成立，只论三合"],"ans":0,"exp":"戌是燥土不生金，辰是湿土反生金，所以申酉戌、寅卯辰不论三会；巳午未、亥子丑可结党成势。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"局中被夹冲、夹克的字，按盲派口径能不能制死？","opts":["能制死，但制后寿命受损","不能，任何夹制都制不死对方","夹冲能制死，夹合不能","能，夹制比单制更有力"],"ans":1,"exp":"夹冲、夹克、夹合、夹穿等任何夹制，都不能将对方制死。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"日支坐官杀库、财库，局中没有刑冲，库开不开？","opts":["自然开，坐下之库随日主可用","大运合库才开，刑冲反而封库","不开，墓库只有刑冲才能制","半开，只作辅助而无大功"],"ans":2,"exp":"口诀：坐下财官临库喜刑冲，不刑冲则不开；戌库要辰冲才能制。","sec":"三、命局层次：富贵、普通、差","t":"rule"},{"q":"制不干净的官杀，按盲派口径当什么看？","opts":["当食伤看","当比劫看","当印看","当财看"],"ans":3,"exp":"官杀被制不净、木党无法制净官时，官当财看；比劫禄做功的是劳碌的体力人。","sec":"（二）普通八字","t":"rule"}],"fine":[{"q":"当八字组合形成了强大的气势时，入手看做功可以如何处理？","opts":["可以抛开主位不看，专看这个气势做功","必须先看日干合生，气势只能放在最后看","若主位不在气势中，该八字直接论差命","只看月令提纲，气势和主位都不用管"],"ans":0,"exp":"八字形成强大气势时，可以抛开主位不看，专看气势做功；主位做功则从主位入手。","sec":"先功后象","t":"step"},{"q":"关于「功」与「象」的综合判断总原则，下列哪项表述最准确？","opts":["有象先看象，无象才看功，功象不并看","有功先看功，无功看象，功象都有则都看","只要有象就必是大富贵，做功可有可无","只看做功即可，有功无象也算上等富贵"],"ans":1,"exp":"总原则：有功先看功，无功看象，功象都有则都看；功象都没有，这个八字就很差。","sec":"先功后象","t":"step"},{"q":"从日干入手看做功时，日干所「合」只有哪两种十神？看「生」主要看哪两柱贴近日干？","opts":["只合正印或偏印；看年干、时干有无财星","只合七杀或偏财；看年干、月干有无印星","只合正官或正财；看月干、时干有无食伤","可合任何十神；只看日支有无食伤暗合"],"ans":2,"exp":"日干所合只有正官或正财两种；日干无合看有没有生，即月干、时干有无食神伤官贴近日干。","sec":"日柱入手的顺序","t":"rule"},{"q":"为什么盲派认为「日干无功要看坐支（日支）」？","opts":["因为日干代表父母，日支才代表命主本人","因为天干能量远高于地支，日支只是辅助","因为所有八字的天干都不做功，只有地支做功","支是干的躯体，干是支的头脑，坐支功即日主功"],"ans":3,"exp":"盲派看一组干支代表一家：支是干的躯体，干是支的头脑，地支所做的功就是天干的，坐支之功即日主之功。","sec":"日柱入手的顺序","t":"rule"},{"q":"若日柱干支都不做功，则看其他柱的禄、比劫、印。其中「地支禄多成势做功」主什么？","opts":["命局不会太差，但有身心忙碌之意","只主有高学历，与财运工作无关","必定大富大贵，坐享其成毫不劳碌","属于最差八字，一生孤贫无依"],"ans":0,"exp":"单以禄做功层次较低，一般为劳动者；若地支禄多成势做功，命局不会太差，但有身心忙碌之意。","sec":"日柱入手的顺序","t":"calc"},{"q":"盲派对八字「平衡」与「气势」的看法与传统命理有何根本区别？","opts":["五行越平衡越富贵，偏于一方必为贫贱","凡大富贵八字一定不平衡，有偏于一方的势","大富贵八字必须四柱五行数量完全相等","只要有势就一定富贵，哪怕不做功也算"],"ans":1,"exp":"盲派不以平衡论好坏，相反，凡大富贵的八字一定不平衡，有偏于一方的「势」，再通过势去做功。","sec":"二、势（党）","t":"diff"},{"q":"在盲派「势（党）」的规则中，判定几个字能否算「一党」的核心原则是什么？","opts":["只要在地支相邻，哪怕五行相克也算一党","必须构成三合局或三会局才能算一党","两者或三者结合，有共同对付的被制之神","必须天干地支全属同一个五行才算一党"],"ans":2,"exp":"成党原则：两者或三者结合，有需要共同对付的敌人（被制之神），就可算一党；主要做功为功神，帮扶为辅神。","sec":"势的种类与成党规则","t":"rule"},{"q":"除常见的六种两党组合外，个别情况下还有哪种特殊的两党组合？","opts":["火与湿土制燥土","金与燥土制水木","水与燥土制湿土","木与燥土制湿土"],"ans":3,"exp":"两党成势除木火、金水、水木、火燥土、金湿土、水湿土外，个别还有木与燥土制湿土（如木与戌土制辰土）。","sec":"势的种类与成党规则","t":"rule"},{"q":"地支中「卯午破」在局中单独存在与形成局时，能否算成一家（一党）？","opts":["局中只有这一对不成一家，成局也算一家但不好","只有卯午单独存在才算一家，成局反而不算","只要见到卯午破，全局直接散架绝不成党","无论是否成局，卯午木火永远算成一家"],"ans":0,"exp":"未戌刑、亥申穿不能算一党；卯午破若局中只有这一对则不成一家，形成局的话也算一家，但总是不太好。","sec":"势的种类与成党规则","t":"diff"},{"q":"在单势做功中，「燥土势」与「湿土势」各自能制坏什么？","opts":["燥土势只坏水，湿土势只坏木","燥土势坏水金湿土，湿土势坏火与燥土","燥土势坏木与火，湿土势坏金与水","燥土势与湿土势都只能制水不能坏火"],"ans":1,"exp":"单势中，燥土势坏水，也可反坏金，还可坏湿土；湿土势坏火，也可坏燥土。","sec":"势能制什么","t":"diff"},{"q":"在两党成势中，「火与燥土」一党与「金水」一党各自主要制什么（含遁藏）？","opts":["火燥土制金水，金水制木火湿土","火燥土只制木，金水只制土","火燥土制水金湿土，金水制火与燥土","火燥土制湿土，金水制水木"],"ans":2,"exp":"火与燥土一党制水（含木）、金（含水）、湿土（含遁藏）；金水一党制火（含土）与燥土（含遁藏）。","sec":"势能制什么","t":"diff"},{"q":"在富贵、普通、差三类命局层次中，占比最大（约六至七成）且层次最难区分的是哪一类？","opts":["富贵八字","贼捕八字","差八字","普通八字"],"ans":3,"exp":"富贵与差八字占比小、结构简单易分析；普通八字占绝大多数（约六至七成），层次最难区分。","sec":"三、命局层次：富贵、普通、差","t":"rule"},{"q":"当命局结构呈现「财制劫财」（或官杀与财库制劫财）并做大功时，如何通过换象断财富？","opts":["换象，把被制的劫财当财看","把财星当印星看，主有高学历无钱财","财制劫财属于比劫夺财，必主破产","把劫财当官杀看，主当大官而非发财"],"ans":0,"exp":"财制劫财（或官杀和财库制劫财）时，要换象把被制的劫财当财看，功大且与主位相关则主大富。","sec":"（一）富贵八字：两个条件","t":"calc"},{"q":"命局中有「辰」土，若局中又见到亥、子水，在盲派取象与做功中如何看待亥、子水？","opts":["亥、子水会把辰库冲破，使辰成为废神","亥、子都是辰库中引出之水，制亥等于制辰","亥、子与辰毫无关系，必须分别单独制去","辰库只能引出亥水，不能引出子水"],"ans":1,"exp":"命局中有辰，如又见亥、子水，则此亥、子都是辰库中引出之水，制去亥或子等于制了辰库。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"在盲派命理中，「墓」与「库」的核心区别是什么？","opts":["阴干入库，阳干入墓，冲开反而变凶","墓代表财库，库代表官库，两者字义相同","墓是死的，库是能收藏的，入墓须冲开才出","墓能收藏万物，库是死地不能再用"],"ans":2,"exp":"墓是死的，库是能收藏的；财等十神入了墓便无用，必须等大运刑冲开墓，财才会出来。","sec":"（一）富贵八字：两个条件","t":"diff"},{"q":"对于「虚透的天干」，在原局中怎样才能将其制死？","opts":["虚透极弱，只要有任意一个字相克即制死","虚透天干根本不需要制，天然就是死的","只要地支相冲即可把虚透天干制死","极难制死，除非克而合之，仅合则制不死"],"ans":3,"exp":"虚透的天干很难制死，除非克而合之，仅合则制不死。","sec":"（一）富贵八字：两个条件","t":"rule"},{"q":"原局地支中被制的神，在大运中最忌讳出现什么情况？","opts":["最忌大运透干无制或在地支受生助","最忌大运再次出现去制它的字","最忌大运遇到同党功神一起制它","最忌大运把它彻底合走或冲掉"],"ans":0,"exp":"原局地支被制的神，不喜大运透干无制或受生助（助则为凶）；如原局制亥水官杀，大运甲木透干无制便反制日主成凶。","sec":"（一）富贵八字：两个条件","t":"calc"},{"q":"普通八字虽然「有功」，但层次不高的两种典型原因是什么？","opts":["全盘没有任何做功的字，废神占满四柱","不成势而主位有小功，或有气势却浪费仅做小功","日主太弱不受生，无法担起庞大的气势","同时具备两种强大气势且把财官全部制净"],"ans":1,"exp":"普通八字两种情况：一是不能形成气势但主位有小功；二是有气势但气势浪费了，只做了很小的功。","sec":"（二）普通八字","t":"rule"},{"q":"对于「活木」（如乙木地支见亥、寅等根），其根在命局中的核心禁忌是什么？","opts":["活木最喜地支火旺来把湿木根烤干","活木之根必须用金木相战来彻底制净","活木之根不能坏，坏得越严重越凶","只要大局有势，活木之根被坏也主富贵"],"ans":2,"exp":"活木要用其根做功，根是日主所喜和意向，即使局中有势也不能坏，坏得越严重越凶。","sec":"（二）普通八字","t":"rule"},{"q":"当命局意向是要制某一地支财星时，天干最忌讳出现什么配置？","opts":["最忌比劫成党去一起制这个财星","最忌该财星在原局中被彻底制净","最忌该财星在地支被别的字合走","最忌该财星的原身透干且无制"],"ans":3,"exp":"局中要制财（如制月令午火财），不喜其原身（如己土）透干无制，透干无制则坏了原局做功意向。","sec":"（二）普通八字","t":"calc"},{"q":"「门户（时柱）之财生到主位」与「年月的禄或劫财做功」，在职业上分别多主什么象？","opts":["前者多开门面做生意，后者多辛苦劳碌之人","前者多靠学术研究谋生，后者多继承祖产享福","前者多当省部级大官，后者多做企业老板","前者主一生破财奔波，后者主清闲有福"],"ans":0,"exp":"门户之财生到主位大都是开门面做生意的人；年月的禄或劫财做功，大多是辛苦劳碌的体力劳动者。","sec":"（二）普通八字","t":"xiang"},{"q":"从废神与做功的角度看，「差八字」与「好八字」最显著的对比特征是什么？","opts":["差八字没有地支，好八字全是天干","越差的八字废神越多，越好的八字废神越少","越差的八字功神越多，越好的八字闲神越多","差八字全盘皆冲，好八字全盘皆合"],"ans":1,"exp":"差八字找不到功神、废神太多、做废功或要用之神被坏；越差的八字废神越多，越好的八字废神越少。","sec":"（三）差八字","t":"diff"},{"q":"地支「戌未相见」与「辰戌远隔相冲」，在盲派作用关系中各怎么论？","opts":["戌未相见论一党相助，辰戌远隔照样开库","戌未相见与辰戌远隔相冲都能彻底制死对方","戌未相见永远论刑，辰戌远隔之冲只是动非开","戌未相见论暗合，辰戌远隔冲比近冲更有力"],"ans":2,"exp":"戌未相见永远论刑（互伤，不能制他字）；辰戌远隔（如年时）的冲只是动而不是开库，力量小。","sec":"（三）差八字","t":"diff"},{"q":"在盲派命局分析中，地支相破里哪一组相破的破坏作用相当大（如印禄互破）？","opts":["戌未相破","辰丑相破","寅亥相破","子卯相破"],"ans":3,"exp":"命局中子卯相破的破坏作用相当大，如印禄互破会破坏全局，破本身不是做功方式，只主表象不好或坏局。","sec":"（三）差八字","t":"rule"}]},{"n":5,"level":"初级","title":"十天干与五行干支特性","qs":[{"q":"按盲派，甲乙木算「活木」须同时满足什么条件？","opts":["得月令当令，不论水","有近根，且得水生","天干透水，不论根","有近根，且不见金"],"ans":1,"exp":"活木＝有根＋得水生，缺一不可；根要在月令、坐支、时支，年支太远不当根。","sec":"一、甲乙木","t":"rule"},{"q":"甲辰日柱，局中遇酉。酉对这棵甲木的要害在哪？","opts":["酉金直接克断天干甲木","酉冲卯木，使甲失去月令根","酉合辰，铲断辰中乙根","酉泄辰土之气，使水无源"],"ans":2,"exp":"甲辰辰中有乙有癸本是活木，最怕埋根之铁；酉合辰即铲断辰中之乙，伤根。","sec":"一、甲乙木","t":"calc"},{"q":"卯月生的木，局中分别来酉与来申，结果有何不同？","opts":["酉申都被卯木克住，皆无妨","来酉与卯合可容；来申冲坏卯","酉申都冲坏卯根，皆凶","来酉冲坏卯；来申与卯合，金可容"],"ans":3,"exp":"春木不敢受冲克，有卯不敢见酉；申与卯合，合制了金，金可容。","sec":"一、甲乙木","t":"calc"},{"q":"乙木生在秋天（酉月），喜忌如何？","opts":["喜火怕水，怕有根喜无根","喜水润怕火，喜有根","喜火也喜有根，水无妨","喜水润，有根无根皆可"],"ans":0,"exp":"口诀「乙生酉月用火攻」：乙秋已是成熟庄稼，见水发霉，见火无水能成贵格，反怕有根。","sec":"一、甲乙木","t":"rule"},{"q":"丙火与丁火在旺衰上的要求，哪项对？","opts":["丙丁都怕衰，喜旺","丙怕过旺也怕衰；丁旺而不烈、衰而不竭","丙喜旺不怕衰；丁不能过旺","丙不看旺衰；丁怕过旺"],"ans":1,"exp":"丙火不能过旺，也怕衰、怕湿土晦；丁如烛灯，日主为丁不用看旺衰。","sec":"二、丙丁火","t":"diff"},{"q":"戊土日主遇官杀，哪种说法对？","opts":["寅卯官杀都怕","怕寅木七杀，不怕卯木正官","不怕寅木七杀，怕卯木正官","寅卯官杀都不怕"],"ans":2,"exp":"戊坐寅是长生之地，永远喜七杀、怕正官；官杀旺时仍要有制有化才有用。","sec":"三、戊己土","t":"rule"},{"q":"庚金弱，没有申酉之根时，该怎样取运才吉？","opts":["逆其性，见旺金帮扶","顺其性，见旺水","顺其性，见旺土生金","逆其性，见旺木火"],"ans":3,"exp":"庚见申酉之根要顺其性（旺水且有用）；弱则逆其性，见旺木火吉；不可亦顺亦逆，否则贱不可言。","sec":"四、庚辛金","t":"rule"},{"q":"庚金坐申禄，被局中其他字制得太过，结果是？","opts":["过制为凶，易出病灾伤灾","只主破财，不涉身体","制得越净越吉，主官贵","无碍，金本不看旺衰"],"ans":0,"exp":"庚见禄不能受制太过，禄到即寿到，过制易出病灾伤灾。","sec":"四、庚辛金","t":"rule"},{"q":"通源的壬癸水「流绝」，主什么？","opts":["主水不能做功，一生无为","只主寿绝，与做功得财官无关","主婚姻不成，夫妻缘薄","主破财，财官不聚"],"ans":1,"exp":"看有源之水是否流绝只涉及寿命；流到库归库不算流绝，无根无源之水也不论。","sec":"五、壬癸水","t":"diff"},{"q":"下面哪一组土，不克水反而生金？","opts":["戌、未","辰、戌","辰、丑","丑、未"],"ans":2,"exp":"辰丑为湿土，原则上不克水、生金；戌未为燥土，克水力大（戌克亥、未克子），不生金反脆金。","sec":"六、辰戌丑未","t":"diff"},{"q":"四墓库入墓的对应，哪一项是对的？","opts":["丑墓酉不墓申","辰墓子不墓亥","戌墓午不墓巳","未墓寅不墓卯"],"ans":3,"exp":"子午卯酉因有半合局关系不以墓论：辰墓亥不墓子，未墓寅不墓卯，丑墓申不墓酉，戌墓巳不墓午。","sec":"六、辰戌丑未","t":"diff"},{"q":"局中土金旺、又见丑酉，其中的巳火该怎么论？","opts":["归顺于金，合金局助金","化为土，晦火生金","随月令定，不随局变","仍为火性，克金制金"],"ans":0,"exp":"巳是唯一性质随环境改变的支：火旺有木生则为火克金；火弱土金旺、特别见丑酉则归顺于金。","sec":"六、辰戌丑未","t":"calc"}],"fine":[{"q":"分析八字中的甲乙木时，应该先看什么，再看什么？","opts":["先看有无官杀克身，再看财星多少","先看死活，再看生在哪个季节","先看生在哪个季节，再看是否透干","先看日主旺衰，再看用神喜忌"],"ans":1,"exp":"木分死活，分析甲乙木先看死活，再看生在哪个季节；季节的喜忌居次，成活与否居首。","sec":"象与成活条件","t":"step"},{"q":"为什么甲辰、乙亥这类日柱，即便局中不见其他水也能算活木？年支的木根算不算根？","opts":["甲辰不算活木，只有乙亥才自带水算活木","因为甲辰乙亥天干通根月令；年支也算根","辰亥根中自带水；年支太远不当根论","甲乙在坐支一律算活木；年支之根最有力"],"ans":2,"exp":"辰中有乙有癸、亥中有甲有壬，根中自带水，本身就是活木；根要近（月令、坐支、时支），年支太远不当根论。","sec":"象与成活条件","t":"calc"},{"q":"关于木之根能否「阴阳互用」（甲见卯、乙见寅），活木与死木有何区别？","opts":["死木的根可阴阳互用；活木则不能互用","活木与死木的根都绝对不能阴阳互用","只有甲木见卯可互用，乙木见寅绝不互用","活木的根可阴阳互用；死木不可，是另外的木"],"ans":3,"exp":"活木的根可阴阳互用（甲见卯、乙见寅都算自己的根）；死木没有这个特点，见之是另外的木，可以被坏。","sec":"象与成活条件","t":"diff"},{"q":"活木见火与死木见火，在吉凶与象法上的核心区别是什么？","opts":["活木见火为秀气发越，死木怕旺火焚尽短寿","活木怕火焚身短寿，死木最喜旺火暖局","活木见火为燃烧，死木见火为木之花朵","活木死木都最忌见火，见火必主神经质"],"ans":0,"exp":"活木见火是木之花朵、秀气发越，喜；死木见火是燃烧，怕旺火，焚尽则短寿、神经质。","sec":"活木与死木的五点区别","t":"diff"},{"q":"死木一般怕水，但遇大运见「亥」与见「子」时，吉凶判断有何不同？","opts":["忌见子水腐烂；见亥水则主升官发财","忌见亥，走亥运不吉；见子看原局喜忌","无论亥运还是子运，死木见之都必大吉","最喜见亥水滋润；最忌见子水冲克"],"ans":1,"exp":"死木最忌水生，忌见亥，走亥运一般不吉；见子则要看原局对子水的喜忌，与亥不同。","sec":"活木与死木的五点区别","t":"diff"},{"q":"活木与死木遇到「空亡」时，各自表现为何？","opts":["活木死木遇空亡都必定主早年丧父丧母","活木则立即枯死短寿，死木反能成栋梁材","活木则木之心空长不健壮，死木则难以成材","活木完全不受空亡影响，死木才怕空亡"],"ans":2,"exp":"活木遇空亡，木之心空，长不健壮（有水仍为活木但不健）；死木遇空亡，难以成材。","sec":"活木与死木的五点区别","t":"diff"},{"q":"同为金生水日柱，「癸酉日」的酉可以制去，而「壬申日」的申为何不能随便去？","opts":["因为酉是正印可以去，申是偏印不能去","因为酉属阴金太弱，申属阳金永远制不死","因为阴干不怕去印，阳干最怕去印","酉不太生癸可以去；申是壬的带根之印不能去"],"ans":3,"exp":"带根者不可随便去。癸酉日酉不太生癸，可以去；若壬申日，申是带根的，去了申就没命了。","sec":"怎样用：死木弃日主、看坐支","t":"calc"},{"q":"木之禄（卯、寅）落在年月与落在日时，在六亲与身体取象上有何区别？","opts":["年月禄可当母亲看，日时禄才是自己身体","无论落在哪一柱，禄被冲都主自己伤寿","年月禄主子女，日时禄主祖父祖母","年月禄主自己身体，日时禄才主母亲"],"ans":0,"exp":"禄在年月可以当母亲看，不主自己身体（如年支卯禄被冲主母凶）；日时的禄才是自己身体。","sec":"怎样用：死木弃日主、看坐支","t":"diff"},{"q":"甲乙木生在春天，关于初春（寅月）甲木与春木无水时的喜忌，下列哪项正确？","opts":["无论有水无水，春木见火都必成参天大树","初春甲嫩最畏金克；春木无水反不宜见火","辰月属春最怕土，最喜金来斩木成材","初春甲木最喜金劈；春木无水最喜旺火泄"],"ans":1,"exp":"初春（寅月）木嫩，最畏金克；春木无水则枯，反不宜见火（特别是卯月）；辰月属春怕金斩，喜土为财。","sec":"四季喜忌","t":"rule"},{"q":"木生于夏天，「有水」与「无水」在用法上有何截然相反的要求？","opts":["无论有水无水，夏木都必须去水用火","有水不可见火，无水则可用子水不可用亥水","有水一定要用水；无水则不能见水反而要去水","有水要去水；无水一定要引水来润局"],"ans":2,"exp":"夏生之木看有无水：有水即活木，一定要用水；没有水则不能见水，反而要去水（但亥带木根仍要用，子可去）。","sec":"四季喜忌","t":"diff"},{"q":"甲乙木生冬为寒木，喜用暖局调候，哪些地支属于能生发的「暖地」？","opts":["只有巳、午、未三地才算暖地","只有丙、丁、午、戌四字才算暖地","从寅到午是暖地，申酉属于寒地","从辰到申都是暖地"],"ans":3,"exp":"冬生寒木喜暖局调候，从辰到申都是暖地（如辰是湿土却是暖运）；大运若为局忌又是调候地，以做功为主、调候次之。","sec":"四季喜忌","t":"rule"},{"q":"乙木生于秋天（酉月）要成贵格，最喜与最怕什么配置？","opts":["喜见火无水，怕有根、喜无根","喜见水无火，喜有强根、怕无根","喜见亥子润局，最怕见丙丁透干","喜金水相生，最怕火来克制秋金"],"ans":0,"exp":"乙秋已是成熟庄稼，见水发霉，故见火无水能成贵格，反怕有根、喜无根（甲木秋生凋零不太贵）。","sec":"四季喜忌","t":"calc"},{"q":"丙火与丁火的共同特性中，它们对四季的敏感度如何？共同最怕什么？","opts":["夏生最怕木生，冬生最喜湿土护火","对四季不敏感，最怕湿土晦火也怕燥土晦火","极度讲究四季，最喜辰丑湿土泄秀","对四季敏感，最喜戌未燥土帮身成势"],"ans":1,"exp":"丙丁对四季都不十分敏感，不讲季节；最怕湿土晦火，也怕燥土晦火。遇土则喜木，无木则贫贱。","sec":"象与共同点","t":"rule"},{"q":"丙火在媒体类象上与丁火有何不同？无根又无原神（印）的丙火称为什么，主什么？","opts":["无根无原神的丙火仍能燃烧，主掌实权","丙主文字传媒、虚火主大富；丁主影视媒体","丙主影视媒体、虚火主名气；丁主文字传媒","丙丁火都只主影视媒体，无根则主贫贱无名"],"ans":2,"exp":"丙主影视媒体、文学漂亮，无根又无原神的丙是虚火，烧不起来，仅主名气名望；丁主文字传媒、神秘文化。","sec":"丙火","t":"diff"},{"q":"丙火日主或戊土日主在「时上见禄」（如巳禄）时，对「冲」与「穿」的禁忌有何不同？","opts":["时上的禄冲和穿都大吉，越冲穿越贵","时上的禄冲和穿都必主立刻破产","时上的禄不怕穿，但最怕冲","时上的禄不怕冲，但怕穿"],"ans":3,"exp":"禄在日时就是自己，穿禄主凶（如寅巳穿禄）；时上的禄不怕冲，但怕穿。","sec":"丙火","t":"rule"},{"q":"用十神看文化学历时，关于「印」和「财」的判断规则，下列哪项正确？","opts":["印去了毛病或有用生了主文化；财重有制有文化","印被制去主绝对没文化，财星透干主博士学历","财虚为吉就必有高文凭，财重有制反而无文化","只要局中有印或有财，无论是否做功都有文凭"],"ans":0,"exp":"印是毛病去了或印有用生了，都主文化；财虚为吉主才能，不一定有文化，财重有制才主有文化。","sec":"文化与学历怎么看（丁火案例的延伸）","t":"diff"},{"q":"关于土的长生位置，天干之土（戊己）与地支之土（辰戌丑未）分别长生在何处？","opts":["天干地支之土一律长生在申","天干之土长生在寅，地支之土长生在申","天干之土长生在申，地支之土长生在寅","天干地支之土一律长生在寅"],"ans":1,"exp":"口诀：天干之土长生在寅（跟火走），地支之土（辰戌丑未）长生在申（跟水走）。戊己土不需要分有无根。","sec":"象与长生、墓","t":"rule"},{"q":"天干戊己土见戌，以及地支辰戌丑未中见辰，各自在什么条件下才论「入墓」？","opts":["只有戊辰、己丑才入戌墓；戌见辰为双墓","只要戊己见戌就入墓；戌辰相见也论入墓","戊己坐火后入戌墓；地支只有丑未入辰墓","戊己永远不入戌墓；地支寅卯见辰论入墓"],"ans":2,"exp":"单纯戊己见戌不为墓，只有坐火后（戊午、己巳）火土一起入戌墓；地支土只有丑、未见辰才入墓，戌与辰冲不入。","sec":"象与长生、墓","t":"calc"},{"q":"关于戊土在四季的贵贱与喜忌，下列哪项表述最准确？","opts":["生戌月最算薄土，见火来生越旺越吉","春秋土最顽固，冬生最忌丙火太阳普照","夏生火旺最容易大贵，冬生见丙火反而变贱","春秋为薄土易贵最爱丙火；夏太燥不会贵"],"ans":3,"exp":"戊生春秋为薄土（不含戌月），易贵，最爱丙火普照；冬生更喜丙火；夏生太燥不会贵；见戌通根顽固怕再见火生。","sec":"戊土","t":"rule"},{"q":"己土的特性最喜什么配置？","opts":["喜丁，喜旺，喜禄（午）","只喜辰丑湿土，最忌见丁火与午禄","极怕旺，只喜寅卯七杀正官克身","喜癸，喜衰，最怕见火来生"],"ans":0,"exp":"己土喜旺也不怕衰，喜丙丁火来生，喜丁、午禄；对四季不敏感，旺时喜金水。特点即喜丁、喜旺、喜禄。","sec":"己土","t":"rule"},{"q":"庚辰日主因辰为庚之「坐家」，往往表现出什么性格特点？庚金最忌哪种水局？","opts":["庚辰日主霸道果断；忌火旺克金主牢狱","庚辰日主懒惰散慢；忌旺水多金沉主牢狱","庚辰日主勤奋好学；最喜水多金沉主大贵","庚辰日主精明善辩；最喜申子辰三合发财"],"ans":1,"exp":"辰生庚为庚之「坐家」，庚辰日主懒惰、散慢、不积极；庚金不喜旺水，水多金沉主牢狱之灾。","sec":"庚金","t":"xiang"},{"q":"辛金对水（壬癸、亥子）的喜忌如何？辛配癸通常主什么才华与职业倾向？","opts":["喜壬子、不喜癸亥；辛配癸主武职军警","壬癸亥子一概皆喜，越旺越富贵","喜癸亥、不喜壬子；辛配癸主聪明文采多从文","辛金最忌见水，见癸水则埋没无光"],"ans":2,"exp":"辛金一般喜癸、亥水，不喜壬、子水；辛配癸为金水伤官，主聪明、有才华文采，职业多属从文如作家写书。","sec":"辛金","t":"diff"},{"q":"命局中出现两个相同的字（例如两个巳火官星），在取象时何时代表同一个人、何时代表两个人？","opts":["为喜代表两个人，为忌代表同一个人","在年月代表同一个人，在日时代表两个人","无论喜忌，两个相同的字永远只代表同一个人","为喜代表同一个人，为忌代表两个人"],"ans":3,"exp":"命局中相同的两个字，为喜则代表同一个人（如伏吟同象），为忌则表示两个人，须区别对待。","sec":"辛金","t":"diff"},{"q":"壬水与癸水在木火喜忌上各有特点：壬水对寅卯、甲乙的喜忌如何？癸水弱与旺各喜什么？","opts":["壬爱寅甲不喜卯乙；癸弱从木火、旺喜制火","壬癸水都不喜木火，只喜申酉亥子成党","壬水喜寅也喜卯；癸水无论旺弱都只喜庚辛金","壬爱卯乙不喜寅甲；癸弱喜金水、旺喜从木火"],"ans":0,"exp":"壬最爱寅木（衰可托、旺可泄），不喜卯木，喜甲未必喜乙；癸阴中之阴，弱则喜生木见火，旺则喜制火。","sec":"壬水","t":"diff"},{"q":"盲派中「四墓库」什么时候才论入墓？如辛酉日柱见丑，按入墓还是拱局论？","opts":["永远只论拱局不论入墓；丑不墓金","多而墓（两个以上叫多）；辛酉见丑论入墓","只要见一个就论入墓；辛酉见丑论半合拱局","只有寅申巳亥永远不入墓，子午卯酉才入墓"],"ans":1,"exp":"什么时候入墓：多而墓，两个以上叫多。如辛酉（两个金）见丑就不拱局了，叫入墓；入墓之神待冲才出。","sec":"四墓库的入墓","t":"rule"},{"q":"关于水的动静与四正神相生，下列哪一项表述符合盲派规则？","opts":["子水生卯木最有力，亥水生寅木反论刑破","子水静而生木力强，亥水动而不生木","子壬动水生木弱，癸亥静水能生；四正神生力弱","子午卯酉四正神相互生力极大，胜过长生之生"],"ans":2,"exp":"子、壬为流动之水生木力弱，癸、亥为静水能生木；子午卯酉四正神相互之间生力不大，生得不情愿。","sec":"水的特性：动与静","t":"diff"}]},{"n":6,"level":"初级","title":"干支配置（上）：生克、自合与带象","qs":[{"q":"按盲派，同一柱内地支要克天干，必须满足什么条件？","opts":["地支必须得月令当旺","地支必须得三合局相助","必先与天干合住，合而克之","地支必须有原神透出相生"],"ans":2,"exp":"干为君、支为臣，天干克地支，地支不能克天干；只有先合住天干（天地自合）才能合制，如丁亥。","sec":"一、干支生克：君臣与互生","t":"rule"},{"q":"柱中有丁亥，又见巳冲亥，丁亥的自合还成立吗？","opts":["成立，冲只是动它不影响合","不成立，要先有申合亥才行","成立，反而合得更有力","不成立，地支被冲则不能自合"],"ans":3,"exp":"自合柱的地支若被它支冲，则不能自合：丁与亥中壬不能合。","sec":"二、自合：合而制之","t":"calc"},{"q":"盲派说自合柱的「合」，是什么性质？","opts":["合而制之，是做功，不是合绊","合而化气，转成另一五行","合而绊住，双方都不起作用","合而生之，是相生不是制"],"ans":0,"exp":"自合是合而制之，属做功方式，没有合绊的意思；强者制弱者，强弱看气势。","sec":"二、自合：合而制之","t":"rule"},{"q":"丙戌、壬戌的自合，戌要逢什么刑才算自合？逢另一种刑为何不算？","opts":["逢丑刑开库才合；逢未刑是坏戌","逢未刑开库才合；逢丑刑是坏戌","逢未刑才合；逢丑刑同样可合","逢丑刑才合；逢未刑是坏戌"],"ans":1,"exp":"戌逢未刑才开库，自合成立；逢丑刑（金水强时）是坏戌中所藏之物，不算自合。","sec":"二、自合：合而制之","t":"diff"},{"q":"自合九柱中，地支能合克天干的是哪四柱？","opts":["己亥、癸巳、壬戌、丙戌","壬午、甲午、戊子、丙戌","丁亥、己亥、辛巳、癸巳","丁亥、辛巳、壬午、戊子"],"ans":2,"exp":"前四柱丁亥、己亥、辛巳、癸巳地支可合克天干；壬午、甲午、戊子一般天干制地支；丙戌、壬戌须未刑开库。","sec":"二、自合：合而制之","t":"rule"},{"q":"盲派所说「统」，指的是什么情形？","opts":["天干与地支自合，合住不动","天干克地支，天干制住地支","地支生天干，一柱表一个象","天干生地支，一柱表一个象"],"ans":3,"exp":"天干生地支时，这一柱表一个象，上面的字代表下面的字，天干把地支统住了，如甲午、庚子、己酉。","sec":"三、干支之生与带象","t":"rule"},{"q":"下列四柱中，哪一柱属于带象十二柱？","opts":["癸卯","戊午","甲子","乙卯"],"ans":0,"exp":"带象是天干生地支且象一致：甲午、乙巳、丙辰、丙戌、丁丑、丁未、戊申、己酉、庚子、辛亥、壬寅、癸卯。甲子是支生干，戊午是支生干，乙卯是同类。","sec":"三、干支之生与带象","t":"calc"},{"q":"带象里意义最大的两种是什么？","opts":["禄带印帽、比劫带官帽","官杀带财帽、印带官杀帽","食伤带比劫、财带食伤","官杀带印帽、财带比劫帽"],"ans":1,"exp":"意义最大的只有官（杀）带财帽、印带官（杀）帽：印带官帽表示当官，官带财帽表示管财的官；其余作用不大一般不论。","sec":"四、带象的取用原则与命例","t":"rule"},{"q":"带象柱不与主位（日柱）发生关联，盲派怎么处理？","opts":["照样论，只是力量弱一些","只论为宾位的他人象","一概不论，无关则无意义","只在大运引动时才论"],"ans":2,"exp":"带象柱必须与主位有关联才论，关联方式有合、生、禄与原身换象、伏吟、拱局、入墓；刑冲穿一般不算关联。","sec":"四、带象的取用原则与命例","t":"rule"},{"q":"日主为戊，年柱为甲午，按盲派这是什么带象？","opts":["印带官帽，必为正职","财带杀帽，主与财有关的官","杀带财帽，主管财的官","印带杀帽，与日柱有关联则主当官"],"ans":3,"exp":"戊日见甲是七杀，午中丁为正印：印带杀帽，印带官杀帽表示当官，但须与日柱关联。","sec":"四、带象的取用原则与命例","t":"calc"},{"q":"与日主有关的官，在什么位置是正职、什么位置是副职？","opts":["主位坐下为正；宾位或合到时支为副","年支为正；时支被合为副","宾位为正；主位坐下为副","时支为正；日支被穿为副"],"ans":0,"exp":"官在宾位或被合到时支为副职；官在日支被它支穿（穿偏）也是副职；主神在主位、中神在坐下为正职。","sec":"四、带象的取用原则与命例","t":"diff"}],"fine":[{"q":"盲派分析四柱干支配置时，依据的三大核心原理是什么？","opts":["干支生克、五行旺衰、十神喜忌","干支虚实、天干化气、三合局势","干支生克、干支互通、干支虚实","干支互通、纳音取象、神煞辅断"],"ans":2,"exp":"干支配置讲一柱之内及柱与柱之间天干与地支的关系，核心依靠干支生克、干支互通与干支虚实三大原理。","sec":"干支配置（上）：生克、自合与带象","t":"rule"},{"q":"如甲辰一柱，天干要克制坐下地支时，天干自身必须满足什么条件？","opts":["地支必须为空亡或被它支冲破无根","天干必须先与地支暗合才能克制地支","天干必须坐在月令之上且透出比劫","天干自身必须有力，如旺、有根或有气势"],"ans":3,"exp":"干为君、支为臣，天干克地支时，天干自身必须有力（旺、有根、有气势）；甲辰柱甲坐辰有根而旺才能克辰。","sec":"基本规则","t":"rule"},{"q":"同一柱内干支发生自合时，最终由谁制去谁，取决于什么？","opts":["谁旺或有气势，谁就合克制去对方","一律由地支制去天干，因地支为根基","按阴阳属性决定，阳干克阴支、阴支克阳干","一律由天干制去地支，因干为君支为臣"],"ans":0,"exp":"自合柱内谁强谁制谁：地支旺或有气势则地支合克天干，天干旺或有气势则天干制去地支。","sec":"基本规则","t":"rule"},{"q":"丙日主前三柱本是日主合财、身旺财旺的纯发财盘，若时柱一露癸巳，象义为何变成有行政职务的企业人？","opts":["癸巳自合化火生助日主，主靠长辈荫庇获得职务","癸官坐丙之禄巳而自合，是用禄制官，权力落在自己头上","巳火被癸水盖头克制，主放弃从政专门经商求财","癸水正官虚透天干，主在朝廷挂职但不掌实权"],"ans":1,"exp":"癸是官，坐丙之禄巳，癸巳天地自合，巳火旺而制去癸水，是用禄制官，把官帽戴在自己禄头上，故带行政职务。","sec":"自合有象：一露就告诉你有官","t":"xiang"},{"q":"八字中先以火制去亥水财官，又以午亥暗合将亥拉回，为何要“制去了又拉回来”而非一制了之？","opts":["先制后合表示财官先败后成，中年后才发迹","先制后合属于合绊，能防止财官被彻底破坏","去是为了管住它，拉回来才算为我所用","单制不合只主发财，拉回来才能转为名气"],"ans":2,"exp":"制去是为了管住，拉回来是为了为我所用，不拉回就像猴子掰玉米，制了也归不到自己名下。","sec":"自合有象：一露就告诉你有官","t":"rule"},{"q":"自合九柱之中，通常表现为“天干制地支”的是哪三柱？","opts":["丙戌、壬戌、癸巳","丁亥、己亥、辛巳","丁亥、壬午、戊子","壬午、甲午、戊子"],"ans":3,"exp":"自合九柱中，丁亥、己亥、辛巳、癸巳可由地支合克天干；壬午、甲午、戊子一般为天干制地支；丙戌、壬戌须未刑开库才合。","sec":"九个自合柱","t":"calc"},{"q":"关于自合柱内天干与地支藏干的相合关系，下列对应哪一项是正确的？","opts":["辛巳柱是巳中丙火与辛金相合","己亥柱是亥中壬水与己土相合","壬戌柱是戌中戊土与壬水相合","癸巳柱是巳中庚金与癸水相合"],"ans":0,"exp":"辛巳为巳中丙与辛合；癸巳是巳中戊与癸合；己亥是亥中甲与己合；壬戌是戌中丁与壬合。","sec":"九个自合柱","t":"calc"},{"q":"当一柱干支形成自合做功时，关于双方谁有功的判断，下列哪项符合盲派规则？","opts":["只有制去对方的一方有功，被制一方无功","自合双方皆有功，谁制谁并不重要","必须天干制地支才算有功，地支制天干不算","双方相互合绊抵消，皆不算做功"],"ans":1,"exp":"自合是合而制之，属做功方式，没有合绊之意；合则旺者制弱者，自合双方皆有功，谁制谁不重要。","sec":"九个自合柱","t":"rule"},{"q":"在盲派认定的九个自合柱中，哪一柱自合做功在命局中最为少见？","opts":["癸巳","己亥","丙戌","壬午"],"ans":2,"exp":"自合九柱中，丙戌柱自合做功少见（且须未刑开戌库才合），其余八柱则较为常见。","sec":"九个自合柱","t":"rule"},{"q":"时柱辛巳自合本有制杀掌权之象，若原局另有寅木生巳又穿巳，在仕途取象上会怎样？","opts":["寅木把巳火引化为印星，主弃武从文转为学者","寅巳相穿只伤木不伤火，完全不影响辛巳制杀做功","寅木生旺巳火反制辛金，主升迁极快且任正职","巳被寅生中带穿而制不净，虽有公检法之象却无官"],"ans":3,"exp":"寅是巳的原神，寅巳相穿是生中带穿，一方面寅生巳、一方面穿坏巳，使巳杀制不干净且穿坏象，故在公检法工作却无官。","sec":"命例","t":"xiang"},{"q":"乙木日主坐下酉金七杀，但命局辰中与亥中有根，又得亥水相生，即使酉辰合伤辰根，此乙木仍作何论？","opts":["仍为活木，因两亥中根未伤而不至损寿","半死半活，遇木运才能生发，水运反主漂木","已成死木，因坐下酉杀克身且辰根被合伤","作从杀论，因日支酉金当令克尽乙木根气"],"ans":0,"exp":"乙木在辰中与亥中有根且得亥水生，为活木；辰酉合虽伤辰中乙根，但两亥中之根未伤，只是身体较差，不至损寿。","sec":"命例","t":"calc"},{"q":"在结合大运与流年分析原局自合或制局应期时，流年与原局、大运的力量对比如何？","opts":["流年为太岁君王，力量大于原局和大运","相对于原局和大运，流年之力很弱小","流年只管半年吉凶，力量略大于大运","流年与大运力量相等，均能直接推翻原局"],"ans":1,"exp":"判断应期时须知，相对于原局和大运，流年之力很弱小，因此原局火土旺时流年亥冲巳反被巳制而冲动。","sec":"命例","t":"rule"},{"q":"坤造夫宫午火伏吟到年支，年干甲木（七杀）坐午火相生，这种配置如何取象？","opts":["年上甲木克制夫宫午火，主丈夫多病且离异","年柱甲午与日柱无关，仅主公婆在远方有职务","甲统住午为一个象，夫宫带官帽，主丈夫当官","午火泄甲木之气，主丈夫能力弱全靠妻子养家"],"ans":2,"exp":"干生支称“统”，甲与午是一个意思；午火由夫宫伏吟而出代表丈夫，甲官统住午火，故丈夫当官且工作处所不止一处。","sec":"干支之生：统","t":"xiang"},{"q":"盲派所说的“广义带象”，是如何看待同一柱内天干与地支的关系的？","opts":["只看地支藏干透出与否，未透干则不能带象","只看天干不看地支，天干十神直接决定地支吉凶","必须地支生天干才算一体，干生支与干克支都不算","干支当一体看，干为头脑支为躯体，支带干就有了干的象"],"ans":3,"exp":"广义带象指同一柱的干与支当一体看，干为头脑，支为躯体；支带了某个干，支就有了干的象。","sec":"带象的两层意思","t":"rule"},{"q":"辛金日主被木火成势制住日支酉禄，但酉金之上坐着乙木偏财，按广义带象如何断？","opts":["酉带了财象可当财看，制禄即等于得财","禄被制且财星盖头，主破财兼有牢狱之灾","乙木克制酉金禄神，主因女人耗尽全部家财","酉禄被制失去作用，乙木财星虚透仅主空有虚名"],"ans":0,"exp":"酉本是日主比劫之禄，但乙木财星坐在酉上，酉就带了财的象，酉禄可当财看，制禄即是得财。","sec":"带象的两层意思","t":"xiang"},{"q":"己土日主时支辰财库上坐戊土劫财，日支丑食伤库坐己且丑入辰库，按广义带象这表示什么？","opts":["丑入辰库表示自己企业被查封，只能给他人打工","辰带他人象为大企业，丑带己象为小企业，是合伙之象","戊劫财夺取辰财库，主日主独自创业却被他人吞并","戊辰与己丑比劫争财，主兄弟反目分家各自单干"],"ans":1,"exp":"辰上坐戊（他人），辰带他人之象为别人的大企业；丑带日主象为自己的小企业；丑入辰库，主与人合伙办厂且占股份。","sec":"带象的两层意思","t":"xiang"},{"q":"狭义带象的十二柱（如甲午、乙巳、庚子等），在干支生克方向上有什么共同特征？","opts":["均是天干克地支，且天干坐下有强根","均是地支合天干，且地支藏干与天干同类","均是天干生地支，且干与支之象一致","均是地支生天干，且干支阴阳属性相同"],"ans":2,"exp":"狭义带象共十二柱，特征是天干生地支且干与支象一致；支生干如财带官帽则属延伸讨论，不在干生支十二柱内。","sec":"带象的两层意思","t":"rule"},{"q":"除印带官帽、官带财帽外，哪种“支生干”的带象柱只要与日主有关联，也算有意义的带象？","opts":["印带比劫帽（干为比劫、支为印）","食伤带财帽（干为财、支为食伤）","比劫带食伤帽（干为食伤、支为比劫）","财带官帽（干为官杀、支为财）"],"ans":3,"exp":"财带官帽（干官杀、支财）是支生干，与日主关联也算带象，表与财有关的官；对日主有意义的带象共此三种。","sec":"五条原则","t":"rule"},{"q":"一般禄带印帽作用不大，但哪两个地支因兼为戊、己之禄与印，故禄带官即是印带官？","opts":["巳与午","亥与子","寅与卯","申与酉"],"ans":0,"exp":"巳、午既是戊、己日主的禄，又是其印星，所以禄带官即是印带官，可定为与日主相关的带象。","sec":"五条原则","t":"diff"},{"q":"判断带象柱是否与主位关联时，刑、冲、穿一般不算关联，但在什么情况下刑、冲也可算有关？","opts":["大运流年同时出现三刑或六冲时","刑、冲在原局有功的情况下","刑、冲的双方五行同属燥土或湿土时","刑、冲发生在年柱与时柱之间时"],"ans":1,"exp":"带象关联主位的方式有合、生、禄与原身换象、伏吟、拱局、入墓；刑、冲、穿一般不算，但刑冲在有功时也可算有关。","sec":"五条原则","t":"diff"},{"q":"若一个本来与日主有关联的有用带象柱，在原局中被坏或被大运坏掉，应当如何论？","opts":["待流年合住坏神时，带象反而加倍应验","转作宾位他人之象，自己仍可分得一半","该带象失去意义，不再按原带象吉象论","带象减半论，仅应验在命主早年时期"],"ans":2,"exp":"带象取用原则规定：带象在原局被坏，或被大运坏，则失去意义。","sec":"五条原则","t":"rule"},{"q":"大运中出现印带官帽、官带财帽或财带官帽时，满足什么条件才算有效？","opts":["只要大运天干透出日主十神即可直接论当官","必须原局也有同一组带象柱伏吟才论","只要大运流年不逢冲破，无论是否关联日柱皆论","必须与原局日柱有合、生、伏吟等关联才论"],"ans":3,"exp":"大运中的带象条件同原局：见印带官帽、官带财帽或财带官帽，须与日柱有合、生、换象、伏吟等关联才有意义。","sec":"五条原则","t":"rule"},{"q":"日主坐下正官本为主位正职之象，若日支正官被原局它支相穿，职级会如何变化？","opts":["正官被穿偏，由正职变为副职","正官被穿坏，彻底失去官职转为平民","正官被穿动，由副职提前升任为正职","正官被穿主外派，职级不变但调往远方"],"ans":0,"exp":"官在主位坐下本为正职，但若被它支穿，盲派称为“穿偏”，正职亦会变成副职。","sec":"五条原则","t":"diff"},{"q":"命局中出现“食神合印”与“财星虚透门户”两种象，通常分别代表什么？","opts":["食神合印多主经商贸易，财虚透门户主挥霍破财","食神合印多主文化教育职业，财虚透门户主才华口才","食神合印多主离乡漂泊，财虚透门户主六亲无靠","食神合印多主武职军警，财虚透门户主吝啬守财"],"ans":1,"exp":"命局有食神合印，大部分人从事文化、思想、教育等文类职业；财星虚透无制在门户，不主发大财而主才气、口才与名气。","sec":"命例","t":"xiang"}]},{"n":7,"level":"初级","title":"干支配置（下）：互通、通根坐库与虚实","qs":[{"q":"按盲派，丁与己的禄（地支）分别是哪一个？","opts":["丁是午，己是巳","丁是巳，己是午","丁是午，己是未","都是午"],"ans":3,"exp":"丙、戊同禄巳，丁、己同禄午；己不禄未，四墓无原身。","sec":"一、干支互通：禄与原身","t":"calc"},{"q":"局中丙火日主自己制不了子水，却见时柱戊子，戊在盲派里起什么作用？","opts":["丙、戊同禄巳可互代，借戊来制","戊子天地合，只主合绊不主制","丙、戊生克无关，戊制子归戊自己","戊土克子水，但与丙火无关"],"ans":0,"exp":"丙戊同禄巳是一家，意思可互用，丙借戊制官等于自己制官。","sec":"一、干支互通：禄与原身","t":"rule"},{"q":"下列哪一柱天干与地支属半禄关系？","opts":["丙戌","丁未","己未","丁巳"],"ans":1,"exp":"未中有丁、丑中有癸，故丁未、癸丑为半禄；丙戌、丁巳是坐强根，不属半禄；己与未无关系。","sec":"二、半禄与一家","t":"diff"},{"q":"辰、戌、丑、未这四墓，在天干有没有原身？","opts":["有，辰戌丑未原身各为所藏本气之干","只有辰、戌有原身，丑、未没有","没有，不能认辰戌原身是戊，丑未原身是己","有，辰戌原身是戊，丑未原身是己"],"ans":2,"exp":"四墓在天干没有代言人，所以墓库必须靠刑冲才有用。","sec":"二、半禄与一家","t":"rule"},{"q":"盲派所说「通根」，指的是什么？","opts":["天干在任何一柱地支见根都算","同一柱或相邻一柱的地支均算","天干在月令地支见根才算","只指同一柱的地支为天干的根"],"ans":3,"exp":"天干在他柱地支见根不论通根，通根一定看坐下；此根不能被他支所伤。","sec":"三、通根与坐库","t":"diff"},{"q":"下面哪组是天干坐库、所坐之库即其根的「连根」四柱，日柱时不能被坏？","opts":["甲辰、丁未、乙未、丙戌","甲辰、丁丑、乙未、丙戌","甲戌、丁丑、乙丑、丙辰","甲辰、丁未、己未、丙戌"],"ans":0,"exp":"这四柱天干与所坐之库同气连根，其根被坏则损寿或伤健康；其余坐库之柱反而喜刑冲开库。","sec":"三、通根与坐库","t":"rule"},{"q":"日柱分别为甲辰、己未、乙丑、辛未，其中哪一柱最需要刑冲才合要求（干支同气又坐库）？","opts":["乙丑，不冲就不吉","己未，干支相同又坐库，无刑冲损财伤妻","辛未，坐库不冲则损寿","甲辰，坐库必须冲开"],"ans":1,"exp":"戊戌、戊辰、己丑、己未干与支同且坐库，须刑冲；甲辰辰是甲之根不需要冲；乙丑可冲可不冲。","sec":"三、通根与坐库","t":"calc"},{"q":"日柱干与支同且坐库（如戊辰）而无刑冲，一般如何断？为什么不能一律武断？","opts":["婚姻多不吉；有刑冲就一定吉","婚姻必不吉；无刑冲则库一定不开","婚姻多不吉；刑冲只是必要条件，非充分条件","婚姻反好；无刑冲则不伤库"],"ans":2,"exp":"财官临库喜刑冲，但组合不同意思会变，刑冲是引拔墓库财官的必要条件，不是充分条件。","sec":"三、通根与坐库","t":"rule"},{"q":"墓库要怎么作用才算「开」？","opts":["天干透出所藏之字即开","三合、六合开库最稳","刑、冲、合都能开","只有刑或冲才能开"],"ans":3,"exp":"墓只有刑或冲才算开，其他作用都不算；入墓只是带象与主位关联的一种方式。","sec":"三、通根与坐库","t":"rule"},{"q":"丙子、丙寅、丙午、丙戌四柱，其中哪柱的丙是虚透？","opts":["丙子","丙午","丙寅","丙戌"],"ans":0,"exp":"丙坐寅午戌有根有生为实，坐子申辰无根无生为虚；地支本身皆实。","sec":"四、干支虚实","t":"calc"},{"q":"财虚透而吉，主才气、人缘、不贪财，但有一个条件是什么？","opts":["不能入库","不能合","不能被冲","不能透双"],"ans":1,"exp":"财虚的人不贪财、人缘好，但一合日主就不一定了；不合则论吉，正财虚尤其好。","sec":"四、干支虚实","t":"rule"},{"q":"原局某字喜虚，大运流年使它通根变实，断为什么？","opts":["主迟发，只是晚运才好","正常，根深更有力","反常，象坏了，不吉","主吉，应期落实"],"ans":2,"exp":"喜虚的字运来见根变实则坏；喜实的字运来虚透也坏，以此断应期。","sec":"四、干支虚实","t":"rule"}],"fine":[{"q":"在盲派干支互通体系中，“禄”与“原身”的定义方向分别是什么？","opts":["阳干找地支叫禄，阴干找地支叫原身","日干找月令叫禄，月令找日干叫原身","地支找天干叫禄，天干找地支叫原身","天干找地支叫禄，地支找天干叫原身"],"ans":3,"exp":"天干找地支叫禄（如甲找寅），是天干在地支的延伸；地支找天干叫原身（如寅找甲），是地支在天干的延伸。","sec":"基本对应","t":"rule"},{"q":"当禄与原身同时出现在一个命局中时，二者在论命时作何处理？","opts":["互通互代，可当一个字看，同功同权","按宾主严格区分，绝不能互相代替","禄只管地支做功，原身只管天干表象","只有同柱相见才互代，隔柱则互不相干"],"ans":0,"exp":"禄与原身同现于一局，互通互代，可当一个字看，同功同权，也叫“互换”，象一致而可相互代替。","sec":"基本对应","t":"rule"},{"q":"按盲派禄与原身的对应表，庚、辛、壬、癸四天干对应的禄支依次是哪一组？","opts":["申、酉、子、亥","申、酉、亥、子","辰、酉、申、子","戌、酉、亥、丑"],"ans":1,"exp":"十干禄支对应为：甲寅、乙卯、丙巳、丁午、戊巳、己午、庚申、辛酉、壬亥、癸子。","sec":"基本对应","t":"calc"},{"q":"女命夫宫巳火之原身戊土透出合制夫星子水，怎么断出“丈夫发财”而非“自己当官”？","opts":["因戊子自合属于合绊，女命遇合绊一律只主发财","因子水是女命食伤而非官杀，制食伤只主求财","女命夫宫透出是丈夫做功，男命此局才断自己当官","因原身力量弱于禄神，女命借原身做功不主官贵"],"ans":2,"exp":"巳戊同象等于夫宫制子官，做功的是夫宫巳的原身戊（丈夫），子又是戊之财，故丈夫发财；若是男命则自己当官。","sec":"命例","t":"diff"},{"q":"盲派判断婚姻好坏的核心口诀中，什么样的配置主好婚姻？","opts":["夫星旺而无制且透出天干，夫妻宫受刑冲","夫宫与夫星各自孤立不发生生克合穿关系","夫星坐下逢空亡且大运流年不再引动填实","夫宫喜神制夫星忌神且能制净，夫妻宫不坏"],"ans":3,"exp":"口诀：夫宫喜神制夫星忌神，且能制净，是好婚姻；看婚姻以夫妻宫为主，宫没坏婚姻无事，制不死则婚姻坏。","sec":"命例","t":"rule"},{"q":"原局两地支相合做功（如寅丑合做功）时，大运流年最忌讳出现什么情况？","opts":["最忌大运流年来穿、冲或合破原局相合之字","最忌大运流年再出现同一组相合之字伏吟","最忌大运流年天干透出比劫来分夺财官","最忌大运流年地支生助原局主位日支"],"ans":0,"exp":"原局相合做功，最不喜大运流年来穿、冲、合；如寅丑合做功，遇巳年穿寅、午年穿丑皆主坏事受处分。","sec":"命例","t":"rule"},{"q":"盲派所说的“藤萝系甲”半禄关系，其适用前提与具体表现是什么？","opts":["仅限甲乙两干同柱并透天干时才能互相借根","甲乙为活木时可共根，甲见卯为根、乙见寅为根","无论活木死木，甲乙日主见亥卯未皆算共根","甲木可借乙之卯根，乙木不能借甲之寅根"],"ans":1,"exp":"甲、乙为活木时可共根，称藤萝系甲：甲木日主见卯为根，乙木见寅为根；死木则不论。","sec":"二、半禄与一家","t":"rule"},{"q":"半禄关系（如丙戊、丁己、丁未、癸丑）在亲密程度与互代作用上，与真正的禄原身相比如何？","opts":["半禄力量大于禄原身，因包含双干或暗藏之气","完全不算一家，仅在原局缺印时才临时借用","当一家看，但只及禄与原身亲近的一部分，不如禄原身","与禄原身完全等同，任何情况下都能百分百互代"],"ans":2,"exp":"具有半禄关系的干支像兄弟般亲密，也当一家看，但只有禄与原身那种亲近的一部分，比不上禄与原身的关系。","sec":"二、半禄与一家","t":"diff"},{"q":"在断人事与事业取象时，命局出现半禄关系常带有哪一层特定含义？","opts":["孤军奋战、独资经营之意","官非诉讼、口舌争端之意","远走他乡、背井离乡之意","合伙、占股份之意"],"ans":3,"exp":"半禄关系有合伙、股份的意思，如宾位酉财上坐己，与日主丁半通禄，主此财有自己一份股份。","sec":"二、半禄与一家","t":"xiang"},{"q":"甲乙活木最怕遇到的“埋根之铁”，在命局中具体指哪种组合？","opts":["如甲辰柱见酉合辰、乙卯柱见申合卯，坏了活木之根","如甲寅柱见午火泄木、乙亥柱见巳火冲亥","如甲子柱见卯刑子、乙未柱见子穿未","如甲戌柱见未刑戌、乙丑柱见戌刑丑"],"ans":0,"exp":"活木最怕埋根之铁：如甲辰柱见酉合辰、乙卯柱见申合卯，金坏了活木之根，活木难活，日主为活木则损健康寿命。","sec":"规则","t":"rule"},{"q":"下列四柱中，哪一组属于“不坐库但坐支通根，且其根同样不能被坏”的日柱？","opts":["丙辰、丁丑、辛未","乙亥、庚申、丁巳","甲戌、乙丑、庚戌","戊戌、己丑、壬辰"],"ans":1,"exp":"乙亥、乙卯、甲寅、庚申、辛酉、丁巳、丙午七柱虽不坐库，但坐支通根，其根同样不能被坏。","sec":"规则","t":"calc"},{"q":"除甲辰、乙未、丁未、丙戌连根四柱外，其余十六个日主坐库之柱（如甲戌、乙丑、庚戌等）坐支被坏时，对寿命有何影响？","opts":["坐支被冲必主短寿，被刑则反主长寿","男命损寿而女命无妨，因阳干坐库忌坏","对寿命健康无损，反而喜刑冲开库","同样严重损寿，必须用印星化泄保护"],"ans":2,"exp":"其余十六柱坐支之库可以被坏，坏则对寿命健康无损，开库则吉。","sec":"规则","t":"rule"},{"q":"同属干支同气坐库，为何“戊戌”一柱与其他三柱不同，宜去冲别人而不宜被辰冲？","opts":["戌为天罗地网之库，只能刑开绝不能用冲开","戊戌本身自带暗合，被辰冲破则彻底失去官贵","戊戌干支皆为阳燥土，遇辰冲则化为水局克身","戌中有丁火印为强根，火旺去冲它支吉，辰冲坏火则凶"],"ans":3,"exp":"戊戌柱中戌藏丁火印为强根，最好火气旺去冲别人、不让别人冲它；若来个辰把戌中火干掉就坏了。","sec":"规则","t":"diff"},{"q":"宾位带象入日支“未”墓时，为何日柱为“己未”不算关联，而日柱为“丁未”却算关联？","opts":["己与未是两种象无关，未则是丁火之根故有关联","己未干支同气只主自闭，丁未为半禄故能纳宾位","未墓只收火木不收土，己土坐未无法引动宾位","己土克制未中乙木阻断入墓，丁火生助未土故通气"],"ans":0,"exp":"入墓是带象与主位关联的方式之一，但己未时己与未是两种象、无关，故宾位入未不算关联；丁未时未是丁之根，则有关联。","sec":"规则","t":"diff"},{"q":"男命日支妻宫为未土，反过来相穿月令中唯一的妻星子水，在婚姻上通常如何断？","opts":["主妻星被穿变成偏财，一生桃花极旺且多婚","妻星被穿而无法进入妻宫，终生与婚姻无缘","主妻子身体多病但夫妻感情深厚，白头偕老","主早婚必离，但中晚年再婚后婚姻十分美满"],"ans":1,"exp":"妻宫穿妻星，妻星被穿而无法进入妻宫，男命月令唯一财星被妻宫穿，主一生与婚姻无缘（不代表无钱花）。","sec":"命例：日柱坐库","t":"xiang"},{"q":"日柱坐夫宫墓库（如甲戌），当大运或流年遇到辰冲日支戌库时，流年冲库在断法上称为什么？","opts":["流年冲库为闭库，主夫妻感情从此彻底锁死","流年冲库为换象，主配偶升官或购置不动产","流年冲库为动库，多主婚变或引动变故","流年冲库为合局，主当年必添丁进口大吉"],"ans":2,"exp":"如甲戌日柱原局戌为夫宫，逢申运庚辰年，流年辰冲夫宫戌，流年冲库为动库，该年离婚。","sec":"命例：日柱坐库","t":"rule"},{"q":"传统命理看旺衰须参照月令，盲派的“干支虚实”是如何确定参照对象的？","opts":["以日主为中心，看他柱天干在月令是否得气","以全局五行数量多少为准，多者为实、少者为虚","只看年柱与时柱的纳音生克，不论坐下地支","只就同一柱干支而言，与别的柱及生克无关"],"ans":3,"exp":"盲派的虚实不等于传统衰旺，只就同一柱干支而言，与别的柱及生克无关；虚实本身是象，更重在看应期。","sec":"原理","t":"diff"},{"q":"按盲派干支虚实的基本原则，地支有没有虚实之分？","opts":["没有，地支因气强，全都算实","有，地支不透天干者为虚，透干者为实","有，四墓库地支为虚，四长生四正地支为实","有，被它支冲穿之地支为虚，相合之地支为实"],"ans":0,"exp":"天干气弱、地支气强；天干无根无生者虚，有根有生者实；地支因气强，都算实。","sec":"原理","t":"rule"},{"q":"在六十甲子虚实表中，戊辰、己丑虽归入“实”，但在实际运用中为何按弱论？","opts":["因辰、丑内藏水库，会直接克死坐上戊、己土","因辰、丑为湿土，帮扶戊、己土之力很弱","因湿土只在冬季有用，其余三季皆无帮扶之力","因戊辰、己丑干支同气坐库，本身属空亡之柱"],"ans":1,"exp":"戊辰、己丑虽归入实，但辰、丑为湿土，帮土力弱，实际运用中这两柱的戊、己按弱论。","sec":"六十甲子虚实表","t":"diff"},{"q":"对照六十甲子虚实表，下列四柱中天干属于“实”（有根有生）的是哪一柱？","opts":["辛巳","庚午","庚辰","壬寅"],"ans":2,"exp":"庚坐申、辰为实，坐子午寅戌为虚；辛坐巳亥未卯为虚；壬坐戌午寅为虚，坐申子辰为实。","sec":"六十甲子虚实表","t":"calc"},{"q":"在盲派虚的含义与用法中，“杀虚透”与“官星虚透且被制净”分别主什么？","opts":["杀虚透主掌大权，官星虚透被制净则只主虚名","杀虚透主官灾牢狱，官星虚透被制净主辞职退隐","二者皆主无权，只代表口才好与文化学历高","杀虚透主名气无权，官星虚透且被制干净则有权"],"ans":3,"exp":"杀虚透没有权，主名气（被制干净另说）；官星虚透且被制干净，则有权（如癸官虚透被巳制净）。","sec":"虚的含义与用法","t":"diff"},{"q":"原局中的字在大运出现时，“制干净的贼神捕神”与“制不干净之字”各有何吉凶要求？","opts":["制干净后成贼神捕神最喜出现，制不干净则忌大运出现","贼神最忌大运出现，捕神则无论何时出现皆主凶","制干净的字忌大运再现，制不干净的字喜大运补制","无论原局制净与否，大运出现一律按吉象应期论"],"ans":0,"exp":"原局制干净后成贼神与捕神，最喜出现；若原局制不干净，就不能在大运出现，出现就反了。","sec":"虚的含义与用法","t":"rule"},{"q":"盲派也论五行十二长生，但在区分阴阳干的长生位置上有什么特点？","opts":["只论阳干不论阴干，阴干一概借用阳干墓库","不分阴阳干，如子水与亥水皆长生在申","严格区分阳顺阴逆，如子水长生在申、亥水在卯","只论五行的帝旺与墓库，不论长生与沐浴"],"ans":1,"exp":"盲派论五行长生十二地，但不分阴阳干，如子水、亥水皆长生在申。","sec":"虚的含义与用法","t":"rule"},{"q":"如戊坐辰湿土身弱而合癸水正财，盲派对“身弱合财”与“身强合财”对财星的要求有何不同？","opts":["无论身强身弱，合财一律只喜财星虚透忌见实根","身弱合财忌讳虚透，必须走比劫大运才能得财","身弱合财贵在财星虚透，身强合财喜财旺实","身弱合财喜财旺入库，身强合财贵在财星虚透"],"ans":2,"exp":"戊坐辰湿土帮土力弱为身弱，癸财虚透，戊癸合，身弱合财贵在财星虚透，而身强合财喜财旺。","sec":"五、虚实命例","t":"diff"}]},{"n":8,"level":"初级","title":"合（一）天干五合","qs":[{"q":"按盲派，天干五合的看法是（　）。","opts":["只讲合不讲化，合是相克关系，是做功方式","合则化为他行，合化成功才有力","合是相生关系，合了就失去克性","合只主感情亲近，不属于做功方式"],"ans":0,"exp":"本派不主张合化；能合的两干必有克的关系，旺者把弱者制死，做功效率很高。","sec":"一、总论：合是什么、怎么用","t":"rule"},{"q":"合去、合伤、合绊三者的区别标准是（　）。","opts":["悬殊为合绊，不悬殊为合去，相当为合伤","悬殊为合去，不悬殊为合伤，相当为合绊","相当为合去，悬殊为合伤，不悬殊为合绊","看合的位置：年月为合去，日时为合绊"],"ans":1,"exp":"按双方力量对比：悬殊弱者制死是合去，强弱不悬殊弱者受伤是合伤，力量相当互相绊住是合绊。","sec":"一、总论：合是什么、怎么用","t":"diff"},{"q":"合伤与合去相比，伤六亲的应期和原局含义是（　）。","opts":["应期略晚，原局合伤主六亲全无","应期略早，原局合伤多为当即破财","应期略晚，原局合伤多为待时而用","应期相同，原局合伤主六亲当年必死"],"ans":2,"exp":"合伤弱者受伤未死，比合去略轻，伤六亲应期略晚，原局合伤一般是待时而用。","sec":"三、合伤","t":"diff"},{"q":"要断父亲早亡，必须具备什么条件？","opts":["父宫被冲就可断，不必看星","父星旺而无制，才可断","父星被合去就可断，不必看宫","父星与所坐的父宫同时被坏"],"ans":3,"exp":"看六亲生死，星与宫必须同时被坏；单坏星不一定死，宫有原神相生则一时死不了。","sec":"二、合去（合制）","t":"rule"},{"q":"口诀「父临库，父当早死」的意思是（　）。","opts":["父星落在墓库，不论旺衰都主父早亡","父宫被冲开库，则父亲早亡","父星入库后逢冲，才主父早亡","父星落在墓库，旺则无事，弱才早亡"],"ans":0,"exp":"父星落墓库不论旺衰，都主父早亡；库中有本气可延气，死得稍晚。","sec":"二、合去（合制）","t":"rule"},{"q":"男命月干辛（财）极弱，时干丙旺，丙辛相合，辛被丙合去，应怎么论？","opts":["丙辛合化水，辛的财象转为水象","辛被制去，所代表的财被得到，六亲则有问题","辛只被合伤，待时再用，不论应期","丙辛相绊，双方都失去原性"],"ans":1,"exp":"力量悬殊为合去：被合去之字若是财则被命主得到，若代表六亲则此人死；极弱者才称合去。","sec":"二、合去（合制）","t":"calc"},{"q":"流年天干合住原局旺字，「合留」与「合动」的区别是（　）。","opts":["合留主财，合动主婚姻","合留合动都主人，只是应期先后不同","合留主人，合动主事","合留主事，合动主人"],"ans":2,"exp":"合动与合留看法相同，合动主事，合留主人；多用合留断婚姻应期。","sec":"四、合留与合动","t":"diff"},{"q":"女命流年只合住夫星，夫宫未被动，应断为（　）。","opts":["结婚，夫宫不动才能稳定","离婚，夫星被合走","结婚，夫星被合住即应婚期","谈对象，不是结婚"],"ans":3,"exp":"星为对象、宫为丈夫；只合星是谈对象，星宫都被合动才是结婚应期。","sec":"合留","t":"rule"},{"q":"原局年干丙、日干辛，中间隔着月干戊，丙辛能否成合绊？","opts":["不能，隔开太远绊不住，须紧邻贴合","能，只要年干与日干力量相当就绊","能，同在原局天干相合就可绊","不能，合绊只在大运与原局之间成立"],"ans":0,"exp":"原局合绊要求紧邻两柱天干相合，远了绊不住；大运合原局任一柱才视为紧邻。","sec":"五、合绊","t":"calc"},{"q":"合绊之字被冲，会怎样？功神被绊又如何？","opts":["合绊逢冲则双方皆伤；功神被绊不吉","合绊逢冲则不合，恢复原性；功神被绊不吉","合绊逢冲则合得更紧；功神被绊反吉","合绊逢冲则化为他行；功神被绊反吉"],"ans":1,"exp":"合绊逢冲则不合，双方恢复原性；功神被绊失去作用不吉，忌神被绊则喜。","sec":"五、合绊","t":"rule"},{"q":"八字中食神合印、劫财合财、伤官合杀，换象后分别主（　）。","opts":["学术思想、劫取之财、伤官主子女","劫取之财、学术思想、伤官当权力","学术思想、劫取之财、伤官当权力","学术思想、合伙之财、伤官主灾病"],"ans":2,"exp":"食神合印是思想性学问；劫财合财是不劳而获的劫取之财；伤官合杀，伤官当权力看。","sec":"六、天干五合的换象原理","t":"xiang"}],"fine":[{"q":"天干能量较低，为何盲派认为天干五合“克而合”的做功效率很高？","opts":["一般相克难把对方制净，克而合才能将弱方制死","合能引动地支三合局同时参与天干做功","五合能直接把天干合化成更有力的五行","天干相合后双方力量翻倍，可同时制两干"],"ans":0,"exp":"天干能量低，单纯相克很难把对方制净；只有“克而合”，旺的一方才能把弱的一方制死，因此做功效率很高。","sec":"一、总论：合是什么、怎么用","t":"rule"},{"q":"日主在命局中主动去合的十神，只可能是哪两类，且有何含义？","opts":["不是合比劫便是合七杀，代表日主的竞争对手","不是合财便是合官，代表日主所追求的东西","不是合印便是合食伤，代表日主的思想根基","合财只主发财，合官只主受制于人而无贵气"],"ans":1,"exp":"日主在命局中所合之物，不是合财便是合官；被合之物就是日主所追求的东西，分析命局必看。","sec":"一、总论：合是什么、怎么用","t":"rule"},{"q":"单纯一个“克”或流年单纯克原局为何意义不大？八字作用的总纲是什么？","opts":["天干生克为总纲，流年克原局一律按大凶应期论","纳音生克为总纲，单纯天干相克必须看纳音是否相克","刑冲合害为总纲，单纯之克除非原局贴克大运又来才论","五行平衡为总纲，流年克原局忌神必主当年暴富"],"ans":2,"exp":"刑冲合害为八字的总纲，单纯一个克意义不大，除非原局有贴克、大运又来；八字是靠刑冲合害产生各种关系。","sec":"一、总论：合是什么、怎么用","t":"diff"},{"q":"父星虽被合去，但若所坐之宫有原神相生，或墓库中有本气，对丧父应期有何影响？","opts":["只要父星被合去，无论宫位有无生助必定当年即死","库中有本气会加速父星入墓，反而比无库死得更早","宫有原神相生虽不死，但主父亲终身瘫痪卧床","星坏宫有生则一时死不了，库有本气可延气而死得稍晚"],"ans":3,"exp":"星坏而宫有原神相生，则父亲一时死不了；库中有本气可以“延气”，死得稍晚。","sec":"二、合去（合制）","t":"diff"},{"q":"为何父母星与父母宫若在月柱被坏，往往主父母死得比较早？","opts":["月令在时间上居早，未交大运前正是走月令运","月柱紧贴日主，日主贴身克父母导致早年刑克最重","月令为父母星的绝对墓库，逢合即直接闭库而亡","月柱天干力量最弱，最容易被年干或日干瞬间合死"],"ans":0,"exp":"月令在时间上居早，没交大运前就是走月令运，所以月柱的父母星宫同时被坏时，父母死得早。","sec":"二、合去（合制）","t":"rule"},{"q":"命局天干有合时，地支最忌讳再出现穿或破，原因是什么？","opts":["地支穿破只影响婚姻感情，不影响天干求财做功","地支一破，天干相合的象就坏了，事做不成或不长久","地支穿破会引发天干反克，导致主位日主立刻受伤","地支穿破会使天干五合直接变成合绊，永远无法解开"],"ans":1,"exp":"天干有合，地支不喜再穿、破，地支一破，天干相合的象就坏了——天干要做的事做不成或做不长久。","sec":"二、合去（合制）","t":"rule"},{"q":"在盲派作用关系中，“破”（如卯午破、子卯破）是否属于做功方式？","opts":["只对地支有生克作用时算做功，无生克时不算","属于做功方式，专门用来破开四墓库或制去弱神","不属做功方式，主要是表象，双方互破致象都坏","属于特殊制局，旺的一方能借破彻底制死弱的一方"],"ans":2,"exp":"破不属做功方式，主要是表象，一般是双方互破，二者的象都坏了。","sec":"二、合去（合制）","t":"diff"},{"q":"男命父宫卯木本生丙火，一旦卯被戌合住便不再去生丙火，盲派把这种现象称为什么？","opts":["夺食","闭气","反生","弃养"],"ans":3,"exp":"父宫卯本生丙火，一被戌合便不生丙火，称“弃养”，主星宫皆坏。","sec":"二、合去（合制）","t":"xiang"},{"q":"天干出现“合伤”时，要判断被伤之字最终受伤的轻重程度，主要看哪两项？","opts":["一看其根，二看其原神","一看虚实，二看空亡","一看月令，二看胎元","一看纳音，二看神煞"],"ans":0,"exp":"判断被合伤之字受伤的程度，一看其根，二看其原神。","sec":"三、合伤","t":"rule"},{"q":"乙木以日支卯为根，遇到“两辰夹穿一卯”与“一辰穿卯又见申合卯”，后果有何不同？","opts":["两种情形完全相同，均主命主八岁前必定克死父母","两辰夹穿制不死但已伤；一辰穿加申合则根全坏而伤父较早","两辰夹穿力大必死无疑；一辰穿加申合因申解穿反而无事","一辰穿加申合只伤妻宫不伤父星，两辰夹穿才伤父星"],"ans":1,"exp":"两辰夹穿制不死但已被伤，不是即刻死；一辰穿一卯又有申克合卯，乙木之根全坏，伤父较早。","sec":"三、合伤","t":"diff"},{"q":"男命年干乙木偏财被庚合伤，而日支为卯木，同为禄与原身，取象上如何区分？","opts":["乙在年干当妻看，卯在日支当父看，绝不可颠倒","二者完全等同，卯被穿既主父死也同时主妻子立即死亡","从宫位区分：年干乙当父看，日支卯居正位当妻看","只看天干乙木不看地支卯，因天干为显象地支为隐象"],"ans":2,"exp":"从宫位区分，同为乙之禄与原身也要分开看：乙落年干代表父，卯居日支正位当妻，妻星得正位怕被他支坏。","sec":"三、合伤","t":"diff"},{"q":"流年天干来“合留”原局或大运某字以应婚期或应人，对被合之字有什么前提要求？","opts":["必须是原局虚透无根的字，实字太重流年合不住","必须是原局从未出现过的字，流年填实才算合留","必须是日主自身的禄神，其他十神一律不算合留","必须是原局或大运中有气或旺的字，弱字留不住"],"ans":3,"exp":"合留指流年之干合住原局或大运中有气或旺的字，该字弱则留不住，多用于断婚姻应期。","sec":"合留","t":"rule"},{"q":"大约多少比例的八字婚姻应期符合“合留”原则？哪些合的关系都可用于断婚期？","opts":["约三分之二符合；五合、六合、三合、半三合、暗合皆可用","约三分之一符合；仅限天干五合与地支六合可用","约一半符合；暗合与半三合力量太小不能断婚期","约九成以上符合；必须同时见到天干五合与地支三合"],"ans":0,"exp":"天干五合、地支六合、三合、半三合、暗合都可用来断婚姻应期，大约三分之二的八字应期符合合留原则。","sec":"合留","t":"rule"},{"q":"男命财多或女命官杀多时，如何区分“真配偶星”与“婚前或婚后的异性朋友”？","opts":["天干透出者为真配偶星，地支暗藏者为异性朋友","与日主或婚姻宫有关联者为配偶星，无关者为异性朋友","正财正官一律为真配偶星，偏财七杀一律为异性朋友","在年月柱者为真配偶星，在时柱者一律为异性朋友"],"ans":1,"exp":"配偶星必须找与日主或婚姻宫有合、冲、换象等关联的财或官杀；配偶星多而与宫、日主无关者，是婚前或婚后异性朋友。","sec":"合留","t":"diff"},{"q":"断婚姻应期时，“领结婚证”主要看什么星？未领证同居如何认定？","opts":["结婚证看财官星；无证同居只在流年合宫时算婚姻","结婚证看比劫星；无证同居必须满三年才算婚姻","结婚证看印星；无证同居满半年即当事实婚姻论","结婚证看食伤星；无证同居无论多久都不算婚姻"],"ans":2,"exp":"结婚证看印星；无证同居者无法看印时，同居满半年即当事实婚姻论。","sec":"合留","t":"xiang"},{"q":"在盲派婚姻断法中，“合留”原则与原局本身的关系是什么？","opts":["合留不仅定婚期，还能彻底改变原局婚姻不好的定数","只要流年逢合留结婚，以后夫妻关系就必定白头偕老","原局婚姻不好则根本不会出现合留之年，必终生不婚","合留只管婚姻应期，婚姻好坏仍要看原局"],"ans":3,"exp":"合留只管应期，婚姻好坏看原局；即便流年合留结婚，原局婚姻不好以后仍可能离婚。","sec":"合留","t":"rule"},{"q":"流年天干合动命局日主时，说明是自己要做的事，具体会应什么事要看什么？","opts":["看流年地支，干支同时来共同定事象","看年柱纳音与流年纳音之间的生克关系","只看日主坐下日支，与流年地支毫无关系","只看大运天干，流年地支只管应期不管事象"],"ans":0,"exp":"合日主则与日主有关联，是自己要做的事，应什么事看流年地支（干支同时来）。","sec":"合动","t":"step"},{"q":"大运天干与原局任一柱天干相合时，在距离与作用顺序上如何看待？","opts":["大运合原局四柱力量完全平均，没有任何先后轻重之分","视为紧邻相合，但早年作用于年月强、后期往后，有先后轻重","只合日干与时干有效，大运天干合年干与月干无效","一律视为隔柱遥合，只有合住月干时才算紧邻成绊"],"ans":1,"exp":"大运天干与原局任一柱天干相合，视为紧邻相合；但早年作用于年月强、后期往后，仍有先后轻重。","sec":"五、合绊","t":"diff"},{"q":"流年干支以“天地相合”成合绊时（如流年壬戌合丁卯），这是指流年与谁相合？","opts":["专指流年与大运柱天地相合，与原局无关","专指流年与日柱天地相合，其余三柱皆不算","指流年与原局某柱天地相合，不是与大运合","既可与原局相合，也可与胎元、命宫天地相合"],"ans":2,"exp":"合绊成立情形之一：流年干支与原局某柱天地相合（如原局丁卯柱遇流年壬戌），这里指流年与原局合，不是与大运合。","sec":"五、合绊","t":"rule"},{"q":"原局之字各有其“原性”（合、冲或他用），关于原局有功之字在大运流年的喜忌，哪项正确？","opts":["原局无论合或冲有功，都最喜大运流年来合绊固之","原局逢合有功喜运岁再冲，原局逢冲有功喜运岁再合","原局逢合有功只忌穿破不忌冲，逢冲有功只忌墓不忌合","原局逢合有功忌运岁来冲，原局逢冲有功忌运岁来合"],"ans":3,"exp":"原局逢合而有功之字，不喜大运流年来冲；原局逢冲而有功之字，不喜大运流年来合（被绊失原性）。","sec":"五、合绊","t":"diff"},{"q":"两干力量相当发生合绊时，是否区分主绊与被绊？谁受损较重？","opts":["不分主绊被绊，双方互绊，但相对弱的一方受损较重","只有主动去合的那一干受损，被动被合的一干反得生助","双方受损完全均等，不可能出现一方受损较重","严格区分主绊与被绊，永远是阳干绊阴干、阳干无损"],"ans":0,"exp":"合绊的两字不分主绊被绊，互绊，但相对弱的一方受损较重。","sec":"五、合绊","t":"rule"},{"q":"在判断乙木食神能否生丁火财星时，天干隔位与地支隔位的相生规则有何不同？","opts":["天干隔位能生，地支隔位不生","天干隔位不生，地支隔位能生","天干与地支隔位一律都不能相生","天干与地支隔位只要中间无克都能相生"],"ans":1,"exp":"如癸水生乙木食神，乙隔位不能生丁，因天干隔位不生，地支能生。","sec":"五、合绊","t":"diff"},{"q":"天干五合换象中，“食神合印”多主从事教育或文化思想工作，那么“伤官合印”通常主什么？","opts":["印为学历、伤官为叛逆，主早年辍学无正式职业","印为母亲、伤官为克泄，主克伤母亲且一生漂泊","印为职业、伤官为技艺，主以技艺为职业","印为房产、伤官为口舌，主因房产纠纷吃官司"],"ans":2,"exp":"天干五合“一方定义另一方性质”：伤官合印，印为职业、伤官为技艺，则以技艺为职业。","sec":"六、天干五合的换象原理","t":"xiang"},{"q":"若命局中“食神合印”落在年月宾位而远离日主，取象上对命主从事学术的态度有何影响？","opts":["代表命主学术成果全被他人盗用，自己一无所得","代表学术成就超越常人，必获诺贝尔级最高荣誉","代表命主完全不懂学术，一生只能从事体力劳动","所搞学术不是他最爱好的，可称为“学匠”"],"ans":3,"exp":"食神与印相合而居宾位、远离日主，所搞的学术不是他最爱好的，可称“学匠”。","sec":"六、天干五合的换象原理","t":"xiang"}]},{"n":9,"level":"初级","title":"合（二）地支六合","qs":[{"q":"地支六合与天干五合相比，多出的一种合法是什么？","opts":["去合（合后一方被合走掉）","生合（一方生另一方，如辰酉）","化合（合后一定变成另一五行）","破合（合后双方都被破坏）"],"ans":1,"exp":"天干合只有克合；地支六合还有生合。六合一般不讲化，通称合绊。","sec":"一、六合总论","t":"diff"},{"q":"配偶星是正官或正财、坐在正位时，他星来合它，主什么？","opts":["主早婚，但婚姻没有什么影响","婚姻更稳固，合住了就不走","配偶被别人合跑，婚姻不顺","配偶星被制，反而更加吉利"],"ans":2,"exp":"得正位的配偶星不喜他星来合；若是偏星（偏财、七杀）则可被制。","sec":"一、六合总论","t":"rule"},{"q":"辰酉合属于哪一类合？辰酉合时被克伤的遁藏之气是什么？","opts":["克合兼闭气；酉中辛金被辰土克","克合；辰中癸水被酉金克伤","生合；酉中辛金被辰土所克伤","生合兼合伤；辰中乙木被酉克伤"],"ans":3,"exp":"辰酉是生合，又能闭辰中水库，并合伤辰中乙木。","sec":"二、六合的四种作用","t":"calc"},{"q":"墓库逢六合，库里的气怎样？怎样才能让库发挥作用？","opts":["合则库闭，只有逢刑、冲才能开库","合则库闭，逢穿才能够开库","合则库开，库气自然就流通了","合则库闭，逢合局再合才能开"],"ans":0,"exp":"墓库只有刑冲才能开；合库则闭气，库中遁藏之物成无用之物。","sec":"二、六合的四种作用","t":"rule"},{"q":"被生合保护着的字，若是局中「要制的字」，见大运流年再来生、来合，结果如何？","opts":["被制得更干净，吉","制不了，凶不可免","被生旺，反而转凶为吉","没有影响，仍可制"],"ans":1,"exp":"生合有「受保护」之意；要制的字被合保护就制不了。","sec":"二、六合的四种作用","t":"rule"},{"q":"婚姻应期的「合留」归纳：原局星宫已有合，流年用什么去应？","opts":["流年再合之为应","流年刑之为应","流年冲之为应","流年克之为应"],"ans":2,"exp":"原局星宫有合，流年冲应；原局有冲，流年合应；不冲不合，流年去合星或宫为应。","sec":"三、六合的用法","t":"rule"},{"q":"「流年合大运」与「流年干支与原局某柱天地合」，各是什么结论？","opts":["流年合大运为合绊；天地合为合动","两者都是合绊，没有区别","两者都是合动，一概不论合绊","流年合大运为合动；天地合按合绊"],"ans":3,"exp":"流年合正在行的大运不是互绊，而是引动大运；流年干支与原局某柱天地合才是合绊。","sec":"三、六合的用法","t":"diff"},{"q":"寅亥合时，寅得亥水之后，寅木的象是什么？","opts":["成湿木，不生火反灭火","成死木，被水荡走","成枯木，需要火去生","成旺木，更能生火"],"ans":0,"exp":"亥中壬水灭寅中丙火，寅得亥为湿木，不生火反灭火。","sec":"四、六合逐个详解（一）：寅亥、卯戌、辰酉","t":"calc"},{"q":"财库戌被卯合住（卯戌合），一见卯运流年会怎样？为什么？","opts":["开了戌库，主发大财","闭了戌库，主破财","合到卯财，主进财","卯制戌，库中财被制住而得财"],"ans":1,"exp":"卯戌合闭戌库，火库的作用要冲才发挥；原局财库被合闭，一见卯就破财。","sec":"四、六合逐个详解（一）：寅亥、卯戌、辰酉","t":"rule"},{"q":"六合里，哪一个合做功效率最高、能量最大？","opts":["辰酉合","午未合","巳申合","子丑合"],"ans":2,"exp":"巳申合最彻底；午未合最差，只增火力闭木库；子丑合效率不高。","sec":"五、六合逐个详解（二）：巳申、午未、子丑","t":"diff"},{"q":"子丑合「有两重性」，指的是什么？","opts":["既可开库又可闭库，要看冲刑","合后既成水又成土，五行互换","既能合绊又能合去，要看流年","好东西、坏东西都被绊，看大运扶谁"],"ans":3,"exp":"子丑合是合绊：局中毛病被绊是好事，好东西被绊是坏事；走哪边的运，哪一边被绊。","sec":"五、六合逐个详解（二）：巳申、午未、子丑","t":"rule"},{"q":"六合换象（互用对方信息）的前提条件是什么？","opts":["克合中一方制住另一方才能换","只要合上了就能换象","必须天干透出才能换象","必须三合成局才能换象"],"ans":0,"exp":"克合当一方制去一方时，象可互换；没有制住则不能换。","sec":"六、六合换象","t":"rule"}],"fine":[{"q":"地支六合与天干五合相比，为何一般通称“合绊”，很少像天干那样细分为合去、合伤？","opts":["地支六合只论生合不论克合，因此永远不会出现合去","地支力量都强，一般通称合绊，特殊应凶时才有合去之意","地支藏干复杂，无法比较双方力量大小，只能一概论绊","地支六合在原局不发生做功，只在大运流年才论合去"],"ans":1,"exp":"地支力量都强，没有天干那样的“合去、合伤”之分，一般通称合绊，特殊应凶时才有合去之意。","sec":"一、六合总论","t":"diff"},{"q":"在盲派命理的各类合局（五合、六合、三合、暗合）中，地支六合的粘合性如何？","opts":["六合最松散，遇到天干相克就会自动散开","六合只在原局紧贴时紧密，大运流年毫无粘合性","六合是八字中最紧密的合，粘合性强","六合粘合性不如三合局，仅强于暗合与半合"],"ans":2,"exp":"六合是八字中最紧密的合，粘合性强，比天干五合更繁杂，一般不讲化。","sec":"一、六合总论","t":"rule"},{"q":"在六合的“助合”（辰酉、寅亥、午未）中，主生一方与被生一方的力量各自如何变化？","opts":["双方互相消耗，最终两败俱伤皆失去作用","生者力量不变，被生者因受生反而变懒不愿做功","生者与被生者同时增强，双方都能加倍做功","被生者逢助，生者泄力而作用减弱"],"ans":3,"exp":"助合指一支生另一支：被生者逢助，生者泄力、作用减弱（如辰酉合辰生酉则辰减力）。","sec":"二、六合的四种作用","t":"rule"},{"q":"地支六合中“闭气”的四组（子丑、辰酉、午未、卯戌），分别关闭了库中什么五行之气？","opts":["子丑闭金、辰酉闭水、午未闭木、卯戌闭火","子丑闭土、辰酉闭金、午未闭火、卯戌闭木","子丑闭金、辰酉闭火、午未闭水、卯戌闭木","子丑闭水、辰酉闭木、午未闭火、卯戌闭金"],"ans":0,"exp":"闭气使库中遁藏不流通：子丑闭丑中金、辰酉闭辰中水、午未闭未中木、卯戌闭戌中火。","sec":"二、六合的四种作用","t":"calc"},{"q":"在六合的“合伤”作用中，除辰酉合克伤辰中乙木外，还有哪两组六合也克伤了地支遁藏之气？","opts":["卯戌合与午未合，皆克伤所藏乙木","寅亥合与巳申合，皆克伤所藏丙火","寅亥合与子丑合，皆克伤所藏戊土","子丑合与午未合，皆克伤所藏丁火"],"ans":1,"exp":"合伤涵盖三组：辰酉（辰中乙木被酉克伤）、寅亥（寅中丙火被亥中壬水克伤）、巳申（巳中丙火被申中壬水克伤）。","sec":"二、六合的四种作用","t":"calc"},{"q":"看配偶星时若正偏星同见，取用顺序是什么？若配偶星得正位，又该以什么为主来看？","opts":["先看年柱出现的财官，无年柱才看日支坐下的婚姻宫","官杀同见以力量旺者为主；得正位时则完全不看婚姻宫","先看正官正财，无正才看偏；若配偶星得正位则以婚姻宫看","男命先看偏财，女命先看七杀；得正位仍只看天干配偶星"],"ans":2,"exp":"看配偶星先看正官（正财），无正官才看七杀（偏财），同见以正官为主；但配偶星得正位，要以婚姻宫看。","sec":"1．合留（婚姻应期）","t":"step"},{"q":"用六合断婚姻应期的“合留”规律中，原局星宫有冲、以及原局不冲不合时，流年各如何应婚期？","opts":["无论原局有冲或无冲，一律须流年天干合日主才能成婚","原局有冲则流年穿之为应；不冲不合则流年冲之为应","原局有冲则流年再冲为应；不冲不合则流年刑之为应","原局有冲则流年合之为应；不冲不合则流年去合星宫为应"],"ans":3,"exp":"原局星宫有合，流年冲之为应；原局有冲，流年合之为应；原局不冲不合，流年去合星、宫为应。","sec":"1．合留（婚姻应期）","t":"rule"},{"q":"大运地支与原局地支六合时，视为紧邻相合，具体有哪两种常见结果？","opts":["原局之支被绊失其原性，或大运之字被原局合入、合留得到","大运之支被原局彻底克死，或原局之支化为大运五行","大运永远克制原局，原局绝不可能合入或合留大运之字","双方只生不克、合力翻倍，一律按大发横财论"],"ans":0,"exp":"大运合原局视为紧邻相合，分两种情况：八字中的支被绊失其原性；或大运中的字被八字合入、合留，被命主得到。","sec":"2．合绊","t":"rule"},{"q":"流年地支合正在行的大运地支时（引动大运），对大运中的墓库与根气有何影响？","opts":["能彻底冲开大运墓库，同时连大运之根一并铲断","只可能是动库而非开库；流年短，也不会坏大运之根","会把大运墓库永远闭死，导致整步大运十年全凶","使流年与大运互相合绊，大运从此不再发挥任何作用"],"ans":1,"exp":"流年合大运不是互绊而是合动大运；流年合大运只可能是动库（开始发挥作用）而非开库，且流年短，不会坏大运之根。","sec":"2．合绊","t":"diff"},{"q":"男命日支亥水妻星得正位，月令寅木（上透正印）与之成寅亥合绊，通常在婚姻与事业上应什么？","opts":["亥水生旺寅木反克妻星，主克妻但自己在单位掌大权","印星化官生身主升官发财，妻子贤惠助夫步步高升","妻星失性头婚必离，且寅印工作被合绊而无官丢工作","只主工作调动换单位，对夫妻婚姻感情没有任何影响"],"ans":2,"exp":"亥为妻星得正位被寅合则失妻星之性，头婚必离；寅为印代表工作，寅被亥合绊失其原性，故无官、失去工作。","sec":"2．合绊","t":"xiang"},{"q":"男命原局巳为功神，日支戌土妻宫能墓巳为忌；走乙卯运卯合绊闭戌库，为何发财同时又因妻破财？","opts":["戌土反克卯木失去财源，因投资房产失败而被迫卖房","卯戌合化火生助日主，发财后因丈夫外遇而赔偿离婚","卯木生旺巳火导致火旺克金破财，妻子则因得禄而平安","卯闭戌库护巳故发财，但戌为妻宫被劫财卯合绊故妻病花钱"],"ans":3,"exp":"卯合绊戌且闭戌库，戌不能墓巳故吉而发财；但戌是妻星居妻宫得正位，被劫财卯合绊，故妻有病花钱。","sec":"2．合绊","t":"xiang"},{"q":"关于“寅亥合”对寅木与亥水各自的具体作用，下列哪一项表述准确？","opts":["亥中壬灭寅中丙，亥水被吸纳弱化，寅木被生却被绊","寅中丙火蒸干亥中壬水，亥水被制死，寅木趁势大旺生火","寅木克制亥水使其闭库，亥中甲木受损而丙火丝毫无损","寅亥合化木成功，亥水彻底消失，寅木力量翻倍生发"],"ans":0,"exp":"寅亥合时，亥中壬水灭寅中丙火；亥水被吸纳失去原性、弱化或合去；水生木，寅木虽被生却被绊，不能发挥作用。","sec":"寅亥合","t":"calc"},{"q":"女命日支寅木夫宫紧合年月时两亥，是否必然断为两次婚姻？","opts":["亥为驿马，两亥合寅主夫妻长期两地分居但不会离婚","两亥不为两次婚姻，可换象为同一夫星跑到夫宫里","凡是两支合夫宫一律主两婚，绝无可能只结一次婚","两亥相争会导致克死第一任丈夫，中年必须再嫁他人"],"ans":1,"exp":"日支寅与两亥合，两亥不为两次婚姻，可换象为同一个人——两亥紧合到夫宫，是夫星跑到寅木夫宫里来。","sec":"寅亥合","t":"diff"},{"q":"什么配置称为“财统官”结构？在这种结构中如何看财的大小？","opts":["必须日干合住七杀且无财星，才能把七杀统作偏财","原局官杀弱而财星极旺，把财当官看，财大官大","原局财弱而官杀多且旺，把官杀当财看，杀大财大","财星与官杀力量相等并透天干，财官各自独立互不统属"],"ans":2,"exp":"原局财弱而官杀多且旺，属“财统官”结构，把官杀当财看，有多少官杀就有多少财，杀大财大。","sec":"寅亥合","t":"rule"},{"q":"原局坐寅印且官坐巳禄，走丁亥大运成寅亥合，为何既得部分权力又夫妻闹僵、寒气攻身？","opts":["寅亥合闭了巳火之库，使日主失去所有工作只能回家务农","大运丁亥与原局反吟，无论原局好坏一概按大凶灾难断","丁火劫财透干夺走妻子，亥水冲克巳禄导致彻底罢官免职","大运合八字有两重性：得亥杀权力的同时绊住寅并灭寅中丙火"],"ans":3,"exp":"大运合八字有两重性：使日主得到亥（权力），同时绊住寅、灭掉寅中丙火，寅被湿不生火而寒气攻身、夫妻闹僵。","sec":"寅亥合","t":"xiang"},{"q":"在分析原局功神与大运流年的关系时，哪些作用方式被视为“坏了功神”？","opts":["合、冲、穿皆是坏，功神被坏则凶","只有流年能坏功神，大运不会破坏原局的功神","只有冲和穿是坏，大运流年来合功神一律主吉","只有相穿是坏，相冲反而能冲旺功神使其更好做功"],"ans":0,"exp":"局中功神不能被命局、大运、流年之字来坏（合、冲、穿皆是坏），坏则凶。","sec":"卯戌合","t":"rule"},{"q":"原局火燥土有势却无财可发，比肩戌土与时支卯木成卯戌合，常对应什么生活职业象？","opts":["卯为木器、戌为窑炉，必为古代陶瓷烧造手艺人","卯为庄稼、戌为土地，木土相合主种地农民之象","卯木克戌土主土木工程，必为大型房地产开发商","卯戌合闭火库主文化教育，必为大学哲学系教授"],"ans":1,"exp":"卯戌合在无财可发的比肩做功局中，是木土相合，卯为庄稼，戌为土地，主辛苦劳碌的种地农民之象。","sec":"卯戌合","t":"xiang"},{"q":"甲辰柱在命局中遇到酉金成辰酉合时，对天干甲木会产生什么致命影响？","opts":["辰土生旺酉金反生甲木，使甲木根深蒂固转为参天大树","辰酉合只闭水库不伤木根，甲木依然可借辰中乙木盘根","酉金铲断辰中乙木之根，使甲木无根不受水生","酉金劈甲引丁，使甲木化为木火通明之象而主大贵"],"ans":2,"exp":"辰酉合不仅闭辰水库，还会由酉金铲断辰中乙木根；甲辰遇酉，木根被断，甲木无根不受水生。","sec":"辰酉合","t":"calc"},{"q":"“巳申合”在单独相见与在局中有气势时，作用结果有何不同？","opts":["无论单独或有势，巳申合永远只是合绊而不能互相制去","单独相见巳火必克死申金，局中有势则申金必反制巳火","单独相见化水大吉，局中有势反而两败俱伤不能做功","单独相见两神俱坏，局中有势则力量大者制小者"],"ans":3,"exp":"巳申单独相见，巳克申而申中壬水又克巳，两神俱坏；局中有势则谁强谁制谁，是六合中做功效率最高的。","sec":"巳申合","t":"diff"},{"q":"火燥土成势，日坐巳财合制年上申印（含壬水劫财），为何能通过非常手段发超级风险财？","opts":["申中劫财与印可换象当财看，制别人之财为自己所用","巳申合直接化为水财，源源不断生助日主成为普通实业家","印星主官方牌照，巳合申主考取公务员掌管国库资金","申金代表固定房产，巳火烧旺申金主拆迁获得巨额补偿"],"ans":0,"exp":"巳申合制住申金（印与劫财），劫财、印可换象当财看，是非劳动所得、非常手段取财，主风险财、超级财。","sec":"巳申合","t":"xiang"},{"q":"局中印星被地支相穿（如寅穿巳印）时，何时断此人心性不好，何时不忌？","opts":["印在宾位被穿主心性不好，印在主位被穿则主身体多病","印为功神被穿主心性不好，印为闲神则不忌","只要印星被穿无论功神闲神，一律断为此人品行极端恶劣","正印被穿主心性不好，偏印被穿则反而主聪明机智"],"ans":1,"exp":"印为功神被穿，主心性有问题、不好；若印为闲神则不忌。","sec":"巳申合","t":"diff"},{"q":"在六合之中，“午未合”为何被称为最差的合、没有大的意义？","opts":["午未合必然引发日支婚姻宫自刑，主一生婚姻破裂多次","午未合能量太强会冲散其他所有合局，使八字无法成格","火土都没被坏，合在一起还是火土，只增火力并闭木库","午火会彻底烧干未中燥土，导致全局变成一片焦土无生机"],"ans":2,"exp":"午未合最差，没有大的意义：火土都没有被坏，合在一起还是火土，只是发生亲近关系，增加火势并闭木库。","sec":"午未合","t":"diff"},{"q":"“子丑合”时，五行气势流向哪一方？若想让丑库发挥作用，必须冲哪一个地支？","opts":["丑往子流，想开库既可冲丑也可冲子，效果完全一样","双方静止不动互不流通，只有用辰戌相冲才能引动子丑","子往丑流，想开库必须用午火冲子水才能彻底打开丑库","子往丑流，想开库须冲丑（冲子只是不合丑）"],"ans":3,"exp":"子丑合方向是子往丑流，有点土克水之意；想开库必须冲丑，冲子只是不合丑而已。","sec":"子丑合","t":"step"},{"q":"女命乙木日主坐丑土，年支子水印星与日支丑土隔一位成子丑合，通常在事业上代表什么？","opts":["隔一位合意为得到，丑旺得子印则主得到权力","子水把丑土合走，主日主放弃公职辞职远赴海外","子丑合闭了财库，主一辈子只能给别人打工勉强糊口","隔一位合根本不成立，子水漂泊在外一生无权无职"],"ans":0,"exp":"子丑合隔一位意为得到，子水在外漂被丑土得到，丑旺则论吉；子为印主权力，故主得到权力。","sec":"子丑合","t":"xiang"}]},{"n":10,"level":"初级","title":"合（三）三合局与暗合","qs":[{"q":"亥、卯、未三字会聚成局，是什么局？中神是哪个字？","opts":["木局，中神未","水局，中神卯","木局，中神卯","木局，中神亥"],"ans":2,"exp":"亥卯未合木局，子午卯酉为中神，所以中神是卯；亥、未是佐神。","sec":"一、三合局总论","t":"calc"},{"q":"在天干五合、地支六合、三合等合法中，能「合化」成另一五行的是哪种？","opts":["只有六合能合化","六合和三合局都能合化","天干五合与三合局都能合化","只有三合局能合化"],"ans":3,"exp":"三合局是所有合法里唯一能合化的；六合讲紧密，不讲合成了什么。","sec":"一、三合局总论","t":"diff"},{"q":"三合局成不成局，同五行在天干透不透有关系吗？成局的必要条件是什么？","opts":["无关；三个字必须齐现，中神最重要","必须中神透出天干，其他两字可缺一","必须同五行透出天干才成局","无关；只要两个字就能成三合局"],"ans":0,"exp":"成局与天干透不透无关，必须三字齐现，其中中神位置最关键。","sec":"一、三合局总论","t":"rule"},{"q":"寅午戌合成火局后，寅木与戌土的力量各有什么变化？","opts":["寅木增力旺，戌土被火克而弱","寅木泄力从火势，戌土被生而增强","寅木被火克而弱，戌土被火泄而弱","寅木与戌土都被火泄，失去本性"],"ans":1,"exp":"寅木生火泄力、从了火势；戌被局中旺火所生，越生越旺。","sec":"二、三合局中各神的力量变化","t":"calc"},{"q":"卯、未两字同现，属于哪一类合？","opts":["三合木局","生地半合木局（长生+帝旺）","墓地半合木局（帝旺+墓库）","拱局（长生+墓库）"],"ans":2,"exp":"生地半合是长生+帝旺（亥卯）；墓地半合是帝旺+墓库（卯未）；拱局是长生+墓库（亥未）。","sec":"三、半合局与拱局","t":"calc"},{"q":"拱局（如亥未、寅戌、巳丑、申辰）与半合局的区别是什么？","opts":["拱局的成局力量比三合局还大","拱局有中神，半合局没有","拱局必须天干透出才算","拱局没有中神，只是虚拱着中神"],"ans":3,"exp":"拱局是长生+墓库、无中神，虚拱中神；半合局含帝旺中神。","sec":"三、半合局与拱局","t":"diff"},{"q":"三合局中若中神与他支有六合关系，怎么论？","opts":["六合更紧密，先论六合，剩下的支论半三合","三合更紧密，六合不论","中神被合绊，整个三合局作废并换象","三合与六合同时成立，不分先后"],"ans":0,"exp":"六合能解三合；长生支或墓支有六合，也是先论六合，剩余字论半三合。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"亥卯未三合木局中，杂有紧贴的酉冲卯，局怎样？","opts":["卯未仍成半合木局","三合木局完全不成","亥未仍成半合木局","木局力量略减但仍成"],"ans":1,"exp":"酉冲中神卯则三合完全不成；巳冲亥则卯未半合仍成；丑冲未则亥卯半合仍成。","sec":"四、三合局的用法与注意事项","t":"calc"},{"q":"寅午戌三合中，午火中神在盘中出现两次，怎么论？","opts":["按中神双现合绊论","仍成三合局，火力加倍","不成三合局，以中神入墓论","成半合局，不入墓"],"ans":2,"exp":"中神双现或多现，不成三合局，以中神入墓论。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"「相穿」与「刑、冲」在开墓库上的区别是什么？","opts":["穿能开墓，刑冲只会破墓","只有冲能开墓，刑穿都不能","穿、刑、冲都能开墓","相穿不能开墓，只有刑、冲才能开墓"],"ans":3,"exp":"提示：穿只是坏，不能开库；墓库须刑或冲才开。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"下列哪一组是盲派所说的暗合（有别于六合）？","opts":["午亥暗合","寅亥相合","巳申相合","卯戌相合"],"ans":0,"exp":"暗合只有寅丑、午亥、卯申三组；寅亥、卯戌、巳申都是六合。","sec":"五、暗合","t":"diff"},{"q":"暗合与六合在「合绊」上的论法区别是什么？","opts":["暗合与六合一样，合了就被绊住","暗合不论合绊只论相制；流年合旺支才算合动","暗合一律为合绊，大运流年合也是绊","暗合与六合都只论相制，不论合动"],"ans":1,"exp":"原局紧邻暗合与大运暗合命局不论合绊，只论相制做功；流年合原局和大运旺支则合动应事。","sec":"五、暗合","t":"diff"}],"fine":[{"q":"三合局在盲派中被称为“党局”，其内部由五行的哪三种状态组成，核心是什么？","opts":["长生、沐浴、冠带三者聚而成局，长生为主导核心","临官、帝旺、衰地三者聚而成局，墓库为最高统帅","长生、帝旺、墓库三者聚而成局，中神如党魁纲领","胎、养、长生三者聚而成局，三支力量完全平等"],"ans":2,"exp":"三合局由长生、帝旺、墓库三者聚而成局，类似结党称“党局”；中神（子午卯酉）如党魁纲领，其余两神是佐神。","sec":"一、三合局总论","t":"rule"},{"q":"三合局成局之后，局中各神是否像六合那样被“合绊”而失去自由？","opts":["只有中神失去自由被佐神绊住，其余两神仍可自由作用","只有长生支保持自由，帝旺中神与墓库均被彻底合绊","与六合完全相同，一旦成局三支全被死死绊住不动","不为合绊，各神仍有一定自由度，还能去作用他神"],"ans":3,"exp":"三合局不为合绊：局中每个神都有一定自由度，还可以去作用其他神，只是因为合局一心向“党”，力量会起变化。","sec":"一、三合局总论","t":"diff"},{"q":"比较六合、三合局与暗合三者的紧密程度，从强到弱排序正确的是哪一项？","opts":["六合最紧密，暗合次之，三合局紧密性较差","三合局最紧密，六合次之，暗合紧密性最差","六合与三合局紧密性完全相同，暗合最松散","暗合最紧密，六合次之，三合局紧密性最差"],"ans":0,"exp":"六合是八字中最紧密的合，故六合能解三合；暗合近似六合，紧密度不如六合、但比三合强。","sec":"一、三合局总论","t":"diff"},{"q":"申子辰三合水局成立后，局中的辰土与申金各自发生什么变化？","opts":["辰土被申金生助而更旺；申金因合局而完全不泄力","辰无原神生则失土性被水荡；申被水泄减力但不变性","辰土与申金双双化为纯粹之水，原来的金土性质全灭","辰土克水反而增力变强；申金被子水冲破彻底失效"],"ans":1,"exp":"申子辰水局：辰本身土力弱，合局更弱，无原神生则失土性且被水荡；申金被水泄，力量减弱但不变性；子水大增力。","sec":"二、三合局中各神的力量变化","t":"calc"},{"q":"亥卯未三合木局成立后，未土变弱的真正原因是什么？亥水又有何变化？","opts":["未土反克亥水使水局破裂；亥水得未土帮扶而变得更旺","未土力量丝毫不减反成强根；亥水入未墓被彻底闭死","未为木库属弱化或自动放弃，非单纯被克；亥水被泄减力","未土被亥卯联手克死，彻底化为腐木；亥水生旺木而增力"],"ans":2,"exp":"亥卯未木局：未为木库，被三合局弱化（这种力量不是克，是弱化或自动放弃）；亥水生卯木，亥水减力（被泄）。","sec":"二、三合局中各神的力量变化","t":"calc"},{"q":"巳酉丑三合金局中，十二地支中唯一的“变色龙”是哪一字？丑土又有何变化？","opts":["丑土是变色龙，随时变成燥土克金；巳火克酉而力量大增","酉金是变色龙，随火势强弱而化火；丑土得巳生而更旺","巳火依然保持火性克金；丑土吸纳酉金使金局无法成立","巳火是变色龙，在此放弃立场从金；丑土生酉而更弱"],"ans":3,"exp":"巳是十二支中唯一的“变色龙”，五行性质随水火强弱变化，在巳酉丑金局中放弃自己立场；丑土生酉金而更弱。","sec":"二、三合局中各神的力量变化","t":"calc"},{"q":"半合局（如亥卯、卯未）成局之后，其中两个地支的力量变化与完整三合局相比如何？","opts":["半合局成局力量小于三合局，故两字的力量变化不大","半合局会把墓库字彻底化掉，力量变化远超完整三合局","半合局只有两字更精纯，力量变化比完整三合局还要大","半合局中两字力量完全不变，只有三合局才产生力量变化"],"ans":0,"exp":"半合局成局力量小于三合局，所以其中两字的力量变化不大。","sec":"二、三合局中各神的力量变化","t":"diff"},{"q":"原局有辰为财库却不开、不能为日主所用，大运若见申金成“申辰拱局”，会产生什么效果？","opts":["申金克断辰中乙木之根，导致原局财库瞬间破产","申辰虚拱子水，能拱出原局辰中之财为我所用","申辰相拱会把辰库彻底闭死，使财星永远无法流出","拱局无中神完全无效，大运见申对辰库没有任何作用"],"ans":1,"exp":"拱局没有中神，其余两神“虚拱”中神；原局辰财库不开，大运见申，申辰相拱就能拱出辰中之财为我所用。","sec":"三、半合局与拱局","t":"xiang"},{"q":"在巳酉丑三合组合中，酉与丑两字同时具有哪双重性？巳与丑又构成什么？","opts":["酉丑纯粹是金局旺地；巳丑为天地自合关系","酉丑纯粹是墓地闭气；巳丑为互穿破坏关系","酉丑以拱为主、以墓金为辅；巳丑为拱局","酉丑以墓金为主、以拱为辅；巳丑为生地半合"],"ans":2,"exp":"巳酉丑中，酉丑具有双重性：以拱为主，以墓金为辅；巳丑（长生+墓库）为拱局。","sec":"三、半合局与拱局","t":"diff"},{"q":"三合局或拱局中，中神落在“主位”与落在“宾位”时，吉凶层次有何不同？","opts":["落宾位临吉神他星拱之主大吉；落主位被拱反主辛劳破财","中神只能落在月令才有效，落在日支或时支一概不论吉","只要三合局成立，中神落在主位还是宾位吉凶完全一样","落主位临吉神他星拱之主大吉；落宾位被生拱仅主次吉"],"ans":3,"exp":"中神位置十分重要：中神落在主位临吉神、他星拱之，主大吉；落在宾位被生拱，即使是吉神，也只是次吉。","sec":"四、三合局的用法与注意事项","t":"diff"},{"q":"亥卯未三合木局中，若紧贴遇到“巳冲亥”，或遇到“丑冲未”，三合与半合分别如何？","opts":["巳冲亥则卯未半合仍成；丑冲未则亥卯半合仍成","只要逢冲无论冲哪一字，三合与半合全部彻底破坏不成","巳冲亥则三合木局依然成立；丑冲未则木局完全破散","巳冲亥则亥卯半合仍成；丑冲未则卯未半合仍成"],"ans":0,"exp":"亥卯未木局中，酉冲中神卯则三合完全不成；巳冲亥则三合不成但卯未半合仍成；丑冲未则亥卯半合仍成立。","sec":"四、三合局的用法与注意事项","t":"calc"},{"q":"大运地支来冲原局三合局的“中神”时，对原局三合局会造成什么后果？","opts":["只要佐神未被冲破，大运冲中神对三合局毫无影响","中神最重要，大运冲中神则此三合局被坏","冲中神只是把中神冲动，反而使三合局做功更加有力","流年冲中神才会坏局，大运冲中神反而能合化成功"],"ans":1,"exp":"三合局的中神最重要，冲中神则破合，大运来冲三合局的中神，则此局被坏。","sec":"四、三合局的用法与注意事项","t":"rule"},{"q":"坤造日支亥水与两未土相拱（亥未拱卯禄），原局并无卯木明现，为何反而主未财很大？","opts":["两未土直接克制亥水夫宫，把夫宫变成大财库而发财","原局无卯木代表没有比劫争财，所以日主独吞全部家产","原局无卯木存在，未土弱化程度低，两处财往夫宫拱故财大","未土在原局逢空亡，虚拱之禄反而能把空亡财星填实"],"ans":2,"exp":"亥未拱禄（卯）似无实有，因原局没有卯木存在，未土弱化程度低，两处未财往里拱，财就大。","sec":"中神的用法","t":"xiang"},{"q":"坤造三合局将辛官合入夫宫卯，戊戌运癸酉年戌合夫宫、酉冲夫宫，为何该年结婚？","opts":["戌土大运冲开年支亥水库，使辛金官星彻底失去控制","癸水正印虚透天干代表离婚证，冲夫宫主先同居后分手","酉金直接冲克日主禄神破身，只要破身无论有无合都结婚","夫宫在原局与大运中被合，合以冲为应期，酉冲动夫宫而婚"],"ans":3,"exp":"女命夫宫卯在原局合局、大运戌又合之，合以冲为应期；流年酉冲夫宫且酉为辛官之禄（酉到即辛到），故结婚。","sec":"婚姻应期中的用法","t":"step"},{"q":"男命无财以食神当财，两午入戌墓不开，行酉运酉戌穿又逢癸酉年为何因贪财坐牢？","opts":["酉戌穿坏食神主失自由入狱，戌为牢狱象且因财致祸","癸水财星透干克死午火，日主身弱不胜财而犯经济罪","戌土财库被酉金冲开，发财太多遭人嫉妒陷害而入狱","酉金冲克午火印星导致丢官罢职，因工作失误被判刑"],"ans":0,"exp":"酉当财看，酉戌穿坏食神（食神主自由，坏则失去自由入狱），戌又为牢狱之象；此例戌穿酉“财”是犯财，因贪财坐牢。","sec":"中神双现不成局","t":"xiang"},{"q":"盲派关于日主禄神（如时上禄神）遭遇“冲”与“穿”的吉凶对比，哪项准确？","opts":["禄无论是被冲还是被穿，一律主当年损寿且破尽家财","禄不怕冲（时禄有时可冲），最怕被穿（穿了寿有问题）","时上的禄只怕天干合克，地支的冲和穿都不会影响寿命","禄最怕被冲（冲禄必死无疑），完全不怕他支来穿"],"ans":1,"exp":"提示：禄不怕冲，最怕被穿；时上的禄有时可以冲，但不可以穿，穿了寿有问题。","sec":"中神双现不成局","t":"diff"},{"q":"水有流动特性：年支见辰墓、月日时见子水，与时支见辰墓、年月日见子水，两者象义有何区别？","opts":["年见辰是子水全部入年墓闭死；时见辰是子水从时墓流出","无论辰在年支还是时支，子水都只出不入、永远不入墓","年见辰是子从年墓流出；时见辰是子水都入了时支的墓","只有月支见辰才能墓子水，年支和时支的辰都不能墓子"],"ans":2,"exp":"年支见辰墓，月日时见子水，则子是从年上墓中出来的（但辰能墓水的象仍在）；时上见辰墓，年月日见子水，则子水都入了时支墓。","sec":"中神双现不成局","t":"diff"},{"q":"与辰墓见子水的“流动特性”相比，未墓见寅卯、戌墓见巳午是否也有同样的流出或入墓特点？","opts":["只有火库戌见巳午有流动特性，木库未见寅卯没有此特点","木火土金四库都有完全相同的流动特性，无任何区别","有，火与木同样具有流动特性，年未时卯也算从年墓流出","没有，只有水有流动特性，未见寅卯、戌见巳午无此特点"],"ans":3,"exp":"水有流动特性，年辰见子为流出、时辰见子为入墓；其他如未见寅卯、戌见巳午，就没有这种特点。","sec":"中神双现不成局","t":"diff"},{"q":"下列关于三组暗合（寅丑、午亥、卯申）内部人元相合的对应，哪一项完全正确？","opts":["午亥暗合是午中丁、己分别合亥中壬、甲","午亥暗合是午中丙火合亥中辛金","寅丑暗合是寅中乙、丁分别合丑中庚、壬","卯申暗合是卯中甲木合申中己土"],"ans":0,"exp":"三组暗合：寅丑（寅中戊丙甲合丑中癸辛己）；午亥（午中丁己合亥中壬甲）；卯申（卯中乙合申中庚）。","sec":"五、暗合","t":"calc"},{"q":"暗合双方力量一强一弱时（如卯申暗合），在命局中如何发挥互制作用？","opts":["永远是阳支制阴支，申金必制去卯木、午火必制去亥水","谁得势谁制，卯旺可制去申，申旺也可制去卯","暗合双方只能互相生助，不能互相制去任何一方","永远是金克木、申制去卯，卯木绝不可能制去申金"],"ans":1,"exp":"暗合互制：相合双方一强一弱，谁得势谁制，如卯申暗合，卯旺可制去申，申旺也可制去卯。","sec":"五、暗合","t":"rule"},{"q":"在盲派取象中，暗合（特别是寅丑暗合）在人事与求财方面常代表什么含义？","opts":["一定代表破财被骗，无论强弱逢暗合必主官司败诉","一定代表公开竞标得财，绝不表示任何暗中交易","有时表示暗中操作之事，如寅丑暗合容易得暗财","只表示夫妻感情恩爱，与求财和做事方式毫无关系"],"ans":2,"exp":"暗合有时表示暗中操作的事情（有时不一定），也可换象；如寅丑暗合容易得暗财，统领。","sec":"五、暗合","t":"xiang"},{"q":"原局地支本在制亥水，若原局天干透壬水无制，或大运出现丁壬合时，为何反而凶？","opts":["天干壬水与地支亥水完全无关，凶因只是大运冲了年支","原局亥水最喜大运合住，大运丁壬合吉，只是流年冲破才凶","大运丁壬合化木生助七杀，使原局官杀过旺直接克死日主","地支要制之字忌原身透干无制，大运丁合壬是保护而非合去"],"ans":3,"exp":"原局在地支要制的字，不喜其原身或遁藏透干无制；原局戊克壬，大运丁合壬是保护壬水使其不受戊克，故反局。","sec":"五、暗合","t":"rule"},{"q":"命局中“合用的东西被穿”以及“穿倒正印（功神）”，在事业与品行上通常分别主什么？","opts":["合用被穿主做官不顺或入狱，穿倒正印主不走正路非法取财","两者皆只主身体皮肤小病，对事业与取财方式全无影响","合用被穿主升官发财，穿倒正印主读书极佳考取名校","合用被穿主夫妻恩爱，穿倒正印主弃商从政清廉奉公"],"ans":0,"exp":"合用的东西一定不能穿（如制卯官而卯被辰穿主做官不顺或入牢）；口诀：穿倒正印不走正路，主以阴暗手段取财。","sec":"五、暗合","t":"xiang"},{"q":"某男命以甲寅生丁火为两眼之象，局中先见寅丑暗合、再见寅亥合，怎么得出失明盲人的结论？","opts":["亥水直接冲灭丁火日主，寅木反而生旺亥水加剧克身","丁火为眼、寅为火源，暗合加六合灭尽寅中火源故失明","丁火坐下丑土直接克死丁火，与寅丑暗合、寅亥合无关","寅丑暗合化为辛金劈伤丁火，导致双目外伤而失明"],"ans":1,"exp":"丁火代表两眼，寅丑暗合把寅合到丑地使眼有问题，寅亥再合灭去寅中火，用的东西怕坏，火源彻底熄灭故成盲人。","sec":"五、暗合","t":"xiang"}]},{"n":11,"level":"初级","title":"刑、破、害、墓","qs":[{"q":"盲派论相刑，只认哪两组？","opts":["寅巳申、子卯刑","子卯刑、辰午酉亥自刑","丑戌未、辰午酉亥自刑","寅巳申、丑戌未"],"ans":3,"exp":"只论寅巳申、丑戌未两组三刑；子卯在盲派是相破，自刑弃而不用。","sec":"一、相刑：寅巳申与丑戌未","t":"rule"},{"q":"寅巳申三字，拆开来按什么论？","opts":["寅巳论穿，巳申论合，寅申论冲","寅巳论合，巳申论穿，寅申论冲","寅巳论冲，巳申论穿，寅申论合","寅巳论穿，巳申论冲，寅申论合"],"ans":0,"exp":"口诀：寅巳带穿，巳申带合，寅申带冲，全见时才论三刑，刑只是附带作用。","sec":"一、相刑：寅巳申与丑戌未","t":"diff"},{"q":"局中金水旺，出现丑与戌相刑，谁刑谁、坏的是什么？","opts":["丑刑戌，坏戌中之金","丑刑戌，坏戌中之火","戌刑丑，坏丑中之土","戌刑丑，坏丑中之金水"],"ans":1,"exp":"丑戌刑：局中金水旺则丑刑戌，能坏戌中之火；局中木火旺则戌刑丑，能坏丑中之金水。","sec":"一、相刑：寅巳申与丑戌未","t":"calc"},{"q":"未与戌相刑（燥土刑燥土），结果怎样？","opts":["火越刑越弱，土气转旺","金越刑越旺，火被制","火越刑越旺，戌中的金被制","火被刑去，戌中金得生"],"ans":2,"exp":"未戌刑把戌未中的火引出来，火越刑越旺，但戌中的金被刑坏、被制。","sec":"一、相刑：寅巳申与丑戌未","t":"rule"},{"q":"原局有丑未相冲在做功，大运来戌，一般怎么论？","opts":["戌来生助，做功更强","戌冲开库，做功得吉","丑未冲加戌，只论冲不变","凑成三刑，原局做功被坏"],"ans":3,"exp":"原来的刑冲做功为吉，第三者来介入构成三刑，三字皆坏，功就没有了；原局丑戌刑做功则怕未来。","sec":"一、相刑：寅巳申与丑戌未","t":"calc"},{"q":"丑戌未之间的刑，近刑和远刑的作用分别是什么？","opts":["近刑坏库中遁藏，远刑开库","近刑开库，远刑坏库中遁藏","近刑远刑都是开库","近刑远刑都只坏库不开库"],"ans":0,"exp":"丑戌未是墓库，近刑刑坏墓库中的遁藏，远刑则能开库，库中之物得以为用。","sec":"一、相刑：寅巳申与丑戌未","t":"diff"},{"q":"子、卯、午、酉中，哪一对不属于相破？","opts":["午与酉","子与酉","子与卯","卯与午"],"ans":1,"exp":"相破只有子卯、卯午、午酉三组，子与酉之间没有相破。","sec":"三、相破：子卯、卯午、午酉","t":"calc"},{"q":"相破与做功是什么关系？","opts":["破只表象，三组破都不做功","破是做功的一种，破即是制","破只表象不做功，午酉破例外有制意","破可做功，子卯破例外有制意"],"ans":2,"exp":"破是象不是做功；唯午酉破因午旺能克酉，有制的意思，也做功。","sec":"三、相破：子卯、卯午、午酉","t":"rule"},{"q":"财星在局中见破，主什么？","opts":["冲动得财","发财","合财","破财"],"ans":3,"exp":"破的含义是无情、破坏、破耗财产，财星有破就是破财。","sec":"三、相破：子卯、卯午、午酉","t":"rule"},{"q":"局中有申，又见丑，通常怎么论？","opts":["申为长生，见丑必入墓","申入未墓，丑与申无关","申酉丑三合，只论合局","申丑相冲，不入墓"],"ans":0,"exp":"寅申巳亥长生见各自墓库必入：寅入未、申入丑、巳入戌、亥入辰。","sec":"五、墓库的原则","t":"calc"},{"q":"辛丑一柱，辛是否算入墓？","opts":["算，辛见丑必入墓","不算，天干坐墓不为入墓","算，金入丑墓力度最大","不算，但要冲开丑才行"],"ans":1,"exp":"天干坐墓，如辛丑、壬辰，天干得强根不是入墓；日主坐墓也不为入墓。","sec":"五、墓库的原则","t":"calc"},{"q":"酉见丑，什么情况才算入墓？","opts":["只要酉丑同现，一律当半合局","只要见丑，必入墓","中神双现，或单见又特别弱","酉旺时见丑才入墓"],"ans":2,"exp":"子午卯酉四正见其墓当半合局看，不为入墓；只有中神双现，或单见又特别弱时才入。","sec":"五、墓库的原则","t":"diff"}],"fine":[{"q":"对于传统命理中的「子卯刑」与「辰午酉亥自刑」，盲派分别持什么态度？","opts":["子卯与自刑都按六冲的规则同等论断","子卯论三刑，自刑只在见全两个时才用","子卯弃而不用，辰午酉亥自刑专门主牢狱","子卯实为相破，自刑少应验弃而不用"],"ans":3,"exp":"盲派只论寅巳申、丑戌未两组三刑；其他书说的子卯刑实为相破；辰午酉亥自刑少有应验，弃而不用。","sec":"（一）哪些算刑","t":"rule"},{"q":"盲派论丑戌未、寅巳申三刑（尤其丑戌未），其吉凶含义与传统理解有何不同？","opts":["不主刑罚罪恶，全见有责难损坏之意多应六亲","与六合作用相同，主贵人相助、家庭和睦","专门主富贵荣华、大权在握与长寿","专门主刑事犯罪、坐牢与官非诉讼"],"ans":0,"exp":"三刑并不表示刑罚、刑法、罪恶或疾病；三刑见全有责难、受过、废弃、损坏之意，多应在六亲伤病早亡。","sec":"（一）哪些算刑","t":"diff"},{"q":"拆解寅巳申三刑中的「寅巳」关系时，寅去刑巳与巳去刑寅分别表示什么？","opts":["寅刑巳主寅木遭难，巳刑寅主火势大旺","寅刑巳以木动火，巳刑寅则寅动而泄遭难","寅刑巳以木克火，巳刑寅则水木相生为吉","不论谁刑谁，寅巳紧邻一律只论开库"],"ans":1,"exp":"寅刑巳是以木动火，火喜旺则吉、忌旺则凶；巳刑寅则寅动而泄，主寅所代表的事物遭难（若寅为忌神反吉）。","sec":"（二）三刑可以拆开来解","t":"diff"},{"q":"当命局中木火力量旺时，出现丑与戌相刑，谁刑谁、坏的是什么？","opts":["丑刑戌，能坏戌中之火","丑戌互相刑伤，两库中物皆得生","戌刑丑，能坏丑中之金水","戌刑丑，能坏丑中之木火"],"ans":2,"exp":"丑戌刑要看局中气势：木火旺则戌刑丑，坏丑中金水；金水旺则丑刑戌，坏戌中之火。","sec":"（二）三刑可以拆开来解","t":"calc"},{"q":"原局已有「戌刑丑」做功，若大运再见到「未」，对原局做功有什么影响？","opts":["大运未土只与丑相冲，与原局戌土毫不相干","未刑戌引出火气，丑中之金水瞬间被制净","未冲丑助戌，戌制丑的做功力量翻倍","未刑戌使戌力减弱，戌就制不了丑"],"ans":3,"exp":"原局戌刑丑做功，大运若再见未，未刑戌使戌的力量减弱，戌就制不了丑，原局做功被破坏。","sec":"（二）三刑可以拆开来解","t":"calc"},{"q":"丑戌未三刑在原局「三者全现」时，在六亲与做功上有什么总体规律？","opts":["不叫做功而是三字皆坏，弱的一方受伤最重","三者之中墓库越旺，其对应六亲越早夭折","只伤日主本人，完全不影响父母与子女六亲","构成三刑大做功，最旺的一方必然彻底损坏"],"ans":0,"exp":"三刑见全不叫做功，是三个字都坏了；多主六亲伤病残疾，相对弱的一方受伤最重，墓中六亲往往突然死亡。","sec":"（三）刑与墓库","t":"rule"},{"q":"判断三刑是否应验「伤六亲」，在四柱排列位置上有什么限制条件？","opts":["三刑必须隔位遥刑才伤六亲，紧邻反主吉","三刑要紧邻才应验，相隔较远则分论冲刑","必须天干透出三个比劫，地支三刑才伤六亲","只要地支出现任意两个，不论远近皆伤六亲"],"ans":1,"exp":"三刑要紧邻才应验“伤六亲”，如果相隔较远，则丑未论冲、丑戌论刑，伤害程度减轻。","sec":"（三）刑与墓库","t":"rule"},{"q":"在墓库与六亲类象中，墓中六亲被坏的死亡特征以及兄弟宫阴阳干支的区分是什么？","opts":["墓中六亲多长寿，只有开库流年才会生病","墓中六亲多缠绵病榻多年，兄弟宫占阳主妹","墓中六亲多突然死亡，兄弟宫占阳主哥占阴主妹","墓中六亲必主车祸，兄弟宫不论阴阳皆主兄"],"ans":2,"exp":"墓中六亲被坏，往往突然死亡（如心脏病、车祸等突发）；兄弟宫占阳主哥哥，占阴主妹妹。","sec":"（一）刑坏父星父宫","t":"xiang"},{"q":"原局意向要用刑冲制去某一个字（如戌未刑制丑财库）时，最忌讳出现什么情况？","opts":["最忌大运再见同五行之字，形成两冲一","最忌天干透出食神，食神泄气则库不能开","最忌它字来穿，相穿会把墓库彻底冲散","最忌它字来合（如子合丑），合则闭库反象"],"ans":3,"exp":"原局要制的字，最忌它字来合——合则闭库（如子丑合闭丑财库），与命局意向相反，象也坏了。","sec":"（二）刑到子女","t":"rule"},{"q":"关于「财官临库，不刑冲不发」，刑冲与发财发官之间是什么逻辑关系？","opts":["刑冲只是必要条件，发不发还要看具体结构","只有原局不带刑冲，财官库才容易发挥作用","刑冲专门用来发官，发财只能靠六合不能靠刑冲","刑冲是充分条件，只要见到刑冲必然大富贵"],"ans":0,"exp":"财官临库不刑冲不发，但刑冲只是发财官的必要条件，不是充分条件；如库被合闭，虽有刑冲仍不发。","sec":"（二）刑到子女","t":"rule"},{"q":"五行中子可生卯、卯可生午，为什么盲派反而把子卯、卯午定为「相破」？","opts":["子卯与卯午在十二地支中位置正对面相冲","四正神之间“相生的不情愿”，以相破为主","子水与卯木、卯木与午火藏干天干互相冲克","四正神全属阴支，阴阴相见必然互相克破"],"ans":1,"exp":"子水本可生卯、卯木本可生午，但四正神（子午卯酉）之间“相生的不情愿”，不生反破，以相破为主。","sec":"（一）破的性质","t":"rule"},{"q":"下列哪一组词语最准确地概括了盲派「相破」的核心类象？","opts":["收藏、控制、占有、得到、管理大企业","仇恨、侧面暗算、防不胜防、六亲早亡","无情、破坏、腐蚀、破耗、漏洞、有瑕疵","正面交战、冲走、冲动、开库引出为用"],"ans":2,"exp":"破的含义是：无情、破坏、腐蚀、废弃、破耗财产、漏洞、受伤、不舒服、不完整、有瑕疵。","sec":"（一）破的性质","t":"xiang"},{"q":"命局中出现比劫破到年支（如卯破午、午破卯在年上），在身体部位上常主什么？","opts":["年上主心脏，表示突发心脑血管疾病","年上主头部，表示偏头痛或眼目失明","年上主胃部，表示消化系统长期溃疡","年上主腿脚，表示腿脚残疾或有问题"],"ans":3,"exp":"年上主腿脚，比肩代表手足，比劫破到年上（如癸丙丙甲／卯辰午午、癸甲丙戊／卯寅午戌），多应腿脚残疾。","sec":"（二）相破命例","t":"xiang"},{"q":"原局门户（时柱）有财星，却被旁支「相破」（如卯破午财），在求财上易呈现什么象？","opts":["破表示零碎，大财变成零零碎碎的小钱","破财库开，突然暴富获得巨额偏财横财","财星被合，全部资金被官府或他人冻结","财星生官，顺利进入国有大企业担任主管"],"ans":0,"exp":"门户财被破，破表示零碎、不完整，原本可大可小的财成了零零碎碎的小钱（如一毛两毛的零钱）。","sec":"（二）相破命例","t":"xiang"},{"q":"在盲派地支作用体系中，传统所谓的十二支「相害」应当如何处理？","opts":["害专指天干克地支，与地支相穿完全无关","与相穿是同一回事，凡害皆按穿论","害比穿力量更弱，相当于轻微的相破","盲派弃用相害，认为相害在实际中毫无应验"],"ans":1,"exp":"十二支相害（子未、丑午、寅巳、卯辰、申亥、酉戌）与相穿是同一回事，凡“害”皆按“穿”论，不另立规则。","sec":"四、害","t":"rule"},{"q":"口诀「墓库喜刑冲，冲则为库，不冲则为墓」中，“墓”与“库”的状态区别是什么？","opts":["墓表示发大财，库表示坐牢失去自由","不冲为库、冲则为墓，一冲即散不能收藏","墓是死的，库是活的，库有时也表死亡应期","墓是活的，库是死的，只有墓才能收藏十神"],"ans":2,"exp":"墓库喜刑冲，冲则为库，不冲则为墓；墓是死的，库是活的；墓库有时还表示人的死亡（冲刑既是做功也是死期）。","sec":"（一）墓库是什么","t":"rule"},{"q":"按「长生入墓」原则，寅、申、巳、亥四大长生各自对应的墓库地支是哪一组？","opts":["寅入丑、申入未、巳入辰、亥入戌","寅入戌、申入辰、巳入未、亥入丑","寅入辰、申入戌、巳入丑、亥入未","寅入未、申入丑、巳入戌、亥入辰"],"ans":3,"exp":"四大长生见各自墓库必入：寅入未墓、申入丑墓、巳入戌墓、亥入辰墓。","sec":"（二）入墓的五条原则","t":"calc"},{"q":"年柱庚金虚透、时干有辛金，月支或日支为丑土，按「多而墓之」原则怎么论？","opts":["不论庚辛入丑墓，因没有连在一起","论庚辛全部入丑墓，因金有两个以上","构成巳酉丑三合金局，不作入墓论","仅时干辛金入丑墓，年干庚金不入"],"ans":0,"exp":"多而墓之要求局中同一五行天干地支连在一起有两个以上才入墓；年庚、时辛、月或日丑未连在一起，不论入墓。","sec":"（二）入墓的五条原则","t":"calc"},{"q":"局中出现「一申一酉」与「丑」时，是否入丑墓的关键区别在于什么？","opts":["申酉不相连见丑才入墓，相连反成半合","申酉相连见丑则入墓，不相连则酉不入","申旺酉弱时都入墓，酉旺申弱时都不入","无论是否相连，一申一酉见丑永远论三合"],"ans":1,"exp":"多而墓之：一申一酉相连见丑，也为入墓；若申酉不相连，则酉不入丑墓（仅申作为长生入丑墓）。","sec":"（二）入墓的五条原则","t":"diff"},{"q":"戊己土以地支戌为墓，但在什么条件下戊己土才会入戌墓？","opts":["只要命局同时见戊己与戌，戊己必定直接入墓","戊己必须坐在湿土辰丑之上，才会反入戌墓","戊己坐火时（如戊午、己巳）才与火同入戌墓","天干戊己土永远不会入任何地支墓库"],"ans":2,"exp":"戊己土不会直接入戌墓，只有其坐火时，才与火一起入戌墓，如戊午、己巳柱见戌，火与土同时入戌墓。","sec":"（二）入墓的五条原则","t":"rule"},{"q":"关于地支丑、未与辰墓的关系，原局「辰丑相见」而大运再见「未」时，怎么论入墓？","opts":["辰丑未三字凑齐，直接按丑戌未三刑论坏","只有大运未入辰墓，原局丑因见未而被冲出","丑未相冲，所以大运未和原局丑都不入辰墓","原局丑入辰墓，大运未也入原局辰墓"],"ans":3,"exp":"原局丑未同见因相冲不入辰墓；但若原局辰丑先见，丑入辰墓，大运再见未，此未也要入原局辰墓，不论冲。","sec":"（二）入墓的五条原则","t":"calc"},{"q":"命局中水土共见且遇辰时，普通水土组合与「癸丑」一柱遇辰有何不同？","opts":["水入辰墓而土不入；癸丑柱见辰则都入辰墓","土入辰墓而水不入；癸丑柱见辰则水土皆不入","水与土在任何情况下见到辰都同时入辰墓","癸丑柱见辰只论丑入辰墓，癸水仍留干透"],"ans":0,"exp":"局中水土共见遇辰，则水入辰墓、土不入；但若癸丑柱，癸顺了丑意当一家看，见辰则都入辰墓。","sec":"（二）入墓的五条原则","t":"diff"},{"q":"命局中需要入墓的字，如果左右两边都见到它的墓库（夹墓），应当如何论断？","opts":["两墓夹一字，该字必定加倍入墓且彻底死绝","夹墓不入，虽有墓而不墓","夹墓不入仅限于阳支，阴支夹墓照常入墓","左边入墓有效，右边之墓直接冲开左边之墓"],"ans":1,"exp":"夹墓不入：局中入墓的字，如两边见墓，该字被夹在中间，则虽有墓而不墓，与夹制无法制的道理相同。","sec":"（二）入墓的五条原则","t":"rule"},{"q":"除「财官临库，不刑冲不发」与「食伤入墓主坐牢」外，关于墓不开与禄入墓的口诀是什么？","opts":["墓不开，全废；禄入墓，主大富","墓不开，无象；禄入墓，必坐牢","墓不开，有象；禄入墓，做功小","墓不开，主寿长；禄入墓，做功大"],"ans":2,"exp":"墓库口诀：墓不开，有象（如丁丑带官帽，丑为庚墓，不开也有官象）；禄入墓，做功小。","sec":"（四）几条口诀","t":"rule"},{"q":"局中湿土辰丑成党，年支见巳火财星（无午火）时，湿土与巳火如何作用？","opts":["湿土直接把巳火穿倒，属于比劫制财做功","巳火入辰库闭而不开，财星彻底废掉无用","巳火把丑辰全部烤干，火土成势反制金水","巳生拱丑官泄净，成“财统官”结构"],"ans":3,"exp":"湿土旺时，巳火见丑不是被制，而是巳生拱丑官、被丑泄净，属“财统官”结构，官当财看；见午才丑午穿制火。","sec":"六、墓库命例","t":"calc"}]},{"n":12,"level":"初级","title":"冲、穿（一）相冲","qs":[{"q":"天干相冲的四组是哪些？戊己为什么不冲？","opts":["甲庚、乙辛、丙壬、丁癸；戊己居中宫无对立","甲庚、乙辛、丙壬、戊癸；戊己同属土","甲庚、乙辛、丙壬、丁癸；戊己力量太弱","甲戊、乙己、丙壬、丁癸；戊己居中宫"],"ans":0,"exp":"天干四冲是方向相对的甲庚、乙辛、丙壬、丁癸；戊己居中宫，没有方位上的对立，所以不冲。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"天干合处逢冲、冲处逢合，盲派一般看作什么的应期？","opts":["破财的应期","结婚的应期","离婚的应期","官司的应期"],"ans":1,"exp":"天干相冲的作用之一：合处逢冲、冲处逢合，一般是结婚的应期。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"地支六冲中，下列哪种说法符合既冲又克、一方有冲无克的规则？","opts":["卯木冲克酉金，酉对卯只冲不克","巳火冲克亥水，亥对巳只冲不克","亥水冲克巳火，巳对亥只冲不克","寅木冲克申金，申对寅只冲不克"],"ans":2,"exp":"子克午、酉克卯、申克寅、亥克巳：施克一方冲克对方，被冲方对它有冲无克。","sec":"一、天干四冲与地支六冲","t":"diff"},{"q":"辰戌冲、丑未冲，与子午冲这类冲相比，有什么不同？","opts":["必有一方被冲坏，另一方劳力","只冲库不冲藏干，库门洞开","双方土性相同，冲而不动","遁藏人元互相混战，土本气因冲变虚"],"ans":3,"exp":"辰戌、丑未是遁藏的人元互相混战，辰戌丑未这几个土的本气因冲而变虚。","sec":"一、天干四冲与地支六冲","t":"rule"},{"q":"地支排成子、午、丑，午夹在子丑之间，冲与合怎么论？","opts":["合必破，论冲不论合","子午冲被子丑合化解，论合不论冲","冲合兼论，子午冲与子丑合同时成立","贪合忘冲，论合不论冲"],"ans":0,"exp":"冲神夹在两合神中间，合必破，论冲不论合。","sec":"二、冲的四种作用","t":"calc"},{"q":"地支排成午、子、丑，冲神午在合神子丑之外且紧邻，冲与合怎么论？","opts":["合必破，论冲不论合","伤合，冲合兼论","贪合忘冲，论合不论冲","冲被合化解，两者皆不论"],"ans":1,"exp":"冲神在合神之外且紧邻是伤合，子午冲与子丑合同时成立；若隔开不紧邻则贪合忘冲，论合不论冲。","sec":"二、冲的四种作用","t":"calc"},{"q":"「旺神冲衰衰神拔，衰神冲旺旺神发」，后一句是什么意思？","opts":["旺者冲旺者，两败俱伤而空","衰弱者冲旺者，旺者被冲坏","衰弱者冲旺者，不伤旺者反把它冲起来","衰者冲旺者，旺者被冲走离开"],"ans":2,"exp":"失时衰弱者冲旺者，不仅伤不了旺者，反而把它冲起来，使之更旺；旺冲衰则衰者被拔除。","sec":"二、冲的四种作用","t":"rule"},{"q":"冲墓库时，近冲与隔冲、遥冲、运冲、岁冲有什么区别？","opts":["近冲开库引出为用；其余坏库中物","近冲坏库中物；运冲岁冲也坏库中物","近冲与其余都是开库，力度不同","近冲坏库中物；其余为开库引出为用"],"ans":3,"exp":"墓库相邻而冲，冲坏的是库里的遁藏之物；隔冲、遥冲、运冲、岁冲则为开库，库中之物得以引出为用。","sec":"二、冲的四种作用","t":"diff"},{"q":"原局出现夹冲（如两子夹冲一午），受冲的字会怎样？","opts":["不能被冲坏，像夹板走不了","被冲开库，库中物引出为用","被冲走离开，应期在运岁","必被冲坏，两冲一力量更强"],"ans":0,"exp":"原局的夹冲不能把受冲者冲坏或冲制：夹冲像夹板，被夹的走不了，既不会死也不会跑。","sec":"三、原局相冲的用法","t":"rule"},{"q":"盲派说冲的换象，条件和结果是什么？","opts":["两方势均力敌，各带对方性质","大的制去小的，小的带大的性质","小的冲倒大的，大的带小的性质","大的制去小的，小的性质不变"],"ans":1,"exp":"冲制时力量大的一方制去力量小的一方，被制的一方必带冲方的性质，如劫财被财制，当财看。","sec":"四、冲的换象","t":"rule"},{"q":"流年冲大运，正行天干运和正行地支运，结果有何不同？","opts":["天干运与地支运都是把大运冲走","天干运冲走运支；地支运提前引动","天干运提前引动运支；地支运冲走大运","天干运、地支运都是提前引动运支"],"ans":2,"exp":"正行天干运时，流年冲运支，运支被提前引动发生作用；正行地支运时，流年冲是冲去、冲走，反使大运不起作用。","sec":"五、大运、流年与冲","t":"diff"},{"q":"大运冲原局中相同的两个或三个字（如原局两寅逢申运），一般怎么论？","opts":["冲开库，库中物引出","合冲相抵，不起作用","冲坏，那个字被冲去","冲动，那个字发动起作用"],"ans":3,"exp":"大运冲原局相同的两个或三个字，一般是冲动（寅发动起作用），不是冲坏冲破。","sec":"五、大运、流年与冲","t":"rule"}],"fine":[{"q":"盲派论天干相冲的制伏效果，若要将对方制死制净，必须满足什么条件？","opts":["必须又合又克的时候才能制净","必须天干四冲同时出现两组","只要年干冲月干紧邻即可制净","只要主冲天干坐强根即可制净"],"ans":0,"exp":"天干相冲本质是相克，有制的意思，但单纯的天干冲制一般不能把对方制死制净，只有又合又克的时候才能制净。","sec":"（一）天干四冲","t":"rule"},{"q":"除了冲制做功和作结婚应期外，天干相冲还有哪一项核心作用？","opts":["原局无财时，冲可以冲出暗财","原局有天干合时，冲可以破合","原局有比劫时，冲可以化为印星","原局有墓库时，冲可以开天干库"],"ans":1,"exp":"天干相冲共有三个作用：一是通过冲制做功；二是原局有天干合时，冲可以破合；三是合处逢冲、冲处逢合为结婚应期。","sec":"（一）天干四冲","t":"rule"},{"q":"地支子午相冲时，藏干人元之间的冲克关系如何？","opts":["子中癸水克午中丁火，午中藏干不克子水","子中癸水与午中己土互相生扶，只克丁火","子中癸水克午中丁火，午中己土克子中癸水","子中壬水克午中丙火，午中己土克子中壬水"],"ans":2,"exp":"子午相冲时，地支遁藏人元互相冲克：子中癸水克午中丁火，同时午中己土反克子中癸水。","sec":"（二）地支六冲","t":"calc"},{"q":"对比地支六冲的藏干冲克，下列哪一组只有单向藏干相克？","opts":["巳亥冲，仅亥中壬水克巳中丙火","寅申冲，仅申中庚金克寅中甲木","子午冲，仅子中癸水克午中丁火","卯酉冲，仅酉中辛金克卯中乙木"],"ans":3,"exp":"卯酉冲仅酉中辛金克卯中乙木；而子午、寅申、巳亥、辰戌、丑未冲，双方藏干之间均有互相冲克。","sec":"（二）地支六冲","t":"diff"},{"q":"双方相邻、力量对等时，子午冲与卯酉冲对施冲方（子、酉）会产生什么结果？","opts":["午、卯被克坏，子、酉则“劳力”耗力","午、卯被克坏，子、酉毫发无损反得旺","子、酉与午、卯力量相当，双方皆被冲坏","午、卯被克坏，子、酉因得生而更强"],"ans":0,"exp":"力量对等且相邻时，子午冲午被克坏而子“劳力”（施冲者耗力）；卯酉冲卯被克坏而酉则劳力。","sec":"（三）冲克的结果","t":"rule"},{"q":"双方相邻且力量对等时，寅申冲与巳亥冲中哪些隐藏遁藏天干会同时受伤？","opts":["寅申冲仅伤寅中甲木，巳亥冲仅伤巳中丙火","寅申冲伤丙火壬水，巳亥冲伤戊土甲木","寅申冲伤甲木庚金，巳亥冲伤丙火壬水","寅申冲伤戊土庚金，巳亥冲伤庚金丙火"],"ans":1,"exp":"寅申冲以申克寅为主，寅中丙火、申中壬水同时受伤；巳亥冲以亥克巳为主，巳中戊土、亥中甲木同时受伤。","sec":"（三）冲克的结果","t":"calc"},{"q":"盲派区分地支相冲的「顺冲」与「倒冲」，二者的根本区别在于什么？","opts":["阳支冲阴支为顺冲，阴支冲阳支为倒冲","年冲月、日冲时为顺冲，时冲日、月冲年为倒冲","主冲方得势冲去被冲方为顺冲，反之则倒冲","相克之冲为顺冲，相生或同五行相冲为倒冲"],"ans":2,"exp":"双方力量悬殊时看势：主冲方得势冲去被冲方，叫顺冲；被冲方得势反冲去主冲方，叫倒冲。","sec":"（三）冲克的结果","t":"diff"},{"q":"地支近冲、隔冲与遥冲在力度和主事上分别有什么特点？","opts":["近冲力弱，隔冲力强主冲开，遥冲主损伤","近冲与隔冲均主冲破，遥冲主合而不冲","近冲力强主冲动，隔冲力微，遥冲主克破","近冲力强，隔冲力弱主损伤，遥冲微主冲动"],"ans":3,"exp":"近冲（相邻）力量强；隔冲（年与日、月与时）力量弱，主损伤；遥冲力量微弱，主冲动，也有冲开之意。","sec":"（四）远近与强弱","t":"diff"},{"q":"关于地支相冲的力度强弱判断，下列说法符合盲派规则的是哪一项？","opts":["冲中带克为强，大运冲强而太岁冲弱","冲而不克为强，太岁冲强而大运冲弱","一合一冲则冲力加倍，合神完全失效","月令力量与年时相等，主要看天干透出"],"ans":0,"exp":"月令力量略大于其他各支；冲中带克为强，冲而不克为弱；大运冲强，太岁（流年）冲弱；一合一冲力量互相抵消减弱。","sec":"（四）远近与强弱","t":"rule"},{"q":"地支排成「子、丑、午」（午在合神之外且与子丑隔开不紧邻），冲与合怎么论？","opts":["合必破，论冲不论合","贪合忘冲，论合不论冲","伤合，子午冲与子丑合同时成立","子丑合被破，午火因孤立被冲走"],"ans":1,"exp":"冲神在合神之外且隔开不紧邻时，构成贪合忘冲，论合不论冲；三合局的情况也依此规则分析。","sec":"（二）冲破合、破局","t":"calc"},{"q":"地支出现三合局时，若局外或局中逢冲神，应如何判断破局与否？","opts":["必须出现两个冲神，才能破除三合局","三合局力量最大，任何冲神皆不能破","依冲神与两合神位置规则同理分析","只要见冲神出现，三合局必定立即破局"],"ans":2,"exp":"两神相合逢冲，要看冲神夹在中间、在合外紧邻还是在合外隔开；三合局遇冲的情况也完全依此位置规则分析。","sec":"（二）冲破合、破局","t":"rule"},{"q":"盲派关于弱者冲旺者的五行经验规律，下列哪一项表述正确？","opts":["弱金冲旺木则木被拔除，不利引火生发","土越冲越实而坚固，水越冲则凝滞不通","弱水冲旺火则火必熄，弱金冲旺木则金断","弱水冲旺火则火愈旺，土冲变旺却是动而反虚"],"ans":3,"exp":"衰冲旺则旺神发：弱水冲旺火火愈旺；弱金冲旺木劈木以利引火；土虽冲而变旺，却是动而反虚；水狂则奔决。","sec":"（三）冲起、冲旺","t":"rule"},{"q":"当冲者无力而激起旺神时，激起凶神与激起吉神的吉凶后果有何不同？","opts":["激凶神为祸，激吉神无妨且有时反为吉","激凶神与激吉神皆主大祸，不可被激起","激吉神反凶，激凶神则因冲而化为吉神","无论吉凶神，只要冲者无力则双方皆无事"],"ans":0,"exp":"冲者有力能冲去对方，去凶神利、去吉神不利；冲者无力反激起对方，激凶神为祸，激吉神无妨，有时反而为吉。","sec":"（三）冲起、冲旺","t":"diff"},{"q":"大运冲原局与流年（太岁）冲原局在基本定性上有何区别？","opts":["运冲与岁冲皆只主冲动，不主冲破","运冲主冲破冲坏，岁冲主冲动冲开","运冲主冲动冲开，岁冲主冲破冲坏","运冲专门开墓库，岁冲专门坏墓库"],"ans":1,"exp":"运冲（大运来冲）冲破冲坏；岁冲（流年来冲）冲动冲开。动是发动，开是开墓。","sec":"（四）冲动、冲开","t":"diff"},{"q":"日主与财星相合（如丁壬合财）时，判断命主能否富贵的关键条件是什么？","opts":["必须天干再透出官星护财，才能论富贵","财星力量必须远大于日主，财旺才能发大财","比较日主与财的力量，日主力大于财才能富","只要日主合财，不论双方力量大小皆必大富"],"ans":2,"exp":"一合财就要比较日主与财的力量，日主的力量要大过财才能富，如同背包袱，包袱太大就背不动而不能富。","sec":"（一）近冲：冲伤、冲坏","t":"rule"},{"q":"当原局年月天克地冲且年支伤官被月令冲坏时，年上伤官一般类象为哪位六亲？","opts":["代表配偶，主婚姻早破","代表父亲，主父亲早逝","代表子女，主头胎难保","代表奶奶，主祖母早逝"],"ans":3,"exp":"年上伤官代表奶奶，年月天克地冲而月令力大冲坏年支伤官时，常断祖母早逝。","sec":"（一）近冲：冲伤、冲坏","t":"xiang"},{"q":"关于乙未、庚辰、辛丑这几个特殊日柱，在原局遇刑冲时的怕忌有何不同？","opts":["只有乙未的未怕刑冲，庚辰与辛丑不怕","只有庚辰的辰怕刑冲，乙未与辛丑不怕","三柱均喜刑冲，逢刑冲皆作开库发财论","三柱均最怕刑冲，逢刑冲必主伤六亲"],"ans":0,"exp":"乙未、庚辰、辛丑这几个日柱遇刑冲时，只有乙未的未怕刑冲，其他不怕；且三刑要紧邻才主伤六亲，相隔较远不论。","sec":"（三）隔冲、遥冲：冲开财官库","t":"diff"},{"q":"在盲派取象中，丁火日主与丙火日主在“文化、演艺”方面的象有何区别？","opts":["丙火与丁火皆无条件代表深厚的学历文化","丁印重反没文化，丙主演艺而作食神可主文化","丁火只主演艺，丙火印重才主没有文化","丁火印重必主高学历，丙火作官杀才主文化"],"ans":1,"exp":"丁火代表文明、文化，但丁日主印星太重化不了就没文化；丙日主不代表文化而代表演艺、表演，丙作食神时也可作文化讲。","sec":"（三）隔冲、遥冲：冲开财官库","t":"diff"},{"q":"口诀「财临库地，父当早死」，在什么条件下父亲不会死得特别早？","opts":["财库紧邻被日支冲开时，父反长寿","日主坐下为比劫羊刃时，父必长寿","财星有原神相生时，不会死得特别早","原局天干透出两个官杀时，可解克父"],"ans":2,"exp":"财临库地，父当早死；但若财有原神（食伤生财），则不会死得特别早，应期往往在财库或伤财之运年。","sec":"（四）近冲：冲制与力量对比","t":"rule"},{"q":"印制食伤做功但食伤未制净，且形成「印带杀帽」时，最忌大运出现什么情况？","opts":["忌行财星生官运，宜行食伤泄秀之运","原局有带象最喜大运天干相合以定根基","忌行印星旺运，且忌地支再见同党比劫","忌行食伤运，且忌天干合去印上的杀帽"],"ans":3,"exp":"印制食伤而食伤未制净，不喜食伤运、喜印运；原局印带杀帽有象，不喜合，若大运天干合去杀帽则坏了带象。","sec":"（五）印制食伤、禄遇杀冲","t":"rule"},{"q":"女命原局年、月、日、时见日主之禄被七杀冲或穿，盲派口诀一般断为何象？","opts":["有曾被人强奸之象","有离乡背井远嫁之象","有掌管兵权之武将象","有克夫再嫁三次之象"],"ans":0,"exp":"口诀：七杀冲穿禄，为强奸（女命四柱见日主之禄被七杀冲、穿，有强奸之象）；另口诀：穿倒羊刃，一刀之罪。","sec":"（五）印制食伤、禄遇杀冲","t":"xiang"},{"q":"原局七杀无制，又见比肩抗杀（且比肩成党），在盲派口诀中主何类象？","opts":["为军警武职，比肩成党主统领大军","为犯罪分子，比肩成党主团伙作案","为清高隐士，比肩成党主交友满天下","为白手起家，比肩成党主兄弟合资经商"],"ans":1,"exp":"口诀：七杀无制，见比肩抗杀，为犯罪分子；比肩成党则代表团伙，若木为根且被运岁申金冲斩，则主被抓应期。","sec":"（六）七杀对抗","t":"xiang"},{"q":"原局本身已有隔冲或遥冲，当大运再见到主冲或被冲的字时，应如何论断？","opts":["一神冲两神变为冲动，原局之冲失效","遥冲遇运变为合局，解除原局之冲","等于变为紧邻冲，是原局之冲的应期","隔冲遇运依然为遥冲，不作应期论"],"ans":2,"exp":"原局隔冲、遥冲，大运再见主冲或被冲之字，就等于紧邻冲，正是原局之冲发生作用的应期。","sec":"（一）大运冲原局","t":"rule"},{"q":"原局某天干在大运地支得根，该大运支冲入命局时，与单纯大运来冲有何不同？","opts":["得根冲入只论冲动，单纯运冲只论开库","得根冲入必主大凶，单纯运冲必主发财","二者皆按原局天干旺衰决定，没有区别","得根冲入一般为应事，单纯运冲则冲坏冲去"],"ans":3,"exp":"原局某天干在大运地支得根，此根又冲入命局，一般是应事；若是单纯由大运来冲原局之字，则主冲坏、冲去。","sec":"（一）大运冲原局","t":"diff"},{"q":"流年冲原局地支时，冲原局的「旺字」与冲「弱字」结果有何差异？","opts":["冲旺字一般为冲动使其发挥作用，冲弱字可能冲去","流年力量弱，无论冲旺冲弱皆不能使字动或去","冲旺字为开墓，冲弱字为闭墓","冲旺字必主破局大凶，冲弱字反主生旺"],"ans":0,"exp":"流年冲原局中的旺字，一般是冲动，使该字在原局发挥作用；冲弱字时，则有可能将该弱字冲去。","sec":"（二）流年冲原局","t":"diff"},{"q":"大运或流年出现「拱」（如申辰拱子）与「冲」在做功方式上有何形象区别？","opts":["拱的力量大于冲，能将库中物一次性全制净","冲是制得干净，拱像接细管子一点点流出来","冲只制官杀，拱只能合化比劫禄神","拱是瞬间爆发巨财，冲是细水长流慢慢得"],"ans":1,"exp":"盲派对拱与冲的做功形象有明确区分：冲是制得干净，而拱则像接了一根细管子，把财或物一点点流出来。","sec":"（三）流年冲大运","t":"diff"}]},{"n":13,"level":"初级","title":"冲、穿（二）相穿","qs":[{"q":"十二支六组相穿是（　）。","opts":["子未、丑午、寅亥、卯辰、申巳、酉戌","子未、丑午、寅巳、卯辰、申亥、酉戌","子午、丑未、寅申、卯酉、辰戌、巳亥","子丑、寅亥、卯戌、辰酉、巳申、午未"],"ans":1,"exp":"冲其合神者即为穿：子合丑而未冲丑，所以子未穿，其余依六合类推。","sec":"（一）六穿与\"冲其合神\"","t":"rule"},{"q":"午本要与未合，而丑来冲未，午与丑按盲派叫什么关系？","opts":["丑午相刑，互相刑伤","丑午相冲，正面对冲","丑午相穿，冲其合神","丑午相合，合神相会"],"ans":2,"exp":"午未合，丑冲未，冲掉了午的合神，午丑成相穿，相互为仇敌。","sec":"（一）六穿与\"冲其合神\"","t":"calc"},{"q":"穿与冲的区别，盲派的看法是（　）。","opts":["冲的杀伤力胜过穿，应事比穿更准","冲和穿都是正面来，只是力量大小不同","穿从正面来可跑，冲从侧面来躲不开","冲从正面来可跑，穿从侧面来躲不开，是仇敌"],"ans":3,"exp":"冲是正面来、敌不过可跑，有冲走冲动之意；穿是侧面来、防不胜防，杀伤力胜过冲，必应事，多应六亲。","sec":"（二）穿与冲的区别","t":"diff"},{"q":"「穿倒」与「穿偏」的判断依据区别是（　）。","opts":["穿倒要比较双方力量，穿偏不管力量只要有穿","穿倒不管力量只要有穿，穿偏要比较力量","穿倒与穿偏都要比较双方力量大小","穿倒看原局，穿偏看大运流年"],"ans":0,"exp":"穿倒看势，被穿一方立不住才倒；穿偏看象，只要有穿，正的就偏、偏的转正。","sec":"（一）穿倒与穿偏","t":"diff"},{"q":"六穿里「相克又穿」最严重的是哪一组？","opts":["子未、卯辰、申亥、寅巳","子未、卯辰、酉戌、丑午","寅巳、申亥、酉戌、丑午","子未、寅巳、酉戌、卯辰"],"ans":1,"exp":"申亥、寅巳是生中带穿，杀伤力小，只有克穿的四组最重。","sec":"（二）克穿重、生穿轻","t":"rule"},{"q":"口诀「吉神被穿主凶，凶神被穿为吉」之外，不用之神被穿应怎么论？","opts":["不用之神被穿，看大运再定吉凶","不用之神被穿也论凶","不用之神被穿也论吉","不用之神被穿不论吉凶"],"ans":2,"exp":"总原则：吉神被穿主凶，凶神被穿为吉，不用之神被穿也论吉。","sec":"（一）原局中的穿","t":"rule"},{"q":"日主坐下的配偶星，被穿时怎么看？","opts":["偏星正星被穿都无妨，只看大运","正星可以被穿无凶，偏星绝不能受穿","偏星正星被穿都主婚姻必坏","偏星可以被穿无凶，正星绝不能受穿"],"ans":3,"exp":"男命坐偏财、女命坐偏官的偏星可以被穿；坐正的配偶星绝对不能受穿。","sec":"（一）原局中的穿","t":"rule"},{"q":"日、时上的禄，对冲与穿的态度是（　）。","opts":["不怕冲，怕穿","不怕穿，怕冲","冲穿都不怕","冲穿都怕"],"ans":0,"exp":"日时上的禄不怕冲，怕穿；日主坐财则可合制不可穿制。","sec":"（一）原局中的穿","t":"rule"},{"q":"夫宫是戌而夫星是酉，酉戌相穿，按盲派应怎么断？","opts":["夫宫夫星相穿，穿而不制反主长寿","夫宫穿坏夫星，严重克夫","夫宫穿夫星为开库，主婚姻变好","夫星制夫宫，女管丈夫婚姻好"],"ans":1,"exp":"酉戌穿中戌为燥土伤食库，坏酉金，夫宫穿夫星就是严重克夫；穿是仇恨，不是制。","sec":"（六）酉戌穿","t":"rule"},{"q":"穿的字被流年合住，对穿的作用有什么影响？","opts":["合不解穿，穿的力量反而加倍","合可解穿，但只解生穿，不解克穿","合可解穿，穿的字被合住则不起作用","穿的字被合住，改为穿而变冲"],"ans":2,"exp":"提示：合可解穿，穿的字被流年合住、绊住，穿就不起作用；穿中结婚往往靠此。","sec":"三、穿的用法","t":"rule"},{"q":"卯辰穿属于克穿，对辰土而言应怎么理解？","opts":["卯辰穿为生穿，主动不主凶","卯辰穿能开辰库，与冲刑同样","卯辰穿开库，但只开一半","墓库被穿不为开库，不同于冲、刑"],"ans":3,"exp":"墓库被穿不为开墓库，如卯辰穿不是开辰库，这与冲、刑不同；卯克辰，是克穿。","sec":"（一）原局中的穿","t":"rule"}],"fine":[{"q":"按「冲其合神者即为相穿」的原理，申与亥为什么构成相穿？","opts":["亥要与午合，而申来冲午","申要与巳合，而亥来冲巳","申亥五行相克，位置对冲","申要与辰合，而亥来冲辰"],"ans":1,"exp":"十二支六合中申巳合，亥水来冲申的合神巳火，冲其合神，故申与亥构成相穿。","sec":"（一）六穿与\"冲其合神\"","t":"calc"},{"q":"禄冲财与禄穿财在盲派断命中有何本质区别？","opts":["禄穿财能制净大财，禄冲财则力量分散难发","禄冲财与禄穿财均主破财，只是应期早晚不同","禄冲财是财来财去得财，禄穿财则禄受伤难受","禄穿财是财来财去得财，禄冲财则禄受伤难受"],"ans":2,"exp":"冲是正面来，敌不过可跑，禄冲财是财来财去、财到自己身上；穿是侧面仇敌拼斗，禄穿财则禄受伤很难受。","sec":"（二）穿与冲的区别","t":"diff"},{"q":"酉戌穿通常是戌燥土穿酉金，但在什么情况下酉反而能穿倒戌？","opts":["局中水旺木衰时，酉水同党必穿倒戌","只要酉金居日支主位，就能穿倒戌土","酉戌紧邻相见时，一律按酉金穿倒戌土","局中金旺而火土弱时，酉反能穿倒戌"],"ans":3,"exp":"穿也是制法之一，但要分势：一方旺则可以穿倒对方，若局中金旺火土弱，酉反而能穿倒戌。","sec":"（三）穿也是制，但要看势","t":"rule"},{"q":"盲派口诀「穿中带克的为制，穿中带生的只看象」，重点看被穿的是什么位置的字？","opts":["穿的是主位的字","穿的是月令的字","穿的是年柱的字","穿的是大运的字"],"ans":0,"exp":"口诀完整为：穿中带克的为制，穿中带生的只看象，穿的是主位的字。","sec":"（三）穿也是制，但要看势","t":"rule"},{"q":"下列哪一项属于盲派所说的「穿偏」或「穿反」的典型表现？","opts":["财库逢大运冲开，库中遁藏之物引出为用","正印被穿变成非正统职业，偏财被穿正","日主之禄被七杀冲开，远赴外地谋职","被穿的字力量太弱，彻底立不住而消亡"],"ans":1,"exp":"穿偏指正的变偏、偏的变正：如正印被穿变成非正统职业，偏财被穿转正，甚至应生男孩穿成女孩。","sec":"（一）穿倒与穿偏","t":"xiang"},{"q":"口诀「穿倒羊刃，一刀之罪」之外，穿倒食神与穿倒正印分别主什么？","opts":["穿倒食神不走正路，穿倒正印损寿元","穿倒食神主破财，穿倒正印主克父","穿倒食神损寿元，穿倒正印不走正路","穿倒食神主牢灾，穿倒正印主离异"],"ans":2,"exp":"口诀：穿倒羊刃，一刀之罪；穿倒食神损寿元；穿倒正印不走正路。","sec":"（一）穿倒与穿偏","t":"xiang"},{"q":"申亥穿、寅巳穿属于「生中带穿」，为什么在断命中仍不能小看？","opts":["因为生中带穿专门破坏日主的禄神与寿命","因为生中带穿比克穿的杀伤力还要更大","因为生中带穿一旦遇到大运必然直接转化为克穿","虽杀伤力小，但从象上同样厉害且必应六亲事"],"ans":3,"exp":"生穿中被生一方有“动”的意思，杀伤力不及克穿；但从象上讲同样厉害，一定应事，大多应六亲。","sec":"（二）克穿重、生穿轻","t":"rule"},{"q":"穿有原局中的穿、大运穿原局、流年穿原局三种情形，其中最可怕的是哪两种？","opts":["原局中的穿和大运穿八字","大运穿八字和流年穿八字","流年穿八字和流年穿大运","原局中的穿和流年穿八字"],"ans":0,"exp":"穿的三种情形中，原局的穿和大运穿八字最可怕；流年穿八字因流年短暂，大多只主心情不好或办事受阻。","sec":"三、穿的用法","t":"diff"},{"q":"在原局婚姻与做功中，关于夫妻宫与日主坐财对「穿」的态度，下列说法正确的是哪项？","opts":["夫妻宫与日主坐财均只论生穿，不论克穿","夫妻宫有用不能穿，日主坐财可合制不可穿制","夫妻宫有用时喜穿，日主坐财最喜旁支来穿制","夫妻宫无用也不能穿，日主坐财可穿制不可合制"],"ans":1,"exp":"夫妻宫有用时不能被穿，一穿就坏；夫妻宫无大用时穿之一般无妨。日主坐财可合制不可穿制。","sec":"（一）原局中的穿","t":"rule"},{"q":"原局出现配偶星与配偶宫互穿时，在什么情况下反而无妨甚至为吉？","opts":["配偶星为正星正位，被婚姻宫紧邻克穿之","日主坐下为禄神，被月令七杀紧邻克穿之","婚姻宫为局中起坏作用的字，被配偶星穿之","日主坐下为正印，被时支财星紧邻克穿之"],"ans":2,"exp":"若婚姻宫为局中起坏作用的字（如死木坐子水忌印），配偶星穿之反而去病为吉，此时婚姻并不一定有凶。","sec":"（一）原局中的穿","t":"rule"},{"q":"大运穿原局配偶宫时，未婚者与已婚者分别常呈现什么结果？","opts":["未婚必在当年闪婚，已婚必在当年立刻离婚","未婚无妨仍易结婚，已婚反而夫妻感情更和睦","不论未婚或已婚，大运穿配偶宫皆主生离死别","未婚难有结婚机会，已婚主不吉但不一定离"],"ans":3,"exp":"配偶宫受大运穿：此运没结婚就很少有结婚机会；已婚者婚姻一定不吉，轻者吵架分居，重者离婚，但不一定离。","sec":"（二）大运穿原局","t":"rule"},{"q":"在穿配偶宫的大运里，命主依然能够顺利结婚的常见条件是什么？","opts":["主穿之字被流年合住绊住，且夫妻星动了","大运天干透出比肩，分担配偶宫受穿之力","流年再出现一个相同的穿神，形成两穿一","流年直接冲克配偶宫，将原局之字冲走"],"ans":0,"exp":"合可解穿：若主穿之字被流年合住、绊住，穿的力量消失，且夫妻星正好动了，也可以在穿的运里结婚。","sec":"（二）大运穿原局","t":"rule"},{"q":"流年穿原局通常杀伤力不大，但在遇到什么位置被穿时尤其需要注意？","opts":["流年穿年支上的闲神或无用之字时","流年穿主位的字（日支）或要用的字时","流年穿大运天干上的虚透之字时","流年穿局中早已受制的凶神之字时"],"ans":1,"exp":"流年穿八字一般不厉害，多主心情不好、办事受阻；但流年穿主位的字（日支，或要用的字）尤其要注意。","sec":"（三）流年穿原局","t":"rule"},{"q":"盲派判断大运、流年见到原局中的字时，应期吉凶应遵循什么原则？","opts":["只有该字在原局为旺神时，运岁见之才算应期","必须看该字在运岁中变旺还是变衰再定应期","不论旺衰，都是原局中那个字的应期","运岁见原局之字一律按生扶日主论吉"],"ans":2,"exp":"大运、流年见原局中的字，不管其旺衰，都是原局中那个字的应期，该字在原局有何作用，运岁见之就发生相应之事。","sec":"（三）流年穿原局","t":"rule"},{"q":"未为比劫羊刃库且子未穿制印本主掌兵权，若局中又见午未合闭了羊刃库，有何变化？","opts":["主兵权翻倍，成为冲锋陷阵的前线猛将","主彻底失去官职，一生只能靠手艺谋生","主牢狱之灾，羊刃入库而化为违法凶星","主“刀枪入库”，变为文官或不拿枪的官"],"ans":3,"exp":"印被刃库所制主掌兵权；但若午未合闭了羊刃库，则是“刀枪入库”，羊刃带文气，转为不拿枪的官或文官。","sec":"（一）子未穿","t":"xiang"},{"q":"甲木日主生于午月无根与生于未月有根，在运用「子未穿」去水时有何区别？","opts":["午月无根死木可去水，未月有根活木不可去水","生于午月一定就是死木，不必看时柱是否有根","甲木不论生午月或未月，皆作死木喜去水","午月死木不可去水，未月活木最喜去水"],"ans":0,"exp":"甲生午月无根为死木可去水；生未月有根或时为乙亥有根则是活木，不可去水；且不能仅凭生于午月就断定死木。","sec":"（一）子未穿","t":"diff"},{"q":"在年月柱不见印星的情况下，年支未土食神被月支子水穿倒，一般主伤哪位六亲？","opts":["伤父亲，年支食神永远代表父亲","伤母亲，年上食神无印时当母亲看","伤妻子，食神在年支一律当妻星看","伤子女，食神被穿倒必主绝后无子"],"ans":1,"exp":"印星在年月为母亲，无印则找食神；年月不见印时，年支食神当母亲看，被子水穿倒主伤母。","sec":"（一）子未穿","t":"xiang"},{"q":"原局出现「合而有寿」（如丁壬合）的组合时，最怕大运流年出现什么情况？","opts":["最怕入库，合神入库则立即亡","最怕生助，印旺生合则寿减","最怕解合，破合则寿尽","最怕再合，重逢合神则减半"],"ans":2,"exp":"原局合而有寿时论吉，最怕大运流年冲克破合、解合，一旦破合则有寿尽之凶。","sec":"（一）子未穿","t":"rule"},{"q":"女命原局出现丑午穿，且午火既是日主之禄（身体）又是子女宫时，易患哪类疾病？","opts":["四肢关节风湿或筋骨骨折","肺部哮喘或呼吸道疾病","头部偏头痛或神经衰弱","子宫或生殖系统疾病"],"ans":3,"exp":"女命中午是日主身体又是子女宫，则类象为子宫；丑为阴暗潮湿之物，丑午穿晦火，易患子宫或生殖系统疾病。","sec":"（二）丑午穿","t":"xiang"},{"q":"女命日主坐下为七杀偏星（如戊寅），通常偏星可被制，为何被年支巳禄穿反主严重克夫？","opts":["巳是日主之禄代表自己，穿夫星且象反局","寅巳相穿属于克穿中最凶的一种，必克死夫","寅木为日主长生之地，任何情况皆不可被穿","年支力量大于日支，年上之禄必把夫星冲走"],"ans":0,"exp":"偏星坐支通常可制，但巳是戊土的禄，代表日主自己，寅巳穿即日主亲自穿夫星，且象也反局，故严重克夫。","sec":"（三）寅巳穿","t":"rule"},{"q":"女命年支伤官卯穿日支夫宫辰，但丈夫健康无碍仅外遇不和，可能是什么原因？","opts":["卯辰穿属于生穿，原本就没有伤害力","卯被月支申合受制，且隔穿力量小只能穿坏","辰为比劫库，比劫库永远不怕木来克穿","年支与日支相隔太远，完全不发生相穿关系"],"ans":1,"exp":"隔穿力量小，只能穿坏不能穿死；若伤官卯又被申金合住受制，穿力进一步减弱，故不致穿死夫星。","sec":"（四）卯辰穿","t":"rule"},{"q":"申亥穿虽为生穿，但若穿倒局中正印或正官，在工作事业上常应什么事情？","opts":["必获海外巨额遗产，一生不必上班劳碌","必升为正职大官，掌控全国财政大权","正统工作归不了正，易下岗或转非正经班","必入公检法司系统，专职审理刑事大案"],"ans":2,"exp":"正印代表正儿八经的工作，穿倒了就归不了正，不让好好上班，申亥穿倒正印常应下岗、停薪留职等。","sec":"（五）申亥穿","t":"xiang"},{"q":"男命日坐酉金偏财而被戌穿，判断是否严重克妻的关键在于局中是否出现什么？","opts":["是否再见卯木冲酉，形成卯酉对冲偏财","天干是否透出庚辛金，金旺则戌穿不动酉","戌土是否坐在月令，月令戌穿酉则必克妻","是否透出比劫与日主争妻，且比劫入戌库穿酉"],"ans":3,"exp":"偏星坐支本可被穿；但若年上透丙比劫坐午入戌库，戌再穿酉，则成一群男人夺妻之象，此时才严重克妻。","sec":"（六）酉戌穿","t":"rule"},{"q":"盲派口诀「比肩遇伤官，穿官为牢灾」能够应验，必须满足的关键条件是什么？","opts":["必须比肩多，且伤官与官星相穿而非刑冲","必须日主身旺，且局中出现两个以上正印","只要见伤官刑官或冲官，同样必主牢狱之灾","只要命局见一个比肩与一个伤官，即主坐牢"],"ans":0,"exp":"比肩遇伤官、与官不和且穿官为牢狱（如戌为伤官库是违法星）；刑冲都不行，必须比肩多，成群捣蛋。","sec":"（六）酉戌穿","t":"rule"},{"q":"八字原局不透财星，财暗藏在年支戌墓之中却被酉金穿坏，一般主什么六亲之象？","opts":["命主本人必早夭，不过三十岁即有寿劫","六亲有早亡之象，年月之财多主父亲早亡","六亲皆大富大贵，祖辈必留巨额房产","子女必定极多，且个个身居高官厚禄"],"ans":1,"exp":"墓中的财被穿，六亲有早亡之象，年月上的财尤其；财在年上代表父亲，父母宫财库被穿坏多主父亲早亡。","sec":"（六）酉戌穿","t":"xiang"}]},{"n":14,"level":"初级","title":"做功方式与制局通辨（上）：做功的六种方式","qs":[{"q":"按盲派做功层次，制用、化用、生泄用的高低顺序是？","opts":["生泄用高于化用，化用高于制用","化用高于制用，制用高于生泄用","制用高于化用，化用高于生泄用","制用高于生泄用，生泄用高于化用"],"ans":2,"exp":"口诀：反胜正，制胜化，化胜泄；制是取得占有，化是借力，生是耗自己之力。","sec":"九、做功方式与层次高低","t":"step"},{"q":"做功层次上，「用凶神做功」与「用吉神做功」，哪个效果更大？凶神、吉神各指什么？","opts":["吉神更大：吉为杀劫刃枭，凶为禄印官","凶神更大：凶为杀劫食伤，吉为禄印官","吉神更大：吉为禄印官，凶为财杀劫","凶神更大：凶为杀劫刃枭，吉为禄印官"],"ans":3,"exp":"凶神指杀、劫、刃、枭，吉神指禄、印、官；无论正向反向，用凶神做功效果更大。","sec":"九、做功方式与层次高低","t":"diff"},{"q":"制用结构不可去日主之根。下列日柱中，哪个被制不涉及寿命？","opts":["戊辰","甲寅","乙卯","辛酉"],"ans":0,"exp":"日主的根（连根）不能制，制了伤寿；乙卯、甲寅一类连根草，辛酉也麻烦，戊辰一类不连根，无所谓。","sec":"二、制用结构（去用结构）","t":"calc"},{"q":"化用结构成立，印与官杀、印与日主的位置各有什么要求？","opts":["印可隔位化官杀，须紧贴日主","印须紧贴官杀，又须紧贴日主","印只须出现在年月，位置不拘","印须紧贴官杀，可隔位生日主"],"ans":1,"exp":"印与官杀隔位则化不了，与日主隔位则生不了身；有官杀有印不等于化用。","sec":"三、化用结构","t":"rule"},{"q":"局中官杀俱旺而无制无化，大运走印星来化官杀，怎么论？","opts":["按制用论，印制官杀","仍属无用结构，大运无用","按化用论，大运补上","按生用论，印生日主"],"ans":2,"exp":"局中官杀俱旺无制化，如果大运有印来化官杀，也按化用论。","sec":"三、化用结构","t":"rule"},{"q":"伤食生财的结构，最怕什么？","opts":["伤食被印制、被官杀克","财星被日主合、被比劫夺","生财的字被冲、被克、入禄","生财的字被穿、被合、入墓"],"ans":3,"exp":"食伤生财最怕生财的字被穿、被合、入墓：做功的字坏了，象就坏了。","sec":"四、生用、泄用结构","t":"rule"},{"q":"日主合财，身旺而财弱，按盲派怎么论？","opts":["不穷，有钱花，一般人","合财可发大财","必是穷人","有财但不会大，不缺吃喝"],"ans":0,"exp":"日主合财看身强弱四档：旺旺发大财，弱旺必穷，旺弱不穷一般人，弱弱有财不大。","sec":"五、合用结构","t":"calc"},{"q":"日主合的是虚透之财，按盲派如何论？","opts":["当财看，身旺必富","表示才华，不当财看","表示官职，不当财看","当财看，身弱则穷"],"ans":1,"exp":"例外：日主合虚透之财，则此财表示才华，身旺合虚财也不表示穷。","sec":"五、合用结构","t":"rule"},{"q":"墓用结构里，做功的字入墓，对做功有什么影响？","opts":["入墓后做功减半","入墓则做功失效，必须开库","不影响做功，入墓与做功是两层意思","入墓只影响内食神格"],"ans":2,"exp":"墓指得到、控制、管理、拥有；入墓并不影响做功，库可开可不开。","sec":"六、墓用结构","t":"rule"},{"q":"体在主位制宾位的用，与用在主位、体在宾位，各叫什么做功？","opts":["前者反向做功，后者正向做功","前者化用，后者制用","两者都叫正向做功","前者正向做功，后者反向做功"],"ans":3,"exp":"体在主位、用在宾位为正向；用在主位、体在宾位等为反向，要求制得干净有力。","sec":"八、正向做功与反向做功","t":"diff"},{"q":"反向做功制宾位的字时，什么情形下不可制？","opts":["宾位的字是寿元星，制之伤寿","宾位的字是官星，制之失官","宾位的字是财星，制之破财","宾位的字是食神，制之无子"],"ans":0,"exp":"反向做功要看宾位有没有寿元星，寿元星在宾位，制之必伤寿；并且制得不干净不算。","sec":"八、正向做功与反向做功","t":"rule"},{"q":"复合结构里，制神与化神各喜虚透还是要实？","opts":["制的东西要实，化的东西喜虚透","制的东西喜虚透，化的东西要实","制与化的东西都喜虚透","制与化的东西都要实"],"ans":1,"exp":"制的东西虚透就跑了更好制；化的东西要实，虚的不能化。","sec":"七、复合结构","t":"rule"}],"fine":[{"q":"在盲派做功体系的基本术语中，「功神」与「制神」分别指什么？","opts":["功神是被拿住处理一方，制神是日主自己","功神是宾位的字，制神只能是主位的字","功神是参与做功的字，制神是被拿住处理一方","功神是原局用神，制神是原局忌神"],"ans":2,"exp":"功神是参与做功的字（相当于拿水的“手”和“水”）；制神则是被拿住、被处理的那一方（相当于“水”）。","sec":"一、为什么不讲用神，只讲做功","t":"diff"},{"q":"按取得东西的办法分类，盲派做功的五种基本方式是哪五种？","opts":["冲用、穿用、刑用、破用、墓用","扶抑、调候、通关、专旺、从格","制用、化用、拱用、暗合、虚透","制用、化用、生用（泄用）、合用、墓用"],"ans":3,"exp":"做功的五种基本方式为制用、化用、生用（泄用）、合用、墓用，再加多种方式并存的复合结构。","sec":"一、为什么不讲用神，只讲做功","t":"rule"},{"q":"同是制财结构，原局有病（如时上官杀无制）与原局制净且捕神过旺，大运喜忌有何不同？","opts":["有病喜运冲掉病，捕旺制净则喜贼神入运","两种结构都只喜捕神入运，绝不喜见贼神","两种结构都只喜贼神入运，绝不喜见捕神","有病喜贼神再入运，捕旺制净喜捕神更旺"],"ans":0,"exp":"原局若有病，喜大运把病冲掉；若原局已制得干净、捕神过旺，则喜大运流年贼神出现。两者喜忌相反。","sec":"二、制用结构（去用结构）","t":"diff"},{"q":"关于日柱连根的禁忌，下列哪组日柱不能被制去，且活木死木有何区别？","opts":["活木不怕铲根，死木一旦铲根则立刻伤寿","壬申、乙亥不能去，乙卯甲寅活木铲根则完","戊辰、辛卯最怕铲根，乙卯甲寅则无所谓","只要日主坐下为印星，任何情况都能被制去"],"ans":1,"exp":"壬申、乙亥日柱不能去；乙卯、甲寅一类连根草，死木还好，活木一旦被铲了根就完了；戊辰类不连根则无所谓。","sec":"二、制用结构（去用结构）","t":"rule"},{"q":"化用结构中，印星生身时「同性相生」与「异性相生」有什么区别？","opts":["不论同性还是异性相生，化用效力完全相同","异性相生力大，同性相生力小须隔位才好","同性相生力大，异性相生力小须更注意贴身","只有异性相生才算真化用，同性相生不算"],"ans":2,"exp":"印化官杀生身时，同性相生力大，异性相生力小；印与日主异性相生时其力较小，更要注意是否贴身。","sec":"三、化用结构","t":"rule"},{"q":"命局中官杀有印星来化，但印化不净或结构不清纯时，一般如何断？","opts":["官虽小但必主高学历，享清贵之名","直接按制用结构论，主武职掌兵权","不当官但必当巨财看，主发大财","既不主当官，也不当财看"],"ans":3,"exp":"有官杀有印不等于化用；若官杀有化但化不净，则既不主当官，也不当财看。","sec":"三、化用结构","t":"rule"},{"q":"原局官杀有的能被印化、有的隔位或受破而化不了时，大运如何走才能升官？","opts":["化不了的是病，大运制病之运是升官之运","化不了的是病，大运生旺该病之运升官","化不净的官杀绝不能制，只能等它自然入墓","只要大运再透出印星，隔位之官也能全化"],"ans":0,"exp":"官杀有的能化、有的化不了时，化不了的就是病；大运制病之运就是升官之运（口诀：有病治病运）。","sec":"三、化用结构","t":"rule"},{"q":"盲派总结「凡大富大贵的八字，一般要伤六亲」，其内在命理原因是什么？","opts":["因为富贵之人命中绝不能见任何财星与印星","旺势制去弱方，被制一方所主的六亲受伤残","大富大贵者必犯三刑，三刑全见必然克六亲","因为富贵之人日主太弱，无力生扶父母子女"],"ans":1,"exp":"这类命局往往有旺于一方的势，要制去弱的一方，被制一方所主的六亲就不伤则残。","sec":"三、化用结构","t":"rule"},{"q":"关于「水木伤官」在生用、泄用结构中的喜忌，盲派口诀怎么说？","opts":["水木伤官喜见印星，不喜见财官","水木伤官最喜七杀，制净伤官才富","水木伤官喜见财官，不喜见印","水木伤官只喜比劫，绝不喜见财"],"ans":2,"exp":"口诀：伤官食神喜见财；水木伤官喜见财官，不喜见印。","sec":"四、生用、泄用结构","t":"rule"},{"q":"什么是「内食神成格」？这种格局大多对应什么职业，格局上忌讳什么？","opts":["食伤入墓且天干透正印，多做学术，忌见比劫","食伤虚透天干而地支无根，多当官员，忌见财","食伤被官杀制净，多为武职，最忌财星透出","食伤成格且内藏财不透，多做企业，忌杂透印"],"ans":3,"exp":"食伤成格局、食伤中又藏着财而财不透，叫内食神（内伤官）格，多是做企业的，格局要纯，不要杂透印。","sec":"四、生用、泄用结构","t":"xiang"},{"q":"在婚姻类象中，女命出现「七杀坐食神」的组合时，往往主什么？","opts":["主找比自己年龄小的男友","主丈夫必为公检法部门的实权领导","主嫁给比自己大十岁以上的丈夫","主一生绝无婚姻，只能孤老终身"],"ans":0,"exp":"女命七杀坐食神（如辛己己癸／亥亥酉酉中辛坐亥），主找比自己年龄小的男友。","sec":"四、生用、泄用结构","t":"xiang"},{"q":"在合用结构中，若日主坐下是「正星坐正位」，对他星来合的态度是什么？","opts":["正星坐正位，最喜他星来合以加固","正星坐正位，不喜他星来合","正星坐正位，必须被它星合走才能发财","正星坐正位，见合反主夫妻恩爱白头"],"ans":1,"exp":"合用结构中，所合之物被坏则八字坏；同时正星坐正位不喜他星来合（被合则合跑了或失去正位）。","sec":"五、合用结构","t":"rule"},{"q":"盲派只在「日主合财」时看身强身弱，其判断身强弱的依据是什么？","opts":["专看是否得月令生扶，失令一律作身弱论","专看天干比劫数量，有两个以上即作身旺论","不凭月令，以坐支为主，兼看象与命局的势","专看时支是否为长生，得长生即作身旺论"],"ans":2,"exp":"唯独日主合财要看身强身弱，判断强弱不凭月令，以坐支为主，兼看象与命局的势。","sec":"（一）日主合财：要看身强身弱","t":"rule"},{"q":"下列几种「合」的情况中，哪一项需要看日主身强身弱？","opts":["日支合他支之财","日主自合坐下之财","日主合年、月之官","日主合他干之财"],"ans":3,"exp":"唯独日主合财要看身强身弱；日支合他支的财、日主自合坐下的财、以及日主合官，均不论身强身弱。","sec":"（一）日主合财：要看身强身弱","t":"diff"},{"q":"除「合虚透之财」外，日主合财不论身强身弱的另外两条例外是什么？","opts":["财成势做大功神；或局中别处另有大功","日主坐下为正印；或天干透出两个七杀","财星坐下为墓库；或财星被比劫所穿","年月干合财不论；或生于四季土月不论"],"ans":0,"exp":"日主合财的例外三条：1.财成势做功是大功神；2.合虚透之财；3.命局别处另有大功，以大功为主。","sec":"（一）日主合财：要看身强身弱","t":"rule"},{"q":"日主合财时，若「身弱而财弱」怎么断？身弱合财一般喜财星以什么形态出现？","opts":["身弱财弱可发巨财，身弱合财喜财入墓库","身弱财弱有财不大，身弱合财喜财星虚透","身弱财弱必是穷人，身弱合财喜财坐强根","身弱财弱必克妻，身弱合财最忌财星虚透"],"ans":1,"exp":"身弱财弱有财但不会大，不缺吃喝而已；身弱合财也喜财星的象虚透（如癸坐卯虚透），反而不致背不动。","sec":"（一）日主合财：要看身强身弱","t":"rule"},{"q":"日主合「时干之官」时，若时干官坐强根与时干官虚透，用法有何不同？","opts":["坐实可不用时支，虚透必须用时支","坐实只主名气，虚透才主掌握实权","坐实必须用时支，虚透可不用支只看象也可制","无论坐实还是虚透，都绝不能制时干官"],"ans":2,"exp":"日主合时干的官，必须用官坐下的时支；若时干官已虚透，则可不用支，只看象，时干官也可以被制。","sec":"（二）合官、合时上官","t":"diff"},{"q":"日主合年干或月干之官时，通常代表什么含义？年月的官一般类象为什么？","opts":["追求婚姻之意，年月的官绝不代表工作单位","辞职下岗之意，年月的官代表仇敌小人","自己创业之意，年月的官代表私营小厂","管理控制之意，年月的官代表外面的单位"],"ans":3,"exp":"日主合年、月的官，是管理控制之意，有的用有的不用看结构；年月的官是外来的，代表外面的单位。","sec":"（二）合官、合时上官","t":"xiang"},{"q":"关于「内食神格」与一般「墓用结构」对开库的要求，下列说法正确的是哪项？","opts":["内食神格不需开库，墓用结构库可开可不开","两者都不论开库，只要一开库就破格","两者都必须逢大运流年刑冲开库才有用","内食神格必须开库，墓用结构绝不能开库"],"ans":0,"exp":"墓用结构中库可开可不开，做功与入墓是两层意思；内食神格也不需要开库。","sec":"六、墓用结构","t":"diff"},{"q":"日主坐下食伤库（丑）入了年月上的劫财财库（辰），在企业经营上常类象为什么？","opts":["在政府机关担任公职，一生从不经商","做企业之象，大库属人先打工后自办","永远无法自主创业，只能做体力劳动","破产坐牢之象，一辈子欠债无法翻身"],"ans":1,"exp":"食伤库入财库是做企业的象；丑入辰则辰大丑小，辰是别人的，丑是自己的，常先替别人企业打工、后自办私企。","sec":"六、墓用结构","t":"xiang"},{"q":"命局属于「复合结构」或大运出现新的做功方式，在命主人生经历上对应什么？","opts":["对应命局混乱无功，一生无所事事无大作为","对应两种做功互相抵消，只能从事单一行业","对应一生多职业，大运现新方式说明换工作","对应早年必克父母，中年必克配偶"],"ans":2,"exp":"多种做功方式对应一生可能从事多种职业；原局只有一种方式的，行运后出现新方式，说明换工作。","sec":"七、复合结构","t":"rule"},{"q":"盲派认为反向做功极常见且效率常高于正向做功，但反向做功成立的前提是什么？","opts":["日主必须身旺，且局中不能见任何官杀星","被制之神必须坐在月令，且得到印星生扶","必须通过三合局来制，绝不能用六冲六合","被制之神制得干净有力，不拖泥带水"],"ans":3,"exp":"反向做功特点是被制之神制得干净有力，不拖泥带水，否则制不充分、不干净就不算反向做功。","sec":"八、正向做功与反向做功","t":"rule"},{"q":"为什么盲派认为在做功层次上「反向做功」通常高于「正向做功」？","opts":["反向者不循常人思维，以奇取胜能成枭雄","正向做功只适合普通上班，绝不能发大财","反向者永远不伤六亲，福禄寿三全无任何瑕疵","反向者只用吉神不用凶神，格局最清纯安稳"],"ans":0,"exp":"反向做功大于正向做功：反向者不同于常人思维，以奇取胜，甚至反正统，能成一世之枭雄。","sec":"九、做功方式与层次高低","t":"rule"},{"q":"所谓「无用结构」的命局，其最核心的判断特征是什么？","opts":["地支全部相冲相刑，日主坐下为墓库","不表达明确意思，用之难用、忌之难去","天干全透食伤泄秀，地支没有任何根气","八字全无财星与官星，只有比劫和印星"],"ans":1,"exp":"无用结构是指整个八字不表达明确的意思，日主无所事事或无所适从，用之难用，忌之难去，多无大作为。","sec":"十、附：无用结构","t":"rule"}]},{"n":15,"level":"初级","title":"做功方式与制局通辨（下）：制局配置与制法效率","qs":[{"q":"地支合制的效率，下列哪一项排在最高档？","opts":["卯戌合","寅亥合","子丑合","巳申合"],"ans":3,"exp":"合制效率：巳申最高，卯戌、卯申、午亥、巳酉次之，子丑、寅丑中，同党合制低，午未不为制。","sec":"（一）合制","t":"step"},{"q":"同样是「合」，午未合与寅亥合在制用上有何区别？","opts":["午未合不为制，寅亥合只制遁藏","午未合只制遁藏，寅亥合不为制","两者都能把对方整个制死","午未合制效率高，寅亥合不制"],"ans":0,"exp":"午未两字相生，仅闭未库，不算制；寅亥、辰酉、午戌为同党相合，只是遁藏被制（亥中壬灭寅中丙）。","sec":"（一）合制","t":"diff"},{"q":"冲刑制的效率排序，最高的是哪一类？","opts":["子午冲、卯酉冲","丑未冲、辰戌冲、丑戌刑等库冲库刑","寅申冲、巳亥冲","力量相当的任何冲"],"ans":1,"exp":"口诀：库冲库刑最高，寅申巳亥次之，子午卯酉再次，势均不制。","sec":"（二）冲制、刑制","t":"step"},{"q":"局中一个子与一个午相冲，双方党力相当，按盲派怎么论？","opts":["子制午，算制用做功","午制子，算制用做功","能量互相耗散，不做功","两败俱伤，必有大凶"],"ans":2,"exp":"冲刑制必须一方之党大于另一方之党才能制；势均则互耗，不做功。","sec":"（二）冲制、刑制","t":"rule"},{"q":"克制的一般效率如何？什么情况属例外而效率很高？","opts":["一般效率最高；围克效率更低","一般效率低；官杀克比劫才算例外","一般效率低；单克有势才算例外","一般效率低；围克制得干净"],"ans":3,"exp":"克制效率低，多为普通人；唯一例外是围克——包围制之，被制者无处可逃，常成贼捕，势中天干作用大。","sec":"（三）克制","t":"diff"},{"q":"地支六穿中，哪几组可以相制，且「穿而又克」效率最高？","opts":["酉戌、卯辰、子未、丑午","申亥、寅巳、酉戌、卯辰","酉戌、卯辰、申亥、丑午","子未、丑午、寅巳、申亥"],"ans":0,"exp":"申亥穿、寅巳穿是生穿，只表破坏之象，不能相制；酉戌、卯辰、子未、丑午可制，穿而又克效率最高。","sec":"（四）穿制","t":"rule"},{"q":"主位（日主）与财相穿，按盲派怎么论？","opts":["穿制得财，主发大财","自己与财无缘，穿则无财之象","只有女命主位穿财才无缘","只影响婚姻，不影响财运"],"ans":1,"exp":"穿可制印、官杀、伤食，唯独主位与财不能穿。男命一生与婚姻无缘但财运可以，女命则一生无财。","sec":"（四）穿制","t":"rule"},{"q":"被制者被制净制死的叫「贼捕」结构，这种结构大运喜见什么？","opts":["制者（捕）","生制者之印","被制之神（贼）","合住制者之神"],"ans":2,"exp":"制净者喜大运见被制之神（贼）；制不净者喜大运见制者（捕），制不净的官杀还要当财看。","sec":"一、制局的基本原则","t":"rule"},{"q":"日主的禄落在不同位置，哪一处的禄一定不能被制？","opts":["时支的禄（可冲不可穿）","月支的禄","年支的禄","日主坐支的禄（日主之根）"],"ans":3,"exp":"落在年、月的禄可制，时支的有时可制，坐支之禄是日主之根，一制就伤寿或反局。","sec":"（一）日主之根不可制","t":"rule"},{"q":"日主甲乙且为活木时，哪些位置的根不可制？","opts":["坐支、月支、时支之根","坐支和年支之根","年支、月支、时支之根","只有坐支之根"],"ans":0,"exp":"活木根不但坐支不能制，月支、时支的根也不能制；年上的根不当根论，大都可制。","sec":"（二）甲乙活木：根不可伤","t":"rule"},{"q":"六亲星居于对应的六亲宫（得正位）而被制，会怎样？","opts":["该六亲得力有福","伤及对应的六亲","只主本人破财","要看大运才定吉凶"],"ans":1,"exp":"例如子女星在子女宫被制，则子女有伤残之象；财居父母宫被合去伤父。","sec":"（三）六亲星得正位被制，伤六亲","t":"rule"},{"q":"歌唱类取财命局中，「嗓音好」的象是什么？","opts":["金主声音，水生金","水主声音，土克水","金主声音，火克金","木主声音，金克木"],"ans":2,"exp":"名人命局规律：金主声音，火克金主嗓音好；壬水为彩在门户，丁壬合是脸上添彩，主唱戏演员。","sec":"五、名人命局汇粹：体力与技艺取财","t":"xiang"}],"fine":[{"q":"制局中，若被制之神在原局「制得不净」，大运喜见什么，且制不净的官杀怎么看？","opts":["喜大运见被制之神（贼），官杀仍当官看","喜大运见印星化杀，官杀绝不能当财看","无论制净与否，大运一律只喜见财星与比劫","喜大运见制者（捕），制不净的官杀当财看"],"ans":3,"exp":"制净制死的贼捕结构喜见被制之神（贼）；制不净的喜大运见制者（捕），并且制不净的官杀要当财看。","sec":"一、制局的基本原则","t":"rule"},{"q":"在比劫与财的双向制局中，「比劫制财」与「财制比劫」在取象上有何不同？","opts":["比劫制财是合伙易得财，财制比劫比劫当财看","比劫制财主破财辛苦，财制比劫主合伙取财","两者均直接代表夺妻克父，毫无区别","比劫制财必为高官，财制比劫必为穷苦之人"],"ans":0,"exp":"比劫制财是合伙、同伴取财，得财容易；财制比劫时，被制的比劫要换象，当财看。","sec":"（一）比劫与财","t":"diff"},{"q":"盲派俗称「制不了老子制小子」，在墓库制局中指的是什么现象？","opts":["印星制不了，专门去制印星所生的比劫禄神","墓库无刑冲难制库中物，大运出现即被原局制","月令旺神制不了，专门去制天干虚透的十神","年支长辈制不了，专门去制时支的子女星"],"ans":1,"exp":"墓库无刑冲通常制不了库中遁藏；但遁藏之物一旦在大运出现，就可被原局制去，俗称“制不了老子制小子”。","sec":"（二）比劫与官杀","t":"rule"},{"q":"女命八字中，官杀星居「日支夫宫」与居「月令」在类象上有何重要区分？","opts":["不论居日支还是月令，女命官星一律只代表丈夫","日支官被制反主升官，月令官被制才主克夫","日支官不代表工作而代表夫，月令官才代表工作","日支官专门代表工作职务，月令官才代表丈夫"],"ans":2,"exp":"女命官杀居夫宫就当夫星看，得正位被制则克夫；日支官不代表工作（代表夫），月令官才代表工作。","sec":"（二）比劫与官杀","t":"diff"},{"q":"「官杀制比劫」（含官杀库、比劫库）这类制局配置，大多主什么命？","opts":["多是艺人，专门靠体力竞争与口才成名","多是僧道，一生清贫孤苦不问世事","多是穷命，比劫被官杀制尽则毫无靠山","多是官命，羊刃有功还主武职，比劫换象当财"],"ans":3,"exp":"官杀制比劫（官杀的墓库、比劫的墓库也算在内）多是官命，羊刃有功还主武职，被制的比劫要换象当财看。","sec":"（二）比劫与官杀","t":"xiang"},{"q":"原局做功本要制去某一个字，若大运反而出现「保护被制者」的字（如辰合绊酉），叫什么？","opts":["反局，原局做功被破坏主凶","通关，原局凶神被感化转吉","开库，原局之功在大运加倍兑现","换象，被制者反过来生旺日主"],"ans":0,"exp":"规则：运中保护被制者之字（如原局制酉，辰运辰合绊酉保护酉），就是“反局”，主失官或大凶。","sec":"（三）伤食与官杀","t":"rule"},{"q":"「官杀制伤食」或「杀库制伤官库」的制局配置，通常多在哪个系统任职？","opts":["高校教授，专攻纯理论学术研究","官命，且常见于公检法系统","演艺界名人，靠歌唱或表演取财","企业高管，专管财务与资金流转"],"ans":1,"exp":"官杀制伤食多为官命，且常见公检法；官制伤官要换象，伤官当权力看；杀（库）制伤官（库）多供职于公检法。","sec":"（三）伤食与官杀","t":"xiang"},{"q":"在「印制食伤」结构中，男命与女命的做功类象有何区别？无财时伤官怎么看？","opts":["男命印制伤不主权，女命印制伤必为高官","不论男女一律主掌大权，无财则印星当财看","男多官命女不主权（有官杀另论），无财伤官当财","印制食伤只能代表穷苦体力劳动者，绝不当官"],"ans":2,"exp":"印制食伤多为官命，但女命印制伤不主权（有官杀则以官杀当权）；八字无财时，伤官当财看，制伤得财。","sec":"（四）印星与食伤","t":"diff"},{"q":"在盲派制局中，日支坐下为「食神」与为「伤官」在被制时的体用倾向有何不同？","opts":["食神与伤官皆纯属外用之神，被制毫无伤体之忧","伤官偏于体，落日支被制必伤日主寿命","食神被制永远主发大财，伤官被制永远主坐牢","食神偏于体，落日支有功被制要伤体"],"ans":3,"exp":"坐支食神被制有不吉的一面：食神偏于体，不像伤官偏于用，食神落日支而有功时，被制要伤体。","sec":"（四）印星与食伤","t":"diff"},{"q":"在「食伤制印」做功的结构中，被制的印星在大运中喜以什么形态出现？","opts":["喜印星在大运中虚透","喜印星在大运中坐强根临旺地","喜财星在大运中生旺印星之党","喜大运再见官杀去生扶原局印星"],"ans":0,"exp":"规则：制印结构喜印星在大运中虚透（被制者实而运中虚透为吉，主升官）。","sec":"（四）印星与食伤","t":"rule"},{"q":"财制印结构中，若是以「羊刃库制印」（如未穿子）做功，命主职业常与什么有关？","opts":["与演艺戏曲有关","与公检法有关","与远洋航运有关","与餐饮美食有关"],"ans":1,"exp":"财制印去印得权，为官者不少；其中羊刃库制印（如未穿子），职业常与公检法或军队军权有关。","sec":"（五）财星与印星","t":"xiang"},{"q":"在印制财的取象中，天干辛金坐于未土之上（辛未组合）常可具体类象为什么物品？","opts":["棉花","石油","大蒜","翡翠"],"ans":2,"exp":"坤造壬丙己辛／子午巳未做海外贸易，辛坐未主大蒜（仅辛坐未时主大蒜）。","sec":"（五）财星与印星","t":"xiang"},{"q":"在日主坐支「连根筋」的经验规则中，辛丑、癸丑日柱的坐支能否被制？","opts":["属于绝对连根，一旦被制必然立刻伤寿","必须逢大运冲开才能制，原局制之必亡","辛丑日柱绝不可制，癸丑日柱则可以制","虽是坐根，但其地支可以制，对健康无妨"],"ans":3,"exp":"十二个连根日柱坐支不可制；但辛丑、癸丑也是坐根，其地支可以制，对健康无妨。","sec":"（一）日主之根不可制","t":"diff"},{"q":"甲乙活木的年支之根大都可制，但在什么情况下年支之根也不可制？","opts":["年支与日支相合能生扶日支而成根时","年支为金水财星且居于空亡之地时","年干透出正官或七杀克制日主时","年支为燥土墓库且与日支相穿时"],"ans":0,"exp":"活木年上的根大都可制，但个别年支之根也不能制，如年支亥水与日支卯禄半合，亥卯合能生卯而成根，则亥不可伤。","sec":"（二）甲乙活木：根不可伤","t":"rule"},{"q":"富贵八字讲究「有气势且有功」，但前提红线是什么？","opts":["气势必须来自月令，时支成势不算有功","气势不能与日主的意向相悖（不坏日主之根）","必须天干透出比劫与食伤，否则不能论富贵","气势必须是木火成势，金水成势不能富贵"],"ans":1,"exp":"富贵八字有气势且有功，但气势不能与日主的意向相悖；若气势反过来制坏日主之根，势再大也有害无益。","sec":"（四）势要与日主意向一致","t":"rule"},{"q":"制用结构中，若制法效率高，但「被制者本身力量太弱」，结果如何？","opts":["主日主必定早夭，寿元受损","功反而越大，主成为亿万富翁","功也小，层次降低","直接变为化用结构，主高官厚禄"],"ans":2,"exp":"制用要看效率也要看大小：被制者制得好效率高，但若被制者本身太弱，做功也小，层次会降低。","sec":"（五）制得好不好：看效率","t":"rule"},{"q":"在盲派地支合制的效率排序中，排在「次高」档次的是哪一组？","opts":["子丑合、寅丑暗合","卯未半合、亥未拱合","寅亥合、辰酉合、午戌合","卯戌合、卯申合、午亥合、巳酉半合"],"ans":3,"exp":"口诀：巳申最高，卯戌、卯申、午亥、巳酉半合次高，子丑、寅丑中，同党合制低，午未不为制。","sec":"（一）合制","t":"step"},{"q":"为什么「寅亥合、辰酉合、午戌合」在地支合制中效率较低？","opts":["相合双方为同党，只是遁藏人元被制","相合双方力量太弱，完全无法发生作用","相合之后变成半合局，把被制者保护起来","这三组全属于相破关系，只表象不做功"],"ans":0,"exp":"寅亥合、辰酉合、午戌合为同党相合，只是遁藏被制（如亥中壬灭寅中丙、酉制辰中乙、午中丁制戌中辛），效率较低。","sec":"（一）合制","t":"rule"},{"q":"关于日主之「禄」的合官与位置禁忌，下列哪一项符合盲派规则？","opts":["禄在年月绝不可制，坐下之禄反可任制","禄合官不为官，禄在时上可冲不可穿","禄在时上不论冲穿，见之必主早年克父","禄合官必为高官，禄在时上可穿不可冲"],"ans":1,"exp":"提示：禄合官不为官；禄在年月可制；禄在时上可冲不可穿；日主坐下的禄（或日主之根）制之恐伤寿。","sec":"（一）合制","t":"rule"},{"q":"当原局时支的「禄」参与做功时，为什么口诀说「大运最怕复吟禄」？","opts":["大运复吟会使禄神入墓，永远不再做功","大运复吟会使财库闭塞，彻底失去财运","大运复吟即表示禄“走了”，主凶","大运复吟会导致禄神变成七杀反克日主"],"ans":2,"exp":"原局时支禄做功，大运最怕复吟禄（即大运再见同字之禄），复吟即禄“走了”，往往应凶事或寿劫。","sec":"（二）冲制、刑制","t":"rule"},{"q":"「围克」是克制中唯一效率很高的例外，在围克结构中什么因素起很大作用？","opts":["被克者的原神起很大作用","大运的纳音五行起很大作用","空亡的地支起很大作用","势中的天干起很大作用"],"ans":3,"exp":"围克包围制之，被制之神无处可逃，制得干净，往往成贼捕结构；围克中，势中的天干起很大作用。","sec":"（三）克制","t":"rule"},{"q":"按盲派地支阳干羊刃取法，戊土日主的羊刃在哪个地支？","opts":["未","辰","戌","午"],"ans":0,"exp":"盲派提示：戊土之羊刃在未（如戊土坐未或时见未，既是羊刃也是官杀库）。","sec":"（四）穿制","t":"calc"},{"q":"当「主位与财星相穿」时，男命与女命在婚姻和财运上各自常有什么表现？","opts":["男命主穿制发巨财，女命主靠丈夫致富","男命与婚无缘但财可，女命与财穿一生无财","男命一生无财但婚好，女命财旺但克夫","男女命皆必同时破大财且一生无婚姻"],"ans":1,"exp":"主位与财不能相穿，穿则与财不和；男命主位与财相穿一生与婚姻无缘但财运可以，女命与财相穿则一生无财。","sec":"（四）穿制","t":"diff"},{"q":"以体力、技艺取财的名人命局中，「七杀（官杀）虚透天干」与「丙丁火做功」分别主什么？","opts":["七杀虚透主无名无权，丙丁主纯做体力苦力","七杀虚透主牢狱之灾，丙丁主从事公检法工作","七杀虚透主名气荣誉，丙丁主名气演艺影视","七杀虚透主大富亿万，丙丁主在政府掌管财政"],"ans":2,"exp":"名人命局规律：七杀（官杀）虚透天干主名气、名望、荣誉、地位；丙丁火做功或为日主主名气、出名、演艺、影视。","sec":"五、名人命局汇粹：体力与技艺取财","t":"xiang"},{"q":"在盲派关于「禄」的喜忌经验中，为什么通常不喜原局「禄多」？","opts":["禄多代表大富大贵，只是最怕逢大运生扶","禄多必定入墓，只要入墓就彻底做不了功","禄多必然克父克妻，一生孤苦无依","一般禄不喜多而喜静，禄多则身忙心乱"],"ans":3,"exp":"一般禄不喜多而喜静，禄多则身忙心乱；但若禄会局成党有气势、又逢印，则是有福而非辛苦劳动者。","sec":"五、名人命局汇粹：体力与技艺取财","t":"rule"}]},{"n":16,"level":"初级","title":"应期入门","qs":[{"q":"某件事在原局落在日柱，大限上大致应在哪个年龄段？","opts":["35—55 岁","18—35 岁","1—18 岁","55 岁以后"],"ans":0,"exp":"年柱1—18，月柱18—35，日柱35—55，时柱55岁以后；大限只是模糊概括。","sec":"二、大限应期","t":"calc"},{"q":"原局大限应凶（如克父），而对应的那步大运是吉运，该怎么断？","opts":["此运不凶，过运也不再凶","此运不凶，过了此运才凶","此运先吉后凶，运中即应","此运照样凶，吉运压不住"],"ans":1,"exp":"交脱诀：限应凶而逢吉大运，则过运应凶，不看应期。","sec":"二、大限应期","t":"rule"},{"q":"原局大限应凶，应期尚未走到吉运之前，凶应不应？","opts":["不应，凶要等吉运过后","半应，只应一半","照样应，未到吉运必见凶","不应，吉运提前化解了"],"ans":2,"exp":"限应凶、后逢吉大运，则未到吉运前凶照应；吉运里才是吉。","sec":"二、大限应期","t":"rule"},{"q":"按盲派，原局的字在运岁中「出现」（反客为主），有哪两种方式？","opts":["现原身，或逢六合","通禄，或逢三合","逢冲，或逢入墓","通禄，或现原身"],"ans":3,"exp":"原局之字在运岁见它的禄，或在运岁天干透出它的原身，就是该字到了。","sec":"三、反客为主（出现）","t":"rule"},{"q":"日主之禄在日柱之前的年、月，对应大运再见禄，是不是寿到？","opts":["不是，只日柱及以后的大限才怕见禄","是，但只限男命","不是，但见禄必有大灾","是，见禄即寿到"],"ans":0,"exp":"禄在日柱之前，对应运见禄不是寿到；晚年及时柱的禄，运岁再见才寿到。","sec":"三、反客为主（出现）","t":"rule"},{"q":"要用的字和要去的字，在大运虚透时各是什么结果？","opts":["要用之字虚透则吉；要去之字虚透则不吉","要用之字虚透则不吉；要去之字虚透则吉","两者虚透都吉，因虚主轻化","两者虚透都不吉，应期落空"],"ans":1,"exp":"要用的字怕虚透、喜见实；要去的字喜虚透、怕见实。","sec":"四、虚透与用忌的应期","t":"diff"},{"q":"原局是贼捕结构（被制之神制得干净），大运流年喜见哪一边？","opts":["贼、捕都不喜，要见别的字","贼、捕都喜，见即有应","喜见贼，不喜只见捕不见贼","喜见捕，不喜见贼"],"ans":2,"exp":"贼指被制之字，捕指制它的字；局成贼捕，运岁见贼为吉。","sec":"四、虚透与用忌的应期","t":"rule"},{"q":"原局不成贼捕、被制之神制得不干净，运岁喜见什么？","opts":["喜见主制之神的克神","喜见被制之神","喜见被制之神的原神","喜见主制之神"],"ans":3,"exp":"制不净则需运岁再来补制，所以喜见主制之神；成贼捕的才喜见贼。","sec":"四、虚透与用忌的应期","t":"rule"},{"q":"原局有戌，运岁天干透出丁火，按盲派应怎么看？","opts":["丁代表戌，等同戌到","丁代表午，与戌无关","丁只主火气，不代表地支","丁与戌相克，主戌受伤"],"ans":0,"exp":"地支遁藏的字在运岁天干出现，就是该地支的应期，作用等同于该地支。","sec":"五、遁藏透干与刑冲合穿墓的应期","t":"calc"},{"q":"「合者主到，冲者主动，墓者主收，穿者主伤」，下列对应哪组是对的？","opts":["合主动起来，墓主受伤","冲主动起来，穿主受伤","冲主受伤，穿主动起来","墓主动起来，穿主到位"],"ans":1,"exp":"口诀是合到、冲动、墓收、穿伤；作用到谁，谁就应事。","sec":"五、遁藏透干与刑冲合穿墓的应期","t":"diff"},{"q":"原局午未合、夫宫未被合住，运岁见丑，对婚姻应期怎么论？","opts":["丑与午相穿，主婚破","丑与未无关，不应事","丑冲开所合的未，是结婚应期","丑合住午，主婚不成"],"ans":2,"exp":"原局夫宫逢合、运岁逢冲刑，冲开所合主婚成；合与冲互为解、促。","sec":"六、婚姻应期","t":"calc"},{"q":"配偶星在年月和在日时，对婚期早晚各有什么提示？","opts":["年月早婚，日时必不婚","在年月相对晚婚，在日时相对早婚","年月日时都一样，只看大运","在年月相对早婚，在日时相对晚婚"],"ans":3,"exp":"配偶星位置靠前则早婚、靠后则晚婚；前提是配偶星必须与夫妻宫有关系。","sec":"六、婚姻应期","t":"rule"}],"fine":[{"q":"八字、大运、流年三者在断命中的分工口诀是什么？","opts":["八字分贵贱，大运判吉凶，流年看应期","八字判吉凶，大运分贵贱，流年看应期","八字看应期，大运分贵贱，流年判吉凶","八字分贵贱，大运看应期，流年判吉凶"],"ans":0,"exp":"口诀为「八字分贵贱，大运判吉凶，流年看应期」，三者配合才能把原局已有之事定到具体时段。","sec":"一、什么是应期","t":"step"},{"q":"按盲派应期观，大运和流年与原局之间的关系实质上是什么？","opts":["只看流年干支生克，不必理会原局已有之象","只是对原局里已有之事在时间上的应验","可以凭空生出原局完全没有记载的新吉凶","能够脱离原局独立决定命主一生的贵贱"],"ans":1,"exp":"原局已预示富贵贫贱与一生大事，大运和流年只是对原局已有之事在时间上的应验。","sec":"一、什么是应期","t":"rule"},{"q":"大限应期中，年柱、月柱、时柱分别对应人生的哪个年龄段？","opts":["年1—18岁、月18—36岁、时50岁以后","年1—15岁、月15—30岁、时50岁以后","年1—18岁、月18—35岁、时55岁以后","年1—20岁、月20—40岁、时60岁以后"],"ans":2,"exp":"四柱大限为年柱1—18岁、月柱18—35岁、日柱35—55岁、时柱55岁以后，只是模糊笼统的时间概括。","sec":"二、大限应期","t":"calc"},{"q":"原局大限应吉，而对应的那步大运却应凶，按交脱诀应怎么断？","opts":["此运不吉，且过运后也不再应吉","此运先凶后吉，后五年即应吉","此运照样吉，大限可以压住大运","此运不吉，过了这步大运才吉"],"ans":3,"exp":"交脱诀：八字之运限应吉，但逢凶大运，则过运应吉，不看应期。","sec":"大限与大运的配合","t":"rule"},{"q":"原局大限应凶，中间遇到一步吉运，在这步吉运本身之中吉凶如何？","opts":["这步吉运仍然论吉，未到之前才见凶","这步吉运论凶，过了吉运才开始转吉","这步吉运依然论凶，吉运压不住原局","这步吉运先凶后吉，凶吉各占一半"],"ans":0,"exp":"原局大限应凶而中间遇吉运，吉运里仍然是吉，只是还没走到吉运之前，该应的凶照样应。","sec":"大限与大运的配合","t":"rule"},{"q":"盲派将「运岁出现原局已有的字」称为反客为主，其中主与客分别指什么？","opts":["年柱月柱是客，日柱时柱与流年是主","八字里的字是主，大运流年的字是客","日主和坐支是主，其余六字与运岁是客","大运流年是主，八字原局的字是客"],"ans":1,"exp":"八字里的每个字都是主，大运、流年的字都是客；运岁出现原局之字就是该字到了，叫反客为主或出现。","sec":"基本概念","t":"rule"},{"q":"原局某个字为凶，当大运中「出现」这个字时，按出现法则怎么断？","opts":["要看是否通禄，现原身则凶而通禄则吉","大运出现只主变动，本身不分吉凶","为凶的应期，原局吉凶与应期同论","反客为主化凶为吉，此运必见喜事"],"ans":2,"exp":"口诀：原局之字为凶，大运出现该字为凶的应期；原局之字为吉，大运出现该字为吉的应期。","sec":"基本概念","t":"rule"},{"q":"晚年禄到时，最怕运岁对禄产生什么作用？其中哪种组合多主凶死？","opts":["怕生扶合旺，寅禄见亥合多主凶死","怕透干虚浮，卯禄见甲透多主凶死","怕泄秀过重，午禄见未合多主凶死","怕冲刑破穿入墓，酉禄被戌穿多主凶死"],"ans":3,"exp":"晚年禄到最怕被冲、刑、破、穿、入墓，尤其禄为酉而被戌穿，多主凶死。","sec":"禄与寿","t":"rule"},{"q":"乾造乙己己庚／巳丑未午，行壬午运癸卯年去世，其看寿应期机制是？","opts":["晚年午禄到即寿到，卯破午坏禄而亡","乙木七杀透干无制，卯年杀旺克身亡","庚金伤官入丑墓，癸卯年开墓而亡","壬水财星虚透无根，卯年泄水而亡"],"ans":0,"exp":"午火是己土之禄，晚年壬午运禄到即寿到；流年癸卯破午，加之原局午被丑穿本已有伤，破禄而亡。","sec":"禄与寿","t":"xiang"},{"q":"坤造庚辛辛癸／寅巳酉巳，壬午年遇害且损子，为何应于壬午年？","opts":["寅木财星为寿元星，壬午年寅午半合泄尽而亡","癸水食神当寿元兼子女，丙子运变实遇午冲坏禄","巳火官星为寿元星，丙子运子水冲巳火而亡","辛金日主坐酉禄，壬午年午火克破酉金而亡"],"ans":1,"exp":"癸水食神当寿元星兼主子女，原局在干为虚，丙子运变为地支子水而实，壬午年午冲子坏禄，故与子同遇害。","sec":"禄与寿","t":"xiang"},{"q":"运中出现「要用之字」与「要去之字」时，两者对受制的喜忌有何不同？","opts":["要用之字喜被制，要去之字怕受制","两者在运中出现都最怕受制","要用之字怕受制，要去之字喜被制","两者在运中出现都最喜被制"],"ans":2,"exp":"口诀：运中出现要用之字，怕其受制，受制不吉；运中出现要去之字，喜其被制，被制则吉。","sec":"要用之字、要去之字","t":"diff"},{"q":"乾造辛丙辛癸／卯申未巳，癸水食神宜虚宜制，行戊子运戊申年亡，原因何在？","opts":["卯木印星被申金暗合制死，寿元断绝而亡","戊土伤官透干克癸，申年土旺水绝而亡","巳火官星被申合住，失去了保护日主之力","子为癸禄使其变实，申子半合水局大旺违背原局"],"ans":3,"exp":"癸水在局中宜虚、宜被制；戊子运子为癸禄而变实，戊申年申子半合水局大旺，与原局意思完全相反。","sec":"要用之字、要去之字","t":"rule"},{"q":"乾造丙辛丁丙／午卯卯午成贼捕结构，行甲午运时庚辰、辛巳年反得大财，为什么？","opts":["午运见捕不见贼本不吉，流年见庚辛贼神而得财","丙辛合在午运被午火冲开，流年合回辛金而得财","甲木印星生助午火，流年辰巳晦火生金而得财","原局贼捕结构最喜见捕，午运逢辰巳助旺而得财"],"ans":0,"exp":"局成贼捕喜见贼神，甲午运午运见捕不见贼本不吉，但庚辰、辛巳流年见贼神庚辛金，故得大财。","sec":"贼捕结构","t":"calc"},{"q":"乾造丙辛丁丙／午卯卯午与丙辛丁壬／午卯卯子前三柱相同，为何后者甲午运反喜午火？","opts":["后者水火既济成化用格，甲午运生助午火更贵","后者时柱壬子官杀无制不成贼捕，午到可直接冲子","后者午火为日主之禄，运中见禄主得财发福","后者辛金已被丙合净，午火不再需要制金"],"ans":1,"exp":"后者时柱壬子与辛为一党且官杀无制，不是贼捕结构；原局午远不能冲子，甲午运午到可直接冲制子水而发财。","sec":"贼捕结构","t":"diff"},{"q":"原局穿制子水时，大运行癸卯运是否一定论吉？","opts":["一定论凶，因卯木泄水生火坏了穿制","一定论吉，因癸为子水虚透，见虚即吉","不一定，须看癸是否虚透无生且被制","一定论吉，因卯木能直接穿倒子水之根"],"ans":2,"exp":"原局穿制子，行癸卯运要看癸是否被制住、有无生助：癸无制或有生则不行，癸虚透无生而被制才论吉。","sec":"补充问答（虚透与制）","t":"rule"},{"q":"原局有申酉金为财，大运见丑使申酉入丑墓，是否必然得财？","opts":["必然得财，财星入库即为收财入囊之应","只要地支见丑就得财，与大运天干无关","必然破财，因金入墓库后财星失去作用","不一定，要看日主与大运干支具体配合"],"ans":3,"exp":"原局有申酉见丑运入墓不一定得财，同样是丑，丁丑日主走癸丑运不得财，走丁丑运则得财。","sec":"补充问答（虚透与制）","t":"rule"},{"q":"当命局或运岁天地合制地支时，若再遇到地支相冲或相穿，吉凶如何？","opts":["不好，天地合制忌地支再遇冲穿","大吉，冲穿能加速合制把对象制死","冲则吉而穿则凶，不可一概而论","无妨，天地合制力量强不受冲穿影响"],"ans":0,"exp":"天地合制地支时，遇到地支再冲、穿也不好，会干扰或破坏原有的合制做功。","sec":"补充问答（虚透与制）","t":"rule"},{"q":"乾造甲庚辛壬／辰午亥辰，甲戌运甲申年离婚，其妻宫与财星的作用机制是？","opts":["辰土劫财库在戌运被冲开，申年合辰夺财而离","亥中甲财透干有走了之意，流年申又穿妻宫亥","甲木正印透干合绊日主，申年冲辰开墓而离","午火七杀在戌运入墓，申年财星生杀克身而离"],"ans":1,"exp":"亥为妻宫且藏甲财，甲申年甲木财星虚透，透干有走了之意，又流年申穿妻宫亥，故此年离婚。","sec":"遁藏透干","t":"xiang"},{"q":"流年冲大运时，大运「当运」与「不当运」在断法上有何区别？","opts":["当运只主工作变动，不当运只主破财伤身","当运为冲起更旺，不当运为冲去无用","当运为冲去，不当运为冲起而提前起作用","当运与不当运均为冲去，只看流年力量"],"ans":2,"exp":"流年冲大运要看当运不当运：当运为冲去，不当运为冲起，使该运提前起作用。","sec":"刑冲合穿墓的应期","t":"diff"},{"q":"局中本弱之字逢流年相冲，与局中旺字逢流年相冲，含义有何不同？","opts":["局弱与局旺逢冲都主破败，只是轻重不同","局弱冲而动起来，局旺逢冲则主破败受伤","局弱逢冲反能生旺，局旺逢冲则主静止不动","局弱冲而破不是动，局旺逢冲才是动的应期"],"ans":3,"exp":"局中本弱的，被冲而破，不是动；局中旺的，逢流年冲才是动的应期。","sec":"刑冲合穿墓的应期","t":"diff"},{"q":"原局本来有相合，运岁再来冲这个合字，盲派如何定义这种作用？","opts":["并非冲开，而是冲合之应，冲使合动促成合","合冲互相抵消，该年平淡无事也不应期","必然冲开原局之合，使合局彻底解散失效","只有六合会被冲开，三合则不会被冲开"],"ans":0,"exp":"原局合、运岁来冲，并非冲开，而是「冲合之应」：冲有动意，使合动而促成合的应事。","sec":"刑冲合穿墓的应期","t":"rule"},{"q":"原局旺字被运岁穿，与原局衰字被运岁穿，后果有何不同？","opts":["旺者被穿主发财，衰者被穿主破财","旺者被穿主该字难受，衰者被穿则可能出凶","旺者与衰者被穿均主出凶，没有轻重之分","旺者被穿必出大凶，衰者被穿只主心里难受"],"ans":1,"exp":"原局的旺字被运岁穿，对方奈何不了它，只主该字难受；原局衰者被穿，则可能出凶。","sec":"刑冲合穿墓的应期","t":"diff"},{"q":"判断结婚应期时，原局的财或官杀要能当配偶星论，必须满足什么前提？","opts":["必须透出在年干或月干，否则不当配偶星论","必须坐于日支本气之内，他支一律不当配偶星","必须与日干或日支有合、冲、入墓或换象等关联","只要八字里有财或官杀，不论位置都当配偶星"],"ans":2,"exp":"原局配偶星必须和夫妻宫有关系（三合、五合、六合、暗合、相冲、入墓、禄与原身换象等），无关系者不当配偶星论。","sec":"总则","t":"rule"},{"q":"除配偶星在日时外，男女命还有哪种年月柱特征也属于晚婚标志？","opts":["女命年月财星旺，男命年月印星旺","女命年月比劫旺，男命年月食伤旺","女命年月印星旺，男命年月官杀旺","女命年月食伤旺，男命年月比劫旺"],"ans":3,"exp":"女命年月食伤旺，可断晚婚；男命年月比劫旺，也是晚婚标志。","sec":"总则","t":"diff"},{"q":"婚姻应期中，「合留」与「合解冲」分别指哪种情况？","opts":["合留是局运旺星干被合，合解冲是原有冲刑逢合年成婚","合留是冲开原局之合，合解冲是太岁合住夫妻宫","合留是男命专用法则，合解冲是女命专用法则","合留是地支三合入宫，合解冲是天干五合日主"],"ans":0,"exp":"合留指原局或大运原有旺相配偶星在天干，再逢运岁来合；合解冲指原有配偶星逢冲刑，逢太岁合的流年婚成。","sec":"常见四种看法","t":"diff"}]},{"n":17,"level":"初级","title":"基础问题","qs":[{"q":"按盲派粗略起运法，生日距节令8天，起几岁运？","opts":["4岁","3岁","1岁","2岁"],"ans":1,"exp":"天数差除以3：8÷3＝2余2，余2进1，得3岁。","sec":"起运岁数","t":"calc"},{"q":"盲派粗略起运法，起运岁数有什么上下限？","opts":["最小3岁，最大12岁","最小0岁，最大10岁","最小1岁，最大10岁","最小1岁，最大8岁"],"ans":2,"exp":"起运岁数最小1岁、最大10岁，4天以内都按1岁运，且按虚岁计。","sec":"起运岁数","t":"rule"},{"q":"盲派交运的时辰，按什么来定？","opts":["出生时辰的五行","日主的五行","出生月令的五行","年的纳音五行"],"ans":3,"exp":"交运时辰按年的纳音五行定：火命、土命、金命、木命、水命各有固定节气与时辰。","sec":"交运时间","t":"rule"},{"q":"年纳音为水命的人，交运时间是哪个？","opts":["冬至前三天亥时","大寒当日寅时","清明前三天午时","处暑当日申时"],"ans":0,"exp":"水命人冬至前三天亥时；火命清明前三天午时；金命处暑当日申时；木命大寒当日寅时；土命芒种后九天辰时。","sec":"交运时间","t":"calc"},{"q":"丙日早子时的时柱是戊子。按盲派，丙日夜子时的时柱是什么？","opts":["壬子","庚子","戊子","丙子"],"ans":1,"exp":"夜子时的纳干要从早子时数一圈后纳：戊子往后数满十二个时辰，得庚子（与乙日早子丙子→夜子戊子同法）。","sec":"二、子时","t":"calc"},{"q":"夜子时与早子时的区别，按盲派怎么讲？","opts":["早子时与夜子时按同一天算，时干完全相同","早子时是23至24点，夜子时是0至1点，二者纳干相同","早子时是0至1点，夜子时是23至24点，夜子时干要数一圈","夜子时按次日起时干，早子时按当日起时干"],"ans":2,"exp":"以24点换日，早子时为当日凌晨0—1点，夜子时为当日深夜23—24点；夜子时时干从早子时数一圈后纳。","sec":"二、子时","t":"diff"},{"q":"盲派说的「正用」与「反用」，区别是什么？","opts":["正用是宾位的体制主位的用；反用是体落主位、用落宾位","正用是原局作功；反用是大运作功","正用是日主制官杀；反用是官杀制日主","正用是主位的体制宾位的用；反用是用落主位、体落宾位"],"ans":3,"exp":"口诀：正用——主位的体，制宾位的用；反用——用的东西落在主位，体落在宾位。","sec":"三、如何看八字：宾主与正用、反用","t":"diff"},{"q":"功神、废神、忌神三者，哪个说法对？","opts":["能做功的是功神，不能做功的是废神，起坏作用的是忌神","能做功的是用神，不做功的是忌神，起坏作用的是废神","旺的是功神，弱的是废神，克日主的是忌神","能做功的是功神，不做功的是忌神，起坏作用的是废神"],"ans":0,"exp":"能做功的神叫功神，不能做功的叫废神，坏事的叫忌神；本体系所说用神实际就是功神。","sec":"基本概念","t":"diff"},{"q":"合制中，下列哪个效率最高？","opts":["寅亥合","巳申合","卯戌合","午戌合"],"ans":1,"exp":"巳申合效率最高，原神用神都能制死；卯戌、卯申、午亥、子丑、寅丑也较高；寅亥合、午戌合很低。","sec":"制用结构中效率高低","t":"step"},{"q":"克制中，效率最高与最低的分别是哪两种？","opts":["贴克最高，围克最低","围克最高，天克地最低","围克最高，贴克最低","天克地最高，围克最低"],"ans":2,"exp":"围克效率最高（如丙戌丙申围住申金），天克地也行但天干必须有势；贴克很低，特别费劲。","sec":"制用结构中效率高低","t":"step"},{"q":"冲制中，哪种冲的效率最高？","opts":["四正位互冲，旺冲衰最好","天干相冲，隔位冲最好","地支相冲，冲日支最好","库冲，挨住冲最好"],"ans":3,"exp":"冲制以库冲效率最高，挨住冲最好；挨不住冲效率也不行。","sec":"制用结构中效率高低","t":"rule"},{"q":"反局为什么叫最凶？它分哪两类？","opts":["原局反局与大运反局，出灾、破财、死亡","合局反局与冲局反局，主疾病、出灾","日主反局与月令反局，主丧偶、破财","原局反局与流年反局，主官非、破财"],"ans":0,"exp":"反局是日主（或日柱）所表意思与八字整体意思相反，分原局反局与大运反局；大运反局要出灾，比原局反局多见。","sec":"五、正局与反局入门","t":"diff"}],"fine":[{"q":"按盲派粗略起运法，生日距节令天数差分别为 3 天和 10 天时，各起几岁运？","opts":["3天起2岁运，10天起3岁运","3天起1岁运，10天起3岁运","3天起1岁运，10天起5岁运","3天起1岁运，10天起4岁运"],"ans":1,"exp":"4天以内都按1岁运；10除以3商3余1，口诀余1舍去，故10天起3岁运。","sec":"起运岁数","t":"calc"},{"q":"盲派粗略起运法计算出的起运岁数，是按周岁还是虚岁计算？","opts":["阳男阴女按虚岁，阴男阳女按周岁","十岁以下按虚岁，十岁以上按周岁","按虚岁计算","按周岁计算"],"ans":2,"exp":"盲派粗略起运法取生日距节令天数差除以3，所得起运岁数一律用虚岁计。","sec":"起运岁数","t":"rule"},{"q":"年纳音为火命人与土命人，交运时间分别在何时？","opts":["火命冬至前三天午时，土命芒种前九天辰时","火命处暑当日午时，土命大寒后九天辰时","火命清明当日午时，土命立夏后九天辰时","火命清明前三天午时，土命芒种后九天辰时"],"ans":3,"exp":"交运时辰口诀：火命清明前三天午时，土命芒种后九天辰时，金命处暑当日申时，木命大寒当日寅时，水命冬至前三天亥时。","sec":"交运时间","t":"calc"},{"q":"交运时间表中「清明前三天」「芒种后九天」的天数计算是否包括节气当天？","opts":["包括节气这一天","只看交节气具体时刻，不按整天计算","不包括节气这一天，须从次日起算","前三天包括当天，后九天不包括当天"],"ans":0,"exp":"盲派交运时间表中，「前三天」「后九天」均包括节气这一天在内。","sec":"交运时间","t":"rule"},{"q":"盲派关于交运时的注意事项，下列哪项符合要求？","opts":["交运当日须禁食一天，七日内不准见属相相合者","交运时不要外出，三日内忌参加红白喜事","只要时辰合局即可随意外出，不必忌红白喜事","交运时宜远行避煞，三日内多见亲友冲喜"],"ans":1,"exp":"交运时不要外出，怕与自己属相不和的人相冲；还要在三日之内忌参加红白喜事。","sec":"交运的注意事项","t":"rule"},{"q":"盲派划分早子时与夜子时，以几点作为分天数的交界？","opts":["晚 11 点（23 点换日）","按当地太阳正午或平旦为准","晚 12 点（24 点换日）","凌晨 1 点（1 点换日）"],"ans":2,"exp":"子时以晚12点为交界，12点分天数（即以24点换日），0—1点为早子时，23—24点为夜子时。","sec":"二、子时","t":"rule"},{"q":"按宾主法看八字，最先应从哪两个位置入手？","opts":["月干和年支","年柱和月令","时干和时支","坐支和日主"],"ans":3,"exp":"看八字的重要概念是宾主，首先从坐支和日主入手，以此分辨主位与宾位。","sec":"三、如何看八字：宾主与正用、反用","t":"step"},{"q":"盲派体系对「合财看身强身弱」「身旺财旺」这类说法持什么态度？","opts":["属于早期说法，本体系不采用","只看合财时采用，冲财时不采用","仅适用于普通命局，不适用于贵格","是判断正用结构财运的核心准则"],"ans":0,"exp":"「合财看身强身弱」「身弱财旺」等属于早期说法，盲派做功体系不采用旺衰论。","sec":"正用：主位的体制宾位的用","t":"rule"},{"q":"反用结构中，当日主本身在局中没有直接用途时，应先看哪里、如何找做功？","opts":["直接以身弱论命，喜大运比劫帮身","看坐支有什么用，看财印等如何做功","只看年柱和月令的干支生克关系","放弃主位，专在宾位找天干五合"],"ans":1,"exp":"日主没有用途时看坐支，看坐支有什么用；财旺要做事，做了才显出财的威力。","sec":"反用：用的东西落在主位，体落在宾位","t":"rule"},{"q":"在盲派理论中，「功」的基本定义是什么？","opts":["天干五合与地支三合，叫做功","日主得令通根且见财官，叫做功","能量转化为效率，叫做功","五行生克达到中和平衡，叫做功"],"ans":2,"exp":"能量转化为效率，叫做功；八字里每个字都有能量，通过刑冲化合等作用产生效率，完成做功。","sec":"基本概念","t":"rule"},{"q":"八字中天干与地支在能量强弱上有何差别？","opts":["天干与地支能量完全相等","天干能量强，地支能量弱","阳干支能量强，阴干支能量弱","天干能量弱，地支能量强"],"ans":3,"exp":"八字里每个字都有能量，天干能量弱，地支能量强；做功主要靠地支的刑冲化合。","sec":"基本概念","t":"diff"},{"q":"普通八字通常具有哪三个特点？","opts":["废神多、效率低、对功神有损坏","没有合冲、只看五行、全盘平衡","气势大、无废神、全盘皆是功神","用神旺、忌神弱、天干地支全合"],"ans":0,"exp":"普通八字的特点是：1.废神多；2.效率低；3.对功神有损坏，不可能每个字都有用。","sec":"基本概念","t":"rule"},{"q":"盲派认为大格局八字最核心的特征是什么？","opts":["日主不旺不弱、四柱毫无刑冲克穿","气势特别大且能做功产生效率","八个字全是财官印食、不见七杀伤官","五行流通不缺、寒暖燥湿绝对平衡"],"ans":1,"exp":"大格局一般气势特别大，而不是什么平衡；气势出来以后要做功，产生效率。","sec":"基本概念","t":"rule"},{"q":"下列地支合制中，哪一组属于效率很低的合制？","opts":["午亥合、子丑合","卯戌合、卯申合","寅亥合、午戌合","巳申合、寅丑合"],"ans":2,"exp":"地支合制中，寅亥合（亥中水制寅中火）与午戌合（午中火制戌中金）效率很低。","sec":"制用结构中效率高低","t":"diff"},{"q":"除巳申合外，下列哪一组地支合制的效率也较高？","opts":["寅亥合、卯戌合、申子合、亥卯合","寅亥合、午戌合、辰酉合、巳酉合","午戌合、未午合、子丑合、申酉合","卯戌合、卯申合、午亥合、子丑合、寅丑合"],"ans":3,"exp":"合制中巳申合效率最高，卯戌、卯申、午亥、子丑、寅丑合都较高；寅亥、午戌合很低。","sec":"制用结构中效率高低","t":"diff"},{"q":"穿制结构中，酉戌穿、卯辰穿、子未穿要发挥较高效率，必须具备什么条件？","opts":["一方须有很强大的力量","两字必须相隔年时远穿","两字力量必须完全相等","天干必须同时透出印星"],"ans":0,"exp":"酉戌穿、卯辰穿、子未穿效率较高，但前提是一方须有很强大的力量。","sec":"制用结构中效率高低","t":"rule"},{"q":"克制结构中，「天克地」要能克住对象，必须满足什么条件？","opts":["地支必须有冲","天干必须有势","日主必须坐禄","天干必须孤立虚透"],"ans":1,"exp":"围克效率最高；天克地也能克住，但天干必须有势；贴克效率很低，特别费劲。","sec":"制用结构中效率高低","t":"rule"},{"q":"冲制结构中，除库冲外，其余相冲要产生高效率必须依赖什么？","opts":["必须同时见合","必须天干虚透","必须有强有力的势","必须隔柱遥冲"],"ans":2,"exp":"库冲效率最高且挨住冲最好；其他冲都赶不上库冲，必须有强有力的势才能起效。","sec":"制用结构中效率高低","t":"rule"},{"q":"效率高的命局与效率低但毛病少的命局，在遇到不利大运时表现有何不同？","opts":["两者遇不利大运都会翻盘，效率高者翻盘更快","效率高者只破财不丢官，效率低者只丢官不破财","效率高者遇反局绝不翻盘，效率低者一遇不利即大败","效率高者遇反局易翻盘，效率低而毛病少者反而稳定"],"ans":3,"exp":"效率高的命一旦大运遇反局（如未制净之字得长生）会翻盘；效率低但毛病少的命，反而稳定。","sec":"普通命局的废神与低效率","t":"diff"},{"q":"原局反局与大运反局在出现频率上有什么差别？","opts":["原局反局不太多，大运反局比较多","只有贵格才有大运反局，常人没有","原局反局与大运反局各占一半","原局反局非常多，大运反局极少见"],"ans":0,"exp":"口诀：原局反局的人不太多，搞清楚日主表达的意思和命局表达的意思就行；大运反局比较多。","sec":"五、正局与反局入门","t":"diff"},{"q":"大运反局时，大运之字对原局功神与被制之神通常起什么作用？","opts":["合住原局闲神，使废神全部转化为功神","坏了原局要用的功神，生助了原局要制的字","生助原局要用的功神，克制了原局要制的字","冲开原局财库，同时合住原局七杀"],"ans":1,"exp":"大运反局即大运所表意思与原局相反：所用的全坏、所制的全生（如丙辰运晦火穿木生金），故出大灾。","sec":"大运反局","t":"xiang"},{"q":"所谓「原局反局」，是指哪两者的意思相反？","opts":["原局天干的意思与原局地支的意思相反","年柱天干的意思与时柱地支的意思相反","日主或日柱所表的意思与八字整体所表的意思相反","月令的五行属性与大运的五行属性相反"],"ans":2,"exp":"原局反局指日主（或日柱）所表达的意思与八字整体所表达的意思相反，天生命就坏。","sec":"原局反局","t":"rule"},{"q":"原局反局时，命主的灾难与破败通常应在何处？","opts":["反在天干无妨，反在地支才坏","一律只应于早年父母宫","一律只坏在晚年子女宫","反在哪，坏在哪"],"ans":3,"exp":"原局反局「反在哪，坏在哪」，如坐支合官反局则早死夫，合到财库反局则一生受穷。","sec":"原局反局","t":"rule"},{"q":"乾造壬己丁己／寅酉丑酉，丑财库被酉入库且丁壬合官，凭什么判断丑是国有企业？","opts":["合官坐印，财库成了印的财库而非私人企业","酉金七杀坐于月令，说明财库只属于国家税务","己土食神透出两干，表示必须替他人打工领薪","寅木正印在年支遥远，说明财库在海外而不在家"],"ans":0,"exp":"丁壬合官看坐印寅，丑这个财库是印的财库，表示丑不是自己的企业，而是国有企业，故为管国企的官员。","sec":"补：库与合官的断例","t":"xiang"},{"q":"坤造甲戊丙甲／午辰午午，夫妻宫两现而时上又见伏吟，主几次婚姻？","opts":["一次婚姻，三个午火伏吟只算一夫","两次婚姻，时上伏吟不代表第三次婚姻","三次婚姻，两现加伏吟各算一次","四次婚姻，四柱各见一妻或一夫"],"ans":1,"exp":"婚姻两次，夫妻宫两现；时上是伏吟，不代表第三次婚姻，主要是指她老公。","sec":"补：库与合官的断例","t":"rule"}]},{"n":18,"level":"初级","title":"婚姻与看寿入门","qs":[{"q":"女命夫妻宫占印，这个印算不算丈夫？","opts":["局中有官才算丈夫，无官则不算","不论有无官，印都算丈夫来论","局中有官则不算，无官才可当丈夫","印是中性的，一律不算丈夫看待"],"ans":2,"exp":"印是中性的东西：只要八字中有官，印就不作丈夫看，无官时印才可当丈夫看；夫妻宫印旺是妻管严。","sec":"先看夫妻宫占什么六亲","t":"diff"},{"q":"男命夫妻宫占七杀，局中又见财星，配偶星取哪个？","opts":["取食伤，食伤生财","财官并取，一妻一妾","取七杀，官杀即妻","取财星，财生官杀"],"ans":3,"exp":"男命占官杀，要看有没有财：有财，财生官杀，财为配偶星；无财，官杀才作配偶星。","sec":"先看夫妻宫占什么六亲","t":"calc"},{"q":"女命夫妻宫占伤官而制不住官，婚姻怎么断？","opts":["管不住老公，婚姻不好或老公外有说法","伤官泄秀，丈夫能干，家庭和顺","官被伤尽，克夫，终身难嫁出去","伤官生财，丈夫有钱，婚姻美满"],"ans":0,"exp":"伤官一定要制官，制住官才得官；制不住则管不住老公，一是婚姻不好，二是老公外面有说法。","sec":"先看夫妻宫占什么六亲","t":"rule"},{"q":"配偶星入配偶宫（得正位），若被冲克坏，主什么？","opts":["婚姻多次变动","配偶病灾或死亡","配偶远走他乡","配偶富贵但感情淡"],"ans":1,"exp":"配偶星入配偶宫是得正位，好坏都不宜将其冲克坏；若坏掉，易出现配偶病灾或死亡。","sec":"判断婚姻好坏的初级法则","t":"rule"},{"q":"男命婚外情的三个条件，哪组正确？","opts":["混杂财星透干；印旺无财；比劫来夺财星","伤食有制；七杀入墓；财星被他神所合住","混杂财星透干；伤食无制；七杀为桃花入主","混杂官杀透干；财多无制；食伤见官杀同现"],"ans":2,"exp":"男命：财星混杂（与妻宫有关）且透干；伤官食神无制（放纵）；七杀（官星亦然）为桃花入主位。","sec":"男命","t":"rule"},{"q":"女命禄入主与他神相合成桃花，外合与内合的区别是？","opts":["外合主离婚收场；内合主不离婚","外合、内合都是与生人外人乱搞","外合只与熟人搞；内合与生人外人乱搞","外合与生人外人乱搞；内合只与熟人搞"],"ans":3,"exp":"「女命淫，只因桃花绊禄」：桃花外合会与生人、外人乱搞；桃花内合只与熟人搞。","sec":"女命","t":"diff"},{"q":"多婚命有几个起坏作用的字，婚姻次序怎么排？","opts":["从年上往时上排，看第几个稳定","从日支起向两边排","按生成数大小排","从时上往年上排，看第几个稳定"],"ans":0,"exp":"多婚的次序是从年上往时上排，看到第几个才能稳定住。","sec":"三、几次婚姻","t":"step"},{"q":"夫妻宫双现（如子、寅），但夫妻星只有一个，怎么断？","opts":["一宫一婚，宫有两现即主婚姻两次","不主婚姻不好，主有好几处家","主夫妻星被分夺，婚姻时刻不稳","主一婚，但夫妻长期分居两地"],"ans":1,"exp":"夫宫双现不等于多婚：夫妻星只有一个，宫双现表示她有好几处家，老公对她特别好。","sec":"夫宫双现不等于多婚","t":"diff"},{"q":"女命行劫财运，官轻财轻与官重财重各怎么论？","opts":["两种都不怕劫，劫一点才好","两种都必离，劫财运一到即离","官轻财轻劫财星必离；官重财重不怕","官轻财轻不怕劫；官重财重必离婚"],"ans":2,"exp":"女命关财门：财是官的原神，官轻财轻行劫财运，劫了财星肯定离婚；官重财重不怕劫，劫一点才好。","sec":"女命关财门","t":"diff"},{"q":"配偶宫、星偏重杂出为重患必离，若又重见伏吟，如何论？","opts":["主丧偶，不主离婚","患更重，必离无疑","主再婚，婚姻稳定","转为轻患，可能离或婚前不顺、婚后分居"],"ans":3,"exp":"重见伏吟为轻患：可能会离，也可能婚前不顺或婚后分居。","sec":"患夫、患妻","t":"rule"},{"q":"去用结构中，下列哪个日柱是主位连根，不能被去？","opts":["壬申","甲子","丁亥","庚午"],"ans":0,"exp":"主位的、连根的不能去，去了人就短寿：壬申、乙亥、乙卯、甲寅之类；甲子无根，庚午、丁亥坐下不是自己的根。","sec":"通根、通源与流绝","t":"calc"},{"q":"日主之禄看寿，哪种说法对？","opts":["时柱见禄即寿到，不论运岁如何","晚年见禄，运岁再见才寿到","日柱之前的大限一见禄便是寿到","晚年时柱见禄大吉，运岁再见更吉"],"ans":1,"exp":"日柱之前的大限见禄不为寿到；晚年、时柱见禄，怕运岁再见禄；晚年见禄最怕被冲刑破穿入墓。","sec":"寿元星与禄","t":"rule"}],"fine":[{"q":"女命夫妻宫印星旺时，在夫妻相处中往往表现出什么特点？","opts":["夫管严，丈夫强势专断，妻子凡事只能顺从","夫妻相敬如宾，双方互不干涉各自自由","妻管严，印旺泄官，丈夫在妻子面前没脾气","印旺生身，丈夫极度依赖妻子但脾气暴躁"],"ans":2,"exp":"女命夫妻宫印旺，是妻管严，丈夫在她面前没脾气，因为印旺泄官。","sec":"先看夫妻宫占什么六亲","t":"xiang"},{"q":"男命夫妻宫占食神或伤官时，在六亲取象上代表什么？","opts":["须看局中有无印星，无印才算配偶星","只代表子女星，不代表配偶星","须看局中有无官杀，有官杀才算配偶星","直接代表配偶星"],"ans":3,"exp":"男命夫妻宫占财、食神、伤官都代表配偶星；占官杀才看有没有财。","sec":"先看夫妻宫占什么六亲","t":"calc"},{"q":"配偶宫原来起好作用而被冲穿坏，与原来起坏作用而被坏，婚姻表现有何不同？","opts":["好宫被坏中途生变或配偶有疾，坏宫被坏感情不好但配偶能干","好宫被坏只主晚婚，坏宫被坏只主配偶性格孤僻","两种情况都主配偶无能且婚姻必然中途离异","好宫被坏感情极好，坏宫被坏则配偶早亡且无能"],"ans":0,"exp":"好宫被冲穿坏，婚姻中途容易有问题或配偶有疾、要求过高；坏宫被坏，则配偶与自己感情不算好但能干有本事。","sec":"判断婚姻好坏的初级法则","t":"diff"},{"q":"按判断婚姻好坏的初级法则，配偶宫遇合（包括六合、暗合）一般可作何判断？","opts":["六合主一婚到老，暗合才主二婚以上","易产生婚姻变化，一般可断二婚以上","只主婚前恋爱顺利，婚后绝不生变","配偶宫稳固不动，主白头偕老、一婚到底"],"ans":1,"exp":"初级法则：配偶宫不喜被他合，一合容易产生婚姻变化（含六合、暗合），配偶宫遇合一般可断二婚以上。","sec":"判断婚姻好坏的初级法则","t":"rule"},{"q":"八字中只有哪两类情况下的财或官杀才当作配偶看？","opts":["与时柱发生刑冲合穿，或藏于年支墓库","只要八字里出现的财或官杀，一律都当配偶看","与日主或配偶宫发生刑冲合穿，或配偶星入主位","透出在年干或月干，或坐于月令本气"],"ans":2,"exp":"一般来说，与日主或配偶宫发生刑冲合穿的配偶星才作配偶看，有时配偶星入主位也当配偶看；除此不当配偶看。","sec":"判断婚姻好坏的初级法则","t":"rule"},{"q":"如果八字中完全没有配偶星，应以什么作为配偶来看？","opts":["以大运最初出现的财官作配偶","以年柱正印作配偶","以时柱食伤作配偶","以配偶宫作配偶"],"ans":3,"exp":"判断婚姻好坏的初级法则明确规定：八字无配偶星者，以配偶宫作配偶。","sec":"判断婚姻好坏的初级法则","t":"rule"},{"q":"男命婚外情条件中，「混杂财星」必须同时满足哪两个条件？","opts":["财星与妻宫有冲刑穿合关系，且有透干","财星坐于日主之禄上，且无食神生助","财星全部藏于地支墓库，且与时支相冲","财星在年柱和时柱双现，且地支不见比劫"],"ans":0,"exp":"男命婚外情第一条：混杂财星（财星必须与妻宫有关系，即有冲刑穿合），且有透干。","sec":"男命","t":"rule"},{"q":"女命婚外情的标志中，除混杂官杀透干、桃花绊禄外，还有哪两项？","opts":["财星虚透，七杀坐于年支","财多无制，食伤见官杀多","印多无财，比劫见食伤旺","官杀入墓，食伤被印制净"],"ans":1,"exp":"女命婚外情四条：1.混杂官杀（与夫宫有关）且透干；2.财多无制；3.食伤见官杀（多）；4.桃花绊禄。","sec":"女命","t":"rule"},{"q":"「女命淫，只因桃花绊禄」中的「桃花绊禄」具体指什么结构？","opts":["女命日主坐下正官被时支穿坏","女命食神在宾位入墓且不透干","女命之禄入主位而与他神相合","女命之禄在年柱被月令冲破"],"ans":2,"exp":"「女命淫，只因桃花绊禄」：女命之禄入主与他神相合便是桃花；外合与生人外人乱搞，内合只与熟人搞。","sec":"女命","t":"rule"},{"q":"看多次婚姻数较多时，五行生成数口诀中「水、火、木、金、土」对应的数字分别是？","opts":["木1·6，火2·7，土3·8，金4·9，水5·10","水1·5，火2·6，木3·7，金4·8，土9·10","水2·7，火1·6，木3·8，金5·10，土4·9","水1·6，火2·7，木3·8，金4·9，土5·10"],"ans":3,"exp":"多婚数较多时可看五行生成数口诀：水—1、6，火—2、7，木—3、8，金—4、9，土—5、10。","sec":"三、几次婚姻","t":"calc"},{"q":"当配偶星受克被坏或配偶宫被坏时，如何数定会有几次婚姻？","opts":["看起坏作用的字有几个，有几个就有几次婚姻","看八字里有几个地支相合，一合主一次婚姻","看原局财星或官杀一共有几个，有几个就结几次","看日主坐支在地支藏干中有几个余气"],"ans":0,"exp":"配偶星受克被坏，或配偶宫被坏：看起坏作用的字（忌神）有几个，有几个就有几次婚姻。","sec":"三、几次婚姻","t":"rule"},{"q":"坤造辛庚庚己／亥寅寅卯，同八字两人婚姻一离一和，原因何在？","opts":["两人相差一小时出生，一为早寅时一为晚寅时","一人以月令寅亥合看夫宫而闹离，一人以日支看夫宫则婚姻好","一人大运逆行，另一人大运顺行所致","一人出生在北方水地，一人出生在南方火地故喜忌相反"],"ans":1,"exp":"该造以月看夫宫的，寅亥合制去官星、夫宫合绊，丈夫是干部要闹离婚；以日看的则丈夫没工作而婚姻好。","sec":"夫宫双现不等于多婚","t":"xiang"},{"q":"女命关财门中，「伤官旺、财被穿倒」与「伤官轻、财受冲受伤」在离婚轻重上有何区别？","opts":["前者为轻可断闹离婚，后者为重必离","前者主丧夫不主离，后者主主动离婚","前者为重必离，后者为轻可断闹离婚","两者都必离无疑，没有轻重差别"],"ans":2,"exp":"女命关财门：原局伤官旺、财被穿倒为重，必离；原局伤官轻，财受冲、受伤为轻，可断闹离婚。","sec":"女命关财门","t":"diff"},{"q":"「患夫」「患妻」中的「患」字，在盲派婚姻断法里指什么？","opts":["夫妻双方性格不合，经常口角争吵不断","配偶身体长期患病，需要命主长期照顾","配偶星落入空亡，导致终身找不到对象","配偶宫或配偶星杂现多了，出现不同配偶"],"ans":3,"exp":"「患」指杂现、多了：不同的配偶；偏重杂出为重患必离，重见伏吟为轻患。","sec":"患夫、患妻","t":"rule"},{"q":"「患夫、患妻」时，从喜忌角度如何判断配偶能否留住？","opts":["起坏作用的字留不住肯定离，起好作用的字多数不会离","只要出现杂现，不论喜忌一律都留不住、必离","只要夫妻宫伏吟，不论喜忌都一定留不住","起好作用的字留不住肯定离，起坏作用的字反而不离"],"ans":0,"exp":"患夫患妻判断：是起坏作用的字（忌神），留不住，肯定离；起好作用的字，多数不会离。","sec":"患夫、患妻","t":"diff"},{"q":"若命局属「患轻者」，通常可通过什么方式或经历来避免离婚？","opts":["必须远嫁异乡或找年龄相差十岁以上者","晚婚或婚姻经过波折可避","完全无法避免，轻患与重患一样必离","早婚且越早办证越能避开"],"ans":1,"exp":"患轻者，晚婚或婚姻经过波折可避；患重者必重婚重配。","sec":"患夫、患妻","t":"rule"},{"q":"食神在命局中当寿元星看时，若食神落在时上空亡，一般主寿命如何？","opts":["只主子女无缘，与命主自身寿命毫无关系","主百岁高寿，空亡反而保护食神不受克","一般主六七十岁、很少超过八十，属寿不长而非寿短","必主三十岁前夭折，属于极短寿之象"],"ans":2,"exp":"食神当寿元星看，在时上落空亡一般主六、七十岁，很少超过八十，这是指寿不长，而不是寿短。","sec":"寿元星与禄","t":"rule"},{"q":"去用结构中，若日柱主位连根（如乙卯、甲寅）属活木，被去或铲根后果如何？","opts":["活木不怕铲根，只要见火就能成材","反主大贵，去尽木气即为从格","只是早年奔波破财，并不影响寿命","人就短寿，一被铲根就完蛋"],"ans":3,"exp":"主位的、连根的不能去，去了人就短寿；乙卯、甲寅之类连根草若是活木，一被铲根就完蛋。","sec":"通根、通源与流绝","t":"rule"},{"q":"壬水通源时，对寅木与卯木、甲木与乙木的喜忌有何区别？","opts":["最爱寅木却不喜卯木，喜甲木未必喜乙木","最爱卯木却不喜寅木，喜乙木未必喜甲木","壬水只怕见木泄气，寅卯甲乙一概不喜","寅卯同为木气，壬水同等喜爱没有区别"],"ans":0,"exp":"壬水最爱寅木，衰水见寅可以依托，旺水见寅可以泄秀，却不喜卯木；同理，喜甲木未必喜乙木。","sec":"通根、通源与流绝","t":"diff"},{"q":"水有源头却一路泄去叫「流绝」而主寿绝；若流到何处则不为流绝？","opts":["流到月上透干，不为流绝","流到时上归库，不为流绝","流到年上逢生，不为流绝","只要大运见金生水，即不为流绝"],"ans":1,"exp":"水有源头怕流绝，流绝则寿绝；但流到时上归库，就不为流绝（如生于寅卯木泄而时落丙辰归库则没事）。","sec":"通根、通源与流绝","t":"rule"},{"q":"盲派看寿时，如何区分「活木」与「死木」？","opts":["在年柱为活木，在日柱和时柱为死木","甲木阳干为活木，乙木阴干一律为死木","有水或春生为活木，无水或空亡为死木","见火照暖为活木，见水浸泡则变为死木"],"ans":2,"exp":"木无水为死木，有水为活木；春生为活木，空亡之木为死木，但空亡之木有水也为活木（只是长得不健壮）。","sec":"木分死活","t":"diff"},{"q":"死木在看寿时最怕什么，容易导致短寿？","opts":["怕弱，木气一弱不用见火就会枯死","怕水多漂浮，见壬癸水旺即短寿","怕土厚埋木，见辰戌丑未多即短寿","怕焚，火旺的死木一旦木气烧干净就死"],"ans":3,"exp":"死木是桌椅劈材，不怕弱，怕焚；火旺的死木人寿短，一旦木气烧干净就死了，且火主神经易有神经质。","sec":"木分死活","t":"rule"},{"q":"从宫位依据看寿，日柱代表什么？年月受伤与日主坐根连体被坏有何不同？","opts":["日柱代表五脏六腑且坐根不能坏，年月伤之一般不影响寿命","日柱只代表配偶而不管身体，年柱受伤才真正影响寿命","年月伤之必主早夭，日柱坐根被坏只主晚年微疾","四柱只要有一柱坐根被坏，寿命长短完全相同"],"ans":0,"exp":"日柱代表五脏六腑，日主坐根连体不能坏，年月伤之对寿命一般不影响。","sec":"木分死活","t":"rule"},{"q":"乾造乙己壬壬／卯卯子寅，为何行丁丑运甲戌年因煤气中毒死亡？","opts":["卯木伤官被丑戌刑坏，甲戌年伤官见官而亡","丁壬合、子丑合天地合绊日主根，甲透合己、寅被戌合","丁火财星在丑运入墓，甲戌年开墓反克日主而亡","壬水日主被乙己克泄太过，甲戌年水入戌墓而亡"],"ans":1,"exp":"丁丑运天地合绊（丁壬合、子丑合），子水根不起作用；甲戌年甲木虚透被己合、寅木被戌合，断了延寿线，丑为湿煤湿土。","sec":"通根、通源与流绝","t":"xiang"}]},{"n":19,"level":"初级","title":"补充答疑与零散断法","qs":[{"q":"日主之禄在日支（坐下）与在时上，被刑冲破穿制时后果有何不同？","opts":["两处之禄都可坏，只是身体变差而已","坐下之禄可坏，时上之禄不可坏，坏则损寿","两处之禄都不可坏，坏了都要损寿折福","坐下之禄不可坏，坏则损寿；时上之禄可坏，只伤身"],"ans":3,"exp":"日支之禄是日主的根，坏了伤寿；时上之禄坏了只是身体差，不至损寿。","sec":"一、禄的处置","t":"diff"},{"q":"年、月上的禄被制、被冲，对日主有没有影响？","opts":["无妨，年月之禄不代表日主自己","有影响，年月禄坏主早年伤父母","无妨，但须大运合来才解","有影响，禄在哪柱都是日主之根"],"ans":0,"exp":"禄在日、时才是日主自己；年、月上的禄被制被冲无妨。","sec":"一、禄的处置","t":"rule"},{"q":"时上有禄，要成「单禄」可坏，前面不能再有什么？","opts":["不能再有食伤泄日主","不能再有生日主的印或比劫","不能再有财星合日主","不能再有官杀克日主"],"ans":1,"exp":"时上禄是孤单的东西，前面再有生身之印或比劫就不是单禄，不可坏。","sec":"一、禄的处置","t":"rule"},{"q":"日主合年月上的官，与合时上的官，含义有何不同？","opts":["两者都是日主被管，只是远近不同","两者都是日主管理，只是官大官小不同","合年月官是管理控制；合时上官是被人管理","合年月官是被人管理；合时上官是管理控制"],"ans":2,"exp":"合年月官，日主管理这个官所代表的东西；合时上官，日主被别人管。","sec":"二、日主合官：年月管人，时上被管","t":"diff"},{"q":"日主合时上的官，官坐下的时支能不能被坏？","opts":["可以坏，只合官就够了","可以坏，坏了官才出来","不能坏，但需要被合住","不能坏，要用时支去制别的支"],"ans":3,"exp":"合到时上才有用，用的就是时支；合官必用时支，所以支不能坏。","sec":"二、日主合官：年月管人，时上被管","t":"rule"},{"q":"原局有破，大运或流年再来一个破（或其他作用），能不能解命中的破？","opts":["解不了，破只有坏处，运中破解不了命中破","能解，以破解破","解不了，但命中的破可转成做功","能解，但须合来才解"],"ans":0,"exp":"破不叫做功，只表象；暗合才是做功。运中来的破不能解命中的破。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"原局有穿，遇到合能不能化解？","opts":["能，但只限六合","不能，合解不了穿","能，但只限暗合","能，合能解一切穿"],"ans":1,"exp":"合解不了穿，穿什么也解不了，不能指望遇合来化解。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"日主与日支自合的地支，还能不能去制别的字？","opts":["不能，自合则地支被合住不起作用","不能，自合只主表象","能，自合并不妨碍它去制别的字","能，但只能制主位的字"],"ans":2,"exp":"日主与日支自合的地支能制，自合不妨碍其做功。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"夫妻宫被穿，哪一类对婚姻伤害更重？","opts":["生穿与克穿一样重","生穿更重，因为生而反穿","申亥、寅巳这类生穿","子未、卯辰这类克穿"],"ans":3,"exp":"夫妻宫生穿不要紧，克穿才厉害。","sec":"三、破、穿、自合的几条答疑","t":"diff"},{"q":"原局食神、官星落空亡，大运流年逢到所落之字，称什么？","opts":["填空，本派承认这一说","冲空，本派承认这一说","解空，运岁一合即解","补空，但本派不承认"],"ans":0,"exp":"空亡可由运、岁填空；食神落空亡短寿也有前提。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"食神落空亡短寿，成立的前提是什么？","opts":["水旺而有根","水没有流绝","食神被官杀所制","食神坐在时柱"],"ans":1,"exp":"水有源头、流到时上归库（不流绝）的，食神落空亡也不短寿。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"看学历的有无与高低，先看什么，再看什么？","opts":["先看食伤，再看印星","先看印星，再看官星","先看官星，再看印星","先看印星，再看财星"],"ans":2,"exp":"官星虚透看学历，先官星后印星。","sec":"四、空亡、泄用与几条虚实补注","t":"step"}],"fine":[{"q":"日主之禄分布在四柱不同位置时，哪两柱的禄才真正代表日主自己？","opts":["年柱与月柱的禄","月柱与日柱的禄","年柱与时柱的禄","日柱与时柱的禄"],"ans":3,"exp":"禄在日、时才是日主自己；年、月上的禄不代表日主自己，被制、被冲无妨。","sec":"一、禄的处置：坐下不坏，时上可坏","t":"rule"},{"q":"时上有禄且前面再见印星或比劫时，该禄还能不能被坏？","opts":["不能，此时不再是单禄，不可坏","可以，只要在时柱上的禄一律都可坏","见印可坏而见比劫不可坏","见比劫可坏而见印不可坏"],"ans":0,"exp":"禄在时上是孤单的东西，前面再有生身之物（印）或再见比劫，就不是「单禄」了，那样的禄不可坏。","sec":"一、禄的处置：坐下不坏，时上可坏","t":"rule"},{"q":"时上之禄为「单禄」时可以被坏，坏了之后对命主有什么具体影响？","opts":["对身体和寿命都没有任何影响","身体会变差，但不至于损寿","只主破财，身体反而更加健康","必然损寿早亡，与坐下之禄相同"],"ans":1,"exp":"口诀：坐下之禄不可坏，时上之禄可坏但伤身；坏了身体会差，但不至于损寿。","sec":"一、禄的处置：坐下不坏，时上可坏","t":"rule"},{"q":"日主合年、月上的官，与合时上的官相比，官的坐支在处置上有何不同？","opts":["两者坐支都可以坏，只要天干合住就行","合年月官坐支不能坏，合时上官坐支可以坏","合年月官坐支可坏看原局意思，合时上官坐支不能坏","两者坐支都绝对不能坏，坏则无官"],"ans":2,"exp":"合年月官，坐支可以被坏，看原局意思；合时上官，一定要用官坐下的支，支不能被坏。","sec":"二、日主合官：年月管人，时上被管","t":"diff"},{"q":"日主合时上之官时，官坐下的时支应如何发挥作用？","opts":["把时支冲破或穿倒，官才能显贵","用年月之支来合住并制死时支","让时支保持静止，不可与他支发生作用","一定要用时支去制别的支"],"ans":3,"exp":"合时上官时，一定要用官坐下的支，支不能被坏；要用时支去制别的支。","sec":"二、日主合官：年月管人，时上被管","t":"rule"},{"q":"为什么说日主合时上的官才算「有用」，而合年月的官不算同一种「用」？","opts":["合时上必用时支，合年月是外来单位或人由日主去管","年月的官只主祖辈官职，与日主本人无关","时上的官能量最大，年月的官能量最小","年月的官离日主太远，日主根本合不到"],"ans":0,"exp":"合是日主所追求的，合到时上才「有用」，用的就是时支；合年月官是外来的单位或外面的人，日主只是去管。","sec":"二、日主合官：年月管人，时上被管","t":"rule"},{"q":"乾造辛丁癸戊／丑酉酉午与辛丁癸己／丑酉酉未只差一个时辰，为何前者开出租后者为公安分局局长？","opts":["前者戊土正官被合绊无用，后者己土七杀透干得用","同为印太旺，后者原局把火制住而前者未能制住","前者水木清华成化用格，后者金水成势伤官见官","前者午火为日主之禄被穿，后者未土为财库被冲开"],"ans":1,"exp":"两造均印太旺，前者癸合时上戊官要用午火制印却未能制住；后者未时原局把火制住了，故差一个时辰贵贱悬殊。","sec":"二、日主合官：年月管人，时上被管","t":"xiang"},{"q":"「破」与「暗合」在盲派做功体系中的地位有何区别？","opts":["破与暗合都是做功，只是效率高低不同","破是做功而暗合不做功，暗合只表象","破不叫做功、只表象且只有坏处；暗合则是做功","破与暗合都不叫做功，都只用来取象"],"ans":2,"exp":"破只有坏处，没有好处，破不叫做功，只表象；暗合则不同，暗合也是做功。","sec":"三、破、穿、自合的几条答疑","t":"diff"},{"q":"下列地支相穿中，哪一组属于伤害较轻的「生穿」，哪一组属于较重的「克穿」？","opts":["酉戌、丑午为生穿较轻，申亥、寅巳为克穿较重","子未、卯辰为生穿较轻，申亥、寅巳为克穿较重","申亥、丑午为生穿较轻，寅巳、酉戌为克穿较重","申亥、寅巳为生穿较轻，子未、卯辰为克穿较重"],"ans":3,"exp":"申亥、寅巳之类生穿对婚姻宫伤害轻；子未、卯辰、酉戌、丑午这类相克又穿的才重。","sec":"三、破、穿、自合的几条答疑","t":"calc"},{"q":"原局有穿时，能否指望通过其他地支或天干的「合」或「穿」来化解？","opts":["不能，合解不了穿，穿什么也解不了","可以，只要遇到六合或三合就能彻底解穿","天干五合能解穿，地支六合解不了穿","以穿解穿可以化解，以合解穿则不能"],"ans":0,"exp":"合解不了穿，穿什么也解不了；原局有穿，不能指望遇合来化解。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"天地合制地支时，若地支再遇到相冲或相穿，结果如何？","opts":["遇冲则吉、遇穿则凶，须分别看待","不好，天地合制忌地支再遇冲穿","无所谓，天地合制完全不受冲穿影响","更好，冲穿能加速合制使做功更彻底"],"ans":1,"exp":"天地合制地支时，遇到地支再冲、穿，也不好。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"「破」在命局和大运流年中出现时，能否产生积极的做功效果？","opts":["原局的破不做功，大运来的破可以做功","能，破与冲一样属于制用做功的一种","不能，破只有坏处没有好处，只表象不做功","破财时算做功，破官时不算做功"],"ans":2,"exp":"破只有坏处，没有好处，破不叫做功，只表象；运中来的破，解不了命中的破。","sec":"三、破、穿、自合的几条答疑","t":"rule"},{"q":"坤造壬丙己己／子午巳巳，印去制财不算制得干净，为何仍发财千万且公司归自己？","opts":["巳火劫财冲破子水，把别人的财抢入自己囊中","丙火印星虚透无根，反而生助子水财星得财","己土比肩合住壬水，天干合财所以公司归自己","印强财弱可换象、印也表财，且午与己同象"],"ans":3,"exp":"该造印强财弱要换象，印也表财；午与己是一个象，故财全是自己的，不必计较制得净不净。","sec":"三、破、穿、自合的几条答疑","t":"xiang"},{"q":"食神落空亡而水有源头、流到时上归库时，寿命应如何论？","opts":["不流绝，即使食神落空亡也不短寿","依然必主短寿，空亡力量大于归库","反主早夭，归库等于把食神收进坟墓","只主寿不长，一般活不过五十岁"],"ans":0,"exp":"食神落空亡短寿的前提是水没有流绝；水有源头、流到时上归库（不流绝）的，食神落空亡也不短寿。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"「泄用」结构中，哪些五行组合可以泄秀，命主通常从事什么行业？","opts":["木土、水火可以泄秀，一般为手艺工匠之人","土金、木火可以泄秀，一般为搞学问之人","水木、土火可以泄秀，一般为军警武职之人","金水、火土可以泄秀，一般为经商求财之人"],"ans":1,"exp":"泄用：土金、木火可以泄秀；用神泄秀的结构，一般是搞学问的。","sec":"四、空亡、泄用与几条虚实补注","t":"xiang"},{"q":"看做功时是以天干为主还是以地支为主？虚透起什么作用？","opts":["以天干为主，地支只是天干的根基不做功","正用看地支做功，反用则专看天干虚透做功","以地支为主，虚透只是表象不做功","天干地支同等做功，虚透也能独立制去地支"],"ans":2,"exp":"看做功以地支为主，虚透只是表象，真正做功的不会是虚的。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"时上伤官虚透，能否去生月干上的财星？","opts":["能，同在天干就可以隔柱相生","男命不能生，女命时上伤官虚透可以生","能，只要中间没有官杀阻隔即可","不能，虚透之字生不了别的字"],"ans":3,"exp":"时上伤官虚透，不能生月干之财，因为虚透之字生不了别的字。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"看学历的有无与高低时，通常应重点观察官星的什么状态？","opts":["官星虚透看学历，先看官星，再看印星","官星入墓看学历，先看比劫，再看官星","官星被穿看学历，先看食伤，再看财星","官星通禄看学历，先看财星，再看官星"],"ans":0,"exp":"官星虚透看学历：看学历有无与高低，先看官星，再看印星。","sec":"四、空亡、泄用与几条虚实补注","t":"rule"},{"q":"关于「日主坐库是否一定要刑冲」存在两说并存时，实际断盘应以什么为准？","opts":["男命必须刑冲，女命一律不需刑冲","以原局实际做功情况（库是否为所用）为准","一律以不需刑冲为准，刑冲反而破库","一律以必须刑冲为准，不刑冲即废"],"ans":1,"exp":"两说并存未见调和时，断盘应以原局实际做功情况（库是否为所用）为准。","sec":"五、两处存疑：照录","t":"rule"},{"q":"「穿倒正印不走正路」的口诀在实断品性时，不可一概而论，还须结合什么来看？","opts":["须看伤官在不在时柱，结合食伤数量而论","须看偏财在不在年柱，结合财星旺衰而论","须看正官在不在主位，结合官星位置而论","须看大运是否走印运，结合流年干支而论"],"ans":2,"exp":"「穿倒正印不走正路」不可一概而论，要看正官在不在主位；论品性须结合官星位置，不能只看穿。","sec":"五、两处存疑：照录","t":"rule"},{"q":"乾造乙癸甲壬／丑未戌申，虽见官库被制，其不当官的原因是什么？","opts":["丑未冲把官库冲坏了","甲木日主无根不任官杀","乙木劫财透干合住了申杀","壬水不能化申杀"],"ans":3,"exp":"此造虽有丑未戌刑冲制官库，但追问「壬又可化申杀，能否当官」，答为「不能化杀」，故不当官。","sec":"六、几则只有问答的命例","t":"calc"},{"q":"乾造己癸己庚／酉酉丑午，问时上之禄能否穿制时，关键答语指出了什么条件？","opts":["己丑日主（坐库）一定要刑冲","年干己土比肩助身，时禄已非单禄","时上午禄坐于庚下，绝对不可穿制","月日两酉伏吟，必须先合去酉金才可穿午"],"ans":0,"exp":"此造问时上之禄可否穿制，答「己丑日主（坐库）一定要刑冲」，同时时上禄可坏。","sec":"六、几则只有问答的命例","t":"calc"}]},{"n":46,"level":"中级","title":"天道、阴阳、五行、体用","qs":[{"q":"按盲派，阴阳是相对概念还是绝对概念？","opts":["绝对：但阴阳可随大运互相换位","相对：随比较对象而定阴阳","绝对：阳就是阳，阴就是阴","相对：只有成对出现才有阴阳"],"ans":2,"exp":"阴阳不是相对的矛盾统一，而是确定属性：热升动左男横为阳，寒降静右女竖为阴。","sec":"二、阴阳：天地之道","t":"rule"},{"q":"阴阳属性里，横与竖、动物与植物各属阴还是阳？","opts":["横属阳、植物属阳","横、动物属阴；竖、植物属阳","竖属阳、动物属阴","横、动物属阳；竖、植物属阴"],"ans":3,"exp":"动物横行、五官能动者横长属阳；植物竖长、耳鼻竖长不动属阴。","sec":"二、阴阳：天地之道","t":"diff"},{"q":"干支把阴阳符号化后，阴极与阳极分别落在哪两个支？","opts":["阳极为午，阴极为子","阳极为寅，阴极为申","阳极为子，阴极为午","阳极为巳，阴极为亥"],"ans":0,"exp":"阳到极点是午（夏至），阴到极点是子（冬至）；子午是阴阳的符号。","sec":"二、阴阳：天地之道","t":"rule"},{"q":"五行里土的位置与作用，按盲派怎么讲？","opts":["旺于夏季，主热长万物","寄于四季最后一月，承载四行，居中为中气","旺于冬季，主藏物","独占一季，与其他四行并列"],"ans":1,"exp":"土代表地球本身，寄于每季季月，秉四季余气，承载其他四行。","sec":"三、五行：阴阳的五种力量","t":"rule"},{"q":"「克」的来源，盲派怎么解释金克木、水克火？","opts":["按五行物质性质，金能砍木、水能灭火","五行相邻，一方吞噬另一方","阴阳之克：秋杀克春生，寒克热","按五季顺序，前一季克后一季"],"ans":2,"exp":"生来自五季时序接续，克来自阴阳之克；四极之克加土后成隔位之克。","sec":"四、五行生克","t":"rule"},{"q":"木无金克与木生火太过，各自的弊病是什么？","opts":["木无金克无法生火；木生火太旺则水干","木无金克会枯死；木生火太旺则成灾","木无金克不成栋梁；木生火太旺则土焦","木无金克不成栋梁；木生火太旺则灰飞烟灭"],"ans":3,"exp":"只克不生与只生不克都有害：木需金克成材；火过旺则木灰飞烟灭。","sec":"四、五行生克","t":"diff"},{"q":"五行里哪几行属形，哪几行属气？","opts":["金木土为形，水火为气","木火为形，金水为气","金木水为形，火土为气","金土火为形，木水为气"],"ans":0,"exp":"形是实的、气是虚的：金木有形可拿，土归形，水火无形为气。","sec":"五、形与气","t":"diff"},{"q":"形与气转化，哪些组合算形化气、哪些算气化形？","opts":["金生水、水生木为形化气；木生火、火生土为气化形","金生水、木生火为形化气；水生木、火生土为气化形","土生金、金生水为形化气；水生木、木生火为气化形","木生火、火生土为形化气；金生水、水生木为气化形"],"ans":1,"exp":"金木为形，水火为气；形化气＝金生水、木生火；气化形＝水生木、火生土；土生金是形化形。","sec":"五、形与气","t":"rule"},{"q":"形化气、气化形、形化形中，按盲派哪种没有贵重之象？","opts":["金生水（形化气），没有形，不显贵重","水生木（气化形），没有形，不显贵重","土生金（形化形），没有气，不显贵重","木生火（形化气），没有形，不显贵重"],"ans":2,"exp":"只有形化气的组合才显其贵重；形化形（土生金）没有气。","sec":"五、形与气","t":"rule"},{"q":"按盲派体阴用阳，癸水日主与甲木日主，谁贵者更多、原因何在？","opts":["甲木贵者多：至阳，可用之字多","两者一样多，贵贱与阴阳无关","癸水贵者多：至阴，不喜之字多","癸水贵者多：至阴，可用之字多"],"ans":3,"exp":"十干以甲为贵、癸为贱，但癸至阴可用甲、可用戊，成格易；甲至阳可用之字少，难成贵格。","sec":"六、体与用","t":"calc"},{"q":"体与用三种关系中，「体静用动」的例子是哪一组？","opts":["身体是体，拳是用","老子之阴为体，孔子之阳为用","菜刀可切菜也可作凶器","天有四季，人用三季"],"ans":0,"exp":"体静，用动才显：身体为体、拳为用，眼为体、视为用；菜刀是体无定用，天四季人用三是体全用缺。","sec":"六、体与用","t":"diff"},{"q":"命理里干支怎样才能「取出象」、看出它的用？","opts":["干支在命局中静止不动、保持本体","干支在命局中动了、与别支发生关系","查本字的五行属性就够了","干支出现在日柱上就能取象"],"ans":1,"exp":"体没有用是无意义的，干支动了才从变化中知道它的用，象就是这样取出来的。","sec":"六、体与用","t":"rule"}],"fine":[{"q":"古人所谓「天圆地方」的本意是什么？","opts":["天干运行为圆，地支固定为方","天穹呈圆形穹顶，大地呈方形平面","圆指时间的循环，方指四方的方域","阳气运行呈圆弧，阴气静止呈方正"],"ans":2,"exp":"「天圆地方」并非讲空间形状，而是圆＝时间的循环（天道主时），方＝四方的方域（地道主位）。","sec":"1. 天不是空间，是时间","t":"rule"},{"q":"盲派认为术数与数学的根本区别在于什么？","opts":["术数依靠神明启示，数学依靠纯粹逻辑推演","术数不讲运行规则，数学必须遵循严格公式","术数只研究空间方位，数学只研究数字逻辑","术数只有一个目的即预知未来，重实用与可检验"],"ans":3,"exp":"命理重实用与可检验，只问能不能预知，不问纯推理；术数只有一个目的就是预知未来。","sec":"2. 天人合一与可验证性","t":"diff"},{"q":"在阳历、阴历、干支历三统历中，命理排盘实际采用哪一种历法？","opts":["只用太阳周期的十二节与干支历，不用月亮周期","以太阳周期的中气定月，以月亮周期定日","同时并用太阳周期十二气与月亮阴历朔望","只用月亮周期的阴历初一十五，不用太阳节气"],"ans":0,"exp":"命理只用太阳周期二十四节气中的十二节与干支历，不用月亮周期（阴历）。","sec":"3. 命理的起源与结构（时相学）","t":"rule"},{"q":"关于命理沿革与起柱法则，下列说法正确的是哪一项？","opts":["李虚中以日为主推命，徐子平以年为主并多用纳音","月干由年干用五虎遁起，时干由日干用五子遁起","干支纪年始于甲骨文时代，干支纪日起于汉武帝","月干由日干用五子遁起，时干由年干用五虎遁起"],"ans":1,"exp":"月干由年干用五虎遁，时干由日干用五子遁；李虚中以年为主、徐子平以日为主；纪日自甲骨文不断，纪年始于汉武帝。","sec":"3. 命理的起源与结构（时相学）","t":"rule"},{"q":"四柱以日干为「我」，其余宫位按亲疏由近及远依次对应什么？","opts":["年柱祖上最近，次为月令父母、日支配偶、时柱子女","时柱子女最近，次为日支配偶、月令父母、年柱祖上","日支配偶最近，次为时柱子女、月令父母、年柱祖上","月令父母最近，次为日支配偶、年柱祖上、时柱子女"],"ans":2,"exp":"年月一家、日时一家，离日主越近越亲：日下坐支（配偶）最近，依次为时柱（子女）、月令（父母）、年柱（祖上及岳家公婆）。","sec":"3. 命理的起源与结构（时相学）","t":"step"},{"q":"《内经》言阴阳为「变化之父母」，其中「变」与「化」有何区别？","opts":["阳气推动的是「变」，阴气推动的是「化」","有形之物改形是「变」，无形之气散失是「化」","由弱转强是「变」，由强转弱是「化」","同性质的成长是「变」，转为异性质是「化」"],"ans":3,"exp":"同性质的是变（如禾苗长成庄稼），转为异性质的是化（如蛹化成蝶），阴阳是推动一切变化的力量。","sec":"1. 《内经》定义的五句话","t":"diff"},{"q":"夏天地下反凉、冬天泉水不冻，体现了阴阳的哪一项属性？","opts":["阴阳互根、互存、互藏，阳极时阴藏于地","阴阳绝对分立，夏至以后阴气便彻底消失","阴阳相互消长，水火互不相容而各自独立","阴阳由气候决定，没有固定的寒热归属"],"ans":0,"exp":"阴阳互根互存互用互藏：阳极处阴并未消失，而是藏起来了，故夏地凉（阴藏于地）、冬泉暖（阳藏于地）。","sec":"2. 阴阳的三个属性","t":"xiang"},{"q":"阴阳属性中，「左与右」的归属及中医气的运行对应是什么？","opts":["左为阴主肺降，右为阳主肝升，不可颠倒","左为阳主肝升，右为阴主肺降，不可颠倒","左为阳主肾水升，右为阴主心火降","左右并无固定阴阳，随男女命局而互换"],"ans":1,"exp":"阴阳是绝对概念，左属阳（主肝气左升）、右属阴（主肺气右降），指气的运行而非解剖位置，不可颠倒。","sec":"3. 阴阳是绝对概念","t":"diff"},{"q":"关于五行与一天、一年的对应关系，下列哪项表述准确？","opts":["木水主阳为上半年，火金主阴为下半年，土居中宫","木主正午热气，火主早晨升气，金主夜晚寒气","木火主阳为上半年，金水主阴为下半年，土寄季月","土固定属阳，独占长夏而不寄于其他三季"],"ans":2,"exp":"木（晨、春）与火（午、夏）主阳，金（下午、秋）与水（夜、冬）主阴；土寄于每季最后一个月（季月），按所在季节分属阴阳。","sec":"2. 一天、一年中的五行","t":"rule"},{"q":"帝王宫室服饰尚黄，五德以「信」为本，这对应五行的哪一行及其类象？","opts":["木行，主升腾生长、仁爱慈悲、给予释放","火行，主光亮盛大、热情礼仪、文化传播","金行，主清冷杀伐、律令理性、义气决断","土行，主承载运化、中庸圆满、平台纽带"],"ans":3,"exp":"土色黄、居中、主信，类象为承载、养育、中和、厚重、中庸、平台、中介、纽带，故五德以信为本、帝王用黄。","sec":"3. 五行类象（象义的第一层）","t":"xiang"},{"q":"下列人事物类象中，哪一组全部属于「水」和「金」的象义？","opts":["机巧谋略、闭藏属水；律令理性、坍缩属金","光亮文采、热情属水；中和中介、厚重属金","慈爱升腾、给予属水；杀伐收回、清冷属金","闭藏计算、平台属水；生长膨胀、理性属金"],"ans":0,"exp":"水主寒冷、闭藏、趋下、机巧计算谋略；金主下降、清冷、杀伐收回、坍缩、律令理性。","sec":"3. 五行类象（象义的第一层）","t":"xiang"},{"q":"五行「生」与「克」若用阴阳来划分，二者分别属什么？","opts":["生与克皆属阳，唯有受生受克才属阴","生主阳，克主阴，合为五行运行的运算法则","木火之生属阳，金水之生属阴，克则无分阴阳","生主阴，克主阳，二者不可同时并存"],"ans":1,"exp":"生主阳（促进、滋养），克主阴（抑制、消灭），生克是一对阴阳，如同算术的加减乘除，是五行运行的运算法则。","sec":"1. 生与克的来源","t":"rule"},{"q":"五行「只生不克」会成灾，下列过生之弊对应完全准确的是哪一项？","opts":["火生土过旺则湿泥难干，金生水过旺则水势泛滥","火生土过旺则成栋梁，土生金过旺则焦烈无收","土生金过旺反被土埋，水生木过旺则野草丛生","土生金过旺则金寒水冷，水生木过旺则水多木漂"],"ans":2,"exp":"火生土过旺则土焦烈，土生金过旺反被土埋没，金生水越生越无生机，水生木越生越野草丛生。","sec":"2. 生克的现实意义","t":"diff"},{"q":"在无克之弊中，「火无水克」与「土无木克」分别会怎样？","opts":["火无水克灰飞烟灭，土无木克则土重埋金","火无水克不能成器，土无木克则泛滥成灾","火无水克焦烈难用，土无木克则野草丛生","火无水克不成既济，土无木克则飞沙走石"],"ans":3,"exp":"土无木克则飞沙走石，水无土克则泛滥成灾，火无水克不成既济，金无火克不能成器。","sec":"2. 生克的现实意义","t":"diff"},{"q":"以「我」为中心，占卜六亲里的「官鬼」与「妻财」分别对应八字十神中的什么？","opts":["官鬼对应正官七杀，妻财对应正财偏财","官鬼对应比肩劫财，妻财对应正官七杀","官鬼对应正印偏印，妻财对应食神伤官","官鬼对应食神伤官，妻财对应正财偏财"],"ans":0,"exp":"克我者占卜称官鬼、八字分阴阳为正官七杀；我克者占卜称妻财、八字分阴阳为正财偏财。","sec":"3. 生克化生六亲、十神","t":"rule"},{"q":"在「形与气」的划分中，「气」向火与向水发展分别追求什么？","opts":["向火追求理性之「真」，向水追求感性之「美」","向火追求感性之「美」，向水追求理性之「真」","向火追求物质享受，向水追求体格健盛","向火追求数字计算，向水追求文字艺术"],"ans":1,"exp":"气是人类精神活动的产物：向火发展为文字、艺术、表演等对「美」的追求（感性）；向水发展为数学、哲学、科学等对「真」的追求（理性）。","sec":"1. 形气的划分","t":"diff"},{"q":"为何「丙辰」可取为手机之象，且用形与用气在命格上各有何表现？","opts":["丙辰纯属形化形之组合，与精神活动毫无关联","丙为形体、辰为水气；形旺主智慧，气旺主体健","丙为光显之气、辰为形；形旺体健喜物质，气旺智慧重精神","丙为金属外壳、辰为电波；形气旺者皆只求物质享受"],"ans":2,"exp":"物件取象是在形上加赋其气，丙为光/显示（气）、辰为形，合为手机之象；形旺体格健盛喜物质享受，气旺智慧超群重精神生活。","sec":"1. 形气的划分","t":"xiang"},{"q":"关于形气转化与中医对应，下列哪一项说法正确？","opts":["土生金与火生土皆属气化形，不显贵重","「病」字中的「丙」指阴气，先有形病后有气病","庚子辛亥属气化形，中医称「阴化气，阳成形」","庚子辛亥属形化气，中医称「阳化气，阴成形」"],"ans":3,"exp":"庚子、辛亥是金之形化水之气（形化气）；投资生产出产品是气化形；中医讲阳化气、阴成形，先有气之病再发展为形之病，病字中的丙即阳气。","sec":"2. 形气转化（命局高低的关键）","t":"rule"},{"q":"体用关系中「体全而用缺」与「知其白而守其黑」各指什么道理？","opts":["用不能穷尽体；体阴守黑是为了追求阳用而非抱阴","体全必致用全；守黑只需自保，不必追求阳用","用可反过来决定体；不知白而守黑方为大贵","一物只能有一用；阳用必以阳体为根基方能成格"],"ans":0,"exp":"体全而用缺指用不能穷尽体（如天四季人用三、一周七天用五）；体阴用阳重在「知」，知其白而守其黑是体阴以求阳，不知白而守黑只是穷困。","sec":"2. 体用三种关系","t":"rule"},{"q":"用「体与用」理解命理做功时，为何不讲单一用神？","opts":["用神只管大运不管流年，故必须彻底废弃","单用神难表复杂命运，须体与用关联做功","所有干支在命局中只有固定单义，无须取象","体与用各自孤立静止，不需要发生任何关联"],"ans":1,"exp":"干支本体如多重叠加，动则坍缩成单一象；一个用神表达不了复杂命运，体＝我与所用工具，用＝要实现的目的，体用发生关联才叫做功。","sec":"3. 体用与命理","t":"rule"},{"q":"隐性因果与显性因果的本质区别在哪里？","opts":["两者皆不可预知，术数只能解释过去不能推知未来","显性因果只管婚姻，隐性因果只管物理化学反应","显性因果多因且不可预知，隐性因果只有命运定数一因","显性因果只有一因可避，隐性因果多因且可随意更改"],"ans":2,"exp":"显性因果是物质世界可观察的多因且不可预知；隐性因果则是术数逻辑，事背后只有一个原因——命运的定数，知与不知都避不开。","sec":"1. 两种因果","t":"diff"},{"q":"盲派断命时，「象」与时代背景、先天禀赋之间是什么关系？","opts":["同一命局在古代与现代所应灾象必然完全一模一样","读象只需死记硬背神煞，不必结合相似性合理推断","象完全脱离时代背景，后天教育可彻底改变先天命格","象在相似性基础上依时代合理推断，先天禀赋非后天可改"],"ans":3,"exp":"同一凶局在古代应火灾、在现代应车祸，象是在相似性基础上的合理推断，读象是重要基本功；禀赋（性）先天，后天的习改变不了命。","sec":"2. 命例：车祸之断","t":"xiang"},{"q":"从根本上说，「象」的本质是什么？它靠什么打破物与人的边界？","opts":["象的本质是相关性，靠时间（干支时相）消解万物边界","象的本质是外形相同，靠空间距离消解万物边界","象只是文学比喻，在现实中并无客观可检验的关联","象是五行物质的直接堆砌，干支本身就是命运的原因"],"ans":0,"exp":"象的本质不是相似，而是相关性；圣人以时间（有结构的干支时相）消解物与物、物与人的边界；干支是对命运的描述与模拟，而非命运的原因本身。","sec":"3. 象的定义","t":"rule"},{"q":"在五行类象中，胃中有火常表现为口苦，这体现了五行与五味、五脏的哪种对应？","opts":["金对应辛味与肺，燥气内收故见口苦","火对应苦味与心，热气上扰故见口苦","木对应酸味与肝，寒气下行故见口苦","土对应甘味与脾，湿气困阻故见口苦"],"ans":1,"exp":"五行类象中火对应热、赤、礼、心、南、苦，故口苦对应火（胃中有火），是由自然之象推及人事与医理的体现。","sec":"3. 五行类象（象义的第一层）","t":"xiang"}]},{"n":47,"level":"中级","title":"十神与宫位","qs":[{"q":"按盲派，为什么取日主旺衰没有意义？","opts":["日干旺衰只表身体，不表能力","日干是用，旺衰要看月令根气","日干衰旺随大运变化，难以定论","日干是体，十为体、只用其九"],"ans":3,"exp":"日干代表「我」，是体不用；把体放到用的位置是没理解命理本质，日主旺衰也不代表能力、身体。","sec":"一、十干之位","t":"rule"},{"q":"乙庚合与丁壬合，哪一方沾光、为什么？","opts":["乙、丁沾光，阴合阳是上升","庚、壬沾光，阳合阴是上升","庚、壬沾光，位低合位高上升","乙、丁沾光，位高者必占便宜"],"ans":0,"exp":"阴喜合阳则上升层次，阳合阴则降低层次；辨合得好不好既看位次也看阴阳。","sec":"二、十干之性","t":"diff"},{"q":"丁壬合、戊癸合，各自常见的类象是什么？","opts":["丁壬多金融理财；戊癸多写作文章","丁壬多写作文章；戊癸多启蒙演说","丁壬多戴帽子；戊癸多镀镜光亮","丁壬多启蒙演说；戊癸多金融理财"],"ans":1,"exp":"丁壬是笔墨之合，多有写作文章之象；戊癸是化彩之合，多为启蒙、演说之象。乙庚才多类象金融。","sec":"三、天干五合","t":"xiang"},{"q":"日主为乙，天干见庚，按盲派这个庚是什么关系？","opts":["七杀，必与日主相合","七杀，必克日主","正官，必与日主相合","正官，必克日主"],"ans":2,"exp":"阴日主正官必合身（乙见庚，必乙庚相合）；阳日主正财必合身（甲见己）。","sec":"四、十神释义","t":"calc"},{"q":"日主为甲，地支见子、亥、午、巳，依次标注十神，哪组正确？","opts":["枭、印、伤、食","印、枭、食、伤","枭、印、食、伤","印、枭、伤、食"],"ans":3,"exp":"地支先取本气：子阴水为印，亥阳水为枭，午阴火为伤，巳阳火为食。同性为偏、异性为正，我生同性为食、异性为伤。","sec":"四、十神释义","t":"calc"},{"q":"伤官合杀、伤官合印、食神合印、食神合官，按盲派哪个多数不喜？","opts":["食神合官","伤官合杀","食神合印","伤官合印"],"ans":0,"exp":"食神是体，合官是自己合到麻烦、引鬼上身；伤官是用、是工具，合杀吉。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，阳官与阴官、阴杀与阳杀，作用有什么不同？","opts":["阳官克身主约束；阴官合身有害无益","阳官合身主约束；阴官克身有害无益","阴杀合身不克害；阳杀克身主杀伐","阴官阳官都克身，只是力度不同"],"ans":1,"exp":"官杀分阴阳：阳官合身主约束，阴官克身有害无益；阴杀克害，阳杀不克害。","sec":"五、十神的社会学内涵","t":"diff"},{"q":"按盲派，男命和女命各以什么十神看子女？","opts":["女命看官杀；男命看伤食","女命看印；男命看财","女命看伤食；男命看官杀","男女都看伤食，官杀为辅"],"ans":2,"exp":"女命以伤官食神为子女，男命以官杀为子女；不论男女，财星也可代表孩子。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，母亲、父亲分别取哪个十神？","opts":["母取正印；父取偏财","母取食神；父取正印","母取正印；父取财星","母取食神；父取财星"],"ans":3,"exp":"母亲取食神（养育给予），父亲取财星（养命之源）；印的本意是保护，不称父母。","sec":"六、配与十神的六亲","t":"rule"},{"q":"按盲派，正财一定代表正妻、偏财一定代表妾吗？","opts":["不一定，正妻要看夫妻宫","男命如此，女命不论","一定，正偏分妻妾","要看财星是否合日主而定"],"ans":0,"exp":"并非正财是正妻、偏财是妾，正妻要看夫妻宫；财星落在比肩劫财下，再怎么讲都是别人的老婆。","sec":"六、配与十神的六亲","t":"diff"},{"q":"按盲派，里外与宾主的划分是什么？","opts":["年时为里、月日为外；年月为宾、日时为主","月日为里、年时为外；年月为宾、日时为主","月日为里、年时为外；日月为宾、年时为主","年月为里、日时为外；年日为宾、月时为主"],"ans":1,"exp":"年月一家为宾，日时一家为主；月日为里，年时为外，外边包里边。","sec":"七、四柱宫位","t":"rule"},{"q":"为什么配偶宫坏必离婚，而子女宫坏不一定克子女？","opts":["配偶宫为日主根，孩子宫离日主远","配偶宫为里，子女宫为外不影响","配偶不回家不成婚，孩子远走正常","配偶宫看十神，子女宫只看星"],"ans":2,"exp":"配偶不回家就不算婚姻；孩子不回家很正常。所以子女宫坏多看孩子远离，宫与星俱坏才克子女。","sec":"七、四柱宫位","t":"rule"}],"fine":[{"q":"以植物生长过程描述十干之序时，庚、辛、癸分别对应什么象？","opts":["庚为初生嫩芽，辛为茂盛长成，癸为收割入仓","庚为种子破壳，辛为破土而出，癸为开出小花","庚为结出果实，辛为选种繁殖，癸为果实变硬","庚为果实成熟变硬，辛为收割，癸为归藏种子"],"ans":3,"exp":"十干序中，庚通更，为果实成熟变硬；辛古为刀，为收割；壬为孕育选种；癸为归、收藏种子以待来年。","sec":"2. 以植物生长描述十干之序","t":"xiang"},{"q":"以社会阶层比拟十干之序时，丙丁、戊己、庚辛分别代表哪类阶层？","opts":["丙丁知识精英，戊己资本财富，庚辛工薪奋斗","丙丁权贵阶层，戊己知识精英，庚辛学生启蒙","丙丁资本财富，戊己工薪奋斗，庚辛权贵阶层","丙丁工薪奋斗，戊己权贵阶层，庚辛资本财富"],"ans":0,"exp":"甲乙权贵阶层，丙丁知识精英（掌握话语权），戊己资本财富阶层，庚辛工薪奋斗阶层，壬癸高智商学生阶层。","sec":"3. 十干之序：由阳到阴，有尊卑贵贱","t":"diff"},{"q":"关于十干五合的人物写照，甲己合与癸水攀附之象分别有何特点？","opts":["甲最喜合己显慷慨大方；癸最低位却只能向下依附","甲一般不喜合己显低头小气；癸最低位却最易攀高逆袭","甲合己必主大富贵；癸唯有合辛才能改变自身阶层","甲己合是刚柔相济之象；癸水固守本位绝不攀附他干"],"ans":1,"exp":"甲头己地，甲己合有低头折腰之象，一般甲不喜合己，至少显小气；癸虽居十干末位，却能嫁戊或攀甲而逆袭上位。","sec":"五合的人物写照","t":"xiang"},{"q":"关于天干五合的合化与阴阳属性，盲派的观点是什么？","opts":["五合必论合化真假，且合化后彻底改变日主五行；合属阳","合与冲皆属阳，天干五合在命局中不改变任何天干之性","讲合不讲化，合化仅五运六气用；合属阴，冲属阳","讲化不讲合，河图之数只用于地支六合而不用于天干"],"ans":2,"exp":"五合源于河图之数（1-6、2-7、3-8、4-9、5-10），命理讲合不讲化（五运六气才用）；相对冲而言，合属阴，冲属阳。","sec":"1. 合的几个问题","t":"rule"},{"q":"「合」有六层含义，丙辛合为明眸善睐大眼、伤官合印为学习知识，各属哪层含义？","opts":["前者属「结合」，后者属「获得与加码」","前者属「发用」，后者属「粘合附着」","前者属「连接」，后者属「定义关系」","前者属「定义关系」，后者属「发用」"],"ans":3,"exp":"丙为眼、辛主清彻水润，丙辛合定义出明眸善睐（定义关系）；伤官（想法）合印（文化）为体发用于用（发用）。","sec":"2. 「合」的六层含义","t":"diff"},{"q":"天干五合的物象中，「高楼贴马赛克」「现代金融理财」「高楼跳下」依次对应哪组五合？","opts":["甲己合、乙庚合、戊癸合","甲己合、丙辛合、丁壬合","戊癸合、丁壬合、甲己合","乙庚合、戊癸合、丙辛合"],"ans":0,"exp":"甲己为装贴之合（高楼贴马赛克）；乙庚为刚柔制器之合，古用线串钱，今多类象金融理财；戊高台、癸低凹，戊癸合为高楼跳下。","sec":"3. 五合之象（相反之象相合）","t":"xiang"},{"q":"关于十干之禄，下列哪一组干与禄的对应关系全部正确？","opts":["丙禄在巳，戊禄在辰，丁禄在午，己禄在未","丙戊禄在巳，丁己禄在午，壬禄在亥，癸禄在子","丙戊禄在午，丁己禄在巳，壬禄在子，癸禄在亥","庚禄在酉，辛禄在申，甲禄在寅，乙禄在卯"],"ans":1,"exp":"十干之禄（比肩称禄）：甲禄寅，乙禄卯，丙戊禄巳，丁己禄午，庚禄申，辛禄酉，壬禄亥，癸禄子。","sec":"1. 十神的定义","t":"calc"},{"q":"按五种能力生克规律，「依赖心强不强调尊严」与「沟通力强不爱思考」分别因何而起？","opts":["前者因财泄伤食，后者因印泄比劫","前者因伤食泄比劫，后者因官杀泄财","前者因印泄官杀，后者因财泄伤食","前者因官杀泄财，后者因印泄官杀"],"ans":2,"exp":"印为借助、官杀为尊严，印泄官杀则依赖强而不重尊严；财为沟通、伤食为思考，财泄伤食则善沟通而不爱思考。","sec":"2. 人性与社会角度的十神","t":"diff"},{"q":"从先天本能与后天社会性划分十神，下列哪一组全部属于「社会性」十神？","opts":["比肩、劫财、偏财","食神、伤官、比肩","正财、偏财、食神","印、官杀、劫财"],"ans":3,"exp":"食神、伤官、财、比肩（禄）属先天本能；印（文化归宿）、官杀（荣誉磨难）、劫财（社会竞争行动力）属后天社会性。","sec":"4. 先天与后天","t":"diff"},{"q":"十神衍生含义中，印、财、劫财在现实人事物上各有何对应？","opts":["印为文凭单位车房，财为下属沟通力，劫财为对手乙方","印为自我享受劳累，财为荣誉心机多疑，劫财为下属金钱","印为学生艺术吃喝，财为衣服文凭地位，劫财为领导权力","印为官方小人官司，财为服务爱好任性，劫财为房子车子"],"ans":0,"exp":"印为庇护（衣车房、文凭单位）；财为支配沟通（金钱、下属、语言之才）；劫财为争夺、朋友、对手、乙方、破财者。","sec":"5. 十神衍生含义","t":"xiang"},{"q":"盲派对十神吉凶的校正中，关于「凶神」与「财星合日主」各有什么要点？","opts":["凶神永远不如吉神可用；财合日主主破财，应尽量避开","凶神得用比吉神厉害；财合日主是我要追求的，优先看","凶神唯有被彻底克制才算好命，财合日主反而不爱沟通","正印必是正当职业，偏财必是非分之财，不可混为一谈"],"ans":1,"exp":"杀伤刃虽为凶神，但得用比吉神厉害，成就高者多用凶神；财星合日主是我要追求的，优先看，且兼有沟通与欲望之意。","sec":"6. 五点校正","t":"rule"},{"q":"从自我与社会交换角度看，伤官、食神、印各自的社会学性格是什么？","opts":["伤官主社会制高点，食神主扁平大众化，印主个性张力","伤官平和重服从，食神偏激爱对抗，印突出锋芒毕露","伤官偏激重独创，食神平和随遇而安，印普遍化易平庸","伤官与食神性格完全相同，唯有印星才决定名声高低"],"ans":2,"exp":"伤官偏激蔑视规则重独创，食神平和不走极端；印是主流大众化、扁平化，印重易平庸，伤食合印则思想被社会认可。","sec":"1. 自我与社会","t":"diff"},{"q":"在十神心性对照中，哪两个十神合谋容易「义气用事、不守规则」而干坏事？","opts":["正官与正印合谋","食神与正财合谋","七杀与偏印合谋","比劫与伤官合谋"],"ans":3,"exp":"比劫冲动讲义气、没耐心，伤官不守规则、点子多，二者合谋如愣头青配狗头军师，容易干坏事。","sec":"2. 十神心性对照","t":"xiang"},{"q":"关于阳日主与阴日主的伤官所合对象，盲派的规律是什么？","opts":["阳日主伤官合印，阴日主伤官合杀，合杀更厉害","阳日主伤官只合官，阴日主伤官只合食神","不论阴阳日主，伤官皆优先合财，绝不合印合杀","阳日主伤官合杀，阴日主伤官合印，合印更厉害"],"ans":0,"exp":"阳日主伤官合印，阴日主伤官合杀；合杀更厉害，因为七杀是社会组织突出点、制高点，一旦用起来极有张力。","sec":"3. 伤官合杀与合印","t":"rule"},{"q":"新事物或企业发展的十神链条，从创造到最终破产的正确顺序是什么？","opts":["印创造→生比劫融资→生伤食突出→生财规模化→生官杀破产","伤食创造→生财融资→生官杀突出→生印规模化→生比劫破产","官杀创造→生印融资→生伤食突出→生比劫规模化→生财破产","伤食创造→生印融资→生比劫突出→生官杀规模化→生财破产"],"ans":1,"exp":"伤食（创造）→生财（融资）→生官杀（企业社会化成突出点）→生印（规模化普及扁平化）→生比劫→最终破产。","sec":"3. 伤官合杀与合印","t":"step"},{"q":"盲派为何说「财富 ≠ 财星」？真正构成财富级别的十神组合应看什么？","opts":["财星太重反主贫穷；唯有比劫重重才代表巨额资本财富","官杀只主权力不管财富；财富大小全看伤官生财多少","财星只是养命之源；官杀得用才可能成财富，规模看印","印星太重越能发大财；官杀反而会拖累企业无法规模化"],"ans":2,"exp":"财星只是自己支配的养命之源，够不上资本财富；官杀得用才可能是财富，规模看印（虚印、财合印主放大加码融资）。","sec":"3. 伤官合杀与合印","t":"diff"},{"q":"若命局中伤官偏性太重，必须社会化才有用，其途径中效率最低的是哪一种？","opts":["伤官被印制","伤官去合印","伤官去合杀","伤官去生财"],"ans":3,"exp":"伤官偏性太重，要社会化（合印、被印制、合杀、或生财）才有用，其中去生财是效率最低的方式。","sec":"3. 伤官合杀与合印","t":"rule"},{"q":"「配」有虚配、干支上下一体为配之意，其中「配杀」与「配比劫」各主何义？","opts":["配杀主突出张力化；配比劫一般指这东西是别人的","配杀主实用趣味化；配比劫主放大包装上市","配杀主隐藏不露；配比劫主自己独享控制","配杀主艺术个性；配比劫主绝对大吉大利"],"ans":0,"exp":"配杀主张力化、突显引人注目；配比劫不一定好，一般指这东西是别人的（如财配比劫＝别人的钱）。","sec":"1. 「配」","t":"diff"},{"q":"六亲取星时，若女命局中无官杀，或看男人之「禄」是否幸福，各应如何取用？","opts":["女无官杀以印星当夫；有禄须见比劫夺才幸福","女无官杀以财星当夫；有禄须有印护才幸福","女无官杀以比肩当夫；有禄绝不可见印星相护","女无官杀则终身无夫；有禄见官杀冲克才算幸福"],"ans":1,"exp":"女命以官杀为夫，无官杀则以财星当夫（财养命合养家）；禄主享用也主忙碌，有禄要有印护才幸福。","sec":"2. 十神与六亲（命理称十神不称六亲）","t":"rule"},{"q":"为何说「成功未必幸福」，而真正让人获得幸福的十神主要是哪类？","opts":["比肩与劫财，因行动竞争能让人始终保持紧张感","偏印与七杀，因越能吃苦耐劳内心便越安逸自足","财星与伤食，因财克印可保护伤食之自由与免于匮乏","官杀与正印，因官杀带来极高社会地位且毫无压力"],"ans":2,"exp":"官杀与印代表社会性，易身不由己；财与食伤代表本性，财克住印、保护伤食自由且免除匮乏，故财与伤食让人幸福。","sec":"3. 幸福的人生","t":"rule"},{"q":"在四柱里外与包局结构中，「开门店往外卖」与「进牢房」各体现了怎样的结构？","opts":["两者皆属月日包住年时，只是十神阴阳不同","门店看年柱宾位，牢房只看日支坐下而不看外柱","门店是外边包住里边，牢房是由里向外推","门店是由里向外发，牢房是外边凶煞包住里边"],"ans":3,"exp":"月日为里、年时为外：开门店要把里边的东西往外卖；进牢房是外边凶煞包住里边，跑不出去。","sec":"1. 宾主与里外","t":"xiang"},{"q":"问孩子适不适合出国、或看人老年能否走动，分别主要先看哪一柱？","opts":["出国先看年柱（远方），能否走动看时柱（门户）","出国先看时柱（门户），能否走动看年柱（祖上）","两者皆只看月柱父母宫，与年柱时柱无关","出国先看日支（居所），能否走动看月柱（家乡）"],"ans":0,"exp":"年柱空间为远方，问出国先看年柱；时柱空间为门户，人能不能走动要看门户（时柱）开不开。","sec":"2. 时间与空间","t":"rule"},{"q":"宫位对应身体部位时，年柱、月柱、日支、时柱分别对应人体的哪些部位？","opts":["年五官头部、月腿足、日支脊柱、时胸腹脏腑","年腿足、月脊柱身躯、日支胸心脑脏腑、时五官手生殖器","年脊柱、月胸脑、日支五官生殖器、时腿足","年胸腹脏腑、月五官手足、日支腿足、时脊柱"],"ans":1,"exp":"年离日主最远为腿足；月为身躯脊柱；日支为核心（胸、五脏六腑、心脑）；时为门户（五官、手、生殖器官）。","sec":"4. 宫位与身体","t":"xiang"},{"q":"关于宫位中的人物与物件，下列哪一项判断是正确的？","opts":["车子、眼镜、化妆品物件多看年柱，鞋子拐杖多看时柱","比劫落配偶宫必表多人争配偶；财落比劫下是自己正妻","比劫落配偶宫不表争配偶；财落比劫下是别人的老婆","同学同事老乡多看时柱，学生晚辈下属多看月柱"],"ans":2,"exp":"日支只有配偶能在，比劫落配偶宫不表争配偶；财星落在比肩劫财下是别人的老婆。年为鞋拐，月为同学同事，时为车衣镜饰与晚辈。","sec":"5. 人物与物件","t":"diff"},{"q":"为什么印星在六亲中不直接代表父母？","opts":["印星属社会性十神，在八字排盘中永远不参与六亲","印星专门代表配偶与子女，无法兼代父母","印星只代表单位与文凭，与所有血缘亲属都无关","印的本意是保护，而父母的意义主要在养育不在保护"],"ans":3,"exp":"印的本意是保护，父母保护时间很短，父母的核心意义在养育（食神主母、财星主父），故印不称父母。","sec":"2. 十神与六亲（命理称十神不称六亲）","t":"rule"}]},{"n":48,"level":"中级","title":"十天干象义","qs":[{"q":"按盲派，十天干里阴日干共同怕见什么、最喜见什么？","opts":["怕七杀，喜见甲","怕七杀，喜见庚","怕偏印，喜见甲","怕伤官，喜见丙"],"ans":0,"exp":"阴日干多怕七杀，几乎都喜见甲，其中最喜甲的是癸。","sec":"通用要点","t":"rule"},{"q":"甲、丙、戊、庚、壬这些阳干，更宜占体还是占用？","opts":["宜占体，占用易受克","宜占用，占体不一定好","体用皆宜，阴阳无别","只有逢旺地才宜占用"],"ans":1,"exp":"阳干高贵而用处少，占体不一定好，宜占用；阴干卑而可用之字多。","sec":"通用要点","t":"diff"},{"q":"甲日见辛与乙日见辛，处理上有何不同？","opts":["甲可用丙合辛，乙没有办法","两者都可以用丙去合住辛","乙可丙合丁制，甲没办法","两者都可以用丁来克制辛"],"ans":2,"exp":"丙是甲之体不可制，丁制则生争斗；乙见辛可用丙合之、丁制之保全。","sec":"二、乙","t":"diff"},{"q":"甲日见己合，一般怎么看？","opts":["合土化象，甲木转旺有力","合后甲得己土所生，主贵","合则财来就我，主大吉","贪恋己财而失贵性，不喜"],"ans":3,"exp":"甲己合是甲贪恋己之财色、失其贵性，合象低头，一般不喜合己。","sec":"一、甲","t":"rule"},{"q":"丙日见下列哪个时柱的丙，属于“丙不落地”、反易成贵格？","opts":["丙申","丙戌","丙午","丙寅"],"ans":0,"exp":"丙子、丙申、丙辰是丙不落地，代表天上之日，不落地反易成贵格。","sec":"三、丙","t":"calc"},{"q":"丙日见甲木，数量上怎么论吉凶？","opts":["越多越旺，三个最贵","一个最好，两个坏格，三个破格","一个破格，两个最好","两个最好，一个太弱"],"ans":1,"exp":"甲生助丙，但多则森林蔽日：一个最好，两个坏格，三个破格。","sec":"三、丙","t":"rule"},{"q":"丙和丁在天干中数量上的喜忌有何不同？","opts":["丙丁都是一个最好","丙多反喜，丁一个就好","丙一个就好，丁多反喜","丙丁都是越多越好"],"ans":2,"exp":"丙为太阳一个就好；丁为星星，星罗棋布，多则反喜，丁多为吉。","sec":"四、丁","t":"diff"},{"q":"丁日见甲、见乙，各怎么论？","opts":["甲乙两者都喜见","甲最恨，乙极喜","甲乙两者都忌见","甲极喜，乙最恨"],"ans":3,"exp":"甲高贵为阳，生丁无条件，是丁最大的贵人；乙仅因是阴就成仇人，丁见乙总有不好的事。","sec":"四、丁","t":"rule"},{"q":"戊土独透天干，职业上常见什么象？","opts":["容易当老师","容易从军","容易做会计","容易经商"],"ans":0,"exp":"戊为高台、讲台，一阳统全阴，别人听他讲看他演；戊土独透者容易当老师。","sec":"五、戊","t":"xiang"},{"q":"戊日见庚（食神）时，要注意哪一点？","opts":["食神必须见财才有用","食神与偏印不可同见，枭神夺食","食神与比肩同见则夺食","食神最忌与官星同见"],"ans":1,"exp":"戊日见庚是食神，喜，但食神与偏印不可同见（枭神夺食）；最怕官星乙来合。","sec":"五、戊","t":"rule"},{"q":"庚日见丙、见丁，各怎么论？","opts":["丙丁都喜，火越旺越好","丙丁都怕，只喜水来柔化","极喜丙煅炼，怕见丁","怕丙煅炼，喜丁点化"],"ans":2,"exp":"庚日极喜丙煅炼成器；丁像气割枪打洞使铁板作废，不喜见丁。","sec":"七、庚","t":"rule"},{"q":"癸见壬，与壬见癸，为什么不同？","opts":["壬见癸得助，癸见壬被克","癸见壬被夺，壬见癸被生","两者都是同类相并，皆吉","癸并入大河放大，壬见癸变小"],"ans":3,"exp":"水可混而并流，小溪并大河放大自己，所以癸特喜壬劫透干；壬见癸则大变小，不喜。","sec":"十、癸","t":"diff"}],"fine":[{"q":"关于十干「占体」与「占用」及象法原则，下列哪项表述准确？","opts":["象法核心是通于理才合象；阴干卑而可用之字多","天干虚实完全由月令决定，与地支根气和合去无关","象法只看字形不问事理；阳干尊贵故可用之字极多","阳干必须占体才能发贵，阴干占体则必定贫贱"],"ans":0,"exp":"象法核心是「一切通于理，合理了才合象」；阳干高贵而用处少、宜占用，阴干卑而可用之字多。","sec":"通用要点","t":"rule"},{"q":"甲木见壬（偏印）与见癸（正印），在喜忌与象义上有何区别？","opts":["壬癸皆为甲木印星，对活木死木的吉凶完全一致","甲为活木时喜壬水滋长，死木不喜；甲最怕癸如虫侵害","甲最喜癸水雨露滋养，最怕壬水泛滥冲奔漂木","死木最喜壬水浸泡，活木最喜癸水滴灌生发"],"ans":1,"exp":"甲须是活木才喜壬生，死木（如甲申）不要壬生；甲最怕癸，癸似虫子侵害甲木，常见头上有疤、长痘。","sec":"一、甲","t":"diff"},{"q":"甲日见丙火食神与见丁火伤官，各有何讲究？","opts":["活木见丙易燃尽而灭，死木见丙如开花般漂亮","甲木见丁无需配印，自然可成栋梁显贵","甲日丙寅时丙为体须护；见丁配壬印则聪明入正道","甲日丙寅时最喜癸克辛合；见丁越旺越显大智慧"],"ans":2,"exp":"活木见丙如开花、死木如燃烧；甲日丙寅时丙是体，合辛或被癸克就坏了。丁心性偏颇为小聪明，合壬配印则才华正显。","sec":"一、甲","t":"rule"},{"q":"甲木日主的四大病象与最佳成格思路分别是什么？","opts":["土重水多火少金缺为病；最好比劫重重而无官杀","活木最怕见庚七杀；最好纯用癸水正印贴身","木多成林为最大病象；最好纯用正官辛金来钉制","火焚水漂金伤寒夭为病；最好见伤官食神而配印"],"ans":3,"exp":"甲木病象：火多无印必焚，水多无根则漂，金多克伐则伤，寒重冷酷则夭；甲日最好见伤官食神而配印。","sec":"一、甲","t":"xiang"},{"q":"关于乙木的象义与性情，下列哪一项对应准确？","opts":["乙在天为风，象形为波主连接传播，配丁或乙巳为书本","乙在天为雷，象形为直主刚强固执，最怕同日主交往","乙在人体对应胆与骨骼，甲对应肝与弯曲关节部位","乙日生人最忌周围多同日主，因大树须保持距离"],"ans":0,"exp":"乙在天为风、在地为禾，象形弯曲为波，主连接（互联网）与传播；配丁或乙巳为书本象；甲胆乙肝；甲不喜多，乙不怕多。","sec":"二、乙","t":"xiang"},{"q":"乙日见丙、壬、癸各有什么喜忌差异？","opts":["乙见丁食神最喜癸水相配，能成文章显达之象","冬日乙见丙如沐春风显贵；喜壬水正印而怕癸水偏印","冬日乙见丙主火焚木枯；喜癸水雨露而怕壬水冲奔","乙见壬午时最忌读书；乙见癸水反能助禾苗快速成长"],"ans":1,"exp":"冬日乙见丙如沐春风，显贵无比；乙见丁最怕癸夺；同是水，乙喜壬正印（壬午时易上大学），却不喜癸偏印（害虫象）。","sec":"二、乙","t":"diff"},{"q":"从人体与心理层面看，丙丁与壬癸在人类认知上分别代表什么？","opts":["丙火主心灵玄学思想，丁火主视觉感官与大剧场表演","丙丁为耳与肾，火主理性；壬癸属水，水主视觉艺术","丙丁为眼与心，火主感性；壬癸属水，水主理性逻辑","人类的理性逻辑与感性艺术皆归丙丁，与水毫无关系"],"ans":2,"exp":"丙丁代表眼睛与心，火主感性（丙偏视觉感官，丁偏思想心灵），水主理性与逻辑（属壬癸）。","sec":"三、丙","t":"diff"},{"q":"丙日见戊、己、壬、癸时，哪一组喜忌判断完全正确？","opts":["见己为阳光普照大吉；见癸最喜雨天润日而见壬大凶","丙日见壬癸皆为官杀混杂大凶，见戊己皆为云遮日象","见戊必主鬼上身大凶；配庚寅时大富而配庚子时主贫","见戊最忌再见癸；见己为云遮日晦；见壬喜而见癸怕"],"ans":3,"exp":"丙见戊如一家但不可再见癸（一合鬼上身）；见己为云遮日象身体不大好；见壬为日照江湖喜，见癸为雨天无日怕（唯癸巳时弱害不大）。","sec":"三、丙","t":"diff"},{"q":"丁日若遇到「丙夺丁光」的情况，什么条件下丁火反而能强势反夺丙光？","opts":["丁火多一个（或行丙大运时星多太阳没落）","遇乙木偏印来生丁火之时","遇癸水七杀贴身克制丁火之时","遇戊土伤官泄尽丁火之时"],"ans":0,"exp":"丙夺丁光是一丁遇丙被压住；但丁多一个，星多太阳没落，丙丁反夺丙光而丁反强势，故丁不怕丙大运。","sec":"四、丁","t":"diff"},{"q":"关于丁日见己、辛、壬的象义，下列哪一项说法准确？","opts":["见己食神最不爱读书思考；见辛丑比辛亥钱财更丰厚","见己食神如厚书爱读书思考；见辛亥比辛丑钱财更多","丁壬配壬寅时，男命必主爱化妆、女命必主入公门","丁日见庚戌时主大富贵，见庚子时则只主空有才气"],"ans":1,"exp":"己如厚书，丁见己食神爱读书爱思考；丁见辛财虚为好，辛亥比辛丑好主钱财多；丁壬配壬寅，女爱化妆、男多在公门。","sec":"四、丁","t":"xiang"},{"q":"戊土「上天为高台，落地为平台」，这一象义与哪两类现实职业或事业相通？","opts":["在天干为秘密情报（如玄学），落地为航海运输（如航运）","在天干为金融货币（如银行），落地为医药化学（如制药）","在天干为高台讲台（如老师），落地为平台（如交易平台）","在天干为地下矿藏（如采矿），落地为空中楼阁（如影视）"],"ans":2,"exp":"戊高高在上为高台、讲台（一阳统全阴，适合老师、法官、演员等），落地则为平台（如交易平台），用同一象。","sec":"五、戊","t":"xiang"},{"q":"戊日见甲、乙、丁、辛时，下列喜忌说法正确的是哪一项？","opts":["最喜乙卯时（官星护身），最怕甲寅时（七杀攻身）","戊日不论生于何季，见丙火偏印皆为大忌而不可用","戊见辛伤官绝不可配火印，配印则伤官无用反成大害","喜甲寅时（怕己合甲），最怕乙卯时；见丁巳为连体通禄"],"ans":3,"exp":"戊喜甲寅时主大财富（怕己合甲及旺火泄），最怕乙卯时；戊见丁巳为归禄（连体通禄）；见辛极喜配火印方贵；冬戊喜丙。","sec":"五、戊","t":"rule"},{"q":"己土「在天为云，在地为土」，在现代物象与人体上分别有何常见取象？","opts":["现代常取装潢材料、云计算（己亥）；人体为各种通道与肌肉","现代常取钢铁矿山、金融银行；人体为大肠肺部与神经","现代常取航空航天、芯片制造；人体为骨骼牙齿与眼睛","现代常取影视传媒、电力光热；人体为心脏大脑与精液"],"ans":0,"exp":"己在天为云，己亥可取云计算，现代物象常取磁砖、马赛克等装潢材料；人体为食道、呼吸道、肠道等各种通道及肌肉。","sec":"六、己","t":"xiang"},{"q":"己日见甲（正官）一般喜合贵，但为何见「甲戌时」未必好？","opts":["戌土为火库，会直接将甲木焚烧殆尽而破格","甲下坐劫财戌，甲头戌手，戌成命主的手而干活劳累","甲戌为虚透无根之官，主其人一生清闲不爱工作","甲木在戌月绝地无根，不能合己土反而反克己土"],"ans":1,"exp":"己喜合甲攀贵，但甲戌时甲下坐劫财戌，甲头戌手，戌成了命主的手，用手干活累。此外己怕乙（尤乙亥）与丁多现，喜丙寅与辛。","sec":"六、己","t":"diff"},{"q":"盲派为何纠正旧教材「庚在天为霜」的说法，而定为「庚在天为降气」？","opts":["霜属于木火之余气，与秋季金气收敛完全没有任何关联","庚属阳金绝对不怕寒霜，唯有夏火才能使庚金产生降气","霜降已晚；立秋气先到而天未凉，秋高气爽即降气使沙尘落","立秋之后气温必然骤降成霜，只是庚金不喜霜雪覆盖"],"ans":2,"exp":"霜降太晚，庚在天是降气（与春木升气相对）；立秋呼吸道过敏因气先到天未凉，秋高气爽是降气使沙尘落下、空气干净。","sec":"七、庚","t":"xiang"},{"q":"庚日见壬（食神）配壬午时「食神压官」，为何不是凶险的「鬼上身」？","opts":["食神合官在所有阳干日主中都是大吉，从来不论虚实","壬水能直接克灭午火官星，使官星彻底消失而不为害","午火中藏丁火正官，与壬水相合后必然化为木局助身","食神不喜合官指食神当体时，壬水虚透不为体故可合官"],"ans":3,"exp":"食神不喜合官是指食神当体时；庚日壬午时，壬虚不为体，可以合官，虚与实区别很大。庚见癸伤官则主生锈、不爱学习。","sec":"七、庚","t":"diff"},{"q":"关于汉字「辛」的特性，中医讲「气」与命理讲「象」有何区别？","opts":["中医讲气，辛为散为燥；命理讲象，辛为润为收","中医讲气，辛为润为收；命理讲象，辛为散为燥","中医只用生石膏取收性，命理只用生石膏取散性","两者皆论辛为辛辣燥热，命局见辛必主肺燥皮肤差"],"ans":0,"exp":"中医讲气（六气影响人体）：辛为散、为燥；命理讲象（归为有形之物）：辛为润、为收。辛配水主皮肤好、不易显老。","sec":"八、辛","t":"diff"},{"q":"阴日干多怕偏印透干，为何辛日反喜己土偏印而不喜戊土正印？","opts":["辛金最喜己丑时而最怕己亥时，因己丑土最湿润","辛喜润怕燥（像肺），戊土燥而土厚金埋，己为湿土润金","辛日癸己同透天干最为大吉，毫无半点冲突","戊土为高台能克辛金，己土为平原能直接生出甲木"],"ans":1,"exp":"辛喜润怕燥，戊（尤戊戌）燥且土厚金埋，故不喜；己为湿土润金，辛日己亥时多好（己制亥伤官），己丑较差，但癸己同透有冲突。","sec":"八、辛","t":"diff"},{"q":"辛日见甲午时、庚寅时、癸巳时，各自的典型象义是什么？","opts":["癸巳时为伤官见官大凶，女人主孤苦无魅力","甲午只论正财不看午杀；庚寅男命必主大贫无财","甲午木从火象取午杀看贵人；庚寅女命多婚不佳但不差钱","丙申时丙官最实最贵，劫财申金反能助日主做大官"],"ans":2,"exp":"辛日甲午时木从火象取午杀看贵人；庚寅时官杀盖劫，女多婚姻不好（男人被劫）但不差钱；癸巳时食神制官，女有魅力男交贵人。","sec":"八、辛","t":"xiang"},{"q":"壬水除「江河湖海」物象外，在性格与职业上具有哪两层核心含义？","opts":["温和与厚重、装潢与地产；多与建筑讲台相关易成教师","孤傲与洁癖、精致与毒舌；多与法律首饰相关易成律师","感性与艺术、清闲与享受；多与表演色彩相关易成演员","理性与智慧、负担与责任；多与数字相关易成会计师、IT"],"ans":3,"exp":"壬水两层核心含义：理性智慧、负担责任（妊、闰月皆有负担与双数意）；壬多与数字相关，职业易成会计师、IT精英；壬合丁文章一流。","sec":"九、壬","t":"xiang"},{"q":"壬日见甲辰时、庚戌时、癸卯时，喜忌与解法各是什么？","opts":["喜甲辰食神制杀（怕己合）；喜庚戌杀印有权；癸卯喜戊合癸","壬日见辛正印最有用，见壬子时主绝对清闲享福","壬日最喜甲辰见己土官星来合；喜庚子时主大权在握","壬日见癸卯时大吉，最怕戊土七杀来合去癸水"],"ans":0,"exp":"壬日甲辰食神制杀吉（怕己合）；喜庚戌杀星配印主有权（庚子没大用）；癸卯不喜争夺，喜戊来合癸引杀；无用辛印喜财合。","sec":"九、壬","t":"rule"},{"q":"在物象上，癸水为何代表「提纯的西药」而非中药？","opts":["癸为草木藤蔓之根茎，需经煎煮方能发挥药效","癸为清澈阴水、细小而圆、没有生机，故主提纯西药","癸为太阳烈火提炼之灰烬，专治一切热病而无副作用","癸为甲木大树之枝叶，生机勃勃且毫无任何副作用"],"ans":1,"exp":"癸是清澈之水，主细小而圆（结晶、药丸），但阴水治病没有生机，对应提纯的西药而非中药，能治病的少且副作用多。","sec":"十、癸","t":"xiang"},{"q":"癸日见甲寅时虽主攀附权贵，但为何「癸亥日配甲寅时」反易生毛病？","opts":["亥中藏甲木与寅重复，形成比劫夺财","甲木在寅为死木，遇到亥水必然漂浮无依","寅亥相合而伤阳，破坏了甲寅的阳气","亥水冲克寅木，导致伤官彻底受损"],"ans":2,"exp":"癸喜甲寅时攀附权贵，但癸亥日配甲寅时，寅亥合而伤阳，易生其他毛病；癸日甲子时则是伤官坐禄，清高自爱。","sec":"十、癸","t":"diff"},{"q":"癸日见戊（正官）、己（七杀）、辛（偏印），喜忌规律是什么？","opts":["癸日见甲乙丙丁皆不喜，唯独见己土七杀最能发贵","最怕戊甲同透成伤官见官；最喜己未时七杀护身","癸日最怕辛金偏印，金水相逢必主容貌丑陋无福","喜戊合且喜戊甲同透；最怕己杀；喜辛但印重须有功"],"ans":3,"exp":"癸日除怕己外遇什么都有用不忌：喜戊合且喜戊甲同透（伤官见官反掌权）；喜辛金水相逢女必白净（冷美人，遇丙辛合更佳），印重须有功。","sec":"十、癸","t":"rule"},{"q":"盲派认为「乙庚相合」可表示金融，其象理依据是什么？","opts":["金融须有收与放同时出现，乙食神主放、庚印主收","古人只用木棒记账、不用金属货币，故乙庚合纯指记账","乙木主克制、庚金主发散，合后形成纯阳刚之气","乙木为纸币印刷、庚金为黄金矿山，二者皆属固定资产"],"ans":0,"exp":"金融目的是资金放大，要有收与放同时出现：乙庚相合中乙木为食神（放）、庚金为印（收），且古用线串钱，故可表示金融。","sec":"七、庚","t":"xiang"},{"q":"瞳仁为肾精所化，肾虽水脏却藏龙雷之火，这对应十干中的哪一重要法则？","opts":["阳干宜占体，阴干宜占用","见阴之体，必取阳用（体阴用阳）","阴体抱阴守黑，无需追求阳用","水火不相容，见水必克火"],"ans":1,"exp":"癸至阴居末位，但至阴反可用阳（体阴用阳），癸日成贵格者多；如肾水脏却藏龙雷之火，即见阴之体必取阳用。","sec":"十、癸","t":"xiang"}]},{"n":49,"level":"中级","title":"干支关系与五行生死","qs":[{"q":"按盲派，天干与地支发生克的关系时，一般怎么论？","opts":["天干地支都不能互克，只看合冲","天干能克地支，地支不能克天干","地支力重，地支能克天干","天干地支互克，谁强谁胜"],"ans":1,"exp":"位比气重要，天干如君如夫，地支如臣如妻，只有上下相合的少数几柱才例外。","sec":"一、干支关系","t":"rule"},{"q":"盲派论五行强弱，用的是哪组概念？","opts":["日主得月令为旺、失令为衰","天干通根多为强、通根少为弱","天干得地气为实、不得为虚","地支藏干多为实、藏干少为虚"],"ans":2,"exp":"本派只讲虚实不讲衰旺：天干能得地气者为实，不得者为虚，如甲寅乙卯为实，甲申乙酉为虚。","sec":"一、干支关系","t":"diff"},{"q":"干支一体的柱子，代表人时有什么要求？","opts":["一体者必比异体好，不必顾忌","必须被冲动，才能显出灵动","可被合化，合化后更有力","不可被坏，坏则不利身体"],"ans":3,"exp":"一体如整体的人，坏了就伤身；所以一体不一定比异体好，日主天干不落地的命没有这层担忧。","sec":"一、干支关系","t":"rule"},{"q":"丙寅、壬申、甲辰、丙午四柱，哪一柱属于「地支生天干，且地支中又藏旺气天干」这类干支一体？","opts":["丙寅","甲辰","三柱皆是","丙午"],"ans":0,"exp":"丙寅（寅生丙，寅中藏丙）与壬申属此类；丙午属通禄一体，甲辰属有克而成整体。题中丙寅是唯一属此类的一柱。","sec":"一、干支关系","t":"calc"},{"q":"金的绝地和水的死地分别是哪个地支？","opts":["金绝于子，水死于申","金绝于寅，水死于卯","金绝于卯，水死于寅","金绝于申，水死于子"],"ans":1,"exp":"寅申巳亥为绝地：火生寅则寅是金绝地；子午卯酉为死地：水旺子，死于卯。","sec":"二、五行生死","t":"calc"},{"q":"「气怕死，形怕绝」中，哪两种五行是「气」、怕什么？","opts":["金木为气，怕绝","水火为气，怕绝","水火为气，怕死","金木为气，怕死"],"ans":2,"exp":"水火为气，怕死（火怕酉、水怕卯）；金木为形，怕绝（金绝寅、木绝申）。","sec":"二、五行生死","t":"rule"},{"q":"庚子、甲午两柱本是金木「死」地，按盲派怎么论？","opts":["形怕绝，死地等于绝地，主凶","金木被死地所克，主凶","金木死而无根，必须有救方吉","形化气、形归气，不主凶反主吉"],"ans":3,"exp":"形不怕死，只有气怕死；死是生气消失而形还在，所以庚子、甲午不凶反吉。","sec":"二、五行生死","t":"calc"},{"q":"水火遇绝地和金木遇绝地，按盲派区别在哪？","opts":["水火气绝有情，既济；金木形绝无情，交战","水火金木遇绝都一样，都主死亡","水火绝则亡，金木绝则可用","水火绝无情相克，金木绝有情相生"],"ans":0,"exp":"水火为气，绝而交融（水火既济），不怕绝；金木为形，绝则无情交战。","sec":"二、五行生死","t":"diff"},{"q":"辰戌与丑未，哪个说法符合盲派？","opts":["四库都必须冲开才能用","辰戌为气库不必开，丑未为形墓必须开","四库都不必开，入墓即可用","辰戌为形墓必须开，丑未为气库不必开"],"ans":1,"exp":"辰戌是水火之库，气主动如阳宅，不开也能用；丑未是金木之墓，形主静如阴宅，用必须开。","sec":"二、五行生死","t":"diff"},{"q":"盲派说地上土和天上土的墓，分别在哪？","opts":["天土墓于辰，地土墓于戌","天土墓于丑，地土墓于未","天土墓于戌，地土墓于辰","天土墓于未，地土墓于丑"],"ans":2,"exp":"天上土同火长生于寅，墓于戌；地上土同水长生于申，墓于辰。戌为天门，辰为地户。","sec":"三、土的生死","t":"rule"},{"q":"十二地支中，辰在哪个字面前最容易被制？","opts":["丑","戌","卯","子"],"ans":3,"exp":"辰是地户，几乎无所畏惧，只有戌能对抗；但子见辰能消解之，小能克大。题目问的是「最怕」，是子。","sec":"三、土的生死","t":"diff"},{"q":"四帝旺（子午卯酉）的地支性格，哪条正确？","opts":["气专，爱钻牛角、固执不通融","气散，宽容大度、交往多","气聚，沉着有谋、能聚财","气专，圆滑随和、善于变通"],"ans":0,"exp":"子午卯酉气专，贪荣忘生，专一固执不讲情面，中医主枢；寅申巳亥气散主开，辰戌丑未气聚主合。","sec":"四、地支三类性格","t":"xiang"}],"fine":[{"q":"关于地支阴阳划分与六十甲子干支相配的原则，下列哪一项正确？","opts":["子丑寅卯辰巳为阳，午未申酉戌亥为阴；阴阳交叉相配","子寅辰午申戌为阳，丑卯巳未酉亥为阴；阳配阳、阴配阴","寅申巳亥为阳，子午卯酉为阴；干支可以随意混配","甲乙丙丁戊为阳，子丑寅卯辰巳为阴；阳干必配阴支"],"ans":1,"exp":"地支以位分阴阳：子寅辰午申戌为阳，丑卯巳未酉亥为阴；天干与地支只能阳配阳、阴配阴，不能错配。","sec":"1. 地支的阴阳与六十甲子","t":"rule"},{"q":"从「位与气」对比天干和地支，两者的气有何本质不同？","opts":["天干重浊之气杂而载衰旺；地支清轻之气纯而依天干存","天干统四时八方而不依地支，地支只受天干支配","天干清轻之气纯而依地支存；地支重浊之气杂而载衰旺","天干与地支气完全相同，唯独天干强度远比地支更强"],"ans":2,"exp":"天干为清轻之气，纯而易分但强度较弱，依乎地支而存；地支为重浊之气，杂而难辨，统四时八方，载五行之衰旺生死。","sec":"2. 天干与地支：位与气","t":"diff"},{"q":"正常情况下天干克地支而地支不克天干，唯一的例外情形是什么？","opts":["四帝旺子午卯酉在日支时，可直接克制天干","天干虚透无根时，任何地支皆可直接克天干","地支临月令旺气时，所有地支皆可克天干","上下相合的少数几柱，地支可克到天干"],"ans":3,"exp":"位比气重要，天干如君如夫，地支如臣如妻；特例是上下相合的少数几柱，地支可克天干，如丈夫因爱深而承让妻子。","sec":"2. 天干与地支：位与气","t":"rule"},{"q":"为何说水火是「阴阳错配」，而金木土是「阴阳正配」？","opts":["按藏气阴阳，水火具阴阳两性（如壬子、癸亥藏气异于位）","金木土为气而水火为形，形之藏气必然与天干正配","水火在六十甲子中专门用来打破阳配阳、阴配阴规律","按地支方位，水火位居南北故必然阳干配阴支"],"ans":0,"exp":"阴阳错配指藏气的阴阳：水火具阴阳两性（火外热内源冷、水阴中藏阳），故壬子（壬阳子藏癸阴）、癸亥为阴阳错配；金木土为形，正配。","sec":"3. 阴阳错配（水火）","t":"diff"},{"q":"虚实对干支象义有何影响？「在天呈象，落地呈形」是指什么？","opts":["天干得地气为虚，天干不得地气为实","虚干体现单体象义，落地为实则干支一体呈整体象义","在天呈象只看月柱，落地呈形只看时柱而不管日柱","虚干完全没有象义，唯有落地为实才能取出单干之象"],"ans":1,"exp":"天干不得地气为虚、得地气为实；在天呈象可体现单体象义，落地呈形则干支一体，表现为整体象义。","sec":"4. 虚实：我们讲虚实，不讲衰旺","t":"diff"},{"q":"甲寅、壬子、丙午、甲辰、乙未中，哪一组虽因阴阳错配不称通禄，却仍属干支一体？","opts":["甲寅、乙未","丙午、甲辰","壬子、丙午","甲辰、乙未"],"ans":2,"exp":"天干通禄于地支为干支一体（甲寅、乙卯），而壬子、丙午因水火阴阳错配不称通禄，但也属干支一体；甲辰、乙未属有克而象义成整体。","sec":"5. 干支一体","t":"calc"},{"q":"干支一体组合如同一个整体的人，其天干与地支分别代表人体的什么？","opts":["天干代表精神，地支代表衣物","天干代表内脏，地支代表皮肤","天干代表四肢，地支代表五官","天干代表头，地支代表躯体"],"ans":3,"exp":"干支一体组合如同一个整体的人，天干代表头，地支代表躯体，代表人时不可被坏，坏则不利身体。","sec":"5. 干支一体","t":"xiang"},{"q":"盲派所说的「干支之化气」与「一柱独立成象」，分别说明了什么规律？","opts":["干支相生为化气表灵动性；干支相克之柱也能独立呈象","凡能化气的柱子必主死板无变；相生之柱反不可分析行业","化气只指天干五合化局，与单柱干支相生相克毫无关系","干支相克才称化气表灵动；干支相克之柱绝不能独立呈象"],"ans":0,"exp":"干支相生的柱子称干支之化气，表示灵动性与转身变化；如丙申虽干支相克，仍可独立呈象，单柱即可分析行业兴衰。","sec":"6. 化气","t":"rule"},{"q":"盲派不采用传统十二长生全套，而只用哪六种状态？","opts":["生、浴、带、官、旺、衰","生、旺、墓、绝、死、退","生、旺、病、死、胎、养","长、冠、旺、墓、胎、退"],"ans":1,"exp":"传统有十二宫，盲派只用六种状态：生、旺、墓、绝、死、退。","sec":"1. 十二长生与本派六态","t":"rule"},{"q":"从地支藏气阴阳看，「生」「旺」「墓」三种状态的藏气各有何特征？","opts":["生、旺、墓三者藏气皆全阳，唯独绝与死才转阴","生藏气全阴；旺藏气全阳；墓位阴而藏气全阳","生藏气全阳；旺位阳而藏气已转阴；墓藏气全阴","生位阴而藏气转阳；旺藏气半阴半阳；墓藏气全阳"],"ans":2,"exp":"生之地支藏气全阳（唯阳气可长生）；旺地支位虽在阳，藏气已转阴（盛极必衰）；墓中藏气全阴（须露头或冲墓才好）。","sec":"1. 十二长生与本派六态","t":"diff"},{"q":"在五行六态中，「墓绝同现」与「退气」在断命取象上各有何含义？","opts":["墓绝同现主大发横财；退气（四旺）表事业蒸蒸日上","绝地只主搬家远行不涉生死；退气专指寅申巳亥四长生","退气之人必主头婚恩爱白头；墓绝同现反主长寿健康","墓绝同现主死亡（绝可决生死）；退气（四土）表退下或难长久"],"ans":3,"exp":"墓绝同现主死亡，绝地可决生死；退气指五行临本季旺而到季月土月退气（辰戌丑未），如找退气老公表示离过婚或难长久。","sec":"1. 十二长生与本派六态","t":"rule"},{"q":"按本派五行六态落点，木、火、金、水四行的「墓」地依次落在哪四个地支？","opts":["木墓未、火墓戌、金墓丑、水墓辰","木墓戌、火墓丑、金墓辰、水墓未","木墓丑、火墓辰、金墓未、水墓戌","木墓辰、火墓未、金墓戌、水墓丑"],"ans":0,"exp":"木生亥旺卯墓未，火生寅旺午墓戌，金生巳旺酉墓丑，水生申旺子墓辰。","sec":"2. 五行的六态落点（按原稿文字还原）","t":"calc"},{"q":"按本派五行六态落点，木的「死」地与火的「绝」地分别是哪两个地支？","opts":["木死于申，火绝于酉","木死于午，火绝于亥","木死于子，火绝于巳","木死于卯，火绝于寅"],"ans":1,"exp":"子午卯酉为四大死地，木旺卯而死于午；寅申巳亥为四大绝地，水生申旺子绝巳，火生寅旺午墓戌绝亥。","sec":"2. 五行的六态落点（按原稿文字还原）","t":"calc"},{"q":"按本派五行六态落点，金的「退」气与水的「退」气分别落在哪两个地支？","opts":["金退于辰，水退于未","金退于未，水退于戌","金退于戌，水退于丑","金退于丑，水退于辰"],"ans":2,"exp":"退气为季月土神（余气）：木春旺退于辰，火夏旺退于未，金秋旺退于戌，水冬旺退于丑。","sec":"2. 五行的六态落点（按原稿文字还原）","t":"calc"},{"q":"形气与长生、三合局的搭配规律中，为何水火长生配阳干，金木长生只配阴干？","opts":["金木为动属阳故配阴干，水火为静属阴故配阳干","丙寅、壬申是阴干配长生，乙亥、辛巳是阳干配长生","阳干皆可配长生，阴干在任何五行中都绝不能配长生","阳化气而阴成形：水火为气需有源，金木为形初生是幼芽或须炼"],"ans":3,"exp":"「阳化气而阴成形」：水火之气阳干配长生与生旺墓（壬申、丙寅，申子辰、寅午戌为阳）；金木之形阳干不可配，只配阴干（乙亥、辛巳，亥卯未、巳酉丑为阴）。","sec":"3. 形气与生旺墓的搭配规律","t":"rule"},{"q":"按照「阳配气、阴配形」的生旺墓搭配规律，下列哪一组干支搭配完全合规？","opts":["丙配寅午戌，乙配亥卯未，辛配巳酉丑","丁配寅午戌，甲配亥卯未，庚配巳酉丑","丙配巳酉丑，壬配亥卯未，乙配申子辰","癸配申子辰，甲配寅午戌，辛配亥卯未"],"ans":0,"exp":"水火之气阳干可配生旺墓、阴干不可配（寅午戌配丙，申子辰配壬）；金木之形阳干不可配、只有阴干可配（亥卯未配乙，巳酉丑配辛）。","sec":"3. 形气与生旺墓的搭配规律","t":"calc"},{"q":"口诀「气怕死，形怕绝」中，为何「火怕酉、水怕卯」？","opts":["火在酉为长生之源，水在卯为墓库之地，故不敢相见","气死就是消亡，丙火见酉如日落无阳，水见卯则生气尽散","酉与卯属于阴支，天干阳气遇到阴支必然立即被克死","火遇酉必成水火既济，水遇卯必成金木交战"],"ans":1,"exp":"气怕死，气死就是消亡：火死于酉（太阳丙见酉日落无阳），水死于卯，故有「火怕酉方酉，水怕卯中伤」之说。","sec":"4. 气怕死，形怕绝","t":"rule"},{"q":"盲派认为土的长生有两个，天上土与地上土长生于何支？其依据是什么？","opts":["天上土生于辰，地上土生于戌，因辰为地户戌为天门","天上土同木生亥（甲为雷），地上土同金生巳（庚为降）","天上土同火生寅（戊为丙化），地上土同水生申（申加土为坤）","天上土与地上土皆只长生于午，因火土同旺于正夏"],"ans":2,"exp":"天上土同火长生于寅（戊为丙所化）；地上土同水长生于申（十干管天气，八卦管地气，水生于申，申加土为坤，土寄生于坤方）。","sec":"1. 天上土与地上土","t":"rule"},{"q":"关于地支「辰」的特殊地位，下列哪一项表述准确？","opts":["辰见子会变得无比强大，唯独见戌会被彻底消解","辰在十二地支中最弱小，几乎害怕所有其他地支","辰为天门，只能墓水而绝对不能墓土，丑未绝不入辰","辰为地户，既能墓水也能墓土（丑未可入辰），取象为龙"],"ans":3,"exp":"辰是地户，不仅能墓水还能墓土（丑未入墓于辰），故取龙象；辰是地支老大，仅戌能对抗，但怕子消解（小能克大）。","sec":"2. 辰","t":"rule"},{"q":"在十二地支三类性格中，四长生（寅申巳亥）的气性与性格特点是什么？","opts":["气散，宽容大度、发散思维、乐分享，中医主开","气专，爱钻牛角、固执不通融、不讲情面，中医主枢","气弱，胆小退缩、保守依赖、不喜交往，中医主闭","气聚，有谋而动、沉着深刻、有时较闷，中医主合"],"ans":0,"exp":"寅申巳亥藏气多、有生有旺，故气散，性格宽容大度、发散型思维、交往多愿分享，中医主开。","sec":"四、地支三类性格","t":"xiang"},{"q":"在十二地支三类性格中，四墓库（辰戌丑未）的气性与中医对应是什么？","opts":["气散，包容大度、不保守、喜欢开放交流，中医主开","气聚，有谋而动、沉着深刻、能聚人聚财，中医主合","气散，浮躁急切、缺乏耐心、不聚财，中医主泄","气专，贪荣忘生、骄傲特立独行、钻研巧劲，中医主枢"],"ans":1,"exp":"辰戌丑未因是墓所以气聚，性格有谋而动、沉着深刻，能聚人聚财，有时较闷不爱表现，中医主合（闭藏沉淀）。","sec":"四、地支三类性格","t":"xiang"},{"q":"按中医「开、枢、合」对应地支三类性格，下列匹配完全准确的是哪一项？","opts":["四长生主合，四帝旺主开，四墓库主枢","四长生主枢，四帝旺主合，四墓库主开","四长生主开，四帝旺主枢，四墓库主合","四长生主开，四帝旺主合，四墓库主枢"],"ans":2,"exp":"寅申巳亥四长生（气散）主开；子午卯酉四帝旺（气专）主枢；辰戌丑未四墓库（气聚）主合。","sec":"四、地支三类性格","t":"diff"},{"q":"十二地支中，为什么「辰」见「子」会被消解，体现了什么道理？","opts":["子与辰相刑相害，在三合局中必然互相毁坏","子为阳水、辰为阴土，阳克阴属于天地正配规律","子水比辰土更重浊，以强凌弱故能冲散辰库","小能克大，如大象怕老鼠、千里之堤溃于蚁穴"],"ans":3,"exp":"辰最怕子，子见辰能消解之（如坚冰消融），体现「小能克大」：再大到不能被更大者制约时，破坏它的往往是最小的东西。","sec":"2. 辰","t":"diff"}]},{"n":50,"level":"中级","title":"地支作用","qs":[{"q":"子午卯酉四帝旺支，藏干情况是怎样的？","opts":["只有子藏两气，其余各藏一气","子午卯酉各藏两气","只有午藏两气，其余各藏一气","四支各只藏一气，没有例外"],"ans":2,"exp":"帝旺支藏气俱阴、只藏本气旺气；因火土同生同旺，午也是土的旺气点，所以只有午藏丁己两气。","sec":"一、地支遁藏与刃","t":"rule"},{"q":"下列四个日柱，哪一个是「自坐刃」？","opts":["乙卯","辛酉","甲寅","壬子"],"ans":3,"exp":"只有阳日干有刃，水火错配所以壬子、丙午自坐刃；甲寅是坐禄不是刃，乙卯、辛酉是阴干，无刃。","sec":"一、地支遁藏与刃","t":"calc"},{"q":"天干没有别的辛，只有一个辛丑日柱，辛按盲派怎么论？","opts":["本坐库不为入墓，不论入墓","辛入丑墓，凶大","辛入丑墓，凶小","辛入丑墓，须看大运"],"ans":0,"exp":"辛丑、壬辰是坐墓，不为入墓；天干多辛相连通于辛丑，才是多而墓之。","sec":"二、墓库的入与出","t":"calc"},{"q":"下列六合组合中，哪一组属于克合？","opts":["午未","卯戌","寅亥","辰酉"],"ans":1,"exp":"寅亥、辰酉、午未是生合；克合是卯戌、巳申、子丑，其中卯戌合卯控制戌，可做功。","sec":"三、地支之合","t":"diff"},{"q":"盲派所讲的三个暗合是哪三个？","opts":["午未、卯申、寅亥","子亥、卯申、寅丑","午亥、卯申、寅丑","午亥、卯戌、寅丑"],"ans":2,"exp":"暗合是午亥、卯申、寅丑：午中丁己合亥中壬甲，寅中甲丙合丑中己辛，卯中乙合申中庚（合绝）。","sec":"三、地支之合","t":"rule"},{"q":"寅申相冲与子午相冲，结果的性质有何不同？","opts":["两者都是强者胜，没有区别","寅申木必胜金；子午水火强者胜","寅申强者胜；子午水必胜火","寅申金必胜木；子午水火强者胜"],"ans":3,"exp":"金木相冲是形争，一旦相冲一定金胜木；水火相冲是气的相冲、水火既济，一方强另一方败。","sec":"四、地支六冲","t":"diff"},{"q":"冲会让字动起来，动对体和用分别如何？","opts":["体不喜多动，用喜动","体喜动，用不喜动","体用都不喜动","体用都喜动"],"ans":0,"exp":"体不喜多动，动则劳碌辛苦；用喜动，动则功成名就。所以体不可克，用冲克无妨。","sec":"四、地支六冲","t":"rule"},{"q":"六穿里哪一个力量最大、哪一个力量最小？","opts":["申亥最大，寅巳最小","寅巳最大，申亥最小","子未最大，丑午最小","卯辰最大，酉戌最小"],"ans":1,"exp":"阳穿阳力大、阴穿阴力小：寅巳两阳相穿拼出你死我活，申亥是冷暴力、最弱。","sec":"五、地支六穿","t":"diff"},{"q":"原局已有寅、巳两字，第三个字申分别由大运和流年带来，怎么论三刑？","opts":["大运、流年来申都不成三刑","大运来申只是引动，流年来申构成三刑","大运来申构成三刑，流年来申只是引动","大运、流年来申都构成三刑"],"ans":2,"exp":"寅巳申三者须同时出现才构成刑；原局两个，大运来第三个也构成三刑，流年来第三个只是引动。","sec":"七、地支刑与破","t":"calc"},{"q":"丑戌刑与未戌刑，能否做功？","opts":["未戌刑能做功，丑戌刑只开库","两者都能做功","两者都不能做功，只开库","丑戌刑能做功，未戌刑只开库"],"ans":3,"exp":"丑戌刑一阴一阳，力大者能坏另一方，可做功；未戌刑不以做功论，只是开库。","sec":"七、地支刑与破","t":"diff"},{"q":"三种破的力量大小，从大到小依次是？","opts":["卯午破、子卯破、子酉破","子酉破、子卯破、卯午破","子卯破、卯午破、子酉破","卯午破、子酉破、子卯破"],"ans":0,"exp":"卯午俱阳，阳见阳破得最凶；子卯其次；子酉阴见阴称相隔，几乎不破，意同申亥穿。","sec":"七、地支刑与破","t":"step"},{"q":"入阳墓与入阴墓，以及阳墓阴墓开不开，怎么区别？","opts":["入阳墓凶大；阳墓阴墓都不开也可用","入阴墓凶大；阳墓不开也可用，阴墓必须开","入阳墓凶大；阴墓不开也可用，阳墓必须开","入阴墓凶大；阳墓阴墓都必须开"],"ans":1,"exp":"辰戌阳墓为气墓、丑未阴墓为形墓；入阳墓如住院，入阴墓可能人就没了，阴墓一定要开。","sec":"八、地支之墓：入、出与开库","t":"diff"}],"fine":[{"q":"四长生寅申巳亥的藏干规律中，下列哪项说法最准确？","opts":["所藏天干俱阴，只藏本气与余气","四支均严格藏三气，且土气最旺","所藏天干俱阳，基本藏本气与长生之气","亥藏壬甲戊三气，土气不可忽略"],"ans":2,"exp":"长生是生生之气，只有阳气能推动生长，故寅申巳亥所藏俱阳；基本藏本气与长生之气，亥只藏两气无土。","sec":"1. 藏干的规律（不必死记）","t":"rule"},{"q":"关于辰戌丑未四墓库的阴阳属性与藏干规律，说法正确的是？","opts":["墓库本身与所藏之气俱为阳","四墓库只藏本气与墓气，无余气","墓库本身俱阴，所藏之气分阴阳","墓库本身分阴阳，所藏之气俱阴"],"ans":3,"exp":"丑未阴土、辰戌阳土，墓库本身分阴阳；但死而归墓无生机，故所藏本气、墓气、余气俱阴，且墓气远足于余气。","sec":"1. 藏干的规律（不必死记）","t":"diff"},{"q":"关于阳日干之「刃」的判定，下列哪项符合盲派规则？","opts":["戊刃在未，且阳干见天干比劫也称刃","阴日干见帝旺同样论刃，如乙见卯","戊刃在午，与丙火共用同一个刃","戊刃在辰，且天干不以刃论"],"ans":0,"exp":"只有阳日干有刃，阴日干无刃；戊土之刃特别，戊刃在未；除地支刃外，阳干见天干如甲见乙、戊见己也称刃。","sec":"2. 旺气与刃","t":"rule"},{"q":"月柱有墓库，日柱见该墓所墓之神，在位置论法上应断为？","opts":["须等流年再来冲动，方能论其入墓","因距离太近，也论入墓而不称出墓","墓在月柱、神在日柱，直接论出墓","月日相邻互相抵消，既不出也不入"],"ans":1,"exp":"一般年月有墓、日时见所墓之支论出墓（引出），但若月上有墓而日上见所墓之神，因距离太近也论入墓，不称出墓。","sec":"1. 入墓与出墓","t":"calc"},{"q":"地支辰见一个子水与见双子水，在墓库作用上有何不同？","opts":["见一子论半合，见双子则冲开辰中水库","见一子或双子皆以子入辰墓论，没有区别","见一子则辰被消解相合，见双子才入辰墓","见一子即入辰墓，见双子反成子辰拱局"],"ans":2,"exp":"墓库讲「多而墓之」：辰见一子时辰被消解、子辰拱合；见双子才构成多而墓之，双子俱入辰墓。","sec":"1. 入墓与出墓","t":"diff"},{"q":"阴天干不通地（未得地支）时，其入墓规律是？","opts":["不通地则入阳干之墓，丁墓辰、癸墓戌","依然入本墓，癸墓辰、丁墓戌、辛墓丑、乙墓未","阴干永远不入墓，只有阳干才论入墓","入墓不在本墓，癸墓未、丁墓丑、辛墓辰、乙墓戌"],"ans":3,"exp":"阴干通地入本墓（如辛酉墓丑）；不通地则按阴长生逆行之墓，即癸墓未、丁墓丑、辛墓辰、乙墓戌，且阴干逆长生只用墓。","sec":"2. 阴干的墓","t":"rule"},{"q":"关于地支六合「五层含义」中的控制支配与远近影响，正确的是？","opts":["控制支配限于克合，贴近之合失自主尤甚","只有生合能做功，克合主缠绊不能做功","生合与克合皆能控制，远合贴合力度相同","远合比贴近之合粘接更强，更易合坏"],"ans":0,"exp":"六合的控制与支配只限于克合（可做功）；贴近之合失去自主性尤甚，远合影响不大，多数合是合坏。","sec":"2. 六合的五层含义","t":"rule"},{"q":"子丑合与辰酉合在「闭库」与吉凶取象上，下列哪项正确？","opts":["子丑合与辰酉合皆使墓库封闭，水不入墓","子丑合使丑金库得闭，辰酉合并不闭辰库","子丑合不闭丑库，辰酉合使辰水库封闭","子丑合主阳气充足，辰酉合主金属不生锈"],"ans":1,"exp":"子丑两阴相合使丑金库得闭、阴结易生病；辰酉相生之合强固水库而不闭库，水照样进辰，可取象钢筋水泥建筑。","sec":"3. 六合逐个讲","t":"diff"},{"q":"六合中「午未合」常被称作最无聊的合，除非满足什么条件才有意义？","opts":["午未贴近死合且不见任何刑冲才有意义","原局天干透出辛金泄未土才有意义","一起完成冲丑或坏子的工作才有意义","大运再来寅木生助午火才有意义"],"ans":2,"exp":"午未阳性都足、无互补性，反而牵绊且关闭未库；除非一起完成冲丑或坏子的工作，午未合才有实际意义。","sec":"3. 六合逐个讲","t":"rule"},{"q":"同属地支暗合，「卯申合」与「寅丑合」在象义上的主要区别是？","opts":["卯申只能做功不能论婚姻，寅丑主车祸伤灾","卯申是阴阳互补之合，寅丑为合绝易伤配偶","卯申粘接比六合更紧，寅丑则完全没有粘接","卯申是合绝易克婚姻，寅丑为阴阳平衡之合"],"ans":3,"exp":"卯中乙合申中庚称合绝（卯绝于申），做功可但婚姻易克；寅丑为极阳与极阴之合，阴阳平衡互通，利学阴阳之学。","sec":"4. 暗合","t":"diff"},{"q":"若从「交易」角度区分地支六冲与六合，下列哪项描述准确？","opts":["冲是不失独立性的简单交易，合是复杂交易","冲与合都会使双方完全丧失自主性与独立性","合代表往来互换与远行，冲代表贪恋与封闭","冲是入股分红的复杂交易，合是简单交易"],"ans":0,"exp":"冲的本意是往来互换，属一供一需的简单交易，不散失独立性；合则似入股分红的复杂交易，结成共同体而丧失部分独立性。","sec":"1. 冲的本意","t":"diff"},{"q":"同样是土墓相冲开库，辰戌冲与丑未冲相比有何不同？","opts":["丑未冲只开未库不开丑库，辰戌只开辰库","辰戌为阳库天门地户，级别比丑未阴库更高","丑未为阳库，互开其库后级别比辰戌更高","辰戌相冲不能开库，只有丑未相冲才能开库"],"ans":1,"exp":"丑未为阴库、冲而互开；辰戌为阳库，称天门地户，级别比丑未更高，如马云、马化腾命局皆有辰戌冲为用。","sec":"2. 三组冲","t":"diff"},{"q":"六穿「穿倒」的含义中，正星逢穿与偏星逢穿的结果分别是？","opts":["正星偏星逢穿皆只主变动，不改变十神性质","正星与偏星逢穿均变为凶神，没有例外","正星不喜穿倒，偏星穿倒反为正","正星穿倒转吉，偏星穿倒更凶"],"ans":2,"exp":"穿倒即穿反，会出现与十神本意相反之象（如食神逢穿反生男儿）；正星不喜穿倒，偏星穿倒反而为正。","sec":"2. 穿的五层含义","t":"rule"},{"q":"下列哪组地支六穿组合，属于「相生之穿」因而原则上不做功？","opts":["子未穿与酉戌穿","子未穿与卯辰穿","酉戌穿与卯辰穿","寅巳穿与申亥穿"],"ans":3,"exp":"带相克之意的穿才能做功，如子未（未克子）、卯辰（卯克辰）、酉戌（戌克酉）；寅巳、申亥为相生之穿，不做功。","sec":"2. 穿的五层含义","t":"calc"},{"q":"六穿通常主伤灾排斥，但唯一「喜欢被穿」的地支组合及取象是？","opts":["辰喜卯穿，如水坝打入木桩更坚固","午喜丑穿，如湿土护火使心脏强健","酉喜戌穿，如烈火锻金使金属更锋利","亥喜申穿，如金生丽水使财运更顺畅"],"ans":0,"exp":"辰为水坝，建坝需将木桩一根根穿入方才坚不可坏，故辰喜卯穿而不喜戌冲；且穿后是辰好了，卯被穿坏。","sec":"4. 六穿逐个讲","t":"xiang"},{"q":"关于墓库与身体逢穿的原则，下列哪项判断正确？","opts":["墓库逢穿易被穿坏；体穿只主升职不主伤灾","墓库逢穿不能开墓；墓当体时可体穿","六亲宫位见穿反主六亲缘深、互助紧密","墓库逢穿即能开墓；任何体都绝不可穿"],"ans":1,"exp":"墓坚固不坏，逢穿不开反能穿坏他支；体不可穿（主手术伤灾），唯一可体穿的是墓当体；六亲见穿则无缘。","sec":"5. 穿的原则","t":"rule"},{"q":"四大三合局中，唯一不以中神为核心、反以墓库为中心的是哪一局？","opts":["巳酉丑金局，金入于丑反以丑为中心","亥卯未木局，木克未土反以未为中心","寅午戌火局，火生助戌反以戌为中心","申子辰水局，水归于辰反以辰为中心"],"ans":2,"exp":"三合局通常以中神（帝旺）为核心，唯独寅午戌火局生助了戌，戌反成中心（如老人干政），午火之性从于戌。","sec":"2. 四局逐个","t":"diff"},{"q":"十二地支中，唯一能够「沟通阴阳」并改变自身五行属性的是？","opts":["申金，遇酉丑为金而遇子辰化水变阳","午火，遇寅戌为火而遇子辰化水变阴","未土，遇午戌为火而遇亥卯化木变阴","巳火，遇木火为火而遇酉丑化金变阴"],"ans":3,"exp":"十二支唯巳可沟通阴阳：本性火属阳，遇木火为火，遇酉丑则合成金局而变阴，变化似人思维，利学易医。","sec":"3. 巳：沟通阴阳","t":"rule"},{"q":"盲派将十二地支分为阳党与阴党，下列关于「党」的论法正确的是？","opts":["木火阳党、金水阴党，有党须有功才贵","木水阳党、火金阴党，有党即大富贵","四土全部归入阳党，不参与阴党结势","只讲三合局结党，不讲阴阳两党之势"],"ans":0,"exp":"本派分木火为阳党、金水为阴党、土分阴阳；有党成势再有功则命佳，若只有党而无功，如养一群闲人，八字反废。","sec":"4. 党的更一般划分","t":"rule"},{"q":"关于盲派对「三刑」的论述，下列哪项符合规则？","opts":["三刑专主刑事刑罚，不伤六亲也不伤身体","不讲辰午酉亥自刑，三刑中间被刑字易出事","辰午酉亥见同字必自刑，且主要代表官司牢狱","体与六亲逢三刑反主能量聚集、大富大贵"],"ans":1,"exp":"本派不讲辰午酉亥自刑；三刑不代表刑罚，会伤及六亲与体，中间被两头刑的字会出问题，婚姻宫成三刑婚姻多出事。","sec":"1. 三刑","t":"rule"},{"q":"地支之破在身体取象上，卯午破与子卯破分别容易对应什么病症？","opts":["卯午破主脾胃消化病，子卯破主心脏猝死症","卯午破主肝胆结石病，子卯破主肺部哮喘病","卯午破主心脑血管突发病，子卯破主肾与泌尿病","卯午破只主读书考试，不对应任何身体疾病"],"ans":2,"exp":"卯午破：午为心、卯为血管，主血管破裂或心脑血管突发病；子卯破：子水怕死于卯，主肾病、尿频或前列腺疾病。","sec":"2. 地支之破","t":"xiang"},{"q":"子午卯酉四帝旺点在原局遇到各自对应的墓神时，如何区分拱局与入墓？","opts":["单现论入墓，双现反而冲破墓库论拱局","无论单现还是双现，永远只论拱局不入墓","无论单现还是双现，见对应墓神一律论入墓","单现见墓论拱局，双现或多现才论入墓"],"ans":3,"exp":"长生点见对应墓神直接入墓；子午卯酉四帝旺点见对应墓神本为拱局不入墓，只有中神双现或多现，多而墓之才入墓。","sec":"2. 入墓出墓","t":"calc"},{"q":"开库的「天引法」有何条件，且各种开库引出方法的效率如何排序？","opts":["天引须天干虚透；效率冲大于引、直开大于旁开","天引与开天库完全相同，均不要求干支虚实","天引须天干坐实根；效率引出大于冲、旁开大于直开","天引只需地支半合；效率天引最全、地支其次"],"ans":0,"exp":"天引是通过天干虚透引出墓中之神（多主卖东西）；效率上：冲者最全、引出其次，直开最全、旁开其次，地支较全、天引其次。","sec":"4. 开库的三种方法","t":"step"},{"q":"原局地支若同时见到「丑、未、辰」或「未、子、辰」，应如何论作用？","opts":["丑未见辰三者合水局，未子见辰三者互刑开库","丑未见辰只收丑而冲不成立；未子见辰则拱子穿未","丑未见辰只收未不收丑，未子见辰只收子不拱","丑未见辰丑未照常冲，未子见辰则未子一起入辰墓"],"ans":1,"exp":"辰丑一党，丑未同见辰时辰只收丑不收未，丑未冲不成立；未子同见辰时辰不收未却能拱子，使子未相穿更加激烈。","sec":"5. 丑未亥子入辰墓的分辨","t":"calc"},{"q":"关于墓库与做功的关系，下列哪项说法符合盲派观点？","opts":["得到全墓者极多，只要见墓就一定能得全部能量","墓库必须被冲破才算有功，收入墓中不算功","被墓之神收入墓库本身就是功，如丑未入辰墓","丑入辰墓只是积蓄能量，只有辰戌冲才算做功"],"ans":2,"exp":"被墓之神收入墓库本身就是功、是能量聚集与放大（丑入辰墓、未入辰墓皆是功）；墓冲开就有用，能做功者更强。","sec":"6. 墓库与做功","t":"rule"}]},{"n":51,"level":"中级","title":"十二地支象义","qs":[{"q":"下列哪一组象属于丑？","opts":["高堂、门楼、舞台","镜子、珠宝、寺院","堤坝、港口、化工","牢狱、下水道、坟墓"],"ans":3,"exp":"丑是阴中之至阴，主黑暗隐蔽：牢狱、地下室、下水道、坟墓；镜子珠宝寺院是酉，堤坝港口化工是辰，高堂门楼是寅。","sec":"二、丑","t":"xiang"},{"q":"寅亥相合，身上易出现什么毛病？","opts":["风湿痰气类的病","心脏类的病","肺咳喘类的病","肾结石类的病"],"ans":0,"exp":"寅主风、亥主湿，亥水灭寅中之阳，湿性粘腻侵入人体要害，风湿病就是这么得的。","sec":"三、寅","t":"diff"},{"q":"卯辰相穿，对两字各是什么结果？","opts":["利卯不利辰，损辰而成就卯","利辰不利卯，损卯而成就辰","两字都受损，穿则双坏","两字都得利，穿则双成"],"ans":1,"exp":"辰是堤坝，卯是加固坝基的木桩，一根根穿进去坝才坚固：是辰好了，卯是被穿坏的。","sec":"四、卯","t":"rule"},{"q":"卯酉相冲，谁受伤？","opts":["强者胜，要看哪边有党","双方同伤，体用都无碍","酉胜卯，卯受伤，卯不能为体","卯胜酉，酉受伤，酉不能为体"],"ans":2,"exp":"金木交战必定酉胜卯，卯受伤；体被酉冲肢体必受伤，所以卯不能为体。","sec":"四、卯","t":"diff"},{"q":"十二支中，辰最怕哪两个字？","opts":["戌和卯","丑和未","酉和子","戌和子"],"ans":3,"exp":"辰怕戌冲（堤坝崩塌）、怕子（化掉消解如坚冰融化）；卯穿辰反使辰更坚，辰喜卯穿。","sec":"五、辰","t":"rule"},{"q":"巳与酉半合、巳与申相合，巳的火性各怎样？","opts":["巳酉合从金而化，巳申合火性不变","巳酉合、巳申合都从金而化","巳酉合火性不变，巳申合从金而化","巳酉合、巳申合火性都不变"],"ans":0,"exp":"巳善变，见酉丑从金而化、不再显火性；巳申相合时巳火不会变其火性。","sec":"六、巳","t":"diff"},{"q":"午亥暗合，多数表现为哪种特点？","opts":["文笔好，善写文章","智商高，数理能力强","心脏有疾，身体易伤","喜热闹，爱出入夜场"],"ans":1,"exp":"午亥是水火之合，火喜得水而既济，多数合而吉且见功，午亥之合多数智商奇高、数理能力强。","sec":"七、午","t":"xiang"},{"q":"未与辰相见，同时再见哪个字，未就不入辰墓？","opts":["午或戌","酉或亥","子或丑","卯或寅"],"ans":2,"exp":"单见未入辰墓；一见子或丑，未就不可入辰墓，辰只收丑或拱子。","sec":"八、未","t":"calc"},{"q":"申的类象中，哪类机构是只收不放？","opts":["酒店、饮食业","银行、典当行","钟鼓楼、音乐厅","税务、公安等执法处罚机关"],"ans":3,"exp":"银行是收了再放，取象寅申冲、卯申合；只收不放的是税务、公安一切执法处罚机关。","sec":"九、申","t":"diff"},{"q":"酉被戌穿，酉当用神时，常见哪两种可能？","opts":["动枪弹的职业，或运动员","教师，或律师","医生，或会计","艺人，或美容师"],"ans":0,"exp":"酉被戌穿时酉不可为体；酉当用被穿，可能是动枪弹的职业，或是运动员（速度与激情）。","sec":"十、酉","t":"rule"},{"q":"申酉戌与诉讼，哪个字最像讲道理争讼的地方？","opts":["申，执法先收押","戌，唯一可吵架争讼","酉，律师讲条文","三者都不讲道理"],"ans":1,"exp":"申酉管法律之收，先关起来不讲道理；戌是唯一可以讲道理、吵架、争讼的地方，公检法中唯戌是阳性。","sec":"十一、戌","t":"diff"},{"q":"亥与子同是水，哪个更能灌溉生木？","opts":["两者生木力量相同","两者都不生木，只能生金","亥是湖泉静水，能生木；子流动，生木差","子是流动活水，能生木；亥静而不生木"],"ans":2,"exp":"亥为湖水泉水，安静，能灌溉庄稼而生木；子是流动之水，静不下来，不能生禾木。","sec":"十二、亥","t":"diff"}],"fine":[{"q":"十二地支按「位」分阴阳，下列哪组地支全部属于阳位？","opts":["丑、卯、巳、未、酉、亥","寅、卯、巳、午、未、戌","子、丑、寅、卯、辰、巳","子、寅、辰、午、申、戌"],"ans":3,"exp":"十二支中子寅辰午申戌为阳位，丑卯巳未酉亥为阴位；判断地支阴阳需将五行属性、位与藏干三层合看。","sec":"通用","t":"rule"},{"q":"子水见辰拱合与见丑相合，在物象上的区别是？","opts":["子辰拱合为提纯制药，子丑合水入下水道变脏","子辰拱合水被淤泥堵死，子丑合为水库提纯","子辰拱合主水脏固化，子丑合主泉水涌流","子辰拱合与子丑合均主水性化工提纯"],"ans":0,"exp":"辰为泥巴而子清澈，子辰拱合是提纯、水性化工制药；丑为下水道，子丑合是水流入下水道变脏且被固化。","sec":"一、子","t":"xiang"},{"q":"子水见午冲与见卯破，各取什么典型象义？","opts":["子午冲主水入下水道，子卯破主江河冲奔","子午冲为皇门两极气化，子卯破为爆胎断流","子午冲主翻车算盘，子卯破主制药化工提纯","子午冲为轮胎爆气，子卯破为水火既济皇门"],"ans":1,"exp":"皇宫坐正子午线，子午冲称皇门、占两极阴阳气化；子为轮胎，卯破子主胎走气爆胎、水不流畅或断流。","sec":"一、子","t":"xiang"},{"q":"在十二地支阴阳程度比较中，「阴中之至阴」与「阴中之阴」分别指？","opts":["亥是阴中之至阴，子是阴中之阴","酉是阴中之至阴，丑是阴中之阴","丑是阴中之至阴，酉是阴中之阴","子是阴中之至阴，辰是阴中之阴"],"ans":2,"exp":"酉占金水、阴位、藏阴干，为阴中之阴；丑占一年最冷腊月之末位，比酉更寒，是阴中之至阴。","sec":"二、丑","t":"rule"},{"q":"丑见巳拱合与丑见辰入墓，两者的作用结果有何不同？","opts":["丑见巳主得龙而化，丑入辰墓主消尽火气","丑见巳与丑入辰墓均为无用功，阴寒加重","丑见巳火融坚冰成大功，丑入辰墓被埋没无光","丑见巳消尽巳火做无用功，丑入辰墓为放大重生"],"ans":3,"exp":"丑之坚冰不能消溶，见巳拱合反消尽巳火做了无用功；丑入辰墓是放大、废物再利用，得龙而化、脱变重生。","sec":"二、丑","t":"diff"},{"q":"寅为阳中之阳，在五邪与家居环境上各对应什么象？","opts":["五邪中风邪为寅，坐下有寅家里装修考究","五邪中湿邪为寅，坐下有寅家里阴暗潮湿","五邪中寒邪为寅，坐下有寅家里冷清寂静","五邪中燥邪为寅，坐下有寅家里简陋朴素"],"ans":0,"exp":"寅在天为风，肝主风气，故五邪中风邪为寅；寅藏火主漂亮且为高堂，坐下有寅家里装修必定考究。","sec":"三、寅","t":"xiang"},{"q":"寅见午拱火局与寅见申相冲，在性质与体用上各有何特点？","opts":["寅午拱局为气化形，寅申冲主寅胜申且寅喜为体","寅午拱局为形化气脱气，寅申冲主收放且寅忌为体","寅午拱局与寅申冲均主风湿痰气之病","寅午拱局使寅木更坚固，寅申冲不伤寅木本身"],"ans":1,"exp":"寅见午火燃尽成灰，属形化气、脱气转化；寅申冲是寅放申收的收放之冲（银行、大贸），寅被冲伤故不可为体。","sec":"三、寅","t":"diff"},{"q":"四帝旺（子午卯酉）中，为何说「卯」之气专尤甚于其他三支？","opts":["卯藏干最多，三气聚于一身故最专","卯占长生之气，所以兼有散与专的双重特性","卯既占形比子午气专，又占阳比酉更专","卯属阴中之至阴，凝聚力比子午酉更强"],"ans":2,"exp":"寅申巳亥主散，子午卯酉主专；卯占木之形，比子午之气更专；在形中又占阳，比酉金更专，且具柳柔与铆专两面。","sec":"四、卯","t":"rule"},{"q":"卯见巳、卯见午破、卯见酉冲，三者在职业与物象上如何区分？","opts":["卯巳主钢筋水泥，卯午破主抗体，卯酉冲主牢狱","卯巳主银行收放，卯午破主互联网，卯酉冲主制药","卯巳主心脑血管，卯午破主文章，卯酉冲主建筑","卯巳主文章美饰，卯午破主裁剪，卯酉冲可取银行"],"ans":3,"exp":"卯为笔、巳为文章，卯巳主书本文章美饰；卯午破取卯为布破之剪之（裁缝）或心脑血管；卯酉冲卯放酉收可取银行。","sec":"四、卯","t":"xiang"},{"q":"辰可引申为「辰车」，通常哪两个干支组合最能取车象？","opts":["甲辰与庚辰，取印与承载之意","戊辰与己辰，取厚土堤坝之意","丙辰与壬辰，取水火既济之意","乙辰与辛辰，取阴柔转动之意"],"ans":0,"exp":"辰中有子水转动，许多转动之物组合即机器，引申为辰车；甲辰与庚辰可取车象，取印与承载之意。","sec":"五、辰","t":"xiang"},{"q":"一般合墓为闭库，但大运「酉」来合原局「辰」时应如何论？","opts":["论化水，辰中阳土全部化为流水","论合动，且酉伤辰中木而不泄辰气","论闭库，水与土皆被完全锁死","论泄气，辰土被酉金严重泄弱"],"ans":1,"exp":"一般合墓为闭，但大运辰被酉合（或酉合动辰）为合动；酉伤辰中之木，而辰不被酉金泄气，水依然可进辰。","sec":"五、辰","t":"rule"},{"q":"巳火善变，遇酉丑化金而遇木火显火；当巳分别见「戌」与「辰」时如何表现？","opts":["见戌被墓闭失火性，见辰得木助而烈炎冲天","见戌与见辰皆化为金性，彻底丧失火性","见戌增火性回归本性，见辰火性减而显生金母性","见戌与见辰皆大增火性，与见午无异"],"ans":2,"exp":"巳见戌一党且增火性、回归本性，不惧丑酉合；见辰则火性立减，显露金之长生母性。","sec":"六、巳","t":"calc"},{"q":"在现代物象与行业中，地支「巳」最核心的代表是？","opts":["高楼大厦、水泥建筑与港口堤坝","果实饮食、休闲田园与酒店餐饮","银行钱库、司法执法与金属重器","思想、文字文化、电脑显示屏与影像"],"ans":3,"exp":"巳善变照应阴阳两面故主思想，本象如两本厚书主文字文化，现代主电脑、显示屏、互联网影像与移动互联网。","sec":"六、巳","t":"xiang"},{"q":"巳与午同属火支，两者在阴阳变通性上的本质区别是？","opts":["巳沟通阴阳善变，午纯阳不妥协唯与亥子交融","巳与午皆能与所有阴支和谐互通，没有区别","巳只能从水不能从金，午只能从木不能从土","午沟通阴阳善变，巳纯阳死板不知变通"],"ans":0,"exp":"巳占阳却能化金变阴、沟通阴阳；午只有阳性，见阴则对抗不妥协，性直无变通，唯与亥子水能水火既济交融。","sec":"七、午","t":"diff"},{"q":"午见未相合与午见丑相穿，对午火分别造成什么影响？","opts":["午未合使午火更明亮，午丑穿使午火得水既济","午未合绊而暗淡无光，午丑穿午败受伤主心疾","午未合与午丑穿均只伤未丑，午火毫无损失","午未合主心脑血管病，午丑穿主智商奇高"],"ans":1,"exp":"午见未合无功则绊，火土燥顽使午不再活泼明快、暗淡无光；午见丑穿则午败受伤严重，午为体必有心脏之疾。","sec":"七、午","t":"diff"},{"q":"未为木之库，一般喜冲刑开库而用，但下列哪组日柱「连体」不可刑冲？","opts":["辛未与癸未","己未与癸未","丁未与乙未","己未与辛未"],"ans":2,"exp":"己未、癸未、辛未可以刑冲开库而用；丁未与乙未干支连体（丁乙皆在未中），不可刑冲，刑冲反伤自身。","sec":"八、未","t":"calc"},{"q":"未被称为「太常」主果实饮食休闲，为何「乙未日」特别喜见子未穿？","opts":["子水冲开未库放出木火用","子水生助乙木使未土消失","未土泄于子水使脾胃更强","未穿制子水为做功制印用"],"ans":3,"exp":"子未穿必是未胜子（未见子变坚）；乙未日未为日支，见子（偏印）被未穿制，属于做功制印用。","sec":"八、未","t":"xiang"},{"q":"申可代表人的嗓音与古代「钟」，通常声响洪亮，唯独遇到哪种情况会声音沉闷、五音不全？","opts":["申入丑墓之时","申见卯暗合之时","申见寅相冲之时","申见子生拱之时"],"ans":0,"exp":"申代表嗓音：寅申有空嗓音洪亮，火克金焦脆，金水相生柔美，唯申入丑墓则声音沉闷、五音不全。","sec":"九、申","t":"xiang"},{"q":"申见子生拱与申入丑墓，对申金的「级别档次」各有何影响？","opts":["申见子泄气降低档次，入丑墓得库提升级别","申见子形化成气提升级别，入丑墓埋没降档次","申见子变浑浊无用，入丑墓变清澈发光","申见子与入丑墓均能提升申金的级别档次"],"ans":1,"exp":"申本干净，见子生拱是形化成气，提升申的级别；申入丑墓则变顽或埋没无光，降低档次（可取地产建筑）。","sec":"九、申","t":"diff"},{"q":"酉代表「磬」主悦耳嗓音，要保住好嗓音，酉最忌哪两种情况？","opts":["一不可申来比，二不可辛来透","一不可子来破，二不可亥来泄","一不可丑来收，二不可午来破","一不可卯来冲，二不可乙来配"],"ans":2,"exp":"申为钟、酉为磬，酉要悦耳一不可丑来收（入墓闷），二不可午来破（克破受损），否则五音不全；卯酉冲、乙酉配反主好嗓。","sec":"十、酉","t":"xiang"},{"q":"酉见辰合与酉见寅，在作用关系与象义上分别是？","opts":["酉辰合主金属提纯更亮，酉寅为相冲","酉辰合闭库无用，酉寅为暗合得财","酉辰合主金木交战，酉寅为相破","酉辰合主金属进泥生锈，酉寅为互绝"],"ans":3,"exp":"酉为精致珠宝之金，见辰合如进泥巴生锈不见光泽，辰有坏酉之意；酉与寅的关系则是互绝（寅绝酉，酉亦绝寅）。","sec":"十、酉","t":"diff"},{"q":"戌在职业与场所类象上十分丰富，下列哪组象义最符合「戌」的特征？","opts":["讲台老师、夜场闹市、宗教场所、武库","下水道、清洁工、地下室、坟墓","草木纺织、互联网波、钢筋、肝胆","泉水水晶、算盘珠、车轮、哲学"],"ans":0,"exp":"戌为火库（武库）又藏丁文库（讲台老师）；夜晚热闹主夜场；临天门主教堂寺院；下水道是丑，草木是卯，水晶是子。","sec":"十一、戌","t":"xiang"},{"q":"戌见亥与戌见卯，在作用结果上的本质差异是？","opts":["戌亥与戌卯皆为互助拱合，没有克制关系","戌克亥水火不容克性大，卯合戌能束缚控制戌","戌生亥同宫相助，卯冲戌使火库崩塌","亥克戌使戌失火性，戌合卯彻底控制卯木"],"ans":1,"exp":"戌亥虽同在乾宫，但戌阳土、亥藏阳水，水火不容故戌克亥且克性大；戌强而大，唯卯能如绳索牵狗般束缚控制戌。","sec":"十一、戌","t":"diff"},{"q":"寅申巳亥四长生中，为何唯独「亥」只藏壬甲而不带土？","opts":["亥中壬水太旺，把本气戊土全部冲走","亥属阴中之至阴，与阳土完全不相容","寅艮山、申坤地、巳土旺皆有土，亥在乾方无土","亥只藏一气壬水，连甲木也未真正藏入"],"ans":2,"exp":"寅在艮为山有土，申在坤为地有土，巳在巽是火土旺地，唯独亥在乾方无土，只藏壬甲两气。","sec":"十二、亥","t":"rule"},{"q":"戌、亥、子三者都表「数」，且亥有笔墨之象，下列对应准确的是？","opts":["戌主毛笔乙亥，亥主钢笔辛亥，子主证交所","戌主精微小数，亥主大数据平台，子主头脑数理","戌与亥皆主算盘珠，子主云计算数据交换","戌主大数据平台，亥主头脑数理，子主精微小数"],"ans":3,"exp":"戌为平台大数据运算（证交所、云计算）；亥为普通数学头脑算（古毛笔乙亥、今钢笔辛亥）；子为小数精微之数（算盘珠）。","sec":"十二、亥","t":"xiang"}]},{"n":52,"level":"中级","title":"干支虚实与自合","qs":[{"q":"壬子、戊辰、丙午、己丑四柱中，哪一柱不称干支通禄？","opts":["戊辰","壬子","丙午","己丑和戊辰都称通禄"],"ans":0,"exp":"通禄八柱是甲寅、乙卯、庚申、辛酉、壬子、癸亥、丁巳、丙午；戊辰、戊戌、己丑、己未之土不称通禄。","sec":"一、干支的五类配置","t":"calc"},{"q":"癸酉、丁卯、甲子、庚辰、庚戌、辛未，这六柱按盲派属于哪一类？","opts":["干支相克，称天干虚透","干支假生，地支可以被坏","干支通禄，连体不可坏","干支托根，支坏则干坏"],"ans":1,"exp":"假生六柱看似生实则非真生，地支是可以坏的，有些组合地支被坏才好，如癸酉。","sec":"一、干支的五类配置","t":"calc"},{"q":"戊辰、戊戌、己丑、己未这四柱，对刑冲的态度分别是什么？","opts":["四柱都喜刑冲，开库见财","四柱都不喜刑冲，冲则库破","戊辰戊戌不喜刑冲；己丑己未刑冲反吉","戊辰戊戌刑冲反吉；己丑己未不喜刑冲"],"ans":2,"exp":"戊辰戊戌为阳库不喜刑冲；己丑己未为阴库，须刑冲反吉。","sec":"一、干支的五类配置","t":"rule"},{"q":"按盲派，天干虚透的官杀、财星、印星，分别主什么？","opts":["官杀主权力；财主才气；印主保护靠山","官杀主才气；财主名气；印主放大包装","官杀主名气；财主钱财；印主学历文凭","官杀主名气；财主才气；印主放大包装"],"ans":3,"exp":"财星虚透为才气，官杀虚透为名气，印星虚透为放大、包装、身份、荣誉。","sec":"二、虚实的应用","t":"rule"},{"q":"原局年上有子，时上见癸未，按盲派是哪个干代表子？若子为妻代表什么？","opts":["癸代表子；妻离开了自己","壬代表子；妻离开了自己","壬代表子；妻生育得子","癸代表子；妻与自己合在一起"],"ans":0,"exp":"子水在天干虚是癸代表子，不是壬；若子表示妻子，柱中见癸未，代表妻子跑了离开了。","sec":"二、虚实的应用","t":"calc"},{"q":"原局年上有寅，时上见甲申，属于实化虚的哪一种？","opts":["墓气的虚","本气的实化虚","所藏旺气的虚","干支自合"],"ans":1,"exp":"本气之支在别处以天干形式出现：年上寅，时上甲申，寅虚在时上。丙申才是藏气（旺气）虚。","sec":"二、虚实的应用","t":"calc"},{"q":"原局有未字，又见乙酉柱，按盲派是怎么回事？","opts":["藏气虚，未中丁火透出","需冲开未库，乙木才能出墓","墓气虚，未中乙木虚而出墓","本气虚，未虚在乙酉上"],"ans":2,"exp":"墓气的虚：墓中之气以天干出现，不用冲就能出墓；未中乙木可从墓中出来。","sec":"二、虚实的应用","t":"calc"},{"q":"流年发生实变虚的情况，按盲派应期上怎么看？","opts":["原局无此变化才有大事","只对妻星有影响，对其余无事","必有大事，人离或财散","不会有大事发生；大运逢之才同看"],"ans":3,"exp":"大运同看原局的虚实变化，如乙酉运妻跑；但流年发生实变虚不会有大事。","sec":"二、虚实的应用","t":"rule"},{"q":"六十甲子中，哪两柱是地支克到天干？","opts":["丁亥、辛巳","甲申、乙酉","己亥、癸巳","戊子、壬午"],"ans":0,"exp":"丁亥亥本气壬合丁而克之，辛巳巳本气丙合辛而克之；戊子、壬午、己亥、癸巳仍是天干克地支。","sec":"三、干支自合","t":"rule"},{"q":"己亥、癸巳的支中藏甲、戊能合己、癸，它们是谁克谁？","opts":["天干地支互不相克，只合","仍是天干克地支，本气受克","地支克天干，与丁亥同理","地支克天干，藏干合克"],"ans":1,"exp":"己亥、癸巳看似亥中有甲、巳中有戊，但仍是天干克地支，因地支本气受天干所克；唯丁亥、辛巳是本气合克天干。","sec":"三、干支自合","t":"diff"},{"q":"干支自合柱的婚姻，按盲派为什么多不幸？","opts":["自合是孤阴孤阳，缺少气交","合得太紧，夫妻无话可说","理想过高，自合之支不可被合冲刑破","自合之支无力，必被日主所克"],"ans":2,"exp":"自合者心有完美理想，现实不能实现；自合之支不能被坏，一有风吹草动就离婚，所以离婚率高或单身多。","sec":"三、干支自合","t":"rule"},{"q":"戊子、己亥与壬午、癸巳，自合柱的取象分别是什么？","opts":["戊子己亥水火既济；壬午癸巳如井盖","戊子己亥如井盖；壬午癸巳投海投火","戊子己亥天地反晦；壬午癸巳水火既济","戊子己亥如井盖；壬午癸巳水火既济"],"ans":3,"exp":"戊子、己亥如井盖将水盖在里边；壬午、癸巳阴阳气交，水火既济；丁亥、辛巳则是天地反晦自毁之象。","sec":"三、干支自合","t":"xiang"}],"fine":[{"q":"盲派之所以不用传统旺衰而按「干支配置」分类六十甲子，根本原因是？","opts":["天干与地支的配置不同，象义就不同","六十甲子只用来定大运，不参与原局吉凶","传统旺衰无法推算六十甲子的纳音五行","天干与地支的生克只看地支而不看天干"],"ans":0,"exp":"天干与地支的配置不同，象义就完全不同，这是盲派将六十甲子分为五类配置而不用传统衰旺的原因。","sec":"一、干支的五类配置","t":"rule"},{"q":"干支通禄共八柱，水火阴阳错配（如壬子）为何仍被称为「通禄」？","opts":["子中藏有壬水本气，阴阳完全一致","子中含癸水，水火错配仍论连体通禄","壬水透出天干时直接变成癸水之象","所有地支帝旺柱一律都被称为通禄"],"ans":1,"exp":"甲寅、乙卯、庚申、辛酉、壬子、癸亥、丁巳、丙午共八柱通禄；水火阴阳错配，壬子中子含癸水仍称通禄。","sec":"一、干支的五类配置","t":"rule"},{"q":"下列四柱中，属于「干支托根」（干依支生存，支坏则干也坏）的是哪一柱？","opts":["甲申","甲寅","甲辰","甲子"],"ans":2,"exp":"干支托根共十柱：甲辰、乙未、乙亥、丙寅、丁未、戊午、己巳、辛丑、壬辰、壬申；甲子假生、甲寅通禄、甲申相克。","sec":"一、干支的五类配置","t":"calc"},{"q":"「干支带象」放在日主上看即坐下食神或伤官，其地支何时可以被坏？","opts":["只要坐下是伤官，地支任何时候都可坏","干支带象如头与身，地支永远不可被坏","日主透出比肩劫财时，地支才可以坏","日主有依托的印星时，地支可以被坏"],"ans":3,"exp":"干支带象为干生支，如头与身；坐下食伤能否被坏要看情况，若日主有依托的印星，地支之字就可以被坏。","sec":"一、干支的五类配置","t":"rule"},{"q":"盲派所讲「天干虚透共二十二柱」，是由哪两部分组成的？","opts":["干支相克二十柱，加假生的庚戌与辛未","干支相克二十柱，加甲辰与乙未两柱","干支假生六柱，加干支托根十柱与六自合","干支相克二十柱，加戊辰与己丑两柱"],"ans":0,"exp":"干支相克共二十柱（甲辰、乙未除外）称天干虚透，再加上干支假生中的庚戌、辛未两柱，共计二十二柱。","sec":"一、干支的五类配置","t":"calc"},{"q":"甲辰、乙未看似天干克地支，但在六十甲子五类配置中为何不归入「干支相克」？","opts":["甲辰与乙未归入四墓专柱，与戊辰同类","甲辰与乙未归入干支托根，不作相克论","甲辰与乙未归入干支通禄，连体不分","甲辰与乙未归入干支假生，支可被坏"],"ans":1,"exp":"干支相克定义中明确「甲辰、乙未除外」，因为甲辰、乙未属于干支托根（辰有乙木余气、未为木库，干依支存）。","sec":"一、干支的五类配置","t":"diff"},{"q":"关于虚实应用中「虚」的本质含义，下列哪项表述最准确？","opts":["天干坐实根而变得沉重，无法流动变化","八字中缺少的五行，只在流年短暂出现","弱化、轻化、气化，即地支跑天上去了","地支被冲破后完全消失，不再起作用"],"ans":2,"exp":"虚实讲变化：虚就是弱化、轻化、气化，通俗地说就是地支跑到天上去了。","sec":"1. 虚是什么","t":"rule"},{"q":"地支子水若在天干虚透，下列哪种说法符合盲派细则？","opts":["壬与癸都可以同等代表子水","是壬代表子，癸不能代表子","子水纯阴专一，永远不会虚透到天干","是癸代表子，壬不能代表子"],"ans":3,"exp":"子水在天干虚，是癸代表子，不是壬；若子水表示妻子，柱中见癸未即代表妻子跑了、离开自己。","sec":"1. 虚是什么","t":"diff"},{"q":"实化虚在命理中有两层主要现实含义，除了「人（妻）离开」之外，另一层是？","opts":["做生意把产品从多的一方移到少的一方卖","读书考取功名利禄，从基层升入高层","身体由强转弱，容易突发性受伤或手术","祖业田产被他人侵占，最终一无所有"],"ans":0,"exp":"实化虚含义有二：一是人（妻）离开；二是做生意的一种类型——产品从多的一方移到少的一方卖出去。","sec":"2. 实化虚的含义与三种情形","t":"xiang"},{"q":"原局地支有「寅」，别处天干地支出现「丙申」，这属于实化虚的哪种情形？","opts":["本气的实化虚，代表甲木直接透出","所藏旺气的虚，代表寅虚了、跑了","墓气的虚，代表丙火从墓库中引出","非虚实变化，只是寅申两支直接相冲"],"ans":1,"exp":"寅中藏长生旺气丙火，寅字虚成丙申属于「所藏旺气的虚」，同样代表寅虚了、跑了。","sec":"2. 实化虚的含义与三种情形","t":"calc"},{"q":"原局以卯为妻，若大运行「乙酉」运（实化虚），婚姻会出现哪种分化？","opts":["无论婚姻是否稳定，大运逢之必然离婚","只要流年不逢乙酉，大运乙酉也毫无影响","婚姻不稳则离婚，稳定则可能因工作分离","大运逢之反主夫妻团聚，不会发生分离"],"ans":2,"exp":"原局无虚实变化而大运逢之同看：卯妻行乙酉运主妻跑了，婚姻本身不稳会离婚，稳定则可能因工作而分离。","sec":"2. 实化虚的含义与三种情形","t":"diff"},{"q":"干支配置中的「庚辰变庚子」，虽非虚实之变，却常代表哪种生意模式？","opts":["完全不做实体加工，只做中介收佣金","只守着祖产收取固定租金，不涉流动","把高价奢侈品低价抛售、清仓处理","从不值钱的地方通过加工转化变得值钱"],"ans":3,"exp":"庚代表财，庚辰变庚子虽不是虚实之变，也是一种生意——从不值钱的地方，通过加工转化变得值钱了。","sec":"2. 实化虚的含义与三种情形","t":"xiang"},{"q":"干支自合共有六柱，下列哪一组全部属于干支自合柱？","opts":["丁亥、戊子、己亥、辛巳、壬午、癸巳","丙申、戊子、己亥、辛巳、壬午、癸巳","丁亥、戊子、乙巳、辛巳、壬午、癸巳","丁亥、戊子、己亥、庚申、壬午、癸亥"],"ans":0,"exp":"干支自合六柱是：丁亥、戊子、己亥、辛巳、壬午、癸巳，属于干支相克一组中特殊的六柱。","sec":"1. 六个自合柱","t":"calc"},{"q":"甲申、乙酉中申酉为何克不到甲乙，而丁亥、辛巳却能地支克天干？","opts":["申酉属于帝旺与长生，本就不克任何天干","天干位高为君，唯丁亥辛巳本气合克天干","甲乙木气太旺，丁辛金火气太弱之故","丁亥辛巳地支藏干最多，故能逆克天干"],"ans":1,"exp":"天干为君、地支为臣，一般地支克不到天干（如甲申、乙酉）；唯丁亥（亥本气壬合丁）、辛巳（巳本气丙合辛）能克。","sec":"1. 六个自合柱","t":"rule"},{"q":"干支自合柱在四柱宫位上最喜配在哪个位置，主何象义？","opts":["多喜配在月上，主兄弟姐妹之间团结互助","多喜配在日上，主夫妻百年好合绝无波折","多喜配在时上，主自身能力能充分发挥","多喜配在年上，主早年即可继承丰厚祖业"],"ans":2,"exp":"自合是阴阳相交、配合得当，多喜配在时上，表示自己的能力能够充分发挥。","sec":"2. 自合的婚姻与取象","t":"rule"},{"q":"在六个干支自合柱的取象中，「丁亥、辛巳」两柱对应的专属象义是？","opts":["阴阳气交，水火既济、富贵双全之象","如井盖一般，将水盖在里边之象","钢筋水泥，建筑高楼、稳固承载之象","天地反晦，投海、投火自毁之象"],"ans":3,"exp":"戊子、己亥如井盖；壬午、癸巳为水火既济；丁亥、辛巳因地支逆克天干，取象天地反晦，投海、投火自毁。","sec":"2. 自合的婚姻与取象","t":"xiang"},{"q":"盲派断法中所说的「反局」，其核心定义是？","opts":["命理表达的意思出现前后相反的矛盾","大运逆行与顺行交替，导致运势反复无常","天干透出七杀而地支没有印星来化杀","日主身弱而财官太旺，无法担起富贵"],"ans":0,"exp":"反局是指命理表达的意思出现前后相反的矛盾，就像论文观点前后矛盾一样，反应在人命上就是反局。","sec":"断法：反局","t":"rule"},{"q":"乾造「己巳 丙寅 戊午 丁巳」，为何会形成「身首分离」的反局？","opts":["大运乙丑与月令丙寅天克地冲，伤及头部","寅午一家寅如头，戊通禄巳为身，寅巳相穿","丙火透干克制己土，形成枭神夺食之局","年时两巳冲克日支午火，导致火土俱灭"],"ans":1,"exp":"日主戊土托于午，寅午一家故寅如头；同时戊通禄于巳，年时两巳代表身体；寅巳相穿即身体与身体相穿，身首分离。","sec":"断法：反局","t":"calc"},{"q":"乾造「己巳 丙寅 戊午 丁巳」应验车祸时，「死时一只眼带不走」对应的象义是？","opts":["午火自刑引发心脑血管破裂而波及眼睛","己土在年干遮蔽太阳，主双目失明之象","寅上丙火如头上眼，丙禄在巳，寅巳穿飞走","丁火坐在巳火之上，主烈火灼伤左眼"],"ans":2,"exp":"寅上见丙火如头上的一只眼，而丙禄在巳；两个巳如两车轮，寅巳相穿即车轮碾头、一只眼在车祸中飞走。","sec":"车祸之象","t":"xiang"},{"q":"同一命盘「己巳 丙寅 戊午 丁巳」，若生在古代为何不断车祸而断「死于火灾」？","opts":["己土代表灶台，寅木为柴薪，必然厨房失火","戊午日柱火土燥烈，古代极易患热病而亡","丙丁火透干太旺，自然引发天干雷火之灾","丁巳己巳两印如房包住命主，寅巳穿引爆起火"],"ans":3,"exp":"古代车无此速度；丁巳、己巳两印包住命主如居住的房子（己土是瓦），寅巳穿引爆火苗起火，人被包在里边出不去。","sec":"同一盘的另一种取象（古代）","t":"xiang"},{"q":"同一八字可取古代火灾与现代车祸两种截然不同的象，这说明取象必须遵循什么原则？","opts":["象既要合于理，又要合于现实生活","古代命例不能套用现代生活，必须另起一盘","凡是见寅巳穿的命局，一律只能断为车祸","象只取决于干支五行，不必考虑时代背景"],"ans":0,"exp":"同一个八字可以取两种象，每个都能得到合理解释，核心原则是：象既要合于理，又要合于现实生活。","sec":"同一盘的另一种取象（古代）","t":"rule"},{"q":"关于命理的「象理」，盲派认为八字中的每一个字是如何得到定义的？","opts":["脱离十神与宫位，单凭五行生克就能定出全部象","在干支、十神、宫位关系中定义，离关系无从理解","每个字的象义固定不变，不随组合关系而改变","只看单个地支的藏干多少即可完全确定象义"],"ans":1,"exp":"命理通过干支关系、十神关系、宫位关系呈象；每一个字都在关系中得到定义与确定，离开关系无从理解命理。","sec":"命理的象理","t":"rule"}]},{"n":53,"level":"中级","title":"正局与反局","qs":[{"q":"按盲派，大运反局的特点是什么？","opts":["凶在大运，过运仍留后患","凶只在这步大运，过运则吉","凶在原局，一生不变","凶只应在当年一年"],"ans":1,"exp":"口诀：反在哪一类，凶在哪一类。原局反局原局凶，大运反局该步大运凶，流年反局该年凶。","sec":"一、基本概念","t":"rule"},{"q":"日主与日支同时做功，两者意思不一致，按盲派怎么论？","opts":["论反局，以日支之功为主","论正局，取日主之意","论反局，以日主之功为主","不分正反，看大运定"],"ans":2,"exp":"日主日支同做功时比较意思，一致为正、不一致为反，但以日主之功为主，不以日支为主。","sec":"二、如何判定原局的正反","t":"rule"},{"q":"日主合年月上的官，与日主合时上的官，意思有何区别？","opts":["两者都是我管人，只是远近不同","合年月官是我被管；合时官是我管人","两者都是我被管，只是轻重不同","合年月官是我管人；合时官是我被管"],"ans":3,"exp":"时柱是主位、主头脑：合时官等于官控制了我的头脑；合年月官是我去管理控制别人，一般不构成问题。","sec":"二、如何判定原局的正反","t":"diff"},{"q":"己丑日、甲戌时（己合时干甲官），丑刑戌，且局中有金水之势。怎么论？","opts":["反局，用的时支戌被日支刑坏","正局，己合甲官是我管人","正局，丑刑戌是制劫财为功","不反，刑戌只是小损"],"ans":0,"exp":"日合时官被官控制，必须用甲坐下的戌（劫财是体），体不可坏；丑刑坏戌即反局。","sec":"二、如何判定原局的正反","t":"calc"},{"q":"己丑日，甲戌在月柱（己合月上甲官），丑刑戌。是否构成反局？","opts":["构成，只要丑刑戌就反","不构成，日合月官是我管人","不构成，但月支戌必须不坏","构成，与甲戌在时柱相同"],"ans":1,"exp":"同一组合，官在月上是我管理控制别人，不要求用戌；官在时上才必须用时支。","sec":"二、如何判定原局的正反","t":"calc"},{"q":"戊土生申，戊申一柱与辛金因戊相连成连体金，这个金是用。此时局中巳申合，怎么论？","opts":["正局，合住申金护住了用神","正局，巳申合是制金为功","反局，连体之用被合坏","不反，只有冲才坏连体"],"ans":2,"exp":"连体不可坏，坏则反局、严重者伤寿；若被制的字与日主不连体（不受生、通根不相连），可制，仍为正局。","sec":"三、连体不可坏","t":"diff"},{"q":"地支依次为巳申未丑，年月巳申合、日时未丑冲，巳未同为火土党、申丑同为金水党。怎么论？","opts":["干合支冲，不算反局","两党左右排列，不反","两党内外排列，不反","两党交叉间隔，冲合反局"],"ans":3,"exp":"巳申未丑按党排成ABAB交叉，一合一冲、两种做法相反，才是冲合反局；内外、左右排列不反。","sec":"四、冲合反局","t":"calc"},{"q":"原局乙庚天干相合，同时丑未地支相冲，算冲合反局吗？","opts":["不算，必须是地支与地支冲合","算，一合一冲做法相反","算，只要日时一方有冲","要看大运有无合冲再定"],"ans":0,"exp":"冲合反局必须地支与地支，干合支冲不算；两党交叉排列才反。","sec":"四、冲合反局","t":"diff"},{"q":"原局靠地支相冲做功，大运地支来合住被冲的字，怎么论？","opts":["天干无合则无妨","冲被合住，岁运冲合反局","合助冲势，更吉","合冲相抵，原局不变"],"ans":1,"exp":"原局冲做功怕岁运来合，合做功怕岁运来冲；如原局申入丑墓冲未，走卯运卯申合则反，走寅运寅申冲仍不反。","sec":"四、冲合反局","t":"rule"},{"q":"原局没有明确的制（冲或合），岁运用相反的方式来破，怎么论？","opts":["只在流年反局","只在大运反局","不怕，不构成反局","照样反局，凶更重"],"ans":2,"exp":"岁运冲合反局的前提是原局有明确的制；原局没有明确的制，则不怕。","sec":"四、冲合反局","t":"rule"},{"q":"流年乙酉「乙到」，原局地支有卯、未、辰，应期先代表哪一个？","opts":["先应原局天干，再论地支","先应辰，再未，最后卯","先应未，再卯，最后辰","先应卯，再未，最后辰"],"ans":3,"exp":"流年应期代表顺序：先地支后天干；地支先本气（卯），再墓气（未），最后余气（辰）。","sec":"五、大运反局","t":"step"}],"fine":[{"q":"八字原局无明显大势、只有日主自己能做功时，按盲派应如何判定正反？","opts":["因无势可随，一律直接判定为反局","也算正局，按原局位置分三类反局","不算正局也不算反局，归为特殊假生局","只要无势，走任何大运都必然成大运反局"],"ans":1,"exp":"正局指日柱做功与原局整体意思一致；八字无势、只有日主自己能做功也算正局。反局按位置分原局、大运、流年三类。","sec":"一、基本概念","t":"rule"},{"q":"判定原局正反局的正确顺序，第一步和第二步分别是？","opts":["先看日支；日支不做功再转看时支","先看年柱；年柱不做功再转看月令","先看日主；日主不做功再转看日支","先看财官强弱；身弱再看印比帮扶"],"ans":2,"exp":"判定原局正反顺序：先看日主，日主不合、不生（不做功）才转看日支；日主与日支同时做功则以日主为主。","sec":"1. 判定顺序","t":"step"},{"q":"判断日支做功是否构成反局时，核心是看日支与「势」的哪方面关系？","opts":["看日支的藏干个数是否多于八字的势","看日支是否坐在十二长生的死绝之地","看日支本身的五行是否与月令直接相冲","看日支所追求表达的意图是否与势对抗"],"ans":3,"exp":"判定日支方向，不是看「日支这个字与势对抗」，而是看「日支表达的意图」与八字整体的势是否对抗。","sec":"1. 判定顺序","t":"rule"},{"q":"当「日主合到官星」做功时，盲派如何观察日主自己所做的功？","opts":["官带着坐支，看该坐支有无做功即为日主之功","必须等流年把官星合走，才算日主做成此功","只看日支与月令的关系，与官星坐支无关","只看日主天干合官，完全不用看官星的坐支"],"ans":0,"exp":"日主合到哪里就要看到哪里：官为统领带着自己的坐支，再看这个坐支有没有做功，做的功就是日主自己做的功。","sec":"1. 判定顺序","t":"rule"},{"q":"日主合时上的官，为何要求「时支必须用、不可坏」？","opts":["时柱在宾位，坏了就无法与外界建立联系","官控制头脑成我意向，干为统帅支为兵卒必用","时支是日主的印星长生，坏了就彻底失学","时支永远代表父母，坏了时支就主克父母"],"ans":1,"exp":"时柱主位主头脑，合时官等于官控制头脑、官的意向成我的意向；干是统帅、支是兵卒，打仗必用兵卒，故时支不可坏。","sec":"2. 日合官：合年月官与合时官，意思不同","t":"rule"},{"q":"在日合时官的配置中，哪两组日时搭配特别要求「必须用时支且不可坏」？","opts":["戊日配癸亥时、庚日配乙酉时","丁日配壬寅时、癸日配戊午时","己日配甲戌时、辛日配丙申时","甲日配己巳时、丙日配辛卯时"],"ans":2,"exp":"只有己日主配甲戌时、辛日主配丙申时必须用时支且不可坏，因为戌对己、申对辛是劫财，是「体」，体不可坏。","sec":"2. 日合官：合年月官与合时官，意思不同","t":"calc"},{"q":"「乙巳 庚辰 辛卯 丙申」坐牢，而换作「壬辰」时却升正处级，关键变化在于？","opts":["丙申时申金太弱受克，壬辰时辰土生金变强","丙申时卯申暗合伤及财星，壬辰时卯辰穿吉","丙申时庚乙合化金太重，壬辰时水泄金气","丙申时辛合官且申被巳合绊；壬辰时伤官制官"],"ans":3,"exp":"丙申时辛合丙官必用申，申反被巳官合绊成反局坐牢；换成壬辰时，巳火泄于辰土、伤官制官，不再是合时官，故升官。","sec":"2. 日合官：合年月官与合时官，意思不同","t":"diff"},{"q":"「甲辰 戊辰 癸卯 己未」一造中，日主戊合月令癸水为何不反局，且应何职业？","opts":["日合月癸是我管人，卯穿辰用财原神制官，行长","辰土多而入墓，癸水入辰库被闭，普通工人","戊癸合化火为印，卯未拱木生火，高校教师","日合月癸是我被管，卯穿辰坏了时支，常坐牢"],"ans":0,"exp":"日主戊合月癸是管理控制，不反；日支卯（食神财原神）与未拱旺穿制辰官，是用财原神制官，故为管钱的企业官（支行长）。","sec":"3. 日合年月官的正局例","t":"xiang"},{"q":"朱元璋造「戊辰 壬戌 丁丑 丁未」，从日主与日支意向角度为何判为正局？","opts":["丁火坐丑湿土泄气，全靠戊土伤官制杀成格","丁合月壬为管人，戌未冲刑制住官库财库","辰戌丑未四库相冲，把日主自身根基冲散","丁火合壬水化木生身，属于身强印旺之正局"],"ans":1,"exp":"日主丁合月令壬官是我管人之意，戌冲辰、刑丑与丑未冲把官库财库全部制住，日主与日支意向一致，正局。","sec":"3. 日合年月官的正局例","t":"calc"},{"q":"判断八字中某被制之字是否属于「连体不可坏」，最关键的依据是？","opts":["看该字的地支是否属于四长生或四帝旺","看该字的天干是否与日主构成天干五合","看该字与日主或用神位之间有无生或通根相连","看该字是否位于日支，在日支一律算连体"],"ans":2,"exp":"判断连体要点：看被制的字与日主（或用神位）之间有无生、通根相连；连体则制之为反（伤寿），不连体则制之为正。","sec":"三、连体不可坏","t":"rule"},{"q":"李宗仁造「辛卯 丙申 辛未 癸巳」中巳申合制申金，为何不构成连体反局？","opts":["辛金日主坐未土得库，即使坏申也不伤寿","癸水透干通关调候，化解了巳申相合之克","申金坐在月令力量极大，巳火根本合不住申","辛日不受生、申与日主不连体，可制为正局"],"ans":3,"exp":"辛金日主不受生，坐下申是劫财（军队），与日主不连体，可以制；主位的官制申做功，故是管理军队的大官，正局。","sec":"三、连体不可坏","t":"diff"},{"q":"「甲午 癸酉 辛卯 己亥」在己卯运丙戌年车祸而亡，其反局机理是？","opts":["辛酉连体酉是用，丙戌年戌穿酉禄成流年反局","亥水入辰墓不开，丙戌年火土太燥引发心脏病","卯酉相冲在原局已成反局，一直拖到丙戌年","甲午带象被癸水冲克，导致官星彻底损坏"],"ans":0,"exp":"辛酉月辛日连体，连体的酉金是用，不可坏；己卯运丙戌年，戌穿酉（穿了禄），连体之用被穿坏，流年反局而亡。","sec":"三、连体不可坏","t":"calc"},{"q":"原局冲合反局中，为何「内外（ABBA）」与「左右（AABB）」排列不以反局论？","opts":["内外与左右结构必然会合化成同一五行","表里制外、主制宾，只是手段不同而意向一致","内外与左右结构根本不存在地支相冲与相合","只要天干透出印星，就能自动化解冲合对立"],"ans":1,"exp":"两党交叉（ABAB）才是冲合反局；内外、左右表示「里制外」「主制宾」，一冲一合只是对外手段不同，意向一致故不反。","sec":"1. 原局冲合反局","t":"rule"},{"q":"「戊申 丁巳 戊子 戊午」初看火土成势去申金，为何此人极穷、一年不足五千？","opts":["申金藏壬水财星太弱，根本不够三人分夺","丁火坐巳火太旺，把戊土烧焦而无法担财","巳申合、子午冲，两党交叉成财星冲合反局","子水冲午火把印星冲坏，导致一辈子没学历"],"ans":2,"exp":"年月巳申合、日时子午冲，火土与金水两党交叉排列（ABAB），主宾做功方式相反，财星反局，哪方面反局哪方面凶。","sec":"1. 原局冲合反局","t":"calc"},{"q":"坤造「丁未 癸丑 丙申 辛卯」年月未丑冲、日时申卯合，为何不反局？","opts":["丙辛天干相合把地支申卯合化成同一党","女命只看夫星是否透干，不看地支冲合反局","丁癸天干相冲抵消了地支未丑相冲的力量","金水在内、木火在外，属内外结构用里制外"],"ans":3,"exp":"地支未、丑、申、卯按两党排为「木火—金水—金水—木火」，即内外结构（ABBA），用里面的制外面的，意思清楚不反。","sec":"1. 原局冲合反局","t":"calc"},{"q":"「癸卯 乙丑 辛未 己丑」原局丑未冲大发，为何己巳运甲申年严重车祸成植物人？","opts":["己甲合、巳申合天地合绊，合住原局之冲成反局","癸水食神在年干虚透，遇到甲木泄气导致病灾","己巳运巳火生助未土，使未土过旺而冲坏丑库","甲申年申金冲克卯木财星，把原局财源断绝"],"ans":0,"exp":"原局丑未冲为吉；己巳运甲申年天地合绊（己甲合、巳申合），把原局的冲合住成反局，甲为头、申为脊柱，合绊不能动。","sec":"2. 岁运冲合反局","t":"calc"},{"q":"「癸卯 丙辰 戊子 丙辰」靠两辰穿制卯，为何壬子运甲申年有官灾、乙酉年却平反？","opts":["甲申年子申半合化水；乙酉年子酉相破助丙火","甲申年申入水党暗合卯成反；乙酉年冲卯不反","甲申年甲木坐实克戊土；乙酉年乙木合庚化金","甲申年申金冲破辰库；乙酉年酉金入辰墓生水"],"ans":1,"exp":"壬子运甲申年，申入辰子水党又与卯暗合，破了穿制成冲合反局（甲虚透终无事）；次年乙酉，卯酉冲不再反，故平反。","sec":"2. 岁运冲合反局","t":"calc"},{"q":"同是地支带穿，「癸卯 甲寅 己卯 戊辰」为何反而「不怕反局，反运也无事」？","opts":["戊土劫财在时干保护，任何大运都无法破局","寅卯辰三会木局成功，能量大到不会反局","甲己合，穿是附带的、做功不明确不专心","原局卯木太旺，把辰土完全穿死而不再怕反"],"ans":2,"exp":"原局甲己合，卯辰穿是附带的，可穿可不穿，做功不明确、不专心，所以不怕反，行反运也无事。","sec":"2. 岁运冲合反局","t":"diff"},{"q":"在「大运体用」的判定规则中，走天干运与走地支运分别以谁为体、谁为用？","opts":["无论走干运还是支运，永远以地支为体天干为用","无论走干运还是支运，永远以天干为体地支为用","走干运干为体支为用；走支运支为体干为用","走干运支为体干为用；走支运干为体支为用"],"ans":3,"exp":"大运体用中，用＝作用、运动，体＝静态、固定：走天干运，支为体、干为用；走地支运，天干为体、地支为用。","sec":"五、大运反局","t":"rule"},{"q":"薄一波造「戊申 甲寅 辛卯 癸巳」行丙辰运，为何丙运能跑掉而辰运坐牢五年？","opts":["丙虚透故能跑；辰生申穿卯晦巳且为伤官牢狱","丙火合辛金为正官加身；辰土冲寅木把禄冲走","丙运有甲木生助不怕金；辰运申子辰合成水局","丙火在时支巳火有根；辰土与戊土比肩争财"],"ans":0,"exp":"丙为官，丙辛合但丙虚透故丙运尚能跑掉；辰运辰生申、穿功神卯、晦巳火，且辰为伤官库又主牢狱，反局坐牢五年。","sec":"五、大运反局","t":"calc"},{"q":"同是行带辰的大运，「丙午 辛丑 己卯 辛未」为何在甲辰运的「甲运」就坐牢十年？","opts":["甲运把月令丑土彻底合化，破了丑未相冲","甲与己合且甲坐辰是实，旺官合身又临辰牢狱","甲木直接穿倒时支未土，导致燥土不能制水","甲木七杀虚透天干克身，毫无印星可以通关"],"ans":1,"exp":"上造丙运丙虚能跑，本造甲与己合且甲坐辰是实，旺官合身，加上辰为牢狱、穿卯晦火反局，所以甲运就坐牢。","sec":"五、大运反局","t":"diff"},{"q":"袁世凯造「己未 癸酉 丁巳 丁未」在丙辰年死亡，其流年反局的机理是？","opts":["癸水七杀在丙辰年得根，直接克死丁火日主","辰土冲开未土墓库，把己土食神全部泄尽","原局用巳，丙虚透辰晦巳使巳倒戈变金内部反","丙火夺了丁火日主的光辉，形成劫财争财"],"ans":2,"exp":"原局要用巳火制酉；丙辰年丙火一虚透，辰土再晦巳火，巳火倒戈合酉变成金，主内部矛盾、手下反叛而死。","sec":"五、大运反局","t":"calc"},{"q":"和珅造「庚午 乙酉 庚子 壬午」为何既发巨财又当大官，且在庚寅运被赐死？","opts":["乙庚合化金局助身，故巨富；庚寅运财旺身弱","年午被酉破、时午被子冲；庚寅运冲克酉金禄","壬水食神生乙木正财；庚寅运寅卯辰三会克土","年午制不净当财、时午制净当官；庚寅运反局"],"ans":3,"exp":"年上午制不净（官杀制不净当财看）故巨富，时上午制净当官看；庚寅运庚坐绝地、寅午拱火使午制不住，反局赐死。","sec":"五、大运反局","t":"calc"},{"q":"盲派断牢狱之灾有一条经典口诀，如「戊申 己未 癸巳 己未」应之坐牢，该口诀是？","opts":["七杀夹克主牢狱","伤官见官必入狱","枭神夺食主牢灾","财多身弱主官非"],"ans":0,"exp":"口诀：七杀夹克主牢狱。如「戊申 己未 癸巳 己未」及「己未 丁卯 辛卯 丁酉」，皆是七杀夹克日主的牢狱命。","sec":"五、大运反局","t":"rule"}]},{"n":54,"level":"中级","title":"应期","qs":[{"q":"按盲派大限，日柱（日支）管多大年龄段？","opts":["18–35 岁","35–50 岁","35–55 岁","55 岁以后"],"ans":2,"exp":"年柱1–18、月柱18–35、日柱35–55、时柱55岁以后；先用大限定出事的年龄范围。","sec":"一、大限应期","t":"rule"},{"q":"月柱大限（18–35 岁）应凶，此时走的大运是吉运，应期怎么论？","opts":["此运应吉，过运应凶","此运照样应凶，吉运无用","吉运压住凶，永不应凶","此运不应，过运则凶"],"ans":3,"exp":"交脱诀：大限与大运都凶才应凶，一吉一凶互相抵消，事情推到过运才应。","sec":"2. 大限与大运的关系","t":"calc"},{"q":"大限应凶，大运吉，和大限应凶、后面才有吉运，两种情形分别怎么论？","opts":["前者过运才凶，后者未到吉运就先凶","前者此运即凶，后者过运才凶","前者此运不凶永不应，后者先凶","两者都是过运才凶"],"ans":0,"exp":"当运逢吉则此运不应、过运凶；若吉运在后面，则吉运未到之前就已应凶。","sec":"2. 大限与大运的关系","t":"diff"},{"q":"庚、辛、癸三个天干的禄（原身）依次是哪三个地支？","opts":["申、酉、亥","申、酉、子","巳、午、子","酉、申、亥"],"ans":1,"exp":"禄表：庚禄申、辛禄酉、壬禄亥、癸禄子；丙戊禄巳，丁己禄午。","sec":"二、禄与原身应期","t":"calc"},{"q":"局中有戊土，流年出现巳，按禄与原身应期怎么论？","opts":["巳只是普通地支，与戊无关","戊被巳生，只论生不论应","见禄代表原身，戊的应期到了","巳为戊的墓，论墓者主收"],"ans":2,"exp":"丙戊禄在巳，见禄代表原身，这一年要发生与戊有关的事。","sec":"二、禄与原身应期","t":"calc"},{"q":"辰戌丑未四库，在禄与原身应期里怎么论？","opts":["辰戌丑未都是土的禄","辰为乙的原身","丑未为金木的原身","四库没有原身"],"ans":3,"exp":"原身只在寅卯巳午申酉亥子上，辰戌丑未四库没有原身，不能这样取应。","sec":"二、禄与原身应期","t":"rule"},{"q":"原局有戌，大运或流年的天干出现丁，应期怎么论？","opts":["丁代表戌，丁的作用相当于戌","丁只代表丁本身","丁生戌，论生不论代","丁入戌墓，论墓者主收"],"ans":0,"exp":"遁藏透干：地支中有遁藏的天干，流年或大运天干出现这个遁藏之干，就是该地支的应期。","sec":"三、遁藏透干应期","t":"calc"},{"q":"原局有辰，流年天干见乙，乙可代表哪个地支？","opts":["丑","辰","未","卯"],"ans":1,"exp":"辰中遁藏乙、癸，所以乙、癸透干可代辰；寅遁藏丙、甲（戊也行）。","sec":"三、遁藏透干应期","t":"calc"},{"q":"原局本来有合，流年要以什么作用为应？","opts":["穿","墓","冲","合"],"ans":2,"exp":"口诀：原局有合以冲为应，原局有冲以合为应。","sec":"四、岁运作用应期","t":"diff"},{"q":"流年冲大运，怎样分「冲去」和「冲起」？","opts":["吉运为冲去，凶运为冲起","当运为冲起，不当运为冲去","旺神为冲起，弱神为冲去","当运为冲去，不当运为冲起"],"ans":3,"exp":"流年冲大运，看当运不当运：当运为冲去，不当运为冲起。","sec":"四、岁运作用应期","t":"diff"},{"q":"局中本弱的字，被流年旺神来冲，应的是什么？","opts":["冲而破，不是动意","冲而合，必定转吉","冲而起，被冲者得力","冲而动，必应喜事"],"ans":0,"exp":"局中本弱，旺神来冲是冲而破；局中本旺，逢流年冲才是动的应期。","sec":"四、岁运作用应期","t":"diff"},{"q":"走天干大运时，体与用怎么分？","opts":["天干为体、地支为用","地支为体、天干为用","天干地支都是体","天干地支都是用"],"ans":1,"exp":"走天干运，地支为体、天干为用；走地支运，天干为体、地支为用。用＝动态起作用，体＝静态被控制。","sec":"五、大运体用的应期","t":"rule"}],"fine":[{"q":"在盲派断命体系中，八字、大运与流年三者的分工依次是什么？","opts":["八字定格局，大运定旺衰，流年看喜忌","八字讲吉凶，大运看应期，流年讲贵贱","八字讲贵贱，大运讲吉凶，流年看应期","八字看应期，大运讲贵贱，流年讲吉凶"],"ans":2,"exp":"先用八字原局定贵贱高低，再用大运定吉凶趋势，最后由流年点出具体发生事情的年份。","sec":"应期","t":"rule"},{"q":"按盲派大限规则，年柱、月柱、时柱各自管辖的年龄段依次是？","opts":["1–18 岁、18–40 岁、55 岁以后","1–16 岁、16–32 岁、50 岁以后","1–20 岁、20–35 岁、60 岁以后","1–18 岁、18–35 岁、55 岁以后"],"ans":3,"exp":"四柱大限分别为：年柱 1–18 岁，月柱 18–35 岁，日柱（日支）35–55 岁，时柱 55 岁以后。","sec":"1. 柱与年龄","t":"rule"},{"q":"大限应吉，但所行大运却凶，按“交脱诀”应期怎么论？","opts":["此运不应吉，过运则吉","此运照样应吉，过运则凶","吉凶相抵，永远不再应吉","此运先应凶，过运也应凶"],"ans":0,"exp":"大限与大运是一吉一凶的“与”关系，吉凶互相抵消，事情往后推到过运才应吉。","sec":"2. 大限与大运的关系","t":"rule"},{"q":"大限与大运的关系类似逻辑中的“与”关系，必须满足什么条件才应事？","opts":["大限吉大运凶则以大限为主，照样应吉","大限与大运都吉才应吉，都凶才应凶","大限凶大运吉则以大运为主，永久免凶","只要大限吉或大运吉，其中之一吉就应吉"],"ans":1,"exp":"一吉一凶则互相抵消，事情推到过运；唯有大限与大运同吉才应吉，同凶才应凶。","sec":"2. 大限与大运的关系","t":"rule"},{"q":"坤造乙甲丁辛／卯申亥亥，月令官星很旺本该早婚，为何丙戌运结不了、丁运甲申年才结婚？","opts":["申亥相穿在戌运最强，过运穿解才婚","丙火劫财夺官，到甲申年才生出官星","戌为伤官去官使大运凶，过戌运则吉","月令大限只管 1–18 岁，未到婚龄"],"ans":2,"exp":"月柱大限 18–35 岁应吉，但丙戌运戌为伤官去官属凶运，故此运不婚；一过戌运，丁运甲申年即婚。","sec":"2. 大限与大运的关系","t":"calc"},{"q":"坤造辛乙辛庚／丑未酉子，一岁丧母、而丧父在戊运丙辰年（月柱大限内），依据是什么？","opts":["子水冲丑土坏了母宫，未土生酉金护住父星","丑未相冲先把年柱冲坏，再冲月柱乙木","年干辛金虚透克母，时干庚金旺相克父","辛酉遇丑即入墓主母早丧，乙坐未墓主父应月限"],"ans":3,"exp":"辛酉一柱见丑即入墓，故母亲极早在一岁去世；乙木父星在月令坐未墓且遭子穿，落在 18–35 岁大限丧父。","sec":"2. 大限与大运的关系","t":"calc"},{"q":"甲、乙、丙、丁四个天干的禄（原身）依次是哪四个地支？","opts":["寅、卯、巳、午","卯、寅、巳、午","寅、辰、巳、未","寅、卯、午、巳"],"ans":0,"exp":"阳干禄在前、阴干禄在后：甲禄寅、乙禄卯、丙戊禄巳、丁己禄午。","sec":"二、禄与原身应期","t":"calc"},{"q":"在盲派应期规则中，“见禄代表原身，见原身代表禄”这条规则的适用优先级如何？","opts":["只在天干透出时有效，地支见禄无效","具有优先性，见之即按该字应期论","只适用于日主本身，不适用于财官十神","仅作辅助参考，须先看五合六合再论"],"ans":1,"exp":"八字中某字在岁运出现，或见其禄神与原身，皆为该字应期，且“见禄代原身、见原身代禄”具有优先性。","sec":"二、禄与原身应期","t":"rule"},{"q":"坤造戊壬甲丙／申戌子寅，申子合局，为何结婚在壬申年、婚姻出问题在己未运丙子年？","opts":["壬申年合住戌土财星，丙子年子水克丙火","壬申年冲动寅木禄神，丙子年寅木生火泄夫","壬申年夫星到合夫宫，丙子年夫宫出现又见未穿","壬申年水旺生木为喜，丙子年火水相战为忌"],"ans":2,"exp":"申为夫星、子为夫宫，壬申年夫星出现拱入夫宫而婚；己未运未穿子，丙子年夫宫子水到流年受穿而婚变。","sec":"二、禄与原身应期","t":"calc"},{"q":"坤造庚辛辛癸／寅巳酉巳，行丙子运壬午年被歹徒杀害，核心应期机理是什么？","opts":["酉金禄神在子运逢死地，午年火旺克金","寅巳穿在午年加重，木火焚尽庚辛比劫","丙子运丙辛合化水，午年水火激战克身","子运癸落支受克泄，午年午冲子坏尽食神"],"ans":3,"exp":"局中禄坏而食神癸水为要，子运癸落入地支反被巳绝寅泄，壬午年午冲子坏了食神（穿倒食神，死不在枕头上）。","sec":"二、禄与原身应期","t":"calc"},{"q":"戊土在寅为长生，同样是戊日主，见“甲寅”时与见“乙卯”时在吉凶上有何区别？","opts":["见甲寅时论吉（甲不克戊），见乙卯时论凶","甲寅为假杀论平，乙卯为真官当财看论吉","甲寅与乙卯皆为官杀旺地，一律按克身论凶","见甲寅时七杀攻身论凶，见乙卯时正官论吉"],"ans":0,"exp":"戊土长生在寅，寅木杀当财看，甲不克戊故戊日见甲寅时论吉；而见乙卯时正官克身无生情，反论凶。","sec":"二、禄与原身应期","t":"diff"},{"q":"乾造乙己甲庚／巳卯戌午，大老婆在乙酉年因心脏病复发去世，其命理应期是什么？","opts":["己土为大老婆，乙酉年乙木克己土而去世","戌坐妻宫得正位为大老婆，乙酉年酉戌穿坏戌","巳火为大老婆，乙酉年巳酉合走而去世","卯木为大老婆，乙酉年卯酉冲破而去世"],"ans":1,"exp":"局中巳午戌己皆为妻象，戌坐日支妻宫得正位为大老婆，流年乙酉形成酉戌穿，穿坏戌土引动心脏病。","sec":"二、禄与原身应期","t":"calc"},{"q":"按遁藏透干应期，原局地支有“寅”，岁运天干出现哪些字可以代表寅？","opts":["甲、乙、丙","丙、丁、戊","丙、甲（戊也可）","甲、壬、庚"],"ans":2,"exp":"寅中遁藏甲、丙、戊，故岁运天干见丙、甲（戊也行）透出时，即可代表原局的寅木发生作用。","sec":"三、遁藏透干应期","t":"calc"},{"q":"反过来推算，当岁运天干出现“乙”时，它依次可代表原局地支的先后次序是什么？","opts":["先辰、再未、最后卯","先未、再卯、最后辰","只代表卯与辰，不代表未","先卯、再未、最后辰"],"ans":3,"exp":"乙木禄在卯为最优先，其次未中藏乙为木库，最后辰中亦遁藏乙木，故有“先卯、再未、最后辰”的先后次序。","sec":"三、遁藏透干应期","t":"calc"},{"q":"乾造丁庚己庚／亥戌巳午，火燥土制亥水大贵，为何行甲辰运之甲运兵败大凶？","opts":["甲到即亥到，亥中甲木旺透反合日主","甲木克去己土，导致日主根基全无","甲木生旺丁火，火炎土燥而自焚","庚金被甲木耗尽，伤官无法泄秀"],"ans":0,"exp":"亥中含甲木官星（对手），原局制之；甲运甲透即亥到，要制之官星不仅制不住，反透干合身制日主。","sec":"三、遁藏透干应期","t":"calc"},{"q":"乾造乙己壬辛／巳丑辰丑，丙戌运之戌运大发数亿，为何到乙酉运之乙运反坐牢没收财产？","opts":["戌运刑开丑库取财，乙运乙己相克坏了官星","戌冲辰开财库，乙代辰透干被辛克坏兼闭库","戌运火土相生旺身，乙运木泄水气致身弱","戌运冲走丑土忌神，乙运合住庚金救出忌神"],"ans":1,"exp":"辰戌冲开财库发大财；到乙运时，乙代辰透干被原局辛金克坏，等于坏了主位辰库，且辰酉合闭库致牢狱破产。","sec":"三、遁藏透干应期","t":"calc"},{"q":"坤造辛壬庚戊／亥辰寅寅，丙申运丙火虚透离异，应期在辛巳年（或甲申年）的原因是？","opts":["丙火为伤官克官，巳年禄旺、申年长生克夫","戊土偏印透出，巳年冲亥、申年合辰破婚","丙代寅且合辛，巳穿寅、申穿亥皆引动寅亥合","辛金劫财透干夺夫，巳申合把寅木合走"],"ans":2,"exp":"寅中丙火为夫星坐正位，被亥合走；丙运丙代寅且合劫财辛，辛巳年巳穿寅、甲申年申穿亥，皆引动原局寅亥合。","sec":"三、遁藏透干应期","t":"calc"},{"q":"盲派岁运作用口诀“合者主到，冲者主动”之后，“墓者”与“穿者”分别主什么？","opts":["墓者主死，穿者主冲","墓者主藏，穿者主合","墓者主散，穿者主破","墓者主收，穿者主伤"],"ans":3,"exp":"岁运与八字发生合、冲、墓、穿时：合者主到，冲者主动，墓者主收，穿者主伤。","sec":"1. 作用的含义","t":"rule"},{"q":"以流年与大运的旺衰对比论冲，“旺者冲旺”与“旺者冲衰”分别称为什么？","opts":["旺者冲旺为冲起，旺者冲衰为冲去","旺者冲旺为冲破，旺者冲衰为冲动","旺者冲旺为冲散，旺者冲衰为冲合","旺者冲旺为冲去，旺者冲衰为冲起"],"ans":0,"exp":"流年冲大运，当运（旺）为冲去，不当运（衰）为冲起；即旺者冲衰为冲去，旺者冲旺为冲起。","sec":"1. 作用的含义","t":"diff"},{"q":"在应期作用规律中，“弱神冲旺神”通常应什么结果？","opts":["冲而不动，旺神毫无反应","冲而应合，动旺神而克伤其所克之字","冲而化合，弱神直接变成旺神之党","冲而应破，弱神当场被旺神冲散"],"ans":1,"exp":"弱神冲旺神是“冲而应合”：冲能激怒并引动旺神，旺神一动，必去克伤它所克的东西。","sec":"1. 作用的含义","t":"rule"},{"q":"关于“活木怕埋根之铁”，原局有几个根时“不可坏根”，有几个根时“可坏”？","opts":["三个根不可坏根，两个根可坏","只要见金都会坏根，不论根数多少","两个根不可坏根，一个根可坏","一个根不可坏根，两个根可坏"],"ans":2,"exp":"有两个根就有了生命，不可坏根（坏之则凶）；只有一个根则可坏（坏之反而论去），木如此，其他五行亦如此。","sec":"1. 作用的含义","t":"rule"},{"q":"坤造癸甲癸癸／巳子卯亥，行己巳运伤官合杀，为何戊寅、己卯年未掌权，反在庚辰年掌权？","opts":["戊寅、己卯年木旺克土，庚辰年土旺制水","庚辰年印星生身，方能担起伤官合杀","辰土为水库，把癸水比肩收进库中不争权","原局有合而庚辰冲动，属“合而应冲”"],"ans":3,"exp":"己巳运己合甲本为掌权之象，但原局有合须待冲动，庚辰年辰冲戌（或冲动）应了“合而应冲”，故该年掌权。","sec":"2. 命例","t":"calc"},{"q":"乾造癸乙甲乙／丑丑子亥，癸未年失了工作却得一万元意外收入，其应期机理是？","opts":["印虚被穿失工作，未冲丑引发财动促合","乙木羊刃见未入库，制住七杀而得偏财","亥未拱木帮身，比劫夺财反得意外之财","未土财星透干，把子水印星合化成财"],"ans":0,"exp":"癸水坐下印虚透又遭子未穿坏，故丢工作；但未冲丑使丑财动，促成子丑合，谓之“财动促合”，故得意外财。","sec":"2. 命例","t":"calc"},{"q":"走“地支大运”时，大运干支的体用如何划分，体与用各自代表什么状态？","opts":["天干为用神，地支为忌神，体用不变","天干为体（静态被控制），地支为用（动态起作用）","天干地支皆为用，同时动态起作用","地支为体（静态被控制），天干为用（动态起作用）"],"ans":1,"exp":"走天干运时干用支体；走地支运时则反过来，天干为体（固定、被控制），地支为用（动态起作用）。","sec":"五、大运体用的应期","t":"diff"}]},{"n":55,"level":"中级","title":"干支类象与神煞类象","qs":[{"q":"珠宝、玉器、钻石、乐器，这组类象属于哪个天干？","opts":["癸","己","庚","辛"],"ans":3,"exp":"辛为月、金子、珠宝、玉器、钻石、乐器，形致密；庚是顽铁、铁器、利器、五金，形棱角。","sec":"一、十天干类象","t":"xiang"},{"q":"辛酉日主见丑，与辛丑日主，按盲派有何不同？","opts":["辛酉见丑阴见阴又入墓，是黑社会；辛丑浊中见清不是","两者都是黑社会，丑酉都主犯罪","辛丑见丑阴见阴又入墓，是黑社会；辛酉不是","两者都不是，丑酉与犯罪无关"],"ans":0,"exp":"多数丑酉与犯罪、黑社会有关；辛酉见丑是阴见阴又入墓，辛丑日主则是浊中见清，人性是好的。","sec":"二、十二地支类象","t":"diff"},{"q":"阳木遇火、阴木遇火，各主什么行业象？","opts":["阳木遇火为纺织，阴木遇火为家具","阳木遇火为家具，阴木遇火为纺织","阳木遇火为冶炼，阴木遇火为家具","阳木遇火为家具，阴木遇火为冶炼"],"ans":1,"exp":"甲木分死活，死木遇火为家具；阴木（乙）遇火为纺织、服装。火克金才是冶炼。","sec":"三、六十干支类象","t":"rule"},{"q":"禄神配印与不配印，主什么不同？","opts":["禄配印为辛苦，禄不配印为享受","禄配印不配印都辛苦","禄配印为享受，禄不配印为辛苦","禄配印不配印都享受"],"ans":2,"exp":"禄印相随表享受（偏懒）；禄不配印则要自己亲为做事，主辛苦。","sec":"1. 禄神","t":"diff"},{"q":"女命禄合到什么才算「禄绊桃花」？","opts":["只有合到食神才算，其余都不算","合到什么都算桃花，没有例外","合到印或夫妻宫才算；合到官杀、财不算","合到伤官、官杀或财；合到印或夫妻宫不算"],"ans":3,"exp":"女人的禄合到伤官、官杀、财为禄绊桃花，禄逢三合也是桃花；合到夫妻宫不为桃花，合到印不算桃花。","sec":"1. 禄神","t":"rule"},{"q":"甲、丙、庚、辛日主，哪一个没有羊刃？","opts":["辛","丙","庚","甲"],"ans":0,"exp":"只有阳干有羊刃（甲刃卯、丙刃午、庚刃酉），阴干如辛没有羊刃。","sec":"2. 羊刃","t":"calc"},{"q":"羊刃有制与无制，分别用正还是用偏？","opts":["有制无制都用正，只看刃的强弱","有制用正，如军警；无制用偏，如匪徒","有制用偏，如匪徒；无制用正，如军警","有制无制都用偏，只看刃的强弱"],"ans":1,"exp":"羊刃喜制服：制之得用正，可做军人、警察、执法人员、外科大夫、运动员；无制则用偏，可能是匪徒、赌徒。","sec":"2. 羊刃","t":"rule"},{"q":"墓库按所收藏的十神取象，伤官、食神库是什么象？","opts":["军团、营地","权力中心、组织部门","寺庙、学校","银行"],"ans":2,"exp":"羊刃库为军团营地，伤官食神库为寺庙学校，财库为银行，官杀库为权力中心、组织部门。","sec":"3. 墓库","t":"xiang"},{"q":"日支为卯，盲派的驿马在哪几个字？","opts":["申、子、辰","寅、午、戌","亥、卯、未","巳、酉、丑"],"ans":3,"exp":"盲派驿马：亥卯未见巳酉丑为马；申子辰见寅午戌、寅午戌见申子辰、巳酉丑见亥卯未，以年日为主查。","sec":"4. 驿马","t":"calc"},{"q":"日柱为壬申，按六甲空亡，空的是哪两个字？","opts":["戌、亥","午、未","辰、巳","申、酉"],"ans":0,"exp":"壬申在甲子旬（甲子到癸酉十日），这十天中无戌亥二字，所以戌亥逢空。","sec":"5. 空亡","t":"calc"},{"q":"关于空亡对吉凶的影响，下列哪条对？","opts":["凶星空亡凶加倍，吉神空亡福更足","凶星空亡凶减半，吉神空亡福不全","凶星空亡全无凶，吉神空亡福加倍","凶星吉神空亡都不受影响"],"ans":1,"exp":"空亡是有其气无其形、有其名无其实：凶星空亡凶减半，吉神空亡福不全。","sec":"5. 空亡","t":"rule"}],"fine":[{"q":"十天干的“形”各有特点，下列哪组对应完全正确？","opts":["甲直乙曲，丙方丁平，戊大己小","甲曲乙直，丙小丁大，戊平己方","甲棱角乙致密，丙大丁小，戊圆润己方","甲直乙曲，丙大丁小，戊方己平"],"ans":3,"exp":"十天干形象对比：甲直乙曲、丙大丁小、戊方己平、庚棱角辛致密、壬无规则癸圆润。","sec":"一、十天干类象","t":"xiang"},{"q":"丙火与丁火在文化、名望与性格象义上各有侧重，属于“丁火”的是哪一组？","opts":["星光、灵光、玄学、神学、多思神秘","闪电、高楼、公门首领、宽仁磊落","光芒、城门、剧场演说、正面体恤","太阳、帝王、影视传媒、激情豪放"],"ans":0,"exp":"丙为太阳、帝王、影视传媒与演说，形大；丁为星光、灯火、玄学、神学、文字内心，形小。","sec":"一、十天干类象","t":"diff"},{"q":"戊土与己土在物象与人性上如何区分？","opts":["戊主田园墓地农业多疑，己主高坡政府建筑忠厚","戊主山丘政府建筑老成，己主田园房屋粉尘谨慎","戊主顽铁五金刚强，己主珠宝首饰灵动","戊主江河航运任性，己主雨露泉水聪明"],"ans":1,"exp":"戊为大地、高坡、政府、建筑、古董，性忠厚老成、形方；己为田园、房屋、墓地、粉尘，性含蓄谨慎、形平。","sec":"一、十天干类象","t":"diff"},{"q":"同属水行，壬水与癸水在职业、人体与形状上的区别是？","opts":["壬主雨露玄学骨髓圆润，癸主大海航运口舌无规则","壬主井泉池塘温柔，癸主江河石油暴躁","壬主江河航运血液无规则，癸主雨露玄学肾精圆润","壬主肺与大肠棱角，癸主心与小肠致密"],"ans":2,"exp":"壬为大海江河、航运贸易、石油、血液，形无规则；癸为雨露泉水、墨、玄学、肾脏骨髓经血，形圆润。","sec":"一、十天干类象","t":"diff"},{"q":"十二地支按五行分阴阳（木火阳、金水阴）时，哪两个地支分别属于“阳中阴”和“阴中阳”？","opts":["寅为阳中阴，申为阴中阳","巳为阳中阴，亥为阴中阳","丑为阳中阴，未为阴中阳","辰为阳中阴，戌为阴中阳"],"ans":3,"exp":"寅卯辰巳午未属木火为阳，申酉戌亥子丑属金水为阴；其中辰为阳中阴，戌为阴中阳。","sec":"1. 阴阳的三种定义","t":"rule"},{"q":"十二地支按遁藏分阴阳时，为何“丑、酉”被称为纯阴（阴中之阴），而亥、子不是？","opts":["丑酉纯阴无阳干，亥阴位中含阳、子阴却位在阳","亥子属水为真阳，丑酉属土金为极阴","丑酉在天干透出辛金，亥子透出壬癸皆为阳","丑酉位于阳宫却藏阴，亥子位于阴宫却藏阳"],"ans":0,"exp":"丑中癸辛己、酉中辛，皆纯阴之物；亥虽在阴位但中含甲阳，子虽为阴但位居阳位，故亥子非阴中阴。","sec":"1. 阴阳的三种定义","t":"diff"},{"q":"在社会风气与场所类象中，戌土与丑土在“乱”的象义上有何不同？","opts":["戌与丑皆主阳乱，专指闹市歌舞场所","戌是阳乱（如歌厅），丑是阴乱（如私情淫乱）","戌是阴乱（如私情），丑是阳乱（如赌场）","戌主牢狱不主乱，只有丑酉才主淫乱"],"ans":1,"exp":"戌为燥土、闹市歌舞色情之地，属阳乱；丑为黑暗隐蔽、地下室与纯阴之物，属阴乱。","sec":"1. 阴阳的三种定义","t":"diff"},{"q":"在学业文理与学科的快速判断中，木火、金水、戌亥、辰见子依次主什么？","opts":["理科、文科、化学、数学","数学、化学、法律、金融","文科、理科、数学、化学","文科、理科、外语、物理"],"ans":2,"exp":"木火主文，金水主理；戌亥为计算运算表数学；辰见子为化学；丑主玄学。","sec":"2. 学业文理与职业的快速判断","t":"xiang"},{"q":"关于职业与语言的快速判断，下列说法完全准确的是哪一项？","opts":["酉主金融而申不主金融，月令与门户皆主外语","申酉皆主金融与法律，月令主外语、门户主国语","申酉只主军警不主法律，戌亥主外语、辰主国语","申酉主法律而仅申主金融，月令主国语、门户主外语"],"ans":3,"exp":"申酉同主法律，但申代表金融、酉不代表金融；月令表国家故国语好，门户（时柱）表远方故外语好。","sec":"2. 学业文理与职业的快速判断","t":"diff"},{"q":"坤造己戊甲癸／卯辰辰酉，命主职业为导游，这一判断主要依据哪组地支类象？","opts":["辰为车与走动，酉在门户主远方，辰酉合表到处走","辰为大机构，甲木为首领，辰卯穿主带队出行","卯为街道门窗，癸水主航运贸易，卯酉冲表出差","戊土主山丘高坡，己土主田园旅游，戊己混杂主奔波"],"ans":0,"exp":"辰有运动、车与走动之意，酉在门户主远方，辰酉合就是合着车到处走动，故断导游。","sec":"4. 命例","t":"xiang"},{"q":"十二地支中，同时包含“医院、西医、司法、金融、道路、车辆、硬物”类象的是哪个地支？","opts":["酉","申","辰","戌"],"ans":1,"exp":"申对应铁器硬物、兵戈军队、司法、金融、医院西医、道路车辆、矿物矿厂；酉不主金融与西医。","sec":"3. 十二支类象总表","t":"xiang"},{"q":"在六十干支自身象中，丁丑、甲申、辛未、己卯依次对应什么象？","opts":["玄学、肺与大肠、珠宝首饰、花木","建筑物、高楼、水泥墩子、种子","盲派、脊椎颈椎、大蒜辣椒、幼苗豆芽","盲派、大蒜辣椒、脊椎颈椎、水泥墩子"],"ans":2,"exp":"干支自身象：丁丑主盲派，甲申主脊椎颈椎，辛未主大蒜辣椒，己卯主幼苗豆芽种子，乙未为建筑物，戊戌为水泥墩子。","sec":"1. 自身象与口诀","t":"xiang"},{"q":"在干支组合取象中，眼睛须由哪两个天干相配而成？若其中水被烤干会如何？","opts":["丙配壬（丙眼珠壬眼眶），壬水枯竭则眼盲","甲配辛（甲眼眶辛眼珠），辛受克则失明","丁配壬（丁眼眶壬眼珠），壬被烤干则近视","丙配癸（丙眼眶癸眼珠），癸被烤干则眼盲"],"ans":3,"exp":"丙配癸才算眼睛：丙为眼眶，癸为黑、为眼珠（瞳孔）；癸水被火烤干耗尽则眼盲。","sec":"1. 自身象与口诀","t":"xiang"},{"q":"坤造癸癸甲丁／丑亥寅卯，丁丑年整容（毁容后补肉）且没有性命之忧，命理依据是？","opts":["癸冲丁、甲遇丁为灭主毁容，甲寅之体未伤故不死","丁丑为盲派贵人星，逢冲反主改头换面之喜","丁火被癸水熄灭主破财，丑土生金护身故不死","寅卯木旺化水生火，只是皮肤受伤而非内脏之疾"],"ans":0,"exp":"甲为头、丁为脸，两癸冲丁且甲遇丁为灭，故主毁容整容；但日主甲寅之体未受伤，故未死。","sec":"三、六十干支类象","t":"calc"},{"q":"关于戊、己、庚、辛的干支类象，下列说法不正确的是哪一项？","opts":["辛金配癸水组合为金水伤官，主漂亮","庚金系弱喜极旺，最喜厚土埋金","辛金取财为五金行业，火克金为冶炼行业","戊为建筑，己为身体（女命则曲线弯、性感）"],"ans":1,"exp":"教材明确指出“庚金系弱不喜旺”，其余三项（戊建筑、己身体性感、辛癸金水伤官及五金冶炼）均正确。","sec":"1. 自身象与口诀","t":"xiang"},{"q":"盲派认为传统神煞应验率不高，在实际测命中只讲哪五个神煞？","opts":["天乙贵人、驿马、桃花、空亡、羊刃","禄神、羊刃、天德、月德、墓库","禄神、羊刃、墓库、驿马、空亡","禄神、亡神、驿马、空亡、华盖"],"ans":2,"exp":"盲派只讲禄神、羊刃、墓库、驿马、空亡五个；其中禄、刃、墓严格说是十干本气与墓气。","sec":"四、神煞类象","t":"rule"},{"q":"盲派中“禄神”的本质含义是什么？在人体类象上主什么？","opts":["日主的官杀与威严，主脾胃、肌肉与皮肤","日主的印绶与贵人，主牙齿、骨骼与肺部","日主的财库与祖业，主头面、头发与肝脏","日主延伸至地支行权，主身体、女命肉体与寿命"],"ans":3,"exp":"禄是日主的延伸，代表日主到地支行使权力；心性主亲为独占，人体主身体、肢体、女人的肉体与寿命。","sec":"1. 禄神","t":"xiang"},{"q":"坤造丁己辛辛／未酉丑卯，为何比较懒惰享受？若将日支“丑”改为“辰”会怎样？","opts":["禄印相随故懒；改辰则辰酉合印更懒，且不算桃花","辛金日主自坐墓库故懒；改辰则辰酉合绊桃花","卯酉冲禄故懒；改辰则辰卯穿，变得极度辛苦","丁火七杀受制故懒；改辰则水库冲未，奔波劳碌"],"ans":0,"exp":"禄印相随表有福气、懒惰享受，原局卯酉冲还在做事；若改辰则辰酉合印更懒，且合到印不算禄绊桃花。","sec":"1. 禄神","t":"calc"},{"q":"同为戊日主见丁未与时支巳印，为何“丁辛戊丁／未亥子巳”断半个皇帝，而“癸丙戊丁／未辰申巳”为伪政府？","opts":["前者亥子水旺为真财，后者申辰拱水被丙火耗尽","丁坐未为半个禄有继承性，后者丁未上盖癸水反了","前者月日水旺冲巳，后者辰土晦火灭禄","前者丁火两透无伤，后者丙火夺丁火之光"],"ans":1,"exp":"戊见年上或时上巳印有继承性，丁坐未为半个禄；后者虽也是半个天下，但上盖癸水克丁反了，故为伪政府。","sec":"1. 禄神","t":"calc"},{"q":"按盲派羊刃表，甲、丙、戊、庚、壬五阳干的羊刃地支依次是？","opts":["卯、午、巳、酉、子","寅、巳、午、申、亥","卯、午、未、酉、子","卯、巳、未、酉、亥"],"ans":2,"exp":"盲派羊刃表：甲刃卯（或乙）、丙刃午（或丁）、戊刃未（或巳）、庚刃酉（或辛）、壬刃子（或癸）。","sec":"2. 羊刃","t":"calc"},{"q":"在盲派取象中，羊刃与劫财在投资或动作上共同含有什么象义？","opts":["都有保守储蓄、只进不出之义","都有务虚玄学、清高超脱之义","都有远行迁移、驿马奔忙之义","都有炒作的意思，有操手之义"],"ans":3,"exp":"羊刃主刀枪手术、执法武装、四肢身体；且劫与刃都有炒作的意思，有操手之义。","sec":"2. 羊刃","t":"xiang"},{"q":"墓库按所收藏十神取象，羊刃库、财库、官杀库依次对应什么场所或机构？","opts":["军团营地、银行、权力中心与组织部门","寺庙学校、证券所、法院监狱","银行、军团营地、寺庙学校","矿井地下室、银行、医院"],"ans":0,"exp":"羊刃库为军团营地（军队警察），伤食库为寺庙学校，财库为银行，官杀库为权力中心、组织部门。","sec":"3. 墓库","t":"xiang"},{"q":"盲派驿马查法以哪两柱为主？若驿马逢合，在状态上怎么论？","opts":["以年柱和月柱为主，逢合则化为财星","以年柱和日柱为主，逢合则停留不动","只以日柱为主，逢合则出远门迁移","以月柱和时柱为主，逢合则奔波加剧"],"ans":1,"exp":"盲派驿马以年柱和日柱为主（日柱尤其明显），见他支或岁运即为驿马；驿马主走动远行，逢合则停留不动。","sec":"4. 驿马","t":"rule"},{"q":"按六甲空亡表，甲戌旬、甲申旬、甲辰旬各自空亡的地支依次是？","opts":["午未、辰巳、寅卯","申酉、辰巳、子丑","申酉、午未、寅卯","戌亥、申酉、子丑"],"ans":2,"exp":"六甲空亡依次为：甲子旬戌亥、甲戌旬申酉、甲申旬午未、甲午旬辰巳、甲辰旬寅卯、甲寅旬子丑。","sec":"5. 空亡","t":"calc"},{"q":"关于天干、大运、流年与五行空亡的规则，下列哪一项表述正确？","opts":["只有地支讲空亡，天干与大运绝对不讲空亡","流年也讲空亡，且流年空亡比原局更重","五行空亡中，水空则陷、土空则流、火空则灭","天干大运可讲空亡（仅作象），流年不讲空亡"],"ans":3,"exp":"天干也可讲空亡，大运来了也算空亡（做功无印象，只是一种象），流年不讲空亡；五行空亡为金鸣、火发、水流、木朽、土陷。","sec":"5. 空亡","t":"rule"}]},{"n":56,"level":"中级","title":"宫位类象与十神类象","qs":[{"q":"按盲派，丈母娘到哪里找？","opts":["年上，与妻宫有关联的印、伤食","时上，与妻宫有关联的官杀","月上，与妻宫有关联的财星","日支，与妻宫同柱的印星"],"ans":0,"exp":"年上表外戚，和妻宫发生关联的印、伤食都是丈母娘；若与妻宫无关，出现伤则可能是奶奶。","sec":"1. 六亲与人物","t":"rule"},{"q":"按盲派，买车、车祸应主要看哪个宫位？","opts":["月支（月柱）","时支（时柱）","日支（日柱）","年支（年柱）"],"ans":1,"exp":"时为门户，出门的代步工具车子在时柱上看，买车、车祸均看时支。","sec":"1. 六亲与人物","t":"rule"},{"q":"天干与地支在表里上各代表什么？","opts":["天干表家里事，地支表外人交往","天干表过去，地支表未来","天干表外在表象，地支表内心与家人","天干表内心与家人，地支表外在表象"],"ans":2,"exp":"天干代表外表、性格表象及与外人交往；地支代表内心世界、与家人关系和隐蔽的心志。","sec":"8. 表里类象","t":"diff"},{"q":"某人命中出现的字落在年柱，按盲派身体类象，最可能对应哪个部位？","opts":["头、面、手、眼、口","胸部、五脏、心脑","躯干、脊、肩、背","腿、足、四肢"],"ans":3,"exp":"年柱离日柱最远，代表腿足四肢；月柱为躯干，日支为五脏心脑，时柱为头面手窍。","sec":"5. 身体类象","t":"calc"},{"q":"按盲派，正偏财分别表示什么？","opts":["表示人对钱财的心性，不是来源正偏","正财表工资，偏财表一切横财","正财是男命妻子，偏财是男命情人","表示钱财的来源是正当还是偏门"],"ans":0,"exp":"正偏财不表示财的来源，而表示人对钱财的心性；来源要看比劫做功与否。","sec":"3. 财","t":"rule"},{"q":"七杀在盲派里怎么区分吉凶？","opts":["见印则吉，见财则凶","有制化显吉的一面，无制化显凶","身旺则吉，身弱则凶","透干则吉，藏支则凶"],"ans":1,"exp":"七杀为凶神，有制化则显吉的一面，无制化则显凶的一面（匪徒、病人）。","sec":"2. 官杀","t":"rule"},{"q":"伤官与食神在情感上有什么区别？","opts":["伤食都专一，只是强弱有别","伤专一用情，食玩乐不专一","伤偏玩乐不专一，食正专一用情","伤食都不专一，只是对象不同"],"ans":2,"exp":"伤偏、食正：伤想象丰富不受约束、感情不专一；食专一专注用情，是付出型。","sec":"5. 食伤","t":"diff"},{"q":"按盲派的基本原则，男命、女命看子女分别怎么取？","opts":["男命官为儿杀为女；女命食为儿伤为女","男女都以食伤看子女，伤为儿食为女","男命食为儿伤为女；女命官为儿杀为女","男命杀为儿官为女；女命伤为儿食为女"],"ans":3,"exp":"基本原则男命以杀为儿、官为女，女命以伤为儿、食为女；通变要看财。","sec":"1. 子女","t":"rule"},{"q":"看儿女时，宫位先后次序怎么排？","opts":["日支、时支、时干、月支……年干","时干、时支、日支、月支……年干","日支、月支、年支，最后看时柱","年干、年支、月干、月支……日支"],"ans":0,"exp":"从日支开始，再时支、时干，再月支、月干，最后年支、年干。","sec":"1. 子女","t":"rule"},{"q":"按盲派，看六亲中的父母，怎样取星？","opts":["财官杀为母，食伤禄为父","财官杀为父，食伤禄为母","印为父，比劫为母","财为母，官杀为父"],"ans":1,"exp":"正偏财为父，官杀也为父；食、伤、禄为母；印是父母星，两个都表示。","sec":"2. 父母","t":"rule"},{"q":"劫财在盲派里怎么论吉凶？","opts":["必凶，只会夺财","见印则助，见官则争","有功用助我得财，无功用破财","身弱则吉，身旺则凶"],"ans":2,"exp":"劫为凶神，有功用可助我得财，无功用反致我破财遭灾。","sec":"4. 比劫","t":"rule"},{"q":"盲派看左右，阴阳怎么对应？","opts":["阳为右，阴为左","年月为左，日时为右","天干为左，地支为右","阳为左，阴为右"],"ans":3,"exp":"阳为左、阴为右；如丙阳比劫在年为腿，表左腿残疾。","sec":"3. 左右","t":"rule"}],"fine":[{"q":"年上与妻宫发生关联的食神与伤官都可看作丈母娘，二者在感情上有何区别？","opts":["伤官无感情，食神重感情；无关妻宫则伤可能是奶奶","食神无感情，伤官重感情；无关妻宫则食可能是奶奶","伤官食神感情同样深厚，只是年龄大小有别","只有正印才是丈母娘，伤食一律只论奶奶或婆婆"],"ans":0,"exp":"年上表外戚，和妻宫关联的印、伤食都是丈母娘；伤无感情、食重感情；若与妻宫无关，伤则可能是奶奶。","sec":"1. 六亲与人物","t":"diff"},{"q":"在四柱人物类象中，若夫妻星或夫妻象出现在“月柱”，配偶很可能是哪类人？","opts":["街头偶遇的陌生人或网友","同学、同事、老乡或同单位之人","学生、晚辈或下属之人","远方海外之人或长辈亲戚"],"ans":1,"exp":"月柱主同学、同事、老乡、领导；若夫妻象出现在月上，配偶可能是同学或同事。","sec":"1. 六亲与人物","t":"xiang"},{"q":"乾造癸丙丙甲／卯辰午午，主“右腿残疾，小儿麻痹”的命理依据是什么？","opts":["月支辰土晦火，导致左侧躯干与肩背不适","日柱丙午伏吟，火炎土燥伤及头部与眼睛","主位午火比劫破年上卯（年为腿、卯阴为右）","年干癸水克丙火，导致心脏与血液受阻"],"ans":2,"exp":"必须是主位（日）与年上的字相破才表自己控制不住：比劫午破年上卯，年主腿足、卯为阴主右，故右腿残疾。","sec":"1. 六亲与人物","t":"calc"},{"q":"坤造辛庚庚己／亥子寅卯，癸卯运丁丑年车被抢，为何戊寅年能找回且身体无伤？","opts":["丑土为车库把卯木收走，寅年寅亥合把车子赎回","原局庚金劈甲引丁，丁火官星主动把车子归还","丁丑年土生金旺克木破财，戊寅年木旺制土得财","丁癸冲只是临时冲走卯车，戊寅年一合找回且寅丑暗合护身"],"ans":3,"exp":"卯财在时上表车，原局子卯破主车有问题，丁丑年丁癸冲抢走卯车，戊寅年合回，且寅丑暗合不伤身体。","sec":"1. 六亲与人物","t":"calc"},{"q":"四柱从年柱到时柱的时间类象，除了对应人生各阶段年龄，还隐含什么顺序规则？","opts":["从大到小、从先到后的顺序（如多次婚姻依次找）","从重到轻、从吉到凶的顺序（年吉时凶）","从内到外、从亲到疏的顺序（由日支向年时扩散）","仅表示年龄分段，不代表事件发生的先后顺序"],"ans":0,"exp":"从年到时是从大到小、从先到后的顺序，例如命中有三次婚姻，三次的先后顺序也是从年到时依次来找。","sec":"2. 时间类象","t":"rule"},{"q":"按空间类象，若一个人要“出远门”，命中主要看哪两个宫位？","opts":["年柱或月柱","年柱或时柱","月柱或日支","日干或日支"],"ans":1,"exp":"年柱主远方、海外、边缘，时柱为门户、出门，故出远门看年柱或时柱；月柱主祖籍家乡，日支主居所。","sec":"3. 空间类象","t":"xiang"},{"q":"按身体类象，月柱、日支、时柱各自对应的核心身体部位依次是？","opts":["头面手眼、五脏心脑、腿足四肢","五脏心脑、头面手眼、躯干脊背","躯干脊背、五脏心脑、头面手眼诸窍","腿足四肢、躯干脊背、五脏心脑"],"ans":2,"exp":"年柱腿足四肢，月柱躯干脊肩背，日支胸部五脏六腑心脑髓，时柱与外部相通的头面手眼嘴耳鼻等器官。","sec":"5. 身体类象","t":"xiang"},{"q":"在宫位物品类象中，鞋子拐杖、祖产单位、房子卧室、衣服眼镜依次对应哪四柱？","opts":["年柱、日支、月柱、时柱","月柱、年柱、时柱、日支","时柱、日支、月柱、年柱","年柱、月柱、日支、时柱"],"ans":3,"exp":"年柱鞋子拐杖祖先之物，月柱祖产家业单位学业，日支房子卧室私产，时柱车门衣服帽子眼镜。","sec":"6. 物品类象","t":"xiang"},{"q":"正印与偏印在学术类型与过旺（无官杀压力）时的负面表现有何不同？","opts":["正印主正统学术、过旺依赖惰性；偏印主非正统学术、过旺孤冷挑剔","正印主五术技术、过旺自私挑剔；偏印主正统学术、过旺呆滞","正印与偏印皆主正统学术，过旺均表现为胆小墨守成规","正印过旺反主精明创意，偏印过旺反主仁慈奉献"],"ans":0,"exp":"正印主正统学术，无官杀压力易懒惰依赖；偏印主非正统学术（如五术技术），过旺则自私冷淡挑剔。","sec":"1. 印","t":"diff"},{"q":"下列哪一组全部属于“印星”的共同事物与人体类象？","opts":["官职、法院、牢狱、疾病、外伤、神经","职称、印章、契约、住宅、靠山、头发、皮肤","文章、作品、娱乐场所、嘴巴、舌头、乳房","金钱、房产、排泄物、分泌物、血液、呼吸"],"ans":1,"exp":"印共同类象包括职业职称、印章契约、单位住宅车、靠山医药，人物为师长父母，人体为头、头发、皮肤、四肢。","sec":"1. 印","t":"xiang"},{"q":"正官与七杀虽同为克我之神，但心性与过旺负面表现有何差异？","opts":["正官无情之克、过旺暴躁霸道；七杀有情之克、过旺唯唯诺诺","正官与七杀皆为有情之克，均不怕旺只怕受克","正官有情之克、过旺胆小墨守成规；七杀无情之克、无制化则显凶","正官过旺必为匪徒，七杀过旺必为文官教师"],"ans":2,"exp":"正官异性有情之克，过旺则胆小怕事墨守成规；七杀无情之克，须制化方可驾驭，无制化则显凶为匪徒或病人。","sec":"2. 官杀","t":"diff"},{"q":"下列人物类象中，哪一组完全属于“官杀”的共同人物类象？","opts":["长辈、老师、父母、祖父、外戚","兄弟、姐妹、朋友、同伙、对手","下属、仆人、父亲、男命妻与情人、儿子","上司、父亲、男命子女、女命夫与情人、小人盗贼"],"ans":3,"exp":"官杀人物类象：上司、老师、长辈、父亲、丈夫或情人（女命）、子女（男命）、敌人、小人、恶人、盗贼。","sec":"2. 官杀","t":"xiang"},{"q":"乾造乙己庚乙／卯卯辰酉，原局透出两个都是正财，命主实际所赚之财是什么性质？","opts":["得到的全是偏财，因财源看比劫做功而非正偏财","正财偏财各半，因日支辰土中藏有偏财","一辈子无财可得，因比劫酉金把卯木冲破","得到的全是工薪正财，因原局无偏财透干"],"ans":0,"exp":"正偏财不表示财的来源是正是偏，只表示人对钱财的心性；财的来源要看比劫做功与否，该造实际得的全是偏财。","sec":"3. 财","t":"calc"},{"q":"关于“财虚透”与“年月财旺”的象义，下列判断完全正确的一项是？","opts":["财虚透主穷困潦倒，年月财旺主少年博学多才","财虚透主才华善交际，年月财旺主财多心乱易早辍学","时上财虚透主吝啬节俭，印星虚透在时上主懒惰","财虚透只表破财，年月财旺主学业有成得高学历"],"ans":1,"exp":"财虚透指才华、会来事、会说话，时上财虚透爱打扮时尚；年月财旺（尤其女性）因财多心乱，一定很早辍学。","sec":"3. 财","t":"xiang"},{"q":"在男女通用及女性专属取象中，财星除了金钱房产外，还代表什么？","opts":["男女皆表学术论文，女性还代表头发与皮肤","男命表母亲寿命，女命表父亲身高","男女皆表情感，女性还代表血气即月经","男女皆表宗教信仰，女性还代表乳房与乳汁"],"ans":2,"exp":"财表情感男女通用；此外，财还表示女孩的血气，即月经，人体共同类象还有分泌物与排泄物、饮食、血液、呼吸。","sec":"3. 财","t":"xiang"},{"q":"比肩与劫财在对待日主“合作与代价”上的本质区别是什么？","opts":["比肩主炒作冒险；劫财主冷静自主不喜竞争","比肩是凶神专主破财；劫财是吉神只助得财","比肩以争夺占有为目标；劫财协同合作毫无私心","比肩协同合作代表我去行权；劫财助我有代价且分夺我财"],"ans":3,"exp":"比肩与日主同性，代表我去行使权力、协同合作；劫财与日主异性，助我但有代价，要分夺我之财。","sec":"4. 比劫","t":"diff"},{"q":"食神与伤官同样由日主所生，二者过旺时的吉凶规律有何根本不同？","opts":["食神是吉神不怕旺只怕受克；伤官过旺则走极端易破规矩","食神与伤官均不怕旺，越旺越主清贵与长寿","伤官是吉神不怕旺只怕受克；食神过旺则傲慢违法","食神与伤官均怕过旺，过旺一律主牢狱与犯罪"],"ans":0,"exp":"食神是吉神，一般都有用，不怕旺只怕受克；伤官过旺则走极端，傲慢刻薄、不守规矩甚至有犯罪意识。","sec":"5. 食伤","t":"diff"},{"q":"十神类象简表中，印、财、官杀、比劫、食伤各自对应的“场所”依次是？","opts":["银行交易所、学校医院、体育场、法院监狱、寺庙","学校医院、银行交易所、法院监狱、竞技场、娱乐场所与厕所","政府机构、竞技场、银行、学校医院、监狱","娱乐场所、银行、学校、法院、体育场"],"ans":1,"exp":"简表场所：印为学校医院学术机构，财为银行交易所，官杀为政府法院监狱，比劫为竞技场体育场，食伤为娱乐休闲场所、厕所。","sec":"6. 十神类象简表","t":"xiang"},{"q":"男命看子女时有“通变法则”，主要看什么十神？怎样区分生儿生女？","opts":["主要看印：印＋杀＝儿，杀无印为女，冲破印生女","主要看比劫：比＋官＝儿，官无比为女，合住财生女","主要看财：杀＋财＝儿，杀无财为女，穿倒财生女","主要看食伤：食＋财＝儿，伤＋印＝女，穿倒官生女"],"ans":2,"exp":"男命以杀为儿、官为女，但通变主要看财：杀加财等于儿，杀无财为女，穿倒财星（或穿倒妻宫财星）则生女。","sec":"1. 子女","t":"rule"},{"q":"坤造丁癸乙丙／未丑巳子，原局有食神按基本原则应生女，为何实际上生了儿子？","opts":["子丑相合把食神丑土合化成水故生儿","原局巳丑拱了七杀，七杀旺故生儿","丁火食神透干被癸水克掉，反断生儿","生在丙辰运，行伤官大运则生儿"],"ans":3,"exp":"女命原局有食本应生女，但有时也看大运：行伤官大运（此造在丙辰伤官运）则生儿子。","sec":"1. 子女","t":"calc"},{"q":"在看子女数量时，原局或岁运出现什么结构组合通常主子女多？","opts":["墓库逢冲则子女多","食伤入空亡则子女多","禄神逢合则子女多","印星虚透则子女多"],"ans":0,"exp":"看儿女从日支到年干依次找，同时有“墓库逢冲则子女多”的规律。","sec":"1. 子女","t":"rule"},{"q":"关于父母星的取象，“印星”与“伤官做母亲”各自代表什么含义？","opts":["印星专指母亲不指父亲；伤官做母亲主随父不随母","印星兼表父母是一个状态；伤官做母亲主母亲离异改嫁","印星专指父亲不指母亲；伤官做母亲主母亲长寿贤惠","印星兼表父母；伤官做母亲主父母白头偕老"],"ans":1,"exp":"印是父母星，两个都表示，是一个状态；伤官做母亲（或水火阴阳相配），往往主母亲离异改嫁、随母。","sec":"2. 父母","t":"diff"},{"q":"乾造丁壬丁辛／未子巳亥，母亲早死且应期在丙辰年（1976），命理依据是什么？","opts":["局中壬水合丁火，丙辰年辰土收了壬水导致母亡","局中亥子水旺克巳火，丙辰年辰戌冲坏了巳火","局中穿倒食神，丙辰年丙壬冲解合兼丙虚透不生未","局中辛金财星克未土，丙辰年丙辛合化水克母"],"ans":2,"exp":"巳未同表母亲，原局穿倒了食神主母早死；丙辰年丙壬冲解合，同时丙虚透代表巳不生未，与母断绝关系故母死。","sec":"2. 父母","t":"calc"},{"q":"坤造戊辛丁癸／申酉未卯，父亲在庚辰年去世，其命理应期依据是？","opts":["申酉金旺克卯木，庚辰年庚金直接劈断卯木","癸水七杀克丁火，庚辰年辰土入墓收走丁火","戊土伤官透干，庚辰年辰土合走酉金致父亡","卯为父，庚辰年父星坐辰穿印（未或印）表父非父"],"ans":3,"exp":"卯申合、卯为父，坐下未食为母；庚辰年因父星卯坐辰穿印，表示父不是父了，所以死父。","sec":"2. 父母","t":"calc"},{"q":"乾造丙丙丙丁／申申辰酉，主“左腿跛脚”且每到申年就有事，命理依据是什么？","opts":["比肩伏吟在年为腿、丙阳为左，申金重量伏吟应凶","丙火在月为肩背、申金冲克，每逢申年必伤脊椎","辰土在日支为腿、丙火克申金，逢申年火金交战","酉金在时为腿、丁阴为左，辰酉合绊导致左腿受伤"],"ans":0,"exp":"比肩伏吟（重复），比劫在年为腿，丙为阳主左，故左腿跛脚；申金主重量，每到申年就有车撞等事。","sec":"3. 左右","t":"calc"}]},{"n":57,"level":"中级","title":"象的应用","qs":[{"q":"按盲派的共象原则，一个字的象至少要几类象指向同一事物才能确立？","opts":["三类，干支、宫位、十神须齐","两类，如干支象加宫位象","四类，须含神煞","一类，只看干支象即可"],"ans":1,"exp":"只要有两类象表述同一事物，即可确立；如丁在时上，丁象与时宫位都有眼睛。","sec":"二、共象原则","t":"rule"},{"q":"伤官、食神出现在年上与时上，分别多表什么人？","opts":["年上表小孩，时上表女性长辈","年时都只表子女","年上表女性长辈，时上表小孩","年上表学生，时上表母亲"],"ans":2,"exp":"伤食既可表小孩也可表女性长辈：在年上表女性长辈，在时上表小孩。","sec":"二、共象原则","t":"rule"},{"q":"原局相合时互用对方的象：食神合印与伤官合印各表什么？","opts":["两者都表学术，只是强弱不同","食神合印为技艺，伤官合印为学术","食神合印为官位，伤官合印为权力","食神合印为学术，伤官合印为技艺"],"ans":3,"exp":"食神合印＝思想性的学问即学术；伤官合印＝技能、技艺；劫财合财＝劫取而得的财。","sec":"三、合象原则","t":"diff"},{"q":"按盲派，原局的劫财合财，取财手段是什么性质？","opts":["劫取而得，不是合法劳动所得","靠合作经营平分而得","靠继承家产而得","靠薪水收入稳定而得"],"ans":0,"exp":"劫财合财＝劫取而得到的财，取财手段是“劫”。","sec":"三、合象原则","t":"rule"},{"q":"阴木生火、阳木生火、辰配子，化象各是什么？","opts":["阴木生火家具装潢，阳木生火纺织服装，辰配子化工","阴木生火纺织服装，阳木生火家具装潢，辰配子化工","阴木生火化工，阳木生火服装，辰配子纺织","阴木生火纺织服装，阳木生火化工，辰配子家具装潢"],"ans":1,"exp":"阴木生火＝丝线加工物：织物、服装；阳木生火＝家具、装潢；辰配子＝化工、制药、提纯。","sec":"四、化象原则","t":"diff"},{"q":"按盲派墓象原则，墓库的含义怎么定？","opts":["一律只表钱财仓库、收藏之物","按库所在宫位定，与所墓之神无关","按所墓之神定，如七杀入羊刃墓为军队","按墓库本身五行定，与所墓之神无关"],"ans":2,"exp":"墓是收藏控制，含义根据所墓之神确定；七杀入羊刃墓表军队，食伤库表学校、工厂。","sec":"五、墓象原则","t":"rule"},{"q":"“财带官帽”与“官带财帽”各表示什么？","opts":["两者都表管财的官","两者都表公家之财","财带官帽为管财的官，官带财帽为公家之财","财带官帽为公家之财，官带财帽为管财的官"],"ans":3,"exp":"一柱以干统支：财带官帽＝公家之财；官带财帽＝管理财的官，官统财。","sec":"七、带象原则","t":"diff"},{"q":"“印带财帽”按盲派是什么象？","opts":["薪水，上班领工资","权力，掌管实权","经营性的房产","公家之财"],"ans":0,"exp":"印为单位，财来自印中，所以印带财帽＝薪水；印带官帽才是权力。","sec":"七、带象原则","t":"rule"},{"q":"吃西瓜理论里，皮和肉分别对应什么？","opts":["月干为皮，月支为肉；吃肉丢皮富","年干为皮，年支为肉；吃肉丢皮富","年支为皮，年干为肉；吃肉丢皮富","年干为皮，年支为肉；吃皮丢肉富"],"ans":1,"exp":"年干为西瓜皮、年支为西瓜肉；吃肉丢皮富、吃皮丢肉穷、皮肉同吃也富。","sec":"七、带象原则","t":"rule"},{"q":"借象原则里，可以互借其象的有哪两种关系？","opts":["墓库相冲、天干通根","天干五合、地支六合","天干通禄神、同五行阴阳不同","同五行阴阳相同、地支三合"],"ans":2,"exp":"丙与巳一家可互借其象；同五行而阴阳不同如寅与卯，也可互借。","sec":"八、借象原则","t":"rule"},{"q":"夫妻宫的副宫有哪两种情况？","opts":["与夫妻宫相合的字，或相冲的字","时支的字，或月支同五行的字","日干通禄的字，或日支所藏的字","从夫妻宫引出的字，或与夫妻宫同五行的字"],"ans":3,"exp":"副宫：夫妻宫引出的字（或夫妻宫从某字引出），以及与夫妻宫同五行的字；多个宫星可断多次婚姻。","sec":"2. 夫妻宫的副宫","t":"rule"}],"fine":[{"q":"盲派取象时，要在纷繁复杂的象中准确定位其中一象，依靠哪七条取象原则？","opts":["干象、支象、宫象、神象、煞象、墓象、库象","共象、合象、化象、墓象、制象、带象、借象","正象、反象、虚象、实象、带象、借象、伏象","共象、合象、生象、克象、刑象、穿象、破象"],"ans":1,"exp":"七条取象原则为：共象、合象、化象、墓象、制象、带象、借象。","sec":"一、七条原则总览","t":"rule"},{"q":"盲派将“象”分为静态与动态两大类，下列归类完全正确的一项是？","opts":["静态为十神、神煞、墓库；动态为天干、地支、宫位","静态为干支、宫位；动态为十神、神煞、合化、刑冲","静态为干支、宫位、十神、神煞；动态为合化、刑冲","静态为大运、流年；动态为原局干支、宫位与十神"],"ans":2,"exp":"静态象包括干支、宫位、十神、神煞四类；动态象则指合化、刑冲等作用关系。","sec":"二、共象原则","t":"diff"},{"q":"乾造庚己丙庚／戌卯戌寅，为何年上食神“戌”不按母亲或外母断，而断定必是岳母？","opts":["戌土为燥土，在年柱专主妻子的母亲","庚金偏财透在年干，财星生戌土故必为岳母","寅戌拱火生己土，伤官旺者一律断为岳母","戌在年表女性长辈，又与妻宫之戌相同离妻最近"],"ans":3,"exp":"食神戌在年上表女性长辈，可以是母、外母或岳母；因年支戌与日支妻宫戌相同，与妻关系最近，故必是岳母。","sec":"二、共象原则","t":"calc"},{"q":"乾造辛丙辛丙／卯申巳申，取“申”为运转着的机器、命主是管机器运转的工人，依据是？","opts":["申支象运转机器、十神劫财运作，巳申合且申盖丙被管","辛金日主自坐羊刃，卯申暗合主体力劳动","丙火七杀克申金，火金交战主车间冶炼工人","卯木财星冲申金，财来就我主操纵大型机械"],"ans":0,"exp":"申在地支象为机器运转、十神为劫财主机械运作，共象定位为运转机器；申上盖丙、巳申合且巳＝丙，故既被管理又管申。","sec":"二、共象原则","t":"calc"},{"q":"时空八字“丙乙庚乙／戌未戌酉”问官司，取象“朋友同学做法官，法院向着你家且能赢”的依据是？","opts":["丙火食神制酉金，丙戌合局把对方律师制服","丙杀为法院、日年戌为朋友及其同学，戌旺穿酉则赢","庚金日主生癸水，乙庚合绊住对方财星故官司必赢","未土印库生庚金，法院印星向着日主而酉金败诉"],"ans":1,"exp":"丙七杀为法院，日支戌为朋友、年上戌为朋友同学，故丙戌是朋友同学做法官；未戌酉三方，戌旺穿酉则赢。","sec":"3. 时空八字（问事以起八字时间为准）","t":"calc"},{"q":"合象原则“复合描述”中，通过干支、宫位、十神等两种以上不同象复合时，它们之间是什么关系？","opts":["必须同时出现五合或六合，否则不能复合","两种象互相抵消，只保留力量更旺的一方","两种象往往不同，但一方能定义另一方","两种象必须完全相同，互相叠加增强力量"],"ans":2,"exp":"复合描述得到的两种象往往不同，但一方能定义另一方，如戌（建筑物）＋食神（作品）＝建筑设计。","sec":"三、合象原则","t":"rule"},{"q":"乾造壬癸丙戊／子丑寅戌，命主是“国家单位公务员从事建筑设计”且年轻时患风湿病，依据是？","opts":["壬癸水官杀混杂主公职，丑戌刑主建筑施工受伤","丙火日主见戌为食神库，子丑合水主水利工程设计","寅木长生丙火主文化，壬水冲丙火导致风湿寒症","寅印公门机关、戊戌建筑设计；寅丑暗合湿土遇风"],"ans":3,"exp":"寅为印主工作兼公门机关，戊戌一柱为建筑设计；寅丑暗合，局中水多丑湿、寅主风，故患风湿病。","sec":"三、合象原则","t":"calc"},{"q":"合象原则第二条“相合双方互用对方的象（如劫财合财）”，其适用的前提条件是什么？","opts":["原局中有的合才适用","必须合化成功才能互用对方的象","只适用于天干五合，不适用于地支六合","必须走大运逢合时才适用"],"ans":0,"exp":"天干五合与地支六合如夫妻成家，互用对方的象，但条件是“原局中有的合才适用”。","sec":"三、合象原则","t":"rule"},{"q":"乾造戊己癸己／申未巳未，取象为“操作股票的证券公司老总”的依据是什么？","opts":["巳申合化水为比劫，合局把七杀制尽故为金融高管","印申（机构）合财巳（钱多），且申为劫财长生主风险运作","未土七杀两现制癸水，巳未拱火主文化传媒公司","戊癸合火化财，己土偏官透干主大型国企领导"],"ans":1,"exp":"印星申合财星巳，印表机构、合财表钱多，而申又是劫财之长生（风险性运作），合起来就是操作股票的证券公司老总。","sec":"三、合象原则","t":"calc"},{"q":"乾造庚乙癸庚／辰酉卯申，八字无财，取象为“中央银行行长（银行大官员）”的依据是？","opts":["辰酉合金生癸水，辰为财库被酉合开故掌管银行","满盘金水主聪明智谋，酉金桃花合辰主审计监察","卯食神为财源，庚申印主金融与权力，卯申合控制钱源头","乙木食神透干合庚金，乙庚合化金主冶炼五金行业"],"ans":2,"exp":"八字无财，卯食神为财之原神可当钱的源头；庚申金有金融与印（权力）含义，卯申合控制钱的源头，故为银行大官员。","sec":"三、合象原则","t":"calc"},{"q":"“丁壬乙戊／未子丑寅”、“戊丙乙戊／申辰丑寅”与“癸丙己丙／卯辰丑寅”均断为公安，核心共同取象是？","opts":["皆有丑未相冲或辰戌相冲，冲开官杀库掌权","皆为水火既济组合，丙丁火照亮壬癸水主执法","皆有申酉金七杀透干，配羊刃主军警武职","皆为阳制阴组合，以寅卯阳木制丑辰阴暗之象"],"ans":3,"exp":"丑、辰属阴暗（黑社会、犯罪之象），寅、卯为阳，命中形成以阳制阴的组合，即是典型的公安、刑警象。","sec":"三、合象原则","t":"calc"},{"q":"乾造壬己癸乙／寅酉酉卯，命主“找了小二十多岁的学生当小情人”，这一取象依据是？","opts":["时上乙卯食神表极小晚辈学生，在局中显现且冲夫妻宫","年干壬水劫财合丁火，丁火偏财在年主远方年轻女子","己土七杀坐酉金长生，杀生印主女下属主动投怀","酉金伏吟在月日两柱，双酉合寅木主两次跨龄婚姻"],"ans":0,"exp":"食神表学生，在时上表年龄很小的晚辈、学生；该乙卯在命局显现又卯酉冲夫妻宫，故与极年轻的学生有情人关系。","sec":"三、合象原则","t":"calc"},{"q":"在化象原则中，阴木（卯）生火在职业上主纺织或服装，若木为印与火为财时如何区分？","opts":["木为印一般搞服装生意，火为财一般在纺织厂打工","木为印一般纺织或丝织工作，火为财一般搞服装生意","只有阴木在前火在后才成立，火在前则不成立","木为印主家具装潢，火为财主化工制药"],"ans":1,"exp":"阴木生火（不分阴木前后）主丝线加工物：木为印一般为纺织或丝织工作，火为财一般搞服装生意。","sec":"四、化象原则","t":"rule"},{"q":"乾造丁己庚庚／酉酉子辰与乾造癸丙戊丙／卯辰子辰，为何均断为“化工提炼或制药业”？","opts":["皆有酉辰合金之象，金水伤官主医疗器械制造","皆有丙丁火透干克金，火炼真金主冶炼提纯","皆有子辰合之象，辰如泥土出水有浊中提纯之意","皆有木火相生之象，木为草药、火为炼丹制药"],"ans":2,"exp":"辰配子主化工、制药、提纯：辰为水库象泥土，子辰合水局是从泥土中出水，正合从混浊中提纯之象。","sec":"四、化象原则","t":"calc"},{"q":"乾造庚戊丙己／戌寅子丑，为何“总想当公务员，结果却是老师”？","opts":["戊己土食伤混杂克官星，被单位开除后转行教书","庚金偏财坐戌库不透根，无财生官故当不成公务员","寅木偏印被丑土暗合绊住，印星无力化杀生身","寅戌拱火主文化机构为老师；坐下子官合丑不做功"],"ans":3,"exp":"寅印与戌食神拱火主文化机构（老师）；坐下子官虽合丑使他喜欢当官，但子丑合不做功、非一家，故是老师。","sec":"四、化象原则","t":"calc"},{"q":"乾造己辛戊甲／卯未辰寅，取象为军队少将（师级）的命理依据是什么？","opts":["七杀入未（羊刃墓兼权力中心），表军队军官","辛金伤官坐未土，伤官合杀主公安检察院领导","卯辰相穿制尽印星，木土交战主土木工程主管","甲木七杀坐寅木禄神，食神制杀主武职高官"],"ans":0,"exp":"未为七杀（寅卯）之墓，是权力中心，同时未土在八字中又是戊土羊刃（表军队），七杀入羊刃墓表军队军官。","sec":"五、墓象原则","t":"calc"},{"q":"乾造丁癸丙壬／未丑子辰，丑未相冲取财，其“善于资本运营且兼从事实业地产，而非纯投机”的依据是？","opts":["子丑合土化官星，官杀混杂主多行业跨界经营","丑财库制劫财主运作，未为印库主实体实业规模","辰土水库收壬癸水，水土混杂主水利与矿产开发","丙火坐子水正官，官印相生主传统制造业起家"],"ans":1,"exp":"丑财库制未中劫财（炒作运作）主资本运营；而未同时是印库，印主实体，有企业规模，故并非纯投机。","sec":"六、制象原则","t":"calc"},{"q":"“乙壬甲甲／未午子戌”与“乙丙甲甲／未戌子戌”同为羊刃库穿印掌权，为何一为军中政委、一为教授与法院院长？","opts":["前者子午冲制印主政法；后者戌未刑开库主高校","前者壬水偏印透干主武职；后者丙火食神透干主文职","前者午未合伤官火文为政委；后者戌为食神库（学校）","前者甲木坐午泄秀；后者甲木坐戌财库主经商"],"ans":2,"exp":"羊刃库穿印本主军权：前者午未合，午为伤官有头脑又火象文，故为军中政委；后者戌为食神库表学校，故先教授后院长。","sec":"六、制象原则","t":"diff"},{"q":"乾造乙己丁庚／未卯丑戌，取象为“搞房产建筑业发大财”的命理依据是？","opts":["己土食神透干生庚金，食神生财主餐饮食品发财","未卯半合木局生丁火，印旺生身主文化出版发财","丑未冲开印库，火土燥湿中和主农业种植发财","丑戌刑坏丑财库中之金发财，戌建筑与卯合呈土木象"],"ans":3,"exp":"丑戌相刑，戌火制坏丑中金（丑为财库）故发财；戌为建筑，卯戌合形成土木之象，故搞房产建筑业发财。","sec":"六、制象原则","t":"calc"},{"q":"带象原则中，一柱干支好比“干像头、支像肢体”，取象时谁主导谁？","opts":["以干统支之象，干决定支象的特点","以支统干之象，支决定干象的特点","干支完全独立，各取各的象互不干涉","只看地支藏干，天干虚浮不起决定作用"],"ans":0,"exp":"认识人先看头象特点再看身体，故一柱干支以干统支之象，干决定支象的特点；复合之象也以干为主导。","sec":"七、带象原则","t":"rule"},{"q":"带象口诀中，“印带官帽”与“财带印帽”分别表示什么含义？","opts":["两者都表示在私营企业打工，没有权力","印带官帽表权力；财带印帽表薪水（上班领工资）","印带官帽表薪水；财带印帽表权力（掌管实权）","印带官帽表公家之财；财带印帽表管财的官"],"ans":1,"exp":"印带官帽＝权力；印带财帽与财带印帽同义，皆表薪水、上班领工资（印为单位，财来自印中）。","sec":"七、带象原则","t":"diff"},{"q":"乾造辛庚丙丁／卯子申酉，其“不为官，乙未运开医药门诊赚钱”的取象依据是？","opts":["丙丁火克申酉金，火金冶炼主自己开五金加工厂","辛金正财合丙火，丙辛合水主经营水产与洗浴行业","子带庚财（官带财帽）当财看；未药合卯房通门面酉","子卯相破坏了印星，没有单位只能靠偏门生意糊口"],"ans":2,"exp":"子官上带庚财（官带财帽）当大财看；未合卯印（房）带辛财通时上门面酉，未有药义且为食伤技能，故开医药门诊。","sec":"七、带象原则","t":"calc"},{"q":"在盲派取象口诀中，“辛金、酉金配丙丁火”以及“辛亥”一柱分别有什么特殊象义？","opts":["辛酉配丙丁火表法律条文，辛亥有文墨书画之象","辛酉配丙丁火表珠宝首饰，辛亥有航运贸易之象","辛酉配丙丁火表乐器钟表，辛亥有酿酒制药之象","辛酉配丙丁火表人（或死人病人），辛亥有杀猪（屠夫）象"],"ans":3,"exp":"口诀：辛金、酉金配丙丁火时，辛酉表人（如丁酉为死人病人，丙辛合可主杀人）；辛亥有杀猪之象即屠夫。","sec":"七、带象原则","t":"xiang"},{"q":"王庆造（癸乙丙辛／丑卯午卯）与同日生民工（癸乙丙癸／丑卯午巳）为何一富一穷？","opts":["前者丙辛合得辛下丑财库（吃肉）；后者癸巳自合只得癸皮","前者卯木羊刃生午火，后者巳火禄神被癸水盖头克坏","前者丙火坐午强旺能担财，后者丙火见巳身旺无依","前者时支卯木为财星，后者时支巳火为劫财夺财"],"ans":0,"exp":"年干为皮、年支为肉：前者丙辛合制辛，得到辛下丑财库，吃了西瓜肉丢了皮故富；后者癸巳自合，吃了皮丢了肉故穷。","sec":"3. 吃西瓜理论","t":"calc"},{"q":"坤造癸甲甲丁／巳寅辰卯，原局未透庚金官星，为何却能借象断定“巳是丈夫，丁也是丈夫（情人）”？","opts":["寅卯辰三会木局，木生火旺故把所有火都当成官杀来看","癸＝辰且巳生辰，故借象巳为夫；再借象定丁为情人","巳中藏庚金七杀，故所有女命只要见巳火都直接当丈夫看","甲木日主生丁火伤官，伤官克官故反过来把丁火当丈夫"],"ans":1,"exp":"癸水下有庚官，癸＝辰（辰藏癸），巳生辰，故借象巳为丈夫；再借象定丁为丈夫（情人）。若无癸水透出，巳不能看夫。","sec":"3. 命例","t":"calc"}]},{"n":58,"level":"中级","title":"财命专辑","qs":[{"q":"盲派以禄当财，成立条件是什么？","opts":["命中有官杀，且官杀制禄","命中有财，且财与禄相生","命中占禄，无伤食泄禄，或八字无财","命中有印，且印被财破"],"ans":2,"exp":"禄当财的条件是占禄而无伤食泄禄，或八字无财；禄是现成之福，辛苦求财。","sec":"一、总纲：哪些神可以当财","t":"rule"},{"q":"以禄当财的八字，最怕见到什么？","opts":["印星生禄、官杀合禄","比肩帮禄、印星护禄","财星合禄、财星制禄","劫财分禄、伤食泄禄、穿禄"],"ans":3,"exp":"禄最怕劫财（分禄）、伤食（泄禄）、穿禄；印生禄、禄合财、禄制财则吉。","sec":"二、禄神当财","t":"rule"},{"q":"库遇到刑、冲、穿，按盲派怎么区分开库与不开库？","opts":["冲、刑才是开库，穿是推倒墓本身","穿、刑才是开库，冲是推倒墓本身","冲、穿才是开库，刑是推倒墓本身","冲、刑、穿都是开库"],"ans":0,"exp":"穿不是开库，穿是推倒墓本身；冲、刑才是打开库。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"八字有财星时，伤食当财与无财时有什么不同？","opts":["有财则伤食不再当财，只作废神","有财则伤食是财之原神，作投资之财","有财则伤食转为官杀，当官看","有财则伤食要制财，才算有功"],"ans":1,"exp":"八字无财星时伤食直接当财；有财时伤食是财之原神，为投资之财。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"伤官当财与食神当财，取财特点有什么不同？","opts":["伤官为思想、脑力之财；食神为谋为、经营之财","伤官为现成之财；食神为风险之财","伤官为谋为、经营之财；食神为思想、脑力之财","伤官为体力之财；食神为权力之财"],"ans":2,"exp":"伤官＝谋为、经营之财；食神＝思想、脑力之财；天干食表思想，地支食表企业。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"官杀统财成立，要满足哪三个限制？","opts":["官（杀）与财各有两个、财官相连、只论原局","官杀与财相邻、日主身强、只论大运","官（杀）或财只有一个、财官相冲、大运也算","官（杀）或财只有一个、财官相连、只论原局"],"ans":3,"exp":"「少」指只有一个，且财官必须相连（财生官）；只论原局，大运出现不算。","sec":"1. 官杀与财互统","t":"rule"},{"q":"原局财星很多、官星只有一个，且财生官相连，按盲派怎么论？","opts":["官统财，官与财都当财富看","财官两无功，只能论工薪","财多身弱，须印星化财","财统官，官星当官看"],"ans":0,"exp":"财多官少，官统财；官（杀）多财少则财统官杀；统了之后官与财都当财富，不再当官看。","sec":"1. 官杀与财互统","t":"calc"},{"q":"「过河拆桥」是什么结构？大运与流年哪个算？","opts":["主位财生宾位官，官被弄住；流年算，大运不算","主位财生宾位官，官被弄住；大运算，流年不算","宾位财生主位官，官被弄住；流年算，大运不算","主位官生宾位财，财被弄住；大运流年都算"],"ans":1,"exp":"日支的财生宾位的官，这个官再被宾位另一字合、制、坏；大运来坏算，流年坏不算。","sec":"3. 过河拆桥（发大财的少见结构）","t":"rule"},{"q":"风险取财（炒股、博彩）的做功之神是什么？","opts":["伤官、食神","印、官杀","比肩、劫财","财星、禄"],"ans":2,"exp":"风险取财主要靠比肩、劫财做功，如劫制财、劫去印、比劫抗杀；智力取财是伤食，体力取财是比劫禄。","sec":"2. 风险取财","t":"step"},{"q":"按盲派，博彩赌博时，哪些日子赢、哪些日子输？","opts":["比劫、财之日赢，官杀、伤食之日输","印、比劫之日赢，财、官杀之日输","财、伤食之日赢，比劫、官杀之日输","比劫、官杀之日赢，财、伤食之日输"],"ans":3,"exp":"赢钱之神是比劫、官杀，输钱之神是伤食、财。","sec":"2. 风险取财","t":"rule"},{"q":"体育运动员、歌星、影星这类名人体力取财，共同特点不含下列哪项？","opts":["财星旺相且身弱","比劫做功效率高","一般有伤食配合","丙丁火做功或七杀虚透于干"],"ans":0,"exp":"名人类三个特点：比劫做功效率高；有伤食配合（技术、艺术）；有丙丁火做功或七杀虚透（名气）。","sec":"4. 体力取财","t":"diff"}],"fine":[{"q":"当财之神（禄、伤食、官杀）若与日主毫无关联，按盲派应如何看待？","opts":["直接转为命主的官星或名气","仍算命主之财，只是来得较晚","只是旁人的财，对命主无意义","须等大运出现比劫才归命主"],"ans":2,"exp":"当财的四条通则第一条即「必须与日主有关联」，若与日主毫无联系，只是旁人的财，无意义。","sec":"一、总纲：哪些神可以当财","t":"rule"},{"q":"八字同时见禄与财时，若出现「禄合财」或「禄制财」，应如何论断？","opts":["禄财相战，只能得其中之一，另一半破耗","须弃禄就财，见禄制财反主劳碌无成","有财则禄不当财，禄合财反主破财","以禄当财与以财当财不矛盾，都算得财"],"ans":3,"exp":"以禄当财与以财当财并不矛盾，禄合财、禄制财都算命主得财。","sec":"一、总纲：哪些神可以当财","t":"diff"},{"q":"在盲派看财时，天干食神与地支食神的取财象义有何不同？","opts":["天干食神表思想，地支食神表企业","天干食神表体力，地支食神表投资","天干食神表银行，地支食神表门面","天干食神表企业，地支食神表思想"],"ans":0,"exp":"食神＝思想、脑力之财，细分则天干食神表思想，地支食神表企业。","sec":"一、总纲：哪些神可以当财","t":"xiang"},{"q":"对比「以财当财」与「以官杀当财」，两者的财富级别通常有何差异？","opts":["以官杀当财级别低，多属工薪小财","以官杀当财级别高，比以财当财大一倍","以财当财级别高，比以官杀当财大一倍","两者财富级别相同，只是行业不同"],"ans":1,"exp":"官杀当财成立时，财富级别高，比单纯以财当财大一倍。","sec":"一、总纲：哪些神可以当财","t":"calc"},{"q":"按盲派禄位对应，丙戊、丁己、壬、癸四组日主的禄神依次是？","opts":["午、巳、子、亥","寅、卯、申、酉","巳、午、亥、子","巳、未、亥、丑"],"ans":2,"exp":"十天干禄位：甲寅、乙卯、丙戊巳、丁己午、庚申、辛酉、壬亥、癸子。","sec":"一、总纲：哪些神可以当财","t":"rule"},{"q":"以禄当财时，若禄神落在年柱，通常主何种取财象义？","opts":["靠兄弟朋友合伙分财","本地开店坐地收租","祖业现成、守家取财","远方、海外取财"],"ans":3,"exp":"年主远方，禄在年上主远方、海外取财。","sec":"二、禄神当财","t":"xiang"},{"q":"庚金日主见申禄在局，若时柱地支为丑，按盲派称作什么结构？","opts":["库护禄，不怕官杀克","比劫分禄，主兄弟夺财","禄穿库，主破财损寿","禄入墓，主一生体弱多病"],"ans":0,"exp":"禄入时上之库（如庚金申禄见时支丑）为「库护禄」，能护住禄神而不怕官杀克。","sec":"二、禄神当财","t":"rule"},{"q":"八字原局庚申禄入丑运看似禄入墓，但若局中原先就有午、未，行癸丑运反而不墓金，原因是什么？","opts":["丑与申暗合，化土为水而泄秀生财","丑未冲打开墓库，反不墓金且能发财","午火生丑土，印星护禄使申金不受克","大运丑土为虚神，不能真正收墓地支申"],"ans":1,"exp":"局中有未，行丑运则丑未冲打开墓库，既护禄又开库，故反不墓金而能发财。","sec":"二、禄神当财","t":"diff"},{"q":"「制财之原神」与直接「制财」相比，在财富级别上应如何判断？","opts":["两者级别相等，只是得财速度快慢不同","制财之原神只主名气，不主实际财富","制财之原神的财富级别比制财还大","直接制财的财富级别比制财之原神大"],"ans":2,"exp":"食神被印合或制干净时，因伤食为财之原神，制财之原神的财富级别比直接制财还大。","sec":"三、伤食当财","t":"diff"},{"q":"命局中出现「食伤库＋财」或食神入库合官的组合，常对应哪类行业或场所之象？","opts":["餐饮、杂货店之象","医院、医药之象","煤矿、采石之象","银行、金融之象"],"ans":3,"exp":"食神为财之源头，库为金融仓库，食伤库配财（尤其带申金金融象）多主银行、金融。","sec":"三、伤食当财","t":"xiang"},{"q":"若伤官合官做功，但年柱出现印星坏了伤官，通常应如何断其层次？","opts":["伤官无势制效率低，不能当官，只开门面","印星护官有情，反主官居高位且掌巨财","伤官被印制干净，必为央行或财政高官","伤官见官反局，必主一生无业且多官司"],"ans":0,"exp":"伤官合官而年上有印坏伤官，令伤官失势、做功效率变低，故不能当官，多为开门面做生意。","sec":"三、伤食当财","t":"calc"},{"q":"若以丢失钱包的时刻起盘，判断钱包「失与不失」最核心的关键是什么？","opts":["财星是否透出在年干","财库与主位是否连得上","原局官杀是否多于比劫","日主是否坐在禄神之上"],"ans":1,"exp":"临时起盘找失物，只要财库仍与主位相连（如库中透干合入日主），便失而复得。","sec":"三、伤食当财","t":"rule"},{"q":"干支呈现「干财支官（杀）」且仅此一组，按盲派互统规则应如何论断？","opts":["财坐死绝之地，不能统官","官财相克，不能互统","官杀带财象，可以统财","只论官星，不能当财看"],"ans":2,"exp":"干财支官（杀）属于官杀带财象、财官相连，同样成立官杀统财。","sec":"1. 官杀与财互统","t":"rule"},{"q":"官杀藏库无冲、或有制而制不彻底（制不尽）而当财看时，通常在什么大运发财？","opts":["比劫泄印生财之运","官杀入墓受克之运","合住官杀库之运","冲开库或引出官杀之运"],"ans":3,"exp":"官杀制不尽而当财，原局未彻底制服，须等大运冲开库或引出官杀加以制化时发财。","sec":"2. 官杀制不尽","t":"calc"},{"q":"关于「过河拆桥」结构，若大运反过来冲坏了主位原先用来生官的那个财，结果如何？","opts":["原局已把财生过去了，大运冲财反而更好，发大财","必须同时见流年合住该财才不破财","大运冲坏主位财则由富转贫，只算流年坏不算","财源被断，过河拆桥破局而破产"],"ans":0,"exp":"过河拆桥一旦原局已将主位财生向宾位官，大运再坏此财反为好，因功神在于弄住官。","sec":"3. 过河拆桥（发大财的少见结构）","t":"diff"},{"q":"运用「取财五法」分析命局财富时，正确的分析顺序第一步应当是什么？","opts":["先算身强，再看十神喜忌","先定职业，再看取财方式","先看大运，再定原局用神","先数财星，再定日主旺衰"],"ans":1,"exp":"盲派看取财五法，强调「先定职业再看取财方式」，再配合做功效率定大小。","sec":"五、取财五法","t":"step"},{"q":"在经营取财中，「内食神（地支食神做功）」与「财配印、财或印落时上做功」的典型区别是什么？","opts":["内食神多开店，财配印或落时上多做企业","两者都只能当工薪族，无法独立经营","内食神多做企业，财配印或落时上多开店","内食神只做外贸，财配印只做资本运营"],"ans":2,"exp":"经营三式：内食神做企业（带官象则是经理人）；财落年时做生意；财配印或落时上做功多开店。","sec":"1. 经营取财","t":"diff"},{"q":"同样是风险取财，偏向「赌博」与偏向「炒股」在命局结构上有何辨别要点？","opts":["财星透干坐禄、或食神生财有情，偏向赌博","有伤官合杀、或印星化杀生身，偏向赌博","官杀混杂无制、或比劫合印透干，偏向赌博","有丑等暗处结构，或禄与财较量取财，偏向赌博"],"ans":3,"exp":"原局有丑之类的暗处结构、或禄与财较量取财，多偏向赌博而非正规炒股。","sec":"2. 风险取财","t":"diff"},{"q":"智力取财（咨询、律师、艺术家、作家）在命局上主要有哪两类核心表现？","opts":["伤食占主位或与主位做功，或木火成气势","禄神坐于年支，或湿土成气势","比劫占主位合财，或金水成气势","官杀入墓无冲，或燥土成气势"],"ans":0,"exp":"智力取财做功之神是伤官、食神，且占主位或与主位做功；另一类是木火成气势表文化思想。","sec":"3. 智力取财","t":"rule"},{"q":"命局中出现「酉丑组合」且与食神制官配合时，常与哪种职业或事件有关？","opts":["海外海运与跨国贸易（如船东）","法律、条文辩护或犯罪相关（如律师）","煤矿开采与地下工程（如矿工）","体育竞技与武术表演（如运动员）"],"ans":1,"exp":"丑库可作法律文书条文，酉丑组合常与法律、犯罪有关，配合食神制官而重自由时多为律师。","sec":"3. 智力取财","t":"xiang"},{"q":"己日主坐丑或未时，别人的东西通常进不来，什么情况下才能进来成为自己的？","opts":["遇到天干透出食神泄秀","遇到六合合住（如子丑合、午未合）","遇到相冲的「钥匙」（如丁癸冲开丑库）","遇到比劫合绊（如甲己合、乙庚合）"],"ans":2,"exp":"己日坐丑未干支一体喜刑冲，别人的东西进不来，唯独「钥匙」冲开库才能进来为己用。","sec":"3. 智力取财","t":"rule"},{"q":"比劫做功效率低的一般体力劳动者，若命局出现「丑与寅暗合」，且丑作阴湿无光之地、金石之库，常对应什么职业？","opts":["证券公司交易员","银行信贷审批员","宾馆服务员或厨师","煤矿工人或开山工人"],"ans":3,"exp":"丑为阴湿无光之地、金石之库，寅丑暗合效率低时，常对应煤矿工人或开山工人。","sec":"4. 体力取财","t":"xiang"},{"q":"分析工薪取财命局时，「食伤、印、官杀、财」四个十神通常分别代表什么？","opts":["技能、单位、被管理、收入","单位、收入、技能、下属","收入、技能、单位、被管理","思想、权力、客户、资本"],"ans":0,"exp":"工薪取财四象：食伤＝技能，印＝单位，官杀＝被管理，财＝收入，且做功效率普遍不高。","sec":"5. 工薪取财","t":"xiang"},{"q":"同为工薪族命局，行运遇「官冲禄」与「财冲禄」在得财上有何本质区别？","opts":["官冲禄与财冲禄都主失业破财","官冲禄不得财，财冲禄反能得财","官冲禄须见比劫帮，财冲禄须见印护","官冲禄能得财，财冲禄反主破财"],"ans":1,"exp":"官冲禄为官克身不得财，须合住；财冲禄则是财进出往来，反而能得财。","sec":"5. 工薪取财","t":"diff"},{"q":"某女命坐支卯禄合申官（乙庚合官带财），以禄作肉体做功，虽能得财（如男子赠房）却为何不能大富？","opts":["乙庚合化金后破印，导致资产全归他人所有","女命忌见官星合禄，只要合禄必主破产负债","以肉体（禄）做功效率低，非大势或制原神","禄神被申金合克，说明一辈子无工作无收入"],"ans":2,"exp":"卯禄作肉体与官带财合做功，能得工薪或他人馈赠，但做功模式本身效率有限，故不能大富。","sec":"5. 工薪取财","t":"calc"}]},{"n":59,"level":"中级","title":"官命看法","qs":[{"q":"按盲派，官命成立的核心要素是什么？","opts":["官星透干通根，且不被合","印星旺而官杀轻，印能生官","日主身旺，官杀受日主承载","官杀与印俱全且有根，有做功"],"ans":3,"exp":"盲派看官命不看日主旺衰，只看官杀、印是否有根并做功，功要落在主位。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀只是天干虚透、地支无根，按盲派怎么看？","opts":["只当名气，大运落实时易当官","只能当小官，大运无关","只主虚名，一生不能当官","照样当官，透干即有权"],"ans":0,"exp":"官杀必须有根；虚透只是名气，但大运把它落实时也易当官。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀、印、伤食做功的字都落在宾位、没有主位的字参与，容易出现什么走向？","opts":["容易走向当官但职位虚","容易走向发财而非当官","容易走向做官后丢官","容易走向灾病而非功名"],"ans":1,"exp":"做功必须有主位的字参与；功落在其他位置，容易走向发财，做不好也转向取财。","sec":"一、官命的核心与总则","t":"rule"},{"q":"官杀与劫刃相配做功，其中「羊刃＋七杀」做功主什么部门？","opts":["检察、法院、法律","带思想文化性的行业","执法、实权、军队","纪检或文官系统"],"ans":2,"exp":"羊刃＋七杀＝执法、实权、军队；申酉做功才偏检法，伤官＋官杀偏纪检，别混。","sec":"一、官命的核心与总则","t":"diff"},{"q":"局中申、酉、丑、寅几个字做功成官命，一般论作哪个部门？","opts":["检察、法院","文化宣传","纪检","公安"],"ans":3,"exp":"申、酉做功偏检察法院法律；再加丑、寅四字齐做功，则论公安。","sec":"一、官命的核心与总则","t":"calc"},{"q":"同样是羊刃（卯）与伤官并见，伤官把羊刃泄掉，主什么？","opts":["主文笔、文官，不带枪","主执法，伤官助刃带枪","主做生意，转而取财","主军队，泄刃反增杀气"],"ans":0,"exp":"刃杀做功是执法军队；伤官泄了羊刃，则转为文笔、文官，刃空亡也不带枪。","sec":"二、制用做功当官","t":"diff"},{"q":"制用、化用做官，哪种效率高、官职大？","opts":["两者效率相同，只看有无根","制用效率高；化用效率低、级别不大","化用官大，制用易因不净反局","化用效率高，生化顺畅官更大"],"ans":1,"exp":"印化官杀只是化走，效率低，级别不大；制用把对方制干净，效率高。","sec":"三、生用化用做功当官","t":"diff"},{"q":"盲派说做功要「制干净」，下列哪种情形才算制到位？","opts":["两字相合，合住即算制","官杀与印同时有根，即算制","真正制住对方，不是对抗不分胜负","两字相冲，冲动即算制"],"ans":2,"exp":"制一定要真正制住对方，对抗不分胜负不算；时上申与卯是合，不叫制。","sec":"一、官命的核心与总则","t":"rule"},{"q":"印戴官帽、以印为用做官，大运或流年把官帽合走，会怎样？","opts":["官帽被摘，但只主官小","官帽被摘，主发财不主丢官","官帽合来更稳，反而升官","官帽被摘，丢官"],"ans":3,"exp":"印为用时怕大运坏印；官帽可摘，合走即丢官。","sec":"三、生用化用做功当官","t":"rule"},{"q":"「官戴财帽子」与「财戴官帽子」，各以什么为主、多是什么职业？","opts":["官戴财帽以财为主，国企经营者；财戴官帽以官为主，管财的官","两者都以官为主，区别只在官职大小","官戴财帽以官为主，行政官员；财戴官帽以财为主，企业经营者","官戴财帽主私企老板；财戴官帽主国企经营者"],"ans":0,"exp":"戴什么帽子就以什么为主：官戴财帽看财象，做企业；财戴官帽看官象，做管财的官。","sec":"五、管财的官与做企业的官","t":"diff"},{"q":"官命里「连体之字」被大运流年坏了，会怎样？","opts":["只主合绊，官位不动","反局，丢官或出事","只主破财，官位不动","解局，官运更通"],"ans":1,"exp":"连体之字不能坏，如辛庚、丙戌，坏了即反局，丢官或出事。","sec":"六、根与虚的要求（总结）","t":"rule"}],"fine":[{"q":"在官命的构成要素中，官杀与印分别主什么？","opts":["官杀主名气，印主财富","官杀主单位，印主下属","官杀主权柄，印主职务","官杀主职务，印主权柄"],"ans":3,"exp":"官命核心必须有官（杀）与印，其中官杀主职务，印主权柄。","sec":"一、官命的核心与总则","t":"xiang"},{"q":"盲派归纳可成官命的六种组合中，若原局无官杀星，下列哪种组合仍可成官命？","opts":["印配财星、印配食伤、印配比禄","财配食伤、财配比禄、食伤配比禄","比肩配劫财、食神配伤官、偏财配正财","比禄配七杀、伤官配正财、劫财配食神"],"ans":0,"exp":"可成官命的六种组合除了官杀配印、伤官、劫刃外，无官杀时还有印配财、印配食伤、印配比禄（官禄格）。","sec":"一、官命的核心与总则","t":"rule"},{"q":"看官命部门特征时，「申、酉做功」与「伤官＋官杀」一般分别对应什么部门？","opts":["前者偏实权部门或纪检，后者偏检察、法院、法律","前者偏检察、法院、法律，后者偏实权部门或纪检","前者偏公安刑侦系统，后者偏国有企业财务","前者偏军队武装执法，后者偏文化教育宣传"],"ans":1,"exp":"申酉做功主检察、法院、法律；伤官＋官杀主实权部门或纪检；羊刃＋七杀主执法、实权、军队。","sec":"一、官命的核心与总则","t":"diff"},{"q":"「食神合印（佩印）」与「伤食旺」两类官命在部门特征上有何细微区别？","opts":["佩印偏军队执法，伤食旺偏公检法纪检","佩印偏金融银行，伤食旺偏房地产开发","佩印带思想文化性，伤食旺偏文化或文官","两者均只做私营企业，不能进入行政系统"],"ans":2,"exp":"食神合印（佩印）主带思想文化性的行业；伤食旺主文化或文官，不一定执法。","sec":"一、官命的核心与总则","t":"diff"},{"q":"日支卯禄遇到月上、时上两个申金，若月柱有午火伤官，判断卯与时上申金的关系应依循什么原则？","opts":["遥合优先，卯先合月上申而不合时申","卯木克土制金，对两申同时构成制用","两申争合卯木，导致卯禄被彻底破坏","近合先合，卯合时上申而不叫制"],"ans":3,"exp":"卯木紧贴时支申金，依「近合先合」原则只合时上申且叫「合」不叫制，月上申则由火围制。","sec":"1. 官杀配伤食","t":"rule"},{"q":"官杀重而伤官轻，形成「捕多贼少」的杀制伤官格局时，喜行何种大运升职？","opts":["行「贼运」（即伤官、食神运）","行印星泄官制伤运","行财星生官助杀运","行官杀更旺的「捕运」"],"ans":0,"exp":"官杀重而伤官轻属「捕多贼少」，须行贼运（水木伤食运等补足被制之贼）才能做功升职。","sec":"1. 官杀配伤食","t":"calc"},{"q":"局中无明官而以官杀库（如戌）当官看，若地支财星（如卯）去合戌库形成「拉」而制不净，通常转向什么？","opts":["成为专职司法辩护律师","容易转向房地产或国有建筑企业","只能靠体力劳动维持普通温饱","必为最高法院或公安刑侦首长"],"ans":1,"exp":"卯财合戌官杀库属于「拉」，制不净且呈木土结构，官职不大或易转向房地产建筑经营。","sec":"1. 官杀配伤食","t":"calc"},{"q":"伤官与羊刃同见时，若出现「卯木羊刃空亡」或「伤官太重破刃」，通常会有何影响？","opts":["羊刃空亡主文官写材料，伤官太重主升至正部级","羊刃空亡更主带枪执法；伤官太重必任军队要职","羊刃空亡不带枪；伤官太重主自由，不愿在执法部门受约束","两者均主因贪腐入狱，一生无官运与财运"],"ans":2,"exp":"卯羊刃空亡则不带枪；伤官太重泄破羊刃且伤官主自由，故不喜约束，多不在执法部门。","sec":"2. 官杀配劫刃","t":"diff"},{"q":"在盲派取象中，哪类做功结构最明显地对应「管军队的军官」？","opts":["木制燥土，且火土为伤官、偏印、正官时","湿土生金，且土金为正官、偏财、比肩时","水木相生，且木火为食神、正印、正财时","火制金，且金水为伤官、七杀、劫财时"],"ans":3,"exp":"火制金为军人象，当金水为伤官、七杀、劫财时军人特征更为明显。","sec":"2. 官杀配劫刃","t":"xiang"},{"q":"某官命同时具备「羊刃库、七杀、官统财」三象，按盲派最贴近哪类职务？","opts":["法院经济庭庭长等管财不管贪财之官","基层煤矿或建筑施工队包工头","文化宣传部或报社总编辑","纯技术研发或医院主治医师"],"ans":0,"exp":"羊刃库配七杀主公检法执法，再带官统财（管财），正合法院经济庭庭长之象。","sec":"2. 官杀配劫刃","t":"xiang"},{"q":"刑警命局中以火土气势（含未七杀）制酉金印星，按盲派如何取「抓犯人」之象？","opts":["酉为阳中之阳＝权柄，阴制阳为印章","酉为阴中之阴＝罪犯，阳制阴为枪象","酉为金石＝银行，未穿酉为清查账目","未为木库＝文书，火生土为调解之象"],"ans":1,"exp":"酉为阴中之阴可象罪犯，火土阳势制酉印，阳制阴带枪象，正合刑警抓犯人。","sec":"3. 印配财星","t":"xiang"},{"q":"同为燥土制水的财库制印库结构，为什么水在原局为「实」与为「虚」时，行戊运、丁运的吉凶截然不同？","opts":["实水行印运必反局，虚水行财运必升官","虚水被合绊后固定不再坏事，实水被合走等于坏了功神","实水被合绊后固定不再坏事，虚水被合走等于坏了功神","实水怕克不怕合，虚水怕冲不怕穿"],"ans":2,"exp":"实水（有根坐支）一合即合绊固定相当于制去；虚水全靠原局去克，遇大运合走反而是坏了功神。","sec":"3. 印配财星","t":"diff"},{"q":"木火有势去亥印（伤官去印得权），但地支同时出现「亥未拱」时，会对权力产生什么影响？","opts":["拱印合财，使权力与财富同时翻倍","拱印生身，使化用效率超越制用","拱印冲官，导致当年立即丢官罢职","拱印分权，导致制不干净、职级难大升"],"ans":3,"exp":"伤官去印本可得权，但亥未拱印等于拱起印来分权，制不干净，职级提升有限。","sec":"4. 印配伤食","t":"calc"},{"q":"关于官命流年应期规律，下列哪项对应关系是正确的？","opts":["冲印主调动，比劫合走自己的位表位被人占","合太岁主丢官，冲财主破产入狱","冲印主发财，禄冲官杀主升职加薪","禄冲财主倒霉，冲官杀主调动升迁"],"ans":0,"exp":"盲派流年规律：禄冲官杀倒霉，冲财得财；合太岁＝亲合；冲印主调动；比劫合走自己的位表位被人占。","sec":"1. 官杀配印，印化官杀","t":"rule"},{"q":"地支见寅、午、戌三字，但中神「午」双现时，能否按三合火局论？","opts":["只要戌在年支，午双现仍可成火局","中神午双现不能成三合局","午双现转为寅戌拱局，不看午火","中神双现力量加倍，仍成三合火局"],"ans":1,"exp":"三合局要求中神唯一，若中神午双现，则寅午戌不能成三合局。","sec":"1. 官杀配印，印化官杀","t":"rule"},{"q":"何谓官命中的「官禄格」？","opts":["年支见禄合官，且时支见食神泄禄","财星生官透干，且禄神入年支墓库","印生禄，且禄在主位当权力","官星坐在禄神上，且见比劫分禄"],"ans":2,"exp":"六种官命组合之一「印配比禄」，即印生禄，禄在主位当权力，称为官禄格。","sec":"2. 印生禄，禄在主位当权（官禄格）","t":"rule"},{"q":"以印为用、印带官帽成官命时，大运最忌讳什么？","opts":["最怕大运合官，合官则转商","最怕大运生印，生印则退位","最怕大运见财，见财则入狱","最怕大运坏印，坏印则丢官"],"ans":3,"exp":"印为用时怕大运坏印，坏印则失去权柄而丢官；官帽被大运流年合走亦主丢官。","sec":"3. 印带官帽子，与主位发生关联","t":"rule"},{"q":"通过印带官帽、中神关联主位而成官命时，若「中神在宾位」，通常对应什么职级位置？","opts":["多主副职","基层普通办事员","无实权的虚职顾问","必为一把手正职"],"ans":0,"exp":"中神落在主位多掌核心正职；中神在宾位时（如年时），往往主副职。","sec":"3. 印带官帽子，与主位发生关联","t":"diff"},{"q":"原局无印星，只是官星透干坐到自己的禄神上做功，一般如何断其身份？","opts":["只能务农或做体力工","多为企业经理人，而非行政官员","必为省部级行政高官","必为公检法实权局长"],"ans":1,"exp":"官命核心须有官杀与印，若无印而官透到禄上，无权柄印信，多是企业经理人。","sec":"3. 印带官帽子，与主位发生关联","t":"calc"},{"q":"某官命「满盘合，又有半个禄且坐劫财」，这种结构最能反映其怎样的做官风格？","opts":["性格刚烈专横，从不听取任何异议","优柔寡断无主见，凡事全凭他人摆布","表面善团结老好人，内有主见不改主张","清高孤傲不合群，只顾个人学术研究"],"ans":2,"exp":"满盘合主老好人、善团结；有半个禄且坐劫财主内有主见，虽会让步但最终不改主张。","sec":"四、其他组合","t":"xiang"},{"q":"私营企业主命局遇官司纠纷时，如何区分是「民事经济纠纷」还是「公检法来闹（刑事/行政）」？","opts":["因财而起是公检法来闹，官被坏才是民事纠纷","印被合是刑事案件，食伤被冲是民事纠纷","只要见驿马逢冲，一律断为公检法刑事案件","因财而起多民事纠纷，官被坏则是公检法来闹"],"ans":3,"exp":"财星合身破大财引起的官司多属民事纠纷；若是原局官星被坏，则是公检法来闹。","sec":"五、管财的官与做企业的官","t":"diff"},{"q":"某命局干支呈现「财戴官帽」，但命局结构是「不用官、反而要去官」，通常对应什么性质的机构？","opts":["自己的私营企业","大型国有银行","法院经济审判庭","政府财政部门"],"ans":0,"exp":"财戴官帽通常为行政管财之官，但若不用官而是去官，则变为自己经营的私营企业。","sec":"五、管财的官与做企业的官","t":"rule"},{"q":"在盲派看子女细象时，教材中提到把子女的什么信息放到「第五柱」来结合命局看？","opts":["子女的姓名笔画","子女的出生年干支","子女的出生时辰","子女的属相纳音"],"ans":1,"exp":"看子女时，可把子女出生年干支放到第五柱来与原局结合，观察合绊、羊刃比劫等象。","sec":"五、管财的官与做企业的官","t":"step"},{"q":"两个命局前三柱完全相同，仅差一个时辰，导致一个当官、一个不当官而去经商，常见决定因素是？","opts":["神煞驿马有无不同，或纳音五行不同","大运顺行逆行不同，或胎元命宫不同","官印虚实不同，或能否合回主位不同","日主身旺身弱不同，或季节寒暖不同"],"ans":2,"exp":"差一个时辰是否成官命，常取决于官印的虚实（虚则化不了/无实权），以及功神能否合回主位。","sec":"六、根与虚的要求（总结）","t":"calc"}]},{"n":60,"level":"中级","title":"婚姻专辑","qs":[{"q":"好婚姻里「宫制星」指夫妻宫的字制去夫妻星。男命、女命各怎么制才算好？","opts":["男命比劫制财，女命伤官制官","男命印星制财，女命食神制官","男命食伤制财，女命比劫制官","男命官杀制财，女命印星制官"],"ans":0,"exp":"宫制星为好婚姻：男命比劫制财、女命伤官制官；但制不住反为坏婚姻。","sec":"一、好婚姻与差婚姻的组合","t":"rule"},{"q":"夫妻宫位合了什么字之外，合其他的星婚姻都不好？","opts":["正偏财与官杀","正偏印与禄","食神伤官与比肩","比肩劫财与印"],"ans":1,"exp":"原文：夫妻宫位合了正偏印与禄之外，合其他的星都婚姻不好。","sec":"一、好婚姻与差婚姻的组合","t":"rule"},{"q":"夫妻宫字对夫妻星「穿」与「冲」，结果有何不同？","opts":["穿冲都必离婚，只是时间不同","冲必离婚或配偶死亡，穿则可以","穿必离婚或配偶死亡，冲则可以","穿冲都只是吵架，不一定离婚"],"ans":2,"exp":"多婚第一条：夫妻宫穿夫妻星，必离婚或配偶死亡；冲可以（冲才是管住）。","sec":"二、多婚的命理","t":"diff"},{"q":"男命正财、女命正官得正位，遇到制它的字，按多婚规则怎么论？","opts":["正偏星都不可制，制则必离","正偏星受制都无妨，有宫就稳","正星可以制，偏星受制婚姻易出问题","偏星可以制，正星受制婚姻易出问题"],"ans":3,"exp":"正星得正位不能制；偏星（偏财、七杀）可以制。","sec":"二、多婚的命理","t":"rule"},{"q":"因夫妻星多现而离婚，婚姻次数按什么数？","opts":["夫妻星有几个就几次","夫妻宫现几次就几次","坏宫之字有几个就几次","坏星之字有几个就几次"],"ans":0,"exp":"因宫被坏离婚，坏宫之物有几个就几次；因星多现离婚，星有几个就几次。","sec":"二、多婚的命理","t":"rule"},{"q":"女命夫宫坐七杀，处正位；月上另有官星拱入夫宫，坐偏位。哪个是正夫？","opts":["月上官星是正夫，七杀为情人","七杀是正夫，官星是偏夫","两者都是正夫","官星是正夫，七杀是偏夫"],"ans":1,"exp":"坐正位的是正夫，坐偏位的是偏夫，不以星的正偏来定。","sec":"二、多婚的命理","t":"calc"},{"q":"夫妻宫占夫妻星之墓，无刑冲克破也易独身，如何开库？","opts":["只能靠天干合，不能刑冲","只能靠大运六合，刑冲反凶","天干钥匙或地支代开，如己丑、戊辰","只能靠地支刑冲，天干无用"],"ans":2,"exp":"开库天干钥匙、地支代开都可（如己未、己丑、戊辰、戊戌）。","sec":"三、独身的命理","t":"rule"},{"q":"「水中捞月」的三个条件是什么？","opts":["正星坐宫、日主与日支自合、天干比劫干扰","偏星坐宫、日主与日支自冲、天干正星干扰","正星坐宫、日主与时支自合、天干偏星干扰","正星坐宫、日主与日支自合、天干偏星干扰"],"ans":3,"exp":"符合者眼界高、理想主义，遇到的对象总不如意，独身。","sec":"三、独身的命理","t":"rule"},{"q":"下列日柱中，哪个是「自合坐正星」的水中捞月日柱？","opts":["丁亥","丁巳","壬子","己巳"],"ans":0,"exp":"自合坐正星的日柱：丁亥、己亥、戊子、辛巳、壬午、癸巳（甲午不一定）。","sec":"三、独身的命理","t":"calc"},{"q":"结婚应期里，天干配偶星逢太岁相合，要想定为应期还须什么前提？","opts":["配偶星必须被冲，再逢合","配偶星有根得旺，不能无根虚浮","配偶星必须入墓，逢合开库","配偶星必须无根，逢合才动"],"ans":1,"exp":"配偶星无根虚浮，逢合即制即坏，不能定为应期。","sec":"四、结婚应期","t":"rule"},{"q":"夫宫亥与夫星寅原本相合、被牵绊，结婚应期该看哪年？","opts":["子年或卯年，再合亥寅","午年或戌年，半合寅木","巳年或申年，冲开亥寅之合","亥年或寅年，伏吟加强合力"],"ans":2,"exp":"宫或星原有合被牵绊，应在冲其合的年份，冲合中任一方都行；巳冲亥、申冲寅。","sec":"四、结婚应期","t":"calc"},{"q":"盲派看结婚应期，太岁管什么？","opts":["只管婚姻好坏，不管应期","太岁为杀则婚姻必差","应期与婚姻好坏都管","只管结婚应期，不管婚姻好坏"],"ans":3,"exp":"太岁管应期，不管婚姻好坏；婚姻质量看八字与大运配合。","sec":"四、结婚应期","t":"rule"}],"fine":[{"q":"八字男命无财、女命无官杀时，盲派看配偶星应分别改看什么？","opts":["男命无财看伤食，女命无官杀看印","男命无财看比劫，女命无官杀看伤食","男命无财看官杀，女命无官杀看比劫","男命无财看印星，女命无官杀看财星"],"ans":0,"exp":"男命以财为妻，无财看伤食；女命以官杀为夫，无官杀看印，且全篇均以配偶宫为主、星为辅。","sec":"一、好婚姻与差婚姻的组合","t":"rule"},{"q":"好婚姻第一种组合「夫妻宫安静」，其完整要求不包括下列哪项？","opts":["不六合或暗合配偶星以外的星","夫妻宫必须透出天干与日主五合","宫有用而不被刑、冲、破、穿","夫妻宫不杂透、不多现"],"ans":1,"exp":"「夫妻宫安静」指宫有用且不被刑冲破穿，不合配偶星以外的星，不杂透、不多现。","sec":"1. 好婚姻的三种组合","t":"rule"},{"q":"在判断好婚姻的「禄」与「桃花」象义时，男命与女命见「官星合禄」有何差异？","opts":["男女命见官星合禄一律主终身独身","男命官星合禄为禄绊桃花，女命见禄则必多婚","女命官星合禄为禄绊桃花，男命比劫制官杀且星静则无桃花","女命官星合禄主无桃花，男命见食神合禄主外遇"],"ans":2,"exp":"女命禄为身体，官杀（如癸合巳禄）合禄主禄绊桃花；男命无财以食为妻、比劫制官杀且星静则无桃花。","sec":"1. 好婚姻的三种组合","t":"diff"},{"q":"「比劫争夫」的婚姻问题，按盲派归纳有五种可能，下列哪项不在这五种之内？","opts":["找的是离过婚的，或老公有外遇","因第三者插足而最终离婚","自己当小的或被包，或曾经的对象","配偶必定先丧偶后再婚"],"ans":3,"exp":"比劫争夫五种可能：找离过婚的、老公有外遇、自己当小的或被包、离婚、曾经的对象。","sec":"2. 差婚姻的三种组合","t":"rule"},{"q":"同为夫妻宫多现，为什么「癸丁丁丙／卯巳巳午」断两次婚，而「癸丁丁乙／卯巳巳巳」却不离？","opts":["前者巳午正偏混杂，后者宫虽多但没杂","前者年支卯破午，后者卯巳相生","前者丙火透干克金，后者乙木生火","前者无财星，后者有乙木印星护妻"],"ans":0,"exp":"宫多现若兼杂现（如巳午正偏混杂）则多婚；宫虽多现（如三巳）但未杂且未坏，婚不会离。","sec":"2. 差婚姻的三种组合","t":"diff"},{"q":"某男命妻宫坐丑库，月支与时支皆为酉金财星入丑墓（一宫两星），应如何判断？","opts":["必与第一任离婚后才能娶第二任","一妻一妾（妻与情人），宫未坏故不离","酉金入墓不开，主终身无妻","必克死两任妻子，终生孤老"],"ans":1,"exp":"一宫两星（如丑宫收两酉财，月上为妻、时上为情人有先后），只要妻宫未坏，往往一妻一妾而不离。","sec":"2. 差婚姻的三种组合","t":"calc"},{"q":"盲派断婚姻桃花时，男命与女命看桃花的十神常用口诀对应分别是？","opts":["男命比肩为桃花，女命常看食神透年干","男命七杀为桃花，女命常看偏印坐日支","男命食伤为桃花，女命常看禄合或比劫争合","男命正印为桃花，女命常看正官合日主"],"ans":2,"exp":"盲派口诀明确指出「男命食伤为桃花」，而女命常见禄绊桃花或财多/官杀混杂。","sec":"二、多婚的命理","t":"xiang"},{"q":"命局中出现「两宫一星带合」（不论三合、六合或暗合），男女命通常应断为几次婚姻？","opts":["三次以上婚姻","一次婚姻白头到老","终身独身无婚","两次婚姻"],"ans":3,"exp":"口诀「两宫一星带合（三合、六合、暗合都是）＝两次婚姻，男女同看」。","sec":"二、多婚的命理","t":"calc"},{"q":"计算多婚命局的婚姻次数时，对于「与夫妻宫毫无关联」或「合而不入宫」的关系，通常怎么处理？","opts":["只同居不算婚，不计入正式婚姻次数","只算第一次正式婚姻，其余全不算","按大运数量加倍计算婚姻次数","全部计入正式婚姻次数，且必办酒席"],"ans":0,"exp":"数次规则：宫、星每现计一个，合出计一个；与宫无关联的只同居不算婚。","sec":"二、多婚的命理","t":"rule"},{"q":"夫妻宫坐夫妻星却又「他合」（六合、暗合他字）时，容易产生什么结果？","opts":["合而化喜，配偶更加忠诚专一","一合就容易把配偶合走，主多婚或离异","主晚婚但一旦结婚永不分离","合主留住，哪怕被穿也不会离婚"],"ans":1,"exp":"多婚第三条：夫妻宫落夫妻星时，不喜他合（六合、暗合），一合就容易合走（正星得正位尤甚）。","sec":"二、多婚的命理","t":"rule"},{"q":"女命原局无明夫星，直到走大运官杀时才遇到的丈夫，在盲派中称作什么？","opts":["暗合正夫，绝不分离","天定良缘，白头偕老","过运夫妻，运过即完","禄印相随，夫富妻贵"],"ans":2,"exp":"大运官杀有夫星（原局无或已败）叫「过运夫妻」，意指该步大运一过婚姻就结束。","sec":"宫穿星，必离（带副宫）","t":"xiang"},{"q":"在多婚数次中，若局中出现两个相同的配偶星字（如年干甲与时干甲），在什么情况下不当同一人看？","opts":["只有在月柱与日柱透出同字时才不当同一人","只要天干字相同，无论在哪一柱都当同一人","只要坐支五行不同，就一定当作同一个人","宫位相差太远（如年与时）或一个与宫穿一个与宫不穿"],"ans":3,"exp":"宫位相差太远的两个同字（如年干甲与时干甲，且坐支与妻宫作用不同）不当同一人，分计多次。","sec":"男命多婚例","t":"diff"},{"q":"多婚命局里除了日支正宫外，其他充当配偶宫的「副宫」，一般表示该段婚姻具有什么特征？","opts":["表示这段婚姻较为短暂","表示这段婚姻最为长久白头","表示配偶必然出身豪门巨富","表示一定会有双胞胎子女"],"ans":0,"exp":"正宫主长久正位，而「副宫表示短暂」（如辰为副宫而子为正宫）。","sec":"男命多婚例","t":"xiang"},{"q":"关于独身命的三种现实表现情形，下列哪项不在盲派所列的三种情形之中？","opts":["有性伙伴但不结婚","一生结过多次婚且每段都很长久","一生独身且无性伙伴","有过短暂婚史，最后独身"],"ans":1,"exp":"独身的三种情形：①一生独身且无性伙伴；②有性伙伴但不结婚；③有过短暂婚史，最后独身。","sec":"三、独身的命理","t":"rule"},{"q":"独身命夫妻宫的第一类先天毛病「夫妻宫与子女宫占比劫、禄神或印」，为什么难成婚或难有子？","opts":["比劫禄合住官杀，使配偶星永远留在宾位发财","印星生旺伤官，导致夫妻宫被彻底冲破","比劫禄伤妻耗官杀，印夺食难有子女，配偶星进不去","比劫禄生旺财星，导致配偶过于挑剔不愿结婚"],"ans":2,"exp":"夫妻宫与子女宫占印、比、禄时，比劫禄克财耗官、印夺食难有子女，使配偶星进不去宫。","sec":"三、独身的命理","t":"rule"},{"q":"女命若出现「子女宫与夫妻宫都是印」，或「局中有两个印」时，盲派口诀通常怎么断？","opts":["宫都是印主子女众多，两个印主白头到老","宫都是印主夫权极重，两个印主丈夫早逝","宫都是印主头胎必生子，两个印主终身不嫁","宫都是印主无子女，两个印主两次婚姻"],"ans":3,"exp":"盲派口诀：「子女宫与夫妻宫都是印，无子女。两个印为两次婚姻。」","sec":"三、独身的命理","t":"rule"},{"q":"下列哪组日柱全部属于「自合坐正星」的水中捞月候选日柱？","opts":["丁亥、己亥、戊子、辛巳、壬午、癸巳","丙午、丁未、戊申、己酉、庚戌、辛亥","庚申、辛酉、壬戌、癸亥、甲寅、乙卯","甲子、乙丑、丙寅、丁卯、戊辰、己巳"],"ans":0,"exp":"自合坐正星日柱共六个确定日柱：丁亥、己亥（男女都是）、戊子、辛巳、壬午、癸巳（甲午不一定）。","sec":"水中捞月","t":"calc"},{"q":"原局完全符合「水中捞月」三条件，但行某步大运时却意外结婚了，往往是因为大运起了什么作用？","opts":["大运使夫妻宫彻底入墓且不再逢冲","大运坏掉了水中捞月格局的某一环","大运加强了日柱天地自合的力量","大运透出了比原局更旺的偏星干扰"],"ans":1,"exp":"当大运能坏掉水中捞月格局的某一环（如壬运合去丁偏星，亥年冲巳），打破理想牵绊即可成婚。","sec":"水中捞月","t":"diff"},{"q":"判断早婚与晚婚时，下列哪组原局特征一般提示「晚婚」？","opts":["配偶星在月干透出有根，且与日主紧贴五合","配偶星在年月，日支坐印绶且无刑冲破害","配偶星在日时，女命年月伤食旺，男命年月比劫旺","配偶星在年月，女命年月官杀旺，男命年月财星旺"],"ans":2,"exp":"早晚婚参考：配偶星在年月＝早婚，在日时＝晚婚；女命年月伤食旺、男命年月比劫旺均主晚婚。","sec":"四、结婚应期","t":"rule"},{"q":"地支合入配偶宫作为结婚应期，主要通过哪两种具体形式实现？","opts":["流年天干合走日主；或地支伏吟配偶宫","太岁与比劫合入年柱；或太岁与印星合入时柱","太岁刑开日支；或大运穿倒年支配偶星","太岁与配偶星合入宫中；或原有星宫半合，太岁补成三合"],"ans":3,"exp":"配偶星地支合入配偶宫两种类型：①太岁与配偶星合入宫中；②原有配偶星与宫半合，太岁补成三合。","sec":"1. 配偶星地支合入配偶宫（三合、六合）","t":"rule"},{"q":"男命甲子年（太岁妻星合入命中且合入妻宫）与女友同居但未领证，若妻位辰土印绶正好「空亡」，如何取象？","opts":["印代表结婚证，印空亡故为「无证经营」","印代表婚房，印空亡故结婚后必须租房住","印代表妻子本人，印空亡故必定一生无妻","印代表岳父岳母，印空亡故父母坚决反对"],"ans":0,"exp":"印＝结婚证，印绶在妻位空亡而星宫已合，表现为事实同居但未领证；婚姻实质是共同生活。","sec":"2. 配偶星逢天干五合","t":"xiang"},{"q":"婚姻应期中，「合处逢冲」与「入墓逢刑冲」分别针对原局的哪种状态？","opts":["两者均只针对比劫争夫，与合墓无关","前者针对宫或星原有合被牵绊，后者针对宫或星入墓不开","前者只看大运不看流年，后者只看流年不看大运","前者针对宫或星入墓不开，后者针对宫或星原有合被牵绊"],"ans":1,"exp":"宫或星逢刑冲应婚分两类：①原有合被牵绊，冲其合为应期；②宫或星入墓，刑冲其墓或冲被墓之神为应期。","sec":"3. 配偶宫或星逢刑冲","t":"diff"},{"q":"男命「丁癸己己／未卯卯巳」，癸卯带象，妻星癸水随卯木入了年上未墓，若要破墓成婚需原局有何条件？","opts":["只要天干再透出戊土合癸即可成婚","只要大运再见卯木伏吟即可自然成婚","如坐下是酉冲卯（冲开未库）才可成婚","只要日主坐下巳火生土即可开未墓"],"ans":2,"exp":"癸卯带象入年上未墓不开则无婚；若原局有酉冲卯等于冲开未库（或己坐巳等），则可成婚。","sec":"3. 配偶宫或星逢刑冲","t":"calc"},{"q":"按盲派总纲，离婚应期年份的核心机理是什么？","opts":["宫与星完全无作用，各自安静不动的年份","印星透干生助日主、官杀入墓的年份","太岁与日主天合地合、星宫齐聚的年份","宫与星发生对抗，且宫无法制星或对抗达到平衡之年"],"ans":3,"exp":"离婚年份多是宫与星发生对抗；当宫来制星却无法制住，或双方力量对抗平衡时，便是离婚应期。","sec":"五、离婚应期","t":"rule"},{"q":"下列哪项不属于盲派归纳的离婚应期常见触发情形？","opts":["太岁将配偶星三合六合引入安静的夫妻宫","大运或太岁刑坏、穿坏夫妻宫","宫穿星之字逢冲合引动，或比劫争夫之字出现","夫星被引动、力量加强到宫无法制"],"ans":0,"exp":"离婚常见触发：大运太岁刑穿坏宫；夫星加强到宫无法制；宫穿星之字被引动；比劫争夫之字出现。","sec":"五、离婚应期","t":"rule"},{"q":"对于已经离异的命局，要推算其「下一次婚姻」的情况（如配偶好坏、何时出现），应依据什么来判断？","opts":["只看离婚当年流年干支的纳音五行","看原局中代表下一次的宫星关系","把第一任配偶的八字直接当作第二任","完全抛开原局，只看下一步大运的十神"],"ans":1,"exp":"已经离的命，原局的宫星关系决定下一次婚姻（如前婚已败，第二次看时支或第二个星）。","sec":"五、离婚应期","t":"step"}]},{"n":61,"level":"中级","title":"学历与牢狱","qs":[{"q":"按盲派，判断学历的「学历之神」和「破坏学历之神」分别是哪些？","opts":["印、食神、财；破坏的是官杀、比劫","官杀、印、食神；破坏的是财、伤官、比劫","印、财、食神；破坏的是官杀、伤官、劫","官杀、印、伤官；破坏的是财、食神、比劫"],"ans":1,"exp":"学历之神是官杀、印、食神；破坏者是财、伤官（无制）、比劫。","sec":"一、学历：判断的神","t":"rule"},{"q":"盲派看学历，印星必须满足什么条件才表示有学历？","opts":["必须有根，无根则文化浅","必须旺相，弱则文化浅","必须做功，不做功是懒惰不好学","必须透干，藏支不表学历"],"ans":2,"exp":"印是学业、本事，必须做功才表示学历；不做功＝懒惰不好学、笨、不开化。","sec":"一、学历：判断的神","t":"rule"},{"q":"伤官对学历的影响，哪种配置才学有所成？","opts":["伤官旺而无制，聪明自成","伤官配财，财生官杀","伤官配比劫，聚众成势","伤官配印做功，或配官杀做功"],"ans":3,"exp":"伤官聪明但不守规矩；配印、配官杀做功学有所成；伤官配财、配比劫则不学习，伤官无制学历难高。","sec":"一、学历：判断的神","t":"diff"},{"q":"按盲派的文理象法，数学、化学、法律各取什么字？","opts":["数学取戌亥庚申；化学申子辰；法律申酉加丑","数学取戌亥庚申；化学申酉加丑；法律申子辰","数学取寅卯配火；化学申子辰；法律申酉加丑","数学取申子辰；化学戌亥庚申；法律寅卯配火"],"ans":0,"exp":"戌主数学、亥为数字，庚申亦属数学；化学为申子辰结合；法律为申酉金加丑。寅卯配火主中文。","sec":"一、学历：判断的神","t":"xiang"},{"q":"盲派判断学历的步骤，正确顺序是什么？","opts":["先看日主旺衰，再看印官杀食神，后看大运","先看印官杀食神做功，再看破坏之神，后看大运","先看大运配合，再看印官杀食神，后看破坏之神","先看破坏之神，再看印官杀食神，后看大运"],"ans":1,"exp":"先看印与官杀、食神哪个做功，再看财、比劫、伤官有没有坏印，最后看大运是否配合。","sec":"一、学历：判断的神","t":"step"},{"q":"按盲派，「阴制阳」的牢狱信号里，阴的地支是哪几个？","opts":["子、丑、亥","亥、子、未","亥、丑、辰","辰、戌、丑"],"ans":2,"exp":"亥水、丑土、辰土是十二支中阴的地支，有牢狱象；阳性的有用之物被这些坏了可能牢狱，阳制阴不为牢狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派说比劫与伤官同见，会出现什么犯罪倾向？","opts":["只主口舌是非，不犯法","暗中策划，必由官星指认","单打独斗，偷盗为主","结伙拉帮，再与官杀对抗必牢狱"],"ans":3,"exp":"劫财伤官组合主结伙违法（拉帮结派），再与官杀对抗必牢狱，是黑道的一种组合。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"伤食与官杀，哪种关系才是犯罪结构？","opts":["对抗，制去了就不是","制服，制得越干净越凶","相生，伤食生官杀","相合，伤食合官杀"],"ans":0,"exp":"犯罪是伤食与官杀对抗，注意是对抗而不是制；制去了就不是。","sec":"三、牢狱之灾的看法","t":"diff"},{"q":"伤官与官杀不和的犯罪结构，在什么年份才应牢狱之灾？","opts":["大运交脱之年","官星出现之年","日主逢冲之年","比劫出现之年"],"ans":1,"exp":"食伤得旺自以为是，但必须官出现之年才产生牢狱之灾，官星不出现时不会意识到官的厉害。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派说牢狱的核心机制「反局」，是原局的什么变成了什么？","opts":["原局的生，被运岁变成克","原局的合，被运岁冲开","原局的冲、制，被运岁变成合","原局的刑，被运岁变成合"],"ans":2,"exp":"原局本是制（冲、制）的结构，大运流年把它变成合（冲制不喜合，合则反）就是反局，大部分主牢狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"按盲派，辰运入狱，哪种情形算出狱？","opts":["辰丑相破，辰库被晦","辰戌冲，开辰库","辰辰自刑，辰库被穿","辰酉合，闭辰库"],"ans":3,"exp":"牢狱为库者冲穿坏库为出狱；辰运入狱则辰酉合闭辰库亦为出狱。","sec":"三、牢狱之灾的看法","t":"rule"},{"q":"盲派看出狱，哪个情形可以判断出狱？","opts":["日主得禄之年，或合出冲出日主","日主入墓之年","官星被克去之年","印星得旺之年"],"ans":0,"exp":"日主得禄之年，或日主被合出、冲出之年出狱；牢狱为库者冲穿坏库、辰库被酉合闭也出狱。","sec":"三、牢狱之灾的看法","t":"rule"}],"fine":[{"q":"在看学历时，财星通常是最忌的「破坏之神」，但在什么特殊情况下财星反主有上进之意？","opts":["原局比劫林立，需要财星耗比劫时","原局印星太旺，需要财星克印时","原局七杀无制，需要财星生七杀时","原局食神透干，需要财星泄食神时"],"ans":1,"exp":"财为欲望之星，一般学习最忌（心乱、贪恋女色金钱）；唯印太旺需财克印时，反主有上进之意。","sec":"1. 各神的含义","t":"diff"},{"q":"论及学历中的「官杀」，正官与七杀的含义及七杀成材的条件分别是什么？","opts":["官杀只主体育技能，与文化学历高低毫无关系","正官主聪明勤奋，七杀只主懒惰散漫；杀须生旺不能制","官杀为身份，七杀兼主聪明勤奋；杀须配印或被制服，无制化反凶顽","七杀只要虚透天干不加制化，必然考取博士"],"ans":2,"exp":"官杀是身份象征，七杀还有聪明与勤奋之意；杀要么配印，要么被制服，无制化反主凶顽。","sec":"1. 各神的含义","t":"diff"},{"q":"在文理学科取象中，除「金水主理、木火主文」外，一般把哪个十神直接对应为「理科」？","opts":["比劫（同时正财多主中文或外语）","劫财（同时枭神多主中文或外语）","偏财（同时羊刃多主中文或外语）","官杀（同时食神多主中文或外语）"],"ans":3,"exp":"文理细象：金水主理、木火主文；官杀主理科；寅卯配火主中文，食神多为中文或外语。","sec":"2. 文理区别","t":"xiang"},{"q":"判断一个人具体能读到什么学历，盲派「从格局到象到事」的思考路径是？","opts":["先定格局高低，再看象（文理方向），再落到具体学历","先定文理方向，再看流年桃花，最后看格局","先看年柱纳音，再定日主强弱，再定学历高低","先背大运神煞，再定五行旺衰，再猜文理方向"],"ans":0,"exp":"判断学历须依「从格局到象到事」：先看做功格局定高低，再看象定文理，最后落到具体学历。","sec":"3. 学历判断的步骤","t":"step"},{"q":"某甲木日主为「死木」，原局印星（水）无根虚透天干，按盲派应如何判断其学历？","opts":["印虚无根主毫无文化，小学难毕业","死木喜印虚，印虚透反而学历高","死木必须印星旺相有根，虚透只主懒惰","死木最怕见印虚透，必中途辍学"],"ans":1,"exp":"死木喜印虚，印虚透且格局清纯时，往往学历高（如考入重点大学）；杀星忌但不贴身虚透亦吉。","sec":"1. 学历高","t":"rule"},{"q":"乙木日主见「亥水入辰墓」且辰酉相合，若命主学历极高（如博士），此处的「辰（印墓）」多取何象？","opts":["看守所或监狱等司法羁押场所","大型商场或集市贸易门面","学术机构（如高校、科研院所）","煤炭矿井或地下采石施工场地"],"ans":2,"exp":"印主学问文化，当印或食神入辰印墓且组合有功无反局时，辰为印墓＝学术机构。","sec":"1. 学历高","t":"xiang"},{"q":"八字呈现「金白水清」且正官配印有功，考学竞赛极其突出，此类命局在现实中常有何种短板？","opts":["只爱打架斗殴，完全不能参加考试","极度贪恋财色，中年必定因贪入狱","性格孤僻绝情，一生必然独身无子","只会考试不会做事，且身体往往较差"],"ans":3,"exp":"正官配印、金白水清主极善考试（如奥赛保送），但金水偏于纯理静思，常表现只会考试不会做事、身体较差。","sec":"1. 学历高","t":"calc"},{"q":"财星在命理中不同年龄段有不同含义，盲派如何区分「年幼看财」与「长大看财」？","opts":["财在年幼表才华（有制可当学历），长大表发财","财在年幼与长大都只表好色贪玩，绝不当学历","财在年幼表发大财，长大表有文凭才华","财在年幼必主克父，长大必主克妻"],"ans":0,"exp":"看原局学历时，财在年幼表才华，长大表发财；正偏财在特殊情况下（有制）也可当学历看。","sec":"2. 学历低或中途停学","t":"diff"},{"q":"原局「伤官太旺、无印制服」的人，在学历与文凭发展上通常呈现什么规律？","opts":["聪明且守规矩，少年最喜财星生伤官","聪明但学历不高，若有官或后运印制可后补","少年必然一路保送博士，无需大运配合","笨拙不开化，一生绝对不可能再补文凭"],"ans":1,"exp":"「聪明莫过伤官」，伤官旺而无印制时学历难高、常中途中断；若印制伤之运来得晚或局中有官，多后补文凭。","sec":"2. 学历低或中途停学","t":"rule"},{"q":"某女命印星不怎么做功、少年不行官运，且原局见「申入丑墓」，最终读了护士学校，其中「申入丑墓」取何象？","opts":["法律法院之象","军校武装之象","医院之象","煤矿窑洞之象"],"ans":2,"exp":"丑为阴暗救治之地，申入丑墓可取医院之象，配合小功而不高之格局，对应护士学校毕业。","sec":"2. 学历低或中途停学","t":"xiang"},{"q":"在牢狱五类基本信号中，「枭神夺食」为什么直接对应牢狱之灾？","opts":["食神代表公检法官员，被枭神克夺等于杀官","枭神代表监狱高墙，只要命中见枭神必坐牢","枭神是正财之原神，被食神克夺等于破产入狱","食伤是重要做功之神，被夺等于失去自由"],"ans":3,"exp":"食伤为自由与思想表达，是重要做功之神，被枭神克夺即意味着「失去自由」，主牢狱。","sec":"1. 五类基本信号","t":"rule"},{"q":"同为五行相制，「阳制阴」与「阴制阳」在牢狱判断上有何本质区别？","opts":["阳制阴不为牢狱，阴坏阳性有用之物才牢狱","阳制阴主民事拘留，阴制阳主升官发财","阴制阳不为牢狱，阳制阴才主重罪牢狱","无论阴制阳还是阳制阴，只要相克都主牢狱"],"ans":0,"exp":"亥、丑、辰是阴之地支，阳性的有用之物被这些阴支坏了（阴制阳）才可能牢狱；阳制阴不为牢狱。","sec":"1. 五类基本信号","t":"diff"},{"q":"盲派口诀「比劫本是无知物，一遇伤官势必归」揭示了什么犯罪心理与行为机制？","opts":["比劫见伤官会互相克制，导致犯罪分子内讧自首","比劫生伤官染上不法心性，众人拉帮听伤官","伤官见比劫会失去主见，一切听从正官的约束","比劫见伤官必定转而用功读书，成为学术带头人"],"ans":1,"exp":"比劫本无知，一遇伤官便去生伤官、带伤官心性，群比听从伤官号令，容易形成拉帮结派违法。","sec":"2. 犯罪的特征","t":"rule"},{"q":"盲派如何从十神与宫位上识别「小偷」的典型组合？","opts":["食神为手、偏印为盗贼，食印在月柱相合","正印为手、正财为盗贼，印财在年柱相生","劫财为手、官为盗贼，劫财与官在主位组合","七杀为手、羊刃为盗贼，杀刃在时柱相冲"],"ans":2,"exp":"盲派象法：「劫财为手，官为盗贼，劫财与官在主位组合＝小偷」。","sec":"2. 犯罪的特征","t":"xiang"},{"q":"关于「冲合反局」与「流年局部反局」，下列说法哪项符合盲派论述？","opts":["流年搅局比大运反局刑期更长，通常判无期","冲合反局只破财不主牢狱；大运反局时间更短","冲合反局指年柱合月柱冲；流年搅局绝不坐牢","冲合反局指主位冲宾位合；流年搅局也可坐牢"],"ans":3,"exp":"「主位逢冲，宾位合」属冲合反局；大运反局多长刑，而「流年局部反局（搅局）也可坐牢，但时间短」。","sec":"3. 反局：入狱的核心机制","t":"diff"},{"q":"当牢狱在命局中体现为「墓库」（如辰、丑库）时，除了辰酉合闭辰库外，还有哪种库的变化主出狱？","opts":["冲、穿坏了该牢狱之库为出狱","天干透出比劫生助该库时为出狱","流年再见同类墓库伏吟加倍为出狱","地支再三合拱起该库力量时为出狱"],"ans":0,"exp":"出狱机制中，若牢狱为库者，冲、穿坏了库即为出狱；若辰运入狱，辰酉合闭辰库亦为出狱。","sec":"4. 出狱的看法","t":"rule"},{"q":"某抢劫犯命局「比劫与寅中伤官成势」拉帮结派，为什么伤官「藏在寅中不透干」能断出「主谋不是他」？","opts":["只要地支有寅木，就说明全部犯罪都是他一人独行","伤官主谋略，藏在地支未透干表主谋是别人","伤官不透干代表根本没有发生抢劫行为","伤官藏在地支代表他自己策划周密、绝不暴露"],"ans":1,"exp":"伤官主想法主谋，藏在寅中未透出且伴劫财成势拉帮结派，说明他是随众参与，主谋不是他。","sec":"1. 比劫伤官怕见官","t":"xiang"},{"q":"官员命局出现「年上七杀太重无制又坐财库」，同时「月令劫财库冲开财库」，这种结构最容易因何入狱？","opts":["因伪造医疗药品或假烟商标而入狱","因街头斗殴聚众抢劫银行而入狱","通过劫财方式贪污受贿取财而犯罪入狱","因替朋友担保炒股亏损而民事欠债"],"ans":2,"exp":"七杀无制本是犯罪结构，月令劫财库冲财库即「通过劫财方式取财」，在官命上多应贪污受贿入狱。","sec":"3. 因财、贪污入狱","t":"calc"},{"q":"在杀人重罪命例（如乙乙庚丙／酉酉寅戌）中，地支「戌」常被取作什么具体物象？","opts":["学术图书馆","渔船码头","银行金库","火库、枪库"],"ans":3,"exp":"戌为火库，在重罪杀人命例中可取枪库之象；羊刃酉金穿戌杀库且羊刃众与官杀对抗，主杀人。","sec":"4. 杀人、重罪","t":"xiang"},{"q":"盲派论甲木体性时，在「甲为死木」的命局结构中（如甲木禄冲制年上七杀申），最怕见到什么？","opts":["甲为死木，怕长生（如亥）或七杀申到齐","甲为死木，最怕见庚辛金虚透","甲为死木，最怕见丙丁火泄秀","甲为死木，最怕见干燥戊戌土"],"ans":0,"exp":"教材明确点出「甲为死木，怕长生」，死木见长生易坏或受克，逢七杀申运及亥月往往应重灾。","sec":"4. 杀人、重罪","t":"rule"},{"q":"在诈骗与牢狱的断法中，若原局「食伤虚透且杂现」，同时行辰运「食神入墓」，分别主何象？","opts":["虚透杂现为沉默寡言，食神入墓为发大财亿万","虚透杂现为骗子，食神入墓为失去自由","虚透杂现为执法干警，食神入墓为升职调动","虚透杂现为学术大师，食神入墓为考入重点大学"],"ans":1,"exp":"食伤虚透为胡说八道，杂现为骗子结构；而食神入辰墓则表示失去自由、不能与外界联系（入狱）。","sec":"4. 杀人、重罪","t":"xiang"},{"q":"原局「杀库制食神库」本为当大官之命，为何一走「甲（官）辰」大运却反而遭遇十年牢灾？","opts":["因为官命绝不能走官杀大运，见官必主牢狱十年","因为甲木克尽了辰土，导致原局彻底失去印星护身","甲合身使原本要去制别人的反了，且辰收丑土藏起来成反局","因为食神库最怕见到比劫帮身，见比劫必入狱"],"ans":2,"exp":"本是杀库制食神库，走甲辰运时甲官合身（去制反变合）、辰又收丑库藏起被制之神，双重反局致牢灾。","sec":"5. 大运反局、流年搅局","t":"calc"},{"q":"小偷命局「辛丙己甲／亥申丑戌」中，时上戌比劫被金水反刑坏，其「用手偷」且「跟官对着干」的象义如何得来？","opts":["日主己土为嘴，丑土为文书＝诈骗签合同","月令申金为车，丙火为枪＝持枪抢劫车辆","年上亥水为脚，辛金为刀＝用脚踢门抢劫","比劫在时为手，甲己合又刑坏戌＝用官坏官"],"ans":3,"exp":"比劫在时（门户）主手，代表用手偷；天干求官（甲己合）而地支反局用官坏官＝跟官对着干。","sec":"6. 小偷与盗贼","t":"xiang"},{"q":"某专偷自行车和摩托车的小偷命局「乙己庚己／酉卯子卯」，其作案对象为何对应「自行车、摩托车」？","opts":["酉劫财在年上主腿脚，且卯酉冲反局","己土在月干主房屋田宅，主入室盗窃古董","子水在日支主游泳船只，子卯破主偷窃渔船","乙木在年干主花草树木，乙庚合主盗伐林木"],"ans":0,"exp":"酉金在年上主腿脚、车辆，以酉劫财与卯冲对抗反局、金见水沉，故对应专偷自行车和摩托车。","sec":"6. 小偷与盗贼","t":"xiang"}]},{"n":62,"level":"中级","title":"实战演示","qs":[{"q":"盲派读八字，天干与地支各代表什么？读盘的先后怎么做？","opts":["天干地支都是象，先看月令再看其他字","天干为形，地支为象；先看地支再用天干落实","天干为象，地支为形；先看天干再用地支落实","天干为用，地支为体；先看日支再看年柱来"],"ans":2,"exp":"「在天成象，在地成形」：四个天干为象、四个地支为形；看天干定性质，用地支落实。","sec":"一、修为的两个来源","t":"diff"},{"q":"论大运时「原局是车，大运是路」，原局不好而大运好，结果如何？","opts":["不会好，原局不好大运好也没有用","好运可延续一生，不会随运消退的","只在原局应期的流年里才能够好起来","也能在该运中好，但运过即完"],"ans":3,"exp":"原局不好、大运好，可以在此运中好，但运一过就完，这种情形不多见。","sec":"六、流年应期的三条规则与长篇示范","t":"diff"},{"q":"流年既有原局应期、又有大运应期时，怎样取舍？","opts":["原局应期优先；已发生作用则以大运为主","大运应期优先于原局应期，不分先后","只看流年干支，不再分原局和大运了","两者同等重要，需要同时一起来论"],"ans":0,"exp":"规则：流年的原局应期优于大运应期；若原局应期已发生了作用，则以大运为主。","sec":"六、流年应期的三条规则与长篇示范","t":"diff"},{"q":"天干透出的字，「实」与「虚」遇合，结果有什么不同？","opts":["实的合走后成化；虚的合住后反而成制","实的一合即固定为制；虚的一合走而坏功","虚实都一样，合了就一律按照合绊来论","实的一合被合走而坏功；虚的一合固定即制"],"ans":1,"exp":"实则合了固定住＝制；虚则被合走＝坏功。朱镕基造与袁世凯造的差别就在虚实。","sec":"二、实战步骤（提炼）","t":"diff"},{"q":"阴制阳与阳制阴，各主什么象？","opts":["阴制阳主枪象；阳制阴（亥丑辰）主牢狱象","阴制阳与阳制阴，一概都只主牢狱象","阴制阳（亥丑辰）主牢狱象；阳制阴主枪象","阴制阳主文职之象；阳制阴主武职之象"],"ans":2,"exp":"阴实阳虚，阴制阳（亥丑辰）为牢狱象，阳制阴为枪象。","sec":"二、实战步骤（提炼）","t":"diff"},{"q":"戊日主与己日主，各偏重什么，要开哪些库？","opts":["戊气胜形开丑未库；己偏形开戌辰库","戊己都气胜形，都需要去开丑未库","戊己都偏重形，都需要去开辰戌库","戊偏形开戌辰库；己气胜形开丑未库"],"ans":3,"exp":"戊偏形、要找气，开戌、辰库；己气胜形、要找形，开丑、未库。","sec":"四、十干日主的用法特点","t":"calc"},{"q":"甲木与乙木，哪个相对难伺候？乙木喜见什么？","opts":["甲难伺候怕金；乙好伺候，喜金克成器","甲乙都怕金，一见金克就一定会坏","甲好伺候，喜火来泄；乙难伺候，喜水生","乙难伺候怕金；甲好伺候，喜金来克"],"ans":0,"exp":"甲为阳指气，最难伺候；乙为阴指形，相对好伺候，喜金克与金火组合。","sec":"四、十干日主的用法特点","t":"diff"},{"q":"盲派所说「余气」（如丑中癸）有什么含义？能否当丈夫？","opts":["经冲才出的气；可当夫星，主二婚或多婚","量小、最后、别人退下的；不当夫，作桃花","量大、最先、本人所有的；可以当夫星","很弱的原神；可作夫星，只是比较晚婚"],"ans":1,"exp":"余气＝量很小、最后一个、中途剩下或别人退下的，不足以构成丈夫，只作桃花看。","sec":"八、命术轶闻中的分析思路","t":"rule"},{"q":"盲派看学历，主要看原局里的什么？对伤官有什么要求？","opts":["看官杀、比劫；伤官有无制服都行","只看印星；食伤一概不看，不论有无制","看食、印；伤官须有制服（庚除外）","看财星、劫财；伤官越旺学历越高"],"ans":2,"exp":"看学历看食、印；伤官必须有制服（庚除外）；有制的财也可当学历看。","sec":"七、婚姻、桃花、学历示范","t":"rule"},{"q":"盲派中「黑道」命格有哪两种典型组合？","opts":["印星制伤官；比劫帮身","财官相生；食神制杀","劫伤组合；伤食制住官杀","劫伤组合；伤食与官杀对抗"],"ans":3,"exp":"黑道的两种组合：比劫遇伤官、以及伤食与官杀对抗（不是制）。","sec":"八、命术轶闻中的分析思路","t":"rule"},{"q":"拱与六合，在象上有什么区别？","opts":["拱主合伙，不抢占；六合有强占之象","拱与六合都只主合伙，没有区别","拱与六合都是强占之象","拱有强占之象；六合主合伙"],"ans":0,"exp":"拱＝合伙（桃花也叫打伙计），拱不是抢占；六合有强占之象。","sec":"七、婚姻、桃花、学历示范","t":"diff"},{"q":"盲派看男命桃花，核心是哪两者发生作用？","opts":["比劫与财发生作用","伤食与财发生作用就是桃花","官杀与印星发生作用","印星与食伤发生作用"],"ans":1,"exp":"男命伤食与财发生作用就是桃花，如伤官为桃花；比劫、官杀不是此例。","sec":"七、婚姻、桃花、学历示范","t":"rule"}],"fine":[{"q":"在实战论命的哲学框架中，盲派所传「套路」与个人「修为」分别对应阴阳与什么？","opts":["套路相当于阳，修为相当于阴；修为全靠背诵神煞口诀","套路与修为都属于阴，只有流年太岁才属于阳","套路相当于阴，修为相当于阳；修为来自圣人典籍与生活观察","套路可以完全替代修为，只需死记套路即可铁口直断"],"ans":2,"exp":"套路相当于阴，修为相当于阳，只有套路而无修为论命会死板；修为来自圣人（《系辞》《鱼樵问答》）与生活。","sec":"一、修为的两个来源","t":"diff"},{"q":"盲派推荐的「来自圣人」两部经典著作《系辞》与《鱼樵问答》，在命理修为上各侧重什么？","opts":["《系辞》讲旺衰，《鱼樵问答》讲格局","《系辞》讲体用，《鱼樵问答》讲虚实","《系辞》讲纳音，《鱼樵问答》讲神煞","《系辞》讲象，《鱼樵问答》讲体用"],"ans":3,"exp":"圣人典籍中，《系辞》讲象（易者，象也），《鱼樵问答》讲体用（体无定用，理为体、象为用）。","sec":"一、修为的两个来源","t":"rule"},{"q":"如何从命局的「形」与「气」判断一个人是「手拙而头脑好」还是「手很巧」？","opts":["全是无形之气、唯一之形虚透为忌则手拙脑好；制有形之字则手巧","全是无形之气则手很巧；地支满盘有形之物则手拙","只要天干见伤官就必手巧；只要地支见正印就必手拙","木火成势则手拙；金水成势则无论制什么都手巧"],"ans":0,"exp":"如丁壬丁辛／未子巳亥全是无形之气、唯一之形辛虚透为忌，故手拙脑好；而制有形的酉则手很巧。","sec":"一、修为的两个来源","t":"xiang"},{"q":"盲派「实战八步」的正确推进顺序是？","opts":["看阴阳形气→看大运→断流年→看格局→定核心功神→辨虚实→定象","看格局→定核心功神→辨虚实→看阴阳形气→定象→看大运→断流年→验六亲婚姻","断流年→看大运→定象→辨虚实→定核心功神→看格局→验六亲婚姻","验六亲婚姻→定象→看格局→辨虚实→看大运→定核心功神→断流年"],"ans":1,"exp":"实战八步：1看格局→2定核心功神→3辨虚实→4看阴阳形气→5定象→6看大运→7断流年→8验六亲婚姻。","sec":"二、实战步骤（提炼）","t":"step"},{"q":"在「阴阳与形气」的转换序列中，木、辰、金、戌、丑五者各自对应形气的什么阶段？","opts":["木气始、辰气终、金形初、戌形始、丑气始收","木气之形、辰形终、金气始收、戌形始、丑形初","木形始、辰形初、金形终、戌气始收、丑气之形","木形终、辰气之形、金气始、戌形初、丑形始"],"ans":2,"exp":"木为形之始，辰为形之初，金为形之终，戌为气始收，丑为气之形；辰戌称天门地户。","sec":"三、阴阳与形气","t":"rule"},{"q":"为什么易经时空观中把「寅卯」对应为一天中的「凌晨」？","opts":["寅卯处于日落西山之时，阳气尽收，故为凌晨","寅卯处于正午极盛之时，万物显形，故为凌晨","寅卯处于亥子水旺之极，冰封万里，故为凌晨","寅卯处于萌芽状态，尚看不见，故为凌晨"],"ans":3,"exp":"易经反映时空观：寅卯是萌芽状态，尚未成形而看不见，故对应凌晨。","sec":"三、阴阳与形气","t":"xiang"},{"q":"在「丙戊辛壬／戌戌酉辰」执行死刑的公安干部命局中，辰戌结构为什么具有「屠宰场（生死起灭）」之义？","opts":["戌气灭辰气始，酉合辰制戌即杀要杀的人","辰戌相冲代表自己入狱，酉金代表被枪决","辰为气灭、戌为气始，丙合辛代表犯人逃跑","戌为银行金库、辰为印信，代表掌管国家财政"],"ans":0,"exp":"戌辰为生死起灭（形气转化）：戌为气灭、辰为气始，酉禄合辰（正）去制戌，故成执法行刑之象。","sec":"三、阴阳与形气","t":"xiang"},{"q":"关于「丁火」日主的用法特点，下列哪项描述最符合盲派实战规律？","opts":["丁为阳火最怕旺，天干见丁越多越贫贱短寿","丁阴火喜旺；天干丁多配地支子丑多搞玄学","丁火地支最忌见子丑，见之必不信玄学只做体力工","丁火最喜食神己土来泄秀，泄得越多层次越高"],"ans":1,"exp":"丁为阴火喜旺（不喜己泄）；丁是神秘之字，代表天文、老天做的文章，天干丁多配地支子丑多搞玄学。","sec":"四、十干日主的用法特点","t":"xiang"},{"q":"关于「庚辛金」与「壬癸水」日主的用法特点，下列说法正确的是？","opts":["庚辛金必须身旺才能担财；壬癸水最怕生木泄气","庚辛金只论从格不论制用；壬癸水最喜亥子无木","庚辛金不看旺衰重在如何去用；壬癸水喜落到实处生木","庚金是首饰怕火炼；辛金是钢坯不怕天干虚透"],"ans":2,"exp":"金为形之成，庚辛不必论旺衰重在如何用（庚钢坯、辛首饰乐水之盈）；壬癸气要找形，喜落到实处生木。","sec":"四、十干日主的用法特点","t":"rule"},{"q":"在「癸乙、甲丙、戊申、丁己」四组十干日主配字组合中，哪两组被盲派评为「厉害、功大，喜」，哪两组「泄了」？","opts":["癸见乙、甲见丙功大而喜；戊见申、丁见己不好","甲见丙、丁见己功大而喜；癸见乙、戊见申泄了不好","四组一律以泄论，全部主功小而贫寒","癸见乙、戊见申功大而喜；甲见丙搞文泄了，丁见己不好泄了"],"ans":3,"exp":"诀：癸见乙（食神最厉害）、戊见申＝厉害功大喜；甲见丙＝搞文的泄了；丁见己＝不好，泄了（丁不喜泄）。","sec":"四、十干日主的用法特点","t":"calc"},{"q":"判断甲木日主地支「卯」是否为甲木之根时，原局有无「寅」字会产生什么差别？","opts":["无寅时卯是甲根；已有寅时卯不是甲根","无论原局有没有寅，卯永远都是甲木的强根","只有原局同时有寅又有卯时，卯才算甲木之根","无论原局有没有寅，卯永远都不是甲木的根"],"ans":0,"exp":"原局只有一个卯而无寅时，卯也作甲的根（羊刃根）；若原局已有寅，则卯不是甲之根而是劫财别人地盘。","sec":"五、官命示范（流年演示）","t":"rule"},{"q":"同为「包围型」贵格，如何区分「皇帝（康熙造）」、「半个主子（林彪造）」与「伪政府」？","opts":["年时有财为皇帝；日支空亡为半个主子；伤官透干为伪政府","全坐自己之禄为皇帝；半个禄为半个主子；癸水压年上反象为伪政府","三合木局为皇帝；三合金局为半个主子；三刑入命为伪政府","全坐七杀为皇帝；半个印为半个主子；正财压年上为伪政府"],"ans":1,"exp":"康熙造丁坐午全禄是皇帝；林彪造未为丁半个禄是半个主子；同样半禄但癸水压年上反了象则是伪政府。","sec":"五、官命示范（流年演示）","t":"diff"},{"q":"若命局呈现「日主腹背受敌、敌人四面包围」的反面控制结构（如未穿子做功），敌人的强弱对命主有何影响？","opts":["敌人越强命主越穷，必须全部制死才算好","敌人一旦强旺，命主必定少年夭折无官","敌人越强做功越强，没有敌人功就没有了","敌人强弱与做功无关，只看日主是否得令"],"ans":2,"exp":"反面控制型命局以敌为功神，敌人越强做功越强，没有敌人功也就没了（如副军长之造）。","sec":"五、官命示范（流年演示）","t":"calc"},{"q":"命局原本是「丑戌刑」的做功格局，行运或流年最忌讳见到哪个字来破坏？","opts":["遇「寅」来合戌，必然立刻升官","遇「申」来生水，代表财富翻倍","遇「辰」来冲戌，代表永久无病","遇「午」来穿丑，带有反局的味道"],"ans":3,"exp":"教材特别提示：「丑戌刑」的格局，遇午来穿（丑午穿），是反局的味道（如徐向前造己丑年生病），要注意。","sec":"六、流年应期的三条规则与长篇示范","t":"rule"},{"q":"在「一贵抵九贱，一贱消九贵」的虚实演示中，天干同时透出虚财或虚官，为什么仍能格局高而发财？","opts":["虚透之财官正好合到日主身上，反成高格","只要八字天干全虚透而地支无一字，必为九五之尊","虚透之字不需要与日主发生任何合克关系就能发财","因为地支辰土多现，见辰必主富贵极品"],"ans":0,"exp":"虚实活用：戊丙虽虚透，但癸也虚透且合到日主戊身上，反成「一贵抵九贱」的高格而发财。","sec":"七、婚姻、桃花、学历示范","t":"rule"},{"q":"在断官命与违法命局时，为什么说「表象的职业与好坏是两样的」？","opts":["只要表象是公检法，就永远不会被判刑坐牢","如酉戌穿反象虽表象为官，实为保护伞被抓","因为官命一定都是好人，坏人绝不可能当官","因为职业只看年柱纳音，好坏只看大运神煞"],"ans":1,"exp":"原局水制火而酉戌穿反了（正理应戌制酉），虽表象可当公安局长，实质却是黑社会保护伞被公审。","sec":"七、婚姻、桃花、学历示范","t":"diff"},{"q":"按盲派父母大限规律，年柱与月柱的大限分界点通常定在几岁？","opts":["45 岁（年柱主 45 岁前，月柱主 45 岁后）","30 岁（年柱主 30 岁前，月柱主 30 岁后）","18 岁（年柱主 18 岁前，月柱主 18 岁后）","12 岁（年柱主 12 岁前，月柱主 12 岁后）"],"ans":2,"exp":"大限规律：年柱大限定在 18 岁之前（如 16 岁死母），月柱大限则在 18 岁之后（如 19 岁死父）。","sec":"1. 父母应期与大限","t":"rule"},{"q":"盲派关于「女命年上伤官空亡」以及「丙见丑中癸水」的两条断诀分别是？","opts":["前者读书极佳；后者为清高独身之象","前者早婚美满；后者为克父克母之象","前者大富大贵；后者为正夫白头到老","前者公婆不喜子女不孝；后者为淫荡桃花"],"ans":3,"exp":"教材断诀：女命年上伤官空亡，公婆不喜，子女不孝；丙见丑中癸水（余气桃花）为淫荡。","sec":"1. 父母应期与大限","t":"rule"},{"q":"在父母生死应期中，若原局戌穿酉，两个同年月日生人分别时支为「丑」与「寅」，父亲去世流年应期有何不同？","opts":["有丑应癸丑年墓到，有寅应甲寅年金绝","两者必然同一年去世，与时支毫无关系","时支有寅则父亲长寿百岁，绝不会去世","原局有丑应甲寅年，原局有寅应癸丑年"],"ans":0,"exp":"同盘不同时应期有别：酉入墓于丑，原局有丑应丑年墓到；金绝于寅，原局有寅则应寅年。","sec":"1. 父母应期与大限","t":"rule"},{"q":"多妻命局（如「壬癸辛辛／寅丑亥卯」）用盲派「数次」方法计算七个老婆时，七次是怎么数出来的？","opts":["日支丑土中藏三个字加四柱天干四个字","五个星宫各现一次，加上地支合了两次","大运一共七步，每步大运固定算一个老婆","天干四个字加地支三个字，随便相加凑成七"],"ans":1,"exp":"数法：五个星宫各计一次，加上合出的两次（如寅亥合、亥卯拱合），共七次；顺序从上而下、从年到时。","sec":"3. 虚实、汉奸与多妻","t":"calc"},{"q":"辛金日主若「年时两头墓（如寅丑酉寅）」且见巳酉丑阴土无阳气，常对应哪类身体残疾或疾病？","opts":["口吃但奔跑如飞，肺热咳嗽","耳聋但精力充沛，肝火极旺","盲人且瘫痪不能动，脾湿（土主脾主力）","嗅觉失灵但力大无穷，肾水泛滥"],"ans":2,"exp":"年时两头坐绝（禄逢墓绝，不能出门户）主瘫痪；辛日主两头墓主盲且不能动，阴土无阳主脾湿。","sec":"4. 命克子女","t":"xiang"},{"q":"原局「壬癸辛乙／子丑酉未」本做房地产、大酒店发财，为何一到「庚辰年」竟至终生坐牢？","opts":["因为乙木在时干克尽了辛金，导致日主无根","因为未土冲坏了丑土，使命主失去所有银行贷款","因为庚金透干生水，导致水旺木漂而彻底破产","原局仅一个未是阳，辰一来全成阴地且丑酉黑道"],"ans":3,"exp":"原局仅一个未土是阳，辰一来全成阴地，阴灭阳而主终生牢狱；兼丑酉为黑道、食伤透干为骗子结构。","sec":"5. 骗子、小偷、其他","t":"calc"},{"q":"子女星被穿本主无子或晚子，为什么盲派认为命主容易在「润月年」生孩子？","opts":["润月补足阴不足与形不足，故易生子","润月年比平年多一个月，纯属概率增加而非命理","润月年阳气过旺，能把子女星全部焚毁化气","润月年天干一定透出食神，地支一定冲开子女宫"],"ans":0,"exp":"中国三统历中，润由阴不足、阳有余而设；阴不足则形不足，润月年来补足其形，故易得子。","sec":"6. 将门虎女、父亲的悲哀","t":"rule"},{"q":"在「乙己壬壬／卯卯子寅」煤气中毒死亡命局中，大运「丁丑」为何被取作「煤气之象」？","opts":["丁火克丑中辛金，代表在工厂被机器压伤","丁火坐湿土丑上，湿土生火燃烧不充分","丑为金库、丁为雷电，金火相击代表高压电触电","丁为太阳、丑为冰雪，代表在雪山冻伤致死"],"ans":1,"exp":"丁丑一柱为火坐湿土之上，湿土上生的火燃烧不充分，正象煤气；加寅食入空亡、子被破而应凶。","sec":"6. 将门虎女、父亲的悲哀","t":"xiang"}]},{"n":84,"level":"高级","title":"天干五合与地支六合的深论","qs":[{"q":"天干相合的两个字，强弱不同时，信息怎么互换？","opts":["强方代表弱方的信息，弱方顺从强方","双方各守本性，互不借用也互不影响","双方信息各占一半，不分强弱也不分主从","弱方代表强方的信息，强方顺从弱方并受其制"],"ans":0,"exp":"合在一起的两字任何一方都能代表对方；强的一方制弱的一方，强方就代表弱方的信息，弱方顺从强方的信息。","sec":"一、天干五合：双方互为代表","t":"rule"},{"q":"丁火日主见丙辛相合，这笔财按盲派怎么论？","opts":["比肩合财，父母给的遗产","劫财合财，非劳动所得，炒股期货赌博类","劫财合财，辛苦劳动所得，薪水类","劫财合财，合伙经营所得，分红类"],"ans":1,"exp":"丙辛合是劫财合财，财是被劫财合过来的，不是劳动所得，而是靠非常手段获利：炒股、期货、赌博一类。","sec":"一、天干五合：双方互为代表","t":"calc"},{"q":"食神合印与伤官合印，各偏向什么？","opts":["食神合印偏技术艺术，伤官合印偏学术研究","两者都偏学术研究，没有区别","食神合印偏学术研究，伤官合印偏技术艺术","食神合印偏权力，伤官合印偏财富"],"ans":2,"exp":"食神合印是带有思想性的文化，偏学术研究；伤官合印偏技术、艺术方面的成就。","sec":"一、天干五合：双方互为代表","t":"diff"},{"q":"合杀而杀被制，伤官合杀与食神合杀的结局有何不同？","opts":["两者都是当官，只是官有大小之分","食神合杀能当大官，伤官合杀只是发财","两者都是发财，只是财有多少之分","伤官合杀变权力能当大官，食神合杀是发财"],"ans":3,"exp":"伤官也代表杀，杀被制而伤官合杀，伤官变成权力，能当大官；换成食神合杀被制，则不是当官而是发财。","sec":"一、天干五合：双方互为代表","t":"diff"},{"q":"食神合印这类天干合落在宾位，与日主本人的事业什么关系？","opts":["无关，只是自己的精神享受","主六亲，决定父母的状况好坏","主财运，决定日主能否发财","直接决定日主的事业成败与高低"],"ans":0,"exp":"合在宾位时与日主本人的事业无关，只是自我精神享受；合到主位才与日主直接相关。","sec":"一、天干五合：双方互为代表","t":"rule"},{"q":"地支六合，不论在命局、大运还是流年，一律怎么论？","opts":["命局合绊论，大运流年合化论而不绊","以合绊论，双方都失去一定的作用","以合化论，双方合成另一种五行","以合绊论，只有较弱的一方失性"],"ans":1,"exp":"地支六合比天干简单：不管命局、大运、流年的合，都以合绊论，合住的双方都丧失原性。","sec":"二、地支六合","t":"rule"},{"q":"午未相合，失性的要点是什么？","opts":["闭金库，午火合入土中","熄了寅中丙火，印星灭","闭木库，午火被晦","闭水库，坏乙木"],"ans":2,"exp":"午未合闭木库、午火被晦；子丑合闭金库；辰酉合闭水库、坏乙木；寅亥合熄寅中丙火。","sec":"二、地支六合","t":"calc"},{"q":"大运与流年相合，大运的合什么时候起作用？","opts":["入大运就起作用，与流年无关","只有大运合原局时才起作用","流年合大运不起作用，只看原局","大运静止，须流年去合才起作用"],"ans":3,"exp":"大运是静止的，只有流年去合它才起作用；流年合入命局，对原局是绊、对流年是留（得到），实际是一种应期。","sec":"三、流年合大运","t":"rule"},{"q":"盲派说的「反局」是指什么？","opts":["违背原局组合意象的合冲，主凶","违背原局组合意象的合冲，多转为吉","凡大运流年合冲原局的字，都主凶","原局内部既有合又有冲的结构，主凶"],"ans":0,"exp":"凡是违背原局组合意象的合冲叫反局，主凶：如原局是巳制酉，辰酉合保护了酉，巳制不住它。","sec":"四、反局","t":"rule"},{"q":"日主坐财库，冲开财库后，怎样的情形最好？","opts":["冲开财库，库中之财不受制任其流出","冲开财库，并能制住库中之财及其原神","冲开库后再用合把库闭上守住","不冲库，让库闭着守住财"],"ans":1,"exp":"见财库一定要冲，冲开能发；冲开财库最好还能制住库中之财和它的原神，这是最大的财之一。","sec":"四、反局","t":"step"}],"fine":[{"q":"天干五合信息互换中，当强方制弱方时，伤官旺而杀弱、伤官合杀，此时「杀」可以代表什么？","opts":["伤官的聪明才智","比劫的体力劳动","日主的祖上遗产","印星的学历文凭"],"ans":0,"exp":"五合双方互为代表，强者代弱、弱者顺强；伤官旺杀弱时，弱杀顺从伤官，故杀代表伤官的聪明才智。","sec":"1. 互换规则","t":"rule"},{"q":"八字中「伤官合印」与「食神合印」同属文化范畴，其中「伤官合印」更偏向哪一类成就？","opts":["金融期货等投机性获利","技术或艺术方面的成就","行政部门的组织人事权力","纯理论的哲学学术研究"],"ans":1,"exp":"食神主思考，食神合印偏学术研究；伤官合印则偏向技术、艺术方面的成就。","sec":"1. 互换规则","t":"xiang"},{"q":"乾造丁未、壬子、乙丑、戊寅，命局印旺有制为官命，丁壬食神合印落在宾位，主日主具有什么特点？","opts":["主日主因沉迷精神追求而丢掉全部官职","主日主靠写书卖画成为职业文化商人","与事业无关，只主个人爱好佛学或周易等精神享受","直接决定日主必须从事高校学术研究工作"],"ans":2,"exp":"合在宾位与日主本人事业无关，只属于自我精神享受，故此造是爱好佛学、周易的官员。","sec":"2. 合在宾位还是主位","t":"calc"},{"q":"坤造壬子、己酉、乙丑、丁丑，丁壬合到主位丑土杀库且杀有制，其应象更接近哪种职位？","opts":["完全没有职权的自由职业技术员","靠投机炒股发财的私营大老板","掌管全国金融系统的部级高官","文化宫电影院总经理一类带文化色彩的小职权"],"ans":3,"exp":"印主权力合到主位杀库，杀有制有小职权，加之丁壬合食神合印偏文化，故做到文化宫电影院总经理。","sec":"2. 合在宾位还是主位","t":"calc"},{"q":"乾造壬午、辛亥、庚辰、丁亥，本属伤官去官，为何日主不是官员而是科学家？","opts":["官在宾位虚透只主名气，主位辰收亥主学术","地支亥水太多，水多木漂导致无心仕途","时柱丁亥天地相合，把日主变成了纯商人","伤官力量太弱，完全制不住原局的官星"],"ans":0,"exp":"官在宾位虚透只能主名气，非实权之官；亥水旺被主位辰收，主归纳总结与聪明才智，故偏向学术科研。","sec":"2. 合在宾位还是主位","t":"calc"},{"q":"乾造壬午、辛亥、庚辰、丁亥，若将壬午与丁亥两柱位置互换，结局会有何变化？","opts":["伤官变成财星，日主转行经商发大财","官星落入主位，日主必是当官之人","形成两党反局，日主会有牢狱之灾","官星彻底消失，日主只能务农为生"],"ans":1,"exp":"原局丁官在时为实但壬午在年为宾，互换后主宾得位，伤官去官落到实处，必是当官的。","sec":"2. 合在宾位还是主位","t":"diff"},{"q":"乾造癸巳、戊午、辛丑、丙申，坐下丑收申金，申合巳官入墓为我所用，为何日主当的都是正职没当过副职？","opts":["命局中完全没有七杀星出现","年干癸水食神把七杀全部合走了","申合的是巳火正官，属于正官合身","日主坐下丑土是印库而非杀库"],"ans":2,"exp":"局中虽有午火七杀，但申合的是巳火正官，属于正官合身并入坐下丑墓，故所任皆为正职。","sec":"3. 合到官星：官合身与谋官","t":"calc"},{"q":"乾造癸巳、戊午、辛丑、丙申，命局「丑午穿」在人事与六亲上体现为什么毛病？","opts":["下属背叛日主，导致公司破产倒闭","兄弟姐妹反目成仇，彼此争夺遗产","配偶身体健康极差，早年克去妻子","七杀上级与他不和，且沾不到父母的光"],"ans":3,"exp":"午火七杀为二主管（上级），丑午穿主上级与他不和；同时午丑害亦主沾不到父母的光。","sec":"3. 合到官星：官合身与谋官","t":"calc"},{"q":"乾造癸巳、戊午、辛丑、丙申，行甲寅运时日主虽仍当官，为何却是「最难受」的一步运？","opts":["寅穿巳，伤及所合的正官与巳火印源","寅午戌三合火局，把坐下丑土烧干","甲木克戊土，彻底断绝了日主的财运","寅申冲破局，日主被直接革职下狱"],"ans":0,"exp":"原局靠申合巳官为用，甲寅运虽不失官，但寅木穿巳火，动摇了谋官的根本，故极为难受。","sec":"3. 合到官星：官合身与谋官","t":"calc"},{"q":"乾造乙巳、己丑、己未、庚午，火土成势冲去月令财食而成世界首富，为何二十几岁凶死儿子？","opts":["丑未冲把坐下子女宫彻底冲垮","年上七杀为儿、时上伤官为病，乙庚合制不净","时支午火羊刃克制庚金伤官太重","原局火炎土燥，毫无水木调候之气"],"ans":1,"exp":"年上乙木七杀为儿子，时上庚金伤官为儿子的病，乙庚合属于制得不干净的病，故儿子二十几岁凶死。","sec":"4. 合而无制的反例","t":"calc"},{"q":"乾造乙巳、己辰、辛卯、丙申，乙庚合且辰卯穿，为何日主不仅无官且犯官灾重判？","opts":["丙火正官太弱，需要大运火旺才能当官","辰土印星太重，导致日主懒惰不求上进","财坐支卯木生官透干克身，自身反被官克住","申金劫财旺极，把乙木财星彻底劫光"],"ans":2,"exp":"乙木财坐卯木生巳火官星，丙火官透出克身，财生官克身且无制，故无官反有官灾。","sec":"4. 合而无制的反例","t":"calc"},{"q":"地支六合中，「寅亥合」与「辰酉合」各自失性的要点是什么？","opts":["寅亥合坏甲木，辰酉合闭火库","寅亥合闭水库，辰酉合坏金库","寅亥合闭木库，辰酉合熄丙火","寅亥合熄寅中丙火，辰酉合闭水库坏乙木"],"ans":3,"exp":"地支六合均以合绊失性论：寅亥合熄了寅中丙火（印星灭）；辰酉合闭水库，同时坏乙木。","sec":"1. 总规则","t":"diff"},{"q":"地支六合中，「卯戌合」与「子丑合」在失性上各指什么？","opts":["卯戌合闭火库且木土失性，子丑合闭金库","卯戌合闭水库，子丑合闭木库","卯戌合闭金库，子丑合闭火库","卯戌合木生土旺，子丑合水土相融"],"ans":0,"exp":"卯戌合闭了火库，木和土都失去原性；子丑合则闭金库。","sec":"1. 总规则","t":"diff"},{"q":"地支六合中，「巳申合」的失性规律与其他六合有何不同？","opts":["固定只去申金，永远伤不到巳火","既可去巳火也可去申金，视双方旺弱而定","固定只去巳火，永远伤不到申金","双方合化成水，火金原性完全保留"],"ans":1,"exp":"巳申合具有双向性：巳火旺时去申中金水，申金旺时去巳中火土。","sec":"1. 总规则","t":"rule"},{"q":"乾造甲辰、丙寅、己亥、庚午，命局中的「寅亥合」直接导致了哪两项人生不利？","opts":["食神被合死，日主终身无子女缘分","官星被彻底制死，日主中年牢狱破产","印灭丢掉工作，妻宫被合走致两次婚姻","财星太旺克身，日主常年卧病在床"],"ans":2,"exp":"寅亥合熄灭寅中丙火印星（丙为工作）故无工作；亥水妻宫被合走失去老婆，故两次婚姻。","sec":"2. 命例","t":"calc"},{"q":"乾造壬寅、辛亥、甲戌、己巳，巳火入戌墓原本无法生财，为何行丙辰运时又出名又发财？","opts":["辰亥相穿解开了原局寅亥合绊之病","丙火坐辰得长生，直接克去辛金官星","丙辛合化水生木，日主身旺任财","辰戌冲开戌墓，放出墓中火土得以生财"],"ans":3,"exp":"原局巳火入戌墓难生财，卯运己卯闭墓初发，至丙辰运辰戌冲开墓库，能量释放故又出名又发财。","sec":"2. 命例","t":"calc"},{"q":"乾造甲辰、癸酉、庚辰、甲申，为何不能按从格论而断为浊金贱命？","opts":["辰酉合闭水墓坏了财根，水木又去不干净","年时两甲木透出，比肩争夺财星太重","申酉戌三会西方金局未成，金气不足","癸水伤官坐酉金受生，克制甲木财星"],"ans":0,"exp":"辰酉合闭水墓，使财星失去根源，且局中水木去不掉，无法成势从格，故为浊金贱命。","sec":"2. 命例","t":"calc"},{"q":"乾造庚戌、己卯、乙卯、己卯，戌卯合是财官合身，为何日主不是当官而是办三家企业的老板？","opts":["庚金正官被己土印星泄尽，毫无官气","官星虚浮不当官，三卯合戌主管理三家企业","卯木比肩太旺，把戌土财库全部克破","月时己土偏财透干，只利经商不利仕途"],"ans":1,"exp":"戌卯合财官合身不管旺衰，但庚金官星虚浮故不当官而办企业；三个卯合一个戌，正应管理三家企业。","sec":"2. 命例","t":"calc"},{"q":"坤造甲寅、辛未、乙亥、癸未，寅亥合导致婚姻难成甚至自己做第三者，何时问题得以解决？","opts":["癸未年，未穿子水合住亥水","丙戌年，戌合卯木闭住火库","甲申年，申冲寅解开寅亥合","乙酉年，酉克寅木斩断桃花"],"ans":2,"exp":"寅亥合将配偶宫亥水合走致婚姻不顺，甲申年申金冲去寅木，冲开寅亥合，问题遂解。","sec":"3. 寅亥合的婚姻意义","t":"calc"},{"q":"同为甲寅、辛未、乙亥日主，时柱为「己卯」比「癸未」婚姻好但财运差，原因何在？","opts":["己土财星虚透无根，卯木比劫夺财致贫","亥卯未三合木局成势，婚姻美满但克父","癸未时官星坐在墓库，夫星入墓必主克夫","卯禄合住亥水护婚，但木旺财弱杀有源不富"],"ans":3,"exp":"己卯时柱卯为禄能将亥水合住故婚姻较好，但木过旺、财弱且杀有源故不富；癸未时亥未拱财身旺财旺故富。","sec":"3. 寅亥合的婚姻意义","t":"diff"},{"q":"关于流年的「绊」与「留」，流年合入命局具有哪两重性？","opts":["对原局而言是被绊，对流年而言是被留（得到）","无论对原局还是流年，一律只以凶论","对天干而言是留，对地支而言必是化","对原局而言是被留，对流年而言是被绊"],"ans":0,"exp":"合绊有两重性：对原局是被绊而失原性，对流年是被留即得到，所以流年合入命局是一种应期。","sec":"三、流年合大运：绊与留","t":"diff"},{"q":"乾造壬子、丁未、癸亥、乙卯，庚戌运与乙卯天合地合，为何既不自由不快乐又算提升？","opts":["戌土正官冲动未土七杀，工作调动频繁","乙卯食神心性被绊不自由，但得到了庚戌财官","庚金正印生癸水日主，学业进步但缺钱","丁壬合被庚金冲散，失去了原本的好友"],"ans":1,"exp":"原局乙卯食神不生财只主悠闲心性，被绊则不快乐；但合留了大运庚戌财官（管材料库），故有提升。","sec":"三、流年合大运：绊与留","t":"calc"},{"q":"乾造戊辰、壬戌、乙未、己卯，原局戌冲辰制印库掌管经济，为何行丁运最不好甚至下乡劳动？","opts":["丁火食神泄乙木太重，日主身体患病","丁火合克己土偏财，导致经济来源断绝","丁壬合护住了本被戊制的壬水，构成反局","丁火生戊土财星，财多身弱不堪重负"],"ans":2,"exp":"原局壬水本被戊土制去，丁运卯戌合库同时丁壬合，使戊制不了壬而壬被保护，属反局失权。","sec":"四、反局：违背原局意象的合","t":"calc"},{"q":"盲派所说的地支「六合换象」，其核心原理是什么？","opts":["六合只改变十神名称，不改变原局的象义","六合中弱方完全克制强方，使强方失去作用","六合双方彻底消失，化出全新的第三种五行","六合中一方变成另一方，被合者带上合方的性质"],"ans":3,"exp":"换象即六合中一方变成另一方：合到哪里，被合的东西就带上合方的性质（如申制巳，金都成火财）。","sec":"五、六合换象","t":"rule"},{"q":"乾造壬申、己酉、癸巳、辛酉，申制巳使金都成了火财，为何行寅运反而倒霉被抓？","opts":["寅冲申破了原局，导致巳火无制","寅巳相穿，把日主自身的财库穿破","寅酉暗合，把酉金印星合走失去靠山","寅木伤官生巳火，使巳火变成七杀克身"],"ans":0,"exp":"原局金水成势靠申制巳做功，寅运寅冲申破局，巳火失去制约，故倒霉被抓。","sec":"五、六合换象","t":"calc"}]},{"n":85,"level":"高级","title":"三合、六冲、相穿、三刑、相破的深论","qs":[{"q":"合的四种用法里，「合留」「合绊」各指什么？","opts":["合留：一方克去另一方；合绊：一方被合去","合留：流年合住八字中的字；合绊：力量相当的两字相合","合留：一方被合去；合绊：一方克去另一方","合留：力量相当的两字相合；合绊：流年合住八字中的字"],"ans":1,"exp":"合留是流年合住八字中的字，婚姻应期的核心；合绊是力量相当者相合；合制是一方被合去，合伤是一方克去另一方。","sec":"一、合的四种用法","t":"diff"},{"q":"婚姻应期上，只合到配偶星与连配偶宫也合动，分别论什么？","opts":["星宫都合只是谈对象，要冲才结婚","只合星就结婚，宫合是离婚","只合星是谈对象，宫也合动才是结婚","只合星是结婚，宫也合动是生子"],"ans":2,"exp":"口诀：星合谈对象，宫合成夫妻；合住即是留住。","sec":"一、合的四种用法","t":"rule"},{"q":"地支六合中，哪一合效率最高、能量最大？","opts":["寅亥合，亥水克寅中丙火","午未合，火土相生","卯戌合，卯木克戌土","巳申合，巳火制申金"],"ans":3,"exp":"巳申合是巳火制申金，效率最高；午未合最差，意义不大，只闭墓库。","sec":"二、地支六合各合的作用与暗合","t":"rule"},{"q":"午亥、卯申、寅丑这三组合，盲派称作什么，性质如何？","opts":["暗合，一方强一方弱的换象","三合，中神最重要","暗合，双方互相化气成新五行","六合，两方力量对等"],"ans":0,"exp":"午亥、卯申、寅丑近似六合，叫暗合，是一方力强、另一方力弱的换象，也是一种做功方式。","sec":"二、地支六合各合的作用与暗合","t":"diff"},{"q":"地支有寅、午、午、戌四字，能不能成寅午戌火局？","opts":["成火局，午戌合为主","不成，中神午双现入墓","不成，寅午戌被午冲散","成火局，午多更旺"],"ans":1,"exp":"三合局中神为尊，中神多现或双现不成合局，而是入墓。","sec":"三、三合局","t":"calc"},{"q":"冲到墓库时，近冲、隔冲、遥冲分别是什么结果？","opts":["近冲遥冲都开库，隔冲才坏库","近冲开库，隔冲伤，遥冲坏库","近冲坏库中之物，隔冲伤，遥冲动、开","近冲伤，隔冲开库，遥冲冲去"],"ans":2,"exp":"近冲库，冲坏库中之物；隔冲库，伤；遥冲库，冲动、冲开。","sec":"四、六冲","t":"rule"},{"q":"子、午、子三字，两子夹一午，一般怎么论？","opts":["二冲一，午必被冲去","两子互相对冲，各自消耗","子水旺，午火被制死","夹冲，一般不为冲坏"],"ans":3,"exp":"夹冲：两个冲一个，一般不为冲坏；若再见帮手（如巳、未、戌）才冲坏。成势的冲才可能冲伤冲去。","sec":"四、六冲","t":"calc"},{"q":"子未、丑午、寅巳、申亥四组穿，哪两组力量较小？","opts":["寅巳、申亥","子未、丑午","子未、申亥","丑午、寅巳"],"ans":0,"exp":"克泄穿最厉害：子未、丑午、卯辰、酉戌；寅巳、申亥是生穿，力小，只有穿动、穿倒、不和之象。","sec":"六、相穿","t":"diff"},{"q":"正印被穿倒、七杀被穿倒，分别当什么看？","opts":["正印当食神，七杀当正官","正印当偏印，七杀当正官","偏印当正印，七杀当劫财","正印当偏印，七杀当食神"],"ans":1,"exp":"穿倒是正的穿成偏的、偏的穿成正的：穿倒正印当偏印看，穿倒七杀当正官看。","sec":"六、相穿","t":"calc"},{"q":"遇到丑、戌、未等库，用什么才能开库？","opts":["只有合能开库","穿或合，冲开不了库","冲或刑，穿开不了库","冲、刑、穿都能开库"],"ans":2,"exp":"穿库开不了库，只有冲库、刑库才能开；穿的结论是穿倒或凶灾。","sec":"六、相穿","t":"rule"},{"q":"子卯、卯午相破的核心是什么？","opts":["一方被合去，另一方得生","一方克泄另一方，穿倒对方","双方都衰弱，无力相生","双方帝旺，旺而不生"],"ans":3,"exp":"破本是相生关系，但双方各自帝旺，旺而不生，不履行职责；还有破坏、破产、捣乱的一层意思。","sec":"八、相破","t":"diff"}],"fine":[{"q":"合的四种用法中，「合制」与「合伤」的核心区别是什么？","opts":["合制主双方同时失去原性；合伤主双方相生而共同增力","合制是按强弱一方被合去；合伤是强弱相差不悬殊，克方克去被克方","合制只发生在天干之间；合伤只发生在地支六合之间","合制是流年合住原局之字；合伤是力量相当的两字相互绊住"],"ans":1,"exp":"合制是强弱悬殊时一方被合去；合伤是双方强弱相差不悬殊，克方力量大于被克方而将其克去。","sec":"一、合的四种用法","t":"diff"},{"q":"婚姻应期中，配偶星、配偶宫逢合为应期的三种情形，下列哪项表述准确？","opts":["必须原局星宫全合才应婚，流年无论是合是冲均无应期作用","原局有合流年应穿；原局有冲流年应破；原局无合冲流年应刑","原局有合流年应冲；原局有冲流年应合；原局不冲不合流年见合即应","原局有合流年应合；原局有冲流年应冲；原局无合冲则不婚"],"ans":2,"exp":"婚姻应期逢合的三种情形为：原局有合流年应冲、原局有冲流年应合、原局不冲不合流年见合即应。","sec":"一、合的四种用法","t":"rule"},{"q":"大运与八字发生相合时，八字中的字与大运中的字分别怎么论？","opts":["八字中的字被合是得到；大运中的字被八字合到则是失去原性","八字与大运相合一律按合化成新五行论，不再区分谁得谁失","无论是八字中的字还是大运中的字，只要相合就一律以得到论","八字中的字被合就失去原性；大运中的字被八字合到则是得到"],"ans":3,"exp":"大运与八字相合时，八字中的字一合就失去原性，而大运中的字被八字合到则是「得到」。","sec":"一、合的四种用法","t":"diff"},{"q":"下列哪项不属于天干五合的「换象三原理」？","opts":["双方彻底合化为第三种全新十神","一方可以定义另一方","双方代表同样的信息","一方可以代替另一方"],"ans":0,"exp":"天干五合只讲合不讲化，其换象三原理是：一方定义另一方、一方代替另一方、双方代表同样的信息。","sec":"天干五合的换象三原理","t":"rule"},{"q":"地支六合中，「辰酉合」与「午未合」的作用分别是什么？","opts":["辰酉闭火库并坏申金；午未生旺木库，意义重大","辰酉闭水库并铲断辰中木根；午未最差，只闭墓库","辰酉合化为金局；午未合化为土局，均主大富","辰酉生旺水库并养乙木；午未效率最高，火力猛增"],"ans":1,"exp":"辰酉合一闭水库、二铲断辰中木根；午未合是最差的合，意义不大，只闭墓库。","sec":"二、地支六合各合的作用与暗合","t":"diff"},{"q":"乾造戊戌、壬戌、辛亥、甲午，亥水伤官暗合午火七杀当官，为何行丁卯运反而失权逃亡？","opts":["丁火克辛金日主，导致日主身体重病无法理政","亥卯半合木局财星太旺，贪财坏印而被罢免","丁壬合护住壬水，卯戌合使戌不能制亥，构成反局","卯午相破，使午火七杀变成正官失去权威"],"ans":2,"exp":"原局以戊制壬、戌制亥为功；丁卯运丁壬合护壬、卯戌合牵绊戌土，戌不能制亥而反局，故失权。","sec":"暗合","t":"calc"},{"q":"三合局中，亥卯未、申子辰、巳酉丑三局与「寅午戌」局在最后一字的变化上有何不同？","opts":["只有申子辰的辰被化掉，其余三局后一字均被生","前三局后一字被生旺，寅午戌局里的戌被彻底化掉","四局的最后一字都被中神彻底克死，无一例外","前三局后一字被化掉，寅午戌局里的戌反而被生"],"ans":3,"exp":"亥卯未、申子辰、巳酉丑三局中最后一字被化掉；而寅午戌火局里的戌土（火库）反而被火生旺。","sec":"1. 成局规则","t":"diff"},{"q":"关于巳酉丑三合局的两两组合，下列判断哪项准确？","opts":["巳酉拱局不成不就；酉丑以拱局为主、墓金为辅；巳丑拱金局","巳酉以墓金为主；酉丑完全冲散；巳丑拱火局","三者两两组合都能独立成完整三合局，力量完全相等","巳酉成完整金局；酉丑只论墓金不论拱；巳丑绝不拱局"],"ans":0,"exp":"巳酉为拱局不成不就；酉丑有两重性，以拱局为主、以墓金为辅；巳丑拱金局且巳火被晦。","sec":"1. 成局规则","t":"diff"},{"q":"寅戌拱火与巳丑合局时，对局中「辛金」的影响分别是怎样的？","opts":["寅戌拱火能克尽辛金；巳丑合局辛金反克丙火","寅戌拱火戌中辛金克不动；巳丑合局丙火不能克辛金","寅戌拱火辛金被生旺；巳丑合局辛金被丙火彻底合化","寅戌拱火戌中辛金必被克死；巳丑合局丙火必克死辛金"],"ans":1,"exp":"巳丑合局时巳火被晦，丙火不能克辛金；寅戌拱火，戌中辛金同样克不动。","sec":"1. 成局规则","t":"rule"},{"q":"乾造甲寅、癸酉、丁丑、庚子，原局有晚婚信息，为何在丙子运癸未年认为能成婚却实际不成？","opts":["未土食神合住寅木，把配偶星庚金彻底藏起来","酉丑半合金局太旺，把甲木正印全部克断","子丑合闭库且大运无结婚信号，未子穿、丑未冲均穿倒","癸水七杀透出克制丁火日主，导致女方家坚决反对"],"ans":2,"exp":"丙子运子丑一合闭库且大运无婚讯，癸未年未子穿、丑未冲，未只能穿倒又有子合丑，故不成。","sec":"2. 命例","t":"calc"},{"q":"大运冲八字、流年冲八字与流年冲库，在盲派中的定性分别是（　）。","opts":["大运冲八字为动，流年冲八字为冲破，流年冲库为冲坏","三者一律都论冲破，只要逢冲必主大凶","大运冲八字为冲开，流年冲八字为冲去，流年冲库为合绊","大运冲八字为冲破，流年冲八字为动，流年冲库为冲开"],"ans":3,"exp":"大运冲八字为冲破（一冲二为冲动）；流年冲八字为动，流年冲库则为冲开。","sec":"1. 冲的总则","t":"diff"},{"q":"运干管前五年、运支管后五年，当行天干运与行地支运时，流年冲大运分别怎么论？","opts":["行天干运流年冲大运为冲动引动；行地支运流年冲大运为冲去离开","无论行天干运还是地支运，流年冲大运都必主大凶破财","行天干运流年冲大运完全不起作用，只有地支运才论冲","行天干运流年冲大运为冲去离开；行地支运流年冲大运为冲动引动"],"ans":0,"exp":"行天干运时，流年冲大运是冲动（提前引动）；行地支运时，流年冲大运为冲去（暂时离开，不一定凶）。","sec":"1. 冲的总则","t":"diff"},{"q":"天干四冲（甲庚、乙辛、丙壬、丁癸）在应期断法上常见于什么情况？","opts":["天干四冲只主破财与官灾，从不用于婚姻应期","合处逢冲、冲处逢合，一般为结婚应期","必须天干四冲同时见地支三刑才算应期","只要原局见天干四冲，必主父母早年离异"],"ans":1,"exp":"天干四冲（甲庚、乙辛、丙壬、丁癸）配合原局合冲，合处逢冲、冲处逢合，一般为结婚应期。","sec":"1. 冲的总则","t":"rule"},{"q":"辰戌冲制库中之物时，若以戌中「辛金」为毛病，辰戌冲能否制住？该如何制？","opts":["辰戌冲与申酉合一样，都能彻底化解辛金","辰戌冲可以直接制死戌中辛金，不必借他支","辰戌冲制不住戌中辛金，只有未土能制辛金","只有子水能制戌中辛金，未土反而生助辛金"],"ans":2,"exp":"戌中辛金最难制，辰戌冲往往只冲出来而制不住；只有未土能制辛金，因为未中内含丁火。","sec":"2. 各冲制的对象","t":"rule"},{"q":"丑未冲在什么条件下才能制去丑中金水？若同时又有子丑合怎么论？","opts":["金水旺时才能制去丑中金水；兼见子丑合则完全不冲","丑未冲永远制不去丑中金水，只主墓库闭死","只要有丑未冲必能制死金水；兼见子丑合则增力","火土旺时才能制去丑中金水；兼见子丑合则减力，能冲能合"],"ans":3,"exp":"丑未冲须火土旺时才能制去丑中金水；既有丑未冲又有子丑合则减力，但仍能冲能合。","sec":"2. 各冲制的对象","t":"calc"},{"q":"乾造乙未、壬午、甲子、庚午，日主断为婚姻失败离婚，其命理核心原因是什么？","opts":["夫妻星制去夫妻宫，搞不定女人反被女人搞定","两午冲一子，两午夹冲把子水彻底冲坏","甲木坐子水沐浴之地，日主自身桃花太重","年上乙木劫财合住庚金，把妻子让给别人"],"ans":0,"exp":"夫妻宫的十神制夫妻星忌神才吉；此造子水夫妻宫反被午火夫妻星制去，反了，故被女人搞定而离婚。","sec":"3. 命例","t":"calc"},{"q":"坤造壬子、丙午、己巳、己巳，火土制去子水大富，为何行壬运癸未年反而破败不好？","opts":["癸未年未土把己土比肩合走，无人帮忙经营","未合绊午使午不能冲子，违背原局用冲制而非穿制的组合","壬水透干生旺甲木官星，官杀混杂克身致灾","未土穿倒午火印星，导致日主失去全部文化名声"],"ans":1,"exp":"癸未年未虽制子，但未合绊午使午不能冲子，违背了原局用冲制而不是穿制的意象，反局必凶。","sec":"五、冲的换象","t":"calc"},{"q":"乾造丁未、癸丑、丙子、壬辰，日主成为亿万富翁且不以从杀格看，其核心做功是什么？","opts":["子辰半合水局生旺七杀，属于纯正杀印相生","未土食神直接生助丑土财星，靠辛苦劳动致富","丑未冲，财库冲去劫财库，为控制管理之意","丁壬合化木生丙火，属于身旺用食伤生财"],"ans":2,"exp":"核心是丑未冲，以财库冲去劫财库（劫财当财看），主资金控制管理，是搞资金控制的大集团老板。","sec":"五、冲的换象","t":"calc"},{"q":"关于相穿在不同层面的轻重，流年穿大运、流年穿八字与命局被穿分别怎么论？","opts":["流年穿八字能开库发财；流年穿大运主升官","三者凶性完全相同，只要见穿必主六亲当年死亡","流年穿大运最凶；流年穿八字无所谓；命局被穿反主大吉","流年穿大运无所谓；流年穿八字是受制受阻；最怕命局中被穿"],"ans":3,"exp":"大运是外来的，流年穿大运无所谓；流年穿八字是受制、心情不好、办事受阻；最怕命局自己被穿。","sec":"1. 穿的性质","t":"diff"},{"q":"当「配偶宫大运受穿」时，对未婚者与已婚者分别有什么应验？","opts":["未婚则此运不能结婚；已婚会出问题但不一定离婚","未婚者此运桃花极旺；已婚者夫妻感情更加恩爱","无论未婚还是已婚，都只影响财运不影响婚姻","未婚则此运必闪婚；已婚则必在当年立刻离婚"],"ans":0,"exp":"配偶宫大运受穿时，若此运未婚则不能结婚，已婚则会出婚姻问题，但不一定离婚。","sec":"1. 穿的性质","t":"rule"},{"q":"酉戌相穿中，要将「戌土」穿倒需要满足什么条件？","opts":["只要酉戌相邻，不管金旺金弱都能穿倒戌","金特别旺时才能穿倒戌","酉金永远穿不倒戌土，只有戌土能穿倒酉金","火特别旺时才能穿倒戌"],"ans":1,"exp":"酉戌相穿属克泄穿，虽力量较大，但金特别旺时才能穿倒戌。","sec":"1. 穿的性质","t":"rule"},{"q":"坤造乙卯、甲申、丁亥、辛亥，地支「申亥穿」在职业与婚姻上分别造成了什么后果？","opts":["穿出偏官变正官得以升职；婚姻宫被生旺而早婚","申亥合化为水生木，在公家单位一路平步青云","穿倒正财正官致失去稳定工作；星宫相穿致婚姻不顺","把申金彻底穿死致终身贫穷；把亥水穿坏致终身无子"],"ans":2,"exp":"申亥穿虽生穿未穿坏，但穿倒正财正官成偏财偏官，故失公家稳定工作；且星宫相穿主婚姻不顺。","sec":"2. 命例","t":"calc"},{"q":"关于三刑在六亲与伤病方面的象义，下列哪项说法符合盲派论断？","opts":["墓中六亲被三刑坏掉，主寿终正寝且无任何病痛","三刑见金必主大富；见父母星主父母长寿高官","三刑占全者六亲和睦兴旺，只是自己事业多波折","三刑见金多伤病残疾；见父母星多早逝；占全者六亲均不吉"],"ans":3,"exp":"三刑见金六亲多伤病残疾；见父母星多早逝；墓中六亲被坏多突然死亡；三刑占全者六亲都不吉利。","sec":"七、三刑","t":"rule"},{"q":"同为三刑，寅巳刑与丑戌、未戌刑在作用方式上有何区别？","opts":["寅巳刑以穿为主、刑力很小；丑戌、未戌为刑开库、坏库","寅巳刑刑力最大；丑戌、未戌以合为主、不主开库","三者均以相生为主，都不带有伤害或动摇之意","寅巳刑能直接刑开火库；丑戌、未戌刑不开任何墓库"],"ans":0,"exp":"寅巳刑以穿为主，刑力很小，意为倒了、动了；丑戌、未戌则能刑开库、坏库。","sec":"七、三刑","t":"diff"},{"q":"对比乾造壬子、癸卯、壬子、丙午与壬子、癸卯、壬子、甲辰，为何前者沦为乞丐而后者为人一般？","opts":["前者丙火财星透干被劫财夺尽；后者甲木食神被辰土生旺","前者卯破午使午火无生、伤官无用；后者未破食伤能泄身","前者缺少辰土财库守财；后者辰土财库直接冲开得大财","前者子午冲把日主坐下冲垮；后者子辰半合水局成势当官"],"ans":1,"exp":"前者卯破午，午火弱且卯不生午，伤官一无所用故成乞丐；后者未破食伤能泄身，以伤官当财当妻。","sec":"2. 命例","t":"diff"}]},{"n":86,"level":"高级","title":"体用宾主与看盘总纲","qs":[{"q":"盲派按位置分宾主，下列哪项归「主」？","opts":["年柱与月柱","日主以外的干支","日主与日支","岁运"],"ans":2,"exp":"日主、日支是主位，有时时柱也算主；年月柱是先天定的祖上父母，岁运是外来的东西，都属宾。","sec":"一、宾主：按位置分","t":"diff"},{"q":"按十神分体用，哪一组是「体」？","opts":["印、官、杀","食神、伤官、财","财、官、杀","比肩、禄、印、劫财"],"ans":3,"exp":"体是我的本钱、工具：比肩、禄、印、劫财；用是我追求的目的：财、官、杀；食伤中性。","sec":"二、体用：按十神分","t":"rule"},{"q":"食神与伤官在体用上怎么归属？","opts":["中性，食神偏体、伤官偏用","食神偏用、伤官偏体","都是用","都是体"],"ans":0,"exp":"食伤是中性，食神偏体、伤官偏用，可当体也可当用。","sec":"二、体用：按十神分","t":"diff"},{"q":"功神与废神的区别是什么？","opts":["功神是体，废神是用","功神产生效率，废神不产生效率","功神是旺字，废神是弱字","功神生日主，废神克日主"],"ans":1,"exp":"用体取用叫做功，做功的字是功神；消耗能量却无效率或效率极低的是废神。","sec":"二、体用：按十神分","t":"diff"},{"q":"盘中是杀印相生，印化官杀，这属于做功五种结构里的哪一种？","opts":["生用","制用","化用","合用"],"ans":2,"exp":"以印化官杀为化用，多是当官的；制用是比肩去财、伤官去官等，生用是食伤生财。","sec":"三、做功的五种结构","t":"calc"},{"q":"盘中是食神、伤官生财，按做功五种结构属于哪一种？结果怎样？","opts":["墓用，利用墓库收藏财","制用，能去官杀而当官","化用，多是当官的","生用，靠劳动创造财富，一般不发大财"],"ans":3,"exp":"食伤生财、食伤泄秀属生用，靠劳动创造财富，一般不发大财。","sec":"三、做功的五种结构","t":"calc"},{"q":"在八字类型中，A类「去用结构」去哪个字要特别慎重？","opts":["去禄，因为禄是自身","去官，因为官是权力","去财，因为财是妻星","去印，因为印是母星"],"ans":0,"exp":"去用结构占约四成，去干净吉、去不净凶；禄为自身，去禄要特别慎重。","sec":"四、八字的八个类型（按做功结构分比例）","t":"diff"},{"q":"一个八字没有功神、找不到做功之神，盲派认为是什么层次？","opts":["普通八字，有工作有饭吃","差八字，找不到做功之神","富贵八字，成气成势","特殊八字，靠大运发"],"ans":1,"exp":"差八字没有功神，废神越多越差；功神越多层次越高，废神越多层次越低。","sec":"五、八字的层次","t":"rule"},{"q":"盲派看盘入手，最先看哪里？","opts":["年柱，先看祖上是否有根","月令，先看用神是否得令","主位，先看日柱、时柱","大运，先看现行大运好坏"],"ans":2,"exp":"先从主位入手：主位的东西可用、力量大，八字好；主位的字不可用，八字差。","sec":"六、看盘入手顺序","t":"step"},{"q":"「杀」落在主位，按盲派要求是什么？","opts":["一定要被合走才吉","有杀就吉，无用也吉","只要日主旺相就吉","一定要用才吉，无用则凶"],"ans":3,"exp":"体在主位一定要有用；杀在主位一定要用才吉，无用则凶；财在主位本身就有用。","sec":"六、看盘入手顺序","t":"rule"},{"q":"禄在年上与禄在月上起作用，分别主什么？","opts":["年上受苦无成，月上侍候别人","年上主远方发财，月上主得官","年上主祖业丰厚，月上主兄弟","年上侍候别人，月上受苦无成"],"ans":0,"exp":"禄在年上为受苦、没有成就；禄或劫财在月上起作用，一般为侍候别人。","sec":"六、看盘入手顺序","t":"diff"},{"q":"盲派说解灾的绝招是什么？","opts":["找生助日主的人","找八字中制你忌神的人","找日支所冲的人","找与日主相合的人"],"ans":1,"exp":"解灾的绝招：找八字中制你忌神的人，如周命制毛命的病，是毛的得力助手。","sec":"六、看盘入手顺序","t":"rule"}],"fine":[{"q":"盲派六大要诀中的「虚实喜忌」，对干支虚实的基本规定是什么？","opts":["年月为虚，日时为实","天干为实，地支为虚","天干为虚，地支为实","用神为虚，忌神为实"],"ans":2,"exp":"盲派六大要诀包含干支配置、宾主理论、十神活论、虚实喜忌（天干为虚、地支为实）、应期理论、看八字之象。","sec":"体用宾主与看盘总纲","t":"rule"},{"q":"盲派按位置分宾主时，以八字整体与岁运对比，以及以日柱与他柱对比，各怎么归属？","opts":["八字整体与岁运都是主；只有年月柱才是宾","日柱与月柱同为小家庭主；年柱与时柱同为他人宾","岁运为主、八字整体为宾；日柱为宾、他柱为主","八字整体为主、岁运为宾；日柱为小家庭主、他柱为他人宾"],"ans":3,"exp":"宾主具有多层对应：日柱（小家庭）对他人之柱为主对宾；八字整体（自我）对外来岁运亦为主对宾。","sec":"一、宾主：按位置分","t":"diff"},{"q":"做功五种结构中，下列哪一组完全属于「制用」的范畴？","opts":["比肩去财、伤官去官、食伤制杀、印制食伤、财制印","日干合财、日支合官、日主合印、三合拱局","食伤生财、食伤泄秀、杀印相生、官印相生","财库逢冲、杀库收官、印库收藏、比劫入墓"],"ans":0,"exp":"制用指比肩去财、伤官去官、食伤制杀、印制食伤、财制印；合用看日干支合，化用为印化官杀，生用为食伤生财泄秀，墓用为墓库控制。","sec":"三、做功的五种结构","t":"rule"},{"q":"在八字的八个类型中，占比最大（约40%）的A类去用结构，其判断吉凶的关键原则是什么？","opts":["去用结构只看天干相克，地支相冲不计入去用","旺方去掉弱方，去干净则吉、去不净则凶","弱方去掉旺方，去干净则凶、去不净则吉","只要八字中有去用动作，不论去得干不干净均主大贵"],"ans":1,"exp":"去用结构占约40%，核心是旺方去掉弱方：去财、去官、去印、去伤、去劫、去禄，去干净吉，去不净凶。","sec":"四、八字的八个类型（按做功结构分比例）","t":"rule"},{"q":"八字类型中的D类「合用结构」与E类「无用结构」（各约占10%），核心区分在于什么？","opts":["合用结构越合越旺；无用结构全靠食伤生财致富","合用结构一律主大富大贵；无用结构只是普通上班族","合用须所合之物有用才吉，合忌神成病；无用结构废字多为贫命","合用结构专指地支三合局；无用结构专指天干五合"],"ans":2,"exp":"合用结构看日主逢合财官，所合有用才吉、合忌神成病；无用结构字无作用、废字特多，为贫命。","sec":"四、八字的八个类型（按做功结构分比例）","t":"diff"},{"q":"乾造丙午、辛卯、丁卯、壬子，丙辛合劫财去财，为何能断为发财命？","opts":["地支卯木印星生助午火，食伤泄秀而发大财","壬水正官坐子水得禄，属于纯正的杀印相生格","子午相冲把日主坐下冲活，财库大开而致富","去用兼合用，且丙劫财坐下午火正是日主的禄"],"ans":3,"exp":"丙辛合是劫财去财（去用兼合用），关键在于此丙火劫财坐下是日主的禄（午），等于自己得禄，故发财。","sec":"四、八字的八个类型（按做功结构分比例）","t":"calc"},{"q":"乾造戊申、甲子、甲寅、丙寅，杀印相生且每个字都有用，为何行卯运虽「卯刑子」依然好？","opts":["卯申暗合，卯为羊刃为自身，能把官得到","卯木直接冲去申金七杀，彻底消除官杀克身之患","子卯相破反而把子水破旺，印星力量倍增","丙火食神泄尽卯木，使卯木完全不起刑的作用"],"ans":0,"exp":"此造组合极好，卯运虽卯刑子，但卯申暗合，卯为羊刃代表自身，能把申官得到，故行运依然吉。","sec":"四、八字的八个类型（按做功结构分比例）","t":"calc"},{"q":"乾造癸丑、己未、丙辰、甲午，表面火土旺去金水，为何实为平庸之人？","opts":["日主丙火坐辰土湿土，身太弱无法担起火土","日支辰水库未破，年上水入库去不掉，未也去不掉辛金","甲木偏印透在时干，枭神夺食导致一生无财","丑未冲把墓库全部冲坏，财官一起流失殆尽"],"ans":1,"exp":"属于无用结构反例：日支辰水库未破，年上癸水跑到水库里去不掉，未土也去不掉辛金，故平庸。","sec":"四、八字的八个类型（按做功结构分比例）","t":"calc"},{"q":"乾造庚戌、庚辰、戊辰、壬戌，地支四土本意戌冲辰去库发财，为何实为穷命且反局不顺？","opts":["天干两个庚金食神泄身太重，耗尽日主元气","壬水偏财坐戌库被克死，属于比劫夺财格","两辰两戌力量相当去不掉，四支无用且财弱无用","四土太旺形成稼穑格，最怕见水破格致贫"],"ans":2,"exp":"两辰两戌力量相当，冲去不掉辰库，导致四支无用成反局；只能食神生财而财弱无用，故为穷命。","sec":"四、八字的八个类型（按做功结构分比例）","t":"calc"},{"q":"富贵八字与普通八字在「气势」与「做功」上的根本差异是什么？","opts":["富贵八字必须五行全齐；普通八字必定五行缺一","富贵八字只靠大运做功；普通八字原局不许做功","富贵八字绝对没有废神；普通八字全都是废神","富贵八字成气势且主位一致做功；普通八字不成气势或功小"],"ans":3,"exp":"富贵八字都有气或势，主位（日柱）与气势一致然后做功；普通八字没成气成势，或做功效率太低、功小。","sec":"五、八字的层次","t":"diff"},{"q":"在做功的字中，「主要功神」与「辅助功神」如何区分（以寅木生巳火、巳火制申金为例）？","opts":["巳火直接制申金为主要功神；寅木生助巳火为辅助功神","申金被制为主要功神；巳火制申为辅助功神","寅木在先为主要功神；巳火在后为辅助功神","只要参与做功地位就完全相同，不区分主次"],"ans":0,"exp":"参与做功的字叫功神，直接完成制取目的的（如巳火制申金）是主要功神，生助促成者（如寅木）是辅助功神。","sec":"五、八字的层次","t":"diff"},{"q":"看盘入手观察「日干」时，什么情况下应当「弃而不看」转而看日支？","opts":["日干坐下有强根或得禄时","日干什么也不干（不合、不参与做功）时","日干为阴干而非阳干时","日干与月干、时干发生五合时"],"ans":1,"exp":"日干合到哪就是追求什么；若日干什么也不干，就弃而不看，再看日支对其他支的刑冲克害墓或日时禄。","sec":"六、看盘入手顺序","t":"step"},{"q":"看盘入手「定核心」的规则，下列哪项表述准确？","opts":["无论干支是否做功，一律固定以月令为八字核心","日干做功以时干为主，日支做功以年支为主","日支做功以日支为主，日干做功以日干为主，兼有以日柱","无论日干是否做功，一律固定以年柱为八字核心"],"ans":2,"exp":"定核心规则：日支参与做功以日支为主；日干参与以日干为主；干支都参与以日柱为主；以功神为八字核心。","sec":"六、看盘入手顺序","t":"step"},{"q":"「用主位的体制宾位的用」与「用主位的用制去宾位的用」，各自对应什么命格特征？","opts":["前者主大富大贵当高官；后者主一生贫寒无成","两者都是反局结构，同样主牢狱与官灾","前者是思维异于常人的特异人才；后者是平凡大众好命","前者是跟上形势的好命；后者是思维异于常人的特异人才"],"ans":3,"exp":"用主位的体制宾位的用，是跟得上形势、被人看好的好命；用主位的用制去宾位的用，是思维异于常人的特异人才。","sec":"六、看盘入手顺序","t":"diff"},{"q":"坤造壬子、辛亥、丁巳、丙午，地支巳亥冲、子午冲相战不做功，为何仍能出名发财三四百万？","opts":["丙辛合财虚透合到主位，金水一家合住金等于控制了水","子午冲把财星冲入主位，巳亥冲把官星冲出","丁火坐在巳火帝旺之上，身旺自然能扛起官杀","原局水火既济，构成纯正的财官印三奇贵格"],"ans":0,"exp":"地支冲不掉是不做功，功劳全在丙辛合：财虚透合到主位，且金水一家，合住金等于合住控制了水。","sec":"六、看盘入手顺序","t":"calc"},{"q":"乾造丙戌、丙申、乙丑、戊寅，坐支丑为用拉官主老婆助大，为何时干戊土应了职场桃花？","opts":["寅申冲把申金正官冲走，导致夫妻感情破裂","时干戊土为桃花且在时上比他小、同单位，戊寅年到位","时干戊土合住月令申金，构成天干五合换象","戊土直接克制壬水正印，破坏了夫妻宫稳定"],"ans":1,"exp":"坐支丑为用给他拉官故老婆帮助大；时干戊为桃花，在时上主比他小、同单位，戊寅年戊到位而应桃花事件。","sec":"六、看盘入手顺序","t":"calc"},{"q":"乾造癸巳、甲子、丁酉、甲辰，主位酉为核心，一生毛病在辰酉且老婆孩子不好的原因是什么？","opts":["甲木正印太多太旺，印重克子导致子女缘浅","子酉相破把酉金财星破坏，导致家庭经济困难","辰酉合闭库，辰中癸水七杀制不尽，病由酉（老婆）引起","巳火劫财在年柱旺极，直接冲克时柱辰土子女宫"],"ans":2,"exp":"此造体巳在宾、用酉在主，子癸制巳尽，唯病在辰酉合闭库，辰中癸水七杀制不尽，且由酉（老婆）引起。","sec":"七、制与被制的实例（宾主体用的综合）","t":"calc"},{"q":"戴笠乾造丁酉、乙巳、丙戌、丁酉为何能成为蒋介石（丁亥、庚戌、己巳、庚午）最得力的助手？","opts":["两人八字年柱都是丁火，同气相求自然投缘","戴笠日柱丙戌与蒋介石月柱庚戌天克地冲","戴笠命局金水极旺，恰好生助蒋介石的财星","戴笠命局制金，恰好能制蒋介石命中的金水之病"],"ans":3,"exp":"蒋介石命局己土得势归禄而有金水之病；戴笠命局制金，正制蒋命中毛病，故成其得力助手。","sec":"七、制与被制的实例（宾主体用的综合）","t":"calc"},{"q":"乾造庚午、乙酉、庚子、壬午，属去官格，为何庚寅运倒霉而死？若年上没有午火会怎样？","opts":["年上午火制不净、寅运午旺而死；若年上无午，寅运也不死","庚金比肩临绝地而死；与年上是否有午无关","寅冲申破了日主禄根而死；年上无午一样必死","寅子相穿把子水伤官穿死；年上无午则更大贵"],"ans":0,"exp":"此造去官格因年上午火制不干净，行庚寅运生旺午火而死；若年上没有午火，寅运也不会死。","sec":"七、制与被制的实例（宾主体用的综合）","t":"calc"},{"q":"乾造己卯、己巳、辛亥、甲午，木火成势去伤官，为何癸亥运升至副省，壬戌运却到人大且戌运无官？","opts":["癸亥运水木相生助旺财星；壬戌运火土克水太重","癸亥运伤官被制到位；壬戌运亥水虚透故没官","癸亥运金水成势；壬戌运寅卯辰三会木局破格","癸亥运伤官见官发大财；壬戌运戊癸合绊住官星"],"ans":1,"exp":"癸亥运原局要去的亥水伤官到位被制，故飞黄腾达；壬戌运亥水虚透（壬运已虚），故没官了。","sec":"七、制与被制的实例（宾主体用的综合）","t":"calc"},{"q":"乾造庚辰、乙酉、癸卯、庚申，金成势制去食神为何能掌管全国银行（比去财还大）？","opts":["庚金正印代表银行大楼，印多自然管银行","乙木食神生旺财星，靠辛苦劳动积少成多","食神为财的原神，比去财还大，制得净且八字都为自身","辰酉合闭水库，把全国的现金全部锁在库里"],"ans":2,"exp":"食为财的原神，去财的原神比直接去财层次还大，且此造制得彻底干净、八字都为自身，故管全国银行。","sec":"七、制与被制的实例（宾主体用的综合）","t":"calc"},{"q":"同样是制官，「食神制官」与「伤官去官」在当官层次上有何差别？","opts":["两者效率完全相同，官职大小全看印星","食神制官必是大官，因食神温和有礼","伤官去官只能当小官，因伤官太过凶悍","食神制官一般是小官，因食神的效率低"],"ans":3,"exp":"食神制官虽也能当官，但一般是小官，因为食神做功的效率较低。","sec":"七、制与被制的实例（宾主体用的综合）","t":"diff"},{"q":"关于「制的四个提醒」，盲派所说的「贼神」与「弱制」分别指什么？","opts":["制死的叫贼神；天干的制叫弱制","正印化杀叫贼神；食神生财叫弱制","暗合的制叫贼神；冲库的制叫弱制","制不死的叫贼神；地支的制叫弱制"],"ans":0,"exp":"制的四个提醒：制死的叫贼神；制住但制不干净；天干的制叫弱制；制不了千万不要再制。","sec":"八、贼神与捕神（制的四个提醒）","t":"diff"},{"q":"当原局某种字出现「制不了」的状况时，盲派的应对铁律是什么？","opts":["制不了，一律改按从旺格论吉","制不了，千万不要再制","制不了，必须等大运出现比劫再来强制","制不了，必须加大力度用刑冲穿去制"],"ans":1,"exp":"制的第四条重要提醒：制不了的字千万不要再去制它，强行去制反而容易引发凶灾。","sec":"八、贼神与捕神（制的四个提醒）","t":"rule"}]},{"n":87,"level":"高级","title":"能量效率与正用反用","qs":[{"q":"制、化、泄生三种体现方式，按格局高低排序是（　）。","opts":["化最高，制次之，泄生最低","泄生最高，化次之，制最低","制与化相同，泄生最低","制最高，化次之，泄生最低"],"ans":3,"exp":"制是直接干掉对方，格局最高；以印化杀次之；泄生怎么生也生不出上亿，效率最低。","sec":"一、制、化、泄的总排序","t":"step"},{"q":"大人物多是哪类人，为什么？","opts":["凶神有制化的人，凶神灵活善变、不择手段","吉神为用的人，吉神正派受人拥戴","凶神无制的人，凶神力量大无拘束","吉神有制化的人，吉神稳定不易出错"],"ans":0,"exp":"杀伤劫枭为用档次高，灵活适应强；财官印食为用太正派，受约束，成就反低。","sec":"一、制、化、泄的总排序","t":"diff"},{"q":"合制的能量由高到低，最前面的两组是（　）。","opts":["子丑第一，巳申第二","巳申第一，巳酉第二","巳酉第一，子丑第二","巳申第一，卯戌第二"],"ans":1,"exp":"合制次序：巳申＞巳酉＞子丑＞卯戌＞卯申、午亥、寅亥、寅丑、午戌。","sec":"1. 合制：把原神和用神全部制住","t":"step"},{"q":"戊子、丙戌、辛巳、丁亥四个柱，合制效率高的两个是（　）。","opts":["辛巳与丁亥，支制干","辛巳与丙戌，各取其一","戊子与丙戌，干克支","戊子与丁亥，各取其一"],"ans":2,"exp":"干克支效率高，支制干效率低：戊子、丙戌高，辛巳、丁亥低。","sec":"1. 合制：把原神和用神全部制住","t":"calc"},{"q":"子午、卯酉、寅申、巳亥之冲，什么情形才有制的意义？","opts":["一对一力量相当的冲就有意义","只要冲到日主的字就有意义","冲到墓库才算，其他都无意义","形成势力，如二冲一或旺冲衰"],"ans":3,"exp":"冲须成势才能冲伤冲去对方成制；一对一差不多的冲只是冲动、对抗，只有消耗。","sec":"3. 冲制","t":"rule"},{"q":"丑未、辰戌冲库为什么能量最高？","opts":["财官临库不冲不发，冲得干净制得彻底","库一冲即开，不论制得干不干净","冲库开出的都是吉神，不必制","库本身旺，冲则助旺"],"ans":0,"exp":"财官临库不冲不发；但库不用则无用，只有冲得干净、制得彻底才有用。","sec":"3. 冲制","t":"diff"},{"q":"穿制的口诀「体穿用，用坏；用穿体，我得」，意思是（　）。","opts":["体穿用、用穿体，都是得到","主位体穿宾位用则得不到，宾位用穿主位体则得到","主位体穿宾位用则得到，宾位用穿主位体则得不到","体穿用、用穿体，都是得不到"],"ans":1,"exp":"主位的体穿宾位的用，用坏了没缘分；宾位的用穿主位的体，反而得到。","sec":"4. 穿制（子未、酉戌、卯辰、丑午）","t":"rule"},{"q":"正用与反用的区别是（　）。","opts":["正用反用只看大运，不看主宾位","正用力大异常，反用规矩力小","正用主位体制宾位用，反用主位用制宾位体","正用主位用制宾位体，反用主位体制宾位用"],"ans":2,"exp":"正用规矩力小；反用阴阳错位异于常人，组合好则才华智慧大、力大。","sec":"1. 定义","t":"diff"},{"q":"一个八字中宾位的东西被制，要有官运或成就，还需要什么条件？","opts":["被制之字必须是库","被制之字必须是印星","被制之字必须在年柱","被制的宾位之字必须与日主发生关系"],"ans":3,"exp":"如子水印与日主没有关系，被制也无官；庚金生子水生甲木，才是副处级官。","sec":"四、宾位的东西被制，且一定要和日主发生关系","t":"rule"}],"fine":[{"q":"在制、化、泄生三种做功方式中，「伤官生财」所属的泄生类一般能达到什么财富量级？","opts":["只能维持温饱，绝对不到十万","与冲库完全相同，可达几十亿","必定能达到亿元以上级别","十万到百万级，难出几千万上亿"],"ans":3,"exp":"泄生是用自己的力量去生去泄，效率最低、层次低，伤官生财一般是十万、百万级，生不出几千万上亿。","sec":"一、制、化、泄的总排序","t":"calc"},{"q":"同样是当官，「化用」（如以印化七杀）与「制用」相比，官职级别通常有何特点？","opts":["化用不如制用效率高，化用的官级别一般不大","两者效率完全一致，官职大小全看食伤","化用的官级别最高，动辄省部级以上","化用只能发财不能当官，制用才能当官"],"ans":0,"exp":"制是直接干掉对方格局最高；化以印化杀次之，因化用不如制用效率高，所以化用的官级别通常不大。","sec":"一、制、化、泄的总排序","t":"diff"},{"q":"合制的能量次序由高到低排列，紧跟在「巳申、巳酉」之后的第三位、第四位分别是（　）。","opts":["卯戌第三，子丑第四","子丑第三，卯戌第四","寅亥第三，午戌第四","午亥第三，寅丑第四"],"ans":1,"exp":"合制能量排序：1巳申＞2巳酉＞3子丑＞4卯戌＞5卯申、午亥、寅亥、寅丑、午戌。","sec":"1. 合制：把原神和用神全部制住","t":"step"},{"q":"干支自合（如戊子、癸巳、壬午自合）要发挥应有的做功效率，必须满足什么前提？","opts":["必须天干没有其他合","必须原局完全没有墓库","必须在命局中成势","必须落在年柱上"],"ans":2,"exp":"戊子、癸巳、壬午等干支自合，不能孤立看，必须在命局中成势才有效率。","sec":"1. 合制：把原神和用神全部制住","t":"rule"},{"q":"在合制「制干净」的前提下，丙戌、午亥、午戌各自大致对应的财富或官职层次是（　）。","opts":["丙戌亿元级，午亥处级，午戌副省级","午戌百万级，丙戌副省级，午亥只能领工资","三者制干净后层次完全一样，皆为部级","丙戌百万级，午亥可到副省级，午戌处级或副处级"],"ans":3,"exp":"在制干净的前提下，能量决定层次：丙戌可到百万，午亥可到副省级，午戌为处级、副处级。","sec":"1. 合制：把原神和用神全部制住","t":"calc"},{"q":"关于「克制」的效率高低排序，下列哪项说法准确？","opts":["围克、干克支高，邻克低，单克最低","支克干效率最高，干克支次之，围克最低","单纯克制效率最高，邻克次之，围克最低","邻克与单克效率相同，都比围克高"],"ans":0,"exp":"克制看结构：围克（左右上三面围制）和干克支效率高，邻克效率低，单纯克制能量最低。","sec":"2. 克制","t":"step"},{"q":"克制中，「戌申午」三面围制与「辛丁／酉未」简单克制，各自对应的成就层次有何差异？","opts":["戌申午围制力量分散效率低；辛丁／酉未克得专一可发亿万","戌申午围制把申制死效率很高；辛丁／酉未只能混口饭吃领工资","两者效率相同，都只能当基层小职员","辛丁／酉未属于干克支，效率远高于戌申午"],"ans":1,"exp":"戌申午围制左右上三面把申制死，效率很高；辛丁／酉未只是简单克制，能量小，只能混口饭吃、领工资。","sec":"2. 克制","t":"diff"},{"q":"刑库做功中，「未刑戌（制去辛金）」与「丑戌刑（戌把丑制干净）」大致对应的财富级别是（　）。","opts":["两者都必破大财，刑库不能发财","未刑戌几千万上亿；丑戌刑几百万级","未刑戌几百万级；丑戌刑几千万上亿","两者都是几十万级，远不如食伤生财"],"ans":2,"exp":"刑库能量也有大小之分：未刑戌制去辛金为几百万级；丑戌刑把丑制干净，可达几千万上亿。","sec":"3. 冲制","t":"calc"},{"q":"冲制之中，为什么说「以木冲能量最高」？","opts":["因为木冲只伤天干不伤地支","因为木五行代表最高官职印星","因为木永远不会受到金的回克","木冲能把原神和用神全坏了"],"ans":3,"exp":"八字有势的冲制（如寅申、卯酉、巳亥、子午）中，以木冲能量最高，因其把原神、用神全坏了。","sec":"3. 冲制","t":"rule"},{"q":"官命的核心必须有官、杀及印星，它们不管作忌神还是用神都必须满足什么条件？","opts":["必须有根","必须与日干五合","必须虚透在年干","必须全部入墓库"],"ans":0,"exp":"官命的核心必须有官、杀及印星，且官杀及印星不管作忌神还是用神都必须有根。","sec":"5. 官命的能量与效率","t":"rule"},{"q":"官命高格局中，「身旺而从强，官杀作忌神，被旺劫刃反克坏」称为什么格？","opts":["从财弃印格，主经商","劫刃去官杀格，主大贵","伤官见官格，主贫贱","杀印相生格，主文职"],"ans":1,"exp":"身旺而从强，官杀作忌神被旺劫刃反克坏，成「劫刃去官杀格」，主大贵。","sec":"5. 官命的能量与效率","t":"rule"},{"q":"判断官贵时，着重看官杀与印，两者在官命象义上分别主什么？","opts":["官杀主权柄，印主职务","官杀主学历，印主下属","官杀主职务，印主权柄","官杀主名气，印主财富"],"ans":2,"exp":"看官贵着重看官杀与印：为用要辅要配，为忌要制要去；官杀主职务，印主权柄，制用效率最高。","sec":"5. 官命的能量与效率","t":"diff"},{"q":"乾造戊申、己未、癸巳、己未，五年积累十几亿成为股市大庄家，其格局属于哪一类？","opts":["正用格局，主位体制宾位用且食伤生财","化用格局，以印化杀生身而得巨富","从弱格局，日主顺从金水旺势发财","反用格局，用占主位且火土成势制尽宾位体金水"],"ans":3,"exp":"此造用占主位、体在宾位，火土成势制去宾位金水并制尽年位原神，属反用格局，效率极高。","sec":"2. 命例","t":"calc"},{"q":"乾造丙寅、辛卯、甲午、癸酉，地支午火制酉金效率低，为何仍能大吉贵显？","opts":["辛金在月上虚透，被丙火合制尽","癸水正印贴身相生，构成纯正杀印相生","寅午半合火局，把酉金彻底烧化为水","酉金被卯木直接冲去，去用十分彻底"],"ans":0,"exp":"此造用午火制酉金效率虽低，但辛金官星在月上虚透，被年干丙火合制尽，故大吉。","sec":"2. 命例","t":"calc"},{"q":"乾造戊辰、壬戌、癸巳、壬戌，戌土既是财库又是官，既主「父早死」又「占了父的光」的原因是？","opts":["两个壬水劫财克死父星；但戊土正官生助日主","制劫财库且财库在年月故父早死；戌为最大用神故仍占其光","辰戌冲把父星直接冲死；但辰为印星故得遗产","巳火财星入戌墓主克父；但癸水坐巳自合得财"],"ans":1,"exp":"戌是财库又是官，制去劫财库而财临库在年月，父当早死；但戌是最大用神，故仍占了月令戌（父）的光。","sec":"2. 命例","t":"calc"},{"q":"乾造戊辰、壬戌、癸巳、壬戌，原局之病在于什么，为何行庚运时下台？","opts":["病是辰土印库太旺；庚运泄土生水而破局","病是巳火财星太弱；庚运合走乙木伤官而下台","病是壬有两个制不干净；庚运生起忌神壬水而下台","病是戊土官星虚透；庚运食神制杀太过而下台"],"ans":2,"exp":"此造火土制水，病在壬水有两个制不干净；戊辰运制壬吉，至庚运金生起忌神壬水，故下台。","sec":"2. 命例","t":"calc"},{"q":"乾造丙午、辛丑、己卯、辛未，火土去金水当大官，为何行甲辰运反而坐牢十年？","opts":["辰丑相破，把辛金食神全部放出克官","甲木合走辛金食神，导致财源彻底断绝","甲木克去戊土劫财，导致无人助身","甲己一合，且辰穿卯破了原局用神"],"ans":3,"exp":"原局以火土木成势去金水，甲辰运甲己一合羁绊日主，同时辰穿倒卯木用神，故坐牢十年。","sec":"2. 命例","t":"calc"},{"q":"乾造戊申、甲寅、辛卯、癸巳（反用），为何管财、口才好，且主两妻、死儿子？","opts":["财制劫巳申拉回故管财；食弱被制口才好；寅卯为财为宫且寅刑巳","印旺生身故管财；伤官配印口才好；申寅冲直接冲死妻儿","杀印相生故管财；正官合身口才好；巳酉合闭库致婚姻破裂","从财格故管财；比肩泄秀口才好；癸水食神入墓致死儿子"],"ans":0,"exp":"劫财被财制为主财并用巳官拉回故管财；食神弱被制主口才好；卯为配偶宫、寅为副配偶宫且为财故两妻，寅刑巳伤子女宫。","sec":"2. 命例","t":"calc"},{"q":"乾造戊申、甲寅、辛卯、癸巳，为何辰运坐牢五年，而壬戌运反而权力最大？","opts":["辰运合走申金劫财；壬戌运申酉戌三会金局助旺日主","辰运收水使水无制且破卯晦火生金；壬戌运去金水而壬虚透吉","辰运冲戌开库放水；壬戌运戌刑丑把劫财全部制死","辰运甲木入墓；壬戌运癸水七杀透干生印"],"ans":1,"exp":"辰运收水使水无制，同时破用神卯、晦火生金故坐牢；原局去金水，壬戌运壬水虚透为吉的应期，故权力最大。","sec":"2. 命例","t":"calc"},{"q":"乾造甲申、丁丑、辛巳、壬辰，金水去官星忌神得官，为何行「癸运」特别不好？","opts":["癸水合住戊土正印，印星被合走失权","癸水食神克制丁火七杀太过，失去权力","丑中含癸即丑到，财星去不掉为病","癸水与壬水混杂，水多金沉导致身体患病"],"ans":2,"exp":"此造财星去不掉为病，丑中含癸与丑是一个字，行癸运等于丑到，故癸运特别不好。","sec":"2. 命例","t":"calc"},{"q":"乾造壬寅、戊申、丙申、壬辰（股市大庄家），壬水与癸水在取财上的层次差别是什么？","opts":["壬水与癸水层次完全相同，只要见水就发财","癸水为正官比壬水七杀贵气，癸透才发大财","壬水透干反而克丙火日主，癸水才算真财","壬从申中出来为财的牛耳精华，癸比壬差；壬透到位吉"],"ans":3,"exp":"此造主位用申财冲制宾位寅印，壬从申中出来，为财的牛耳精华（癸比壬差），壬透到位即发大财。","sec":"2. 命例","t":"calc"},{"q":"乾造壬寅、辛亥、丙辰、丁酉（五千万富翁），发财的主要级别来自哪里而非哪里？","opts":["主要来自月令亥水入坐下辰库（几千万级）；辰收酉仅几十万级","主要来自年支寅木长生（几千万级）；辛金透干仅几十万级","主要来自时支酉金正财（几千万级）；亥水入辰仅几十万级","主要来自丁壬合化木（几千万级）；辰酉合仅几十万级"],"ans":0,"exp":"用杀制劫而得财，时支酉为财被辰收仅几十万级别；主要是月令亥水入坐下辰库，才达到几千万级别。","sec":"2. 命例","t":"diff"},{"q":"坤造辛亥、甲午、壬午、乙巳，主位财合制宾位比，原局去不干净，为何行「丁酉运」能发财？","opts":["丁酉运酉金生助亥水，比劫帮身一起去赚大钱","丁酉运印星辛金干支都被制，制住印后亥水也就合制干净了","丁酉运酉午相破，破出了午中隐藏的巨额财星","丁酉运丁壬合化木，食神生财源源不断"],"ans":1,"exp":"原局亥水有源（辛印生），巳午去不干净；丁酉运辛金印星干支都被制，源头被断，亥水也就合制干净而发财。","sec":"2. 命例","t":"calc"},{"q":"对比乾造庚子、癸未、甲寅、丁卯与丙子、乙未、甲寅、丁卯，为何前者是副处级官而后者无官？","opts":["前者甲木坐在寅木得禄；后者甲木无根无法担官","前者有庚金七杀透干；后者只有丙火食神无官星","前者子水印与日主发生关系；后者子与日主无关","前者子水被未土穿得更干净；后者子水旺极穿不掉"],"ans":2,"exp":"宾位的东西被制，且一定要和日主发生关系：前者庚生子生甲，与日主相关故为副处级官；后者子与日主无关故无官。","sec":"四、宾位的东西被制，且一定要和日主发生关系","t":"diff"}]},{"n":88,"level":"高级","title":"正局反局进阶","qs":[{"q":"正局与反局的定义是（　）。","opts":["日柱做功意象与原局势一致为正，相反为反","日主旺为正局，日主弱为反局","日柱做功意象与原局势一致为反，相反为正","日支与八字五行平衡为正，偏枯为反"],"ans":0,"exp":"正局：日柱做功表达的意象与原局一致（八字无势而日主能做功也称正局）；反局：意象与原局势力相反，主凶。","sec":"一、定义与三层","t":"rule"},{"q":"原局反局、大运反局、流年反局，凶的范围分别是（　）。","opts":["原局不凶、该运凶、该年凶，运过则吉","原局凶、该运凶、该年凶，运过则吉","原局凶、该运凶、该年凶，运过仍凶","都只主一生凶，不分运年"],"ans":1,"exp":"原局反局则原局凶，大运反局该运凶，过了大运则吉，流年反局该年凶。","sec":"一、定义与三层","t":"diff"},{"q":"盲派看日主表述的意象，「日干合什么」代表（　）。","opts":["日干合什么，就是原局势力所在","日干合什么，就是它最排斥的东西","日干合什么，就是它的本意想得到什么","日干合什么，就是被日支制去的东西"],"ans":2,"exp":"日干合的是日主需要的、想得到的；冲则是日主最排斥的。","sec":"日主表述意象的方式","t":"rule"},{"q":"日主之功与日支之功意思不一致时，以谁为主？","opts":["以月令之功为主","两者各占一半，谁旺听谁","以日支之功为主，不以日主为主","以日主之功为主，不以日支为主"],"ans":3,"exp":"日主与日支同时做功看是否一致，不一致为反局；以日主之功为主。","sec":"2. 日主之功与日支之功相反","t":"rule"},{"q":"日主合的官落在哪个位置，不属于反局？","opts":["合年月上的官，表示自己管理别人","合时柱的官，官坐支只要不冲就不反局","合年月上的官，表示被别人管理","合时柱的官，表示自己管理别人"],"ans":0,"exp":"日主合时柱官，要看官坐下之支做什么；合年月官是自己管理别人，不为反局。","sec":"2. 日主之功与日支之功相反","t":"diff"},{"q":"两党冲合并见，什么情况是反局，什么情况不是？","opts":["有冲合并见就是反局，无例外","间隔相反是反局，内外组合不反","内外相反是反局，间隔组合不反","冲合并见皆不反，只看大运来断"],"ans":1,"exp":"年月合日时冲、或年月冲日时合是间隔，两种做功方式相反则乱；金水在内木火在外，用里制外则意思清楚，不反。","sec":"三、冲合反局（两党相反）","t":"diff"},{"q":"大运反局的判断条件是（　）。","opts":["运生旺了原局的用神","运冲到了日支即为反局","运与原局势力对抗，而又无法被原局所制","运的五行与原局五行相同"],"ans":2,"exp":"行运行到与原局势力相对抗、又无法被原局所制的大运，该运凶，过了大运则吉。","sec":"四、大运、流年反局","t":"rule"},{"q":"反局的现象特征，一般是（　）。","opts":["大部分主离婚，财反局主婚姻不顺","大部分主破财，财反局主牢狱","大部分主疾病，财反局则大富","大部分主牢狱，财反局则一辈子受穷"],"ans":3,"exp":"大部分反局结构都主牢狱；比劫抗杀、官杀对抗、与官方意向矛盾都是对抗法律的组合；财反局受穷。","sec":"五、反局的现象特征与综合判断","t":"rule"},{"q":"日主主位有印比时，最怕什么？","opts":["被财官破，破必有灾","被印比再生，生必有灾","被日支合住，合必有灾","被食伤泄，泄必有灾"],"ans":0,"exp":"主位有印比是自己，要去得财官，所以主位印比最怕被财官破，破必有灾。","sec":"日主表述意象的方式","t":"rule"},{"q":"反局的判法，下面哪种说法对？","opts":["日支的追求与日主一致，也是反局","看日支表达的追求与八字的势是否对抗","只要日支做功方向与八字的势对抗就是反局","日支合去伤官，日支被合制，就是反局"],"ans":1,"exp":"并非日支与八字的势对抗，而是日支表达的追求与八字的势对抗；如日支午亥合去伤官，日支也是被午合制，是正局。","sec":"1. 日支做功方向与八字的势对抗","t":"diff"}],"fine":[{"q":"八字本身「无势」时，什么情况下依然可以称为「正局」？","opts":["日主能做功也称正局","必须等到大运成势后才算正局","只要地支有六合就算正局，不必做功","八字无势一律只能按反局论"],"ans":0,"exp":"正局不仅指日柱做功意象与原局气势一致；若八字本身无势，只要日主能做功，也同样称为正局。","sec":"一、定义与三层","t":"rule"},{"q":"关于日主表述意象的方式，下列哪项说法符合盲派理论？","opts":["日干冲代表日主最想得到的，合代表最排斥的","合为日主需要的、冲为最排斥的，且日支与气势也是日主的表述","主位印比越多越怕见木火，见财官反而最吉","只有日干合才算日主意象，日支与气势与日主无关"],"ans":1,"exp":"日主表述意象有四：日干合是需要、冲是排斥；日支也是日干代表；气势是日主表述；主位印比最怕财官破。","sec":"日主表述意象的方式","t":"rule"},{"q":"日主合「时柱官星」时，判断日主之功与日支之功是否相反，关键要看什么？","opts":["只看官星在天干是否透出，不必理会坐下地支","只要日干合时柱官，一律直接定为正局","看官坐下的地支去干什么，是否与日支做的功相反","只看年柱地支是否与月柱地支相冲"],"ans":2,"exp":"日主合时柱官，官是统领，要看官坐下的支去干什么；若官的坐支与日支做的功相反，就反局了。","sec":"2. 日主之功与日支之功相反","t":"step"},{"q":"乾造辛亥、丙申、己丑、甲戌，日主经常坐牢且有盗窃之象，其命理原因是什么？","opts":["丙火正印透干生身太旺，印旺无制导致懒惰犯法","甲木正官克制己土太过，属于七杀攻身无化","亥申相穿把禄神穿死，日主身体残疾无力谋生","日主合甲欲用戌，日支丑却借金水势刑坏戌，反局且丑为小偷"],"ans":3,"exp":"日主合甲官用甲坐下戌，但日支丑借金水之势刑戌坏戌，反局；戌为劫财为手、丑为阴暗为小偷，故常坐牢。","sec":"2. 日主之功与日支之功相反","t":"calc"},{"q":"乾造乙巳、庚辰、辛卯、丙申，日主乙庚合又丙辛合，为何学生时代就犯牢狱之灾？","opts":["丙辛合欲用坐下申劫财，申反被局中巳火官星制了，反局","卯辰相穿把日主坐下财星穿破，属于比劫夺财犯法","乙木偏财坐卯木太旺，身弱不胜财而盗窃","辰土正印入墓不开，导致学业荒废误入歧途"],"ans":0,"exp":"丙辛合用坐下申劫财，但申不能制官，反被局中巳火官星制住，日主之功与命局相反，故犯牢狱之灾。","sec":"2. 日主之功与日支之功相反","t":"calc"},{"q":"乾造甲辰、戊辰、癸卯、己未与乾造戊辰、壬戌、丁丑、丁未（朱元璋），日主均合月令官星，为何都不是反局？","opts":["因为两造日主坐下都是羊刃，足以抗衡官杀","日主合年月上的官表示自己管理控制别人，属于正局","因为月令官星都处于虚透状态，不与日支冲突","因为两造地支都没有出现任何刑冲穿害"],"ans":1,"exp":"日主合年月上的官星（如银行行长造、朱元璋造）表示自己管理控制别人，与日支制官库并不矛盾，属正局。","sec":"2. 日主之功与日支之功相反","t":"diff"},{"q":"坤造丙子、戊戌、丁丑、丁未，主「丈夫早死」且「子女也不好」，命理原因是什么？","opts":["丁火坐丑土湿泥，日主自身体弱难以生育","戊土伤官透干克官，属于典型的伤官见官克夫","子丑合反局，子夫星入夫宫被未冲戌刑；丑子女星犯三刑","丙火劫财在年上夺去全部财星，导致家贫无子"],"ans":2,"exp":"局意去金水，日支子丑合却追求子水反局；子水夫星合入夫宫被未冲戌刑主夫早死；丑为子女星犯三刑故子女不好。","sec":"2. 日主之功与日支之功相反","t":"calc"},{"q":"乾造癸未、丙辰、戊戌、丙辰，为何事与愿违一辈子受穷（只靠戊癸合有饭吃）？","opts":["两丙火偏印夺食太重，彻底断绝了财源","戊土坐戌火库太燥，水被烤干无法生财","未土羊刃直接穿倒了辰中癸水正财","欲用戌冲辰取财，但辰旺反制戌土成反局"],"ans":3,"exp":"日主本意用戌冲辰取财，但辰土旺秉月令，反把戌土制了（收水伤印），意思相反成反局，故一辈子穷。","sec":"2. 日主之功与日支之功相反","t":"calc"},{"q":"乾造壬寅、戊申、辛巳、戊戌（反局早死）与李宗仁造辛卯、丙申、辛未、癸巳（非反局），关键差异在哪？","opts":["前者戊申一体、日主受戊生是用金；后者辛不受生且合官制申","前者缺少癸水食神泄秀；后者癸水透干通关化杀","前者出生在戌时入墓；后者出生在巳时得长生","前者寅申巳三刑全见；后者只有巳申合没有寅刑"],"ans":0,"exp":"前造巳申合本去金，但戊申一体，辛受戊生是用金，与去金水相反故反局；李宗仁造辛不受生，合官制申，非反局。","sec":"2. 日主之功与日支之功相反","t":"diff"},{"q":"乾造乙酉、己卯、庚子、己卯，日主为何会成为偷抢自行车、摩托车的盗贼？","opts":["原局缺乏印星化杀，七杀攻身迫使日主铤而走险","命局从财，日主却乙庚合、酉冲卯劫财而错方式","己土正印透干太多，印重身懒只想着不劳而获","子卯相刑把食神彻底刑坏，日主毫无谋生技能"],"ans":1,"exp":"命局表述从财（食神生财），但日主乙庚合、庚坐酉冲卯劫财，弄错了发财方式，且子卯刑致灾，故劫偷抢。","sec":"3. 日主合财、合官的反局","t":"calc"},{"q":"坤造己酉、甲戌、甲申、乙丑，金旺成势酉戌穿，为何在「丁丑运」坐牢？","opts":["丑戌未三刑在丁丑运集齐，刑破夫妻宫而坐牢","乙木劫财在丁丑运得根，抢夺日主财产引发官司","官不要财而日主甲己合、坐戌求财，丁即戌在运上与旺官对抗","丁火伤官透出直接克制申金七杀，伤官见官致灾"],"ans":2,"exp":"金旺官不要财，日主意向却求财（与官方意向矛盾）；丁丑运丁即命局中的戌，出来与旺官对抗，故坐牢。","sec":"3. 日主合财、合官的反局","t":"calc"},{"q":"乾造甲寅、戊辰、戊子、癸丑，为何一辈子受穷且在己巳运判刑坐牢？","opts":["子丑合闭了财库，己巳运巳火被丑土彻底晦灭","甲木七杀坐寅木太旺，己巳运寅巳申三刑全动","辰土比肩夺财太重，己巳运比劫更旺破产入狱","戊癸合财实透身弱且戊对抗七杀；己巳运戊通禄、忌神穿寅"],"ans":3,"exp":"戊癸合日主求财但财实透身弱，更严重的是戊土对抗七杀必凶；己巳运戊通禄于巳、忌神穿寅，为坐牢信号。","sec":"3. 日主合财、合官的反局","t":"calc"},{"q":"乾造己巳、壬申、己未、乙丑，火土党与金水党对抗，主「一辈子坐牢」的命理核心是什么？","opts":["前边巳申合、后边丑未冲，比肩与七杀对抗成官反局","壬水正财合住丁火印星，贪财坏印触犯刑律","己土坐未土燥极无水润泽，性格暴躁易犯法","乙木七杀虚透在时干，完全没有根气可用"],"ans":0,"exp":"壬申、乙丑为一党，前边巳申合、后边丑未冲，两党势力相反对抗；比肩与七杀对抗成官反局，合住对抗即被逮。","sec":"1. 原局","t":"calc"},{"q":"乾造戊申、丁巳、戊子、戊午，初看火土成势去子水财星似大富，为何实则非常穷？","opts":["申金食神生助子水财星，源远流长去不干净","年月巳申合、日时子午冲，主宾做功方式相反致财星反局","丁火正印坐在巳火旺地，印旺克制食神断财源","三个戊土比肩争财，把仅有的一点子水瓜分殆尽"],"ans":1,"exp":"火土与金水之间一边（年月）巳申合、一边（日时）子午冲，主宾做功方式相反，属财星反局，故非常穷。","sec":"1. 原局","t":"calc"},{"q":"乾造庚申、戊寅、丁未、庚子，原局靠寅申冲、食神穿杀为功，为何行辛巳运之「巳运」反局受迫害？","opts":["巳火劫财透出辛金偏财，财被劫光而遭人陷害","巳未拱火局太燥，把子水七杀彻底烤干失权","巳为火党，巳申合坏了原局的寅申冲穿，不穿了","寅巳申三刑集齐，导致日主身体重病失去自由"],"ans":2,"exp":"此造靠寅申冲穿做功；行辛巳运之巳运，巳为火党去合申，坏了原局的冲穿，变成合而不穿，故反局受迫害。","sec":"2. 原局冲合反局的其它例","t":"calc"},{"q":"乾造戊戌、甲寅、丁卯、甲辰，原局以卯穿辰为功，为何最怕行「亥」运或「亥」年（如乙亥年重病）？","opts":["亥水正官直接克制丁火日主，属于七杀攻身","亥水冲克巳火羊刃，日主失去最后的护身符","寅亥合绊熄灭寅中丙火，导致日主彻底失势","亥从辰出，合寅卯木局，坏了卯穿辰的做功方式"],"ans":3,"exp":"原局以卯穿辰为功；亥水从辰中出来，去合寅卯木局，改变了穿辰的做功方式（冲合反局），故主重病失权。","sec":"2. 原局冲合反局的其它例","t":"calc"},{"q":"同是火土去金水之局，薄一波造（戊申、甲寅、辛卯、癸巳）辰运坐牢，而丙午、辛丑、己未、辛未造为何「甲运」就坐牢？","opts":["前造丙辰运丙合辛但丙虚；后造甲辰运甲合身且算旺","前造木火势太强丙运制不住；后造甲木直接冲破未库","前造丙火是正官不主牢狱；后造甲木是七杀必主牢狱","前造寅卯辰三会木局护身；后造丑未冲在甲运提前引动"],"ans":0,"exp":"薄造丙辰运丙虽合辛但丙虚，故到辰运才坐牢；后造甲辰运甲木合身且算旺，使制局提前反了，故甲运就坐牢。","sec":"四、大运、流年反局","t":"diff"},{"q":"袁世凯乾造己未、癸酉、丁巳、丁未，火燥土成势制杀与财，为何行辰运被贬职、丙辰年死？","opts":["辰运水库冲开未土，癸水七杀透干直接攻身","辰运晦火生金反局；丙辰年丙虚透且辰酉合保护酉金","丙辰年丙火劫财夺尽丁火禄神，寿元耗尽而亡","辰运与丁卯运天克地冲，把巳火彻底冲灭"],"ans":1,"exp":"辰运晦火生金反局故被贬职；丙辰年巳用神虚透（丙虚无用），同时辰酉合把酉忌神保护起来，反局而死。","sec":"四、大运、流年反局","t":"calc"},{"q":"和珅乾造庚午、乙酉、庚子、壬午，金水有势制火当大官，为何行「庚寅运」被革职查办？","opts":["寅子相穿把子水伤官穿倒，失去了生财的源头","庚金比肩在天干与乙木正财相合，贪财坏了名声","寅运官星午火得长生、日主临绝地，官制不住反局","寅木偏财直接冲克申金禄神，导致破产抄家"],"ans":2,"exp":"原局金水制火为功；行庚寅运，官星午火得长生而日主庚金临绝地，官制不住形成大运反局，故被革职查办。","sec":"四、大运、流年反局","t":"calc"},{"q":"乾造戊申、己未、癸巳、己未，壬戌运戌运大发，为何到「癸亥运」一定反局且癸运就差？","opts":["癸水比肩合住戊土正官，导致日主失去靠山","癸亥干支一气水旺，把未土杀库彻底泡坏","亥水劫财直接冲灭巳火财星，资金链断裂","原局合制申金，亥运冲破其合而反局；癸通于亥"],"ans":3,"exp":"原局巳申合制申金；到癸亥运，亥冲巳破了巳申合而反局，且癸水通根于亥，故癸运就开始变差。","sec":"四、大运、流年反局","t":"calc"},{"q":"乾造庚申、己丑、丙申、乙未，原局丑未冲去印库，为何行「辛卯运」反局且父破财，而「寅运」不反局？","opts":["卯从未出，卯申合使本冲变合为冲合反局；寅运不是合故不反","卯木直接克制己土伤官；寅木却能生助丙火日主","卯酉相冲引动申金；寅申相冲刚好符合原局","辛卯运辛金合住丙火；寅运甲木生助丙火"],"ans":0,"exp":"卯是从未中出来的，本来丑未冲，现卯申合住申入丑墓冲未，本冲变合为冲合反局（卯为父财故父破财）；寅运非合不反。","sec":"冲合反局的大运流年","t":"diff"},{"q":"坤造癸卯、乙丑、辛未、己丑，原局丑未冲制财库发大财，为何行己巳大运甲申年严重车祸成残废？","opts":["丑未戌三刑在流年暗拱而成，刑伤日主筋骨","原局两党相冲为吉，流年己巳与甲申天地合反局","己巳大运巳火正官合住申金，官杀混杂攻身致残","甲申年申金劫财太旺，直接冲克年支卯木偏财"],"ans":1,"exp":"巳是未土的党，申是丑土的党，两党在原局相冲为吉；到己巳运甲申年天地合，冲变合为大反局，故出车祸致残。","sec":"冲合反局的大运流年","t":"calc"},{"q":"乾造癸卯、丙辰、戊子、丙辰，原局穿制卯为功，为何行壬子运「甲申年」被审查丢官罢职？","opts":["甲木七杀透干直接克制戊土日主，七杀无制","甲申年与月柱丙辰天克地冲，把印星冲破","申带官杀入辰党又与卯暗合，违背穿制之意反局","申子辰三合水局太旺，财多身弱不堪重任"],"ans":2,"exp":"原局是辰穿制卯为功；甲申年申带官杀，申入辰之党却又与卯暗合，穿变合违背原局意象，故反局罢职。","sec":"冲合反局的大运流年","t":"calc"},{"q":"乾造庚戌、己丑、丙辰、壬辰，原局戌刑丑制得很好，为何「癸未年」坐牢一年？","opts":["癸水正官透干克丙火，形成官杀混杂之灾","辰戌冲与丑未冲同时爆发，四库全开破产","未土伤官穿倒子水正官，犯了伤官见官","癸未年未土来三刑搅局，坏了原局之意而成反局"],"ans":3,"exp":"原局戌刑丑制得很好，不喜癸未年未土来三刑搅局，坏了原局的意思，属反局，故坐牢一年。","sec":"冲合反局的大运流年","t":"calc"},{"q":"在综合判断中，盲派认为「正局」最典型的结构标志是什么？","opts":["每个字都有用，每一步都在做功，人聪明能干","只要大运不走财乡，一生必定平安顺遂","日主必须身旺得禄，且四柱不见任何七杀","原局完全没有刑冲穿破，五行平和流通"],"ans":0,"exp":"正局的标志是每个字都有用，每一步都在做功，人聪明能干；反局则多主牢狱或财反局受穷。","sec":"五、反局的现象特征与综合判断","t":"rule"}]},{"n":89,"level":"高级","title":"大运流年与应期","qs":[{"q":"按盲派，月柱管人生哪个年龄段？","opts":["35–55 岁","18–35 岁","55 岁以后","1–18 岁"],"ans":1,"exp":"年柱 1–18 岁，月柱 18–35 岁，日柱 35–55 岁，时柱 55 岁以后；年月为早，日时为晚。","sec":"1. 柱的年龄段","t":"rule"},{"q":"交脱诀：大限（柱的年龄段）应凶，而大运逢吉，如何断？","opts":["吉运中也凶，过运亦吉","吉运抵消，终身不凶","此运不凶，过运则凶","此运即凶，过运转吉"],"ans":2,"exp":"交脱诀：大限应凶、大运应吉，此运不克，过运则凶；大限应吉、大运应凶，此运不吉，过运则吉。","sec":"2. 交脱诀（大限与大运的凶吉叠加）","t":"rule"},{"q":"大运干支各管几年？","opts":["运支前五年，运干后五年","运干管十年，运支只作象","运干运支每年轮流管","运干前五年，运支后五年"],"ans":3,"exp":"运干管前五年，运支管后五年。","sec":"3. 大运的体用","t":"rule"},{"q":"走天干运时，运中地支（体）的作用是怎样的？","opts":["本不参与作用，被流年冲合引动才提前参与","完全不参与，流年也引动不了","只在后五年参与，与流年无关","与天干一样全程参与作用"],"ans":0,"exp":"走天干运时地支是体、是象，不参加作用；逢流年冲合引动，地支就提前参与作用。","sec":"3. 大运的体用","t":"diff"},{"q":"「反客为主」指什么，有哪两种方式？","opts":["运中见八字之字到，生旺与墓绝","运中见八字之字到，通禄与现原身","运中冲去八字之字，冲刑与穿害","运中见八字所无之字，通禄与化象"],"ans":1,"exp":"大运中出现八字中的字就是该字到了，方式是通禄（禄神出现）与现原身（遁藏之字透干）。","sec":"二、反客为主","t":"rule"},{"q":"原局地支有戌，大运或流年天干出现丁，应论什么？","opts":["丁克戌，戌被制","丁与戌无关，只论丁本身","丁代表戌的信息，等于戌到","丁生戌，戌得力"],"ans":2,"exp":"戌中遁藏丁，地支遁藏之字在大运流年天干出现，也是该字的应期。","sec":"二、反客为主","t":"calc"},{"q":"口诀「合者主到，冲者主动，墓者主收，穿者主伤」，下列对应正确的是？","opts":["合主到，冲主伤，墓主动，穿主收","合主收，冲主动，墓主到，穿主伤","合主动，冲主到，墓主收，穿主伤","合主到，冲主动，墓主收，穿主伤"],"ans":3,"exp":"流年大运与原局冲合刑穿墓都是应期：合为到、冲为动、墓为收藏、穿为伤。","sec":"3. 冲合刑穿墓","t":"rule"},{"q":"原局有合、流年来冲；与原局有冲、流年来合，分别怎么用？","opts":["原局有合以冲为应，有冲以合为应","原局有合以冲为应，有冲仍以冲为应","原局有合以穿为应，有冲以墓为应","原局有合以合为应，有冲以冲为应"],"ans":0,"exp":"口诀：原局有合以冲为应，原局有冲以合为应。","sec":"3. 冲合刑穿墓","t":"rule"},{"q":"流年冲大运，当运与不当运有何区别？","opts":["不当运为冲去，当运为引动","不当运为引动，当运为冲去离开","两者都是引动，只是轻重不同","不当运不起作用，当运为大凶"],"ans":1,"exp":"流年冲大运：不当运为引动大运，当运为冲去，是暂时离开之意，不一定凶。","sec":"4. 流年与大运之间","t":"diff"},{"q":"流年穿大运，按盲派怎么看？","opts":["大运被穿则该运全废","与穿命局同样凶","无所谓，最怕命局中的字被穿","穿动大运则引出吉事"],"ans":2,"exp":"大运是外来的，流年穿大运无所谓；最怕的是命局中的被穿。","sec":"4. 流年与大运之间","t":"rule"}],"fine":[{"q":"盲派断命体系中，八字、大运与流年三者的分工分别是怎样的？","opts":["八字看吉凶，大运看贵贱，流年定应期","八字看贵贱，大运看吉凶，流年定应期","八字看贵贱，大运定应期，流年看吉凶","八字定应期，大运看贵贱，流年看吉凶"],"ans":1,"exp":"盲派看命分三层：原局八字决定层次贵贱，大运管十年吉凶，具体吉凶何时兑现由流年定应期。","sec":"大运流年与应期","t":"rule"},{"q":"按盲派四柱大限划分，日柱与时柱分别主管人生的哪个年龄段？","opts":["日柱 30–50 岁，时柱 50 岁以后","日柱 18–35 岁，时柱 35–55 岁","日柱 35–55 岁，时柱 55 岁以后","日柱 35–60 岁，时柱 60 岁以后"],"ans":2,"exp":"四柱大限为年柱 1–18 岁、月柱 18–35 岁、日柱 35–55 岁、时柱 55 岁以后；年月为早，日时为晚。","sec":"1. 柱的年龄段","t":"rule"},{"q":"交脱诀中，若大限（柱的年龄段）应吉，而大运恰好逢凶，应如何判断？","opts":["大限吉被冲破，终身不吉","此运半吉，过运不再应吉","此运即吉，过运则凶","此运不吉，过运则吉"],"ans":3,"exp":"交脱诀规定：八字运限应吉但逢凶大运，则此运不吉、不看应期，待过运后应吉。","sec":"2. 交脱诀（大限与大运的凶吉叠加）","t":"rule"},{"q":"交脱诀中，若八字运限应凶，后面又逢吉运，尚未进入吉运时如何断？","opts":["未到吉运必先见凶","吉运提前解凶，不必担心","凶吉相抵，平淡度过","等交入吉运后才见凶"],"ans":0,"exp":"口诀云：运限应凶，后逢吉运，未到吉运必见凶；若是大限应凶正逢吉运，才延至过运应凶。","sec":"2. 交脱诀（大限与大运的凶吉叠加）","t":"rule"},{"q":"走地支大运时，同柱的大运天干如何论其作用？","opts":["彻底失效，即便流年合冲也绝不再参与作用","为体且已过去只看其象，但逢合冲引动也要作用","只在运支最后一年重新掌权，其余时间休囚","与地支共同主事，全程直接参与原局生克"],"ans":1,"exp":"走地支运时天干为体，已过去，只看其象；但如果大运天干逢流年合或冲而被引动，仍要参与作用。","sec":"3. 大运的体用","t":"diff"},{"q":"盲派断流月时加入体用思想，流月主要看其与谁的关联才发生作用？","opts":["看月令，与月令同气才发生作用","看大运，只与大运地支关联作用","看日主，与日主关联才发生作用","看年柱，与年干关联才发生作用"],"ans":2,"exp":"断流月要加入体用思想：流月看日主，与日主发生关联（如合、冲、禄等）才发生作用。","sec":"3. 大运的体用","t":"rule"},{"q":"若流年为乙酉，按盲派流月应事规律，乙日主的重要事情最易在哪个月发生？","opts":["子、午月及壬月","寅、申月及甲月","辰、戌月及戊月","卯、酉月及庚月"],"ans":3,"exp":"流年乙酉，重要事情多应在冲合或坐实流年的卯、酉月；且乙日主与庚相合，易在庚月发生关联。","sec":"3. 大运的体用","t":"calc"},{"q":"在「反客为主」中，禄与原身代表的方向有何不同？","opts":["禄是天干派到地支代表天干，原身是地支放到天干代表地支","禄是地支放到天干代表地支，原身是天干派到地支代表天干","禄只代表阳干，原身只代表阴干，二者互不通用","禄专主寿命吉凶，原身专主官禄财帛，作用范围不同"],"ans":0,"exp":"禄是天干派到地支上行使权力的，代表天干；原身是地支放到天干上行使权力的，代表地支。","sec":"二、反客为主","t":"diff"},{"q":"关于寿元星见禄与大限的关系，下列判断正确的是？","opts":["无论哪个大限，见禄一律主寿元终结","日柱大限之前见禄不为寿到，时柱大限后怕见禄","年柱月柱大限见禄最怕寿到，时柱大限见禄反而长寿","只有日柱大限怕见禄，时柱大限见禄反主延年"],"ans":1,"exp":"大限日柱之前见禄不为寿到，大限后（即时柱大限）怕见禄；禄逢冲、刑、破、穿、墓皆凶。","sec":"二、反客为主","t":"diff"},{"q":"盲派地支相穿断生死中，哪一组相穿最主凶死之象？","opts":["寅巳相穿","申亥相穿","酉戌相穿","卯辰相穿"],"ans":2,"exp":"禄逢冲、刑、破、穿、墓都不好，其中酉戌穿在断寿元与灾祸时最主凶死。","sec":"二、反客为主","t":"xiang"},{"q":"某字在原局本有作用，若在大运或流年出现（或见其禄、原身），此运此年有何规律？","opts":["该字必须经过三次合冲后才能发挥原局作用","该字只作为外在环境，不再参与原局做功","该字作用必然与原局相反，吉变凶、凶变吉","该字产生的作用与它在原局中的作用一致"],"ans":3,"exp":"八字中某字在流年或大运出现，或见其禄神与原身，此运此年所发生的事及产生的作用与原局该字相同。","sec":"1. 字的出现","t":"calc"},{"q":"女命原局合夫星的地支遁藏原身，若在大运天干「虚透」，主婚姻有何象？","opts":["夫有名无实，不顾家或闹离婚","夫妻恩爱和睦，必定早婚得子","夫星入墓得藏，婚姻稳固无波","夫星显达贵气，丈夫升职加薪"],"ans":0,"exp":"原身（如午中己合亥中甲）在大运虚透，虽见夫象却无实根，主夫有名无实、不顾家、闹离婚。","sec":"1. 字的出现","t":"xiang"},{"q":"原局以食神为寿元星且在天干受生，行运至其禄地（落入地支）却原局生源受克、他支绝泄，再逢流年冲禄时如何断？","opts":["禄神得冲而旺，反主名利双收","食神被坏，寿元或人身易遭大凶","食神入地藏锋，平顺无灾渡过","冲禄即生印星，反得贵人相救"],"ans":1,"exp":"天干食神落入地支禄地，若原本受生之源无法生到地支，反被他支绝泄，流年一冲禄支则食神被坏，应凶灾。","sec":"1. 字的出现","t":"calc"},{"q":"原局某字透干虚浮代表地支遁藏之字，若此透干之字在原局或运年受克坏，其后果是？","opts":["只伤天干表面名声，地支毫发无损","遁藏之字自动转移到其他地支继续做功","等于坏掉了所代表的那一个地支","地支反而因天干受克而脱胎换骨变旺"],"ans":2,"exp":"原局地支的遁藏字在大运透干即代表该地支，若透干之字被原局或流年克坏，等于坏了该地支之功，主大凶。","sec":"2. 遁藏字出现","t":"calc"},{"q":"原局「乙庚合」伤父星乙木，逢「甲戌年」甲庚相冲反而应父逝，其机理是？","opts":["甲木作为印星，见戌土入墓导致父星随葬","甲木冲破庚金，解了乙庚合后父星无依","流年甲木抢合庚金，乙木失去合神而孤立","弱神冲旺神，冲而应合，冲动庚金反必克乙"],"ans":3,"exp":"甲庚冲是弱神冲旺神，非冲而不合，而是冲而应合：冲能动庚，庚金一动必克伤弱乙木，故应父灾。","sec":"3. 冲合刑穿墓","t":"diff"},{"q":"流年冲原局之字，何时论「冲而破」、何时论「冲而动」？","opts":["局中本弱遇旺神来冲为破，局中本旺遇冲为动","冲年时二柱皆论动，冲月日二柱皆论破","阳支逢冲皆论动，阴支逢冲皆论破","局中本旺遇冲为破，局中本弱遇旺神来冲为动"],"ans":0,"exp":"原局某字本弱，逢旺神来冲是冲而破，不是动意（如财官弱遇冲失工作）；若局中本旺，逢流年冲则是动的应期。","sec":"3. 冲合刑穿墓","t":"diff"},{"q":"原局某柱存在相合关系（如合官、合杀掌权），有时并不在合年应事，而在冲年应事，是因为？","opts":["原局相合皆为假合，只有逢冲才能变成真合","合而应冲，冲有动意，动而促成合局兑现","合局力量太弱，必须先冲散再重新相合","流年冲破合局后，官杀不再受制反而得权"],"ans":1,"exp":"原局有合，有时在流年冲时才应事，属于「合而应冲」——冲有动意，此冲能动而促成原局之合。","sec":"3. 冲合刑穿墓","t":"calc"},{"q":"原局「寅」遇「巳」，寅巳相穿同时带相生，在断工作变动时有何特殊含义？","opts":["寅木入巳火之墓，主工作被他人强行收走","只论刑伤官非，绝不能引动巳火做功","穿而生有动意，能引动巳火参与合事（上岗做事）","穿而绝灭，巳火被寅木彻底扑灭而失业"],"ans":2,"exp":"寅穿巳是穿而生，带有动意；寅既动了巳，若原局有巳申合等做功组合，就能引动合事而主上岗有事做。","sec":"3. 冲合刑穿墓","t":"xiang"},{"q":"局中「丁火食神」可类象为学生与学术成果，若丁通禄于午而午被穿，应何事？","opts":["主门下弟子增多，学术声望传向远方","学生得奖成名，学术成果大获官方认可","仅主命主本人肠胃不适，与学生成果无关","学生或学术成果不顺之事（如成果被盗或徒弟出事）"],"ans":3,"exp":"丁食神可作学生、学术成果，丁通禄于午，午被穿则必应学生或学术成果不顺（如资料被盗卖、徒弟被开除）。","sec":"3. 冲合刑穿墓","t":"xiang"},{"q":"局中「内食神」主企业，若大运墓库收食神且透干合身，同时该运支又穿主位，说明什么？","opts":["进入管企业的单位受领导，但自己不愿留或无实权","企业彻底破产倒闭，命主流落外地打工","自己独资创办大型企业，完全掌握生杀大权","进入公检法机关担任正职，大权独揽"],"ans":0,"exp":"食神入墓库且墓库透干合身，说明进入管理企业的部门；但墓库穿主位，表示自己不愿在那里或无实权，逢刑库年易离开。","sec":"3. 冲合刑穿墓","t":"xiang"},{"q":"流年冲大运时，行「天干运」与行「地支运」的含义有何区别？","opts":["天干运冲大运大凶，地支运冲大运大吉","天干运冲大运为提前引动，地支运冲大运为冲去离开","行天干运时流年根本冲不到大运地支","天干运冲大运为冲去离开，地支运冲大运为提前引动"],"ans":1,"exp":"行天干运时流年冲大运为冲动、提前引动运支；行地支运时流年冲大运为冲去，运支冲走主暂时离开，不一定凶。","sec":"4. 流年与大运之间","t":"diff"},{"q":"流年合大运，按盲派应期规则论作什么？","opts":["反客为主，直接替代原局","合死大运，十年无用","合动大运","合走大运，主远行离家"],"ans":2,"exp":"流年与大运之间：流年合大运为合动；流年冲大运分当运冲去、不当运引动；流年穿大运则无所谓。","sec":"4. 流年与大运之间","t":"rule"},{"q":"在盲派断婚姻与六亲时，口诀「伏吟为走，不是死」该如何理解？","opts":["伏吟主死后魂魄远走，仍旧应验死亡之灾","伏吟主夫妻分居三年后必然复婚","伏吟只主自己外出旅游，六亲绝不会离开","宫位伏吟常主配偶或六亲离开，非死亡"],"ans":3,"exp":"如年柱或夫妻宫伏吟，主奶改嫁远行、前妻带子出国等离开之象，「伏吟为走，不是死」。","sec":"四、大运流年命例（综合）","t":"xiang"},{"q":"某命「身旺财弱」，原局以财库发财，逢大运或流年强力刑冲财库时反容易怎样？","opts":["容易破财，甚至把之前挣的钱输光","财星得冲而清，改行当官掌权","只损偏财不损正财，收入稳中有升","财库大开，必然暴富数倍"],"ans":0,"exp":"身旺财弱时，再遇刑冲财库反而破财（把以前挣的输光）；虽平时靠库发财，但逢重刑冲财弱之库主破耗。","sec":"四、大运流年命例（综合）","t":"calc"},{"q":"若男命配偶宫「丑」被原局「辰」墓收住，结婚的应期通常在什么流年？","opts":["见酉金合住辰库闭墓之年","冲辰开墓、放出丑土配偶宫之年（如戌年）","直接冲配偶宫丑土之年（如未年）","再见丑土伏吟配偶宫之年"],"ans":1,"exp":"配偶宫丑入辰墓被收，只有逢辰戌冲开辰墓、放出丑妻时才能结婚；若逢未年冲丑，反是把配偶宫冲走，成不了婚。","sec":"四、大运流年命例（综合）","t":"calc"}]},{"n":90,"level":"高级","title":"干支象义与干支配置","qs":[{"q":"按盲派干为君、支为臣，天干与地支的克制关系是什么？","opts":["干支都不能互克，只论生合","支可克干，干不克支；干支相合时才论干克支","干可克支，支不克干；干支相合时才论支克干","干支互相可克，以旺者为胜"],"ans":2,"exp":"天干可以克地支，地支不可以克天干；干支相合的情况下才论地支克天干，如辛巳、癸巳、丁亥、己亥。","sec":"1. 干为君，支为臣","t":"rule"},{"q":"甲辰、甲戌两柱，甲木能否克住地支？","opts":["辰土、戌土都能克住","辰土、戌土都克不住","能克住戌土，不能克住辰土","能克辰土，不能克住戌土而甲木被坏"],"ans":3,"exp":"天干克地支，如甲辰甲木能克辰土；甲戌甲木不能克住戌土，则甲木被坏。","sec":"1. 干为君，支为臣","t":"calc"},{"q":"丁丑、乙亥、壬申、庚辰四柱，哪一柱是干生支、成「带象」？","opts":["丁丑","乙亥","庚辰","壬申"],"ans":0,"exp":"干生支（甲午、癸卯、壬寅、丁丑、丙戌等）象一致，叫带象；乙亥、壬申、庚辰是支生干，不算。","sec":"2. 干生支与带象","t":"calc"},{"q":"天干财虚透（不坐根），按盲派主什么？","opts":["主官职权力","不主钱财，主才华、会来事、能说会道","主钱财丰厚，也主才华","主文凭学历"],"ans":1,"exp":"财虚透不主钱财，主才华才气、会来事、能说会道，以吉论；实了才表财运。","sec":"十神虚透的含义","t":"rule"},{"q":"印星虚透，用与忌的文凭情况有何不同？","opts":["印为用虚透有文凭；印为忌虚透没文凭","印不论用忌，虚透都没文凭","印为用虚透没文凭；印为忌虚透有文凭","印不论用忌，虚透都有文凭"],"ans":2,"exp":"印分用忌：为用，虚透没文凭；为忌虚透有文凭（或为忌去印也有文凭）。","sec":"十神虚透的含义","t":"diff"},{"q":"口诀「财官临库不冲不发」，下面哪项是配套的说法？","opts":["合库为吉，为用不合则不能用","穿库为吉，为用不穿则不能用","冲库为凶，为用不冲反而可用","冲库为吉，为用不冲则不能用"],"ans":3,"exp":"戊辰、戊戌、己未、己丑通根，财官临库不冲不发，冲库为吉，为用不冲则不能用。","sec":"二、干支虚实","t":"rule"},{"q":"甲寅、甲午、甲申、甲戌四柱，哪一柱天干为「实」（得根）？","opts":["甲寅","甲申","甲戌","甲午"],"ans":0,"exp":"甲木实：甲寅、甲辰、甲子；甲午、甲申、甲戌为虚。","sec":"二、干支虚实","t":"calc"},{"q":"盲派说「虚为应期」，是指什么？","opts":["岁运的虚字，才能做功","原局的虚字，在岁运见到时应事","原局的实字，在岁运见到时应事","大运只看虚，不看实"],"ans":1,"exp":"口诀：实为用怕虚，虚为用怕实；虚为应期；大运见了实，有制化论吉。","sec":"二、干支虚实","t":"rule"},{"q":"丁未、癸丑这类干支关系，盲派叫什么？与丙戊、丁己有何区别？","opts":["一个字一个象；丙戊、丁己是半个象","藤萝系；丙戊、丁己是原身关系","半禄关系；丙戊、丁己是半通禄（一家）","半通禄（一家）；丙戊、丁己是半禄关系"],"ans":2,"exp":"半禄关系：丁未、癸丑；半通禄（一家）：丙戊、丁己；一个字一个象：丙巳、戊巳、丁午、己午。","sec":"三、干支互通：原神、禄、半禄","t":"diff"},{"q":"甲乙木共根叫藤萝系甲，其中甲木见哪个字为根？","opts":["寅","午","卯","亥"],"ans":3,"exp":"藤萝系甲：甲木见亥为根，乙木见寅为根。","sec":"三、干支互通：原神、禄、半禄","t":"rule"},{"q":"象的三种运用里，食神合印，食神表思想、印代表文章，合起来为思想文化，属于哪一种？","opts":["合象","借象","共象","带象"],"ans":0,"exp":"合象是天干五合、地支六合后两个字互相定义；共象是干支象与十神象配合，带象是干带支或支带干。","sec":"六、象的三种运用","t":"diff"},{"q":"盲派学科对应中，酉金（有时也有申金）对应哪一科？","opts":["化学","物理","语文","数学"],"ans":1,"exp":"戌亥为数学；丙丁火为语文；戌未为化学；酉金为物理，申金有时也是。","sec":"五、十二支之象","t":"rule"}],"fine":[{"q":"干支相合时才论地支克天干，下列哪一组干支符合这一情况？","opts":["甲午、戊子、丙戌、壬戌","壬申、癸酉、丙寅、丁卯","辛巳、癸巳、丁亥、己亥","甲辰、乙未、庚辰、辛丑"],"ans":2,"exp":"干为君、支为臣，通常干克支、支不克干；唯干支暗合（辛巳、癸巳、丁亥、己亥）才论地支克天干。","sec":"1. 干为君，支为臣","t":"calc"},{"q":"壬戌、丙戌两柱若要发生干支自合，需要满足什么条件？","opts":["不用刑开，壬戌、丙戌天然直接自合","必须用辰冲开后，再用酉穿才可自合","必须用丑刑开戌库，不能用未刑","必须用未刑开戌库，不能用丑刑"],"ans":3,"exp":"壬戌、丙戌两柱必须刑开才能自合，且得未刑，不能用丑刑，因为丑为湿土。","sec":"1. 干为君，支为臣","t":"calc"},{"q":"在干支配置论官位大小时，八字成势后制去什么神最易当大官？","opts":["制去官星或官星的长生之神","制去正印或偏印的原身","制去比肩或比肩的禄神","制去食神或伤官的墓库"],"ans":0,"exp":"八字成势后，制去官星或官的长生之神为大官；若运中官星长生入墓或晦火制不住官，则易失权。","sec":"2. 干生支与带象","t":"rule"},{"q":"按盲派干支虚实要点，甲辰日主最怕见哪个地支，因会铲断甲木之根？","opts":["申金","酉金","戌土","巳火"],"ans":1,"exp":"甲辰柱本为实，但甲辰日主最怕见酉金，因辰酉合铲了甲木之根，导致不能成活。","sec":"二、干支虚实","t":"calc"},{"q":"戊辰、戊戌、己未、己丑四库都可以坏，但哪一柱的库绝对不敢坏（辰冲、丑刑都不可）？","opts":["丁未","癸丑","丙戌","壬戌"],"ans":2,"exp":"四库都可以坏，唯独丙戌不敢坏，辰冲、丑刑都不可；丁未柱为实，通根在未，未土也不能坏。","sec":"二、干支虚实","t":"diff"},{"q":"关于壬申日柱与癸酉日柱能否坏坐支（申、酉），下列说法正确的是？","opts":["壬申日柱任何时辰都可坏申，癸酉日柱绝对不能坏酉","壬申与癸酉两日柱在任何时辰都不能坏坐支","壬申日柱生在寅时才可坏申，癸酉日柱生在午时可坏酉","壬申日柱仅生在巳时可坏申，癸酉日柱的酉可被坏被火制"],"ans":3,"exp":"壬申日柱生在巳时可以坏申金，在其他时不能坏；癸酉日柱的酉金可以被坏、被火制。","sec":"二、干支虚实","t":"calc"},{"q":"天干「官星虚透」时，通常不主官职，而主要代表什么？","opts":["名气、名望、头脑聪明伶俐","财源广进、产业丰厚","官非缠身、刑狱之灾","实权在握、执掌生杀大权"],"ans":0,"exp":"官星虚透不为官职，而主名气、名望、头脑聪明伶俐，不主权；杀制尽才当官，官杀有制化当文化官。","sec":"十神虚透的含义","t":"xiang"},{"q":"食伤虚透或弱时，「被制/泄秀」与「食神弱不被制」有何性格差异？","opts":["食伤弱不被制主大富，被制反而主贫寒","被制或泄秀主才华能说会道，弱不被制则不爱讲话","只要食伤虚弱，无论制与不制都主能说会道","被制或泄秀主木讷寡言，弱不被制则口才极佳"],"ans":1,"exp":"食伤虚或弱被制有用、或泄秀，主才华、能说会道；食神弱不被制，则不爱讲话；实了才表财运。","sec":"十神虚透的含义","t":"diff"},{"q":"财星虚透在「时干」与财星虚透「合印」，分别主什么能力？","opts":["透时上守财吝啬，合印则破财损名","透时上主晚年发大财，合印则主考取高学历","透时上能花钱会办事，合印则善沟通有调解表达能力","透时上主出国经商，合印则主继承祖业房产"],"ans":2,"exp":"财虚透不主钱财而主才华，透在时上主能花钱会办事；财虚透合印则会沟通、有调解和表达能力。","sec":"十神虚透的含义","t":"xiang"},{"q":"在干支互通中，「一个字一个象」与「半个象」对应的干支组合分别是？","opts":["一字一象为丙戊、丁未、丁巳；半个象为丙巳、戊巳、丁午、己午","一字一象为丁未、癸丑；半个象为辰戌丑未","一字一象为甲寅、乙卯；半个象为甲亥、乙寅","一字一象为丙巳、戊巳、丁午、己午；半个象为丙戊、丁未、丁巳"],"ans":3,"exp":"丙巳、戊巳、丁午、己午是一个字一个象；丙戊、丁未、丁巳是半个象；丁火见戌土也是半禄关系。","sec":"三、干支互通：原神、禄、半禄","t":"diff"},{"q":"关于辰戌丑未与原身、禄及己未、己丑日主的关系，下列哪项正确？","opts":["辰戌丑未无原身无禄，己未、己丑被刑冲克害不怕坏根","辰戌丑未皆有原身，但只有己丑不怕刑冲","己未、己丑坐下墓库一旦刑冲，日主立即破根大凶","辰以戊为禄、戌以丙为原身，己未、己丑最怕刑冲坏根"],"ans":0,"exp":"辰戌丑未没有原身、没有禄；己未、己丑的地支被刑冲克害，与日主己土无关，不怕坏根。","sec":"三、干支互通：原神、禄、半禄","t":"rule"},{"q":"甲戌、己丑、己未、辛未这四组日柱，若坐下配偶宫墓库没有刑冲，通常主配偶怎样？","opts":["配偶必为公职","配偶不如意","配偶富贵双全","配偶早年离异"],"ans":1,"exp":"甲戌、己丑、己未、辛未四柱，配偶坐下墓库且没有刑冲开库时，主配偶不如意。","sec":"三、干支互通：原神、禄、半禄","t":"xiang"},{"q":"十天干象义中，丙火与丁火在文化传媒及旺衰喜忌上有何区别？","opts":["丙主报纸文章、喜旺不怕衰；丁主影视、不能过旺也不能衰","丙怕水克而喜木焚，丁怕晦火而喜湿土","丙主影视、不能过旺也不能衰；丁主报纸文章、喜旺不怕衰","丙丁都主影视传媒，且都忌讳过旺"],"ans":2,"exp":"丙火主影视、媒体、演说，不能过旺（火多木焚）也不能衰、怕晦火；丁火主文化传媒（报纸文章），喜旺不怕衰。","sec":"四、十干之象","t":"diff"},{"q":"天干中哪两个字被认为「不能成大气」，而癸、辛、丁、甲、戊、庚能成大气？","opts":["乙木、己土","癸水、丁火","庚金、辛金","壬水、丙火"],"ans":3,"exp":"盲派十干气势规律：天干能成大气的有癸水、辛金、丁火、甲木、戊土、庚金，不能成大气的有壬水、丙火。","sec":"四、十干之象","t":"rule"},{"q":"关于活木、死木及四季之水的生木能力，下列判断正确的是？","opts":["癸水、亥水为静水能生木；子水、壬水为流动之水不很生木","子水、壬水为流动之水最能生木；癸水、亥水不能生木","只要见水都是活木，且水能直接生死木","死木最怕金克，活木最怕见火"],"ans":0,"exp":"子水、壬水为流动之水，不很生木；癸水、亥水为静水、雨露，能生木。死木不怕金克、生火秀气；活木见火主文章。","sec":"四、十干之象","t":"diff"},{"q":"辰、戌、丑、未四土的特性中，哪一组土「脆金」，哪一组土「生金且晦火」？","opts":["未丑脆金；辰戌生金晦火","戌未脆金；辰丑不克水、生金、晦火","辰丑脆金；戌未不克水、生金、晦火","辰戌脆金；丑未生金晦火"],"ans":1,"exp":"辰湿润、丑湿寒，皆不克水、生金、晦火（辰晦火力大）；戌燥硬、未干土，皆脆金（未亦克水）。","sec":"四、十干之象","t":"diff"},{"q":"十二地支中，命局若「巳火」占重要位置，人常具有什么性格与变通特征？","opts":["沉默寡言、阴沉算计、不善变通","含蓄谨慎、行动迟缓、固执守旧","遇金变金、遇火变火，灵活且有变色龙倾向","直来直去、性情刚烈、绝不轻易改变立场"],"ans":2,"exp":"巳火遇金强则变金，遇火强则变火；命局有巳火占重要位置，主此人灵活、变化快、思维快，有变色龙倾向。","sec":"四、十干之象","t":"xiang"},{"q":"十二支之象中，「申金」与火相配主武职，若申带伤官、带羊刃分别多应何单位？","opts":["带伤官为法院、律师，带羊刃为企业、工厂","带伤官为银行、税务，带羊刃为学校、医院","带伤官为公安、军队，带羊刃为检察院、纪委","带伤官为检察院、纪委，带羊刃为公安、军队"],"ans":3,"exp":"申主司法、军队、公检法，与火相配主武职；其中申带伤官多为检察院、纪委，申带羊刃多为公安、军队。","sec":"五、十二支之象","t":"xiang"},{"q":"关于「戌土」随十神变化所对应的场所象义，下列对应准确的是？","opts":["伤官库官库易为庙宇，食神库为学校或编辑部","财库易为庙宇道观，羊刃库为杂志编辑部","官库易为学校教室，食神库为医院药房","伤官库易为银行金库，食神库为部队军营"],"ans":0,"exp":"戌为火库、文明之象：作为伤官库、官库易为庙宇，作为食神库为学校，也有编辑部之象；又可为枪库、网吧等。","sec":"五、十二支之象","t":"xiang"},{"q":"盲派学科与文理对应中，下列哪项对应关系完全正确？","opts":["亥子语文、戌未物理、丙丁化学、水土文金火理","戌亥数学、丙丁语文、戌未化学、木火文金水理","戌亥物理、丙丁数学、戌未外语、木火理金水文","申酉化学、丙丁历史、戌未数学、金水文木火理"],"ans":1,"exp":"学科对应：戌亥为数学，丙丁火为语文（到时上、年上为外语），戌未为化学，酉金（有时申）为物理，木火属文、金水属理。","sec":"五、十二支之象","t":"xiang"},{"q":"运用十二地支之象的总口诀是什么？","opts":["地支只看坐下日支，年月时支只作参考","先定地支旺衰，再按五行生克直接定职业","地支的象要看它干什么，配合天干之象和十神透干使用","地支只看十二支本象，不必理会天干与十神"],"ans":2,"exp":"用法口诀：地支的象要看它干什么——必须根据天干之象和十神透干配合使用，不可死板单看地支。","sec":"五、十二支之象","t":"rule"},{"q":"象的三种运用中，「共象」与「合象」的核心区别是什么？","opts":["共象是两字相合互相定义；合象是干支象与十神象交叉","共象必须三合局才能成立，合象只要邻柱相生即可","共象只看天干，合象只看地支","共象是干支象与十神象交叉表同一象；合象是五合六合后两字互相定义"],"ans":3,"exp":"共象有交叉含义（如丙火为眼且是食神亦主眼）；合象是天干五合、地支六合后两字说明同一问题，互相定义。","sec":"六、象的三种运用","t":"diff"},{"q":"同为食伤库做功的教师命造，如何区分「大学老师」与「中专院校老师」？","opts":["做功到时上为大学老师，做功到坐下没到时上为中专","做功到年上为大学老师，做功到时上为小学老师","坐下食伤库被刑为大学老师，被穿为小学老师","食神库主大学老师，伤官库主小学老师"],"ans":0,"exp":"从年到时大致对应小学到大学：食伤库做功到时上（如被时上酉穿）为大学老师；做功到坐下没到时上为中专院校老师。","sec":"六、象的三种运用","t":"xiang"},{"q":"「辰酉合」且辰土食神为药，酉金为阴中之阴表玄学，二者合象常断为何种职业？","opts":["西医外科手术医生","用玄学开药的中医大夫","制药厂财务会计","化工提炼厂工程师"],"ans":1,"exp":"辰土食神其象为中药，酉金为阴中之阴表玄学，辰酉合是将西方拉回来救人，合象为用玄学开药的中医大夫。","sec":"六、象的三种运用","t":"xiang"},{"q":"「戌穿酉」在戌土类象演示中常应凶暴之灾，主要因为戌与酉各自代表什么？","opts":["戌为学校、酉为学生，戌穿酉主退学转校","戌为银行、酉为钞票，戌穿酉主银行升职","戌为枪凶器、酉为禄为人，易应枪击或枪毙","戌为文书、酉为印信，戌穿酉主学历落榜"],"ans":2,"exp":"戌为枪、凶器，酉为禄为人；局中戌穿酉且带劫杀等凶神时，常应抢劫开枪杀人或被枪毙之象。","sec":"七、以戌为例的类象演示","t":"xiang"}]},{"n":91,"level":"高级","title":"宫位、十神、神煞类象深化","qs":[{"q":"月柱与日柱相合、相冲，分别主什么？","opts":["相合离开老家，相冲离不开祖籍","相合相冲都主离开老家","相合主搬家，相冲主不动","相合离不开祖籍，相冲离开老家"],"ans":3,"exp":"月为祖籍、家乡，日为现在的居所；月日相合离不开祖籍，月日相冲肯定离开老家。","sec":"一、四柱宫位总表","t":"rule"},{"q":"看外界对你的评价与看你内心世界，各看天干还是地支？","opts":["外界评价看天干，内心世界看地支","两者都看地支","外界评价看地支，内心世界看天干","两者都看天干"],"ans":0,"exp":"天干表外，地支表内：天干看外界评价，地支看家庭内部关系、内心世界。","sec":"宫位的用法","t":"rule"},{"q":"日支被流年地支穿了一下，通常应什么事？","opts":["远方来的小人，关系疏远","犯小人，且是关系最密切的人","晚辈下属犯小人","祖籍老家的亲戚出事"],"ans":1,"exp":"日支为与自己最近的人，日支来穿一下就是犯小人，并且是与自己关系最密切的人。","sec":"宫位的用法","t":"calc"},{"q":"官杀在盲派里代表什么，不代表什么？","opts":["代表丈夫情人，不代表权力","代表职务权力，也直接代表官非","代表职务权力，不代表官非桃色","代表官司刑伤，不代表职务"],"ans":2,"exp":"官杀代表职务、地位、权力，不代表官非、官司、盗贼、疾病、桃色，那些要靠组合判断。","sec":"官杀","t":"rule"},{"q":"官杀制化得不好时，一般按什么看？","opts":["当食伤看","当比劫看","当印看","当财看"],"ans":3,"exp":"官杀共象之一：官杀制化不好当财看。","sec":"官杀","t":"rule"},{"q":"「正官为夫、偏官为情人」这种说法，盲派怎么看？","opts":["不对，要看宫位，七杀得正位以夫看","对，正官永远是夫","对，偏官永远是情人","不对，要看有无印星"],"ans":0,"exp":"要看宫位：七杀得正位以夫看，正官得宾位为桃花。","sec":"官杀","t":"diff"},{"q":"十神中哪一个与其他十神不同，是越旺越好？","opts":["正财","食神","正官","正印"],"ans":1,"exp":"食神不怕旺，越旺越好，出现在哪都好，只怕被克；其他十神太重多为毛病。","sec":"食伤","t":"rule"},{"q":"盲派说八字里的禄，是什么？有什么忌讳？","opts":["印星在地支，不可被穿","比肩在地支，最喜被刑冲","比肩在地支，不可被刑冲","财星在地支，不可被合"],"ans":2,"exp":"禄是比肩在地支的体现，表示亲历亲为；八字见禄不能被刑冲，禄冲、刑、破、穿、墓都不好。","sec":"禄","t":"rule"},{"q":"羊刃的天干范围是怎样的？","opts":["阴干有刃，阳干无刃","阴阳干都有刃","只有甲丙庚壬四干有刃，阴干也可借用","阳干有刃，阴干无刃"],"ans":3,"exp":"阳干见阴的劫财为羊刃，所以阳干有刃、阴干无刃；羊刃一定要制服。","sec":"羊刃","t":"rule"},{"q":"盲派说墓库象，财星入墓、伤食入墓分别象什么？","opts":["财墓为银行，伤食墓为学校或庙宇","财墓为学校，伤食墓为权力中心","财墓为权力中心，伤食墓为军团","财墓为军团，伤食墓为银行"],"ans":0,"exp":"羊刃墓为军团，伤食墓为学校或庙宇，伤杀墓为权力中心（组织部），财墓为银行。","sec":"墓库","t":"xiang"},{"q":"六亲落在空亡上，什么情况下有毛病？","opts":["旺衰都没事","衰则有毛病，旺则没事","旺则有毛病，衰则没事","旺衰都有毛病"],"ans":1,"exp":"旺喜空，衰不喜空；六亲临空亡，衰有毛病，旺没事。","sec":"空亡","t":"rule"},{"q":"出生时辰为子或午，兄弟姐妹的数量一般如何断？","opts":["两三个，多则五个","两个，月旺四个","一个，多则两个","独一个，多则差三岁以外"],"ans":2,"exp":"子午一个多则两个；卯酉两个月旺四个；寅申巳亥二三个多则五个；辰戌丑未独一个。","sec":"四、宫位的应用：兄弟姐妹与面形","t":"calc"}],"fine":[{"q":"在盲派命理类象体系中，宫位与星神二者谁的作用更大？","opts":["星神的作用大于宫位","年柱看星神，时柱才看宫位","宫位与星神同等重要，不可分先后","宫位的作用大于星神"],"ans":3,"exp":"盲派重宫位轻星神（相对于传统），明确强调「宫位的作用大于星神」。","sec":"宫位、十神、神煞类象深化","t":"rule"},{"q":"按四柱宫位对应身体部位，年柱与时柱分别主管身体的哪些部分？","opts":["年柱主腿足四肢，时柱主头面五官及生殖排泄","年柱主胸部五脏，时柱主躯干脊背肩","年柱主心脑髓，时柱主腰背肋骨","年柱主头面五官，时柱主腿足四肢"],"ans":0,"exp":"宫位对应身体：年腿足四肢，月躯干脊背肩，日胸部五脏六腑心脑髓，时头面手眼嘴耳鼻、生殖排泄器。","sec":"一、四柱宫位总表","t":"xiang"},{"q":"看买卖房产、买车以及搬家移动两处，在四柱宫位中分别看哪一柱？","opts":["买卖房看年支，买车看月支，搬家看年月相冲","买卖房看日支，买车看时柱，搬家看月日伏吟","买卖房看时柱，买车看年柱，搬家看日时相合","买卖房看月柱，买车看日支，搬家看年时伏吟"],"ans":1,"exp":"日支为居所私产，印财日支为买卖房信息；时为门户车辆，印财时柱为买车；月日伏吟为搬家、移动两处之意。","sec":"宫位的用法","t":"xiang"},{"q":"从宫位上看找对象的方式，及看一个人爱不爱打扮，下列对应正确的是？","opts":["年上时上都主父母包办；比劫在月柱爱打扮","月上对象多网恋、日上多相亲；七杀在日支爱打扮","年上对象多长辈介绍、时上多自己处；食伤在时柱门户爱打扮","年上对象多自己处、时上多长辈介绍；正印在年柱爱打扮"],"ans":2,"exp":"年为长辈外亲，年上配偶星有父母长辈介绍的象，时上的是自己处的；时柱为门户化妆，食伤在门户上为爱打扮。","sec":"宫位的用法","t":"xiang"},{"q":"若日支配偶宫与年支发生刑害关系，通常应哪方面的六亲问题？","opts":["兄弟姐妹早年离散","同事领导背后排挤","子女晚年不孝顺","岳父母或公婆关系不好"],"ans":3,"exp":"年柱为公婆、岳父母（外亲），年支看岳父母或公婆；配偶宫与年支发生关系必与之有关，刑害则不好。","sec":"宫位的用法","t":"xiang"},{"q":"正印太重与偏印过重在心性毛病上有何不同？","opts":["正印重依赖懒笨，偏印重自私冷淡不通人情","正印太重主叛逆暴力；偏印过重主墨守成规","正印太重主自私冷淡；偏印过重主懒惰笨拙","正偏印过重都只主聪明灵动，没有负面心性"],"ans":0,"exp":"正印太重依赖、懒惰、不思进取、笨，土印太重更笨；偏印过重则自私、冷淡、不通人情，且多主祖上血缘远。","sec":"印星","t":"diff"},{"q":"天干七杀虚透与地支七杀在性格与表象上有何差异？","opts":["天干七杀虚透表实权在握，地支七杀表胆小怕事","天干七杀虚透表名声，地支七杀表心力强、有心劲","天干地支七杀都只主疾病与官非，毫无区别","天干七杀虚透表暗藏心计，地支七杀表名扬四海"],"ans":1,"exp":"天干七杀虚透表名声，地支七杀表心力强有心劲；七杀透干坐支聪明，能否学好要看印制化是否得当。","sec":"官杀","t":"diff"},{"q":"女命正官在原局「合身」与「不合身」，在盲派看来有何差别？","opts":["合身主官非缠身，不合身主清贵掌权","合身主丈夫早逝，不合身主婚姻美满","合身为管理控制之意，不合身则没意义","合身与不合身都一样主有官职"],"ans":2,"exp":"正官合身为管理控制之意，是你管理别人；正官不合身就没意义。杀印相生者贵，官杀混杂者行官杀运不吉。","sec":"官杀","t":"calc"},{"q":"正财合身与偏财虚透在花钱习惯与感情心性上有何区别？","opts":["正财主单纯欲望，偏财主真爱专一","正财偏财虚透都主发大财，与花钱性格无关","正财合身主乱花钱，偏财虚透主守财节俭","正财合身不大方且真爱，偏财虚透乱花钱且欲望"],"ans":3,"exp":"正财合身人不大方、不乱花钱，感情上是真爱；偏财虚透为才华、主乱花钱，感情上是单纯的欲望、浪漫多情。","sec":"财星","t":"diff"},{"q":"天干食神多与地支食神多在职业类型上有何不同？","opts":["天干多技艺职业，地支多辛劳职业（成格大事业）","天干食神多为辛劳体力活，地支食神多为清闲技艺","天干食神多为武职军人，地支食神多为公检法","天干地支食神多都只主自由散漫，无法成格局"],"ans":0,"exp":"天干食神多为技艺职业；地支食神多为辛劳职业，但地支食神一旦成了格局会从事很大的事业。","sec":"食伤","t":"diff"},{"q":"命局中「劫财在宾位」，通过财库制去劫财库并把劫财拉入主位做功，常是什么命？","opts":["一生靠苦力打工的贫寒之命","擅长资本运营、运作炒作的大企业家","安分守己的基层文职公务员","不涉钱财的寺院僧道之人"],"ans":1,"exp":"劫财在宾位通过财库制劫财库拉入主位做功，主擅长资本运营、运作炒作，常为十几亿资产的大企业家。","sec":"比劫","t":"xiang"},{"q":"禄神在原局中「有印生、印旺不太做功」与「禄无印生」有何区别？","opts":["有印生主短寿多病，无印生主大富大贵","有印生主孤单辛苦，无印生表坐享其成","有印生不太做功表享受，无印生则孤单辛苦","禄无论有无印生，都一律主亲历亲为辛苦劳碌"],"ans":2,"exp":"禄表示财富与享受：禄有印生、印旺、不太做功就表享受；禄无印生则孤单辛苦；禄坏了不享受就辛苦了。","sec":"禄","t":"diff"},{"q":"盲派认为禄在女命中还代表女人的肉体，最忌讳遇到什么情况？","opts":["大运逢天干虚透，主远嫁他乡","原局逢食神泄秀，主一生孤寡无子","原局或大运逢印生，主婚姻被长辈拆散","原局或大运逢刑冲，主易遭强暴或伤身"],"ans":3,"exp":"禄表示女人的肉体：八字见禄不能被刑冲，原局逢刑冲被强暴，大运逢刑冲也不行；日上时上的禄不可坏（时酉可坏）。","sec":"禄","t":"rule"},{"q":"羊刃制官杀的不同组合对应公检法不同部门，下列对应完全正确的是？","opts":["羊刃合杀为公安军队，伤官合杀为检察机关，劫财羊刃制官为纪检委","羊刃合杀为纪检委，伤官合杀为公安军队，劫财羊刃制官为检察机关","羊刃合杀为检察机关，伤官合杀为法院，劫财羊刃制官为军队","羊刃合杀主笔主文，伤官泄羊刃为公安军队"],"ans":0,"exp":"羊刃合杀为掌兵权（公安、军队）；伤官合杀为制贪官（检察机关）；劫财羊刃制官为纪检委；伤官泄羊刃主笔主文。","sec":"羊刃","t":"diff"},{"q":"按盲派墓库「多而墓之」原则，一个字入墓的条件是什么？","opts":["只有地支与天干同时透出才入墓","两个或以上才入墓，单个不入墓","必须三个以上才能入墓，两个不入墓","只要原局见到墓神，哪怕单个也立刻入墓"],"ans":1,"exp":"墓库规则「多而墓之」：亥入辰、寅入未、巳入戌、申入丑、丑未入辰，必须两个或以上才入墓，一个不入墓。","sec":"墓库","t":"rule"},{"q":"按墓库中神、墓神「唯一」原则，下列地支组合中「丑能入临辰墓」的是哪一项？","opts":["辰丑辰","丑未辰","辰寅丑辰","一丑两辰（无间隔）"],"ans":2,"exp":"中神、墓神都应唯一：丑未全就不墓，一丑两辰也不墓；「辰丑辰」丑不入，「辰寅丑辰」两辰被寅隔开，丑入临辰。","sec":"墓库","t":"calc"},{"q":"关于土的墓库，辰、戌、丑、未四土之间谁入谁墓、谁与谁相冲？","opts":["丑土、戌土入辰墓；未和辰为冲，不为入墓","辰、丑、未都入戌墓","只有未土入辰墓，丑土不入辰墓","丑土、未土入辰墓；戌和辰为冲，不为入墓"],"ans":3,"exp":"土墓在辰，未土、丑土入辰墓（丑未全则不墓）；戌和辰为相冲，不为入墓。","sec":"墓库","t":"rule"},{"q":"按驿马查法「申子辰马在寅，寅午戌马在申」，那么巳酉丑与亥卯未的驿马分别是？","opts":["巳酉丑马在亥，亥卯未马在巳","巳酉丑马在卯，亥卯未马在酉","巳酉丑马在申，亥卯未马在寅","巳酉丑马在巳，亥卯未马在亥"],"ans":0,"exp":"驿马按三合局头字对冲取：申子辰（申冲寅）马在寅，寅午戌马在申，巳酉丑（巳冲亥）马在亥，亥卯未（亥冲巳）马在巳。","sec":"驿马","t":"calc"},{"q":"关于空亡在四柱宫位及十神上的应用，下列说法正确的是？","opts":["年上空亡最凶，日上空亡毫无影响","日空与己密切，伤官空无子，年空不严重","什么空亡什么早到，且越空越旺","正印空亡没儿子，伤官空亡主聪明"],"ans":1,"exp":"空亡：什么空亡什么晚、什么缺；日上空亡与己关系密切，年上空也看但不严重；伤官空亡没儿子。","sec":"空亡","t":"diff"},{"q":"若年上伤官（如未土）空亡，原局又有木克未土，为何反主婆婆当大官，且逢未年却反凶？","opts":["空亡使未土彻底消失；逢未年木被土反克而发财","空亡只管青年不管晚年；逢未年只是驿马走动","空亡使木有克土之象无克土之实；逢未年填实受克则病或受整","未土空亡主多子多福；逢未年主添丁进喜"],"ans":2,"exp":"未土空亡时，木有克未土之象而无克未土之实，故婆婆为大官；一旦逢未年填实，木实克未土就应大病或受人整。","sec":"空亡","t":"calc"},{"q":"按出生时辰看兄弟姐妹数量，时辰为「卯酉」与「辰戌丑未」分别如何断？","opts":["卯酉一个（多则两个）；辰戌丑未两个（月旺四个）","卯酉二三个（多则五个）；辰戌丑未四个以上","卯酉独一个；辰戌丑未二三个（多则五个）","卯酉两个（月旺四个）；辰戌丑未独一个（多则差三岁以外）"],"ans":3,"exp":"子午一个多则两个；卯酉两个月旺四个；寅申巳亥二三个多则五个（月令旺）；辰戌丑未独一个，多则差三岁以外。","sec":"看兄弟姐妹的数量","t":"calc"},{"q":"在四柱八字中，哪一柱出现「伤官、七杀」最容易应验兄弟有伤亡？","opts":["月柱","日柱","年柱","时柱"],"ans":0,"exp":"月柱为兄弟宫，月上见伤官、七杀，常主兄弟有伤亡（多在四五岁等早年伤兄弟）。","sec":"看兄弟姐妹的数量","t":"xiang"},{"q":"兄弟姐妹超过五个时用五行生成数，按「阳干用奇数、阴干用偶数」，丙、丁、庚、辛各对应几？","opts":["丙二、丁七、庚四、辛九","丙七、丁二、庚九、辛四","丙三、丁八、庚一、辛六","丙七、丁二、庚五、辛十"],"ans":1,"exp":"五行生成数：水一六、火二七、木三八、金四九、土五十；阳干用奇数（丙七、庚九），阴干用偶数（丁二、辛四）。","sec":"看兄弟姐妹的数量","t":"calc"},{"q":"盲派地支起数口诀中，对应数字「七」与「六」的干支分别是哪些？","opts":["乙庚丑未七，丙辛寅申六","丁壬卯酉七，戊癸辰戌六","丙辛寅申七，丁壬卯酉六","甲己子午七，巳亥六数终"],"ans":2,"exp":"地支起数歌：甲己子午九，乙庚丑未八，丙辛寅申七，丁壬卯酉六，戊癸辰戌五，巳亥四数终。","sec":"看兄弟姐妹的数量","t":"calc"},{"q":"按「面形诀」，寅申巳亥、子午卯酉、辰戌丑未三类日主/时柱的脸型与睡姿对应正确的是？","opts":["子午卯酉面四方侧睡，寅申巳亥脸慢长仰睡，辰戌丑未团团脸仰睡","子午卯酉脸慢长侧睡，寅申巳亥团团脸趴睡，辰戌丑未面四方仰睡","子午卯酉团团脸趴睡，寅申巳亥面四方仰睡，辰戌丑未脸慢长侧睡","子午卯酉面四方仰睡，寅申巳亥脸慢长侧睡，辰戌丑未团团脸趴睡"],"ans":3,"exp":"面形诀：子午卯酉面四方、头旋正、朴实面朝天；寅申巳亥脸慢长、左偏清秀侧着睡；辰戌丑未团团脸、趴着睡。","sec":"面形诀","t":"xiang"}]},{"n":92,"level":"高级","title":"财命的高级断法","qs":[{"q":"局中财星没有原神，按盲派本体系口径先怎么看？","opts":["先当忌神看，必须去掉；去不了才用","先当闲神看，不管不问","先当用神看，有财就用","先看旺衰，身旺才取财"],"ans":0,"exp":"财官无原神或不成气势，先当忌神看；去不了就要用；用也用不上是贱命。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"天干虚透的财与地支有根的实财，哪个算财？","opts":["虚财、实财都算财","实财为财，虚财不为财","虚财为财，实财反主辛劳","虚财为财，但须被合住"],"ans":1,"exp":"虚财不为财，实财才为财；但财虚被比劫克合主大富，是另一层意思。","sec":"一、有财与发财的基本判断","t":"diff"},{"q":"时上见财与刃头财，分别主什么？","opts":["两者都主辛苦求财，毫无区别","时上财主风险之财，刃头财主财进财出","时上财主财进财出，刃头财主风险之财","时上财主稳定积累，刃头财主祖业之财"],"ans":2,"exp":"时上见财为门户财，财进财出；财在羊刃头上是风险之财。","sec":"一、有财与发财的基本判断","t":"diff"},{"q":"财入库而无刑冲，能不能发财？","opts":["能，财入库就是积累","能，大运合库也算发","能，库里财会自行出来","不能，财临库不冲不发"],"ans":3,"exp":"财临库不冲不发；而且要冲得干净、制得彻底才有用。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"下列哪一种结构是发大财的一种？","opts":["主位有财，生到宾位的官，再被宾位之物制住","宾位有财，生到主位的印，再被宾位之物制住","主位有财，生到宾位的食伤，再被主位之物制住","主位有官，生到宾位的财，再被主位之物制住"],"ans":0,"exp":"主位财生宾位官，再被宾位的东西制住这个官，是发大财的结构之一。","sec":"一、有财与发财的基本判断","t":"rule"},{"q":"财星虚透，又被比劫克合，一般断什么？","opts":["主平常，不富不贫","主大富","主婚姻有变","主破财"],"ans":1,"exp":"财做忌神、财星虚弱被比劫制则主富有，财星虚透遭比劫克合者主大富。","sec":"三、伤官当财、劫财去财","t":"rule"},{"q":"用劫财去财取得的财，取财方式多是什么？","opts":["勤劳经营，稳扎稳打","技术手艺，凭本事吃饭","股票、赌博、中介，非勤劳、非正当","继承祖业，守成不变"],"ans":2,"exp":"劫财制财者多为做股票、赌博、中介、不择手段、不劳而获，八字无印尤其如此。","sec":"三、伤官当财、劫财去财","t":"rule"},{"q":"局中官杀被制，但制得不干净，该按什么看？","opts":["官杀当印看","官杀当比劫看","官杀当食伤看","官杀当财看"],"ans":3,"exp":"杀制不净当财看，官杀无制、官入墓、官多财少也当财看。","sec":"三、伤官当财、劫财去财","t":"calc"},{"q":"伤官在盲派里当财看，是什么性质的财？","opts":["谋为之财，野心、投机、风险，故财大","辛苦的禄财，来源于出体力","稳定的正财，来源于工资薪水","祖上的遗财，来源于家业"],"ans":0,"exp":"伤官是所苦心追求的东西，是谋为之财，带野心投机风险，所以财大。","sec":"三、伤官当财、劫财去财","t":"diff"},{"q":"官戴财帽与财戴官帽，各以什么为主？","opts":["官戴财帽以官为主；财戴官帽以财为主","官戴财帽以财为主；财戴官帽以官为主","两者都以官为主，只分大小","两者都以财为主，只分公私"],"ans":1,"exp":"戴什么帽子以什么为主；官戴财帽又没有用官去官的是私企。","sec":"四、财库的冲刑与制财、取财方式","t":"diff"},{"q":"以智力取财的命，典型的结构是什么？","opts":["财星带官，靠官位取财","七杀带印，靠权势取财","伤官带比肩，是自己的才智，能生财","劫财带禄，靠出体力取财"],"ans":2,"exp":"伤官星带比肩，说明是自己的才智，伤官生财，所以靠智力取财。","sec":"五、以智力取财（伤官星带比肩）与其他","t":"rule"}],"fine":[{"q":"一般财官无原神或不成气势时先当忌神看；若去不了又用不上，属于什么命？","opts":["贱命","清贵之命","大富之命","中等小康之命"],"ans":0,"exp":"一般财官无原神或不成气势，先当忌神看；如果去不了，就要用；用也用不上是贱命。","sec":"2. 本体系的判法","t":"rule"},{"q":"在财命取财方式中，「以禄取财」通常具有什么性质？","opts":["投机暴富","辛苦取财","官权得财","坐享祖业"],"ans":1,"exp":"禄也为财，以禄取财属于亲历亲为的辛苦取财，不同于伤官谋为之财或劫财投机之财。","sec":"2. 本体系的判法","t":"diff"},{"q":"若原局财星特别多，走到什么大运时「官统财」而发财？","opts":["走到墓库闭库运","走到食神运","走到官运","走到印运"],"ans":2,"exp":"原局财特别多时，走到官运，官星统领群财（官统财），主发财。","sec":"3. 发财与发大财的结构","t":"calc"},{"q":"下列哪一组均属于「以库取大财」的常见做功结构？","opts":["财库合比劫库、印库生财库、食伤库被闭","财星虚透无根、印星重重无制、官杀混杂无库","财库逢合不动、官库无刑无冲、比劫库空亡","财库制印、财库冲比劫库、劫财库被官库制"],"ans":3,"exp":"财库制印、财库冲比劫库、劫财库被官库制等，都是以库取大财的方式。","sec":"3. 发财与发大财的结构","t":"rule"},{"q":"原局财临库且喜刑冲发财，若大运地支合住该财库（闭库），通常应何事？","opts":["财库被闭，财或病神受保护，主穷或不发财","闭库转为当大官，弃商从政","闭库只影响婚姻，与财运好坏无关","财库被合稳固，主资产翻倍暴富"],"ans":0,"exp":"财临库不冲不发；若遇卯运合戌闭库、子运子丑合闭财库，则库中财受保护而冲制不到，主穷或不发财。","sec":"3. 发财与发大财的结构","t":"calc"},{"q":"从格命局中「从格要有病」，若原局用财库去病神并合到主位，其做功效果是？","opts":["去病却把财库合死，一生贫寒","去病的同时财库也开了，事业得以起步发展","只利六亲健康，对个人财运毫无帮助","病神越去越旺，导致破产坐牢"],"ans":1,"exp":"从格要有病，用财库去病神又合到主位（如丑去未并合入主位），去病的同时财库也开了。","sec":"3. 发财与发大财的结构","t":"calc"},{"q":"「官统财（财旺官弱）」的命局，日后到底是发财还是当官，取决于什么？","opts":["财星透干就发财，财星藏支就当官","官星制化好就发财，制化不好就当官","官星制化不好就发财，制化好就当官","无论官星制化好坏，一律只能发财"],"ans":2,"exp":"官统财（财旺官弱）是财星戴官帽子，官是财的管理者；官制化不好就发财，制化好就当官。","sec":"二、财统官与官统财","t":"diff"},{"q":"「财统官（官旺财弱）」的显著特征与断法是什么？","opts":["官旺财弱必主贫贱，一生受官府克剥","官星与财星各不相干，只能靠体力挣钱","财星戴官帽子，财有多大官就有多大，财当官看","官星戴财帽子，官有多大财就有多大，官当财看"],"ans":3,"exp":"财统官即官旺财弱、官星戴财帽子，官有多大财就有多大，官当财看。","sec":"二、财统官与官统财","t":"diff"},{"q":"戊土日主配「甲寅时」与见「乙木正官」，在受力与意象上有何区别？","opts":["长生在寅故甲寅杀不克身，戊怕乙木正官","甲寅时主戊土贫寒，乙木正官主戊土巨富","甲木、乙木对戊土同样猛烈克制，没有区别","戊土最怕甲寅七杀克身，最喜乙木正官合身"],"ans":0,"exp":"戊土日主配甲寅时，因戊土长生在寅，七杀不克自己、强度不厉害，类似官统财；而戊土怕乙木正官。","sec":"二、财统官与官统财","t":"calc"},{"q":"坐下官星合了印星（如寅亥合），把印拉到主位为自己所用，主什么？","opts":["印代表破财，主负债","印代表权力，主有权","印代表病灾，主短寿","印代表奔波，主无业"],"ans":1,"exp":"坐下官合了印，官把印拉到主位为自己所用，因印代表权力，主有权；若时上财弱坐官旺则是财统官。","sec":"二、财统官与官统财","t":"xiang"},{"q":"「伤官当财看」的命局，为何忌讳财星在天干明现？","opts":["财星明现会直接合走日主","财星明现会生助伤官导致过旺","财星明现会泄伤官之气而损格","财星明现会克坏比肩禄神"],"ans":2,"exp":"伤官当财看者（早期说法宜身旺），忌财星明现，因为财星会泄伤官而损格。","sec":"1. 伤官当财看","t":"calc"},{"q":"在「劫财去财格」中，若原局官杀多且身弱、财也为忌，财星旺与财星弱各有何断法？","opts":["财星旺弱都主富，只要有比劫即可","财星旺弱都主贫，因官杀多不能胜财","财星旺而主富，财星弱而主贫","财星弱而主富，财星旺而主贫"],"ans":3,"exp":"官杀多身弱、财也为忌时，财星弱而主富，财星旺而主贫；财星虚透遭比劫克合者主大富。","sec":"2. 劫财去财格","t":"diff"},{"q":"不论八字何种类型，只要满足什么条件，即主富有？","opts":["财做忌神，财星虚弱被比劫制","财做喜神，比劫成群来分夺","财星入墓，终身不逢刑冲","财做忌神，财星极旺无比劫"],"ans":0,"exp":"不管八字何种类型，只要财做忌神，财星虚弱被比劫制，即主富有；比劫为主、财为客，如用手劫取他人之财。","sec":"2. 劫财去财格","t":"rule"},{"q":"若八字无印且用劫财取财，盲派对命主的行为与交往有何提醒？","opts":["只靠书画文艺挣钱，性格孤高清冷","非正当生意，易不择手段抢骗偷赖，小心交往","为人忠厚老实、勤恳本分，最值得深交托付","必定是清廉正直的公职人员，绝不贪污"],"ans":1,"exp":"八字无印、用劫财取财者，非正当生意也非勤劳赚钱，有的会不择手段、有抢骗偷赖，要小心交往。","sec":"2. 劫财去财格","t":"xiang"},{"q":"按盲派做功效率论，做功效率低或不做功的八字，一般是什么阶层或职业？","opts":["亿万富翁或资本家","公检法司执法官员","农民或无业人员","大学教授或科学家"],"ans":2,"exp":"做功效率低或不做功的八字，一般是农民或无业人员；有功且高效才发财或当官。","sec":"2. 劫财去财格","t":"rule"},{"q":"如丁火日主见「丙辛合」劫财去财，而劫财丙火坐下午火又为日主丁火之禄，这说明什么？","opts":["丁火被丙火合绊，只能打工领死工资","丙火夺去丁火光辉，主有官非牢狱","劫财抢走了日主的禄，主一生破财","劫财坐日主之禄，等于我得禄，发财命"],"ans":3,"exp":"丙辛合劫财去财，劫财丙火坐下（午）为日主之禄，等于我得禄去财，故为发财命。","sec":"2. 劫财去财格","t":"calc"},{"q":"下列哪几种情况在盲派财命断法中，均可以把「官杀当财看」？","opts":["杀制不净、官杀无制、官星入墓、官多财少","比肩抗杀、食神合印、禄神逢冲、印星太重","伤官见官、官杀混杂入禄、正官合身成格","杀被制尽、官印相生、官星虚透、财多官少"],"ans":0,"exp":"杀制不净当财看；官杀无制当财看；官星入墓亦如此；官多财少、官戴财帽，均当财看。","sec":"3. 官杀当财看（杀制不净当财）","t":"rule"},{"q":"原局「两辰一戌」本因辰多冲制不过、制官杀不净，行「己酉运」反发财数亿，原理是？","opts":["酉戌相穿坏掉戌库，官杀失去克制","酉合绊年辰，日支辰得以被戌冲制做大功","酉金生旺辰中水，官杀更旺而压制日主","己土合住戌土，彻底解除辰戌相冲"],"ans":1,"exp":"两辰一戌冲制不过时，大运酉与年辰合绊一辰，使日支之辰被戌冲制做大功，且杀当财看，发财数亿。","sec":"3. 官杀当财看（杀制不净当财）","t":"calc"},{"q":"「财入别人之墓，盖完就行了」与「财库制印且财库是官」，分别对应什么生意或企业象？","opts":["前者为股份制企业，后者为个体盖房子","两者都是房地产炒作，只是规模大小不同","前者盖房子（非地产），后者股份制企业有国有股","前者为银行金融业，后者为街头个体户"],"ans":2,"exp":"财入别人之墓，盖完就行了（如盖房子而不是房地产）；财库制印得权是企业，财库是官则是股份制企业，有国有股。","sec":"四、财库的冲刑与制财、取财方式","t":"xiang"},{"q":"从官帽子判断企业性质时，符合什么条件一般断为「私企」？","opts":["印戴官帽，且印星合身的","财戴官帽，且用官去官的","官库制印库，且官在月令的","官戴财帽，且没有用官去官的"],"ans":3,"exp":"官戴财帽以财为主；官戴财帽、没有用官去官的是私企。","sec":"四、财库的冲刑与制财、取财方式","t":"diff"},{"q":"同为伤官有功智力取财，坐支「丑土偏印库」暗合主位与「正印外透」的八字，职业分别倾向于？","opts":["偏印库倾向玄学风水师，正印外透倾向正统设计师","偏印库倾向正统公务员，正印外透倾向江湖术士","偏印库倾向建筑包工头，正印外透倾向股民赌徒","两者都只能当老师，不能从事其他行业"],"ans":0,"exp":"丑土有玄学含义又是偏印库，偏印主偏门，主搞玄学（有名风水师）；若正印外透便是正统行业（设计师），皆智力取财。","sec":"五、以智力取财（伤官星带比肩）与其他","t":"xiang"},{"q":"坐支「食神合印」，印星上透「财星」（如丙辛合），这种组合在职业与收入上多主什么？","opts":["伤官见官无制，属于自由职业作家","食为头脑、印为单位、财为工资，普通工薪族","食神生财直冲官库，属于资产过亿的企业家","劫财合财夺印，属于无业游民"],"ans":1,"exp":"坐支食神合印、印上透财：食神为技能或头脑，印为单位，财便是工资，是普通工薪族。","sec":"五、以智力取财（伤官星带比肩）与其他","t":"xiang"},{"q":"原局「内食神不透」与「比劫成党冲财局（如寅申冲）」，分别适合什么求财路子？","opts":["内食神不透适合当律师，比劫成党适合做中医","内食神不透适合风险赌博，比劫成党适合当学校老师","内食神不透适合做企业，比劫成党冲财局适合风险投资（如股票）","两者都只适合拿死工资，不宜经商投资"],"ans":2,"exp":"内食神不透为做企业；比劫成党寅申冲制财局，适合风险投资（如业余做股票赚钱、进证券公司）。","sec":"五、以智力取财（伤官星带比肩）与其他","t":"xiang"},{"q":"在断取财手段时，口诀「穿倒正印（如寅巳相穿）」通常主什么行为倾向？","opts":["恪守礼法，专心考取高学历走仕途","乐善好施，将全部财产捐给寺院","稳重保守，只靠存银行利息度日","不走正路，多以非正统或劫财手段取财"],"ans":3,"exp":"口诀：穿倒正印，为不走正路；若配劫财、辰丑阴暗之象，主以不正当手段取财或当包工头等。","sec":"六、辅助：官财混合的更多实例","t":"rule"}]},{"n":93,"level":"高级","title":"官命、职业与学历的高级断法","qs":[{"q":"按盲派，官杀与印在官命里各主什么？","opts":["官杀主钱财，印主职务","官杀主职务，印主权柄","官杀主权柄，印主职务","官杀主名声，印主学历"],"ans":1,"exp":"看官贵着重看官杀与印：官杀主职务，印主权柄；官杀及印不管作忌神还是用神都必须有根。","sec":"1. 官命的核心与根","t":"rule"},{"q":"主位的印或财做功，什么结构才可能是当官有权？","opts":["印或财在年干，去主位的字","印或财在月令，克日主","印或财在日支，去宾位的字","印或财在时干，合日主"],"ans":2,"exp":"印或财必须在日支（主位），去宾位的字才可能为权力；其他位置多是做生意的。","sec":"1. 官命的核心与根","t":"rule"},{"q":"羊刃合杀，在职业上主什么？","opts":["管财务，银行、国企","管医药，医院、卫生","管文教，学校、媒体","掌兵权，公安、军队"],"ans":3,"exp":"羊刃主枪，合杀即掌兵权，为公安、军队一类。","sec":"2. 官的职业分类（总表）","t":"rule"},{"q":"伤官合杀与劫财羊刃制官，各对应什么机构？","opts":["伤官合杀为检察反贪，劫财羊刃制官为纪检","两者都是检察院、法院","伤官合杀为公安，劫财羊刃制官为军队","伤官合杀为纪检，劫财羊刃制官为检察反贪"],"ans":0,"exp":"伤官合杀＝制贪官的（检察机关）；劫财羊刃制官＝纪检委。","sec":"2. 官的职业分类（总表）","t":"diff"},{"q":"伤官泄羊刃，一般表示从事什么？","opts":["管钱财，经营买卖","主笔主文，耍笔杆子","掌兵权，带枪执法","做技术，医药研发"],"ans":1,"exp":"伤官泄羊刃主笔主文；如政法委处长不带枪，是文官。","sec":"二、公检法与军队","t":"rule"},{"q":"杀的四种状态，按官命论由什么对应什么才对？","opts":["制化为贵气，制尽为名气，虚为当官，制不好当财","制尽为贵气，制化当官，虚为名气，制不好当财","制化为贵气，制尽当官，虚为名气，制不好当财","制化当官，制尽贵气，虚为当财，制不好名气"],"ans":2,"exp":"杀有制化为贵气，杀制尽为当官，杀虚为名气，杀制不好当财看。","sec":"3. 官的位置与大小","t":"step"},{"q":"制用与化用相比，做官的效率如何？","opts":["制用只能做武职，化用才是文职","制用化用效率相同","化用效率高，制用级别不大","制用效率高，化杀生身级别不大"],"ans":3,"exp":"化用不如制用效率高，化杀生身级别不大；以库取权最大。","sec":"3. 官的位置与大小","t":"diff"},{"q":"按盲派，老师与校长的结构区别是什么？","opts":["印拱食伤库为老师，印上戴官帽为校长","食伤生财为老师，财戴官帽为校长","印拱食伤库为校长，印上戴官帽为老师","官杀制伤官为老师，印生官为校长"],"ans":0,"exp":"印有用拱了食神库、伤官库一般做老师；印上戴官帽，则为校长。","sec":"三、文教类：老师的看法","t":"rule"},{"q":"财戴官帽用官去官与不用官去官，分别是什么？","opts":["两者都是私企，只是用印不同","用官去官为国企，不用官去官为私企","用官去官为私企，不用官去官为国企","两者都是国企，只是官职大小不同"],"ans":1,"exp":"财戴官帽用官去官是国企；不用官去官是私企；官戴财帽则以财为主。","sec":"四、国企与私企：官的帽子","t":"diff"},{"q":"按盲派，印星虚透与学历是什么关系？","opts":["印虚透一律有文凭","印虚透与学历无关，只看财","印为用虚透无文凭，为忌虚透有文凭","印为用虚透有文凭，为忌虚透无"],"ans":2,"exp":"印星虚透，用神虚透没文凭；印为忌虚透有文凭，或为忌去印也有文凭。","sec":"五、学历的判断","t":"rule"},{"q":"财星对学习一般是什么作用？除印太重要财克印之外","opts":["最喜，财生官印助学业","无关，学历只看食伤","印弱时才忌，印旺时更不利","最忌，心乱学不进去"],"ans":3,"exp":"财为欲望之星，一般学习最忌；只有印星太重要财克印时，反有学习上进的意思。","sec":"五、学历的判断","t":"rule"}],"fine":[{"q":"盲派判断职业的总方法，主要看哪两个方面？","opts":["只看官杀和印星的十二长生状态","看财和财的原神，看五行类象和十神意向","看日主旺衰和调候用神","只看年柱纳音与神煞驿马"],"ans":1,"exp":"职业判断的总方法：看财和财的原神，看五行类象和十神意向。","sec":"官命、职业与学历的高级断法","t":"rule"},{"q":"官命的核心结构中，官杀及印星不管作忌神还是喜用，都必须满足什么条件？","opts":["都必须合入年柱","都必须虚透天干","都必须有根","都必须逢空亡"],"ans":2,"exp":"官命核心必须有官、杀及印星，且官杀及印星不管作忌神还是用神，都必须有根。","sec":"1. 官命的核心与根","t":"rule"},{"q":"印为用神代表权力，且印戴官帽（如酉印戴己土官帽），行大运把官帽合去或坏印时应何事？","opts":["调任公检法一把手","连升三级","弃官从商发大财","丢官罢职"],"ans":3,"exp":"印为用代表权力时，怕大运来坏印，坏印则丢官罢职；印戴官帽若大运合去官帽子（如甲己合），同样主丢官。","sec":"1. 官命的核心与根","t":"calc"},{"q":"在官的职业分类中，「食神合印（佩印）」与「羊刃踏杀在时上」分别多主什么行业？","opts":["前者为宣传教育等文化业，后者为公检法","前者为公检法，后者为宣传教育行业","前者为银行会计，后者为大学教授","两者都只主私企做生意"],"ans":0,"exp":"食神合印（佩印）主带思想文化性的行业（宣传教育）；羊刃踏杀在时上一般为公检法。","sec":"2. 官的职业分类（总表）","t":"xiang"},{"q":"地支「申金」与火相配主武职，若申带伤官、带羊刃分别多应何职？","opts":["带伤官与带羊刃都只主法院法官","带伤官为检察院、纪委，带羊刃为公安、军队","带伤官为银行行长，带羊刃为学校校长","带伤官为公安、军队，带羊刃为检察院、纪委"],"ans":1,"exp":"申与火相配主武职；申带伤官（或七杀）为检察院、纪委，申带羊刃为公安、军队。","sec":"2. 官的职业分类（总表）","t":"diff"},{"q":"在官的位置与大小比较中，哪一种取权方式级别最大？","opts":["比肩抗杀、伤官见官无制","食神虚透合官、日主坐禄无刑冲","以库取权及制去官与官的原神","单纯的化杀生身、官印相生"],"ans":2,"exp":"化用不如制用效率高，化杀生身级别不大；财库制印库、官库制印库以库取权最大，制去官及官的原神亦为大官。","sec":"3. 官的位置与大小","t":"rule"},{"q":"同为甲木坐申合卯（羊刃），为何「卯木空亡且时上伤官泄羊刃」者不带枪，反为政法委文官？","opts":["申金七杀太弱，无法制住卯木羊刃","甲木无根，只能从事自由商业","时上伤官合走申金，完全脱离政法系统","伤官泄羊刃主笔主文，且羊刃卯木空亡故不带枪"],"ans":3,"exp":"羊刃主枪，七杀合羊刃为公安带枪；但伤官泄羊刃主笔主文（耍笔杆子），加上羊刃卯木空亡，故不带枪而为政法委文官。","sec":"二、公检法与军队","t":"diff"},{"q":"若甲木坐申暗合卯木，且「伤官太重泄羊刃、卯木空亡」，为何反而不进执法部门而做企业？","opts":["伤官太重不愿受约束，且卯木羊刃空亡","申金被伤官彻底克死，毫无管理能力","甲木见火焚身，不能担任领导职务","卯木空亡主无财可发，只能打工"],"ans":0,"exp":"伤官泄羊刃若伤官太重，伤官主自由不愿受约束，加上卯木空亡，故不在执法部门，反成企业负责人。","sec":"二、公检法与军队","t":"diff"},{"q":"八字中「金受火制」常主什么职业，尤其在金水为伤官、七杀、劫财时更明显？","opts":["中医大夫","军人、武职","文职教师","银行会计"],"ans":1,"exp":"金受火制为军人（武职之象），特别是金水为伤官、七杀、劫财时更明显（如巳申合、未穿申制申劫财）。","sec":"名人与高官（文字例）","t":"xiang"},{"q":"刑警队长命局中，以火土成势制「酉金」，为何会有带枪捕犯之象？","opts":["酉为门户车辆，制酉主交通协管","火土相生代表银行金库，主掌管钱财","酉为犯罪分子有捕犯之象，且火有枪象","酉为文书印信，制酉代表文官批文"],"ans":2,"exp":"酉为阴中之阴，可象犯罪分子，制酉有捕抓犯人之象；加上巳火两重，火有枪象，七杀做功主公检法，故为带枪刑警。","sec":"名人与高官（文字例）","t":"xiang"},{"q":"原局「八字无财以官星为父」，父母宫印星自坐绝地，而日支卯禄合月令申官，卯为何象？","opts":["日主的亲生母亲，长寿健康","日主的仇敌小人，一生克害日主","日主的亲姐姐，远嫁海外","先死母后的后母，且与日主关系好"],"ans":3,"exp":"八字无财以官星申为父，印坐绝地主先死母；卯申合，卯为父之第二个老婆（后母），且卯为禄在日支与日元一体，故关系好。","sec":"名人与高官（文字例）","t":"calc"},{"q":"原局火土有势、巳酉合制去月令酉财（戴官帽），行「辰运」为何反局倒霉？","opts":["辰酉合护酉并晦巳火，坏了原局制财之势","辰酉合增强了火土气势，制财太过","辰土冲开戌库，官杀过旺压身","辰为财库，把所有官职都收入库中闭死"],"ans":0,"exp":"原局巳酉合意在制去酉金财官原神，走辰运时辰酉合不仅晦巳火，还保护了酉金，使原局制去之势反了局而倒霉。","sec":"名人与高官（文字例）","t":"calc"},{"q":"天干相合中，像「戊癸远合」这类隔柱相合，在官命做功上主什么含义？","opts":["合而不化，完全无效","管理、控制之义","夫妻离异，各奔东西","破财损官，被人架空"],"ans":1,"exp":"天干合分远近，如戊癸合为控制之义，远合在官命结构中主管理、控制（如管经济、管全局）。","sec":"名人与高官（文字例）","t":"rule"},{"q":"政界高层命造中，若「伤官在门户（时上）」且官杀制化得好，通常主其早期有何职业经历？","opts":["当过船员（伤官在门户主漂泊）","当过厨师（伤官在门户主饮食）","当过律师（伤官在门户主表达，官主法律）","当过矿工（伤官在门户主挖矿）"],"ans":2,"exp":"伤官在门户上主表达能力，官主法律，官杀制化得权且伤官在门户者，常主曾当过律师（如布莱尔造）。","sec":"名人与高官（文字例）","t":"xiang"},{"q":"原局「去印结构」（如木火有势制亥水），逢流年「巳火冲亥印」（如辛巳年）时，官员常应何事？","opts":["与工作毫无关系，只主家里装修","印被冲破，立即免职入狱","辞职下海经商，从此脱离体制","印动主工作变动，从小地方调到大地方升迁"],"ans":3,"exp":"去印得权结构中，印代表工作单位与权力；逢巳火伤官冲亥印之年，印动主工作调动，且常主从小地方调往大地方。","sec":"名人与高官（文字例）","t":"calc"},{"q":"原局「禄到年上」又逢「寅巳相穿」，大运反而在外地升职，这是什么象法？","opts":["年为远方，禄被穿出去代表外放，外地升职得劲","寅巳穿主牢狱之灾，绝不可能外放升官","禄在年上主早年退休，晚年无权","禄到年上主克死祖辈，一生不能离开老家"],"ans":0,"exp":"年为远方，禄到年上且见寅巳穿（原局在本地不舒服），一旦被穿出去（外放），反而在外地十年升职得劲。","sec":"名人与高官（文字例）","t":"xiang"},{"q":"原局「卯辰相穿」，若卯木制辰土太过，为何行「己丑大运」每见土年反而升一级官？","opts":["丑运与辰土相冲，把官库冲破","制土太过需丑土帮忙，使木发挥作用而升官","丑运把卯木彻底合死，不再克土","土年生金克木，把日主制伏"],"ans":1,"exp":"八字卯辰穿制土太过时，反需大运土来帮忙（如己丑运），让木发挥制土做功的作用，故每见土年升一级官。","sec":"带 /穿 /制 的实例（有盘）","t":"calc"},{"q":"文教类职业中，印星有用但拱食伤库「拱到宾位去了」，与「拱在年月上」分别主什么？","opts":["拱到宾位主当大学校长，拱在年月主当小学老师","拱到宾位主终身从教，拱在年月主晚年才从教","拱到宾位主不愿做老师，拱在年月上主早年当老师","两者都只主从事工程建筑，与教育无关"],"ans":2,"exp":"印星有用拱食神库主当老师；拱在年月上主早年当老师；若拱到宾位去了，则表示自己不愿意做老师。","sec":"三、文教类：老师的看法","t":"xiang"},{"q":"女命木火成势、食伤过旺，却自坐「伤官库（戌库）」，为何既当学校教务主任又不离婚？","opts":["因为正官极旺，彻底克住了所有食伤","因为地支水局成势，彻底扑灭了木火","因为食伤全部虚透在年干，对夫宫毫无影响","伤官库为学校，且旺伤入坐下夫宫戌墓故不离"],"ans":3,"exp":"自坐伤官库为学校，故任学校教务主任；伤官虽旺克夫，但全部入夫宫戌墓（戌在主位），故不离婚，只主严管丈夫。","sec":"三、文教类：老师的看法","t":"calc"},{"q":"如「戊子日主配丙辰时」，丙戊一家、子辰会财局，丙火为印且八字无官，这类人常是什么职业？","opts":["银行管财的官（替别人管钱，以印当官）","私企个体老板（自己赚大钱）","公安刑警队长（带枪执法）","自由职业作家（靠稿费谋生）"],"ans":0,"exp":"丙火为印（单位、权力），八字无官以印当官，子辰会财局但子未穿官库，虽管大财却不是自己的钱，是银行管财的官。","sec":"四、国企与私企：官的帽子","t":"xiang"},{"q":"企业高管命局中，若「正官、正印、食神都太正太温和」，与「财库制印、财库带官」相比有何特点？","opts":["资产必然远超制库格，且专做风险投机","虽有资产，但不如制库格厉害，重大决策往往都不管","决策果断狠辣，必定兼任省部级行政高官","绝对无法成为董事长，只能做基层会计"],"ans":1,"exp":"正官正印食神都太正、太温和，虽也可成上市公司董事长（数亿资产），但没有财库制印、官杀库那般厉害，决策都不管。","sec":"四、国企与私企：官的帽子","t":"diff"},{"q":"在判断学历时，若八字为「正格、用官且官身两停」，考上顶尖名校的应期常在什么流年？","opts":["比肩羊刃无制且逢冲之年","印星彻底被财星克破之年","官星禄神到位之年（如用戊官见巳年）","官星被伤官彻底冲散之年"],"ans":2,"exp":"正格用戊土官、官身两停，逢己巳年戊土官星禄神在巳到位，应期到而中高考状元、考入名校。","sec":"五、学历的判断","t":"calc"},{"q":"「标准的从儿格局，纯，病在年柱」，这类学子往往在什么流年考入北大等名校？","opts":["印星突然重重出现反克食伤之年","比劫与官杀混杂交战之年","大运流年合住并生旺病神之年","大运或流年冲去原局唯一病神之年"],"ans":3,"exp":"标准从儿格清纯，唯一病在年柱（如癸丑），逢流年（如辛未年）冲去病神丑土，格局尽清而考入北大。","sec":"五、学历的判断","t":"calc"},{"q":"关于学历反例：有的命官至「地委书记」却文凭不高，有的用神印星虚透（如庚戌）却中专且易被抓，说明什么？","opts":["官贵与学历非绑定，弱格制食伤可贵而文凭不高","当官必然有高学历，地委书记文凭不可能不高","用神印虚透必定考上名牌大学，绝不会只读中专","学历高低完全只看七杀旺衰，与印星虚实毫无关系"],"ans":0,"exp":"制食伤成势可当大官（地委书记），但非印或清纯文格故文凭不高；用申印而庚戌用神虚透只读中专，巳申合坏印则被抓。","sec":"五、学历的判断","t":"diff"},{"q":"民国军阀张宗昌等「从儿格」八字中，「伤官用财」与「伤官生财」的文武趋向有何不同？","opts":["伤官用财主贫困，伤官生财主短寿","伤官用财为武，伤官生财为文","伤官用财与伤官生财皆主从文","伤官用财为文，伤官生财为武"],"ans":1,"exp":"从儿格（如壬午壬寅壬寅壬寅）中，伤官用财为武（军阀武职），伤官生财为文。","sec":"五、学历的判断","t":"diff"}]},{"n":94,"level":"高级","title":"婚姻宫、副宫、配偶星与结婚应期","qs":[{"q":"盲派定义「结婚」，同居关系须满足什么条件才算？","opts":["只要有同居事实就算结婚","同居满一年以上才算结婚","以结婚为目的、同居满半年","领了结婚证并办过婚礼才算"],"ans":2,"exp":"以婚姻为目的、共同生活超半年算结婚；婚前同居很短的不算，但若最终结为夫妻，之前同居也算应期的一部分。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"副宫同柱所配之字就是配偶星，若这个字是印或比劫，婚姻怎么断？","opts":["主配偶有才华，婚姻吉","婚姻平稳，无需另看别处","主早婚，且夫妻感情好","婚姻不好"],"ans":3,"exp":"配偶星有多少算多少；所配若是印、比劫，婚姻不好。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"盲派看婚姻，「宫」与「星」的关系，怎样才算成「婚姻组合」？","opts":["宫星有关联（合生拱同柱入库）才成","宫星必须相冲才能成婚姻组合","只要命中有配偶星就成婚姻组合","宫星必须同在天干才能成组合"],"ans":0,"exp":"宫是位、星是人；宫星无关联则只是虚的对象。","sec":"一、结婚的定义与看婚姻的三个件","t":"diff"},{"q":"婚姻的虚实长短，天干与地支、原局与大运各怎么看？","opts":["天干虚为长，地支实为短，运婚过运仍在","天干虚为短或桃花，地支实为长，运婚过运无","天干地支皆为长，运婚过运仍在","天干实为长，地支虚为短，运婚过运仍在"],"ans":1,"exp":"天干虚、主短或桃花运；地支实、主长；因大运而成的婚姻，过运则无。","sec":"一、结婚的定义与看婚姻的三个件","t":"diff"},{"q":"夫星与夫宫在原局本已相合住，要引动它成为结婚应期，用什么方式？","opts":["再用一个合去加固","用克去伤它","用冲去引动","用刑去拆开"],"ans":2,"exp":"合动是应期的第一法；原局已合住的，须用冲来引动。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"原局有刑克、隔住婚姻的字，应期怎么应？为何伤官运也可能结婚？","opts":["伤官运不能结婚，只能等官运来","有阻碍字就一生都不能结婚","阻碍字强旺的流年才能够结婚","坏掉阻碍字为应期，伤官运也可结"],"ans":3,"exp":"坏阻碍应：阻碍字被坏掉即为应期，所以伤官运也可因去阻碍而结。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"大运带来不利婚姻的信息（如刑坏夫宫之运），结婚应期怎么取？","opts":["过运后第一个合适的流年完婚","仍在该大运的合适流年结婚","要等到下一个十年大运的中间","该运内即使不合适也会勉强结"],"ans":0,"exp":"不利婚姻的大运要过运后第一个合适流年才完婚，运中不再讲流年。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"按应期干支对应表，流年出现天干「庚」，等于动了八字中的哪个地支？","opts":["酉","申","戌","亥"],"ans":1,"exp":"对应表：庚对应申；酉对应辛。","sec":"二、结婚应期的五条规则","t":"calc"},{"q":"流年逢寅、卯，通过合局、墓气到位，可以引动八字中的哪个库？","opts":["丑","辰","未","戌"],"ans":2,"exp":"申酉引丑，亥子引辰，寅卯引未，巳午引戌，金引丑、水引辰、木引未、火引戌。","sec":"二、结婚应期的五条规则","t":"calc"},{"q":"女命伤官本伤夫，却有哪两种情形，伤官运或伤官年反而应结婚？","opts":["印星多而重；印星入他星之墓中","官杀不透干；官杀入日支之库中","比劫多而重；财星入他星之墓中","官杀多而混杂；官杀入他星之墓"],"ans":3,"exp":"官杀多、混杂，或官杀入墓于他星，均可应伤官，但婚姻多不太好。","sec":"三、基本应期命例","t":"rule"},{"q":"同一颗夫星既能被流年冲动、又能被合动时，取哪一种引法？","opts":["看引动后是生助还是反伤，取生助","取与日主相合的那一种引法来用","一律取冲，因为冲的力量更大","一律取合，因为合更像是婚姻象"],"ans":0,"exp":"如丙寅年寅冲申却生旺伤官反克官，不取；取巳申合动。看引动后是生助还是反伤。","sec":"三、基本应期命例","t":"diff"}],"fine":[{"q":"婚前有过同居经历但时间很短，什么情况下这段同居仍算作结婚应期的一部分？","opts":["同居期间双方已有共同财产","同居满三个月且双方父母知情","同居虽短但最终两人结为夫妻","同居发生在夫妻星透干的流年"],"ans":2,"exp":"婚前同居很短本不算婚姻，但若最终结为夫妻，之前的同居也算作结婚应期的一部分。","sec":"一、结婚的定义与看婚姻的三个件","t":"diff"},{"q":"具体取用副宫与配偶星时，正确的先后观察步骤是什么？","opts":["先看比劫，再看比劫所生的食伤","先看时干，再看时支所藏的十神","先看配偶星，再看年支所合之字","先看副宫，再看副宫同柱所配的字"],"ans":3,"exp":"看婚姻先看宫再看星；取副宫与配偶星时，先看副宫，再看副宫同柱所配的字，此字即为配偶星。","sec":"一、结婚的定义与看婚姻的三个件","t":"step"},{"q":"在盲派婚姻断法中，「副宫」具体是指八字中的哪个位置？","opts":["日支所透之干，即日主同柱另一半位置","时干所坐的印星或比劫","月支所藏的本气十神","年支与日支相合的地支"],"ans":0,"exp":"婚姻宫为日支，副宫则是日支所透之干（如日支藏干透出者），代表日主同柱的另一半位置。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"若命中有不止一段婚姻或感情，一般如何从四柱排列判断其出现的先后顺序？","opts":["以时柱为早、月柱为晚，由近及远","以年柱为早、时柱为晚，依次排列","以阳干为早、阴干为晚，按阴阳分","以日柱为早、年柱为晚，逆向排列"],"ans":1,"exp":"婚姻先后一般以年柱为早、时柱为晚，从年到时依次排列。","sec":"一、结婚的定义与看婚姻的三个件","t":"rule"},{"q":"原局配偶星较多时，按结婚应期五法中的「伤克应」，结婚应期常落在何时？","opts":["印星透干合住日主的时间","比劫生助食伤、官杀极旺的时间","伤克配偶星、多者去其一的时间","原局配偶星同时全部透出的时间"],"ans":2,"exp":"伤克应指原局配偶星多的，可以伤克配偶星的时间为应期，即多者去其一而应。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"应期五法中的「宫星联体」，是指太岁使配偶星与婚姻宫形成什么状态？","opts":["宫星相隔且各自逢空","宫星相冲且同时入墓","宫星皆伏吟于年柱之上","宫坐于星上或星坐于宫上"],"ans":3,"exp":"配偶星、宫因太岁而「宫坐于星上」或「星坐于宫上」，把宫星联在一起，即为结婚应期。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"应期第一法「合动」中，除了将夫妻星与夫妻宫相合，还有哪种五合方式也可作应期？","opts":["夫妻星与日主五合","比劫与七杀五合","年干与时干五合","印星与食神五合"],"ans":0,"exp":"合动一般以三合、六合、天干五合将夫妻星与夫妻宫相合，也有夫妻星与同主（日主）五合为应期。","sec":"二、结婚应期的五条规则","t":"rule"},{"q":"按应期干支对应表，流年出现天干「丙」时，等于引动了八字中的哪些地支？","opts":["卯、未","寅、巳","巳、戌","午、戌"],"ans":1,"exp":"干支对应表中，丙对应寅、巳；丁对应午、戌、未；戊对应巳、戌、辰。","sec":"应期的干支对应（天干引动之地支）","t":"calc"},{"q":"按应期干支对应表，流年出现天干「乙」时，等于引动了八字中的哪些地支？","opts":["寅、卯、未","卯、巳、丑","卯、未、辰","亥、寅、卯"],"ans":2,"exp":"干支对应表中，甲对应亥、寅；乙对应卯、未、辰。","sec":"应期的干支对应（天干引动之地支）","t":"calc"},{"q":"按应期干支对应表，流年出现天干「辛」时，等于引动了八字中的哪些地支？","opts":["申、酉","申、丑","酉、戌","酉、丑"],"ans":3,"exp":"干支对应表中，庚只对应申，辛对应酉、丑。","sec":"应期的干支对应（天干引动之地支）","t":"calc"},{"q":"按应期干支对应表，流年出现天干「癸」时，等于引动了八字中的哪些地支？","opts":["子、辰、丑","亥、申、子","亥、子、辰","子、申、丑"],"ans":0,"exp":"干支对应表中，壬对应亥、申；癸对应子、辰、丑。","sec":"应期的干支对应（天干引动之地支）","t":"calc"},{"q":"利用天干对应地支表断应期时，哪种流年干支组合的引动最为有力？","opts":["仅天干虚透而地支不与原局发生关系","干动星、支动宫（或相反）同时到位","仅地支暗冲而天干被日主合走","流年干支与年柱完全天克地冲"],"ans":1,"exp":"天干与地支同时到位（干动星、支动宫，或干动宫、支动星）时，应期最为有力。","sec":"应期的干支对应（天干引动之地支）","t":"rule"},{"q":"依据地支引动与墓库口诀，八字中的「戌」库可以代表哪一组地支？","opts":["亥、子","申、酉","巳、午","寅、卯"],"ans":2,"exp":"金引丑、水引辰、木引未、火引戌，库可代其所收之气，故戌可代表巳、午。","sec":"地支引动与墓库","t":"calc"},{"q":"依据地支引动与墓库规律，流年逢「亥、子」水，可以引动原局中的哪个墓库？","opts":["未","戌","丑","辰"],"ans":3,"exp":"申酉引丑，亥子引辰，寅卯引未，巳午引戌，故亥子可引动辰库。","sec":"地支引动与墓库","t":"calc"},{"q":"女命日支为未、官星为寅入夫宫之墓，原局另见虚透之丁火桃花，丁火通常应作何看？","opts":["婚前男友，不当丈夫看","代表丈夫的父母长辈","主晚年才出现的夫星","必为二婚所嫁的正夫"],"ans":0,"exp":"天干虚者主短或主桃花运，原局虚透之桃花星多作婚前男友看，不当丈夫看。","sec":"三、基本应期命例","t":"xiang"},{"q":"女命夫星坐于夫宫、却被他支含劫财来合且夫星入墓，婚期如何引动及婚后象如何？","opts":["必在入墓之年成婚，且配偶寿命极长","当冲出引动成婚，但婚后易因合到别人而离","当再合加固成婚，婚后夫妻感情稳固持久","终身无法引动成婚，只能保持同居关系"],"ans":1,"exp":"墓中之星要冲出才为应期，夫星被他合也当冲应；但夫星被含劫财之支合走，主婚后易离。","sec":"三、基本应期命例","t":"diff"},{"q":"男命妻宫与丑暗合，丑带劫财且库中枭、财、食俱全，为何该女只是长期情人而非妻子？","opts":["丑为湿土晦火，说明命主本人不愿成婚","财星入墓不透，说明对方经济条件太差","劫财主她另有男人，库全主她有家人孩子","暗合力量太弱，双方只是一面之缘"],"ans":2,"exp":"丑带劫财说明她有男人；丑为库为家，枭（母）、财（情人）、食（孩子）俱全，说明她有家人有孩子。","sec":"三、基本应期命例","t":"xiang"},{"q":"女命原局夫星入墓于他星或官杀多而混杂，即便在伤官运或伤官年成婚，婚姻质量通常如何？","opts":["主夫妻白头偕老、儿孙满堂","婚姻反而比正官运更稳固","只主晚婚，婚后没有任何波折","婚姻都不太好"],"ans":3,"exp":"女命官杀多混杂或官杀入他星之墓虽可应伤官运或伤官年结婚，但婚姻都不太好。","sec":"女命伤官应结婚的两种情形","t":"rule"},{"q":"女命原局无财、夫星夫宫皆入墓且大运不见冲墓之运，通常应如何寻找结婚应期？","opts":["找伤官大运与伤官流年","找正印大运与偏印流年","找官星伏吟的建禄流年","找比肩大运与比肩流年"],"ans":0,"exp":"原局夫星夫宫入墓难婚，应冲墓；运中不见冲墓之运时，就找伤官运之伤官流年。","sec":"女命伤官应结婚的两种情形","t":"rule"},{"q":"女命若夫妻宫恰好是夫星的死绝之地，通常要发生什么变化才能结婚？","opts":["夫妻宫逢合不冲才结婚","坏掉夫妻宫才结婚","生旺夫妻宫才结婚","夫妻宫伏吟两次才结婚"],"ans":1,"exp":"夫妻宫若是夫星死绝之地，须坏掉夫妻宫（如穿倒夫宫）才能结婚。","sec":"四、其他应期实例要点","t":"rule"},{"q":"女命月上官星坐亥在宾位，日时另见真正夫星，月上官星通常代表什么？","opts":["命主父亲的兄弟姐妹","必定白头偕老的发妻之位","婚前男友，或是别人的丈夫","命主婚后所生的长子"],"ans":2,"exp":"在宾位且早现的官星多为婚前男友，且在宾位坐他支，往往是别人的丈夫。","sec":"四、其他应期实例要点","t":"xiang"},{"q":"女命大运刑日支夫宫，却依然能在此运结婚，常见的一种命理原因是什么？","opts":["原局印星极旺把夫宫刑坏成了好事","只要大运走财星就绝对不怕刑夫宫","流年天干透出比劫帮日主扛住刑伤","局中另有支亦为夫宫并包住夫星且未被坏"],"ans":3,"exp":"如戌运虽刑未（夫宫），但局中卯亦为夫宫且包住夫星，戌坏未而不能坏卯，故仍能成婚。","sec":"四、其他应期实例要点","t":"diff"}]},{"n":95,"level":"高级","title":"恋爱同居、破身与淫乱卖身命","qs":[{"q":"按盲派，女命以什么为身体？破身的时间怎么定？","opts":["以夫星为身体，夫星入库才破身","以印为身体，印被合之时即破身","以食伤为身体，食伤一现就破身","以禄为身体，禄被破时破身"],"ans":3,"exp":"女命以禄为身体，禄被破的时间就是破身的时间。","sec":"2. 女命：禄为身体，破禄即破身","t":"rule"},{"q":"女命破禄的两种方式是什么？","opts":["食伤间泄气式冲破，或官杀冲禄","比劫夺财，或印被财克","官杀合禄，或食伤合印","伏吟禄神，或禄神入墓库"],"ans":0,"exp":"破禄有两种：泄气式的破（子破卯、卯破午之类），以及官杀冲禄。","sec":"2. 女命：禄为身体，破禄即破身","t":"diff"},{"q":"早恋的基本信号，女命与男命各看什么？","opts":["女命印旺，男命官杀重","女命见禄无印，男命比劫重","男女都看食伤旺","女命比劫重，男命见禄无印"],"ans":1,"exp":"女命见禄无印易破身；男命比劫重易早恋；财（男）或官杀（女）在年月也主早恋。","sec":"1. 总纲","t":"diff"},{"q":"天干虚透的婚前对象，若坐在比劫地支上，最终怎样？","opts":["会成为合作伙伴","会成为同居对象但不分手","会成为别人的老公（老婆）","会成为自己的配偶"],"ans":2,"exp":"天干虚透的对象多为婚前对象；其坐比劫地支，最终是别人的人。","sec":"1. 总纲","t":"rule"},{"q":"婚前对象要发展到同居，需要什么条件？","opts":["这个对象在年柱","这个对象坐在日主之禄上","这个对象与印星相合","这个对象与夫妻宫有关联"],"ans":3,"exp":"这类对象与夫妻宫有关联，才会发展到同居。","sec":"1. 总纲","t":"rule"},{"q":"女命的日柱（或其他柱）干支一气，如丁未，表示什么？","opts":["没有过别人，纯洁","桃花旺盛","身体不好","多次婚姻"],"ans":0,"exp":"干支一气表示没有过别人；两个字联成一体（如两个巳合申）则婚前多个同居对象。","sec":"3. 其他提示","t":"rule"},{"q":"女命巳（禄）遇申，成巳申合，按盲派怎么论？","opts":["巳为食申为伤，食伤相合","巳为身体申为财，以身换财","巳为官申为印，官印相生","巳为财申为身体，以财养身"],"ans":1,"exp":"禄神遇合易失身；巳为禄身体、申为财，合则以身换财。","sec":"2. 女命：禄为身体，破禄即破身","t":"calc"},{"q":"女命官杀入墓、墓不开，表示什么？","opts":["男人少而专一，婚姻很稳定","丈夫早亡，终身无夫无婚","男人多，来的都是别人的","丈夫有钱，主夫荣妻又贵"],"ans":2,"exp":"夫宫（官杀）入墓不开：男人多，而且来的都是别人的男人。","sec":"1. 总则","t":"rule"},{"q":"淫乱命中，丑落在时上是什么象？","opts":["财库，积蓄钱财所在之处","门户，主出外远行之事","阳中之阳，男性象征，公开之事","阴中之阴，女性器官，偷偷之事"],"ans":3,"exp":"阴中之阴（丑）落时上表示女性器官、偷偷干的事；被刑冲穿就开始做功。","sec":"1. 总则","t":"xiang"},{"q":"女命禄或禄加伤食逢冲穿，并用来取财，按盲派是什么象？","opts":["以身体取财，卖淫之意","以经营取财，生意人之象","以权力取财，当官之象","以才艺取财，艺人之象"],"ans":0,"exp":"禄神，或禄加伤食神，逢冲穿有性爱之意，以此做功取财，就是卖淫之意。","sec":"1. 总则","t":"rule"},{"q":"同是禄伤相连的女命，歌唱家与卖身命的分野是什么？","opts":["是否有印星来制伤官","夫宫是否单一稳定","禄神是否坐在日支","伤官是否透出天干"],"ans":1,"exp":"夫宫只有一个且夫星夫宫相拱稳定的，是歌唱家；夫宫多现的，是卖身命。","sec":"2. 女命卖身命例","t":"diff"}],"fine":[{"q":"男命财星或女命官杀在年、月柱，为何多主早恋对象或同学？","opts":["年柱主晚婚，月令代表父母","年柱主远方，月令代表长辈","年柱主夫妻宫，月令代表子女","年柱主早，月令代表同学"],"ans":3,"exp":"财（男）或官杀（女）在年、月主早恋，因年主早、月令为同学，故年月对象多是早恋对象或同学。","sec":"1. 总纲","t":"xiang"},{"q":"女命原局「财旺」在早恋与同居判断中提示什么信息？","opts":["开心早，多为早恋同居命","心性保守，必为晚婚独身命","克夫极重，婚前绝不谈恋爱","财多身弱，只谈精神恋爱"],"ans":0,"exp":"女命财旺则开心早（开窍早），主早恋、同居命。","sec":"1. 总纲","t":"rule"},{"q":"女命看破身时，除了本命禄神外，哪几个地支也可直接当「身体」看？","opts":["申、酉，以及为印的戌","巳、午，以及为禄的亥","寅、卯，以及为墓的未","子、丑，以及为库的辰"],"ans":1,"exp":"女命以禄为身体，巳、午都可当「身体」看，亥为禄也同。","sec":"2. 女命：禄为身体，破禄即破身","t":"rule"},{"q":"女命「禄神遇合」（非单纯破禄）在男女关系上提示什么？","opts":["必主正官合身，早年明媒正娶","必定守身如玉，婚前绝无亲密","容易失身，合财则以身换财","只主事业升迁，与男女关系无关"],"ans":2,"exp":"女命禄神遇合易失身，如巳申合：巳为禄身体，申为财，合则以身换财。","sec":"2. 女命：禄为身体，破禄即破身","t":"rule"},{"q":"女命两个相同的字联成一体去合官星（如两巳合申，两禄合一官），主什么象？","opts":["婚后夫妻恩爱、从一而终","终身无异性缘、孤独终老","只谈一次恋爱便直接结婚","婚前有多个同居对象"],"ans":3,"exp":"两个字联成一体（如两禄合一官），主合多了，婚前有多个同居对象。","sec":"3. 其他提示","t":"rule"},{"q":"女命外貌与身材类象中，「土金泄秀」与「乙坐亥」分别主什么特征？","opts":["土金泄秀主漂亮，乙坐亥主苗条","土金泄秀主矮胖，乙坐亥主粗壮","土金泄秀主平凡，乙坐亥主年长","土金泄秀主黑瘦，乙坐亥主丰腴"],"ans":0,"exp":"土金泄秀主漂亮，乙坐亥主苗条；此外财带官杀生到夫宫也主长得漂亮。","sec":"3. 其他提示","t":"xiang"},{"q":"女命原局见巳、午，或原局有合而被合者，在性情与异性缘上各有什么特点？","opts":["巳午主性冷淡，有合被合主孤僻寡言","巳午主性开放，有合被合对异性有吸引力","巳午主晚婚迟，有合被合主远离异性","巳午主守旧派，有合被合主克夫害子"],"ans":1,"exp":"巳午俱为桃花，主性开放；原局有合而被合者，对异性有吸引力。","sec":"3. 其他提示","t":"xiang"},{"q":"女命「食伤太重克夫」，除了主婚姻不好之外，还直接主什么？","opts":["夫荣妻贵","富贵清闲","无福操劳","多子多福"],"ans":2,"exp":"命局食伤太重克夫，主婚姻不好、无福操劳。","sec":"3. 其他提示","t":"rule"},{"q":"男命妻宫是比劫库，且财星落在宾位被比劫冲、比劫旺，主什么感情特征？","opts":["用情专一、婚后绝对忠诚","惧内怕妻、不敢接触异性","清心寡欲、晚年出家修行","好色、玩女人、性关系乱"],"ans":3,"exp":"财落宾位被比劫冲、比劫旺且妻宫为比劫库，主好色、玩女人、性关系乱。","sec":"二、男命早恋、同居命例","t":"xiang"},{"q":"男命年月有劫财、时上财带官星合到坐下，在婚恋与家境上常有什么表现？","opts":["早年家贫晚婚，女方家反对而奉子成婚","中年丧妻再娶，婚后无子无女孤老","女方家境贫寒，男方家极力促成早婚","早年富贵早婚，父母包办而明媒正娶"],"ans":0,"exp":"年月劫财主晚婚、家贫、女方家反对；时上财带官星合到坐下，主奉子成婚、生米煮成熟饭。","sec":"二、男命早恋、同居命例","t":"xiang"},{"q":"女命夫星在日支夫宫，却同时出现他支与夫宫「一合、一冲」（如寅亥合、巳亥冲），主何？","opts":["旺夫益子组合","离婚组合","晚婚大吉组合","白头偕老组合"],"ans":1,"exp":"夫宫之夫星既被合走又被冲坏（如寅亥合、巳亥冲），为典型离婚组合。","sec":"三、女命同居、破身命例","t":"rule"},{"q":"女命以巳火为身体，行戌运时「巳入戌墓」，在同居断法中代表什么象？","opts":["丈夫早亡自己守寡终身","自己出家独居远离男人","自己与男人同处一处","与父母同住从未谈恋爱"],"ans":2,"exp":"巳为女命身体，戌为男方库或夫墓，行戌运巳入戌墓，主自己与男人同处一处（同居）。","sec":"三、女命同居、破身命例","t":"xiang"},{"q":"女命乙丑日主「占了男人的库」，若局中见「寅丑暗合」且子为枭神，分别主什么角色？","opts":["寅丑暗合为正妻，子为枭神为媒人","寅丑暗合为早婚，子为枭神为贵人","寅丑暗合为离异，子为枭神为长女","寅丑暗合当小三，子为枭神为偏房"],"ans":3,"exp":"乙丑占男人库主男人来光顾；寅丑暗合主当小三，子为枭神主偏房。","sec":"三、女命同居、破身命例","t":"xiang"},{"q":"女命比占夫宫、伤官旺且婚姻对象反复难成（如戌中带财），通常给什么婚恋建议与断语？","opts":["嫁老头要稳些，或会被别人包养","宜找比自己小十岁的丈夫最稳妥","宜嫁同龄初恋，婚后必能白头到老","宜早婚早育，越早结婚婚姻越稳固"],"ans":0,"exp":"女命伤官婚难成，嫁老头要稳些；戌中带财且比占夫宫，主会被别人包养。","sec":"三、女命同居、破身命例","t":"diff"},{"q":"在淫乱命与卖身命总则中，命局的「辰、丑、未」作为财官杀墓库时，统称为什么？","opts":["女人库","男人库","父母库","子女库"],"ans":1,"exp":"财官杀的墓库（辰、丑、未）在女命淫乱卖身命总则中称为「男人库」。","sec":"1. 总则","t":"rule"},{"q":"女命「官星带财入到自己坐下」，在淫乱卖身命总则中是什么象意？","opts":["丈夫赚大钱全部交给妻子管","自己花钱养活无业的丈夫","男人带钱找她上床","父母出嫁妆资助女儿成婚"],"ans":2,"exp":"官星带财入到自己坐下，读象为男人带钱找她上床。","sec":"1. 总则","t":"xiang"},{"q":"女命「夫宫多现，满局皆夫宫」，在卖身命总则中形象地代表什么？","opts":["一辈子只嫁一个男人","到处是她的房产","丈夫家族人丁兴旺","到处是她的床"],"ans":3,"exp":"夫宫多现、满局皆夫宫，表示没有专一归宿，到处是她的床。","sec":"1. 总则","t":"xiang"},{"q":"女命「食伤连体、两个相同字相连（如两辛、两甲相连）主身体」，若时上见财合之，主什么？","opts":["以身体取财","以官职俸禄取财","以祖业继承取财","以文才取财"],"ans":0,"exp":"食伤连体、两个相同字相连主身体；时上见财合之，主以身体取财。","sec":"1. 总则","t":"xiang"},{"q":"女命局中出现「穿倒正印」与「夫宫被穿」，在婚姻道路上主什么？","opts":["走正途功名，嫁入名门望族","不走正路，没有正经婚姻","虽有波折，但必有明媒正娶","只主学业不佳，不影响婚姻"],"ans":1,"exp":"穿倒印（正印）、夫宫被穿，主不走正路，没有正经婚姻。","sec":"1. 总则","t":"rule"},{"q":"女命「禄在门户」且「门户被穿」，在男女关系与男方心态上分别主什么？","opts":["禄在门户主远嫁，门户被穿夫妻恩爱长久","禄在门户主富贵，门户被穿男人甘愿入赘","禄在门户易出轨，门户被穿男人只图占有","禄在门户主守节，门户被穿男人真心爱护"],"ans":2,"exp":"女命禄在门户容易出轨；门户被穿，说明男人不是爱她而是占有她。","sec":"2. 女命卖身命例","t":"xiang"},{"q":"男命做「鸭」（卖身男命）的典型命局做功与组合特征是什么？","opts":["妻宫坐七杀配羊刃，比劫无力，只靠俸禄","妻宫坐正印配正财，官印相生，三合局取财","妻宫坐食神配正官，干支一气，静而不动","妻宫坐劫库配虚财，再见劫财，丑午穿取财"],"ans":3,"exp":"妻宫坐劫财库再见劫财主性能力强，妻宫多现配虚财女人来往，丑午穿（劫财做功）女人带财来，主做「鸭」。","sec":"3. 男命卖身与传媒类","t":"xiang"},{"q":"女命满局比劫、卯穿辰官墓发生性关系，为何还会发展成「拍影片出售（卖片子）」？","opts":["见丙火为影像，且亥入辰顶丙主传媒摄影","见辛金为珠玉，且酉戌相穿主珠宝首饰","见壬水为江河，且子午相冲主远洋贸易","见戊土为高山，且寅巳相穿主土木工程"],"ans":0,"exp":"卯身体穿辰男人发生性关系，见丙火为影像、亥入辰顶丙表示传媒摄影，故变成影片出售。","sec":"3. 男命卖身与传媒类","t":"xiang"}]},{"n":96,"level":"高级","title":"男命多婚组合","qs":[{"q":"男命多婚，婚姻顺次按柱怎么排？","opts":["年柱为早，时柱为晚，依次排第","时柱为早，年柱为晚，依次排第","月柱为头婚，其余不分先后","日柱为头婚，年时柱依次再婚"],"ans":0,"exp":"婚姻顺次：年柱为早，时柱为晚，依次排第。","sec":"一、多婚的顺次与总原则","t":"step"},{"q":"盲派看婚姻，天干与地支的配偶，长短如何分？","opts":["天干地支不分长短，只看宫位","天干虚者为短或主桃花；地支实者为长","天干实者为长；地支虚者为短或主桃花","天干虚者为长；地支实者为短"],"ans":1,"exp":"天干虚者为短，或主桃花运；地支实者为长。大运因而成的婚姻，过运则无。","sec":"一、多婚的顺次与总原则","t":"diff"},{"q":"盲派看男命婚姻，配偶星怎么认定？","opts":["先看月令，月令所藏的财即配偶星，只算一个","先看日干，日干所合之字即配偶星，只算一个","先看副宫，副宫同柱所配之字即配偶星，有多少算多少","先看时柱，时柱的财即配偶星，按早晚论"],"ans":2,"exp":"先看副宫，再看副宫同柱所配之字，这个字就是配偶星，有多少算多少；若为印、比劫，则婚姻不好。","sec":"一、多婚的顺次与总原则","t":"rule"},{"q":"男命妻宫不多现，但妻宫被合坏或刑坏，按盲派怎么论？","opts":["必有婚外情","晚婚但白头到老","一定无婚姻","一婚不到头"],"ans":3,"exp":"五种多婚组合之二：妻宫虽不多现，但妻宫被坏（合坏、刑坏、穿坏），一婚不到头。","sec":"男命多婚的五种组合","t":"calc"},{"q":"妻宫被坏，与妻宫没坏而妻星被坏又出现新妻星，两种情形哪句对？","opts":["前者一婚不到头；后者因新妻星出现容易多婚","前者容易多婚；后者一婚不到头","两者都只主一婚，但有桃花","两者都主不婚"],"ans":0,"exp":"妻宫被坏（组合2）是一婚不到头；妻宫没坏而妻星被坏，加上新的妻星出现（组合3）则容易多婚。","sec":"男命多婚的五种组合","t":"diff"},{"q":"「妻星多合」，按盲派口诀如何论婚？","opts":["合一次加一个，合多了也只算一婚","合一次加一个，或因合而离开","合一次减一个，多合则无妻","合与婚无关，只看冲刑"],"ans":1,"exp":"男命多婚组合之四：妻星多合，合一次加一个；或因合而离开。","sec":"男命多婚的五种组合","t":"rule"},{"q":"口诀「宫星双合，两次婚姻」是指什么情形？","opts":["一星两宫，两次都合到位，所以白头到老","一星一宫，第一次合到位，第二次又被合走","一星两宫或一宫两星，第一次合没到位，第二次才到位","一宫两星，第一次到位，第二次冲开"],"ans":2,"exp":"一个妻星对应两个妻宫（或反之），第一次合没到位，第二次合才到位，命该两次婚姻。","sec":"两条断离、断再娶的辅助诀","t":"rule"},{"q":"盘中没有透出丙丁劫财、羊刃、比肩，只有两个禄，按盲派怎么论？","opts":["两个禄主劫财夺妻，主离婚","两个禄主妻宫被冲，主婚姻不稳","两个禄各当一妻，主多婚","两个禄只表示自己，不表示离婚"],"ans":3,"exp":"没有透出丙丁劫财羊刃比肩，则两个禄只表示自己；凡劫财、羊刃透干对婚不好。","sec":"两条断离、断再娶的辅助诀","t":"diff"},{"q":"土作妻星且满盘财星，逢刑冲，按盲派怎么论婚？","opts":["反主一妻","主多桃花，婚外情多","刑冲越多，妻越多","必离婚，不再娶"],"ans":0,"exp":"凡土作妻星之命，逢刑冲反主一妻；夫妻宫不能刑坏，土互相牵制。不刑冲的土财星才有可能表示桃花。","sec":"三、反例：满盘财星逢刑冲，反主一妻","t":"diff"}],"fine":[{"q":"男命多婚的第一种组合是「妻宫多现又配妻星」，还须满足什么条件才容易多婚？","opts":["妻宫本身不稳","食伤入墓于年支","妻星透出在年干","印星旺相生助日主"],"ans":0,"exp":"男命多婚组合之一：妻宫多现又配妻星，形成婚姻组合，而妻宫本身不稳，则容易多婚。","sec":"男命多婚的五种组合","t":"rule"},{"q":"男命「妻星落在比劫上、被比肩争，或被羊刃、劫财透干包制」，主要应什么后果？","opts":["妻贤子孝，富贵双全","克妻，多结多离","娶得贤内助，助夫发财","只谈恋爱不结婚"],"ans":1,"exp":"男命多婚组合之五：妻星落比劫、被比肩争，或被羊刃劫财透干包制，主克妻、多结多离。","sec":"男命多婚的五种组合","t":"rule"},{"q":"两造八字仅差一字（如一造双巳妻宫，另一造年支为卯），为何后者「差一个字，一次婚姻」？","opts":["卯木合住日主，把所有桃花都化解","年支卯木逢空亡，主一婚到老","妻宫单一，且天干财不坐副宫非正妻","卯木把妻星生旺，所以不再离婚"],"ans":2,"exp":"年支换卯后不再是双妻宫，癸财不坐副宫不是妻子（只主沾花惹草），仅一次婚姻。","sec":"两条断离、断再娶的辅助诀","t":"diff"},{"q":"在「双拱、双宫双星」的两次婚姻结构中，若第一次未拱到月令、未拱到位，意味着什么？","opts":["第二次婚绝对无法成功","第一次婚必定白头到老","命主终身只能有同居关系","第一次婚不成立或不牢"],"ans":3,"exp":"双宫双星命该两次婚姻，第一次未拱到月令、未拱到位，则第一次婚不成立或不牢，第二次才合到位。","sec":"两条断离、断再娶的辅助诀","t":"rule"},{"q":"同样是「午午戌」地支连体，为何透出丙丁劫财羊刃时，对男命婚姻特别不利？","opts":["午午戌连体都代表透干的劫刃","午火自刑导致夫妻宫必坏","丙丁火透干会直接冲破日支","午午戌三合火局把财星烧绝"],"ans":0,"exp":"凡劫财、羊刃透干对婚不好，午午戌这类连体都表示透出的丙丁劫刃，共同克夺妻财。","sec":"两条断离、断再娶的辅助诀","t":"diff"},{"q":"男命副宫下配多个配偶星，为何有的断「离婚再娶」而不是「家里红旗不倒、外养二奶三奶」？","opts":["日主太弱担不起满盘财星","妻宫被刑冲克坏，妻待不住","妻星全部透在年干和月干","命局没有食伤来生助财星"],"ans":1,"exp":"妻星多且与命主有关联，若夫妻宫被刑冲克坏，妻在宫中待不住，便主离婚再娶而非包养二奶。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"男命数妻时，为何同一个地支妻星（如巳或寅）有时会被计作「两个老婆」？","opts":["地支伏吟在流年出现一次就多算一个","每个地支天生固定代表两个以上配偶","合与冲或配副宫各算一次，多作用多算","只要地支藏干有两个就必定算作两个"],"ans":2,"exp":"同一字若既合妻宫又与副宫自合（或既配副宫又冲妻宫），每多作用一次就多算一个。","sec":"1. 宫多现、星多用","t":"calc"},{"q":"男命妻星上面带有官杀（子女），且夫妻宫被刑冲克坏而多婚，子女方面常见什么象？","opts":["终身不育子女，妻子也不曾带过孩子","子女虽归男方抚养，但极度克伤父亲","每次结婚必生双胞胎且全归男方抚养","每次成婚带孩子进，离时妻带孩子走"],"ans":3,"exp":"官杀为子女，妻星上带官杀，主每次成婚都带孩子进来；离婚时官杀带着老婆跑，自己一个孩子也落不着。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"男命以时上的「伤官」作为第二任妻子，这位再婚妻子在年龄或性格上常有什么特征？","opts":["年龄小很多，或新潮重享受","长年体弱多病，生活无法自理","出身豪门世家，性格严厉且克夫","年龄比命主大十岁以上，性格极守旧"],"ans":0,"exp":"伤官落时上主小，如娶自己的学生；或主新潮、享受吃喝玩乐型。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"男命原局财星过弱受火克（或无明财），通常可以取柱中哪个十神替代当妻子看？","opts":["正印偏印（如卯中乙木偏印）","伤官食神（如巳中戊土伤官）","比肩劫财（如午中丁火劫财）","正官七杀（如申中庚金七杀）"],"ans":1,"exp":"财星过弱受火克时，可以食伤（如巳中戊土伤官、午中己土）当妻看。","sec":"1. 宫多现、星多用","t":"rule"},{"q":"男命原局日柱与月柱干支相同（伏吟，如双丁巳）且入他宫比劫，主什么婚姻之象？","opts":["主夫妻分居两地但永不离","伏吟是相守，主白头偕老","伏吟是走了，主离婚之象","主妻子双胞胎，姐妹同嫁"],"ans":2,"exp":"丁巳伏吟，伏吟是走了，又入他宫比劫，为离婚之象。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"男命妻星食神或财星与含有「劫财」的地支相合（如卯申合，申中壬为劫），主什么？","opts":["妻被合住，绝对不会出轨","妻入墓库，主妻早亡守鳏","妻合到贵人，必定旺夫发财","妻合到劫地，妻子找别人"],"ans":3,"exp":"妻星合到劫地（如申中壬为劫财，或巳上带劫被宾位合），主妻跟别人跑、找别人。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"男命妻宫坐亥水正财得正位，但命局比劫旺相众多、亥水受克无生，常主什么行为象？","opts":["暴力打老婆，财虚透运易离","妻子强势掌权，男方逆来顺受","夫妻聚少离多，感情平淡无争","极度宠爱妻子，对妻言听计从"],"ans":0,"exp":"正财得正位怕比劫克夺，比劫旺众且财受克无生，主暴力打老婆之象，行财星虚透运离异。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"男命妻星在天干外生七杀，且该妻星又入于他柱七杀之墓（宾位他人的妻宫），主什么？","opts":["妻子极度旺夫，帮夫升官发财","妻子有外遇，跟别的男人走","妻子性格刚烈，在家克制丈夫","妻子在体制内做高官掌实权"],"ans":1,"exp":"妻星外生杀，又入于杀之墓（别人的妻宫），主妻子有外遇之意。","sec":"1. 宫多现、星多用","t":"xiang"},{"q":"若男命第一妻天干财星与坐支「干支一气」（如癸丑一气），在判断妻子是否外遇时应注意什么？","opts":["干支一气主妻子必然多次出轨","干支一气主妻子必为二婚带娃","干支一气不能看妻有别的男人","干支一气主妻子在婚前同居多人"],"ans":2,"exp":"如癸财生乙虽主妻找别人，但若原局是癸丑一气，则不能看妻有别的男人。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"男命原局有「庚辰、酉」的妻星妻宫组合，本主一人不离，若八字另见「乙巳」劫财合之，会如何？","opts":["乙巳帮身担财，一婚更加稳固","只是自己有桃花，绝对不会离婚","乙巳主妻贤惠，帮夫打理家业","第一妻被别人合走，一婚必离"],"ans":3,"exp":"若无巳劫财，庚辰酉视为一人不会离婚；一旦有乙巳合走庚辰，则被别人合走，第一婚必离。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"男命「土逢冲（如戌辰戌）」何以能代表两个不同的妻子？年上庚戌到时上庚戌又主什么？","opts":["财星多现各有所主；主妻从远方来","土逢冲只主同居；主妻是亲戚介绍","土逢冲必主克死前妻；主妻在同村","土逢冲主一妻不离；主妻是青梅竹马"],"ans":0,"exp":"财星多现，各有所主，故土逢冲可代表不同妻子；年上庚戌到时上庚戌，主妻从远方来。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"男命妻宫被羊刃穿，命中有两个羊刃克掉两个妻子，那么第三次婚姻通常会如何？","opts":["第三次只能找离过婚的否则必死","第三个克不动了，可白头到老","第三个同样克死，须克七个才止","克掉两个后终身孤寡无法再婚"],"ans":1,"exp":"命中有两个羊刃克掉两个妻子，到第三个就克不动了，逢劫财流年成婚后可白头到老。","sec":"1. 宫多现、星多用","t":"calc"},{"q":"男命原局有两丁一午（午代表丁），共三个劫财羊刃透干包制申金妻星，主几次婚？","opts":["只有一个申金，只主一次婚姻","申金被包制死，终身无妻无婚","三个克妻因素，三次婚姻","两丁一午合化，主五次以上婚姻"],"ans":2,"exp":"2丁1午共三个劫财，有三个克妻因素，故主三次婚，申代表三个妻子。","sec":"1. 宫多现、星多用","t":"calc"},{"q":"男命「甲庚丁庚／午午酉戌」虽无劫刃透干、婚姻稳定不离，但「酉财被戌穿」仍会应在什么上？","opts":["妻子红杏出墙，长年分居","子女早夭折，晚年无靠","自己破产负债，一生贫寒","妻子身体不好，长年有病"],"ans":3,"exp":"未透丙丁劫刃，两午之禄表示自己故不离婚；但酉财被戌穿，主妻子身体不好、长年有病。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"「一星两宫、双拱两婚」的男命，若在世俗法律上始终未离婚，这种命局结构常如何应验？","opts":["男人在外有情人并生子，实质二妻","妻子在婚后长期患病住院","完全不应验，夫妻极其恩爱忠诚","命主出家修行彻底断绝男女关系"],"ans":0,"exp":"一星两宫命该两婚，四同八字中有人离婚再娶，有人虽没离婚却在外有情人并生子。","sec":"1. 宫多现、星多用","t":"diff"},{"q":"在土财星的婚姻判断中，「土财逢刑冲」与「不刑冲的土财星」在桃花与妻数上有何区别？","opts":["逢刑冲必主多桃花；不刑冲必主一妻","逢刑冲反主一妻；不刑冲有可能主桃花","两者都主多妻多妾，没有本质区别","逢刑冲必克死三妻；不刑冲必主晚婚"],"ans":1,"exp":"凡土作妻星逢刑冲反主一妻（互相牵制）；而不刑冲的土财星，则有可能表示桃花。","sec":"三、反例：满盘财星逢刑冲，反主一妻","t":"diff"}]},{"n":97,"level":"高级","title":"女命多婚组合","qs":[{"q":"盲派论女命婚姻，夫星和夫宫分别取什么？","opts":["官杀为夫星，月支为夫宫","官杀为夫星，日支为夫宫","食伤为夫星，日支为夫宫","财星为夫星，日支为夫宫"],"ans":1,"exp":"女命以官杀为夫星、日支为夫宫；多婚结构都是围绕星、宫的好坏看的。","sec":"一、女命多婚的组合","t":"rule"},{"q":"夫宫没坏而夫星被坏，又有新的夫星出现，与夫宫虽不多现但夫宫被坏，各主什么？","opts":["两者都只主丈夫有外遇，不离婚","前者一婚不到头；后者容易多婚","前者容易多婚；后者一婚不到头","两者都主终身不婚"],"ans":2,"exp":"夫星被坏又有新夫星是多婚；夫宫被合坏、刑坏、穿坏则一婚不到头。","sec":"一、女命多婚的组合","t":"diff"},{"q":"女命夫星被比劫包、被比肩合走，主什么？","opts":["丈夫早亡，守寡不再嫁","婚姻美满，比劫帮夫","丈夫发财，但夫妻缘薄","丈夫必有外遇，初婚亦离"],"ans":3,"exp":"比劫争夫，夫星与宫的联系再好，初婚也离。","sec":"一、女命多婚的组合","t":"rule"},{"q":"盲派说的「关财门」是怎么回事？","opts":["财是官杀之原神，财被冲坏或劫克，必多婚","财被合住，官杀不透，必晚婚","印被财克，官杀无生，必多婚","官杀被冲坏，财无依靠，必多婚"],"ans":0,"exp":"财为夫星（官杀）的原神，财星被冲坏、被劫克，夫星无源，称关财门。","sec":"一、女命多婚的组合","t":"rule"},{"q":"「一星两宫、双宫双星」，主几次婚姻？","opts":["一次，因星宫相合","两次，第一次没合到位","两次，第二次没合到位","三次，因多现必刑"],"ans":1,"exp":"夫宫或夫星多现，第一次没合到位，主两次婚姻。","sec":"一、女命多婚的组合","t":"rule"},{"q":"夫宫辰在日、时伏吟，这种两辰并见是否表示二婚？","opts":["表示二婚","表示三婚","不表示二婚","表示夫外遇但不离"],"ans":2,"exp":"双宫主二婚，但辰在日时伏吟则不表示二婚。","sec":"一、女命多婚的组合","t":"calc"},{"q":"夫星与夫宫之间两穿、一破，一共几婚，第几次才稳？","opts":["共三婚，第二次才好","共四婚，第三次才好","共两婚，第二次才好","共三婚，第三次才好"],"ans":3,"exp":"两穿离两次，破一次，共三婚；刑的能量耗尽后第三次婚姻才好。","sec":"一、女命多婚的组合","t":"calc"},{"q":"夫宫合入夫星之墓，怎么断？","opts":["夫不死则离，把婚姻埋了","只主晚婚，婚后美满","夫旺而不离，库中有财","夫宫稳固，只是不爱说话"],"ans":0,"exp":"夫宫合入夫星之墓，婚姻被埋；夫不死则离。","sec":"二、典型命例","t":"rule"},{"q":"夫星多合（合一次加一个，或因合而离开），主什么？","opts":["主晚婚，合则稳固","主多婚，合一次加一个夫","主不婚，合则孤独","主丈夫发财，合则助夫"],"ans":1,"exp":"夫星多合，合一次加一个，或因合而离开，是多婚组合之一。","sec":"一、女命多婚的组合","t":"rule"},{"q":"女命合财，对婚姻有多大意义？","opts":["合财主夫有外遇","合财主婚姻稳固","没有多大意义","合财即合夫，主婚成"],"ans":2,"exp":"财是官杀的原神，女命合财本身对婚姻的意义不大，要看星宫刑穿的变化。","sec":"三、本章小结","t":"rule"}],"fine":[{"q":"女命「夫宫多现又配夫星」形成婚姻组合，还须具备什么条件才容易多婚？","opts":["命局食伤全部入墓","夫宫本身不稳","夫星坐于印星之上","夫宫伏吟在日时两柱"],"ans":1,"exp":"女命多婚组合之一：夫宫多现又配夫星形成婚姻组合，而夫宫本身不稳，则容易多婚。","sec":"一、女命多婚的组合","t":"rule"},{"q":"按女命多婚常用诀，为何夫星与夫宫之间「被穿、被破」就会导致离婚？","opts":["星宫穿破后，子女必定离家","星宫穿破后，财星必定暴发","星宫穿破后，夫星不能相生","星宫穿破后，日主必定早亡"],"ans":2,"exp":"星宫之间被穿、被破，则夫星不能相生，宫星无法相守，故主离婚。","sec":"常用诀","t":"rule"},{"q":"女命头婚夫星被夫宫破、又被他支穿而离，若二婚看时支官星，什么情况下第二次能过得好？","opts":["二婚夫星透在年干且坐比劫","夫宫继续穿破二婚夫星","二婚夫星入墓于他支且不开","夫宫生助二婚夫星且无伤克"],"ans":3,"exp":"如日支卯破午又丑午穿致初婚离，而时支巳火有日支卯木相生且无伤克，则第二次婚姻过得好。","sec":"1. 夫星被穿、被争","t":"diff"},{"q":"女命天干虚透七杀（如月干庚金），且与日主相冲，这段婚姻通常呈现什么特点？","opts":["短暂婚姻，难白头到老","长久婚姻，必定白头偕老","只恋爱不结婚，终身无名分","丈夫身居高位，婚姻极稳"],"ans":0,"exp":"天干杀星虚透本主短暂婚姻，再与日主相冲，主很快离异，不是长久之夫。","sec":"1. 夫星被穿、被争","t":"xiang"},{"q":"女命夫宫见禄，行「禄合印」的大运时，婚姻生活常呈现什么状态？","opts":["连年桃花不断，频繁再婚","一个人过，处于单身状态","夫妻极其恩爱，寸步不离","丈夫飞黄腾达，全家迁居"],"ans":1,"exp":"女命夫宫见禄本身已有独处之象，行禄合印之运（如壬辰运）主一个人过、单身。","sec":"1. 夫星被穿、被争","t":"xiang"},{"q":"女命盘中天干透出两个相同官星（如双丙），或两柱同地支夫星（如戊申、庚申），数夫时怎么算？","opts":["双丙算两人，戊申庚申算两人","双丙算一人，戊申庚申算三人","双丙算一人，戊申庚申算一人","双丙算三人，戊申庚申算一人"],"ans":2,"exp":"双丙连体是一个人；戊申、庚申同占一申也算一个人。","sec":"1. 夫星被穿、被争","t":"calc"},{"q":"女命日支与官星暗合（如寅丑暗合）本属好婚姻，但若年月比劫众多且「子丑合」力量大于「寅丑合」，结果如何？","opts":["只是婚前波折，婚后绝无外遇","比劫帮身担夫，婚姻更加富贵","寅丑暗合仍能保住初婚不离","比劫争夫，必然离婚"],"ans":3,"exp":"年月比劫众多为比劫争夫，且年月子丑合的力量大于日支寅丑合，故初婚必离。","sec":"1. 夫星被穿、被争","t":"diff"},{"q":"女命原局时支有官星（如午火），但早年大运行「巳运」直接冲入夫宫，头婚应看谁？","opts":["头夫不看午，而看巳运冲入之夫","头夫看年柱，巳运与婚姻全无关","巳运冲宫必主克死原局午火丈夫","头夫只看午，巳运绝对不结婚"],"ans":0,"exp":"午火虽为夫，但大运行巳运冲入夫宫，头夫不看午而看巳运；再婚才找午为夫。","sec":"2. 宫星双现、夫宫入墓","t":"diff"},{"q":"女命大运中出现「夫宫入大运之墓」（如亥夫宫入丙辰大运辰墓），夫妻关系常出现什么象？","opts":["女方暴富掌权，男方入赘女家","男方常年不在家，关系难维持","男方天天粘在家，夫妻极度恩爱","夫妻双方同时升职，感情更深"],"ans":1,"exp":"丙辰运亥入辰墓，男的常年不在家，夫妻关系无法维持而致离异。","sec":"2. 宫星双现、夫宫入墓","t":"xiang"},{"q":"女命流年或原局出现「官星坐禄又自合」，在男女感情上多主什么？","opts":["丈夫有外遇","终身无桃花","自己有桃花","必嫁大富豪"],"ans":2,"exp":"官星坐禄又自合（如戊子年或时上癸巳禄上坐杀自合），皆主女命自己有桃花。","sec":"2. 宫星双现、夫宫入墓","t":"xiang"},{"q":"女命以「辰」为官星，同时「辰又是比劫库，且辰拱比劫」，这种官星有何特点？","opts":["丈夫体弱多病，依赖妻子","丈夫忠厚老实，绝无外心","丈夫孤僻寡言，远离人群","丈夫花心，且有争夫之象"],"ans":3,"exp":"辰是官又是比劫库，主花心；辰拱比劫，是比劫争夫之象。","sec":"2. 宫星双现、夫宫入墓","t":"xiang"},{"q":"女命夫星或婚姻组合呈现「戌加巳、阳包阴、阳制阴」，其丈夫在生活习惯上常有何象？","opts":["赌徒之象","教师之象","医生之象","僧道之象"],"ans":0,"exp":"戌加巳，阳包阴、阳制阴，在盲派取象中为赌徒之象。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命遇到「辰为官之退气」作为婚姻或同居对象，这类关系有何特点？","opts":["找高官显贵之人，且富贵终身","找离过婚的男人，且不长久","找未婚初恋青年，且白头到老","找同乡青梅竹马，且感情极稳"],"ans":1,"exp":"辰为官之退气，代表找离过婚的男人，且这种关系也不长久。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命「主位的正官」最忌讳什么情况，一旦发生就会导致婚姻变坏？","opts":["最忌透干，一透婚姻就坏","最忌坐禄，一坐婚姻就坏","最忌他合，一合婚姻就坏","最忌得生，一生婚姻就坏"],"ans":2,"exp":"主位的正官不喜他合，一合婚姻就坏（如他支带劫财来合，男人外边有别人）。","sec":"3. 星被合、宫被穿的离与再婚","t":"rule"},{"q":"女命原局「夫星墓中有比劫，且天干官星又见他合（如戊癸合）」，丈夫的外遇往往呈现什么状态？","opts":["丈夫只是暗恋，绝不敢行动","外遇很快结束，绝不会被人知","情人必定是命主的亲姐妹","丈夫的情人会公开化"],"ans":3,"exp":"夫星中墓有比劫，又见戊癸合他合，主丈夫的情人会公开化。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命双宫双星且夫墓有比劫，若原局有食伤（如卯时）穿宫星则必离；若去掉此食伤穿，结局如何？","opts":["不离婚，只是丈夫有外遇","终身嫁不出去，孤独终老","婚姻极其完美，绝无外遇","依然必离，且比有食伤更惨"],"ans":0,"exp":"食伤穿了宫星则必离；若无此食伤穿之，则不离，只是夫有外遇。","sec":"3. 星被合、宫被穿的离与再婚","t":"diff"},{"q":"女命以「丑未冲」作为未土夫宫与丑土夫星的关联，为何行「戌运」反主离婚？","opts":["戌土生助夫星太旺，导致克身","戌刑坏了丑未冲，使冲不成立","戌运与夫宫相合，主丈夫升官远调","戌土为食伤，直接克死了未土夫星"],"ans":1,"exp":"丑未冲为宫星关联，行戌运成丑未戌三刑，坏了宫星之冲（使冲不成立）故离；不行戌运则无事。","sec":"3. 星被合、宫被穿的离与再婚","t":"diff"},{"q":"女命「夫宫（如辰）中含比肩，且带复吟」，所嫁的丈夫通常有什么婚姻经历？","opts":["丈夫是初婚未娶的","丈夫终身不愿领证","丈夫是离过婚的","丈夫是丧偶多年者"],"ans":2,"exp":"夫宫中含比肩、带复吟，主丈夫之前有过婚史，是离过婚的。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命局中既有七杀为正夫、又有正官为偏夫（婚外情），在人物对比上常见什么特征？","opts":["正夫远在海外，情人就在本单位","正夫年幼未婚性格暴，情人年长稳重","正夫贫困无能，情人必定是富豪","正夫年长离异对她好，情人年相当或小"],"ans":3,"exp":"如寅为正夫（离过婚、大十来岁、对她好），乙卯为偏夫情人（年岁相当或小一点，不如夫好）。","sec":"3. 星被合、宫被穿的离与再婚","t":"diff"},{"q":"女命「夫宫之夫星伏吟到月令并带比劫」，在婚姻象意上代表什么？","opts":["伏吟就是出去了，丈夫跟别人","伏吟就是回来了，丈夫极恋家","伏吟主夫妻双胞胎，同进同出","伏吟主丈夫升官，月令掌大权"],"ans":0,"exp":"夫宫之夫星伏吟到月令带比劫，伏吟就是出去了，主丈夫跟别人走。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命原局无离婚象，却在癸卯运「子破卯」离异，其中卯为枭印、七杀的食神，离婚主因常是什么？","opts":["丈夫赌博欠债而躲债离婚","婆婆不喜欢她而导致离异","双方父母要求彩礼过高吹掉","自己出轨同事而主动离婚"],"ans":1,"exp":"卯木枭印为婆婆（亦是七杀的食神），夫星子水破卯，主因婆婆不喜欢她而离异。","sec":"3. 星被合、宫被穿的离与再婚","t":"xiang"},{"q":"女命婚姻若涉及「情人先出现、正夫后成婚」的顺序变化，通常需要大运或流年发生什么作用？","opts":["只要等到食伤伏吟之年自然就会转正","一旦先做情人就绝对不可能变成正夫","看刑等变化，如刑去阻碍使之变正夫","必须等正夫入墓不开后才能转正"],"ans":2,"exp":"情人先、夫后需看刑的变化，如丑戌刑了，原本为情人的寅就变成了自己的丈夫。","sec":"三、本章小结","t":"rule"}]},{"n":98,"level":"高级","title":"婚外情与桃花（男女命）","qs":[{"q":"按盲派，男命婚外情的基本格局是什么？","opts":["财星多，妻宫入墓","妻宫稳定，有伤官透干","妻宫稳定，有副妻宫现，再有配偶星相配","妻宫被冲，有副妻宫现"],"ans":2,"exp":"男命婚外情：妻宫相对稳定，有副妻宫出现，再有配偶星与之相配。","sec":"规则","t":"rule"},{"q":"男命婚外情有可能的前提是什么？","opts":["只要伤官旺就有","一般须官杀旺，官杀制比劫","只要财多就有","一般须比劫旺，无比劫财再多也无用"],"ans":3,"exp":"比劫主占有欲，一般必须比劫旺婚外情才有可能；如无比劫，再多财也无用。","sec":"规则","t":"rule"},{"q":"男命比劫旺而七杀透干制比劫，桃花如何论？","opts":["自我控制强，不一定有桃花","七杀透干则必无桃花且不婚","比劫旺必有桃花，杀只增加数量","七杀制比劫，桃花更多更乱"],"ans":0,"exp":"有七杀透干制比劫的，自我控制强，不一定有桃花；不是所有比劫旺的人都有桃花。","sec":"规则","t":"diff"},{"q":"男命伤官桃花与比劫桃花的区别是？","opts":["两者都情深，只是数量不同","伤官桃花情份不深，比劫桃花多而没感情","伤官桃花占有欲强，比劫桃花放任","伤官桃花缠身，比劫桃花专一"],"ans":1,"exp":"伤官主放任，桃花不缠身、用情不专一；比劫主占有，桃花多而没多少感情。","sec":"规则","t":"diff"},{"q":"男命时上有丑库而不被冲开，象义是什么？","opts":["主不近女色，无桃花","库里藏着一个固定情人","库里有很多女人","主妻子早逝"],"ans":2,"exp":"特殊象：时上库不开（如丑），里边有很多女人；库靠大运流年引动。","sec":"特殊象","t":"xiang"},{"q":"男命伤官在宾位、头上盖着庚（比劫），象义是什么？","opts":["主无桃花","是自己的正妻","是自己的情人且专情","是别人的女人"],"ans":3,"exp":"伤官桃花不缠身，伤官在宾位、头顶庚比劫，是别人的女人；庚坐戌也主外边的女人。","sec":"特殊象","t":"xiang"},{"q":"男命八字中的戌，桃花象上代表什么？","opts":["色情场所","正式妻子","寿元","贤惠之妻"],"ans":0,"exp":"特殊象：戌为色情场所；庚坐戌主外边的女人。","sec":"特殊象","t":"xiang"},{"q":"男命官星化财，与正常财星相比，桃花多少如何？","opts":["比正常财星少得多","比正常财当桃花的命多得多","官星化财则必无桃花","与正常财星相同"],"ans":1,"exp":"特殊象：官星化财，比正常财当桃花的命多得多。","sec":"特殊象","t":"rule"},{"q":"女命婚外情的规则，下列哪一条正确？","opts":["女命夫宫被冲才有桃花","女命见伤官再逢比劫，必有桃花","女命见禄再逢财官，容易有桃花","女命见印再逢官杀，容易有桃花"],"ans":2,"exp":"女命：夫宫稳定有副夫宫现，再有配偶星相配；有另外夫星拱入夫宫；见禄再逢财官容易有桃花。","sec":"规则","t":"rule"},{"q":"女命官星的退气库（辰、戌、未之类）取象为桃花，意思是？","opts":["是已故的丈夫","是将来的婚姻","是正式的丈夫","不是正式的丈夫"],"ans":3,"exp":"官星退气为桃花，意思是不是正式的丈夫；入墓不开则多，且是别人的男人。","sec":"补充象","t":"xiang"}],"fine":[{"q":"盲派按关系持续时间与目的划分婚外关系，持续最久的、略长的、短的分别称为什么？","opts":["正妻、偏房、过客","偏房、外室、红颜","妾、情人、桃花","情人、桃花、露水"],"ans":2,"exp":"持续最久的称妾，略长的为情人，短一些的及不以结婚为目的或无法结婚的都称桃花。","sec":"婚外情与桃花（男女命）","t":"diff"},{"q":"盲派高级体系判断「桃花运」的依据是什么，与传统神煞法有何不同？","opts":["专以年支子午卯酉定沐浴桃花","专以红鸾、天喜、咸池神煞定桃花","只看日支是否逢六合，不看副宫与星","按宫、星、副宫、比劫看，不用沐浴"],"ans":3,"exp":"盲派的「桃花运」按宫、星、副宫、比劫来看，不用沐浴看桃花的另一套法。","sec":"婚外情与桃花（男女命）","t":"diff"},{"q":"男命虽见多个财星，但「比劫太弱，且唯一的比劫被湿土晦坏」，婚姻与桃花如何断？","opts":["无桃花，婚姻也只有一次","必主克妻，至少三次婚姻","桃花极多，但绝不会离婚","财多身弱，必找年长情人"],"ans":0,"exp":"男命比劫太弱、财或比劫被湿土晦坏无力去劫时，无桃花，婚姻也是一次。","sec":"规则","t":"rule"},{"q":"男命局中出现「财星合入家中（如甲己合，巳入戌墓）」，在男女关系上代表什么象？","opts":["终身不近女色","女人进了家中","女方父母来同住","妻子离家出走"],"ans":1,"exp":"财星合入家中（如甲己合、巳入戌墓），读象为女人进了家中，主好色多桃花。","sec":"特殊象","t":"xiang"},{"q":"男命「庚坐戌」（比劫坐于戌上）在婚外情特殊象中代表什么？","opts":["发妻正室","自己的女儿","外边的女人","年长的上司"],"ans":2,"exp":"戌为色情场所，庚坐戌主外边的女人。","sec":"特殊象","t":"xiang"},{"q":"男命「两卯合戌」本是包局一妻，若「月令丁卯受年支酉冲」，两卯应如何区分？","opts":["依然是一个人，只是妻子常出差","月令卯为正妻，时上卯为自己的母亲","两卯皆被冲坏，终身无妻也无情人","不是一个人，月令卯为同学或情人"],"ans":3,"exp":"一般两卯合戌表示一人，但月令丁卯受酉冲后，月上卯与时上卯不是一个人，月令卯为情人、同学。","sec":"二、男命婚外情命例","t":"diff"},{"q":"男命局中有「壬子、辛亥」两个女人，虽大运破夫妻宫，但因「亥子同入辰墓、子辰相合包局」，结果如何？","opts":["妻妾同居一室之象，婚姻不易离","男方必因桃色纠纷而倾家荡产","两个女人同时离开，孤家寡人","原配必定迅速离婚，再娶新欢"],"ans":0,"exp":"亥子同入辰墓为妻妾同居一室之象，子辰相合出现包局，故婚姻不易离，几次要离没离成。","sec":"二、男命婚外情命例","t":"diff"},{"q":"男命见「子水伤官冲入妻宫」，且「子在庚比劫下」，为何不当妻子而当情人看？","opts":["伤官绝对不能进入男命的夫妻宫","子在庚下是别人女人，伤官主玩乐","子水在年支，主早年夭折的同学","子水五行太寒，不能生助日主"],"ans":1,"exp":"子在庚比劫下，是别人的女人；伤官主玩乐之意，一般不主婚姻，故当情人看。","sec":"二、男命婚外情命例","t":"diff"},{"q":"男命「伤官桃花（如子水）与夫宫形成拱局（非冲）且夫宫复吟占伤官库」，感情特点如何？","opts":["终身只有一个情人，且白头偕老","桃花虽多，但每次都被对方骗光钱","桃花多但不缠身，不处感情较淡","用情极深且专一，愿为情人离婚"],"ans":2,"exp":"子辰多拱桃花多，伤官桃花用情不专、分情、不缠身、不处感情、较淡。","sec":"二、男命婚外情命例","t":"diff"},{"q":"男命甲日主见「两己合身」主桃花，若月令己在卯地、时上己在巳地，两者有何区别？","opts":["月令己是初恋未嫁，时上己是寡妇","月令己是远方网友，时上己是同乡","月令己是发妻，时上己是自己的女儿","月令己是别人老婆老相好，时上己是新人"],"ans":3,"exp":"两己合身主桃花，月令己在卯地主别人的老婆、老相好；时上己是新人。","sec":"二、男命婚外情命例","t":"xiang"},{"q":"男命坐下卯为妻宫，若左右相邻两支对卯形成「两头穿（夹穿）」，婚姻通常如何？","opts":["夹穿穿不离，只是配偶多病而已","夹穿主新婚不久即闪电离婚","夹穿力量极强，必定克死两任妻子","夹穿主妻子红杏出墙并卷款潜逃"],"ans":0,"exp":"坐下卯为妻，两头穿是夹穿，夹穿穿不离，多病而已。","sec":"二、男命婚外情命例","t":"diff"},{"q":"男命桃花星戊土落时上，且局中「丙火生戊土」，若丙火代表传媒，这段桃花易出现什么后果？","opts":["桃花对象是自己的亲戚","桃花事件容易被曝光","桃花极其隐秘无人知晓","桃花会带来巨额意外之财"],"ans":1,"exp":"丙为传媒，戊为桃花，戊被丙生容易曝光，主桃色新闻公之于众。","sec":"二、男命婚外情命例","t":"xiang"},{"q":"男命乙日主时上见「寅」劫财（与乙相通、为日主之禄），与日支「丑」暗合，主什么？","opts":["寅为正官，暗合主因桃花而升官发财","寅丑暗合主夫妻极度恩爱、白头偕老","寅为自己男根，暗合不主妻而主桃花","寅为别人男人，暗合主妻子红杏出墙"],"ans":2,"exp":"乙与寅相通，寅为日主之禄（代表命主男根），是一个人，故寅丑暗合不主妻子而主桃花。","sec":"二、男命婚外情命例","t":"xiang"},{"q":"女命原局「阴多阳少者喜阳」，在桃花与婚姻稳定性上有什么特殊规律？","opts":["阴多阳少者，终身不会有桃花","越有桃花，婚姻越容易破裂","只要有桃花，必定克死丈夫","越有桃花，婚姻反而越稳定"],"ans":3,"exp":"女命阴多阳少者喜阳，越有桃花婚姻越稳定。","sec":"补充象","t":"rule"},{"q":"女命「夫宫多现，财官都来合禄」，在异性关系上通常表现为什么？","opts":["固定不住，较随便，桃花男友多","丈夫掌权，自己在家相夫教子","坚守贞操，一生只爱一人","眼光极高，终身难遇合适对象"],"ans":0,"exp":"夫宫多现的财官都来合禄，主固定不住、随便，桃花多、男友多。","sec":"补充象","t":"rule"},{"q":"女命遇「比劫桃花（如丙辛来合桃花）」，在行劫财运或桃花运时常伴随什么后果？","opts":["因桃花而升官掌权（官印相生）","因桃花而大破财（劫运破财）","因桃花而身体健康（禄神得生）","因桃花而大发横财（桃花生财）"],"ans":1,"exp":"比劫桃花（丙辛来合桃花），行劫运主因找桃花而大破财，甚至养活小桃花。","sec":"补充象","t":"xiang"},{"q":"女命「暗桃花」（如卯为财星，在局中冲一次、合二次共用了三次），属于什么类型？","opts":["克夫害子型，与钱财毫无关系","精神柏拉图型，绝无肉体接触","无感情型，多图男人钱财搞桃花","纯情浪漫型，只谈感情不谈钱"],"ans":2,"exp":"暗桃花如卯用三次（冲一次、合二次），卯为财无感情型，多图男人钱财搞桃花。","sec":"补充象","t":"xiang"},{"q":"女命流年天干的某字（如癸）到来，把原局所合之字（如戊）合走外出，桃花应期有何表现？","opts":["桃花直接转正，当年就领证结婚","桃花持久缠绵，一处就是十几年","绝对不会出现桃花，全年平静无波","桃花瞬间来去，刚看上就走了"],"ans":3,"exp":"流年天干某字（如癸）到，则其所合之字（戊）外出，桃花瞬间来去，刚看上男的就走了。","sec":"补充象","t":"calc"},{"q":"女命原局有「包局（如酉包局生亥且时上重现）」，若女命「财重用情」，与已婚情人分手后常怎样？","opts":["不会彻底分开，往往藕断丝连","立刻彻底断绝联系，老死不相往来","因爱生恨，公开举报对方家庭","马上逼迫对方离婚并成功转正"],"ans":0,"exp":"女人财重用情，原局出现包局就不会彻底分开，过运暂分后仍藕断丝连。","sec":"四、女命婚外情命例","t":"diff"},{"q":"女命年上官星被月干高透的比劫（如甲木）争夺，在婚外情或配偶外遇上有什么公开性特征？","opts":["比劫高透，主女方悄悄暗恋他人","比劫高透，婚外情众人皆知","比劫高透，外遇极其隐蔽无人知","比劫高透，丈夫绝对不会出轨"],"ans":1,"exp":"月透比劫夺夫星，不仅表明配偶另有所欢，且比劫高透主婚外情众人皆知。","sec":"四、女命婚外情命例","t":"xiang"},{"q":"女命大运巳火禄神与申（日主长生、自己）相合（巳申合），且巳上坐官星，主什么？","opts":["自己身体受克，因桃花而破财生病","丈夫在外面养小三，自己在家守寡","自己身体同财官合，有桃花并带财运","彻底断绝桃花，专心致志拼事业"],"ans":2,"exp":"巳上坐官，巳申合，申为日主长生为自己，自己身体同财官合，自然有桃花并带来财运。","sec":"四、女命婚外情命例","t":"xiang"},{"q":"女命「借象时干丁火看桃花，丁落子女宫之伤官，且局中卯辰穿」，其桃花对象可能应到谁？","opts":["同班读书的青梅竹马","远方异国他乡的富商","年长二十岁的单位领导","晚辈亲人，甚至非亲生的儿子"],"ans":3,"exp":"丁落子女宫之伤官为儿子，卯辰穿不是亲生的，故桃花对象应到自己的晚辈亲人（非亲生儿子）。","sec":"四、女命婚外情命例","t":"xiang"}]},{"n":99,"level":"高级","title":"包局婚姻判断","qs":[{"q":"按盲派，包局婚姻有哪三种基本结构？","opts":["星生宫、宫生星、星宫互相克","星入墓、宫入墓、星宫同入墓","星合宫、宫合星、星宫互相冲","星包宫、宫包星、星宫全被他星包"],"ans":3,"exp":"包是一个字被另外的字夹住围住：星在宫两头、宫在星两头，或星宫一起被别的字围住。","sec":"一、包局的三种基本结构","t":"rule"},{"q":"配偶星包局的婚姻有什么特点？","opts":["被配偶看得紧，不易离婚，离则代价大","配偶不管事，婚姻宽松","容易离婚，离婚代价小","配偶多外遇，但必离"],"ans":0,"exp":"包局婚姻自己被看得紧，容易累也不容易离婚，一旦要离要付出很大代价。","sec":"配偶星包局婚姻的三个特点","t":"rule"},{"q":"六合式的包局，婚姻是什么情形？","opts":["合则和睦，婚姻美满","合得紧看得紧，婚姻痛苦","合住后配偶外出，聚少离多","合而不紧，一说就离"],"ans":1,"exp":"六合式包局合得紧看得紧，晚上到点必须回去，所谓结婚等于坐牢。","sec":"配偶星包局婚姻的三个特点","t":"rule"},{"q":"以亥为妻星，两头各有一亥成包局，天干分别配哪组时包局不成立（反局）？","opts":["甲亥与丙亥","壬亥与庚亥","辛亥与乙亥","己亥与丁亥"],"ans":2,"exp":"两头字天干相克，象反了不是同一人，包局不成；其余几组天干相生，仍是同一人。","sec":"反局：两个同字不是同一人","t":"calc"},{"q":"包局出现反局（两头字象相反），婚姻如何？","opts":["包局更牢，婚姻离不了","要等冲夫宫的大运才离","只主吵架，不会离婚","包局不成立，婚姻必离"],"ans":3,"exp":"包局的前提是两头字象相同可视为同一人；象反则不是一个人，包局不成，婚姻必离。","sec":"反局：两个同字不是同一人","t":"rule"},{"q":"包局婚姻想离，下列哪个才是原局包局被破开的方式？","opts":["羊刃克妻大运或冲破夫宫的流年","流年再合一个配偶星","印星合入日主","大运生助配偶星"],"ans":0,"exp":"冲破夫妻宫（羊刃克妻之大运、冲夫宫流年）破了原局包局，终能离；六合式包局可被六合破暗合。","sec":"二、星包局命例（离不了）","t":"diff"},{"q":"女命官杀被食伤、禄印等包局，婚姻怎么论？","opts":["婚姻必离，包局为破","婚姻稳不会离，夫宫受破也只主手术伤灾","婚姻稳，但丈夫必外遇","婚姻不稳，因食伤克官"],"ans":1,"exp":"官星被包局稳，虽夫宫被穿被破（丑午穿、卯午破），也只主丈夫手术或伤灾，不离婚。","sec":"四、官杀包局、官局不离","t":"rule"},{"q":"盲派判断“被人包养”的口诀是什么？","opts":["女命八字官杀混杂，比劫包局","女命八字无财星，官星包局","女命八字无官杀，财星包局","女命八字无印星，食伤包局"],"ans":2,"exp":"女命无官杀，财星（或伤官带财）包局者被人包养；包她的人多带比劫库、有家室。","sec":"五、财包局：被人包养的组合","t":"rule"},{"q":"被包养的命，包养她的男人一般有什么特点？","opts":["年龄小，无家室","出身贫寒，无钱财","官职高，但无子女","带比劫库，有家室"],"ans":3,"exp":"包她的人多带比劫库（如戌中丁、未木库），是有家室的人。","sec":"五、财包局：被人包养的组合","t":"rule"}],"fine":[{"q":"盲派命理中，「包」字取象用于婚姻判断时，核心含义是指什么？","opts":["两个字天干五合，夫妻感情融洽","地支三合局成化，配偶人数众多","日主坐下得禄，自身独立不受约束","一个字被另外的字夹住围住，进退由他"],"ans":3,"exp":"「包」是盲派常用象法，指一字被他字夹住围住、进退由他，在婚姻上决定是被盯紧离不了还是被人包养。","sec":"包局婚姻判断","t":"xiang"},{"q":"以下哪一组干支放在星包局的两头时，与「辛亥、乙亥」同样属于天干象反、包局不成立的反局？","opts":["庚辰与甲辰、丁卯与癸卯","辛酉与癸酉、乙卯与丁卯","甲子与丙子、己丑与辛丑","壬寅与甲寅、丙午与戊午"],"ans":0,"exp":"包局前提是两头字象相同可视为同一人；庚辰与甲辰、丁卯与癸卯天干相克，象反不是一人，构成反局。","sec":"反局：两个同字不是同一人","t":"rule"},{"q":"乾造：乙丁壬乙／巳亥申巳，年时两乙巳妻星包局，其中「乙」与两「巳」取象为何主妻子盯得紧？","opts":["乙为花草牵绊，巳为食神贪恋享受","乙为电话线，两巳为眼睛，时刻跟着","乙为文书契约，巳为牢狱限制人身","乙为绳索捆绑，巳为驿马奔波不停"],"ans":1,"exp":"年时两乙巳妻星包局，乙象电话线，两个巳象眼睛，妻子电话跟着、眼睛盯着，不管走到哪都跟着。","sec":"二、星包局命例（离不了）","t":"xiang"},{"q":"乾造：乙丁壬乙／巳亥申巳，原局中月干丁配月支亥，在婚姻与感情上如何取象？","opts":["亥为妻之娘家，丁为妻之兄弟","亥为原配正妻，丁为婚生女儿","亥为别人的妻子，丁为自己的女友","亥为岳母宫位，丁为婚姻介绍人"],"ans":2,"exp":"亥在宾位为别人、别人的妻子，丁配亥则丁为女友；行午运为丁禄，壬午运情人离自己更近。","sec":"二、星包局命例（离不了）","t":"xiang"},{"q":"乾造：壬己癸甲／寅酉亥寅，寅为妻星成包局，且原局再无别的配偶星干扰，大运又不行克妻运时，婚姻如何？","opts":["配偶早逝，随后再娶贤妻","夫妻聚少离多，中年自然和平分手","先离后复婚，一生感情起伏极大","包局婚姻看得紧且痛苦，但无法离婚"],"ans":3,"exp":"寅为妻成包局，无他星干扰又不行克妻大运，六合看得紧、晚上到点必须回去，婚姻痛苦却离不了。","sec":"二、星包局命例（离不了）","t":"rule"},{"q":"坤造：丙丙癸丙／辰申卯辰，原局既有卯辰相穿，又有辰包局，其婚姻实际走向应如何判断？","opts":["两头穿穿不动，婚姻不好却离不了","卯辰穿破夫妻宫，初婚必早离","辰申拱水生身，夫妻恩爱无波折","卯木冲克辰土，丈夫早年丧命"],"ans":0,"exp":"辰为丈夫成包局，虽然日支卯与辰相穿，但两头包局穿不动，所以婚姻不好却离不了；辰申拱主夫有外遇。","sec":"二、星包局命例（离不了）","t":"calc"},{"q":"坤造：丙丙癸丙／辰申卯辰，大运行至壬辰运时遇到桃花企业家，此人不是原局丈夫的原因是？","opts":["卯辰穿破大运辰土，主虚幻无实之人","壬辰与原局丙辰象变了，是有家室的男人","壬水克癸水比劫，主外遇短暂即散","申辰拱水化局，主远方未婚青年"],"ans":1,"exp":"原局丈夫为丙辰（丙辰是男人目光盯着她），行壬辰运天干象变，与丙辰不是同一人，主遇到有家的男人。","sec":"二、星包局命例（离不了）","t":"xiang"},{"q":"乾造：庚己庚己／寅卯申卯，原局卯木妻星包局且卯申合缠绊难离，最终在乙酉运乙酉年离婚，其破局机制是？","opts":["寅木入申绝地，妻星能量自然耗尽","流年天干透乙木，构成反局自散","行羊刃克妻大运，冲破了原局包局","申酉戌三会金局，化去原局卯木"],"ans":2,"exp":"卯包局且卯申合缠绊，离婚极难；幸逢乙酉运为羊刃克妻之大运，乙酉年冲破原局包局，上法院多次后终能离。","sec":"二、星包局命例（离不了）","t":"step"},{"q":"乾造：甲丁乙戊／寅卯亥寅，时上见寅包局且妻子凶悍，后于辛运甲申年离异，原局中提供离婚再娶条件的是？","opts":["丁火食神克制比劫，主妻主动离去","戊土财星透于时干，主另娶新欢","寅亥六合化木，主原配自动退出","寅上透甲可为他人妻，且亥卯合进妻宫"],"ans":3,"exp":"寅为妻包局，但寅上透甲，甲己或他柱可配，表示妻可以成为别人的老婆；丁卯年亥卯合进妻宫为第二妻。","sec":"二、星包局命例（离不了）","t":"calc"},{"q":"坤造：庚甲丁戊／戌申卯申，两申为一人成包局且申卯暗合如坐牢，最终能走出牢笼离婚的特殊合局破法是？","opts":["年日卯戌六合，以六合破开申卯暗合","日时卯申暗合，耗尽申金夫星之力","年时戌申拱合，将夫星引出宾位","月时申酉半会，以金局冲克卯木"],"ans":0,"exp":"申包局本如坐牢，但因原局年日卯戌六合，盲派以「六合破暗合」，乙酉年冲破夫妻宫后终于离婚走出牢笼。","sec":"二、星包局命例（离不了）","t":"diff"},{"q":"坤造：庚甲丁戊／戌申卯申，离婚后改嫁老头且对方带财星，这在原局中对应哪一组合之象？","opts":["甲木正印透干，主嫁年长贵人","卯戌六合，合到年上伤官带财","庚金财星坐戌，主前夫留遗产","戊土伤官透时，主配偶年少多金"],"ans":1,"exp":"因有卯戌合，伤官戌在年上（年主大），合到年上伤官且戌中带财，故离婚后嫁老头且带财星。","sec":"二、星包局命例（离不了）","t":"xiang"},{"q":"乾造：壬辛己乙／子亥巳亥，两亥财星包局却因辛亥与乙亥象反而必离，若不离婚按盲派断有何后果？","opts":["仅主妻子外遇，婚姻名存实亡","夫妻长年分居，但白头偕老","象反代表两人，不离则死","自身破产败家，婚姻依然稳固"],"ans":2,"exp":"辛亥与乙亥天干相克，象反不是同一人，表示命中注定有两段婚姻关系，不离则死，实际乙运乙酉年离。","sec":"三、反局命例（必离）","t":"calc"},{"q":"坤造：庚庚丁甲／戌辰卯辰，宫星入于辰墓并成包局，为何仍断其初婚必离、会有第二夫？","opts":["丁火日主坐卯，印星过旺克夫","庚金透出年月，比劫争夫夺爱","辰土为水墓库，墓中官杀混杂必离","庚辰与甲辰象反，分属第一、二夫"],"ans":3,"exp":"虽宫星入辰墓成包局，但庚辰与甲辰天干象反不是一人，庚辰为第一夫，甲辰为第二夫，故初婚必离。","sec":"三、反局命例（必离）","t":"calc"},{"q":"乾造：己丁壬癸／酉卯午卯，两卯成包局，除丁卯、癸卯象反必离外，原局还有何象加剧初婚吵架必离？","opts":["日支午火与妻星卯木构成卯午相破","年干己土克日主壬水，官杀攻身","天干壬癸水克日支午火，水火相战","年支酉金与月支卯木构成卯酉相冲"],"ans":0,"exp":"丁卯与癸卯象反不是一人，加之日支午与卯相破（卯午破主吵架），故初婚必离，庚辰年卯辰穿应期离婚。","sec":"三、反局命例（必离）","t":"calc"},{"q":"坤造：丙丙辛丁／午申亥酉，官杀星包住日主，除主自身有女性魅力外，丙坐申上还主丈夫什么情况？","opts":["申为丈夫印星，主丈夫依赖母亲","申为丈夫桃花，主丈夫外边女人多","申为丈夫官禄，主丈夫仕途显赫","申为丈夫财库，主丈夫家境极富"],"ans":1,"exp":"官杀包住自己主有魅力、男人喜欢；丙夫星坐申上，申为丙之桃花（且带劫财象），故主丈夫外边女人多。","sec":"四、官杀包局、官局不离","t":"xiang"},{"q":"女命坤造：丙癸辛癸／寅巳酉巳（梦露），成为大众情人的原局包局与干支组合特征是？","opts":["寅巳相穿破宫，婚姻屡结屡离成名","癸水食神旺极，官杀无根反被制服","辛见癸金白水清，官包局且丙主眼睛传媒","巳酉半合金局，比劫众多争抢配偶"],"ans":2,"exp":"辛金见癸水为金白水清主美丽动人；官星包局，丙火主眼睛、传媒，男人的眼睛都盯着她，成大众情人。","sec":"四、官杀包局、官局不离","t":"xiang"},{"q":"坤造：乙己壬壬／卯丑午寅，原局丑午相穿（夫星穿夫宫），为何婚姻不会离且能嫁企业家老板？","opts":["壬水日主坐午，暗合丁火财星稳固","己土正官透干，得月令丑土通根有力","寅卯木生助午火，化解丑午相穿之害","年时食伤包住夫宫夫星，且丑为退气"],"ans":3,"exp":"虽丑午穿，但乙卯、壬寅食伤占年时包住夫宫与夫星，故不会离婚；己丑为夫，丑是水之退气，主夫大且离过婚。","sec":"四、官杀包局、官局不离","t":"calc"},{"q":"坤造：丙辛庚甲／辰卯午申，原局申与辰禄印包局包住午火夫星，而地支出现卯午相破，这在婚姻上主什么？","opts":["婚姻不会离，只主丈夫做手术或有伤灾","禄印包局无用，丈夫必有外遇抛妻","卯午相破主夫妻反目，中年必然离异","只主女命自身破财，与丈夫毫无关联"],"ans":0,"exp":"申辰禄印紧紧包住午火夫星，婚姻稳不会离；卯午相破在夫星上，只表示丈夫会做手术或有伤灾之意。","sec":"四、官杀包局、官局不离","t":"diff"},{"q":"坤造：辛庚辛戊／酉寅酉子，八字无官杀，两酉包寅木财星，如何从「寅」与「酉」看出其被人包养？","opts":["戊土正印透时，主正经婚姻嫁入豪门","寅戴劫是他人夫，以酉禄身体包财","辛金比肩透干，主与闺蜜合伙经商","子水食神生寅财，主靠才艺自主赚钱"],"ans":1,"exp":"无官杀而财包局，寅木财星上戴庚甲/庚劫象为别人的老公，日主以酉禄身体去包局包财，故被人包养。","sec":"五、财包局：被人包养的组合","t":"xiang"},{"q":"坤造：戊丁丁戊／申巳亥申，无正经婚姻而被情人包养，其中「巳」火禄神落宾位带比肩有何双重象义？","opts":["既表示正经工作，也表示偏财外快","既表示自己的父母，也表示公婆长辈","既表示自己的身体，也表示别的女人","既表示法律文书，也表示婚姻证书"],"ans":2,"exp":"巳为日主禄神，落在宾位（月支）又带比肩，既表示自己的身体，也表示别的女人（与人共夫、被包养）。","sec":"五、财包局：被人包养的组合","t":"xiang"},{"q":"坤造：庚戊丁庚／戌寅卯戌，无官杀而伤官戌带财包局，长年被人包养无正经婚姻，坐下卯偏印起何象义？","opts":["偏印主克夫夺财，男人与她必破产","偏印主远嫁异国，与家乡父母断绝","偏印主学历低下，无文化难觅正缘","偏印主做偏房，戌中丁为有家室之象"],"ans":3,"exp":"八字无官杀，伤官戌带财包局，坐下卯为偏印（偏印主做偏房），戌中有丁比劫库主对方有家室，故长年被包养。","sec":"五、财包局：被人包养的组合","t":"calc"},{"q":"坤造：丙戊甲辛／寅戌午未，无官星被未、戌两财星包局，行未运被官员包养，原局中未与戌的关系应如何看？","opts":["未与戌是不同的两个男人，皆有家室","未为正夫，戌为子女，主母凭子贵","未与戌同属土财，代表同一位男性","未为自己娘家，戌为官员之办公场所"],"ans":0,"exp":"两头未与戌象不同，是不同的两个男人；戌拱寅、未为木库，都带比劫库之象，表示包她的人都有家室。","sec":"五、财包局：被人包养的组合","t":"diff"}]},{"n":100,"level":"高级","title":"配偶情况判断（二婚、偏房、年龄差、父母反对与招婿）","qs":[{"q":"夫星前面有比劫在前争夫，按盲派怎么断？","opts":["配偶前面有过婚姻，或自己二婚","配偶比自己年龄大","自己是偏房二奶","夫妻缘薄，必定离婚"],"ans":0,"exp":"夫星前有比劫争夫（比劫在前，争在前边），断配偶前面有过婚姻或自己二婚。","sec":"一、配偶是否二婚（找二婚）","t":"rule"},{"q":"下列哪项表示配偶原是别人的？","opts":["夫宫包夫星","夫星入他人之库","夫星得正位坐夫宫","夫星坐禄，不被冲克"],"ans":1,"exp":"夫星或妻星从他宫出、夫星入他人之库，都表示配偶原是别人的。","sec":"一、配偶是否二婚（找二婚）","t":"rule"},{"q":"做偏房的典型组合是？","opts":["官杀混杂，又见正印","伤官见官，又见偏财","比劫争夫，又见偏印（枭）","比劫争夫，又见正印"],"ans":2,"exp":"比劫争夫又见偏印做偏房；正印是明媒正娶之意。","sec":"组合","t":"rule"},{"q":"女命夫宫穿到正印，怎么论？","opts":["必离婚，不论名分","明媒正娶的正妻","偏房，但必转正","只能是偏房"],"ans":3,"exp":"正印为明媒正娶，被夫宫穿到，所以只能是偏房。","sec":"组合","t":"calc"},{"q":"命中正印、枭都有，怎样论偏房转正？","opts":["破枭变印为转正","合枭入库为转正","枭印俱被比劫争为转正","破印变枭为转正"],"ans":0,"exp":"转正的关键是枭被破而变成印，即「破枭变印」。","sec":"组合","t":"rule"},{"q":"乙丑、辛丑两柱地支同为丑，辨是一个人还是两个人，看什么？","opts":["看月令，同令即同人","看天干，相克相反则为两人","看大运，换运即换人","看地支，同支即同一人"],"ans":1,"exp":"辨别一个人还是两个人，关键看天干；乙丑、辛丑天干象反，是两个人。","sec":"组合","t":"diff"},{"q":"地支的冲与合，各指示什么方向？","opts":["冲合都是去的方向","冲合都是离开的方向","冲是离开的方向，合是去的方向","冲是去的方向，合是离开的方向"],"ans":2,"exp":"地支冲合：冲是离开的方向，合是去的方向。","sec":"组合","t":"rule"},{"q":"男命妻星为亥，年上巳含比劫，巳亥冲；亥卯未三合局，妻宫稳定。妻有外情的情形？","opts":["外情长期，必离婚","妻无外情，冲为克妻","外情不断，终致丧妻","外情短暂偶尔，不会离婚"],"ans":3,"exp":"冲为短暂偶尔之意；亥卯未三合，妻宫稳定，所以妻有别的男人但不会离婚。","sec":"三、配偶有情人（配偶外情）","t":"calc"},{"q":"男命伤官比劫旺，与伤官比劫不旺，分别易找什么年龄的配偶？","opts":["旺的找小的；不旺的找大的","旺不旺都易找小的","旺不旺都易找大的","旺的找大的；不旺的找小的"],"ans":0,"exp":"口诀：男命伤官比劫旺的找小的，伤官比劫不旺找大的。","sec":"四、年龄差：嫁老夫、娶小妻","t":"diff"},{"q":"看配偶年龄：妻星一柱向年上拱，与食神妻星拱入夫宫，各主什么？","opts":["向年上拱主妻小；食神拱入主妻大","向年上拱主妻大；食神拱入主妻小","两者都主妻比自己小","两者都主妻比自己大"],"ans":1,"exp":"年主大，妻星一柱向年上拱，妻比自己大；食神主小，拱入夫宫之食神妻星，找小的。","sec":"四、年龄差：嫁老夫、娶小妻","t":"diff"},{"q":"父母反对婚姻，哪种结构终能成婚，哪种成不了？","opts":["夫宫包夫星与对象被穿，都不成","夫宫包夫星与对象被穿，都能成","夫宫包夫星能成；对象被穿被争不成","对象被穿被争能成；夫宫包夫星不成"],"ans":2,"exp":"父母反对而终能成婚：夫宫包夫星，婚姻没问题；对象被穿、被比肩争，母亲反对得逞，婚不成。","sec":"五、父母反对的婚姻","t":"diff"},{"q":"夫星落在月令，女命嫁出去仍住娘家与招婿，如何区分？","opts":["落在日柱暗合夫宫住娘家","暗合、六合都是招女婿","六合夫宫住娘家；暗合夫宫招女婿","暗合夫宫住娘家；六合夫宫招女婿"],"ans":3,"exp":"口诀：女命月令为娘家，夫星落月令、暗合夫宫者一般嫁出去依然住娘家；如是六合，一般是招女婿。","sec":"六、嫁出去住娘家与招婿入赘","t":"diff"}],"fine":[{"q":"坤造：戊甲己辛／申寅未未，甲寅为夫而戊土比劫在前争夫，断夫为二婚；原局己未库不开，为何仍断夫贵？","opts":["寅申冲在旁边开库，且原局冲好","甲己合土化气，官星转化为印星","辛金食神透时生财，自然得夫贵","未土比肩伏吟，比劫帮身担起官星"],"ans":0,"exp":"己未库原局虽不开，但寅申冲在旁边开库，故夫贵；原局冲好了大运不好也无事，冲了杀主子女多为前妻所带。","sec":"一、配偶是否二婚（找二婚）","t":"calc"},{"q":"乾造：乙壬戊壬／巳午申戌，申为妻星被年支巳合住（巳申合，原是别人之妻），要到何时妻子才正式到位？","opts":["行戌运火土燥烈，熔金克去乙官","行寅运穿去巳火，解了巳申合","行申运妻星临旺，直接夺妻归己","行午运伏吟妻宫，冲开婚姻库"],"ans":1,"exp":"巳申合表示申原是别人的妻子，行寅运寅巳穿，穿去巳火解了巳申合，对方离婚后妻到位，丁丑年丑代表申结婚。","sec":"一、配偶是否二婚（找二婚）","t":"step"},{"q":"女命做「二奶、偏房」的组合中，除比劫争夫又见偏印、夫宫穿正印外，还有哪一项典型组合？","opts":["食神制杀，又见正印透于月干","伤官配印，又见禄神坐于时支","比肩争夫，又见夫宫令偏印","官星独透，坐下日支正财生官"],"ans":2,"exp":"做偏房二奶的典型组合包括：比劫争夫又见偏印、比肩争夫又见夫宫令偏印、夫宫穿正印、比劫满盘争夫。","sec":"组合","t":"rule"},{"q":"盲派断「漂亮的二奶命」，常与以下哪一组干支十神象义对应？","opts":["食神吐秀主才华，食神生财主富贵","正官清纯主端庄，正印护身主贤淑","七杀攻身主刚烈，羊刃架杀主权威","伤官高傲主无文化，伤官合杀主漂亮"],"ans":3,"exp":"伤官高傲，无文化农村人，伤官合杀主漂亮，再逢夫宫穿正印或比劫争夫，往往成漂亮的二奶命。","sec":"组合","t":"xiang"},{"q":"坤造：己丁戊癸／未丑寅亥，坐下寅杀为夫，柱中寅亥合在婚姻名分上论为「有夫无证、非法婚姻」的依据是？","opts":["亥财合灭寅中丙枭，合财贪财而无证","未丑相冲破库，结婚证被原局冲毁","癸水正财合戊，日主合财不顾名分","寅木克制丑土，夫星克伤配偶宫位"],"ans":0,"exp":"寅从未中出为比劫，夫前有婚；寅亥合，亥财合灭寅中丙枭印，主合财贪财、灭丙无证，是有夫无证的非法婚姻。","sec":"组合","t":"calc"},{"q":"坤造：壬丁丁辛／子未卯丑，行丁丑运找远方男士仍做二奶，虽有子卯相破，为何依然被包养得财？","opts":["未丑相冲开库，财星涌入日主宫位","子丑合财库成包局，丑为钱包","辛金偏财透时，主正职收入丰厚","丁壬相合化木，印星生身得长辈助"],"ans":1,"exp":"第二个男人为辛丑，官杀退气主远方；虽有子卯破，但子丑合财库形成金水包局，丑是男人带的钱包，故被包养。","sec":"命例","t":"calc"},{"q":"坤造：丁壬丁乙／巳寅未巳，年上丁巳比肩争夫，最终能从偏房转正的关键原局机制是什么？","opts":["年时两巳伏吟，前妻主动退位让贤","未土拱合卯木，夫宫自动生旺夫星","寅巳穿使夫离前妻，乙枭入未夫宫库","丁壬五合化木，比劫被日主合化成印"],"ans":2,"exp":"寅巳穿主夫会离开那个女人回到自己身旁，且八字中乙枭入未夫宫库，是有转正之信息，庚寅年夫离婚后正式转正。","sec":"命例","t":"step"},{"q":"坤造：戊甲丁丙／申子卯午，卯申合到宫卯枭本主偏房，后来能够偏房转正的大运应期关键是什么？","opts":["癸亥运亥卯半合，印星化为官星","庚申运申金伏吟，夫星直接入宫","壬戌运戌土合卯，加强偏印之力量","见甲正印，辛酉运酉冲破偏印卯"],"ans":3,"exp":"申子合状态变化且原局见甲正印，破枭变印可转正；戌运合卯枭为偏婚，到辛酉运之酉冲破偏印卯而转正。","sec":"命例","t":"step"},{"q":"坤造：甲己庚乙／辰巳午酉，巳午都为夫是一个人，酉为比劫，原局「巳酉拱」主丈夫什么情况？","opts":["争夫之象但争不去，夫外边包养情人","比劫夺夫成功，初婚早年必离异","丈夫事业败落，靠妻比劫朋友接济","夫妻感情冷淡，各自再婚互不干涉"],"ans":0,"exp":"酉为比劫，巳酉拱是争夫之象，然夫宫稳定争不去，乙丑运巳酉丑三合，夫在外面包养情人，自己知道也无办法。","sec":"三、配偶有情人（配偶外情）","t":"calc"},{"q":"男命八字中，通常从哪一项干支配置直接看出命主本人桃花多、喜欢在外面找女人？","opts":["食神独透时干，且地支不见冲合","比劫落在年时，或地支含比劫","正官坐于日支，且年干透出偏印","正印落在月令，且日支坐正财"],"ans":1,"exp":"男人劫财主桃花；比劫在年时或地支中含比劫（如巳中有劫财），主本人桃花也多、喜欢搞女人。","sec":"三、配偶有情人（配偶外情）","t":"rule"},{"q":"乾造：辛丙辛丙／卯申巳申，辛卯运自己十年桃花、庚寅运自己桃花没了而妻子犯十年桃花，其命理机制是？","opts":["辛卯运生助巳火；庚寅运克制申金","辛卯运合入日支；庚寅运刑坏年支","辛卯为已离头妻；寅申冲破巳申合","辛卯运财星透干；庚寅运印星入墓"],"ans":2,"exp":"头妻辛卯已离，辛卯运再来是别人妻子为自己桃花；二妻申在庚寅运被寅申冲破坏巳申合，妻红杏出墙但包局不离。","sec":"三、配偶有情人（配偶外情）","t":"diff"},{"q":"乾造：甲戊癸己／辰辰卯未，日支卯为妻且原局无比肩争妻，为何仍断妻子桃花众多？","opts":["辰卯相穿破宫，妻子心性不稳外向","甲木伤官透年，妻子嫌贫爱富出轨","癸水日主坐食神，妻子贪图享乐","卯入未墓，未透己杀克日主为他男"],"ans":3,"exp":"卯虽无比肩争妻，但卯入未墓，未上透出己土七杀克日主，此杀代表别的男人，故妻子桃花众多。","sec":"三、配偶有情人（配偶外情）","t":"calc"},{"q":"乾造：丙己壬癸／午亥辰卯，丙午为妻，月支亥为比劫且内含甲桃花，原局「午亥暗合」主什么象？","opts":["妻红杏出墙有外情，暗合丈夫不知","丈夫暗中包养情人，妻子毫不知情","夫妻私下恩爱，外人看不出感情好","妻暗中补贴娘家，丈夫毫不知情"],"ans":0,"exp":"丙午为妻，午亥暗合，亥为比劫在宾位且亥中甲为桃花，主妻子红杏出墙有外情，暗合则丈夫不知。","sec":"三、配偶有情人（配偶外情）","t":"xiang"},{"q":"在盲派婚姻年龄差判断中，哪一组天干五合专门主「老少配」？","opts":["甲己合","戊癸合","乙庚合","丁壬合"],"ans":1,"exp":"口诀与断法明确指出：戊癸合为老少配，年龄差距很大；伤官也表现叛逆的婚姻，一般年龄差距较大。","sec":"四、年龄差：嫁老夫、娶小妻","t":"rule"},{"q":"女命八字中，夫星落在年柱上且原局水旺时，在配偶地域与距离上如何取象？","opts":["年上主近郊县城，水旺主配偶经商","年上主本地同乡，水旺主婚姻多变","年上主远方，水旺主六数（六千里）","年上主祖宅邻里，水旺主配偶多病"],"ans":2,"exp":"夫星在年上主远方；水旺，水主六数，故可取象远嫁六千里之外（如山东嫁到台湾）。","sec":"四、年龄差：嫁老夫、娶小妻","t":"xiang"},{"q":"坤造：壬癸辛己／寅丑亥亥，女命犯旺伤官嫁大近60岁老头，戌运不出嫁、行酉运则老头会死，对应何种应期？","opts":["戌运刑丑夫宫，酉运子丑合化水","戌运穿酉财星，酉运卯酉相冲破局","戌运入墓收官，酉运伤官见官克夫","戌运克亥不出嫁，酉运寅酉互绝"],"ans":3,"exp":"寅亥合，戌运克亥不能出嫁，过了戌运第一年癸酉年即嫁；行酉运时，夫星寅与大运酉互绝（寅酉互绝），故老头会死。","sec":"四、年龄差：嫁老夫、娶小妻","t":"step"},{"q":"乾造：丁癸癸辛／酉卯未酉，娶小20岁妻子且本人职业为公安，原局中对应「公安」职业之象的是？","opts":["卯酉相冲，酉金是法律","丁火偏财透年，丁为枪械武器","未土七杀在日，未为监狱看守","癸水比肩双透，癸为侦查暗访"],"ans":0,"exp":"食神卯主小且比劫多故娶小20岁妻；本人是公安，因原局卯酉相冲，酉是法律，冲动法律之象。","sec":"四、年龄差：嫁老夫、娶小妻","t":"xiang"},{"q":"坤造：丁戊癸甲／未申丑寅（孟广美），曾处外籍男友破财数千万，后二婚嫁离婚富翁，各对应原局何象？","opts":["未土七杀攻身破财；丁火偏财透干嫁富翁","寅入他墓财生杀破财；丑开未墓嫁富翁","申金劫财合身破财；寅申冲主嫁富翁","戊癸合化火破财；甲木伤官生财嫁富翁"],"ans":1,"exp":"寅财入他人墓、财生杀为忌倒贴成仇人故破财；寅申冲主离婚的男人，2010庚寅年丑开未墓而嫁得离婚富翁。","sec":"四、年龄差：嫁老夫、娶小妻","t":"calc"},{"q":"坤造：丁辛甲甲／巳亥午子，辛亥为对象，丁巳为女方父母反对对象，这在十神取象上依据什么规则？","opts":["女命比劫为兄，甲木透干争夺夫星","女命七杀为父，辛金克甲木表示反对","女命食神为母，丁克辛、巳冲亥反对","女命正印为母，亥水生甲木表示反对"],"ans":2,"exp":"女命食神为母，丁巳食神（丁克辛、巳冲亥）即代表女方父母反对对象；干禄比肩、戌食伤库也可看母。","sec":"五、父母反对的婚姻","t":"xiang"},{"q":"乾造：己甲丁甲／未戌卯辰，戌未均为妻却相刑，母亲喜欢未、自己喜欢戌，导致两次婚姻都离的原因是？","opts":["辰戌相冲破财库，妻子无财难持家","甲木正印透双干，母亲包办两次婚姻","卯戌六合化火，比劫争妻夺走配偶","戌未相刑自相矛盾，且未代表母亲"],"ans":3,"exp":"戌未为妻却相刑，自相矛盾：他喜欢戌母亲不喜欢，母亲喜欢未他又不喜欢（因未为母亲），故结两次婚都离。","sec":"五、父母反对的婚姻","t":"calc"},{"q":"坤造：戊乙壬辛／戌丑子丑，父母独女而招倒插门女婿，为何头夫克死、二婚仍招女婿？","opts":["乙辛丑象反两人；丑月令六合子招婿","子丑合土克水；戊土七杀透年主招婿","壬水日主坐刃；乙木伤官生财主招婿","戌丑相刑克头夫；辛金生壬水主招婿"],"ans":0,"exp":"乙丑、辛丑天干象反为两人；丑被戌刑又被乙克（阳日主见阴伤官克夫）克死头夫；二夫丑在月令六合夫宫子仍招婿。","sec":"六、嫁出去住娘家与招婿入赘","t":"calc"},{"q":"乾造：己庚乙庚／巳午丑辰，以辰为妻，如何判断命主是离开父母、入赘女方（而非从小过继爷爷家）？","opts":["己土偏财透年入赘，庚金正官透月过继","丑午穿离开父母，月令乙庚合主入赘","乙木日主坐丑入赘，辰土财库主过继","丑入辰墓入赘女家，巳午火旺主过继"],"ans":1,"exp":"月令为父母家，丑午穿主离开父母；月令乙庚合与妈妈有关联主入赘女方；若无月令乙庚合则可能从小给出去在爷爷家长大。","sec":"六、嫁出去住娘家与招婿入赘","t":"diff"}]},{"n":101,"level":"高级","title":"伤克配偶判断","qs":[{"q":"按盲派，看到命局「伤克配偶」的信息，本质是什么？","opts":["本人命硬，真正克死配偶","配偶本身命中有问题，本人只体现信息","配偶宫被大运流年冲坏所致","配偶星太弱，需印星来救"],"ans":1,"exp":"伤克配偶一定是配偶本身命中有问题，本人命中体现出伤克配偶的信息，并非真是本人克死的。","sec":"一、基本规则","t":"rule"},{"q":"水的墓、绝、死分别落在哪个地支？","opts":["墓在未，绝在巳，死在卯","墓在辰，绝在申，死在午","墓在辰，绝在巳，死在卯","墓在丑，绝在寅，死在子"],"ans":2,"exp":"死墓绝表：水墓辰、绝巳、死卯；金墓丑、绝寅、死子；木墓未、绝申、死午；火（土同）墓戌、绝亥、死酉。","sec":"死墓绝表与互绝","t":"calc"},{"q":"夫星是金（如庚、辛），哪个地支是它的墓、哪个是它的绝？","opts":["墓在未，绝在申","墓在戌，绝在亥","墓在辰，绝在巳","墓在丑，绝在寅"],"ans":3,"exp":"金墓丑、绝寅、死子，夫星为金时宫位见丑为临墓、见寅为临绝。","sec":"死墓绝表与互绝","t":"calc"},{"q":"口诀「互绝」包括下列哪四组？","opts":["寅酉、子巳、卯申、午亥","寅酉、子巳、卯午、申亥","寅申、子午、卯酉、巳亥","寅卯、子巳、申酉、午亥"],"ans":0,"exp":"口诀：寅酉互绝，子巳互绝，卯申互绝，午亥互绝。","sec":"死墓绝表与互绝","t":"rule"},{"q":"男命克妻，哪种劫财最严重？","opts":["午火劫财","申金劫财","亥水劫财","寅木劫财"],"ans":1,"exp":"男命羊刃容易克妻，劫财克妻，以申金劫财最严重。","sec":"一、基本规则","t":"rule"},{"q":"女命克夫的伤官，日主阴阳与伤官阴阳怎样配合才克？","opts":["阴日主见阳伤官克夫，阳日主见阴不克","只有阴日主见阴伤官才克夫","阳日主见阴伤官克夫，阴日主见阳不克","阴阳日主见任何伤官都克夫"],"ans":2,"exp":"阳日主见阴伤官克夫，阴日主见阳不克；阴伤官以乙卯辛酉己丁午及伤官库未丑戌最严重。","sec":"一、基本规则","t":"diff"},{"q":"女命乙木日主，天干透出丙火伤官，按此规则克夫吗？","opts":["克夫，伤官必克官","克夫，丙火最严重","不克，因为丙是食神不是伤官","不克，阴日主见阳伤官不克"],"ans":3,"exp":"阴日主见阳不克；乙日主的伤官是丙，丙为阳，阴日主见阳不克夫。","sec":"一、基本规则","t":"calc"},{"q":"女命夫星不宜临墓，「库不开」意味着什么？","opts":["库不开就是墓","库不开才能保夫星","库不开反而吉","库不开只有男命才算墓"],"ans":0,"exp":"女命夫星不宜临墓，库不开为墓，墓库需刑冲才开；夫星临墓被冲开则伤而不死。","sec":"一、基本规则","t":"rule"},{"q":"夫宫与夫星同时被坏（如宫被刑星被穿），按盲派怎么断？","opts":["宫星同坏反主婚姻稳定","必离，也可能死夫","主夫有外遇但不离","只主夫病，不离婚"],"ans":1,"exp":"夫宫与夫星同时被坏必离，也可能死夫；配偶宫、星三刑也主克。","sec":"一、基本规则","t":"rule"},{"q":"配偶星（或配偶）「墓绝同现」，主什么？","opts":["主多次婚姻，应期在合到之年","主晚婚，应期在冲开墓库之年","主死亡，应期找刑开墓库或绝地引动之年","主离婚，不主死亡"],"ans":2,"exp":"墓绝同现主死亡；应期看大运流年冲破、刑开墓库或引动绝地。","sec":"一、基本规则","t":"rule"}],"fine":[{"q":"女命阳日主见阴伤官克夫，教材指出哪一组阴伤官干支及伤官库克夫最为严重？","opts":["壬、子、癸、亥、甲、寅、乙及申子辰","乙、卯、辛、酉、己、丁、午及未丑戌","甲、寅、庚、申、戊、丙、巳及辰戌丑","丙、午、丁、巳、戊、己、庚及寅午戌"],"ans":1,"exp":"女命阳日主见阴伤官克夫，以乙、卯、辛、酉、己、丁、午及伤官库未、丑、戌最为严重；阴日主见阳伤官不克。","sec":"一、基本规则","t":"rule"},{"q":"按死墓绝表，火与土（以火论）的「绝、死、墓」分别落在哪三个地支？","opts":["绝在寅，死在子，墓在丑","绝在巳，死在卯，墓在辰","绝在亥，死在酉，墓在戌","绝在申，死在午，墓在未"],"ans":2,"exp":"死墓绝表中，火与土（以火论）同论：绝在亥，死在酉，墓在戌。","sec":"死墓绝表与互绝","t":"calc"},{"q":"按死墓绝表，木五行的「绝、死、墓」分别落在哪三个地支？","opts":["绝在巳，死在卯，墓在辰","绝在亥，死在酉，墓在戌","绝在寅，死在子，墓在丑","绝在申，死在午，墓在未"],"ans":3,"exp":"死墓绝表中，木的绝在申，死在午，墓在未（如寅木见申为绝、见午为死、见未为墓）。","sec":"死墓绝表与互绝","t":"calc"},{"q":"坤造：丙壬甲乙／午辰子亥，原局无官杀取辰为夫星，行己丑运壬午年夫先伤后自杀，其克夫机理是？","opts":["己丑运丑穿午伤夫原神，壬午年壬克丙","己丑运丑土合子，壬午年子午相冲破宫","己丑运辰丑相破，壬午年乙木伤官见官","己丑运壬水入墓，壬午年丙火焚尽亥水"],"ans":0,"exp":"夫星辰之原神在年上丙午，己丑运丑穿午使原神受伤（关财门），壬午年壬水克伐丙火为丑午穿之应期。","sec":"1. 夫星入墓、关财门","t":"step"},{"q":"坤造：丙癸癸丁／辰巳亥巳，夫星辰临墓，己丑年夫患癌病逝，且姐姐在自己结婚当天意外身亡，姐亡对应何象？","opts":["癸水比肩透干，遭己土七杀克伐","亥水墓绝同现（绝在巳，见辰墓）","丁火财星透时，与癸水日主天克地冲","丙火正财入辰墓，大运己丑刑开墓门"],"ans":1,"exp":"大运己丑坏火原神、关财门主夫亡；亥水在原局见巳为绝、见辰为墓，墓绝同现，故姐姐在结婚当天意外身亡。","sec":"1. 夫星入墓、关财门","t":"calc"},{"q":"坤造：甲辛乙己／寅未亥卯，辛未为夫，丈夫桃花多且行戊辰运庚寅年心脏病突发而亡，对应的原局组合是？","opts":["甲木劫财透年桃花多；戊土正财合癸","己土偏财透时桃花多；寅卯木旺克未","劫入未墓夫桃花多；亥卯未合木关财门","辛金七杀坐未桃花多；庚金劈甲引丁"],"ans":2,"exp":"宾位劫财入未墓主老公桃花多；亥卯未三合木局使未土立不住为关财门，戊辰运辛金杀星临墓主死亡，庚寅年病发而亡。","sec":"1. 夫星入墓、关财门","t":"calc"},{"q":"坤造：丙庚甲丁／午子寅卯，以庚子为夫、见寅卯绝而破之，行丙申运癸未年夫车祸身亡，丙与未各起何作用？","opts":["丙火生助丁火，癸未年子未穿破夫星墓","丙申暗合卯木，癸未年卯未半合化木","丙克庚金夫星，癸未年冲开午火财库","丙代表寅，癸未年合起羊刃穿倒子水"],"ans":3,"exp":"丙申运中丙代表寅（金之绝地），癸未年合起羊刃穿倒子水夫星，故夫车祸身亡；乙未运再嫁二婚夫。","sec":"2. 夫星被绝、被破、车祸","t":"step"},{"q":"坤造：壬壬戊己／寅寅子未，寅为夫星且有子水生寅，为何仍断克夫且行丁酉运辛卯年发现丈夫胃癌？","opts":["未穿倒夫宫子，酉运寅酉互绝","戊土坐子受克，辛卯年寅卯辰三会木","壬水财星过旺，辛卯年子卯相刑破宫","己土劫财透时，丁酉运丁火焚尽寅木"],"ans":0,"exp":"不喜未时，寅之墓地未穿倒夫宫子水；先行丁酉之酉运，寅酉互绝，寅官被绝，故辛卯年发现丈夫胃癌。","sec":"2. 夫星被绝、被破、车祸","t":"step"},{"q":"坤造：戊壬戊丙／午戌午辰，无官以财当老公，财到夫宫为死地，行己未运老公车祸致残却未死，原因是？","opts":["丙火偏印透时护身，化去克夫之气","夫星临墓被大运未土冲开，伤而不死","两午火包局戌土，包局主婚姻永不分离","壬水财星通根于辰，能量极旺难克死"],"ans":1,"exp":"夫宫印旺克夫、财到夫宫为死地故夫遭车祸致残；但辰中夫星临墓被大运未冲开（或原局戌辰冲），故伤而不死。","sec":"2. 夫星被绝、被破、车祸","t":"diff"},{"q":"坤造：癸癸壬庚／丑亥申戌，卯运戊子年老公脑溢血差点死，且一生没有孩子，其中「没有孩子」对应何象？","opts":["丑戌相刑破子息宫，子女星被刑伤致死","癸水劫财透年月，子息被比劫争夺殆尽","无食伤看财，财在戌库不开且空亡","申金偏印坐日支，枭神夺食必主无子"],"ans":2,"exp":"卯运卯戌合克夫戌；看孩子无食伤看财星，财在戌库中，不开库为墓且又是空亡，子息宫被坏，故没有孩子。","sec":"2. 夫星被绝、被破、车祸","t":"calc"},{"q":"坤造：乙癸丙己／卯未戌丑，夫宫逢丑未戌三刑，行丙戌运26岁庚辰年正月初五夫车祸身亡，流年「辰」代表什么？","opts":["辰代表丈夫在远方的情人","辰代表日主丙火的食神泄秀","辰代表日主父母的印星宫位","辰代表夫星癸水（夫星墓库）"],"ans":3,"exp":"夫星为癸，阳日主丙见己未阴伤官极克夫，又逢丑未戌三刑；丙戌运庚辰年，辰代表夫癸（水墓），引动夫星应灾。","sec":"3. 夫宫三刑、宫星俱损","t":"step"},{"q":"坤造：壬庚壬辛／辰戌寅丑，寅为夫宫、丑为夫星，乙巳运壬午年夫自杀身亡，其「宫星俱坏」的路径是？","opts":["乙巳运刑穿坏夫宫寅，午穿坏夫星丑","壬水比肩夺夫，庚金枭神入丑墓不开","辰戌相冲破印库，寅丑暗合消耗夫星","乙木合去庚金印星，壬水冲克丙火财星"],"ans":0,"exp":"乙巳伤官运刑坏夫宫且巳穿倒夫宫寅，流年壬午之午又穿坏夫星丑，夫宫与夫星同时被坏，故夫自杀。","sec":"3. 夫宫三刑、宫星俱损","t":"step"},{"q":"坤造：壬丙壬癸／子午申卯，丙午为夫且夫宫包夫星，唯不喜卯午相破，行卯运己卯年丈夫应何灾？","opts":["夫外遇败家，夫妻从此分居永不相见","不离婚，丈夫车祸受重伤（家养数载）","夫妻反目，当年立即办理离婚手续","夫星入绝地，丈夫当年车祸身亡"],"ans":1,"exp":"夫宫包夫星婚姻稳不会离，但卯午破在夫星上，行卯运己卯年卯午破应期，主丈夫车祸受重伤，壬寅运好起来。","sec":"3. 夫宫三刑、宫星俱损","t":"diff"},{"q":"坤造：乙丁乙己／未亥丑卯（慈禧），原局亥卯未三合木局克夫宫丑土，庚寅运27岁辛酉年咸丰帝亡，其应期机理是？","opts":["丁火食神透月干，辛酉年酉丑半合金局","寅亥六合化木，辛酉年引发丑未相冲","辛酉为夫星再现，行庚寅运夫星入绝地","庚金正官合乙木，辛酉年冲破卯木禄神"],"ans":2,"exp":"原局三合木局克丑土夫宫，本是克夫之命；庚寅运为金之绝地，辛酉年夫星再现且走到绝地，即为克夫应期。","sec":"3. 夫宫三刑、宫星俱损","t":"step"},{"q":"坤造：丁辛戊辛／卯亥辰酉，同是天干「辛」字，为何说「辛酉的辛克夫，辛亥的辛不克」？","opts":["辛酉与戊土同旬；辛亥与丁火相合","辛酉为阳伤官；辛亥为阴食神","辛酉在时柱宾位；辛亥在月柱主位","辛酉阴伤官坐酉阴支力大；辛亥坐亥稍缓"],"ans":3,"exp":"阳日主戊见阴伤官乙卯辛酉己丁午及伤官库最严重；辛酉干支皆阴伤官落主位旁边克夫极重，而辛亥之辛不克。","sec":"3. 夫宫三刑、宫星俱损","t":"diff"},{"q":"坤造：癸己戊甲／丑未午寅，戊日主八字无酉伤官，却见丑伤官库，其克夫力量与见酉伤官相比如何？","opts":["丑伤官库比酉伤夫之力更大，且丑午穿","丑为湿土力量弱，比见酉伤官克夫轻","丑只克情人，对正夫甲寅毫无影响","丑未相冲可解救，故完全不克丈夫"],"ans":0,"exp":"戊日主以酉为伤官，无酉而见伤官之库丑，丑比酉伤夫之力更大，且丑午穿伤夫宫，己未夫墓合入夫宫亦主克夫。","sec":"3. 夫宫三刑、宫星俱损","t":"diff"},{"q":"坤造：庚戊甲乙／子寅子丑（钟楚红），庚子为夫、丑为庚墓，甲戌运能结婚，为何癸酉运乙酉年夫病、丙戌年死？","opts":["戊土偏财透月干，丙戌年戊土克尽子水","夫宫合夫墓，癸酉运引动丑且戌坏丑","乙木劫财合庚金，癸酉运乙木被金克绝","甲木日主坐子水，癸酉运子酉破伤身"],"ans":1,"exp":"夫宫子合了夫星之墓丑（夫寿有损），甲戌运丑被戌刑开能结婚；癸酉运引动丑，墓绝同现主死亡，丙戌年死。","sec":"3. 夫宫三刑、宫星俱损","t":"step"},{"q":"乾造：乙庚壬庚／未辰子戌，无明财以年上乙木伤官为妻，为何头婚不得到头且妻病死？","opts":["庚金枭神双透，夺去食神使妻无寿","壬水日主坐子刃，直接冲克午火暗财","乙庚被克合，乙根未入辰墓又被子穿","辰戌相冲破妻宫，妻星无立足之地"],"ans":2,"exp":"乙木妻星被庚克合，乙之根未入辰墓，未又被妻宫子水穿倒，妻星克墓两伤主死亡，故第一任妻子子运病死。","sec":"三、男命克妻命例","t":"calc"},{"q":"乾造：辛丙辛壬／丑申卯辰，卯为妻被申金合绝（卯申互绝），为何巳运无事，到35岁乙亥年死妻且同年又娶妻？","opts":["巳运生辰土，乙亥年辰亥相穿破妻宫","巳运刑申金，乙亥年寅亥合解救卯木","巳运克丙火，乙亥年壬水克丙火得财","巳运绊申，乙亥年冲巳放申克卯且妻星到"],"ans":3,"exp":"巳运合申，申被绊无力克卯；乙亥年亥冲去巳火放开申金克死卯木，同时乙亥流年妻星又到位，故同年死妻又娶妻。","sec":"三、男命克妻命例","t":"step"},{"q":"乾造：庚己丁癸／寅丑卯卯，庚为妻见寅为绝、见丑为墓（墓绝同现），45岁甲戌年妻被情人杀害的应期机制是？","opts":["甲运合去妻依托之己，甲戌年刑开丑墓","甲运冲克庚金妻星，甲戌年寅戌拱火","甲运穿倒丑土墓库，甲戌年癸水透干","甲运生旺丁火日主，甲戌年卯戌合火克金"],"ans":0,"exp":"甲运合去妻星庚金依托的原神己土，甲戌年甲又到且戌刑开丑墓为应期（寅丑暗合含丙劫财，主妻有情人）。","sec":"三、男命克妻命例","t":"step"},{"q":"乾造：丙壬癸丙／申辰亥辰，以亥中甲木为妻而不以丙财为妻，行酉运丁亥年妻病死的机理是？","opts":["丙火虚透无根；酉运酉亥相穿破妻宫","丙被壬劫；亥入两头辰墓，酉运合闭墓门","丙火入戌绝地；酉运辰酉合化金克木","丙火被癸水克；酉运申酉戌三会金局"],"ans":1,"exp":"丙被壬劫不主妻，以亥中甲为妻；亥入两头辰墓不开，酉运辰酉合闭墓门（两个夹板夹紧），丁亥年妻到而病死。","sec":"三、男命克妻命例","t":"calc"},{"q":"乾造：己丙庚壬／丑寅午午，以寅木为妻、坐下午为木之死地且无原神，行酉运乙亥年死妻的应期组合是？","opts":["庚金日主坐午受克，乙亥年乙庚合化金","酉金冲克卯木暗妻，乙亥年寅亥相破","寅酉互绝应酉运，乙亥年合动寅木引动","酉丑半合金克木，乙亥年亥午暗合熄火"],"ans":2,"exp":"寅见午死又无原神（只泄无生），行酉运为寅酉互绝，乙亥年合动寅木为引动应期，故于酉运乙亥年死妻。","sec":"三、男命克妻命例","t":"step"}]},{"n":102,"level":"高级","title":"独身组合四型","qs":[{"q":"独身命的共同点是什么？","opts":["大运先天不见财官","日主先天无根无气","夫妻宫先天有毛病","夫妻星先天被冲克尽"],"ans":2,"exp":"独身命的共同点是夫妻宫先天有毛病；盲派把它归为四种宫位类型。","sec":"二、夫妻宫的四种先天毛病","t":"rule"},{"q":"夫妻宫与子女宫占比劫禄神、夫妻星不易进入，现实表现通常是？","opts":["一生没有任何异性伙伴，纯属独身","婚后丈夫早亡，此后一直守寡","结婚后夫妻长期分居两地生活","男朋友都是有家室的"],"ans":3,"exp":"这型主位占印劫禄，夫妻星进不来；官星虽有但坐比劫地、与劫财合，是别人的男人，有男友但不结婚。","sec":"二、夫妻宫的四种先天毛病","t":"rule"},{"q":"夫妻宫落制夫妻星之星，但制之不成，结果是？","opts":["夫妻星反坏夫妻宫，宫星相破","夫妻星入墓，墓不开而无法出来","正星得位天地合，偏星旺相来干挠","夫妻星被比劫夺去，宫内无星可用"],"ans":0,"exp":"宫欲制星而星强，反把夫妻宫坏掉，宫星相破，因此独身。","sec":"二、夫妻宫的四种先天毛病","t":"calc"},{"q":"夫妻宫落夫妻星之墓，并无刑冲克破，仍易独身，原因是？","opts":["偏星旺相，干挠正星","墓不开，财官入墓出不来","宫星相破，星反坏宫","比劫争夫，夫星被夺"],"ans":1,"exp":"夫妻宫占夫妻星之墓，墓不开则财官入墓不出，要开库之运才有婚。","sec":"二、夫妻宫的四种先天毛病","t":"calc"},{"q":"「水中捞月」型独身的结构是？","opts":["宫占比劫禄神，夫妻星难以进入宫内","宫制星不成，星强反坏夫妻宫位","宫坐正星且天地合，偏星旺相干挠","宫坐偏星，正星入墓而不得开库"],"ans":2,"exp":"夫妻宫坐夫妻正星且天地相合，本人有理想配偶，但命局偏星旺相干挠，遇到的总不如意，只能单身。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"rule"},{"q":"妻星卯木入未墓，未墓不开，哪个大运才可能开库成婚？","opts":["酉运，酉卯冲开卯木","辰运，辰未相逢开库","午运，午未合开未库","戌运，戌未刑开未库"],"ans":3,"exp":"墓不开的独身命要行刑冲开库之运：未库逢戌刑开；午未是合，合不开库。","sec":"五、第三型：宫占星之墓，墓不开","t":"calc"},{"q":"女命官星坐比劫地，又与劫财相合，婚姻怎么断？","opts":["有男友，但一生不会结婚","早婚而离，再婚稳定","晚婚且长久稳定","有婚姻，丈夫多有外情"],"ans":0,"exp":"官星坐比劫地又合劫财，是别人的男人：有男朋友，但一生不结婚。","sec":"三、第一型：主位占比劫印禄","t":"calc"},{"q":"「水中捞月」型独身，运上有没有解除的办法？","opts":["行刑冲开库之运，墓开则有婚缘","一般无解，理想主义使然","行去掉伤官之运，工作强而得婚缘","官星落夫宫位之运，可有短暂婚缘"],"ans":1,"exp":"这型是理想主义加偏星干挠，章末归纳为一般无解；开库之运属第三型，官星落宫运属第一型。","sec":"七、本章小结","t":"rule"}],"fine":[{"q":"盲派将「独身命」在现实生活中的表现归纳为哪三种具体情况？","opts":["只谈恋爱、同居不育、多婚终孤","早婚丧偶、晚婚独居、出家修行","纯独身无伴、有伴不婚、短婚后独身","无性婚姻、异地分居、终身未嫁"],"ans":2,"exp":"独身有三种情况：一生独身且没有性伙伴；有性伙伴但一生不结婚；有过短暂婚史但最后独身过一生。","sec":"一、独身的三种情况","t":"rule"},{"q":"在独身组合四型的十神类象附注中，哪两个十神在女命六亲中都可代表「婆婆」？","opts":["偏财与七杀","比肩与劫财","正印与食神","枭神与伤官"],"ans":3,"exp":"附注明确指出：枭、伤官都为婆婆（印为夫之母或伤官为夫之财星原神等取象）。","sec":"二、夫妻宫的四种先天毛病","t":"xiang"},{"q":"坤造：甲壬戊己／辰申午未，著名芭蕾舞演员一生独身，「有男朋友，但一生不会结婚」的原局原因在于？","opts":["官星坐比劫地，又甲己合到比劫","壬水偏财透干，日主贪财而不顾官","午未相合化土，官星被合化成比劫","申辰拱水为财，财星泄尽官星之气"],"ans":0,"exp":"年日时比劫重重，官星甲虽有，但坐比劫地又甲己合到比劫（别人的男人），故有男朋友但一生不结婚。","sec":"三、第一型：主位占比劫印禄","t":"calc"},{"q":"坤造：丁丙癸壬／未午酉子，夫宫坐偏印酉、时柱占禄子，为何己酉运能结婚、庚戌运却闹离婚并从此独身？","opts":["丙火合辛金成婚；戌运辰戌冲开墓库","年有财己酉官临宫；戌运午戌穿倒宫","丁壬合木生官；戌运酉戌相害伤印星","未土合午火成婚；戌运子戌相刑破禄"],"ans":1,"exp":"年上有财星故有婚姻象，己酉运官星落夫宫能结婚；庚戌运午戌结党穿倒夫妻宫酉而离婚，此后主位偏印占禄独身。","sec":"三、第一型：主位占比劫印禄","t":"step"},{"q":"乾造：丙丙庚乙／申申午酉，属于主位占比劫印禄的独身第一型，其「有劫无妻、光棍一个」的原局结构是？","opts":["申酉金局过旺，午火妻宫被水冲破","午火正官坐日支，丙火双透克死庚金","两丙配劫财，乙庚合且乙木被化掉","乙木正财坐酉绝地，申金合酉夺财"],"ans":2,"exp":"妻宫午火为官，副妻宫两丙透配申金劫财，时干乙木正财与日主乙庚合但乙被化掉，故有劫无妻成光棍。","sec":"三、第一型：主位占比劫印禄","t":"calc"},{"q":"坤造：辛辛戊丁／亥卯午巳，主位见印禄（午巳），乙亥丙子年结婚，为何行至乙运头一年辛巳年离婚并倾向独身？","opts":["丁火枭神夺食，辛巳年巳午未会火局","辛金伤官透干，辛巳年乙辛冲克官星","亥卯半合木局，辛巳年巳卯相穿破宫","卯破宫必离，辛巳年冲亥关财门"],"ans":3,"exp":"卯为夫破宫位必离，主位见印禄为离婚后独身组合；乙运头一年辛巳年冲亥，关财门，应期离婚。","sec":"三、第一型：主位占比劫印禄","t":"step"},{"q":"坤造：甲丙己己／午寅亥巳，夫宫亥之夫星得正位，为何壬戌运离婚后独身不再婚？","opts":["巳亥冲、寅亥合把夫合没，时见比印","寅巳相穿坏夫星，壬水财星入戌墓","午亥暗合泄夫气，丙火印星克伤水","甲己合土化比劫，夫星化入他宫"],"ans":0,"exp":"夫星得正位不喜他星合，原局巳亥冲、寅亥合把老公合没了；壬戌运离婚，时柱己巳见比印，故离婚后独身。","sec":"三、第一型：主位占比劫印禄","t":"calc"},{"q":"乾造：丁癸丁辛／亥丑未亥，以丑中辛为妻星，妻宫未冲丑欲制妻星，结果为何不仅光棍且一生穷困潦倒？","opts":["丁火日主通根未库，被癸水直接冲灭","金水有势反坏主位未体，做功体受损","辛金偏财透时干，被癸水七杀泄尽","亥水正官伏吟年时，官杀攻身无印化"],"ans":1,"exp":"妻宫未欲制丑，但金水有势反将主位做功的体（未库）冲坏，星反坏宫故独身，且做功之体受损而穷困潦倒。","sec":"四、第二型：宫制星不成，星坏宫","t":"calc"},{"q":"坤造：丁壬庚壬／未寅子午，同属夫宫子水伤官欲制夫星午火却被反坏而单身，为何工作能力极强（注册会计师）？","opts":["未土正印生庚金，印星护身主高学历","寅午半合火局生土，官印相生主显贵","局中子水伤官可去，去之论吉","壬水食神双透泄秀，才华横溢得高薪"],"ans":2,"exp":"虽然夫宫子水被坏（且未穿子主相貌不佳、单身未谈对象），但命局子水伤官本是可去之病，去之论吉故事业能力极强。","sec":"四、第二型：宫制星不成，星坏宫","t":"diff"},{"q":"乾造：壬戊辛丙／子申未申，坐下未土为财库，命局不见明财以食伤为妻，为何仍与妻无缘成光棍？","opts":["申金劫财重重伏吟，妻星一现即被劫","丙火正官合辛金日主，官星束缚无自由","戊土正印透月干，克制壬水食神妻星","未库不开且大运晚开，食神子又穿未"],"ans":3,"exp":"妻宫未为财库但库不开，大运55岁才开库；以食伤为妻却见食神子水穿妻宫未，无一字做有用功，故光棍。","sec":"四、第二型：宫制星不成，星坏宫","t":"calc"},{"q":"坤造：辛辛丙甲／卯丑辰午，财官入墓不开成老姑娘，为何盲师断她「六十三岁后才可能结婚」？","opts":["两财星俱墓于丑，63岁未运冲开丑库","夫宫辰土临水墓，63岁戌运冲开辰库","卯木正印穿辰土，63岁酉运冲破卯木","午火羊刃合未土，63岁子运冲开午火"],"ans":0,"exp":"夫宫辰临夫星墓不开，财星辛两现当夫看又俱墓于丑库（丑关财门），须行刑冲开库运，至63岁未运方冲开丑库。","sec":"五、第三型：宫占星之墓，墓不开","t":"step"},{"q":"坤造：辛辛丙甲／卯丑辰午一生未婚，若只看日柱「丙辰」而不看月柱丑库与双辛，其婚姻本该怎么论？","opts":["单纯丙辰日必主早婚后克夫再嫁","单纯丙辰日是有婚姻的","单纯丙辰日依然是终身独身之命","单纯丙辰日主水中捞月理想主义"],"ans":1,"exp":"单纯的丙辰日有婚姻的，此造无婚是因为财星两现俱入丑库不开、丑关财门且官星退气，非丙辰日主自身之过。","sec":"五、第三型：宫占星之墓，墓不开","t":"diff"},{"q":"坤造：甲戊丁甲／辰辰未辰，属宫占星墓不开的第三型，为何她一直未婚却「在外处情人、情人很多」？","opts":["戊土伤官透月干，伤官旺主风流多情","未土食神落日支，食神生财主感情丰富","夫宫未入他宫辰墓不开，辰多且癸暗","甲木正印透年时，印星多主异性缘旺"],"ans":2,"exp":"夫宫未入于他宫辰墓，辰为官杀墓不开，表示配偶隐蔽不能公开；辰多且辰中癸水男人都是暗的，故未婚而情人多。","sec":"五、第三型：宫占星之墓，墓不开","t":"calc"},{"q":"乾造：甲丙己戊／辰子未辰，教授至今未婚且对女性没有感觉，其原局妻宫与妻星的阻碍关系是？","opts":["辰土为妻，妻宫未与辰比和却无关联","戊土为妻，戊土透时与日主隔柱不相合","甲木为妻，甲木高贵生印不入妻宫","子水为妻，妻宫坐未穿子，妻进不了门"],"ans":3,"exp":"原局子水为老婆，然妻宫坐未穿子，宫星不开又相穿，妻进不了门，故至今未婚且对女性没有感觉。","sec":"五、第三型：宫占星之墓，墓不开","t":"calc"},{"q":"坤造：乙辛辛癸／巳巳未巳，原局官星巳火旺而包局并生到夫宫未土，为何近50岁仍一直未婚且无情人？","opts":["妻宫未是财之墓不开，夫宫关了财门","乙木偏财透年干，远在年柱无法合身","辛金比肩伏吟月日，比劫争夫夺走配偶","癸水食神透时干，克制巳火正官太过"],"ans":0,"exp":"官星虽旺而包局生到夫宫，但妻宫未是财之墓不开（夫宫关了财门），故没有婚姻，可能戌运刑开会有。","sec":"五、第三型：宫占星之墓，墓不开","t":"calc"},{"q":"乾造：辛庚己癸／卯子亥酉，日主坐下亥水正财得正位且天地自合，为何不仅没结过婚连女友也没有？","opts":["庚金伤官透月干，克合乙木使婚姻破败","坐正星天地合有理想配偶，偏星子干挠","酉金食神在时支，子酉相破损及妻宫","卯木七杀在年支，克制己土使日主胆怯"],"ans":1,"exp":"己亥天地相合坐正财，表示有理想配偶；但命局偏财子水等旺相干挠，遇到的总不如意，过分理想主义而单身。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"calc"},{"q":"坤造：辛庚己壬／丑子亥申，夫宫亥水藏正官且与己土天地相合，为何至今独居未婚？","opts":["庚金伤官透月干，克制亥中甲木正官","申金伤官在时支，申亥相穿破损夫宫","子水偏星得令干挠，且子丑合副夫宫","辛金食神透年干，泄耗日主无力担夫"],"ans":2,"exp":"夫宫亥中藏正官与日主天地合，又有子水财星得令为干挠星，且子丑合到副夫宫，构成水中捞月组合而独身。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"calc"},{"q":"坤造：己丙壬己／丑寅午酉，夫宫午火坐正财正官且天地相合，本该有好婚姻，为何已过花甲从未结婚？","opts":["酉金正印在时支，印星过旺泄尽夫气","寅午半合化火，夫星化为忌神烧身","己土正官双透干，官杀混杂不知所从","丑午穿坏夫宫，且透偏财丙为午之偏星"],"ans":3,"exp":"一是丑午穿坏了夫宫正星，二是透干偏财丙火正是夫宫正财午的偏星，与偏官透出干挠相当，故一生无婚。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"calc"},{"q":"坤造：戊乙己癸／寅卯亥酉，七十多岁一生未婚（水中捞月型），为何五十一岁那年却要了个女儿？","opts":["子女宫酉逢食神，戊合癸下酉生夫宫","寅亥六合化木局，木气透出化为食伤","乙木七杀在月干，杀星生印转为子女","己土坐亥有暗胎，中年大运生助子女星"],"ans":0,"exp":"命中子女宫酉逢食神，大运来了应期；戊是别人、远方，合癸下酉生夫宫，故主别人的孩子（抱养/要了个女儿）。","sec":"六、第四型：正星得位而偏星干挠（水中捞月）","t":"calc"},{"q":"对比独身四型的解除条件：第一型与第三型若在运上出现短暂婚缘，大运机制有何本质区别？","opts":["一型刑冲开库有婚；三型官落夫宫运有婚","一型官落夫宫运有婚；三型刑冲开库有婚","一型与三型均须行比劫禄神之运方有婚","一型去伤官之运有婚；三型合财之运有婚"],"ans":1,"exp":"第一型（主位占比劫印禄）在官星落夫宫位的运有婚；第三型（宫占星墓不开）须行刑冲开库之运（未运、戌运）方有婚。","sec":"七、本章小结","t":"diff"}]},{"n":103,"level":"高级","title":"差婚姻与好婚姻组合","qs":[{"q":"「差婚姻」（不离但差）的共同点，哪项对？","opts":["宫星全无关联，只靠大运维系不散","宫星入墓不开，但有大运冲开才不离","宫星被冲坏，但有合神救护而不离","宫星不坏或被包住，但有穿破隔阂"],"ans":3,"exp":"差婚姻宫星并未被坏（或被包住），所以不离；但存在穿、破、印食伤的隔阂，所以不好。","sec":"一、差婚姻（不离但差）","t":"diff"},{"q":"夫妻宫与夫星有穿、破、刑，但夫星被包局、合住而不坏，怎么断？","opts":["吵闹不和，但不离婚","必离婚，穿破主夫妻分离","无婚姻，宫星相破不能成婚","不吵不闹，穿破反主婚姻美满"],"ans":0,"exp":"差婚姻断法：有穿、破、刑则吵、不和；但宫星被包住、合住、不坏，所以不离。","sec":"一、差婚姻（不离但差）","t":"calc"},{"q":"看似有穿、冲、克、二夫二妻之象，被什么化解时婚姻反而很好？","opts":["大运比劫帮身而解","包局、连体、一气所化解","食伤泄秀制官而解","印星化解官杀而解"],"ans":1,"exp":"总纲：看似有穿冲克、二夫二妻之象，但被包局、连体、一气所化解，则婚姻很好。","sec":"二、好婚姻（易看错的组合）","t":"rule"},{"q":"夫宫为未，丁火杀星与巳火官星都与夫宫有关，且巳透乙与丁相连成连体，怎么看？","opts":["是两个夫，主二婚","要看大运才能分一人二人","连体是一个人，一婚到头","一个是夫，一个是情人"],"ans":2,"exp":"连体不以两个人看：丁乙巳连在一起是一个人，所以不是二婚，也无桃花。","sec":"2. 看似二妻（夫）实为一人","t":"calc"},{"q":"男命财星多、比劫弱，能不能断多婚、桃花多？","opts":["能，财多比劫弱更招桃花","能，财多主多妻多婚","不能，因为财星必受制","不能，比劫弱无精力兴趣"],"ans":3,"exp":"男命桃花或多婚一般要比劫旺才行；比劫弱则没有精力与兴趣找桃花，财多不等于多婚。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"rule"},{"q":"妻宫穿局中的桃花星，意味着什么？","opts":["反过来排拆桃花，无桃花婚姻好","妻宫被破，终将离婚收场","桃花更旺，婚姻多有波折","桃花入墓，晚年才得发作"],"ans":0,"exp":"妻宫穿桃花星就是反过来排拆的意思，所以从无桃花与情人，婚姻非常好。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"rule"},{"q":"男命八字既无财星、又无食伤星，以什么当妻？","opts":["以印星当妻，印星即配偶","以妻宫当妻，看宫的象","以比劫当妻，比劫即配偶","以官杀当妻，官杀即配偶"],"ans":1,"exp":"既无财也无食伤时，以妻宫为妻，看宫字本身的象。","sec":"4. 无财无食伤，以妻宫为妻","t":"rule"}],"fine":[{"q":"学过差婚姻、多婚、伤克组合后，命理判断最容易出现的误判是什么？核心应对方法在于？","opts":["易把偏房看成正妻，重点在看地支合","易把克配偶看成离婚，重点在看大运","易把独身看成晚婚，重点在看子息宫","易把好婚姻看成差的多的，重点在甄别"],"ans":3,"exp":"学过差婚姻、多婚、伤克之后，特别容易把本来好的婚姻看成差的、多的，核心在于甄别包局、连体、一气等化解。","sec":"差婚姻与好婚姻组合","t":"diff"},{"q":"乾造：乙庚丁癸／酉辰未卯，妻星庚辰加乙酉，卯辰穿主夫妻不和，为何丙子、乙亥运二十年无夫妻生活、甲戌运常找小姐？","opts":["子亥运金生水灭火；戌运卯戌合娱乐地","子亥运水冲妻宫；戌运辰戌相冲开财库","子亥运官杀攻身；戌运丁火入墓失精力","子亥运木枯火熄；戌运乙庚合化为劫财"],"ans":0,"exp":"丙子、乙亥运金生水灭了丁火，二十年无夫妻生活；甲戌运卯戌合到娱乐场所，且戌为自己比劫旺地，故常找小姐。","sec":"一、差婚姻（不离但差）","t":"step"},{"q":"坤造：辛癸戊乙／卯巳午卯，夫星卯成包局而卯午破主吵架骂人，为何年时两卯（辛卯、乙卯）不构成反局离婚？","opts":["巳火印星通关，化解了卯午相破之害","辛卯上下不生不是反局，包局不能离","辛乙天干相生，故两卯视为同一人","戊土坐午得刃，日主强旺能担起夫星"],"ans":1,"exp":"辛卯上下不生，不是反局；夫星卯形成包局，所以虽然卯午破主吵架、破口大骂、夫对她不好，却不能离婚。","sec":"一、差婚姻（不离但差）","t":"diff"},{"q":"坤造：癸乙庚戊／丑丑戌子，戌为夫被双丑刑本有离婚象，为何婚不会离且自己还能通过丈夫赚钱？","opts":["戊癸合化火生戌，夫妻利益深度绑定","乙庚合金助身强，能从丈夫手中分财","子丑合包住戌不离；丑戌刑制杀当财","丑土正印生庚金，夫宫受生得夫家财"],"ans":2,"exp":"子丑合将戌紧紧包在里面，所以不离；丑中藏辛主夫外边女人多，而丑戌刑制杀当财，故她通过丈夫赚钱。","sec":"一、差婚姻（不离但差）","t":"calc"},{"q":"坤造：己癸乙壬／酉酉卯午，命中两七杀，为何癸酉为丈夫、己酉为情人，且丑运穿主位食神后婚姻变差？","opts":["己土偏财坐酉库，丑运酉丑半合夺夫","乙木坐卯禄神旺，丑运午丑相穿伤禄","癸水偏印合乙木，丑运子丑合绊夫星","己癸天干不同为两人，丑代表酉穿食神"],"ans":3,"exp":"己酉与癸酉天干不同不是一人，癸水为结婚证故癸酉为夫、己酉为情人；丑运丑代表酉穿主位食神，思想无法沟通。","sec":"一、差婚姻（不离但差）","t":"calc"},{"q":"在差婚姻的四步断法中，若大运使「印、食伤隔断」或「杀到绝地」，在现实婚姻关系上通常表现为什么？","opts":["思想无法沟通，关系渐远但凑合不离","配偶突遭横祸，婚姻因丧偶而终结","夫妻立即反目，当年办理离婚手续","感情迅速升温，打破原局穿破隔阂"],"ans":0,"exp":"差婚姻原局宫星被包住合住不离，大运使印食伤隔断、杀到绝地时，主夫妻思想无法沟通、关系越来越远但仍不离。","sec":"一、差婚姻（不离但差）","t":"rule"},{"q":"乾造：甲壬丙庚／寅申午寅，以申为妻，夫妻宫午火与申相克本不吉，为何反而断为好婚姻？","opts":["壬水七杀制丙火，保护申金免受火克","妻宫延伸两寅成包局，宫包星且印为家","庚金偏财透时干，通根申金得位有力","甲木偏印透年干，木火相生化解金火战"],"ans":1,"exp":"夫妻宫午虽克申，然妻宫延伸出两寅形成包局，宫将星包在里边，印包局为结婚证、家，反成好婚姻。","sec":"1. 宫星相克但被包住","t":"calc"},{"q":"乾造：甲壬丙庚／寅申午寅，时干透庚与月支申金如何看？且妻子在银行工作对应原局哪一象？","opts":["庚为情人申为妻；甲木生火主银行工作","庚申为两个人看；午申相克主银行工作","庚申当一人看；寅申冲之象主银行工作","庚为女儿申为妻；丙火照耀主银行工作"],"ans":2,"exp":"时透庚与申金当一个人看（壬杀当财看，申为妻）；原局寅申冲之象，主妻子在银行工作，自己做老板。","sec":"1. 宫星相克但被包住","t":"xiang"},{"q":"坤造：甲庚癸乙／寅午巳卯，巳为夫宫之夫星，又见午火，看似两个男人，为何实际婚姻感情很好、无任何问题？","opts":["寅午半合化火局，官杀混杂化为正官","庚金正印透月干，合乙木化解比劫争","癸水日主坐巳火，财官自合不受他扰","甲寅、乙卯包局，巳午相连被包为一人"],"ans":3,"exp":"虽见巳又见午看似两个男人，然出现甲寅、乙卯包局，巳午相连被包在里边，是一个人，婚姻感情很好。","sec":"1. 宫星相克但被包住","t":"calc"},{"q":"乾造：癸甲甲己／未子子巳，子为妻宫、未为夫（妻）星，子未相穿本有离婚之象，为何婚姻没问题？","opts":["己未一象，己透时干合日主甲成包局","巳火食神在时支，火土相生扶起未土","两子水伏吟月日，穿力分散无法伤未","癸水正印透年干，水土相克化解子未穿"],"ans":0,"exp":"己、未一个象，子未穿本有离婚象，然己代表未透到时上合到自己（甲己合），形成包局，故婚姻没问题。","sec":"1. 宫星相克但被包住","t":"calc"},{"q":"坤造：丁乙辛辛／未巳未卯，未为夫宫，丁乙巳连体为一个夫星，此外「未为印星、丁为家与书笔」对应什么职业？","opts":["企业高管老板","中学语文教师","影视表演演员","银行会计出纳"],"ans":1,"exp":"丁乙巳连体为一个夫星，一婚到头无桃花；未为印星，丁为家、为书笔，故命主是中学语文教师，老公生意人。","sec":"2. 看似二妻（夫）实为一人","t":"xiang"},{"q":"乾造：壬庚壬癸／寅戌辰卯，亿万富翁兼官员，实为「婚姻很好，一次婚姻」的原局依据是？","opts":["壬水比肩双透干，比劫分财得妻家助力","癸水劫财坐卯木，劫财合财化解多婚象","寅戌拱妻是一人，辰戌冲关联且卯辰穿","庚金偏印透月干，保护日主不被财星耗"],"ans":2,"exp":"寅戌相拱为妻星是一个人，辰戌冲发生关联，时见癸卯因卯辰相穿排斥桃花之意，故婚姻很好、一次婚姻。","sec":"2. 看似二妻（夫）实为一人","t":"calc"},{"q":"坤造：壬癸丙戊／辰卯辰子，丙日主、辰为夫宫，见官杀杂透看似有婚姻问题，为何实为好婚姻？","opts":["戊癸五合化火，官杀被食神合化助身","卯木正印生丙火，印星通关官杀生身","壬水七杀透年干，远在宾位不入夫宫","癸卯一人卯辰穿排异性，子辰一家"],"ans":3,"exp":"癸卯一个人，卯辰穿排斥婚姻异性；子时官星与辰一家，一个人看，故非官杀杂乱多婚，实际婚姻很好。","sec":"2. 看似二妻（夫）实为一人","t":"calc"},{"q":"坤造：壬癸丙戊／辰卯辰子，任县长且婚姻很好，「晚婚、对象在远方，且婚后立不住孩子、孩子晚」的原因在于？","opts":["辰为孩子，原局卯辰穿导致孩子晚","戊土食神透时干，被癸水合去无子息","子水正官落时支，子卯相刑伤及子女宫","丙火日主坐辰墓，子女星入墓难以出头"],"ans":0,"exp":"28、29岁结婚，对象在远方；辰为孩子，因原局卯辰穿（辰旺穿了卯印），导致立不住孩子、孩子晚。","sec":"2. 看似二妻（夫）实为一人","t":"calc"},{"q":"乾造：丙癸癸戊／午巳巳午，满盘财星易误判为多婚或外遇，实则婚姻很好且受妻管束，原局关键机制是？","opts":["癸水日主坐巳绝地，自身无力克制财星","比劫弱无精力找桃花，戊癸合官统财","巳午火旺极从财，财星纯粹专一不杂","丙火正财透年干，远居年上不与日主合"],"ans":1,"exp":"男命桃花多婚须比劫旺，此造比劫弱无精力与兴趣找桃花；且戊癸合，官管自己、官统财，受妻管束而婚姻很好。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"calc"},{"q":"乾造：己丙庚己／亥寅辰卯，辰为妻宫、亥为妻星（寅亥合一家），时支卯本有桃花之意，为何从未有过桃花与情人？","opts":["庚金日主坐辰印，印星护身克制桃花欲","寅卯半会木局，桃花被寅木合入正妻宫","卯辰相穿，妻宫穿桃花星反排斥桃花","己土正印双透干，日主守礼自律不越轨"],"ans":2,"exp":"时柱坐卯虽有桃花之意，然日支妻宫辰与卯构成卯辰相穿，妻宫穿桃花星就是反过来排斥的意思，故无桃花。","sec":"3. 财多不等于多婚、桃花被穿即无桃花","t":"calc"},{"q":"乾造：戊庚癸壬／申申丑子，既无财星又无食伤星，以妻宫丑为妻，为何能「沾妻子的光，因妻家关系走入仕途」？","opts":["戊癸五合化火财，日主合财得妻家资助","庚金正印坐申禄，印星强旺直接生官","壬水劫财透时干，助身担起戊土正官","官杀丑为印之墓，印带官星主权力"],"ans":3,"exp":"无财无食伤以妻宫丑为妻，官杀丑正好为金印之墓，印带官星主权力（官印相生沾妻光），故因妻家关系走入仕途。","sec":"4. 无财无食伤，以妻宫为妻","t":"xiang"},{"q":"乾造：戊庚癸壬／申申丑子，命主行甲运时争钱800万、办学校送给政府，其中「甲运」与「学校」各对应什么象？","opts":["甲运为伤官、为学生，戌为学校","甲运为正财、为资金，丑为学校","甲运为偏印、为校舍，子为学校","甲运为七杀、为权力，申为学校"],"ans":0,"exp":"癸水日主行甲运为伤官运、取象为学生，争钱800万办学校送给政府（戌为学校）。","sec":"4. 无财无食伤，以妻宫为妻","t":"xiang"},{"q":"同是「宫星相克、穿、破但被包局」，如何区分是「吵但不离的差婚姻」还是「好婚姻」？","opts":["星包宫必为差婚姻；宫包星必为好婚姻","有穿破隔阂为差；包住且宫生星为好","原局有穿必为差；大运有合必为好","男命必为差婚姻；女命必为好婚姻"],"ans":1,"exp":"宫星有穿破但被包局合住，若有穿破隔阂则吵但不离（差婚姻）；若被包住且宫生星或连体一气，则为好婚姻。","sec":"三、本章小结","t":"diff"},{"q":"八字中看似出现两个夫星或两个妻星，以下哪种情况不以两个人看、仍是一婚到头？","opts":["一星落于主位，另一星落于宾位墓库","前有比劫争抢，后有偏印贴身相克","连体、一气、天干相合视为同一人","两同支天干相克，构成反局之象"],"ans":2,"exp":"两个配偶星若连体（如丁乙巳）、一气、天干相合视为同一人，则一婚到头；天干相克相反（反局）才是两个人。","sec":"三、本章小结","t":"diff"}]},{"n":104,"level":"高级","title":"父母死亡的组合与应期","qs":[{"q":"父（母）星在局中「多现而且杂现」，按盲派叫什么？主什么？","opts":["叫「患」，容易克父母","叫「旺」，主父母长寿","叫「杂」，主父母不和","叫「患」，只主父母多病不死"],"ans":0,"exp":"克父母六条之一：父（母）星多现而且杂现称为「患」，容易克父母。","sec":"一、克父母的六条组合","t":"rule"},{"q":"「财临墓地」在看父亲时主什么？","opts":["父亲不管子女","父当早死","父亲发财","父亲长寿"],"ans":1,"exp":"克父六条之一：财临墓地，父当早死；应期看冲开墓或天干引动墓。","sec":"一、克父母的六条组合","t":"rule"},{"q":"父母星无法立足的位置不同，各有什么含义？","opts":["立不住只主父母分居，不主死","只有日时立不住才克父母","年月、日时宫位上立不住，都是克父母的信息","只有年月立不住才克父母"],"ans":2,"exp":"父母星在年月宫位不能存在是克父母的信息，在主位日时宫位不能存在也是。","sec":"一、克父母的六条组合","t":"diff"},{"q":"断父母死亡的应期，第一步先找什么？","opts":["流年的天克地冲","父母星的墓库","日主的喜忌","父（母）星的原神"],"ans":3,"exp":"先找父母星的原神（生它的字），运或流年穿、克、合走原神，则父母之星失养。","sec":"判断应期的方法","t":"step"},{"q":"父星入墓，应期怎么取？","opts":["原局墓已备好，大运流年冲开墓或天干引动墓","合住墓库之年才应","墓被冲开后永不再应","原局无墓，运中补出墓才应"],"ans":0,"exp":"星入墓：原局墓已备好，大运流年冲开墓，或天干引动墓，即应。","sec":"判断应期的方法","t":"rule"},{"q":"父母死因取象：卯午相破、申子穿，分别主什么病？","opts":["卯午相破主肝胆病，申子穿主心脏病","卯午相破主心脑血管病，申子穿主尿毒症","卯午相破主胃癌，申子穿主血液病","卯午相破主尿毒症，申子穿主心脑血管病"],"ans":1,"exp":"卯为血管、午为心脏，卯午相破主心脑血管病；子为肾，申子水为肾，申子穿则尿毒症。","sec":"判断应期的方法","t":"xiang"},{"q":"按父母死因的取象，地支戌与子分别对应哪个脏腑？","opts":["戌为肠胃，子为血管","戌为肾，子为心脏","戌为心脏，子为肾","戌为肝，子为肺"],"ans":2,"exp":"取象：卯是血管、午是心脏、戌为心脏、子为肾。","sec":"判断应期的方法","t":"xiang"},{"q":"看母亲时，一定以印星为母吗？","opts":["男命以印为母，女命以财为母","一定以印为母，财为父","印被穿则改以官杀为母","不一定，先按该命实际的象验证何字为母"],"ans":3,"exp":"父母星要按该命实际的象去认，先验证以哪个字为母更符合，不可死守以印为母。","sec":"二、不以印为母的特例","t":"rule"}],"fine":[{"q":"盲派看父母死亡，整套分析的正确先后顺序是什么？","opts":["先定何字为父母星，再看宫位立足与刑冲穿，最后找应期","先看大运流年应期，再反推谁是父母星，最后看宫位","先看年柱纳音，再查十神神煞，最后按墓绝断生死","先看印财旺衰，再定日主喜忌，最后找大运流年冲克"],"ans":0,"exp":"看父母先确定「谁是父、谁是母」，再看这颗星在宫位上能不能立足、有无帮扶及刑冲穿坏，最后按「墓、绝、原神」找应期。","sec":"一、克父母的六条组合","t":"step"},{"q":"同是父母星数量多，什么情况才叫克父母的「患父、患母」？","opts":["父（母）星伏吟且不杂他干","父（母）星多现而且杂现","父（母）星暗藏于墓库之中","父（母）星独透且得长生"],"ans":1,"exp":"父（母）星多现而且杂现称为「患」，如天干丁卯为父又有丙午为父，同现相争相破，才主克父母。","sec":"一、克父母的六条组合","t":"diff"},{"q":"除患父母、宫位无立足、财临墓与无帮扶被坏外，克父母六条还包括哪一项？","opts":["父母星带文昌贵人","父母星坐于日主禄地","父母星临三刑、夹刑","父母星逢天干五合"],"ans":2,"exp":"克父母六条包括：患父母；年月不能立足；日时不能立足；财临墓地；父母星临三刑、夹刑；无帮扶受冲克穿坏。","sec":"一、克父母的六条组合","t":"rule"},{"q":"财星临墓库且年月无根时，什么条件下父亲反而不会太早去世？","opts":["财星透在年干而墓在时支","财星在日时无气绝地之时","财星逢三刑且夹刑之时","财星与墓库坐于同支时"],"ans":3,"exp":"易错点：财临墓地父当早死，但若财临墓库而坐于同支（如戊辰同柱），虽年月无根，也不会太早死，需待运引。","sec":"六、本章小结","t":"rule"},{"q":"父母星在「年月无气」与在「日时无气死绝」，在应期早晚上有何区别？","opts":["年月无气主早失或无立足，日时无气主与我无缘、死父略晚","年月无气主父母长寿，日时无气主父母早年必亡","年月无气只主离异不主死，日时无气只主多病不主死","年月无气主母亲早逝，日时无气专主父亲早逝"],"ans":0,"exp":"父母星引到年月无立足、受刑穿则早失；引到日时无气死绝，表示父母与自己无缘，往往死亡略晚。","sec":"五、父母双亡同看","t":"diff"},{"q":"运或流年破坏父母星的「原神」，哪三种作用方式都会导致父母之星失养？","opts":["生、扶、拱合原神","穿、克、合走原神","空亡、入墓、伏吟原神","长生、沐浴、冠带原神"],"ans":1,"exp":"先找父（母）星的原神（生它的字）；运或流年穿、克、合走原神，父母之星失养即应灾。","sec":"判断应期的方法","t":"rule"},{"q":"原局财星入墓且墓库空亡（如戌土空亡），何种运岁组合最易应验丧父？","opts":["大运空亡财星，流年把财星合进时柱","大运合走食伤，流年让财星透干坐禄","大运来墓并冲开空亡之墓，流年再引动运支","大运生旺财星，流年把墓库完全填实不冲"],"ans":2,"exp":"原局戌土空亡代表墓已备好，行庚辰大运墓到且冲开戌墓，流年酉金再引动辰土，即为开墓死父之应期。","sec":"三、克父命例","t":"calc"},{"q":"原局「戌刑丑」使父墓本来是开的，为何行子运反而应验死父？","opts":["子水冲开戌土，使父星彻底失养","子水合走印星，使母亲先于父亲去世","子水生旺木气，使父母星变成患父","子丑合把墓闭住，且子又引动原局辰墓"],"ans":3,"exp":"原局戌刑丑墓本是开的，但行子运时子丑合使墓闭合，同时子又引动辰墓，故墓闭反而死父。","sec":"三、克父命例","t":"diff"},{"q":"当命局父母星「墓绝同现」时，丧亲应期通常如何抓取？","opts":["行到绝地之运，流年引动父（母）星本字","行到食伤之运，流年天干透出印星","行到长生之运，流年合住父母星原神","行到比劫之运，流年冲去日主禄神"],"ans":0,"exp":"星临绝地（墓绝同现），行到绝地之运，流年引动父星（母星）本字，即为应期。","sec":"判断应期的方法","t":"rule"},{"q":"天干象也能用于长生死绝：若以「子」为父星，为何行甲运、甲年克父？","opts":["甲是子的胎养之地","甲是子的病死之地","甲是子的帝旺之地","甲是子的长生之地"],"ans":1,"exp":"天干的象也能用于长生死绝：甲木为子水的病死之地，故子水为父时，行甲运、甲年主克父。","sec":"判断应期的方法","t":"calc"},{"q":"父母星与主位仅有一处关联（如母癸卯与主位巳火关联），流年寅木穿巳主何应？","opts":["母星离父另嫁，父母闹离异","母星得木生扶，母亲转危为安","唯一联系被破坏，母亲去世","母星被合入主位，母亲搬来同住"],"ans":2,"exp":"巳与母星卯有关联性，流年寅木穿坏主位的巳火，唯一的良好联系没有了，故母亲去世。","sec":"四、克母命例","t":"rule"},{"q":"乾造己丁壬丙／未卯寅午，行丙寅运戊寅年正月死父，除寅长生午火外，丙透有何象？","opts":["印星护身，寅木生助丁火使其长寿","比肩夺财，日主壬水透出克了丙火","伤官见官，己土透出克坏壬水日主","鸠占雀巢，丙午父星透出占了丁卯父位"],"ans":3,"exp":"局中丁卯为父、丙午为另一父（患父），丙寅运寅长生午火、丙火透出，形成鸠占雀巢之象而死父。","sec":"三、克父命例","t":"xiang"},{"q":"以寅木禄神带食神为母，行辛丑运甲戌年母逝，流年「甲」字起什么作用？","opts":["甲代表寅木虚透于天干","甲生助丁火使其成患母","甲是寅木的病死之地","甲合住年干丙火救母"],"ans":0,"exp":"寅木在日支为母，行辛丑运子丑合绊原神、丙辛合去丙，甲戌年甲代表寅木虚透于天，母归天。","sec":"二、不以印为母的特例","t":"calc"},{"q":"若按印为母则印被穿应早丧母，但事实母亲长寿八十余，应如何调整认母之星？","opts":["改以地支空亡之字为母，不论冲穿","改按实际象验证，如以禄神带食神为母","仍以印为母，只是改断母亲早年离异","改以天干最旺的比劫为母，不论宫位"],"ans":1,"exp":"父母星要按该命实际的象去认，先验证以哪个字为母更符合；如子印被未穿而母高寿，则不以印作母，改以寅禄带食神为母。","sec":"二、不以印为母的特例","t":"rule"},{"q":"乾造丁癸辛丁／未卯卯酉，为何不以未印为母，而以癸水食神为母？","opts":["癸水坐于卯木长生之地，故必为母","丁火七杀透出护癸，故以癸水为母","辛生癸食神为母，时支酉为其原神也当母看","未土被卯木克坏且空亡，不能作母"],"ans":2,"exp":"辛金生了月上的癸水食神，所以癸是母亲；时支酉是癸的原神，也当母看。丙戌年穿倒酉禄，母脑溢血亡。","sec":"四、克母命例","t":"calc"},{"q":"坤造乙乙丙庚／未酉戌寅中，母星戌土为何早丧母？","opts":["戌土合住寅木，母星被合走","戌土空亡于日时，母星虚透","戌土坐于日支太旺，形成患母","戌引到年月无位置，又受未刑、酉穿"],"ans":3,"exp":"包局戌为母，引到年月没有位置，又见未刑戌、酉穿戌，所以早失母；戌运戌年戌到母到而应。","sec":"五、父母双亡同看","t":"rule"},{"q":"坤造癸癸甲己／亥亥辰巳中，己巳母星除了在年月被两亥冲克临绝，还伴随什么克母之象？","opts":["枭神夺食","羊刃逢合","比肩争财","伤官见官"],"ans":0,"exp":"巳火引入年月宫位被两亥水冲克，临绝无气，同时两癸枭神夺食，为克母之象，乙丑运乙酉年巳到死地而亡。","sec":"四、克母命例","t":"rule"},{"q":"父母死因取象中，丙戌年「穿倒母星之酉禄」易对应哪种突发死因？","opts":["尿毒症死亡","脑溢血死亡","胃癌死亡","肺结核死亡"],"ans":1,"exp":"丁癸辛丁／未卯卯酉造，己运克癸水母亲，丙戌年穿倒酉禄，母亲脑溢血死亡。","sec":"四、克母命例","t":"xiang"},{"q":"父母死因取象中，戌土除了代表火库，在脏腑上主什么，遇三刑坏戌易主何病？","opts":["戌为肺部，遇丑未戌三刑坏戌主肺癌","戌为肾脏，遇丑未戌三刑坏戌主尿毒症","戌为心脏，遇丑未戌三刑坏戌主心脑血管病","戌为脾胃，遇丑未戌三刑坏戌主胃癌"],"ans":2,"exp":"戌为心脏，壬庚辛乙／子戌丑未造丑运丑未戌三刑火木俱坏，庚辰年坏戌合乙，父心脑血管病突然去世。","sec":"三、克父命例","t":"xiang"},{"q":"坤造戊甲庚戊／申寅戌子中，母星戊申与子水同党，26岁癸未年「穿倒子水」主母死于何病？","opts":["胃癌","肺病","心脑血管病","尿毒症"],"ans":3,"exp":"申子一党，子为母亲的肾，癸未年未穿倒子水，故母亲死于尿毒症。","sec":"四、克母命例","t":"xiang"},{"q":"乾造戊丁庚戊／申巳子寅中，寅木父星被巳穿申冲，行己未运癸亥年父逝，己未运起了什么作用？","opts":["未土穿了子水（父星原神），且寅又入未库","未土合住巳火，解除了巳穿寅之患","未土生助申金，使申金直接透干克寅","未土冲开寅木，且己土合住戊土印星"],"ans":0,"exp":"寅木为父，己未运未土穿了子水（寅的原神）使父失养，同时寅又入未库；癸亥年引动父星为应期。","sec":"三、克父命例","t":"calc"},{"q":"同父母的两造（乾癸癸丁丙／卯亥巳午与坤乙乙丙庚／未酉戌寅），庚戌年先死母、甲寅年再死父的共同命理机制是什么？","opts":["父星在年月受穿克早亡，母星在日时无气略晚","戌运戌年母星入墓或到位先应，甲寅年水父星临绝或引动绝地后应","寅运寅年母星先入绝地，戌运戌年父星再入墓库","庚戌年父星财库被冲开先亡，甲寅年母星禄神被冲后亡"],"ans":1,"exp":"兄妹同父母，庚戌年火墓（或母星戌）到位先死母；甲寅年水到日时、父星酉到寅为绝，故甲寅年死父略晚。","sec":"五、父母双亡同看","t":"rule"}]},{"n":105,"level":"高级","title":"父母离异与弃养（过继、给出去）","qs":[{"q":"命中父母之星相克，但没有任何一方死亡的信息，应断什么？","opts":["父母不和，但终身不离","父母离异","父母分居但不离","父母一方早亡"],"ans":1,"exp":"看得出父母相克、看不出死亡信息，一定是离异。","sec":"一、父母离异","t":"rule"},{"q":"父星双合、伏吟，与母星双合、伏吟，各主什么？","opts":["父早亡，母早亡","父外遇不离，母外遇不离","父另娶，母改嫁","父改嫁，母另娶"],"ans":2,"exp":"父星双合、伏吟是父另娶；母星双合、伏吟是母改嫁。","sec":"一、父母离异","t":"diff"},{"q":"父母离异后，孩子是随父还是随母，怎么看？","opts":["看月令是印还是财","看时柱是男字还是女字","看年柱是父字还是母字","看日主坐在哪一方的字上"],"ans":3,"exp":"随母或随父，看自己（日主）坐在谁的字上。","sec":"一、父母离异","t":"rule"},{"q":"继父、继母在盘中怎么找？","opts":["暗合或冲引出的另一个字","大运中新来的比劫字","时柱上透出的食伤字","月令里透出的比肩字"],"ans":0,"exp":"继父、继母是暗合、冲所引出的另一个字；父母之星被他字合到继位也是。","sec":"一、父母离异","t":"rule"},{"q":"月令食神入墓，时上又见食神，主什么？","opts":["一生衣食无忧","父母不养，为过继命","父母双全，晚年得子","母亲早逝，父亲独养"],"ans":1,"exp":"月令食神入墓，父母不养；时上再见食神，为过继命。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"盲派把食神看作「养我之物」，食神被合、被穿、被绊，主什么？","opts":["与子女缘薄，晚得子","身体虚弱，多病","没饭吃，被送走","学业不顺，辍学"],"ans":2,"exp":"食神被合、被穿、被绊，就是没饭吃，被送养。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"时柱伏吟，又有天干五合（如丁壬合）合到主位，主什么？","opts":["父母双全，远方有贵人","出国发展，远走他乡","随母改嫁，有继父","远方食神合到主位，过继给他人"],"ans":3,"exp":"时柱伏吟、天干五合到主位，远方食神合到主位，所以过继（如过继给叔叔）。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"日支与年支相穿（如寅巳穿，穿倒食神），主什么？","opts":["父母不养","父母另娶另嫁","父母双亡","随母改嫁"],"ans":0,"exp":"日支与年支相穿，穿倒食神，父母不养。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"过继命里，月柱与时柱各代表谁？","opts":["月柱为祖父母，时柱为父母","月柱为生父母，时柱为养父母","月柱为养父母，时柱为生父母","年柱为生父母，月柱为养父母"],"ans":1,"exp":"看过继先分清：月柱是生父母，时柱是养父母。","sec":"二、父母弃养（过继、给出去）","t":"diff"},{"q":"乙庚合，合到门户（时柱），在弃养上主什么？","opts":["留下来，母亲亲养","给人当差，晚年归家","给出去，送养","随父同住，继母相伴"],"ans":2,"exp":"乙庚合合到门户，是给出去、送养之象。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"母带伤官、父星他合，在养育上分别主什么？","opts":["母带伤官不养自己；父星他合接济自己","母带伤官溺爱自己；父星他合偏心自己","母带伤官早亡；父星他合另娶","母带伤官不养自己；父星他合不管自己"],"ans":3,"exp":"母带伤官，不养自己；父星他合，不管自己。","sec":"二、父母弃养（过继、给出去）","t":"rule"}],"fine":[{"q":"父星伏吟主父娶两次，如何判断父亲是「先离婚再娶亲妈」还是「先娶亲妈再离婚」？","opts":["看年柱与时柱哪柱天干为阳","看亲父星伏吟的先后顺序","看日主坐支是长生还是墓库","看母星是否同时出现天干五合"],"ans":1,"exp":"先离婚后与亲妈结婚者，看亲父星伏吟的先后顺序；如丑土伏吟，先后位置决定谁在前、谁在后。","sec":"一、父母离异","t":"rule"},{"q":"局中「财临墓地」本有克父之象，若同时出现财墓被穿（如酉戌穿），更倾向于何种判断？","opts":["父亲不仅长寿，而且必定大发横财","必定在童年克死父亲，绝不会离异","表明要离开父、没缘份，不一定是克死","父亲虽不死，但日主必定被父亲打伤"],"ans":2,"exp":"如甲甲乙甲／戌戌酉申造，戌财临墓本克父，但酉戌穿表明要离开父、没缘份，不一定是克死。","sec":"一、父母离异","t":"diff"},{"q":"坤造壬癸辛己／寅丑亥亥中，寅为父、亥为母，父星「寅合两亥」且亥伏吟，主何象？","opts":["日主有两个亲生母亲，生母与养母同住","母亲早年丧夫，随后终身守寡不嫁","父亲娶两个妻子且同时同居不分","寅合两次且亥伏吟，表示母亲嫁两次"],"ans":3,"exp":"亥为母，寅为父，寅合两亥是合了两次，亥又伏吟，就表示母嫁两次；日主坐在亥上故随母。","sec":"一、父母离异","t":"xiang"},{"q":"坤造丙庚己庚／寅寅卯午中，父母离婚后为何「父再婚，而母一个人过」？","opts":["两庚伏吟母离开父，寅生午（与卯破）为父外遇及继母","寅木克死庚金，母星早亡，父亲随后独身终老","两庚合住丙火，母星被合走改嫁，父星独守空房","午火冲去寅木，母星另觅新欢，父星无依无靠"],"ans":0,"exp":"丙寅为父，两庚为母，庚绝在寅父不要母，庚复吟母离开；寅生午，午与卯破是继母，故父结婚而母自己过。","sec":"一、父母离异","t":"diff"},{"q":"乾造壬己己乙／子酉卯丑中，壬子为父、酉食为母，为何父母必离异？","opts":["酉金入墓于丑，母星早年去世","子酉不生相隔，不能在一起","乙木克伤己土，日主与父母无缘","子水冲克酉金，父克死母星"],"ans":1,"exp":"壬子为父，酉食为母，子酉之间不生且相隔，不能在一起，所以父母离异；卯酉相冲，卯为继父。","sec":"一、父母离异","t":"rule"},{"q":"坤造壬丙癸甲／戌午酉寅中，丙午加戌为父、甲寅为母，天干「壬压戌」代表谁？","opts":["一直照顾日主长大的亲生祖母","对日主非常好的亲生继父","从母亲手中夺走父亲的那个女人","日主早年夭折的亲哥哥"],"ans":2,"exp":"壬压戌，壬是劫财，正是从母亲手中夺走父亲的那个女人；酉戌穿使父与自己无缘，父母必离异。","sec":"一、父母离异","t":"xiang"},{"q":"坤造乙丙甲乙／未戌子亥中，丙戌为母、未为父，为何日主「从未见过生父」？","opts":["亥水冲克丙火，母亲把生父赶出家门","未土空亡于年柱，生父在出生前去世","乙木比劫争父，生父远走海外不归","父母相刑早离异，且日支子与未相穿"],"ans":3,"exp":"丙戌为母，未为父，戌未相刑要离异且离得早；子未穿，日支穿父星，故自己从未见过生父。","sec":"一、父母离异","t":"xiang"},{"q":"坤造癸甲甲丁／巳寅辰卯中，4岁随娘改嫁且继父对自己很好，继父是盘中哪个字，为何对她好？","opts":["辰为继父，因辰在日主坐下","巳为继父，因巳在年支生助辰土","丁为继父，因丁透时干照暖甲木","卯为继父，因卯在时支与寅比劫"],"ans":0,"exp":"甲寅伏吟母有改嫁之意，巳火财为亲父被寅穿而分离；辰为继父，就在日主坐下，所以对自己很好。","sec":"一、父母离异","t":"xiang"},{"q":"坤造癸甲甲丁／巳寅辰卯，大运乙卯，为何父母离异恰好应在「4岁丙申年」？","opts":["丙申年申金入墓于辰，亲父当年发生意外伤亡","寅巳穿在年月必早，丙申年申合父星巳而冲寅，引动寅巳之穿","丙申年申金穿倒辰土，母亲当年被迫离开亲父","丙申年丙火透干生旺辰土，继父在当年正式进门"],"ans":1,"exp":"寅巳相穿在年月必早，4岁丙申流年，申合住父星巳火而冲克寅木，引动原局寅巳之穿而应验随母改嫁。","sec":"一、父母离异","t":"calc"},{"q":"乾造庚庚庚戊／子辰辰寅中，子与辰皆作母看、辰辰伏吟主母改嫁，从何处看出「母亲离过婚（另有前夫）」？","opts":["子水临空亡之地，为母亲前边的丈夫","戊土透在时干，为母亲前边的丈夫","辰中有乙木退气，为母亲前边的丈夫","寅中有丙火长生，为母亲前边的丈夫"],"ans":2,"exp":"子为母，辰也为母，辰辰伏吟主母改嫁；辰中有乙木退气，正表示母亲离过婚，是母亲前边的丈夫。","sec":"一、父母离异","t":"xiang"},{"q":"乾造辛戊庚己／亥戌寅卯中，亥为母、卯为父，为何「亥被戌克而合到寅」主父离与继父？","opts":["戌土克坏亥水，主母亲早年去世、父亲续弦","亥母合到寅是生助父星，主父母破镜重圆","寅木冲克申金，主日主因打架而被父母抛弃","亥母被戌克而合到寅，主离开父而另有继父寅"],"ans":3,"exp":"卯合戌，合到父亲的宫位；亥母被戌克而合到寅，表示离开父亲之意，寅木则为继父。","sec":"一、父母离异","t":"xiang"},{"q":"坤造己辛丙癸／巳未申巳中，己巳为母、申为父，一申配两巳，丁丑年离异前，乙亥年为何先闹离婚？","opts":["亥年冲破原局巳申合，呈父母分离之象","亥年合住未土祖母，家中无人调解父母矛盾","亥年透出乙木印星，父亲当年另娶他人进门","亥年穿倒己土母星，母亲重病引发家庭破裂"],"ans":0,"exp":"己巳为母、申为父，一申配两巳，时上巳为父的女朋友；乙亥年亥水冲破巳申合，显父母分离之象。","sec":"二、父母弃养（过继、给出去）","t":"xiang"},{"q":"坤造丙癸辛癸／寅巳酉巳（梦露）中，癸为母，「癸巳自合」在弃养象里表达什么含义？","opts":["母亲随父远走他乡","母亲不要自己","母亲极度溺爱自己","母亲与养母争抢自己"],"ans":1,"exp":"癸为母，坐巳被合无气，癸巳自合直接表示母亲不要自己，从小被父母离弃送人。","sec":"二、父母弃养（过继、给出去）","t":"xiang"},{"q":"乾造壬庚癸癸／寅戌卯丑从小被送养，其中「卯戌合」与「时上癸水伏吟」分别起什么象意？","opts":["卯戌合代表过继给远方叔叔，时上癸水伏吟代表继承家业","卯戌合代表母亲早亡，时上癸水伏吟代表父亲独自抚养","卯戌合食神被收走代表没饭吃，时上癸水伏吟代表送出去","卯戌合代表父母恩爱和睦，时上癸水伏吟代表随母改嫁"],"ans":2,"exp":"卯戌合食神被合绊收走代表没饭吃（财库戌被闭了火气），时上癸水伏吟（癸当禄看）代表送出去。","sec":"二、父母弃养（过继、给出去）","t":"diff"},{"q":"乾造辛丙辛丙／卯申巳申从小过继给姨妈，卯为父，「卯合劫财」为何主父亲不养自己？","opts":["卯为七杀之位，合劫财表示父母刑克","卯为食神之库，合劫财表示父亲早逝","卯为印星之根，合劫财表示母亲改嫁","财为养我之物，合劫财表示不养我"],"ans":3,"exp":"辛为母，卯为父，财为养我之物，卯合劫财就是不养我；日主逢时上丙官合，又有新父母（丙养父、申养母）。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"乾造乙庚壬癸／巳辰寅卯由姥姥养大，盘中哪个字代表「姥姥」？","opts":["卯通于乙，乙代表姥姥","巳火财星，巳代表姥姥","辰土水库，辰代表姥姥","癸水劫财，癸代表姥姥"],"ans":0,"exp":"寅巳穿倒食神父母不养，时上见伤官卯，卯通于年干乙，乙代表姥姥，故由姥姥养活。","sec":"二、父母弃养（过继、给出去）","t":"xiang"},{"q":"坤造己辛丙癸／巳未申巳中，父母离异不管自己，自己在奶奶家生活，哪个字代表「祖母（奶奶）」？","opts":["巳为祖母","未为祖母","申为祖母","癸为祖母"],"ans":1,"exp":"母带伤官不养、父星他合不管自己；丙辛合到月令，月令未土代表祖母，故在奶奶家生活。","sec":"二、父母弃养（过继、给出去）","t":"xiang"},{"q":"乾造壬辛庚丁／午亥辰亥中，月令与时上食神皆入墓，为何能明确断其「从小过继给叔叔」？","opts":["有辰午暗合，月令食神生旺主位","有辛庚比劫，日主自己外出独立谋生","有丁壬合，远方食神合到主位","有亥亥自刑，时柱养父母早年去世"],"ans":2,"exp":"月令与时上食神都入墓，但有丁壬合，远方的食神合到主位，所以过继，且是从小过继给叔叔。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"乾造丙戊乙庚／午戌丑辰从小被给出去，盘中「丑午穿」与「丑戌刑」分别表达谁不养自己？","opts":["丑午穿代表父母双亡，丑戌刑代表随母改嫁","丑午穿倒财星父不养，丑戌刑母也不养","丑午穿代表由姥姥抚养，丑戌刑代表由叔叔收养","丑午穿倒食神母不养，丑戌刑父也不养"],"ans":3,"exp":"丑午穿，穿倒食神母不养；丑戌刑，父也不养；乙庚合，合到门户，给出去。","sec":"二、父母弃养（过继、给出去）","t":"diff"},{"q":"在过继或弃养命局中，若「时柱有养父母」，通常大运走到哪类地支时会有新的家？","opts":["走到能代表养父母宫位或新家之地（如辰地）","走到月令生父母墓库被合闭的大运","走到比劫透干争抢财星的大运","走到冲克日主禄神与食神的大运"],"ans":0,"exp":"月柱为生父母，时柱为养父母；如丙癸辛癸／寅巳酉巳，癸巳自合送人后，走到辰地有新的家。","sec":"二、父母弃养（过继、给出去）","t":"rule"},{"q":"判断父母离异后谁「另娶」或「改嫁」，除了双合、伏吟外，继父或继母还常通过何种方式在盘中显现？","opts":["年干空亡且不与任何地支发生刑冲穿合","暗合冲引出的字，或父母星被合到继位","日主坐下比肩伏吟且不透天干","月令食神入墓且时柱再见同类食神"],"ans":1,"exp":"继父、继母由暗合、冲所引出的另一个字显现，或父母之星被他字合到继位（如寅丑暗合、卯酉冲）。","sec":"一、父母离异","t":"rule"},{"q":"比较「母带伤官」与「食神被穿倒」在弃养断法上的侧重点，下列哪项正确？","opts":["母带伤官主母亲长寿，食神被穿主日主一生衣食无忧","母带伤官专主父母离异后母改嫁，食神被穿专主生父早年病逝","母带伤官主母不养且母子关系不好，食神被穿主养我之物被坏没饭吃","母带伤官主过继给姨妈，食神被穿主过继给远方叔叔"],"ans":2,"exp":"母带伤官如己未（伤官坐母），关系不好且不养自己；食神为养我之物，被穿倒（如寅巳穿、丑午穿）则没饭吃被送走。","sec":"二、父母弃养（过继、给出去）","t":"diff"}]},{"n":106,"level":"高级","title":"职业象法一：十天干与十二地支之象","qs":[{"q":"大阴阳与小阴阳的划分是（　）。","opts":["大阴阳木水为阳火金为阴，小阴阳甲丙戊庚壬为阳","大阴阳甲丙戊庚壬为阳，小阴阳木火为阳","大阴阳木火为阳金水为阴，小阴阳甲丙戊庚壬为阳","大阴阳金水为阳木火为阴，小阴阳乙丁己辛癸为阳"],"ans":2,"exp":"大阴阳以木火为阳、金水为阴；小阴阳以甲丙戊庚壬为阳、乙丁己辛癸为阴。","sec":"一、阴阳、五行与十干总说","t":"diff"},{"q":"戊土独透天干，职业倾向是什么？","opts":["记者，戊主传播","银行职员，戊主金融","医生，戊主手术","老师，戊有讲台之象"],"ans":3,"exp":"戊为高台、舞台、讲台，独透者易当老师。","sec":"二、十天干之象","t":"xiang"},{"q":"乙与丁，各自在传媒文化方面的象分别是（　）。","opts":["乙主纸张书籍传播，丁主文化文字智慧","乙主文化文字智慧，丁主纸张书籍传播","乙主光电影视色彩，丁主纸张传播","乙主讲台舞台，丁主文字荣誉"],"ans":0,"exp":"乙为书籍纸张毛笔丝线，有传播之象；丁为文明文化文字思根智慧医道玄学。丙才主色彩影视光电。","sec":"二、十天干之象","t":"xiang"},{"q":"庚、辛两干取象的主要区别是（　）。","opts":["庚为珠宝针笔，辛为钢材机器军警","庚为钢材机器军警，辛为珠宝针笔","庚为书画影视，辛为讲台建筑","庚为数字运算，辛为玄学西药"],"ans":1,"exp":"庚：五金钢材矿山机器金融军队警察手术；辛：珠宝玉器金饰针笔钱币精加工。","sec":"二、十天干之象","t":"xiang"},{"q":"庚金日主，局中无火，按盲派应怎么看？","opts":["金旺无火则主富，利于求财","金旺无火则化水，主聪明","金旺无火为顽金，难成才","金旺无火则最清贵，主文职"],"ans":2,"exp":"庚喜火炼方成器，金旺无火为顽金（顽铁）。","sec":"二、十天干之象","t":"rule"},{"q":"壬癸两干的类象，分别偏向（　）。","opts":["壬主珠宝针笔，癸主钢材机器","壬主文化文字，癸主讲台建筑","壬主玄学谋略西药，癸主数字运算","壬主数字运算，癸主玄学谋略西药"],"ans":3,"exp":"壬：运筹运算数字，易成会计；癸：玄学智谋美容产品西药。","sec":"二、十天干之象","t":"xiang"},{"q":"亥水与子水在象上的区别是（　）。","opts":["亥为不动之水，子为流转不息之水","亥为大海，子为小溪","亥为阳水近壬，子为阴水近癸","亥为流转不息之水，子为不动之水"],"ans":0,"exp":"亥占阴位而藏阳，阴水近癸；子占阳位而藏阴，阳水近壬；亥为不动之水，子为流转不息之水。","sec":"四、十二地支之象","t":"xiang"},{"q":"戌土除火库外，还是什么库，对应哪类职业？","opts":["武库，主军队警察","文库，火主文，主学校编辑部教育部门","财库，主银行金融","水库，主车辆机器"],"ans":1,"exp":"戌是火库，火主文，也是文库：学校、编辑部、教育部门；辰才是水库。","sec":"四、十二地支之象","t":"xiang"},{"q":"亥与会计职业相关的四种情况是（　）。","opts":["亥为伤官见官，被食神穿，被比劫冲，或亥为食","亥为比劫合财，被印墓，生助官杀，或亥为印","亥为食伤合财，被财墓，冲制财官，或亥为财","亥为印星，被官杀克，被比劫合，或亥为官"],"ans":2,"exp":"亥与会计相关：亥为食伤合财；亥被财墓；亥冲制财星或官杀星；亥为财星。","sec":"四、十二地支之象","t":"rule"},{"q":"己酉为赛车之象，为何不是车祸？","opts":["酉戌穿主发动机，不主车祸，不论强弱","戌强酉弱，戌穿坏酉，所以反主速度","己酉合住了戌，戌穿的作用消失","酉强戌弱，戌穿不坏酉；若只一个己酉才可能车祸"],"ans":3,"exp":"己象方向盘、酉为驾驶技术、酉戌穿为速度、戌为发动机；酉强戌弱穿不坏酉，所以不是车祸。","sec":"十二地支命例","t":"diff"},{"q":"用食神或伤官合法对抗官，常见的职业是（　）。","opts":["律师，站在当事人一边对抗检控机关","法官，代表官方执法","军警，执行官方命令","会计，替单位管理财务"],"ans":0,"exp":"伤官有对抗官之意，用伤官、食神合法对抗官，很可能是律师。","sec":"十二地支命例","t":"xiang"}],"fine":[{"q":"十天干顺次相生，在尊卑贵贱的取象上遵循什么基本原则？","opts":["以阴为尊贵，以阳为卑贱","以火土为尊贵，以木金水为卑贱","以阳为尊贵，以阴为卑贱","以官杀为尊贵，以食伤为卑贱"],"ans":2,"exp":"十干顺次由阳而逐步生阴，十干有尊卑贵贱，以阳为尊贵，阴为卑贱。","sec":"一、阴阳、五行与十干总说","t":"rule"},{"q":"按五行的季节与气象总说，庚辛金与壬癸水各自的气象是什么？","opts":["庚辛金季夏主养育为厚重，壬癸水秋主收为成熟","庚辛金秋主藏为机变通灵，壬癸水冬主收为肃杀律令","庚辛金夏主长为火热美丽，壬癸水春主生为生发向上","庚辛金秋主收为肃杀律令，壬癸水冬主藏为机变通灵"],"ans":3,"exp":"庚辛金主秋收，气象为肃杀、律令；壬癸水主冬藏，气象为机变、通灵。","sec":"一、阴阳、五行与十干总说","t":"xiang"},{"q":"在人体与职业取象中，甲木与丙火在自然象和人体头面部位各主什么？","opts":["甲为雷与大树主头、头面，丙为日与光主眼睛、神经","甲为霞与丘陵主鼻、胃，丙为云与沃土主脾、腹","甲为风与禾苗主颈、脊柱，丙为星与灯主心脏、血管","甲为霜与金主大肠、牙齿，丙为月与金主肺、皮肤"],"ans":0,"exp":"甲在天为雷、在地为大树，人体主头、头面、头发、眉毛；丙在天为日、在地为光，人体主眼睛、神经、大脑、血压等。","sec":"二、十天干之象","t":"xiang"},{"q":"十天干中，哪两个天干最常直接用于看「文化水平高低、文章书籍」或「爱读书」？","opts":["壬表示文化水平高低与书籍，癸临食神表示爱读书","丁表示文化水平高低与文章书籍，己临食神表示爱读书","甲表示文化水平高低与文章，庚临食神表示爱读书","丙表示文化水平高低与讲台，辛临食神表示爱读书"],"ans":1,"exp":"丁可用来表示文化水平高低、文章书籍；己有书本之象，己临食神表示爱读书（如己亥相配）。","sec":"二、十天干之象","t":"xiang"},{"q":"庚金与辛金在人体部位和病象取象上，下列哪项区分最准确？","opts":["庚主肾脏、膀胱、尿道，辛主脾胃、胰腺、食道","庚主肺、皮肤、耳朵、筋骨，辛主大肠、大骨骼、骨钙","庚主大肠、大骨骼、骨钙，辛主肺、皮肤、呼吸道、喉咙","庚主心脏、血管、小肠，辛主肝胆、经脉、手指"],"ans":2,"exp":"庚主大肠、大骨骼、骨钙、肺、牙齿、嗓音、脐；辛主肺、皮肤、呼吸道、喉咙、鼻腔、耳朵、筋骨、声音。","sec":"二、十天干之象","t":"diff"},{"q":"在医药与病灾取象中，「辛金」与「癸水」分别对应哪类医疗相关象义？","opts":["辛代表提纯物与西药，癸代表针、手术与机器","辛代表中药汤药与学校，癸代表手术刀与医院","辛代表讲台与砖瓦，癸代表方向盘与水泥","辛代表针、医药与病人，癸代表提纯物与西药"],"ans":3,"exp":"辛主珠宝、针、笔、医药、病人；癸主眼泪、水墨、玄学、美容产品、提纯物、西药。","sec":"二、十天干之象","t":"xiang"},{"q":"坤造癸癸甲丁／丑亥寅卯遭遇抢劫毁容并整容，其中「癸克丁」「酉冲卯」「丁丑年从屁股取皮植皮」的对应取象是什么？","opts":["癸克丁为毁容，酉冲卯动羊刃为抢劫，丑为阴为屁股","癸克丁为抢劫，酉冲卯动羊刃为毁容，丑为水库为汤药","癸克丁为流窜犯，酉冲卯为毁容，丑为高台为医院","癸克丁为植皮，酉冲卯为动手术，丑为墓库为住院"],"ans":0,"exp":"甲主头、丁主面，癸克丁表示毁容；酉冲卯动羊刃表示抢劫，酉代表丑为劫犯；丁丑年丁补丁，丑为阴为屁股故取皮植皮。","sec":"十天干命例","t":"xiang"},{"q":"张艺谋命局庚庚丙壬／寅辰子辰中，何以判其为「导演」且女演员通过他的作品扬名？","opts":["丙见庚为火炼顽金主矿山，寅为公门官府，辰为牢狱代表严厉","丙见壬为日照江湖主光影色彩，寅见水为演，庚为女演员靠丙照壬子才气","寅见辰为木土相穿主运动，庚为男演员，壬子为官杀代表名气","庚见壬为金水伤官主数理，辰为水库主机器，丙火主讲台教育"],"ans":1,"exp":"丙日见壬为日照江湖，主明暗光影色彩；寅见水为演故为导演；庚为女演员，壬子是庚之伤食才气，靠丙火来照而扬名。","sec":"十天干命例","t":"xiang"},{"q":"丁俊晖命局丁癸庚丁／卯卯辰丑中，如何用干支象拼出「打台球且冠军收入囊中」的过程？","opts":["癸数字、丁灯火、卯辰穿运输、丁伏吟门店、丑入辰墓主破财","癸玄学、丁文字、卯辰穿算账、丁伏吟讲台、丑入辰墓主牢狱","癸技术、丁点目标、卯辰穿运动、丁伏吟移动、丁配丑落袋入辰墓","癸西药、丁心脏、卯辰穿车祸、丁伏吟医药、丑入辰墓主手术"],"ans":2,"exp":"癸伤官为技术，丁为点目标，卯辰穿为运动，丁丁伏吟为移动，丁配丑为落袋；丁带丑印代表冠军，丑入辰墓即收入囊中。","sec":"十天干命例","t":"xiang"},{"q":"邓丽君命局壬癸庚戊／辰丑辰寅中，成名「歌后」的核心组合象是什么？","opts":["寅木为演艺，戊土是医院，戊寅相配呈火炼顽金之象","庚金为声音，丑土是书柜，庚丑相合呈金水相逢之象","壬食神为才华，辰印是讲台，壬辰相配呈日照江湖之象","癸伤官为才华，戊印是舞台，戊癸合呈落日霞光之象"],"ans":3,"exp":"癸伤官为才华，戊印是舞台（高台），戊癸合有落日霞光之象，故成一代歌后；乙亥年亥合寅灭丙火，寒湿瘀肺而亡。","sec":"十天干命例","t":"xiang"},{"q":"甲癸庚甲／辰酉辰申造为何「上学尽考零分，且行子运五年进好几次局子」？","opts":["庚旺无火为顽铁，月见癸水反为生锈；子运水来金沉主牢狱","庚金逢酉为羊刃，甲木财星透干克印；子运子辰合主破财","庚金配癸为伤官，甲木偏财合身克比；子运冲午火主车祸","庚金坐申为禄神，辰土印星包局克食；子运子酉破主离婚"],"ans":0,"exp":"庚日主金旺无火炼为顽铁，月见癸水不为秀气反为生锈，故考试零分；行子运水来金沉（金沉水底不见阳光）主牢狱。","sec":"十天干命例","t":"xiang"},{"q":"中医师命局癸辛己戊／巳酉巳辰中，哪几个象共同拼出了「针药并用的好中医」？","opts":["辛酉为首饰，巳火为色彩，戊辰为水泥，癸水为玄学","辛酉为病人与针，巳扶阳为医生，戊辰手合酉把脉并作汤药","癸水为西药，巳火为手术，戊土为讲台，辰土为牢狱","辛酉为钟表，巳火为网络，戊辰为机器，癸水为美容"],"ans":1,"exp":"辛酉取象病人、辛为针，巳沟通阴阳扶阳为医生；戊辰劫财为手合酉为把脉，辰为水库兼木余气合酉金食神为汤药。","sec":"十天干命例","t":"xiang"},{"q":"庚癸己丙／午未卯寅（双目失明算命师）中，己丑年被炸双目失明的象与应期机制是什么？","opts":["寅头丙眼配庚肺，金木相战入丑墓，己丑年庚绝于寅且丑午穿","卯木血管配午心，火炎木焚入辰墓，己丑年己生庚且丑未相刑","寅头丙眼配癸瞳仁，火土燥癸入未墓，己丑年己克癸且丑冲开未墓","癸水为肾配丙火，水火相冲入戌墓，己丑年丙克庚且丑寅暗合"],"ans":2,"exp":"寅为头，丙为眼，丙配癸如眼睛与瞳仁；火土太燥癸焦干，阴干癸入未墓，己丑年天干己克癸、地支丑冲开未墓而失明。","sec":"十天干命例","t":"calc"},{"q":"十二地支中，哪组地支的阴阳属性是「占阴位而藏阳」？","opts":["午火与子水","卯木与酉金","寅木与申金","巳火与亥水"],"ans":3,"exp":"巳占阴位而藏阳（近丁），亥占阴位而藏阳（近癸）；而午与子是占阳位而藏阴。","sec":"四、十二地支之象","t":"diff"},{"q":"地支「寅」与「申」在职业和器械取象上，下列哪项描述符合教材？","opts":["寅含火为枪弹发动机武装，申为铁器重器机器车辆政法西医手术","寅为酒食休闲庭院公园，申为地下室厕所煤炭黑社会","寅为池塘井泉泥巴水库，申为窑冶炉城墙坟墓加油站","寅为柔软纸张丝线舟船，申为首饰钟表寺院隐学妓女死人"],"ans":0,"exp":"寅含火故为枪弹、发动机、动力、武装暴力、公门；申为阳金重器，主铁器、矿产、机器车辆、政法司法、西医手术。","sec":"四、十二地支之象","t":"xiang"},{"q":"地支「未土」与「丑土」同为阴土，在性质与常见行业取象上如何区分？","opts":["未为阳土主城墙高崖加油站，丑为阳土主堤岸田园大机构","未干燥收敛主酒食休闲酒店中药，丑寒湿至阴主地下室矿井黑社会目盲","未寒湿至阴主地下室矿井牢狱，丑干燥收敛主公园庭院酒店","未为火库主互联网汽车数学，丑为水库主车辆计算机网络"],"ans":1,"exp":"未为阴土干燥收敛，常有酒食休闲、公园庭院、酒店、中药之意；丑为阴中之至阴、寒湿，主地下室、矿井、煤炭、牢狱、黑社会、目盲。","sec":"四、十二地支之象","t":"xiang"},{"q":"十二地支中，哪两个地支因同在「乾位」或与乾卦相关而均主「数字、运算、数学」？","opts":["巳与午","未与申","戌与亥","卯与辰"],"ans":2,"exp":"戌在乾位，乾主数学；亥与戌同为乾位，主数字、运算、科技（近壬）。此外子水也主数字、数学。","sec":"四、十二地支之象","t":"xiang"},{"q":"十二地支病象中，寅、卯、辰、丑各自易对应的典型病症分别是什么？","opts":["寅多骨病血疾，卯多痰湿肝郁，辰多心脑血管，丑多水液血液","寅多肠疾肺伤，卯多齿痛目疾，辰多胃热消渴，丑多肾亏眼疾","寅多转筋体痛，卯多中风头疾，辰多肺臃肿瘤，丑多隆闭肿瘤","寅多中风头疾，卯多转筋体痛，辰多隆闭肿瘤，丑多肺臃肿瘤"],"ans":3,"exp":"十二支病象：寅多中风头疾；卯多转筋体痛；辰多隆闭或肿瘤；丑多肺臃或肿瘤。","sec":"四、十二地支之象","t":"xiang"},{"q":"坤造丁丙丙丁／酉午寅酉为何是「银行管理不良资产」的公职人员？","opts":["独寅公门主公职，丙丁克酉阴财管财，午羊刃有执法之象","丙火为影视传媒主演员，寅木为高楼大厦，酉金为钟表器皿","丁火为文化文章主编辑，酉金为病人死人，午火为血光之象","酉金为轻器首饰主银行，午火为广告色彩，寅酉互绝主改行"],"ans":0,"exp":"寅为公门，独寅坐地支为贵主公职；丙丁克住酉阴财为管财，午羊刃有执法之象，故为银行管理不良资产。","sec":"十二地支命例","t":"xiang"},{"q":"乾造癸甲癸乙／未子丑卯为报社高级记者、编辑，与坤造壬癸癸壬／子卯卯子为拉面馆女老板，同用「卯」字如何区分取象？","opts":["前者卯为肝胆肢体配子水病灾，后者卯为报刊传播配比劫广告","前者卯为柔软的纸配食神思想写文章，后者卯为面配比劫在两头用手拉面","前者卯为园林花草配未土公园，后者卯为舟船运输配子水江海","前者卯为门窗建材配丑杀库，后者卯为丝线织物配子水漂染"],"ans":1,"exp":"报社造卯象柔软的纸，食神为思想，思想写在纸上为文章；拉面馆造食神为吃饭，卯为面，比劫为手在两头拉面。","sec":"十二地支命例","t":"xiang"},{"q":"乾造癸丙甲戊／卯辰辰辰为何是「汽运公司经理」而非普通司机？","opts":["丙火为发动机且戊土为道路，卯木生丙火故为大老板","癸水为运算且甲木为首领，辰土入墓做功故为修车工","甲辰为车象且辰多连排成车队，卯辰穿做功故掌有权力","戊土为讲台且卯木为教鞭，辰土为学校故为驾校校长"],"ans":2,"exp":"辰含水为车、藏子为转动、水库主机器，综合代表车，辰多连排故为汽运公司；卯辰穿做功故掌权力当经理。","sec":"十二地支命例","t":"xiang"},{"q":"乾造乙戊癸庚／巳子卯申为何能断为「银行行长」？","opts":["乙木为纸张，子水为数字，子卯相刑为算账，庚申为政法","戊土为高台，癸水为玄学，戊癸合为名气，巳申合化水为财","巳火为色彩，卯木为传播，巳申合为演艺，癸水为才华","庚申主收，卯木主放，一收一放为金融银行之象，卯申合食神合印为功"],"ans":3,"exp":"庚申主收，卯木主放，一收一放为银行金融象，卯木食神为财原神（钱的源头），卯申合食神合印为功，故为行长。","sec":"十二地支命例","t":"xiang"},{"q":"李昌镐（乙癸丙戊／卯未子子）与会计主管（壬丁戊己／子未申未）同有「子未穿」，为何象义截然不同？","opts":["前者子空亡为棋子厮杀，后者子财未手打算盘算账","前者子未穿主车祸速度，后者子未穿主官非牢狱","前者未为酒店餐饮主饭店，后者未为公园庭院主园林","前者子为流动江海主航运，后者子为肾脏泌尿主西医"],"ans":0,"exp":"李昌镐造子为小珠子代表黑白棋子，子未穿为运算与战斗，子落空亡代表虚空棋盘厮杀；会计造子临财星、未为比劫为手，子未穿如打算盘拨珠算账。","sec":"十二地支命例","t":"diff"},{"q":"乾造丁乙丙丁／酉巳戌酉（戴笠）中，「戌穿酉，透丙丁羊刃」如何取象其职业特征？","opts":["戌为文库学校，酉为粉笔学生，丙丁羊刃为讲台授课","戌含枪弹穿酉，丙丁羊刃为射出的子弹，酉为被射杀之人","戌为加油站汽车，酉为方向盘，丙丁羊刃为赛车速度","戌为闹市影院，酉为珠宝玉器，丙丁羊刃为装修装潢"],"ans":1,"exp":"戌有枪弹之意，戌穿酉且透丙丁羊刃，丁代表射出去的子弹，酉代表被射杀的人，巳戌一家强化戌力，故以杀人为业。","sec":"十二地支命例","t":"xiang"},{"q":"总结职业与事件取象的「四个层次」，正确的由局部到整体的顺序是什么？","opts":["干支的作用与变化→干支本身相配→整体局象→干支与十神综合","干支与十神综合→整体局象→干支本身相配→干支的作用与变化","干支本身相配→干支与十神综合→干支的作用与变化→整体局象","整体局象→干支的作用与变化→干支本身相配→干支与十神综合"],"ans":2,"exp":"取象四层次：1.干支本身相配；2.干支与十神综合；3.干支的作用与变化；4.整体局象判定。","sec":"五、取象的四个层次（总结）","t":"step"}]},{"n":107,"level":"高级","title":"职业象法二：生意人","qs":[{"q":"命局里承担财富的几类东西，级别由小到大怎么排？","opts":["财星、官杀、食伤","官杀、食伤、财星","食伤、财星、官杀","财星、食伤、官杀"],"ans":3,"exp":"财是养命之源，级别较小；食伤是财之源，比财大；官杀由财所生，是财富升级成权势规模，最大。","sec":"一、先定义：什么可以当财富看","t":"step"},{"q":"定财富级别时，「禄」代表哪一份财富？","opts":["自己能用到花到的那份，不是做大的资本","财升级成权势与产业的那一份财富","可以做大规模的资本，用来扩张业务","财的源头，源头大于水流，级别更大"],"ans":0,"exp":"口诀：财是养命钱，食伤是财源，官杀是财升级，禄是自己享用。","sec":"一、先定义：什么可以当财富看","t":"rule"},{"q":"做生意的命里，印星常常代表什么？","opts":["父母给的祖业遗产和房产","门店、公司、厂子、规模","贵人提携和上级的赏识","读书学历和单位里的工作"],"ans":1,"exp":"做生意的命里，印常常不是读书、不是工作，而是门店、公司、厂子、规模；印在年时门户，有几个印星往往几个厂子。","sec":"二、生意组合的几种基本结构","t":"rule"},{"q":"官杀库不开又无制，这样的命主多走什么路？","opts":["官杀无制主牢狱，不能做事","仍然当官，只是官位不高","不能当官，转而求财做生意","出家修行，不求财也不求官"],"ans":2,"exp":"官杀库不开又无制，不能当官，转而求财做生意。","sec":"二、生意组合的几种基本结构","t":"rule"},{"q":"禄冲财、寅申冲，再逢驿马，是什么组合？","opts":["在单位里当官的格局","技术研发型的企业格局","守着门店稳定经营的格局","做贸易，满世界跑"],"ans":3,"exp":"禄冲财、寅申冲是典型生意组合；逢驿马就是满世界跑、辛苦求财，如进出口贸易。","sec":"二、生意组合的几种基本结构","t":"xiang"},{"q":"劫财合财，对投资和赌博各主什么？","opts":["喜投资好赌，但赌必输，正经生意能赚","喜投资好赌，赌必赢，做正经生意反而不赚","喜赌博必发大财，做正经生意必定失败","不喜投资不好赌，只赚稳定的工资收入"],"ans":0,"exp":"劫财合财，被劫合去的财不做功，所以十赌九输；但做正经生意却能赚，赌与做生意要分开问。","sec":"二、生意组合的几种基本结构","t":"diff"},{"q":"取行业象时，酉金见水一般取什么象？","opts":["车辆出租、物业","酒店、饭店、餐饮","装修、彩绘类","玻璃、化工类"],"ans":1,"exp":"酉金见水有酒店、饭店、餐饮之象；未也有酒店之意。装修彩绘取丙火、车辆出租取申金、化工取子水。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"运中出现丁运、劫运、比劫运，对求财一般怎样？","opts":["比劫引动财库，主利于发大财做生意","比劫是自己的钱，主利于独立创业","帮别人、别人的钱，多主打工或破财","比劫帮身，主财运必定大发，利于做大"],"ans":2,"exp":"天干比劫透出，多为「帮别人」「别人的钱」，主打工、辛苦，或财被劫而破财。","sec":"四、大运流年的应期规律","t":"rule"},{"q":"按应期代换，流年辰到，相当于哪个字到？","opts":["酉","午","申","子"],"ans":3,"exp":"丑到等于申酉到，辰到等于子到：流年用本气所藏之字或同类字来代换，要熟练。","sec":"四、大运流年的应期规律","t":"calc"},{"q":"官杀被运岁引动而不被制，结果一般怎样？","opts":["不是升官发财，而是官非伤病盗贼小人","只主财运好转，与官非伤病无关","升官发财，权势变得更大了些","官杀不被制，反主清闲无事可做"],"ans":0,"exp":"官杀被引动而不被制，不是升官发财，而是官非、伤病、盗贼、小人。","sec":"四、大运流年的应期规律","t":"rule"},{"q":"命局有财库，库不开时怎么论？发财应期在哪？","opts":["财已经在手；运岁闭库时才发财","财不能释放；运岁冲开刑开财库时发财","财已经在手；运岁冲开财库时破财","财不能释放；运岁合闭财库时发财"],"ans":1,"exp":"库不开则财不能释放，运岁冲开、刑开财库就是发财的应期；财库合闭则不利。","sec":"二、生意组合的几种基本结构","t":"rule"}],"fine":[{"q":"在财富定级中，「地支食伤本身含财」与单纯「食伤」相比，级别如何？","opts":["更小，因食伤被财星克制，财源受阻","最小，因地支食伤含财只能供个人享用","相同，因二者都只属于维持生活的养命钱","更大，因食伤库里带着财，源头与结果同在"],"ans":3,"exp":"食伤是财之原神比财大；地支食伤本身含财则更大，因为食伤库里带着财，源头与结果同在。","sec":"一、先定义：什么可以当财富看","t":"diff"},{"q":"做生意的人大致分哪两路？","opts":["一路投资经营开门面，一路开公司做贸易","一路做财务会计，一路做律师执法","一路靠体力打工，一路靠赌博投机","一路入公门当官，一路当教师教书"],"ans":0,"exp":"生意人分两路：一路是投资经营、开门面的；一路是开公司做贸易的（货物流通、产品代理、销售）。","sec":"二、生意组合的几种基本结构","t":"rule"},{"q":"做生意的命局中，印星落在年、时门户且与财发生关联，通常代表什么象？","opts":["父母祖业破败，一生只能替别人打工","自己的店面、公司或厂子，几个印星往往几个厂","婚姻多波折，容易找离异带孩子的对象","必定考取高学历，进入国家机关当官"],"ans":1,"exp":"印落年、时门户就是自己的店面、工厂，有几个印星往往就有几个厂子；印带财合上身几乎都是开店面做生意。","sec":"（一）印的角色：门店、公司、规模","t":"rule"},{"q":"坤造丁癸丁丙／酉卯亥午中，「卯午相破」在职业选择上发出了什么关键信号？","opts":["午禄被破，必须依赖国家单位领取稳定工资","卯午破主官杀混杂，适合进入政法系统执法","卯印工作单位被破，没有单位的命，自己创业","卯印破禄主父母早亡，只能外出学手艺打工"],"ans":2,"exp":"卯代表工作单位，卯午相破使卯被破，所以命主没有工作单位的命，成为自己创业、独资开公司的信号。","sec":"例一：装修彩绘企业（坤造）","t":"rule"},{"q":"坤造丁癸丁丙／酉卯亥午中，为何财富级别偏高且发财几千万？","opts":["癸水七杀合住丙火，比劫帮身直接分夺酉金","酉金财星高透天干，财星旺而独得月令长生","卯木食神生助午火，食伤泄秀而无官杀混杂","亥水官星被卯午包局当财富看，且丁控制酉金生亥"],"ans":3,"exp":"亥水官星被卯、午包局当财富看（最高一级财富），午亥合到自己，且年上丁控制酉金（亥的原神）源源生给自己。","sec":"例一：装修彩绘企业（坤造）","t":"rule"},{"q":"乾造甲甲丙己／寅戌午丑中，为何既能白手起家做家具厂，又能把企业做成规模？","opts":["寅午戌三合制丑库（戌刑丑），伤官坐财库且甲己合印放大","丑土晦火生金，财星透干合身且有比劫护卫","丙火坐午为羊刃，直接冲克年支寅木以劫财求财","己土伤官冲克甲木，破掉印星后转为个体跑贸易"],"ans":0,"exp":"寅午戌三合火局强化戌土，用戌刑制丑土财库做功；时上伤官坐财库生产有技术含量的东西，甲己伤官合印把财富放大成规模。","sec":"例二：高档家具企业（乾造）","t":"rule"},{"q":"乾造丁戊癸壬／未申酉戌中，同一个财星，为何「合在劫财手里」与「合在印上」结果截然不同？","opts":["合在劫财手里升官掌权，合在印上破财赔钱","合在劫财手里十赌九输，合在印上投资成事业","合在劫财手里开厂发财，合在印上赌博必赢","合在劫财手里稳拿工资，合在印上夫妻离异"],"ans":1,"exp":"丁壬合财被劫财合去不做功，故十赌九输；巳从戌出合申酉（财合印），则是投资做生意成事业。","sec":"例三：建筑、建材、酒店（乾造）","t":"diff"},{"q":"乾造甲壬丙辛／寅申申卯中，为何「乙亥运」只是平常运，而「1998戊寅年」却辞职继承父业？","opts":["亥运生旺甲木使比劫夺财；戊寅年丙辛合财自己打工","亥运合住卯木使印星无功；戊寅年戊癸合火化官为印","亥运穿坏寅申冲使交易受阻；戊寅年寅申冲月令父宫","亥运冲开戌库使财星暴发；戊寅年寅午合火克死申金"],"ans":2,"exp":"寅申冲是做贸易往外卖的象，亥运寅亥合而申亥穿，破坏了寅申冲，故为平常运；戊寅年冲到月令申（父亲），遂辞职继承父业。","sec":"例四：门店经营，子承父业（乾造）","t":"rule"},{"q":"乾造甲壬丙辛／寅申申卯何以看出是「继承祖业（子承父业）」？","opts":["日主丙火坐下申金空亡，必须依赖父母接济","时支卯木冲克月令申金，将父亲产业强行夺取","年干甲木高透为祖父，直接合住时干辛金正财","月令财带杀帽为父亲祖上之财，且伏吟到主位"],"ans":3,"exp":"月令申金财带杀帽是父亲祖上的财，日支再见申金（伏吟到主位），且卯申合财合印上身，所以是继承祖业。","sec":"例四：门店经营，子承父业（乾造）","t":"rule"},{"q":"乾造辛庚丙庚／丑子子寅十几岁学木工，到丙申运才自己开工厂，为何早年戌运做木工体力活？","opts":["年上丑伤官带财有一技之长，走比劫墓运戌运多做体力活","时上庚金偏财坐寅木长生，走戌运寅戌拱火主进公门","年上辛金正财合身，走戌运开财库后立刻转型做贸易","日坐子水官星被寅木泄气，走戌运伤官见官被迫学艺"],"ans":0,"exp":"年上丑土伤官带财表示有一技之长，大运走比劫之墓运（戌运），用比劫制财制官杀的多做体力活，故做木工。","sec":"例五：木工起家到多厂老板（乾造）","t":"rule"},{"q":"乾造辛庚丙庚／丑子子寅在丙申运、乙未运开出四个厂，运中「申」与「乙未」如何引动多厂齐开？","opts":["申入丑墓使企业倒闭，乙未运比劫争财使合伙散伙","申把地支全引动开厂，乙合庚财合印，未代表寅开丑库","申合住子水关闭财源，乙木生丙火使命主转行教书","申冲克寅木破掉工作单位，乙木克伤丑土迫使命主改行"],"ans":1,"exp":"丙申运一个申字把地支全引动，故几个厂同时开；乙未运乙合庚（财合印主投资，几个印星几个厂），未代表寅，丑未冲印库开财库。","sec":"例五：木工起家到多厂老板（乾造）","t":"calc"},{"q":"行业拼象：坤造丁癸丁丙／酉卯亥午为何做「装修、外墙彩绘」？","opts":["酉金轻器主首饰，丁火冶炼成器，癸水淬火主珠宝加工","亥水为江海主航运，卯木为舟船，午火为发动机主运输","丙火漂亮落门户，火见水化妆彩绘，亥墨卯文，卯午破手加工","癸水为西药，卯木为中药，丙火为炉灶主医药制造"],"ans":2,"exp":"丙火主漂亮、装饰落门户；火见水有化妆彩绘之意；亥为墨水、卯为文字文章、卯午相破为用手加工，合起来是装修彩绘。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"行业拼象：甲甲丙己／寅戌午丑何以判为「高档家具」企业？","opts":["寅木为公门高楼，戌土为城墙，合局主房地产开发","甲木为纸张，丙火为广告，己土为书本主出版印刷","丑土为寒湿泥巴，己土为水泥，合局主建材矿山","木火成党死木为木材见火漂亮，己伤官得库为一群技术工人"],"ans":3,"exp":"木火成党局，「死木」是木材见火漂亮；门户己土伤官为技艺、得库为一群技术工人，伤官坐财库做有技术含量的东西，甲己合放大成家具企业。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"行业拼象：辛庚丙庚／丑子子寅开了玻璃、化工、木器多个厂，各厂对应的干支象是什么？","opts":["庚寅为木器厂，辛丑为玻璃厂，子水与亥水为化工之象","庚寅为服饰，辛丑为餐饮，子水为航运贸易","庚寅为化工，辛丑为木器厂，子水为玻璃厂","庚寅为玻璃厂，辛丑为化工，子水为木器厂"],"ans":0,"exp":"庚寅为木器厂，辛丑为玻璃厂，子水、亥水为数学和化学，子水有化工之象；一个申字把地支全引动，几个厂同时开。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"行业拼象：坤造辛辛乙庚／亥卯卯辰做金属器材、化工、航运贸易，其「化工」与「金属」各取何象？","opts":["乙木见卯为金属器材，庚金见辰为化工产品与航运","金见亥水为金属玉器秀气物，亥辰包局且辰水库主车船化工","辛金见卯为车船航运，乙木见亥为金属玉器与化工","卯辰穿为金属器材，乙庚合为化工产品与房地产"],"ans":1,"exp":"金见亥水为金属、玉器等秀气的东西；年亥与时辰包局，辰为水库有车船、化工之象，卯辰穿动辰库。","sec":"三、取行业：象的拼合","t":"xiang"},{"q":"大运流年应期中，若原局有「破」的毛病（如卯午破），什么样的运岁反而是最好的运？","opts":["运岁里有字直接冲克相破的其中一个地支","运岁里有字再次伏吟加重原局的相破力量","运岁有字同时合住相破的两边（如未合卯与午）","运岁里有字穿倒相破两支的共同原神"],"ans":2,"exp":"原局有「破」的毛病（如卯午破），运岁里有字同时合两边（如未既合卯又合午）可解决问题，是最好的运（例一丁未运发财几千万）。","sec":"四、大运流年的应期规律","t":"rule"},{"q":"按流年与大运的同类字代换规律，坤造丁癸丁丙／酉卯亥午在戊申运「2009己丑年」为何生意不好？","opts":["丑到等于辰巳到，且丑亥合闭水库","丑到等于未戌到，且己土克坏癸水","丑到等于寅卯到，且丑戌刑坏财库","丑到等于申酉到，且丑午穿坏午火禄神"],"ans":3,"exp":"丑到等于申酉到（地支藏干与同类代换），戊申运己丑年，丑到即申酉到，同时丑午穿坏午火，故生意不好。","sec":"例一：装修彩绘企业（坤造）","t":"calc"},{"q":"乾造甲甲丙己／寅戌午丑在丁丑运「2001辛巳年」自己投资开家具厂，流年辛巳起了什么作用？","opts":["辛表示丑到（开财库），丙辛合财表示自己投资","辛克甲木破掉门店，巳穿寅木表示改行做贸易","辛表示戌到（合闭库），巳亥冲表示离开原单位","巳火冲动申金，辛金化水表示当年与人赌博破财"],"ans":0,"exp":"丁丑运之前丁为劫财主帮别人打工；2001辛巳年，辛表示丑到（丑运开了财库），丙辛合财表示自己投资开厂。","sec":"例二：高档家具企业（乾造）","t":"calc"},{"q":"乾造丁戊癸壬／未申酉戌走「甲辰运」发财，为何「只有甲辰运发财，其他辰运不行」？","opts":["甲木生助丁火偏财，辰土空亡使戌库不再受未土刑","辰冲开戌库，且甲为食伤、戊喜甲，戊甲相见搞地产发财","甲木克坏戊土官星，辰土穿倒未土使印星完全独立","甲木合住己土比劫，辰土合闭酉金印星使财不外流"],"ans":1,"exp":"辰冲开戌财库，且甲为食伤，戊喜甲，戊甲相见会搞房地产；若换其他天干的辰运则无此组合，故只有甲辰运发财。","sec":"例三：建筑、建材、酒店（乾造）","t":"calc"},{"q":"乾造戊甲庚戊／申寅戌寅日坐官杀库不开、财旺拱官、禄冲财逢驿马，其职业与走午运的吉凶分别是什么？","opts":["先当官后下海经商，午运官杀得旺必升官兼发大财","在单位做财务会计，午运财星合身必受上级提拔重用","不能当官而跑商贸，午运官杀被流年穿动必出官非伤病","守着门店做小生意，午运火炼庚金必扩大开几家工厂"],"ans":2,"exp":"日坐官杀库不开不当官，禄冲财逢驿马满世界跑做商贸；午运不适合投资，官杀被流年穿动必出官非、伤病（如糖尿病误诊）。","sec":"六、其余命例要点（对照）","t":"rule"},{"q":"坤造癸戊戊辛／丑午子酉在辛酉运庚辰年，为何被断「不是伤病灾就是官灾」（结果涉案被拘）？","opts":["子午相冲坏印星，庚辰年财星透干克印主车祸破财","戊癸合化火生土，庚辰年比劫夺财主合伙人卷款潜逃","辛金合住丙火，庚辰年食神生财主投资房地产被套","丑与酉包局，庚辰年伤官入墓无自由，行坏运主牢狱"],"ans":3,"exp":"丑与酉包局行坏运有牢狱之象，辛酉运庚辰年伤官入墓（辰为辛伤官之墓库）无自由，故断不是伤病灾就是官灾。","sec":"六、其余命例要点（对照）","t":"rule"},{"q":"坤造辛辛乙庚／亥卯卯辰为何「一生中途改行」，且在「未运被朋友骗破财」？","opts":["辛亥与庚辰两个象主改行；未运中神双现三合不成反破财","乙庚合化金主改行；未运亥卯未三合木局成势大发横财","卯辰穿主破产；未运冲开丑库使官杀透出升官掌权","辛金克乙木主失业；未运土旺生金使企业扩大为多厂"],"ans":0,"exp":"辛亥（金水财务器材）与庚辰（车船化工）两个象，故一生中途改行；未运亥卯未中卯中神双现，三合不成，被朋友骗破财。","sec":"六、其余命例要点（对照）","t":"diff"},{"q":"在判断「财临库地」时，为什么财库不开或被合闭既影响发财，也常应验于父亲？","opts":["财库合闭只影响日主赌博输钱，与父亲寿元毫无关系","财库不开则财不能释放，同时财临库地且闭则父当早死","财库合闭主父亲做大生意，日主只能继承父业打工","财库不开则财归父亲所有，父亲因此长寿且掌管家业"],"ans":1,"exp":"「财临库地父当早死」，财库不开、被合闭（如丑库合子为闭）则父寿有碍；对求财而言，库不开财不能释放，需运岁冲刑开库方发。","sec":"（二）财库、官杀库：开库为发财之机","t":"rule"},{"q":"完整判断一个生意人命局的六个步骤，前三步正确的先后次序是什么？","opts":["先看大运流年开库→再定财富级别→最后看有无做功","先拼具体行业象→看运岁应期→最后再找什么字代表钱","先定什么代表钱定级→看是否有做功→看印在门户还是被破","先看印星旺衰→再看日主喜忌→最后看有没有驿马星"],"ans":2,"exp":"判断步骤：1.先定什么代表钱以定级；2.看是否有做功（制谁合谁、库是否开）；3.看印的位置（门户=门店，被破=自己干）；4.组合性质；5.拼行业象；6.看运岁应期。","sec":"七、判断步骤","t":"step"}]},{"n":108,"level":"高级","title":"职业象法三：老师","qs":[{"q":"老师命里，食伤旺而形成包局，除了代表头脑口才，还代表什么象？","opts":["周围是一群学生","周围是一群同事","周围是一群病人","周围是一群上级领导"],"ans":0,"exp":"食伤既代表头脑、思想、口才，也代表学生；食伤旺而形成包局，就是周围一群学生的象，可以当老师。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"老师象里，哪个天干代表讲台，什么形态最典型？","opts":["丙，光芒四射，火来照土","戊，独阳高透，阳来统阴","己，独阴低伏，阴来承阳","庚，棱角分明，金来制木"],"ans":1,"exp":"戊为高台、讲台，独阳高透，阳来统阴，如一人在高台上讲、学生在下面听，是老师的象。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"十二地支中，哪两个字可以代表学校？","opts":["辰和未","卯和酉","寅和戌","子和午"],"ans":2,"exp":"寅与戌可代表学校：寅为食神又为学堂，戌为食伤库（学生之库），许多老师与这两字关系很大。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"时柱见辛卯，老师象里辛、卯各取什么象？","opts":["辛为书本，卯为讲台","辛为教鞭，卯为粉笔","辛为讲台，卯为书柜","辛为粉笔，卯为教鞭"],"ans":3,"exp":"时见辛卯有老师的象：辛为粉笔，卯为教鞭；书象取己与未，讲台取戊。","sec":"一、老师命的识别条件","t":"xiang"},{"q":"命局金水旺、亥水配印，又是金水伤官，最可能教什么科目？","opts":["数学、物理化学等理科","音乐、书法等艺术科","体育、舞蹈等技能科","语文、英语等文科"],"ans":0,"exp":"木火旺主文、金水旺主理；亥水主数学，亥配印、金水伤官数理能力强，教统计、数学化学。","sec":"一、老师命的识别条件","t":"calc"},{"q":"同样是伤官配印，什么情况能入公门当校长，什么情况只做教师？","opts":["有无财星都能入公门，看日主旺衰","不杂财星能入公门；杂财、财重损格只教书","杂财星才能入公门；不杂财只教书","有无财星都只教书，不会入公门"],"ans":1,"exp":"口诀：伤官配印不见财，才能入公门；见财损格则入学校。财重又甲己合之类，只能做普通教师。","sec":"二、老师与","t":"diff"},{"q":"日支坐官杀库而无功，不能当官，适合做什么？","opts":["做军警最合适","做医生最合适","做老师最合适","做生意最合适"],"ans":2,"exp":"官杀库在坐下、无功，不是当官的命，做老师最合适；辰为杀库不开又不能制服，则不当官也不做生意，以读书、说话为业。","sec":"二、老师与","t":"rule"},{"q":"老师命的应期，伤官合印、食神合杀各应在什么事？","opts":["伤官合印为升职，食神合杀为破财","伤官合印为参加工作，食神合杀为考学","伤官合印为结婚，食神合杀为生子","伤官合印为考学，食神合杀为参加工作"],"ans":3,"exp":"伤官合印、财制印、食神合杀是参加工作、考学、调动的应期；考学要看伤官合印，不是印本身出现。","sec":"三、判断步骤","t":"step"},{"q":"老师命的婚姻，女命与男命各有什么常见规律？","opts":["女命伤官克夫，晚婚多婚常见；男命官印稳定","女命男命都是晚婚，终身不婚","女命男命都是早婚，婚姻稳定","女命官印稳定；男命伤官克妻，多婚"],"ans":0,"exp":"判断步骤里附带看婚姻：女命伤官克夫，晚婚、多婚常见；男命官印稳定。","sec":"三、判断步骤","t":"rule"},{"q":"己与未，在老师象里各取什么象？","opts":["己为讲台，未中藏卯是粉笔","己有书象，未中藏卯是书柜","己为教鞭，未中藏卯是书本","己为学校，未为学生之库"],"ans":1,"exp":"天干己土有书象，地支未中藏卯是书柜；己同时象口，说话为业。讲台取戊，学校取寅戌。","sec":"一、老师命的识别条件","t":"xiang"}],"fine":[{"q":"同是食伤包局的老师命，有「伤官配印成格」与「无印无官只食伤包局」在职务上有何区别？","opts":["配印成格能入公门当校长或教研领导，无印官只单纯教书","配印成格主教理科，无印官专主教文科","配印成格只能教小学，无印官反而能当大学校长","配印成格主改行做生意，无印官主进入政法机关"],"ans":0,"exp":"食伤旺形成包局是一群学生的象；若伤官配印成格能入公门（当校长、教研领导类），只是食伤包局而无印、官则是单纯教书。","sec":"（一）食伤包局：一群学生","t":"diff"},{"q":"在老师象中，「戊坐午（印）」与「伤官在下、戊在上」组合分别表达什么画面？","opts":["戊坐午为工厂门店，伤官在下戊在上为老板管理工人","戊坐午为文职讲台，伤官在下戊在上为老师高讲学生静听","戊坐午为报社编辑，伤官在下戊在上为记者外出采访","戊坐午为武职军营，伤官在下戊在上为学生顶撞老师"],"ans":1,"exp":"戊为高台、讲台，坐午（印）为文职、讲台；伤官在下、戊在上，就是老师高高在上讲、学生在下面静静听讲。","sec":"（二）戊为讲台","t":"xiang"},{"q":"十二地支中，寅与戌之所以常代表「学校」，各自的象理依据是什么？","opts":["寅为财星又为驿马，戌为火库（电器之库）","寅为公门主警察，戌为城墙主牢狱","寅为食神又为学堂，戌为食伤库（学生之库）","寅为阳木主建材，戌为乾位主军火枪弹"],"ans":2,"exp":"十二地支中寅与戌可代表学校：寅为食神又为学堂，戌为食伤库（学生之库）也是文库。","sec":"（三）寅、戌为学校","t":"xiang"},{"q":"除「己土」象口外，十二地支中哪个字「食神落门户」时也取象为唇为口、以说话为业？","opts":["亥水","丑土","申金","辰土"],"ans":3,"exp":"己土同时象口，说话为业；辰土食神落门户为唇为口，同样以说话为业（如高中英语老师丁丙丙壬／巳午午辰）。","sec":"（四）己与未：书","t":"xiang"},{"q":"「木火伤官」的老师在性格与业余爱好上，通常具有哪类特征？","opts":["聪明好学文笔好，喜诗词歌赋弹琴书法，喜自由不喜约束","沉稳内向不善言辞，只喜钻研数字统计与机械计算","循规蹈矩墨守成规，最喜体制内严密纪律约束","脾气阴沉多疑，喜欢暗中算计他人，热衷赌博投机"],"ans":0,"exp":"木火伤官聪明好学，思想活跃，爱好诗词歌赋、文笔好，还喜弹琴书法；喜自由，不喜约束；火旺性急、精力旺盛。","sec":"（六）科目判别：木火主文，金水主理","t":"xiang"},{"q":"伤官配印本喜不见财，若命局见财损格但「财星远隔」，在学历与职业上常有何表现？","opts":["既不能入公门，也绝不可能考上大学，只能初中毕业","虽不入公门当官，但能有高学历而成大学老师","必定放弃教书，转行去做进出口贸易大发横财","反而更能升任中学副校长或教育部门高官"],"ans":1,"exp":"伤官配印成格能入公门，见财损格则不入公门；但财星远隔时（如例三癸辛戊戊／亥酉午午），能有高学历而成大学老师。","sec":"二、老师与「官」的分界","t":"diff"},{"q":"命局中「辰为杀库不开，也不能制服」，在官、商、师三者中应如何取舍？","opts":["虽不做生意，但必在政法军警部门担任要职","官杀无制必主牢狱之灾，一生难有稳定职业","不会当官，也不会做生意，以读书、说话为业当老师","虽不当官，但必辞职下海开办多家工厂做生意"],"ans":2,"exp":"辰为杀库不开，也不能制服，不会当官，也不会做生意，只能读书、说话为业（如高中英语老师）。","sec":"二、老师与「官」的分界","t":"rule"},{"q":"判断老师命的五步流程中，在「找学校/讲台/书/说话象」与「看官路」之间，夹着哪一步？","opts":["看运岁（考学、参加工作应期）","看婚姻（女命克夫，男命稳定）","看财富级别（财、食伤、官杀定级）","定科目（木火主文，金水主理）"],"ans":3,"exp":"判断步骤：1.看食伤包局/库/门户；2.找学校/讲台/书/说话象；3.定科目（木火主文、金水主理）；4.看官路；5.看运岁；6.附带看婚姻。","sec":"三、判断步骤","t":"step"},{"q":"乾造戊戊甲己／午午子巳，为何「2009己丑年想调工作未成」，而「2010庚寅年可以成」？","opts":["己丑年丑午穿且拱旺杀星难制；庚寅年庚冲甲为动，寅穿巳合午换校","己丑年伤官见官惹是非；庚寅年印星入墓彻底辞职下海","己丑年子丑合闭了财库；庚寅年申金冲寅木被迫调离","己丑年财星合身不想走；庚寅年寅午合火克死子水才离职"],"ans":0,"exp":"己丑年子丑合想调工作（甲己合要送礼），但丑午穿、巳丑拱旺杀星无法得制故不成；庚寅年庚冲甲（动），寅穿巳合午，离开一校到另一校。","sec":"例一：文类小学教师（乾造）","t":"calc"},{"q":"乾造戊戊甲己／午午子巳在辛酉运为何迟迟结不了婚？","opts":["酉运生旺子水官星，日主一心只想当官","酉运同时引发午酉破与子酉破（破坏夫妻宫）","酉运冲克卯木羊刃，对象出现意外伤病","酉运合住辰土食神库，命主无心恋爱"],"ans":1,"exp":"此造晚婚命，行辛酉运时，午酉破、子酉破（破坏日支夫妻宫），所以结不了婚，要到壬戌运婚姻才成。","sec":"例一：文类小学教师（乾造）","t":"calc"},{"q":"坤造己丙庚癸／未寅戌未在戊辰运，为何1997丁丑年没考上大学，1998戊寅年补考考中？","opts":["丁丑年癸水被己土克死；戊寅年丙火长生才考中","丁丑年伤官入墓；戊寅年寅木冲开申金才考中","丁丑年三刑没考上，戊寅年戊癸合（伤官合印）考中","丁丑年丙辛合财；戊寅年寅午戌三合火局才考中"],"ans":2,"exp":"戊辰运戊癸合伤官合印是考学读书之象；1997丁丑年官坐印且丑戌未三刑故落榜；1998戊寅年戊癸合，伤官合印利于名而考中。","sec":"例二：中学教师（坤造）","t":"calc"},{"q":"坤造己丙庚癸／未寅戌未中，为何父亲在「2003癸未年」意外身亡，且命主一直没怀孕？","opts":["丙火父星在戌运入墓，癸未年水克火应期；寅木克未土故难孕","庚金父星在寅绝地，癸未年财星虚透；未土合住卯木故难孕","己土父星被癸水冲克，未年三刑；戌土空亡故难孕","寅父逢年时两头未墓无原神，未年墓到应期；癸伤官落未焦干难孕"],"ans":3,"exp":"寅为父，原局年时逢未墓（两头墓）且无原神生，癸未年未墓到应期；伤官癸水为子女，落在未地被火土焦干，故生育困难。","sec":"例二：中学教师（坤造）","t":"calc"},{"q":"坤造癸辛戊戊／亥酉午午为何自己挣钱养活老公，且2009己丑年离婚后「不会再结、独身过」？","opts":["亥中壬财生甲杀老公故养夫；坐下印旺泄官气个性独立，不在乎婚姻","酉金食神生助癸水故养夫；戊土比肩争夫彻底厌恶男性","午火羊刃克坏酉金故养夫；亥水空亡表示终身没有正缘","亥水官星被午火克死故养夫；辛金伤官高透主克夫绝情"],"ans":0,"exp":"亥里壬财是她的钱、甲杀是老公，甲杀受壬财生故她养老公；己丑年丑午穿坏夫妻宫、甲己合争夫而离，因坐下印旺能泄官气，个性独立故独身过。","sec":"例三：高校外语老师（坤造）","t":"xiang"},{"q":"坤造辛甲戊丙／酉午午辰中，如何用「阴包阳局」与「辰酉合」拼出老师上课的画面？","opts":["辛为粉笔，酉为钟表，午为心脏，老师严格按时间监督学生考试","戊为高台讲台，伤官为学生，辰代表低处，老师高高在上、学生下听","丙为太阳光照，甲为大树，辰为水库，老师带领学生户外实践","甲为高官，戊为城墙，辰酉合化金，老师在学校兼任行政领导"],"ans":1,"exp":"伤官配印形成阴包阳局，戊为高台象讲台，伤官为学生，辰酉合且辰代表低处，正好构成老师高高在上、学生下面静静听讲的画面。","sec":"例四：数学老师（坤造）","t":"xiang"},{"q":"坤造辛甲戊丙／酉午午辰为何以后能「改行做生意发财」（或嫁生意人老公）？","opts":["丙火印星合身，行未运三合木局把学校做成连锁企业","甲木七杀制身，行寅运冲动申金跑进出口贸易发财","辰为财库原局不开，行戌运冲开辰库发财，亥子运引出辰财","酉金伤官生财，行申运比劫帮身直接开厂做大生意"],"ans":2,"exp":"辰为财库，原局辰库不开财不能释放；行戌运冲开辰库发财，后接亥子大运都能引出辰中之财与主位关联；不改行则嫁旺财生意人老公。","sec":"例四：数学老师（坤造）","t":"calc"},{"q":"坤造辛甲戊丙／酉午午辰在申运、丁酉运皆不成婚，为何要到「戊戌运（39岁后）」才成婚？","opts":["申运财星入墓、丁酉运比劫争夫；戊戌运戌冲开辰库才遇正缘","申运官星绝地、丁酉运伤官见官；戊戌运甲木透干合住戊土","申运冲克寅木、丁酉运午酉破；戊戌运寅午戌三合才见夫妻星","申运伤官旺、丁酉运酉破婚姻宫午；戊戌运戌穿倒伤官不再坏官"],"ans":3,"exp":"辛克甲伤官克夫严重，申运伤官旺地，丁酉运酉直破婚姻宫（午），两步运皆不成婚；戊戌运戌土穿倒伤官（酉），不再坏官才有婚姻。","sec":"例四：数学老师（坤造）","t":"calc"},{"q":"乾造乙己辛己／卯丑酉亥高学历且为大学统计学老师，其「爱读书、成绩好」与「教统计学」分别取何象？","opts":["己为书配亥伤官为爱读书，己印包局为学校，时上亥水主数学","乙木为纸配卯财为爱读书，丑土杀库为学校，时上亥水主外语","辛金为笔配酉禄为爱读书，己土高台为讲台，丑土墓库主物理","卯酉冲为思维活跃，乙己相克为辩论，丑亥拱水主历史文学"],"ans":0,"exp":"己为书象、伤官为思想，己亥相配故爱读书成绩好；己印包局代表学校、己象口，时上亥水表示数学，数理能力见长故教统计学。","sec":"例五：大学老师（乾造）","t":"xiang"},{"q":"乾造乙己辛己／卯丑酉亥中，辛酉见丑本为入墓，为何反而「不被墓所困，工作轻松一生平稳」？","opts":["酉丑半合金局，把墓库直接转化为日主的禄神","卯酉相冲是旁边开墓，进出自如，且禄印相随","乙木克破己土，使印星失去墓库之力而完全自由","亥水冲开丑墓，使辛酉金水相涵，不受墓库约束"],"ans":1,"exp":"辛酉见丑本为入墓，但有卯酉相冲在旁边开墓，则进出自如，不被墓所困；加之禄印相随，故工作轻松、一生平稳。","sec":"例五：大学老师（乾造）","t":"rule"},{"q":"乾造乙己辛己／卯丑酉亥在乙酉运处情人且最终被比肩所夺，盘中「卯（乙）」与「亥」在婚姻上各代表什么？","opts":["卯为妻子（禄冲财得正妻），亥为情人（伤官暗藏无名分）","卯为父母安排的对象，亥为自己自由恋爱但无缘成婚的人","卯为情人（透乙坏印无结婚证书），亥为妻子（亥配印有证书）","卯为前妻（冲夫妻宫必离），亥为继室（印星合身带孩子）"],"ans":2,"exp":"卯酉冲以卯为情人，以亥为妻子（亥配印，印为结婚证书，卯透乙坏印星故无证书）。乙酉运情人乙坐比肩而来，最终被比肩所夺，晚婚找亥。","sec":"例五：大学老师（乾造）","t":"diff"},{"q":"坤造庚乙乙庚／戌酉卯辰为初中生物老师，盘中「对学生负责」与「多婚」分别对应什么结构？","opts":["辰为水库主包容故对学生负责；伤官见官无印化解主多婚","庚为七杀主严格故对学生负责；财星合身太重克印主多婚","卯为禄神主勤劳故对学生负责；日主坐下空亡无依主多婚","戌食伤库有用主负责；官杀包局加比劫争夫多婚"],"ans":3,"exp":"戌为食伤库是命局最有用的字，故对学生负责；庚戌、酉、庚辰官杀包局，夫妻宫被坏（酉戌穿、卯辰穿）再加比肩争夫，故多婚。","sec":"五、其余命例要点","t":"xiang"},{"q":"坤造丁丙丙壬／巳午午辰（高中英语老师）在「庚寅年」考上研究生，此年寅木与原局的「印」各主什么？","opts":["庚寅年为印星长生而考研究生，原局印在此兼主房子","庚寅年为伤官见官而考研究生，原局印在此兼主子女","庚寅年为财星临绝而考研究生，原局印在此兼主配偶","庚寅年为比肩夺财而考研究生，原局印在此兼主车辆"],"ans":0,"exp":"满盘火局，庚寅年印星（寅木）长生而考上研究生；且教材指出在此例中「印为房子」。","sec":"五、其余命例要点","t":"calc"},{"q":"坤造壬辛庚辛／辰亥辰巳（加拿大美女老师）为何能成为「教务管理人员」且「桃花旺」？","opts":["巳火七杀坐禄主严格，庚金日主坐辰主学校；戊土高透主貌美","食神墓库辰为学校，时上配杀巳亥冲为功、亥从辰出成管理；金水相逢主貌美","壬水伤官合身主口才，巳火正官合辰主学校；木火通明主貌美","辛金比劫包局主竞争，辰土印星生庚主管理；财星透干主貌美"],"ans":1,"exp":"金水伤官喜见官，食神为学生、辰土为食神墓库为学校，时上配杀巳亥冲为功、亥从辰出成为教务管理人员；「金水若相逢，必招美丽容」且比劫争夫桃花旺。","sec":"五、其余命例要点","t":"xiang"}]},{"n":109,"level":"高级","title":"职业象法四：公务员","qs":[{"q":"官杀没有被制服就合到日主身上，盲派怎么论？","opts":["合身就是升官，不论有制无制","自己合一个毛病上身，一生灾祸连连","官杀有力，合身即主大贵显达","官杀被合住，反而一生清闲平安"],"ans":1,"exp":"官杀有制再合身，才是我管理控制；无制而合，等于把毛病合到自己身上。","sec":"二、官位大小怎么看","t":"rule"},{"q":"公务员命里印星落在年上、与日主隔得远，权力如何？","opts":["印远隔主升得特别快，官运亨通","印在年上只影响学历，不影响官位","用之不得力，没什么权力","印远隔反而权力更大、升得快"],"ans":2,"exp":"印要用得上才有权，隔得远就用之不得力。","sec":"二、官位大小怎么看","t":"rule"},{"q":"官星合到的是比劫（别人的官），一般怎么论？","opts":["主在外地升迁，有调动","必定丢官，仕途中断","官位最高，自己掌握实权","官是别人的，只能当副手"],"ans":3,"exp":"合到别人的官只能当副手；若能合到自己身上，才是自己升官。","sec":"二、官位大小怎么看","t":"diff"},{"q":"官职升不高的典型组合是？","opts":["财透生官、官制不好、运又走财生旺官","子辰一家包局，官杀有制成功","官杀库在日支下又被冲动发用","官杀有制、食伤包局、权力集中"],"ans":0,"exp":"财生官而官无制，官越旺越难控制，升不高；包局、库被冲动则是权力大的象。","sec":"二、官位大小怎么看","t":"rule"},{"q":"官杀库坐在日支下、被冲动，一般怎么论？","opts":["官库被冲，主丢官、官位不保","坐下官杀发用，有权力","冲动只主调动，不主有权力","库被冲破，官位不稳、没有权力"],"ans":1,"exp":"官杀库在坐下被冲动，官杀发用，权力就出来了。","sec":"二、官位大小怎么看","t":"rule"},{"q":"盲派以哪两个字代表公门？","opts":["卯与乙","子与壬","寅与甲","申与庚"],"ans":2,"exp":"寅与甲在命局中占重要地位，是看公务员命先要找的字。","sec":"一、公务员命的基本组合","t":"rule"},{"q":"阳制阴局（甲、丁制辰、丑）的公务员，多在哪类部门？","opts":["财政、税务、审计","乡镇党委、基层政府","组织、人事、编制","公安、检察院、纪检"],"ans":3,"exp":"辰丑为阴为牢狱，甲丁为阳为光明正义，所以多在公安检察纪检一类。","sec":"三、不同部门的象","t":"xiang"},{"q":"伤官配印、寅与未包局、财制印得权，多是哪类部门？","opts":["权力部门（市委办、组织部）","公安、检察、纪检部门","财政、税务、审计部门","后勤、总务、行政部门"],"ans":0,"exp":"寅主公门，未与寅同象表权力，财制印得权，所以是权力部门。","sec":"三、不同部门的象","t":"xiang"},{"q":"判断公务员命，先后顺序是？","opts":["先排应期，再找公门，最后看做功","先找公门，再看做功，再判职务大小","先判部门，再看做功，最后找公门","先看婚姻六亲，再定职务大小"],"ans":1,"exp":"步骤是公门→做功→职务大小→部门→应期→复核婚姻六亲。","sec":"四、判断步骤","t":"step"}],"fine":[{"q":"公务员命局中出现的「财」，核心代表什么，且需满足什么条件才为公门俸禄？","opts":["代表权力，须坐于宾位且与印星完全隔绝","代表工资，须与主位发生关系为日主所用","代表外快，须透出天干且被比劫直接分夺","代表私产，须落在年上且不与日主发生关系"],"ans":1,"exp":"公门命局中的财表示工资，必须和主位发生关系、为日主所用，才算捧上公门饭碗。","sec":"一、公务员命的基本组合","t":"rule"},{"q":"同样是年月见官星或印星，如何区分「为日主所喜」有公职与「与公门无缘」？","opts":["官印旺相即为日主所喜，衰弱无根则与公门无缘","印在年上即为日主所喜，官在月上则与公门无缘","做功中被用到或合到主位为喜，为忌且不联主位则无缘","官印透干即为日主所喜，藏于地支则与公门无缘"],"ans":2,"exp":"盲派所说的「喜」，是指官印在做功中被用到或合到主位；若官印为忌且与主位无涉，则与公门无缘。","sec":"一、公务员命的基本组合","t":"diff"},{"q":"除年月官印、杀库及寅甲入局外，哪种成格结构也是公务员命的常见组合？","opts":["比劫争财透干","羊刃驾杀无制","食神生财入墓","伤官配印入格"],"ans":3,"exp":"伤官配印入格，以印制伤官、主文笔才华与管束权，是公务员命的常见结构。","sec":"一、公务员命的基本组合","t":"rule"},{"q":"公务员命局出现「伤食混杂、不见官杀」时，对其官职层级有何影响？","opts":["官职不大，难掌高权","权力极大，多为一把手","一生灾祸连连且丢官","必进执法部门掌重权"],"ans":0,"exp":"伤食混杂又不见官杀，做功不专一、缺官杀实权，往往只是科级等中小职务，官职不大。","sec":"二、官位大小怎么看","t":"rule"},{"q":"命局中出现「食伤包局」或「子辰一家包局」时，通常主官位权力如何？","opts":["被困受制，只能当副手","包局成势，权力较大","杂气混局，职务升不高","远隔无力，没什么权力"],"ans":1,"exp":"食伤包局或子辰一家包局，主势力集中、控制范围广，故主权力较大。","sec":"二、官位大小怎么看","t":"rule"},{"q":"命局中忌神（如戊日见乙木为忌）透出或占月令时，仕途上常见什么表现？","opts":["适合去公安检察等执法部门","专管财政大权，掌握国家钱库","常犯小人，受领导压力，职务不高","得贵人提拔，升迁迅速无阻"],"ans":2,"exp":"忌神在月令或透干（如乙木为忌），主常犯小人、受领导压制、做事不顺，故职务难升很高。","sec":"二、官位大小怎么看","t":"rule"},{"q":"原局出现「别人的官」（如劫财坐官）时，怎样才可能变成自己升官而非只当副手？","opts":["坐下官星远隔年上，与比劫互不发生作用","比劫透干生旺官星，让别人力量更强","财星透干去生比劫所坐之官，形成官旺格","冲去别人或把别人的官合到自己身上"],"ans":3,"exp":"别人的官若只合到比劫，就只能当副手；若通过岁运冲去别人并合到自己主位，就是自己得官升职。","sec":"二、官位大小怎么看","t":"diff"},{"q":"公务员命局中「木火伤官而见丑为钱财」，多对应管理哪一类政府部门？","opts":["财政、税务部门","乡镇、街道党委","公安、检察部门","组织、宣传部门"],"ans":0,"exp":"丑为阴财、钱财，木火伤官与丑财做功，主管理财政、税务等管钱部门。","sec":"三、不同部门的象","t":"xiang"},{"q":"同为甲木，盲派在行业象法中如何区分「甲辰活木」与「甲戌死木见火」？","opts":["甲辰活木主乡镇一把手，甲戌死木见火主银行高管","甲辰活木主公家的财，甲戌死木见火多主家具装修","甲辰活木主文笔秘书，甲戌死木见火主纪检监察","甲辰活木主公安执法，甲戌死木见火主财政税务"],"ans":1,"exp":"甲辰为活木带财库，代表公家的财（财政部门）；甲戌为死木，见火多则为木材加工、家具装修之象。","sec":"三、不同部门的象","t":"diff"},{"q":"「食伤制杀局」的公务员，大多数集中在什么性质的部门？","opts":["文秘、档案、宣传等文职部门","后勤、总务、基建等保障部门","公安、检察、纪检等执法部门","财政、税务、审计等管钱部门"],"ans":2,"exp":"食伤制杀是以我制官杀，对应管人、执法的权力，因此大多数在公安、检察院、纪检等执法部门。","sec":"三、不同部门的象","t":"xiang"},{"q":"命局见「双寅穿巳、寅发用，杀带财帽合印」，多对应哪类官职之象？","opts":["市政府专职文秘人员","检察院核心办案人员","税务局专业财税干部","乡党委书记等地方主官"],"ans":3,"exp":"杀带财帽合印主权力与工资，双寅穿巳发用主权力发威，在职业象法中多对应乡党委书记之类。","sec":"三、不同部门的象","t":"xiang"},{"q":"年上财库（如年柱见辰财库）由主位透出的官杀所控制，在公务员命里主什么象？","opts":["管理国家或公家的钱","自己私下经商发大财","专管组织人事与编制","只享虚名而无实权"],"ans":0,"exp":"年为宾位、国家，财库在年上且被主位透出的官杀控制，说明管理的是国家或公家的钱财。","sec":"三、不同部门的象","t":"xiang"},{"q":"推算公务员应期时，「参加工作」与「职务提升」最常见的引动方式分别是？","opts":["参加工作多比劫克财，提升多伤官透干克破印星","参加工作合动官印或入公门，提升多官星印库被冲穿合开","参加工作多官印入墓闭库，提升多财星远隔主位","参加工作多印星受冲破，提升多官杀无制直接合身"],"ans":1,"exp":"参加工作多应合动官印或走公门字（如寅运当兵入公门）；提升则需官星或印库被冲、穿、合开而发用。","sec":"四、判断步骤","t":"step"},{"q":"判断公务员应期时，岁运出现什么情况往往对应「退休或丢官」？","opts":["食伤合官且印库被冲开","官杀库在坐下被冲动发用","官印被破，或印星不再受生扶","岁运合动官星并引向主位"],"ans":2,"exp":"官印是公门饭碗的根基，一旦岁运破了官印或断了印星生源，就容易应退休、离职或丢官。","sec":"四、判断步骤","t":"step"},{"q":"戊土为日主时，喜生甲寅时，从象法上看「财星转化为杀星」说明什么？","opts":["财星受损导致只能从事文职","官杀无制必致一生灾祸连连","印星远隔主位难以进入公门","杀代表更大级别的财富与权力"],"ans":3,"exp":"甲寅时中财星生扶并转化为七杀，杀为更大级别的财富，若落在宾位且受我控制，便是管公家大财的权力。","sec":"五、命例详解","t":"rule"},{"q":"原局「阴重而无阳、合多安静」的公务员命局，往往需要什么岁运才能提升调动？","opts":["阳的年份或大运去冲动它","财星虚透而不见官杀之年","三合水局消解原局墓库","阴湿的年份继续合住印库"],"ans":0,"exp":"阴重无阳、合多太静则做功不显，往往需要阳的年份冲动原局（如壬午冲子、丙戌冲辰），方能调动提升。","sec":"五、命例详解","t":"rule"},{"q":"命局中出现「丑、子俱入辰墓」时，为什么不仅不是凶象，反而主权力提升？","opts":["入墓代表彻底退休，不需再劳心费力","入墓本身就是做功，且丑变辰有放大的意思","子水冲去辰土官库，主脱离公职去投机","辰土冲开丑土财库，主私下经商发大财"],"ans":1,"exp":"坐下丑印入时上辰墓，入墓本身就是做功手段；且小库（丑）变大库（辰）有放大权力管辖的意思。","sec":"五、命例详解","t":"diff"},{"q":"大运或原局见「印禄相随」（如坐禄又有印生），不论男女通常主什么？","opts":["官杀无制，容易惹上官非牢狱","投机破财，频繁更换工作单位","运气不差，不辛苦劳累，工作稳定","奔波劳碌，一生多犯小人是非"],"ans":2,"exp":"印禄相随（如辛酉运酉禄得辰土印生），只要见禄有印生，无论男女运气都不差，工作稳定且不辛苦。","sec":"五、命例详解","t":"rule"},{"q":"八字中出现「甲木七杀」，「甲多」与「只有一位甲」在遇己土合杀时有何区别？","opts":["甲多遇合主犯小人破财，一位甲遇合主掌财税大权","无论甲多或只有一位，逢己土合杀一概主降职","甲多遇合主丢官罢职，一位甲遇合主连升三级","甲多不怕合反主提升，只有一位甲则不喜合"],"ans":3,"exp":"甲多为杀旺，逢己土劫财合杀反主提升得权；若原局只有一位甲木，被劫财合走则不喜。","sec":"五、命例详解","t":"diff"},{"q":"命局中「庚申运」遇「申子辰三合水局」，为何会让以「丑入辰墓」做功的公务员降职？","opts":["三合水局消解了辰土，使辰不能墓丑做功","庚金冲克甲木印星，导致印星远隔无力","三合局冲动夫妻宫，引发婚姻破裂连累仕途","申金生助子水财星，导致财旺生官难制"],"ans":0,"exp":"原局全靠丑入辰墓做功，申子辰三合水局把辰土化成水，消解了辰墓丑的做功，故不仅不升还可能降职。","sec":"五、命例详解","t":"rule"},{"q":"地支「两丑夹穿午火（群阴包一阳）」，为何反而不坏午火并能成为贵格？","opts":["午火被彻底穿灭，形成纯粹阴局而当大官","夹穿穿不坏反显独阳之贵，须阳透天制阴主权","午火冲走两丑财库，代表辞去公职下海经商","丑土直接生助午火，形成火土伤官生财格"],"ans":1,"exp":"群阴包一阳，两丑夹穿穿不坏午火，反显独阳之贵；再配年月甲丁阳透制辰丑阴，便成阳制阴主权贵局。","sec":"五、命例详解","t":"xiang"},{"q":"当公务员命局见年上比肩、且日主是「借比肩之象而用」时，职务层级往往如何？","opts":["独揽全权，必定成为地区一把手","完全无官运，只能终身从事体力劳动","官位借别人象而用，通常只当副手","直接掌管财政大权，升迁至正处级"],"ans":2,"exp":"年上见比肩而日主借象用之，权柄非自己独专，所以一般只能当副手。","sec":"六、其余命例要点","t":"rule"},{"q":"大运走「壬辰运」，官归于印库（辰收丑入墓），在仕途上一般有什么象义？","opts":["伤官见官，主犯小人且官司缠身","官星入墓，主被免职或退居二线","印库闭塞，主只得虚名而无实权","官归印库，主权力与管辖范围放大"],"ans":3,"exp":"原局丑官被大运辰土印库收墓，官归于印库是权力放大的象，主实权升迁；若是官星虚透无根则只虚名。","sec":"六、其余命例要点","t":"rule"},{"q":"命局中「己土食神为书，甲己合」在公务员命象中常体现为何种个人特征？","opts":["喜欢读书学习","专搞股票投机","频繁换单位调动","脾气暴躁好斗"],"ans":0,"exp":"食神主思想才华与书本，己土食神为书、甲己合为读书之象；若兼见甲丁与阴财，还可有玄学占卜之能。","sec":"六、其余命例要点","t":"xiang"}]},{"n":110,"level":"高级","title":"职业象法五：部队军官","qs":[{"q":"按盲派，军官命局里比劫羊刃库、寅戌、申各代表什么象？","opts":["比劫羊刃库为兵营；寅戌为军警；申为武库","比劫羊刃库为武库；寅戌为兵营；申为军警","比劫羊刃库为兵营；寅戌为武库；申为军警","官杀库为兵营；寅戌为武库；申为军警"],"ans":2,"exp":"比劫库有兵营、部队之意；寅戌为武库，戌本意是火药、枪支、炮弹；申为军警，常见火金相克。","sec":"一、军官的特殊组合","t":"xiang"},{"q":"申为军警，要成军官之象，申需要出现什么组合？","opts":["木火相生，如寅午戌成局","金水相生，如申子辰成局","水木相生，如亥卯未成局","火金相克，如丁制辛、午制申"],"ans":3,"exp":"申为军警，出现火金相克的组合（丁制辛、午制申）成军官。","sec":"一、军官的特殊组合","t":"rule"},{"q":"按盲派，军官里印星为权力，权力的做功方式是什么？","opts":["制印得权，即财制印","官杀生印，杀印相生而已","食伤泄印，伤官见官","印生比劫，比劫护身"],"ans":0,"exp":"制印得权（财制印）是军官最常见的做功；伤官配印、杀印相生也是权力象。","sec":"一、军官的特殊组合","t":"rule"},{"q":"盲派看军衔高低，什么样的命局军衔较高，什么样官职不大？","opts":["单层功军衔较高；包局太多反而不大","印官杀食伤包局高；伤食混杂小","比劫成林军衔较高；财星太旺官职不大","印星太旺军衔较高；官杀混杂官职不大"],"ans":1,"exp":"官位高低看包局：印包局、官杀包局、食伤包局军衔较高；单纯伤食混杂则官职不大。","sec":"二、军衔与升迁的判断","t":"diff"},{"q":"盲派所说「过河拆桥」之功是什么意思？","opts":["冲开官库，把别人的权力引到自己","制去自己用完的比劫，权力集中","冲穿别人的官或用完的神，位置留给自己","合住别人的官，让官位转给自己"],"ans":2,"exp":"过河拆桥是用一个字冲穿别人的官或自己已用完的用神，让官位空出来留给自己；如丑午穿、子午冲、丑未冲。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"「贼捕结构」里，贼神与捕神分别是什么？","opts":["官星为贼神，印星为捕神","比劫为贼神，财星为捕神","制者为贼神，被制者为捕神","被制者为贼神，制者为捕神"],"ans":3,"exp":"贼神是被制者、捕神是制者；制局中被制的神喜欢到位，如辰为贼神、戊为捕神，辰到则制神有对象，升职。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"原局有戊制辰的制局，行运见辰到，按盲派是什么应期？","opts":["贼神到位，制神有对象，利升职","比劫到位，争夺官位，主降职","官星入墓，官位被收，主转业","印库被冲，权力受损，主降职"],"ans":0,"exp":"辰为贼神、戊为捕神，被制的辰到位，捕神有对象可制，是升职之象。","sec":"二、军衔与升迁的判断","t":"calc"},{"q":"盲派看军官升迁，见到什么情形就要升官？","opts":["比劫出现，或印到被生、官杀合身而旺","戊土出现，或印到被制、官杀被制化","戊土被克，或印库被冲、官杀到位无制","食神出现，或印到被合、财星入库较旺"],"ans":1,"exp":"见戊土是做功重要字；戊出现，或印到被制、印库出现、官杀出现被制化，就要升官。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"同一原局，运岁里出现什么情形，军官会升迁停滞甚至转业？","opts":["财星制印被引动的大运","比劫帮身、官杀得助的大运","印被穿、做功被破的大运","印被合住而官星得力的大运"],"ans":2,"exp":"印被穿、做功被破的大运，升迁停滞，甚至变成闲职或转业。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"盲派看军官的步骤，前几步的正确顺序是什么？","opts":["先排应期，再找武象，再找权力，再定军衔","先找权力，再找武象，再定军衔，再排应期","先定军衔，再找武象，再找权力，再排应期","武象、权力、军衔、应期"],"ans":3,"exp":"先找武象（比劫羊刃库、寅戌、申、火金相克），再找权力（印、官杀、杀库，谁制谁），再定军衔级别，再排升职应期，后看转业退休与婚姻。","sec":"三、判断步骤","t":"step"},{"q":"盲派看军官转业、退休，看哪些信号？","opts":["官合入比劫，印被破，做功被破","官星被冲，比劫被制，运入印库","印星被生，官杀有制，运入财地","财星被合，食神入库，印星生旺"],"ans":0,"exp":"转业退休看官星合入别人（比劫）、印被破、做功被破，或运入「官非」。","sec":"三、判断步骤","t":"rule"},{"q":"军官命局做功多用冲穿，对婚姻有什么影响？","opts":["冲穿越多，夫妻宫越稳固，家宅平安","多伤妻星夫妻宫，婚姻多波折","与婚姻无关，只影响官位升迁快慢","只影响子女宫，不影响妻星与夫妻宫"],"ans":1,"exp":"做功用的是穿、冲，多与妻星、婚姻宫相关，所以军官婚姻多波折；复核时注意夫妻宫、妻星是否被穿冲。","sec":"六、本章小结","t":"rule"}],"fine":[{"q":"十二地支中「戌」作为武库，在部队军官取象中其本意代表什么？","opts":["钱财、账本、算盘，主财务","文件、印章、档案，主文职","火药、枪支、炮弹，主军营","车辆、道路、桥梁，主交通"],"ans":2,"exp":"戌为火库，在武官象法中本意是火药、枪支、炮弹，所以主军营、部队。","sec":"一、军官的特殊组合","t":"xiang"},{"q":"部队军官与普通公务员在命局组合上的共同点与核心区别分别是什么？","opts":["同在伤官见官，别在必须印星远隔且无制","同在食伤生财，别在必须见到子未相穿与丁壬合","同在财库冲开，别在不能出现任何比劫与羊刃","同在官印做功，别在比劫羊刃库、寅戌武库及火金相克"],"ans":3,"exp":"军官与公务员都有官印、杀库带财参与做功；区别在于军官有比劫羊刃库、寅戌武库、申为军警及火金相克。","sec":"一、军官的特殊组合","t":"diff"},{"q":"判断军官军衔高低，除了看印、官杀或食伤是否包局，还要看什么？","opts":["包局的层数（一层功或两层功）与有无杂乱","日主出生季节是否处于旺相的春夏两季","八字中正财与偏财的数量是否超过三个","命局中是否完全没有出现冲穿刑害"],"ans":0,"exp":"定军衔级别要看包局层数（一层功或两层功）以及局中有无伤食混杂等杂乱情况。","sec":"二、军衔与升迁的判断","t":"rule"},{"q":"原局以「戊戌控制癸亥」为一层功，时柱「卯」再来控制「戌土」加码，这种两层功主什么？","opts":["做功互相抵消，只能当普通士兵","加码做功层级，军衔级别很高","比劫争夺权力，必定中年转业","印星被彻底穿坏，无任何职务"],"ans":1,"exp":"卯控戌是一层功，戊戌控癸亥又是一层功，两层功加码做功层级，军衔级别可达军级。","sec":"二、军衔与升迁的判断","t":"calc"},{"q":"断部队军官命局时，定完军衔级别并排完升职应期之后，接着应看什么？","opts":["先看能否下海经商，再断偏财运势","先定学历高低，再看父母寿元长短","看转业退休，再复核婚姻与子女","先找武象，再看谁制谁的权力关系"],"ans":2,"exp":"判断步骤依次为：找武象→找权力→定军衔→排升职应期→看转业退休→复核婚姻与子女。","sec":"三、判断步骤","t":"step"},{"q":"复核军官命局的婚姻时，为什么尤其要重点检查夫妻宫与妻星是否被穿冲？","opts":["军官命局必须夫妻宫被穿冲，婚姻才能稳定","穿冲夫妻宫只代表频繁调动，不涉及感情","只要军衔够高，妻星被穿冲也不会影响婚姻","军官做功多用穿冲，常把婚姻波折当作代价"],"ans":3,"exp":"军官升迁做功往往依赖「穿」「冲」，而这些穿冲常落在妻星或婚姻宫上，因此婚姻多波折。","sec":"三、判断步骤","t":"rule"},{"q":"原局有「未土」比劫羊刃库，早年行「戌运」逢「丁卯年」时，为何常应「当兵进军营」？","opts":["戌运刑开比劫羊刃库，卯年引动未库进军营","戌运彻底穿坏印星，卯年代表被迫提前退休","戌运冲去官杀星，卯年代表下海经商发财","戌运合住夫妻宫，卯年代表考上地方大学"],"ans":0,"exp":"未为比劫羊刃库主兵营，戌运刑开未库，流年丁卯引动未库，正应踏入军营当兵。","sec":"四、命例详解","t":"rule"},{"q":"己酉运中，官星酉戴财帽，且天干「甲己合」、地支「辰酉合」，在升迁上说明什么？","opts":["财星生旺忌神，属于降职处分的运","官星与日主产生关联，属于有升职机会的运","官星被彻底合走，属于必须转业的运","比劫争夺官位，属于只能当闲职的运"],"ans":1,"exp":"官星带财帽，甲己合（合日主）与辰酉合（印库合官）都表示这个官与自己相关，利升迁。","sec":"四、命例详解","t":"diff"},{"q":"原局以「未穿子」制印得权，行戊申运遇到「申子辰三合印局」，为何反而主权力更大？","opts":["三合局关住财库，使所有财富归于比劫所有","三合局把未土彻底化水，彻底消解穿的凶性","三合强化印的力量，且不破坏未穿子的功","申金直接冲去日主坐下禄神，让官位空出来"],"ans":2,"exp":"申子辰三合印局强化了印星代表的权力体量，同时并未破坏未穿子制印的做功，故权力更大。","sec":"四、命例详解","t":"rule"},{"q":"岁运逢「甲申」冲日主坐下「寅禄」时，若能化险为夷反主升职，原局通常需有什么字来化？","opts":["局中有巳火与申寅构成三刑破局","局中有酉金与申金混杂争夺官位","局中有戌土直接脆申金使其无力","局中有子水化申金冲寅禄之势"],"ans":3,"exp":"岁运申冲寅禄本不利，但若原局中有子水，申子半合水局生木，便化解了冲禄之害反主得权。","sec":"四、命例详解","t":"rule"},{"q":"流年「劫财坐杀（如甲申）」本是别人的官，什么情况下会变成「别人调走、自己升官」？","opts":["原局有天干合劫财且地支有合引动到自己","大运走印星被穿的大运，使别人无法调动","原局完全无合无冲，让劫财安静留在宾位","原局财星透干生旺劫财所坐之七杀"],"ans":0,"exp":"劫财坐杀本是别人的官，但若有甲己合、卯申合等将之合动并关联主位，就是别人调走、自己升官。","sec":"四、命例详解","t":"diff"},{"q":"原局依赖「戊癸合」财星制印得权的军官，为何行「己巳运」反而不利升职？","opts":["己土合走庚金官星，导致夫妻宫被彻底穿坏","原局依赖戊癸合，见己土则无用，升职困难","己巳一柱代表下海经商，必定发大财而辞职","巳火生旺戌土武库，导致军权过大难受控制"],"ans":1,"exp":"原局制印全靠戊土合克癸水，大运走己巳时己土不能代戊克癸，做功无力，故升职困难。","sec":"四、命例详解","t":"rule"},{"q":"命局坐支卯木七杀为实权，若行大运「乙巳」使「乙木」虚透天干，权力会如何变化？","opts":["权力集中放大，必定连升两级","伤官见官发威，调入公安执法部门","权力虚透无用，可能变成闲职","财星制印成功，转为实权一把手"],"ans":2,"exp":"乙木代表卯木七杀虚透天干，表示权力虚而无用；若再逢巳亥冲破原局合象，往往变成闲职。","sec":"四、命例详解","t":"rule"},{"q":"命局中「食神主心情」，当大运流年出现「子卯相破、食神破禄」时，容易应什么象？","opts":["心情极佳，连连晋升并获重权","财源广进，投资股票获利丰厚","婚姻美满，配偶得贵人大力提拔","心情不好，工作不顺并犯小人"],"ans":3,"exp":"食神代表心情，食神破禄（如子卯相破）主心情郁闷、工作不顺、容易犯小人。","sec":"四、命例详解","t":"rule"},{"q":"流年「己卯」同时应「伤官合杀升职」与「卯午相破（午为贵人）」时，现实中常出现什么情况？","opts":["虽升职但帮自己的贵人调走，后台没了","贵人升迁为更大领导，自己继续留任原职","因犯严重官非牢狱，导致贵人被牵连降职","升职失败且被迫转业，同时与配偶离婚"],"ans":0,"exp":"伤官合杀主升职应期，但卯破午火贵人，往往表现为明升暗降（如调下属单位当正职）且后台调走。","sec":"四、命例详解","t":"diff"},{"q":"大运走「丙午运」，日主自坐羊刃劫财并参与原局做功时，在军官象法中主什么？","opts":["火旺泄尽木气，主调离一线沦为闲职","羊刃到位做功，直接代表掌握军权","羊刃无制克妻，主彻底失去所有职务","劫财争夺财星，主转业从事个体经营"],"ans":1,"exp":"丙午运自坐羊刃劫财做功，羊刃到位做功本身就是掌握军权、带兵执掌实权的象。","sec":"四、命例详解","t":"rule"},{"q":"原局「辰戌冲制比劫库」，又见「戌穿酉」与「丁制酉」制财星时，对婚姻常见何种影响？","opts":["比劫护住妻星，主配偶身体健康且掌大权","财星得生扶，主夫妻白头偕老毫无波折","比劫库再穿妻星酉金，易克妻或中途断弦","辰戌冲开财库，主妻子经商发财而离婚"],"ans":2,"exp":"酉为妻星，被做功的戌土武库相穿，又受羊刃丁火克伤，往往应验克妻或头婚中途断弦。","sec":"四、命例详解","t":"rule"},{"q":"「年上乙卯连根，伤官主思想」的组合，为什么非常适合在部队当军官带兵？","opts":["连根为文笔，伤官主独自在机关写材料","连根为财库，伤官主在后勤部门管采购","连根为远方，伤官主长期驻外搞外交","连根为战友，伤官主一群士兵听其号令"],"ans":3,"exp":"年上乙卯连根为战友与自己，伤官主思想表达，象意为一群士兵听其讲话号令，极适合带兵。","sec":"五、其余命例要点","t":"xiang"},{"q":"「庚为顽金喜火炼」的团级军官，行「壬寅运」与「辛丑运」在仕途上有何不同？","opts":["壬寅运去官留杀利升职，辛丑运别人夺权不受重用","壬寅运别人夺权不受重用，辛丑运去官留杀利升职","壬寅运主犯官非牢狱，辛丑运主升至正军级实职","壬寅运与辛丑运均主印星被穿坏，皆为转业闲职运"],"ans":0,"exp":"壬寅运壬合丁冲丙、去官留杀，利升职；辛丑运辛主别人，两辛合为别人夺权，故不受重用。","sec":"五、其余命例要点","t":"diff"},{"q":"命局见「申子辰三合羊刃局、杀星配羊刃」的军官，为什么不宜三合水局太旺？","opts":["三合水局会合走印星，导致考学全部落榜","三合水局会泄尽杀气，反不利权力发挥","三合水局会冲开财库，导致转业下海经商","三合水局会生旺火库，导致性格暴躁犯上"],"ans":1,"exp":"杀星配羊刃本可做功，但申子辰三合羊刃水局太旺，会泄尽官杀之气，反而不利军权层级。","sec":"五、其余命例要点","t":"rule"},{"q":"军官转业下海经商时，若命局出现「财星化官星为忌（如午火财星化己土）」，结果往往如何？","opts":["财官相生，经商必定迅速积累巨额财富","官星护财，转业后仍可回原单位任顾问","喜神化忌，经商不成反致破产","财库冲开，先破小财后成跨国企业老板"],"ans":2,"exp":"午火财星化己土忌神，属于喜神化忌的组合，因此下海经商不但不成功，反而容易破产。","sec":"五、其余命例要点","t":"rule"},{"q":"军官命局以「寅代表部队，日主己巳为身体」，若岁运遇「寅巳穿」可能应何种身体灾伤？","opts":["巳为心，寅巳穿主突发心脑血管严重疾病","寅为眼，寅巳穿主双眼近视并动眼部手术","巳为头，寅巳穿主头部高血压与偏头痛","寅为腿，寅巳穿主腿部受伤（如枪伤）"],"ans":3,"exp":"寅木在人身类象中为腿，日主己巳为身体，岁运逢寅巳穿，正应腿部在部队受伤（如枪伤）之象。","sec":"五、其余命例要点","t":"xiang"}]},{"n":111,"level":"高级","title":"职业象法六：会计","qs":[{"q":"会计命局取象，哪几个字被看作「数字、运算」之象？","opts":["巳、午、丙","申、酉、庚","寅、卯、甲","亥、子、壬"],"ans":3,"exp":"亥、子水带数字运算之意；壬主运算通达，与财星、官杀挂钩就容易从事会计。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"子未相穿与亥未拱财，在会计取象中各读作什么？","opts":["子未穿为运算，亥未拱财为计算财务","子未穿为管钱，亥未拱财为出纳","子未穿为书写，亥未拱财为运算","子未穿为计算财务，亥未拱财为运算"],"ans":0,"exp":"子之象如算盘珠，穿＝拨动，是打算盘之象，可直读为运算；亥未拱财是计算财务。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计的第三条规律「伤官／食神配印，且有亥子水参与做功」中，食伤与印各代表什么？","opts":["食伤是大机构，印是行动力","食伤是头脑技能，印是单位机构","食伤是财库，印是数字运算","食伤是单位机构，印是头脑技能"],"ans":1,"exp":"食伤是头脑、技能，印是单位、机构，亥子水加入就是用自己的数字技能为单位服务。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"丁壬合在会计命局里主什么象？","opts":["有计算之意，主钱财到手","有远行之意，主外资企业","有书写之意，才华为机构所用","有行动之意，主比劫夺财"],"ans":2,"exp":"丁壬合有书写之意，又是食神（伤官）配印，主才华为机构所用、学历文凭较高。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计命局中，年上的印或官（印带官合身）表示什么？","opts":["年为远方，表示出国留学","年为祖上，表示家族企业","年为门户，表示自己创业","年为远方，可表示外资、大企业"],"ans":3,"exp":"年为远方；印带官合身，可表示外资、大企业。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"会计命局里，寅（中含官杀）取什么象？","opts":["大机构，也代表大财","眼睛视力，也代表辛苦","书写文职，也代表才华","小单位，也代表小财"],"ans":0,"exp":"寅中含官杀，代表大机构，也代表大财，机构规模高。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"断会计命局的判断步骤，正确顺序是哪个？","opts":["先定级别，再找数字，再看做功方式","先找数字，再看做功方式，再定级别","先看大运流年，再找数字，再定级别","先看做功方式，再定级别，再找数字"],"ans":1,"exp":"步骤：①找数字（亥子壬）；②看做功方式；③定级别（财库开不开）；④看格局大小；⑤用大运流年验证。","sec":"一、会计命局的三条取象规律","t":"step"},{"q":"命局所管的钱很多，财库不开，这钱是谁的？怎样才轮到自己发财？","opts":["是自己的；财库不开也能发财","是单位的；财库入墓后才发财","是单位的；财库被冲开刑开才轮到自己","是自己的；财库被合住才发财"],"ans":2,"exp":"财库不开，所管的钱再多也是单位的；财库被冲开、刑开，才轮到自己发财。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"断会计命局时，大运、流年怎样看作用？","opts":["大运流年都只作用原局","大运先与流年作用再看原局","流年先作用原局再合大运","大运看自身象再合原局，流年先合大运"],"ans":3,"exp":"看运口径：大运先看它自身的干支象意，再看与原局每一柱的作用；流年先与大运作用，再与原局作用。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"月令巳火伤官与亥水印相冲，算不算「伤官配印」？","opts":["不算，是伤官与印不和，易丢工作","不算，是比劫夺印，主破财","算，只是印被制，不影响单位","算，是伤官配印中最强的一种"],"ans":0,"exp":"易错点：巳亥冲不是伤官配印而是伤官冲印；月令代表工作单位，月令坏印容易丢工作。","sec":"三、其余五例要点","t":"diff"},{"q":"会计命局级别高低（总监、行长与普通会计、出纳）怎么分？","opts":["官杀不包局、无印无制级别高","官杀包局、有印有制级别高；局不成只能普通","食伤多见、无官杀级别高","财星重见、比劫多级别高"],"ans":1,"exp":"官杀包局、有印有制，级别才高；局不成、制得不干净，只能做普通会计、出纳。","sec":"一、会计命局的三条取象规律","t":"rule"},{"q":"出纳命局里「戊坐子」取什么象？","opts":["子为算盘，主发大财，适合做老板","子为眼睛，视力不佳，适合文员","子为数字，认真仔细，适合做出纳","子为大机构，才华横溢，适合做总监"],"ans":2,"exp":"戊坐子，认真仔细，子为数字，故做出纳；若财被合走则只帮人管财。","sec":"三、其余五例要点","t":"xiang"}],"fine":[{"q":"在会计命局的配套细节取象中，「比劫」与「伤官」分别代表什么？","opts":["比劫代表外资，伤官代表工资","比劫代表眼睛，伤官代表书写","比劫代表数字，伤官代表大机构","比劫代表行动力，伤官代表头脑"],"ans":3,"exp":"在会计取象规律中，比劫主行动力，伤官主头脑技能，亥水主数字，三者配合完成财务核算。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"十二地支中「巳火」在会计配套细节象里，既可取人身哪部位，又有何玄学之象？","opts":["巳为眼睛，且可沟通阴阳、有罗盘之象","巳为心脏，且可代表银行信贷柜台","巳为腿脚，且可代表部队武库军营","巳为头部，且可代表国家财政部门"],"ans":0,"exp":"巳火在人身类象中代表眼睛（被丑晦、被子克则视力差）；同时巳火可沟通阴阳，有罗盘之象。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"八字中「月令出现枭神」时，在幼年生活细节上常对应什么象？","opts":["主幼时双眼即高度近视","主幼时不吃母乳","主幼时早早离家参军","主幼时父亲早逝或离异"],"ans":1,"exp":"月令枭神为偏印当令，在盲派细象中常主幼时不吃母乳。","sec":"一、会计命局的三条取象规律","t":"xiang"},{"q":"活木生于冬，食神高透门户且与时支印星自合（如丁亥自合），在职业象上主什么？","opts":["彻底脱离单位自行创业开工厂","官杀无制且一生奔波犯小人","以自己的技术才华为单位机构所用","印星远隔主位且与公门无缘"],"ans":2,"exp":"食神高透主才华技术，自合印星（单位），主凭自身专业技能为机构单位服务。","sec":"二、命例详解","t":"rule"},{"q":"原局既以「子未穿」算账做功，又因时柱见亥而「亥未拱木」，对格局有何影响？","opts":["亥未拱木放大财库，主升任财务总监","亥未拱木化去子水，主彻底改行从政","亥未拱木增强印星，主跨国企业高管","亥未拱木削弱未土力量，损了格局而无职权"],"ans":3,"exp":"原局靠子未穿做功，但亥未拱木消耗了未土的力量，损了格局，故命平常而没有职权。","sec":"二、命例详解","t":"diff"},{"q":"原局以「子未穿」做功且透癸水印星的会计，行「戊辰运」为何工作得不到提升？","opts":["辰使印星入墓，并破坏了子未穿","辰土冲开未土财库，导致辞职下海经商","戊癸合化火局，导致眼睛严重受伤","戊土生旺癸水印星，导致印星太重无制"],"ans":0,"exp":"戊辰运中戊癸合利于宾位之癸，且辰土墓印星又破坏了子未相穿的做功，故工作难提升。","sec":"二、命例详解","t":"rule"},{"q":"命局以「午火」为思想才能，行「乙酉运」出现「酉破午」时，工作上常见何象？","opts":["财库彻底冲开，投资股票获利百万","才华得不到展示，工作不顺常换单位","印星合身得力，考取注册会计师","才华充分显露，受领导破格提拔"],"ans":1,"exp":"午是思想才能，酉破午则才华受阻不得展示，故在工作上常感不顺、频繁更换单位。","sec":"二、命例详解","t":"rule"},{"q":"金水食伤生财入墓于坐下未土印库，同样是管大财，何时归单位、何时归自己发大财？","opts":["只要日主坐下为财库，所管之钱全部归自己","只要有寅木大机构，财库不开也能自己发大财","未库不开则财归单位，丑冲未开库才自己发财","未库不开则自己发财，丑冲未开库则财归单位"],"ans":2,"exp":"未既为财库又为印星（单位），财库不开则所管的钱再多也是单位的；若见丑冲未开库，才轮到自己发大财。","sec":"二、命例详解","t":"diff"},{"q":"命局「申子辰合水局，子午冲（印制伤官）」有权力，为何往往权力不够大？","opts":["子午冲破了夫妻宫，导致无法升职","伤官太旺克死印星，导致频繁下岗失业","申金七杀无制，导致一生只能做普通出纳","月令比肩坐印库，权力被比肩所分"],"ans":3,"exp":"印星做功（子午冲）本主权力，但月令比肩坐印库，印的权力被比肩分走一半，故权力不够大。","sec":"二、命例详解","t":"rule"},{"q":"女命原局「申金为丈夫且主金融，化子水冲午」与数字相关，配偶多从事何种职业？","opts":["银行官员或金融财务类职务","部队带兵军官或基层民警","学校教师或机关档案文秘","家具装修或木材加工商人"],"ans":0,"exp":"申金主金融、化子水数字冲午有印制伤官之权，因此丈夫多为银行官员或金融系统干部。","sec":"二、命例详解","t":"xiang"},{"q":"大运「辛丑」遇「辛金克月干甲木而不克日主甲木（大限尚在月令）」，应如何论吉凶？","opts":["正官克身大凶，必定丢官罢职并破大财","不克日主以吉论，且丑墓申穿午反为功","比肩争夫大凶，必定此运离婚且失业","伤官见官大凶，必定因做假账而入狱"],"ans":1,"exp":"大限在月令时，辛克月干不克日主，以吉论；同时大运丑土使申入墓并穿午火伤官，反助升职。","sec":"二、命例详解","t":"rule"},{"q":"「巳亥冲」与「戌制亥」在财务与文职职业取象上，有何细微区分？","opts":["巳亥冲主军警武职，戌制亥主跨国总监","巳亥冲主文职工作，戌制亥主财务工作","巳亥冲主财务工作，戌制亥主文职工作","巳亥冲主下海经商，戌制亥主风水占卜"],"ans":2,"exp":"亥为数字，禄神巳冲亥主财务、收银一类工作；食神戌土制亥水，则偏重于办公室文职工作。","sec":"二、命例详解","t":"diff"},{"q":"命局中「辛金财星虚透被劫，关了财门」，但地支「卯戌合」食神合印，工作与财运如何？","opts":["彻底离开财务行业，转行从事体力劳动","既发大财又当高官，婚姻美满顺遂","工作频繁失业，靠投机股票暴富","难发大财，但工作稳定且收入不错"],"ans":3,"exp":"财星虚透被劫、关了财门主难发大财，但食神合印（卯戌合）利工作，再得印生禄，工作稳定收入好。","sec":"二、命例详解","t":"rule"},{"q":"女命原局「子息宫落伤官，又与日支坐下食神相刑」，在子女方面常见什么后果？","opts":["夫妻宫与子息宫俱坏，不利子息难生育","只影响婚姻感情，完全不影响生育子女","头胎必生双胞胎，晚年得子女大力扶持","子息极为兴旺，儿女双全且皆成材"],"ans":0,"exp":"子息宫落伤官与坐支食神相刑，造成夫妻宫与子息宫俱坏，严重不利子息，甚至生不了孩子。","sec":"二、命例详解","t":"rule"},{"q":"「土金伤官喜见印，但印星虚透又坐财星，印在劫财上」，这种组合多主什么职业象？","opts":["伤官配印成大格，主跨国企业财务总监","伤官格不成，主辛苦替人打工（如文员、出纳）","杀印相生包局，主政府财政税务局局长","财星制印得权，主部队后勤团级军官"],"ans":1,"exp":"印星虚透又坐财星，伤官配印格不成立；印在劫财上主辛苦、替人打工，难有高职，多为文员或出纳。","sec":"三、其余五例要点","t":"rule"},{"q":"行「庚辰运」遇「三合财局」且原局有「子丑合」，为何财虽重却自己不发财？","opts":["财星全部化为官杀，直接升任公司老总","三合财局把印星生得太旺，不想求财","子丑合把财合走，只是帮别人管财","日主身弱不胜财，只能把钱全部捐出"],"ans":2,"exp":"虽走三合财局财星很重，但地支子丑合把财合走，说明这财不是自己的，只能替别人（或单位）管财。","sec":"三、其余五例要点","t":"rule"},{"q":"天干「甲木为头，被辛金官星克伤」，在人身健康象法上常见什么病症？","opts":["双眼近视、白内障","肠胃溃疡、消化不良","腿部骨折、行动不便","血压高、头晕头痛"],"ans":3,"exp":"甲木在人身类象中代表头，被辛金克制，常应血压高、头晕、头痛等头部毛病。","sec":"三、其余五例要点","t":"xiang"},{"q":"「月令子印带丙火食神（子未穿算账）」与「门户酉官带财虚透、丙辛合」兼见，主何特征？","opts":["既可做会计，又有买卖口才之象，一生多职业","终身只能做单一出纳，绝无经商做生意的可能","必定考入国家执法部门，成为专职纪检干部","必定长期在部队服役，成为专业财务军官"],"ans":0,"exp":"子未穿主计算做会计，门户丙辛合为买卖交易、食神为口才，兼见做生意之象，故一生有多种职业象。","sec":"三、其余五例要点","t":"diff"},{"q":"命局「官杀太重不能发大财」，什么情况下这套命局反而「有价值」能靠技术求财？","opts":["比劫重重透出，把所有官杀全部转化为印星","虚官虚杀透出被自合制杀取财（如辛巳自合）","财星全部入墓不开，且日主完全不与数字沾边","实官实杀无制，直接全部合入日主身中"],"ans":1,"exp":"官杀过重本难发大财，但若透出虚官虚杀并被主位自合（如辛巳自合）制杀取财，便有价值，可凭专业技术求财。","sec":"三、其余五例要点","t":"rule"},{"q":"命局「无劫财做功、食伤合杀、杀无制」时，盲目参与股票投资往往结果如何？","opts":["投机暴富，成为专业股神","先赔后赚，最终稳赚不赔","炒股必赔，容易破财","毫无波澜，资金全部保本"],"ans":2,"exp":"炒股投机喜劫财做功或制住杀星；若无劫财做功、食伤合杀而杀无制，逢财杀岁运炒股必赔。","sec":"三、其余五例要点","t":"rule"},{"q":"四同八字（如乙巳／辛巳／乙亥／庚辰），为何女命一直做会计，男命早年做会计后改行做风水？","opts":["女命大运顺排必进部队，男命大运逆排必进银行","男命把辰土财库彻底冲破，女命把酉金官星合走","女命喜欢自由不喜管束，男命喜欢安稳坐办公室","男命冲去亥水后以巳火伤官为用，巳有罗盘象"],"ans":3,"exp":"女命亥入辰墓做会计；男命大运逆排冲去亥水后，以月令巳火伤官为用，巳可沟通阴阳、有罗盘之象，故做风水。","sec":"三、其余五例要点","t":"diff"},{"q":"命局中「劫财合财（如卯戌合）」同时又有「卯辰穿」，在投资方面主什么象？","opts":["拿自己的钱投资，且卯辰穿主投资获利","帮别人管钱算账，完全不能自己做投资","拿公家的钱炒股，必定引发官非与破产","劫财夺财破财，所有投资全部血本无归"],"ans":0,"exp":"劫财合财表示拿自己的钱去投资，地支卯辰穿做功有制，则主投资能够获利赚钱。","sec":"三、其余五例要点","t":"rule"}]},{"n":112,"level":"高级","title":"职业象法七：技术人员","qs":[{"q":"盲派看技术人员命局，一般用什么为用、什么代表单位？","opts":["食伤为用，官印为单位","财星为用，比劫为单位","比劫为用，财星为单位","官印为用，食伤为单位"],"ans":0,"exp":"食神伤官主头脑技术，官印为单位机构；技能为单位所用，就是技术人员的基本构成。","sec":"一、技术人员命局的总规律","t":"rule"},{"q":"技术人员命局与管理者命局，在格局上的区别是？","opts":["技术员必成包局，管理者不成包局","技术员不成包局、制局，成包局可做管理","两者都不成包局，只看食伤多少","技术员必成制局，管理者必成包局"],"ans":1,"exp":"没有包局、制局，只是靠技术吃饭，格局不大；格局大者能当管理者或领导。","sec":"一、技术人员命局的总规律","t":"diff"},{"q":"技术人员命局中，比劫参与做功代表什么？","opts":["主钱财被劫，工作不稳","主合伙开公司","动手能力，常是半体力半技术","主纯脑力、不用体力"],"ans":2,"exp":"比劫主动手能力；技术人员既付出脑力也付出体力，常是半体力半技术。","sec":"一、技术人员命局的总规律","t":"rule"},{"q":"乙未、戌、亥（壬）在技术行业取象上，依次对应什么？","opts":["数字运算、集成电路、电子电器","传媒影视、土建工程、数字运算","土建工程、电子电器、设计","集成电路、电子电器、数字运算"],"ans":3,"exp":"乙未为集成电路（也表传播、互联网）；戌为火库表电子、电器、电力；亥、子、壬表数字、运算。","sec":"行业取象表","t":"xiang"},{"q":"八字中己酉，在技术行业取象上主什么？","opts":["设计，己为线条、酉为面板","数字运算","电信传媒","土建工程"],"ans":0,"exp":"己酉：己为线条、酉为面板，设计之象；辰酉合表坐办公室。","sec":"行业取象表","t":"xiang"},{"q":"辰戌两字在技术行业取象上主什么？","opts":["设计，辰为线条","土建工程，戌为高楼","电子电器，戌为火库","集成电路"],"ans":1,"exp":"辰戌表土建工程，戌为高楼；戌作火库另表电子、电器、电力。","sec":"行业取象表","t":"xiang"},{"q":"技术人员常兼职教学，盲派取什么象？","opts":["伤食表老师，阴旺求阳","比劫表学生，财星表老师","伤食也表学生老师，阳旺求阴，学生求知","官印表学生，食伤表单位"],"ans":2,"exp":"伤食也表学生、老师，阳旺求阴（学生求知），所以技术人员常兼职教学。","sec":"行业取象表","t":"rule"},{"q":"八字没有食伤，也可能是技术命的日时组合是哪一个？","opts":["戊戌日配辛酉时","丙寅日配壬辰时","乙未日配丙戌时","壬辰日配己酉时"],"ans":3,"exp":"无食伤也可以是技术命：壬辰日配己酉时，己为线条、酉为面板，设计之象，辰酉合坐办公室。","sec":"一、技术人员命局的总规律","t":"rule"}],"fine":[{"q":"在技术人员行业取象中，「丙火、寅木」与「丙寅」的组合多对应哪类行业？","opts":["传媒、影视、电脑、网络或电信","食品、餐饮、酒店或旅游","会计、审计、出纳或统计","煤炭、矿山、钢铁或冶金"],"ans":0,"exp":"丙火主明亮传播、寅木主动手能力与网络线缆，丙寅同现多主传媒、影视、电脑、网络与电信。","sec":"行业取象表","t":"xiang"},{"q":"「金水食伤制火官杀」的结构，在技术工程领域通常对应哪种工作？","opts":["用文字才华做政府宣传与档案管理","用数理技术做电子、电器、电力工程","用印星比劫做部队带兵与治安刑侦","用木土组合做园林绿化与室内装修"],"ans":1,"exp":"金水食伤代表数理逻辑与运算，火官杀代表电与火器，金水制火即用数理技术从事电子、电器、电力工程。","sec":"行业取象表","t":"xiang"},{"q":"在行业取象表中，印星为「寅」与天干见「辛」分别偏重哪种技术工作象？","opts":["寅主金融信贷，辛主建筑施工管理","寅主平面广告设计，辛主煤炭开采","寅主电器电力设备，辛主精细加工","寅主土建高楼，辛主互联网软件开发"],"ans":2,"exp":"印为寅时多代表电器、电力设备；辛金主精致细密，常取精细加工之象（两辛合有合住之意）。","sec":"行业取象表","t":"xiang"},{"q":"判断技术人员命局时，第一步应当先看食伤的什么关键信息？","opts":["食伤是否与财库形成辰戌冲或丑未冲","大运是否正在走比劫羊刃库发用之地","八字中正印与偏印是否同时透出天干","食伤的位置与来路（出于何支及是否透干）"],"ans":3,"exp":"断技术人员第一步先看食伤的位置与来路，看伤官出于何支、是否被官印牵动、是否透干或在门户有手。","sec":"判断步骤","t":"step"},{"q":"在技术人员命局对大运时，「官杀得制」与「官杀旺而制不好」在待遇上有什么区别？","opts":["官杀得制是好运，制不好只能是普通工薪","官杀得制与制不好均主高薪，只看比劫旺衰","官杀得制主兼职教学，制不好主出国留学深造","官杀得制主辞职单干，制不好主升任公司高管"],"ans":0,"exp":"官杀得制则是好运、收入高；若原局或运岁官杀旺而制不好，便只能拿普通工薪收入。","sec":"判断步骤","t":"rule"},{"q":"乙木生冬透丙火且见丑入辰库，本像公安刑警，为何「寅与丑隔一酉」就变成电信技术？","opts":["酉金冲去寅木公门，使日主只能下海搞建筑","酉绝寅使寅合丑不成立，且丙寅表电信网络","酉金生旺丑土杀库，使日主升任政府高官","酉金合住辰土财库，使日主彻底改行做会计"],"ans":1,"exp":"寅为公门、丑为阴暗，若寅丑相邻贴合则为公安；中间隔一酉金则酉绝寅、寅合丑不成立，转为丙寅电信技术。","sec":"二、命例详解","t":"diff"},{"q":"寅木在人身类象中代表肝胆，若岁运见「戊寅伏吟」且「劫财见财」，易发生什么事？","opts":["顺利考取研究生并出国深造","结婚生子且配偶事业大旺","患肝胆疾病住院并破财","升职为部门经理并购置房产"],"ans":2,"exp":"伏吟主难过、折腾，寅为肝胆、戊寅伏吟加上甲劫财见戊财，正应肝胆病（如乙肝）住院破财。","sec":"二、命例详解","t":"xiang"},{"q":"同为火天干，「丙火」与「丁火」在旺衰喜忌上有何本质不同？","opts":["丙喜旺（越旺越贵），丁怕旺（太旺必自焚）","丙丁均喜极旺，皆主必须配金水才能成格","丙丁均喜衰弱，最怕见到甲乙木来生扶","丙怕旺（太旺焚灭），丁喜旺（如群星灿烂）"],"ans":3,"exp":"丙与丁性质不同：丙为太阳怕过旺，太旺反而焚灭；丁为灯烛星火喜旺，如群星灿烂，更喜甲木生。","sec":"二、命例详解","t":"diff"},{"q":"命局年上伤官配印且「甲寅主权力」，为何因「寅巳相穿」而不当官反成高薪设计师？","opts":["寅与自己不和故不为官，木火主文化技能为单位用","寅木远隔无法参与做功，一生只能靠祖业生活","寅巳相穿彻底坏了印星，只能从事纯体力劳动","巳火直接合走甲木印星，导致辞职下海搞地产"],"ans":0,"exp":"寅巳相穿使甲寅权力与日主巳火不和，故不为官；但木火主文化、食伤主技能、甲印为单位，成高薪设计师。","sec":"二、命例详解","t":"rule"},{"q":"岁运中出现「寅午戌三合」又「刑未（未为印库代表单位）」，在职业上常应何事？","opts":["印库与比劫同旺，对应在原单位连升三级","刑去一个、合来另一个，对应换工作单位","印库被彻底刑坏，对应长期失业在家","财星入库闭塞不动，对应辞职去考公务员"],"ans":1,"exp":"未为印库代表单位，流年刑未又构成三合，即刑去旧单位、合来新单位，正应更换工作单位。","sec":"二、命例详解","t":"rule"},{"q":"命局「辛金劫财在门户表示手」，配合「丑戌刑、辛巳自合」做功，说明什么工作特点？","opts":["纯坐办公室写文章，完全不用动手","专门从事银行信贷，掌管大额现金","半体力半技术，且制杀收入较高","纯靠体力搬运苦力，收入微薄难温饱"],"ans":2,"exp":"比劫在门户代表动手能力，参与丑戌刑与辛巳自合制杀，既主半体力半技术，又因制杀而收入较高。","sec":"二、命例详解","t":"rule"},{"q":"男命八字无财星而以食伤为妻星，若妻星坐支「与夫妻宫相刑（如丑戌刑）」，婚姻如何？","opts":["食伤生财有源，头婚稳固且白头偕老","无财星则一生独身，完全不会谈恋爱","夫妻宫越刑越旺，配偶能带来巨额财富","夫妻宫犯刑，头婚要离且难有稳定婚姻"],"ans":3,"exp":"无财取食伤为妻星，若妻星坐支与夫妻宫相刑，则夫妻宫犯刑、星宫不和，第一次婚姻要离，婚姻难稳。","sec":"二、命例详解","t":"rule"},{"q":"互联网技术员命局中同时见到「乙庚合」与「卯申合」，在薪资与公司层面主什么象？","opts":["财合印、财富放大，公司有钱且工资高","比劫夺财、印星受损，公司亏损且降薪","伤官见官、官杀无制，频繁与领导吵架","财库闭塞、官星虚透，只享虚名而收入低"],"ans":0,"exp":"乙庚合、卯申合均为财星合印，代表财富的放大效应，主所在公司实力雄厚有钱，个人工资也高。","sec":"二、命例详解","t":"rule"},{"q":"壬午大运中，「壬水虚透」与「午卯相破（破月令印星）」分别对应什么影响？","opts":["壬虚透主患眼疾手术，午破卯印主长期稳定在岗","壬虚透主荣誉学位利深造，午破卯印主变动不利升职","壬虚透主下海破财，午破卯印主提拔为部门主管","壬虚透主考学落榜，午破卯印主夫妻恩爱领证"],"ans":1,"exp":"壬水杀星虚透主荣誉学位、利考研深造；地支午卯相破破坏月令印星，故不利升职而主职业变动。","sec":"二、命例详解","t":"diff"},{"q":"男命以「庚申年柱为妻、卯申合」，行「午运」为何难结婚，须过午运到「癸未运」才成？","opts":["午运合住夫妻宫太稳固，未运冲开夫妻宫才遇对象","午运代表出国留学无暇恋爱，未运回国进银行工作","午运克申难入宫且午破卯印，未运合卯合午方成","午运比劫太弱无力争妻，未运劫财透干才抢到配偶"],"ans":2,"exp":"午运火克申金妻星，使夫妻星无法进入夫妻宫，且卯午破印也难领证；到癸未运卯未、午未相合，婚姻遂成。","sec":"二、命例详解","t":"rule"},{"q":"命局中「未中藏乙为集成电路，拱亥为数字、电脑运算」，最贴切哪种具体职业？","opts":["银行信贷员","部队参谋长","建筑施工员","软件工程师"],"ans":3,"exp":"乙未为集成电路、亥为数字，未拱亥即集成电路与电脑数字运算结合，正对应软件工程师。","sec":"二、命例详解","t":"xiang"},{"q":"原局以「丑未冲」做功的食神制杀技术命，行「辰运」为何收入不多且一直打工？","opts":["辰运破坏了丑未冲，使原局没有做功","辰运生旺比劫羊刃，导致投资股票暴富","辰运合住食神辛金，导致转为政府公务员","辰运冲开官杀库，导致辞职下海去开矿"],"ans":0,"exp":"原局全靠丑未冲制杀做功，行辰运时辰土破坏丑未冲、把亥水收墓，原局无功可做，故一直打工收入不多。","sec":"二、命例详解","t":"rule"},{"q":"男命原局「午亥合，午为母」，若地支同时出现「丑午穿」，在父母关系上常应什么象？","opts":["父母双双出国，长期异地定居","父母婚姻不好，有离婚之象","母亲升任高官，父亲下海经商","父母恩爱长寿，白头偕老"],"ans":1,"exp":"亥水为财为父、午亥合则午为母，但丑为父母宫又丑午相穿，父母星宫相穿，主父母婚姻不好、容易离婚。","sec":"二、命例详解","t":"xiang"},{"q":"地支「寅木」除可代表传媒、电器设备外，与「申」组合（寅申组合）还适合什么行业？","opts":["平面装修","餐饮酒店","金融行业","煤矿开采"],"ans":2,"exp":"寅木可代表传媒、电器设备，而寅申组合（木放金收）在职业象法上还非常适合从事金融行业。","sec":"三、其余五例要点","t":"xiang"},{"q":"「壬辰日天河骑龙」在面对地支「戌冲辰」时，为什么最忌讳冲？","opts":["辰为火库高楼之象，一冲就会引发火灾","辰为木库公门之象，一冲就会立即退休","辰为金库银行之象，一冲就会变成高管","辰为水库水坝之象，喜穿不喜冲，冲则崩溃"],"ans":3,"exp":"壬辰日见辰为水库，有水坝之象，水坝喜穿（如卯辰穿）不喜冲，一旦戌冲辰则水坝崩溃、根基动摇。","sec":"三、其余五例要点","t":"rule"},{"q":"在技术人员病伤取象中，「丑为阴中之阴损阳气」与「戊子自合（子为腿脚）」各易应什么？","opts":["丑损阳主郁闷乏力，戊子自合主腿脚摔伤骨折","丑损阳主高血压头痛，戊子自合主眼部近视手术","丑损阳主咽喉发炎，戊子自合主心脑血管疾病","丑损阳主肺部肿块，戊子自合主肝胆发炎住院"],"ans":0,"exp":"丑为阴中之阴损阳气，会让人身体郁闷乏力；子在人身主腿脚，戊子自合有被绊住之象，易应摔倒腿脚骨折。","sec":"三、其余五例要点","t":"xiang"},{"q":"「壬辰日配己酉时」的建筑工程技术人员，为何能坐办公室做设计却不能当官？","opts":["辰酉合主下海经商，己官透干主必须外出跑工地","辰酉合主坐办公室设计，己官透干降低格局故不当官","辰酉合主发大财亿万，己官透干主兼职当大学老师","辰酉合主夫妻宫稳固，己官透干主一生无工作单位"],"ans":1,"exp":"己为线条、酉为面板是设计象，辰酉合表示坐办公室；但己土正官透干反而降低了格局，故不能当官。","sec":"三、其余五例要点","t":"rule"}]},{"n":113,"level":"高级","title":"职业象法八：银行工作人员","qs":[{"q":"银行象法里，「收」与「放」分别对应哪个方位五行？","opts":["东方木主收，西方金为放","东方木为放，西方金主收","西方金为放，东方木主收","南方火为放，北方水主收"],"ans":1,"exp":"银行吸收存款、发放贷款，用象法就是收与放：东方木为放，西方金主收。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"局中同时出现卯与申，在银行取象上怎么看？","opts":["只是木金相克，与银行无关","申为放卯为收，主证券业","卯申组合为收放，容易是银行","卯申合为会计，与银行无关"],"ans":2,"exp":"收放组合包括卯酉、卯申、寅申、丑未，出现这类组合容易是银行。","sec":"一、银行命局的三条取象规律","t":"calc"},{"q":"哪两个字再配财星，就代表金融机构银行？","opts":["壬与亥","甲与寅","丙与午","庚与申"],"ans":3,"exp":"庚与申为金融之意，银行属金融机构，再配财星就代表银行。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"亥、子、壬在职业象里与什么行业相关，需要与什么相连？","opts":["数字，与财星财库相连","文字，与印星相连","药物，与食伤相连","权力，与官杀相连"],"ans":0,"exp":"银行第一条取象规律：数字与财富发生关联，与会计组合类似，亥子壬为数字，与财星、财库相连。","sec":"一、银行命局的三条取象规律","t":"rule"},{"q":"十二地支里，哪个字能装财又是财库的地方，直接取银行象？","opts":["未","丑","辰","戌"],"ans":1,"exp":"丑是金库又是财库，能装财又是财库的地方就是银行。","sec":"配套细节象","t":"xiang"},{"q":"丑未冲在银行象里怎么取？","opts":["一动一静，丑代表子，未代表午","一收一放，丑代表寅，未代表酉","一收一放，丑代表酉，未代表寅","一生一克，丑代表酉，未代表亥"],"ans":2,"exp":"丑未冲＝一收一放，银行之象；丑代表酉（金），未代表寅（木）。","sec":"配套细节象","t":"xiang"},{"q":"杀印相生、官带财帽的结构，银行象里取什么？","opts":["管账的会计","发放贷款的业务员","仓库保管员","管财的官"],"ans":3,"exp":"杀印相生、官带财帽表示管财的官，官星带财就是管财。","sec":"配套细节象","t":"xiang"},{"q":"财星包局，取象怎么看？","opts":["单位都是钱，取象为银行","财被围住，取象为破财","财被封死，取象为穷困","家里钱多，取象为富商"],"ans":0,"exp":"财星包局表示单位都是钱，取象为银行；包局所包之神都可理解成一家。","sec":"配套细节象","t":"xiang"},{"q":"判断银行命局的步骤，第一步看什么？","opts":["职位高低，是否包局","收放字与金融字，是否与财星或财库绑定","大运岁运是否引动丑未冲","做功方式是印做功还是食伤做功"],"ans":1,"exp":"步骤：先找卯酉、卯申、寅申、丑未、庚申酉，是否与财绑定；再看做功，再定职位，注意双层职业，最后对运。","sec":"判断步骤","t":"step"},{"q":"银行命局中，什么结构才能当官（行长、经理）？","opts":["官杀无制、印被坏","食伤泄秀、比劫成势","包局、杀印相生、印带官","财星太旺、印星虚透"],"ans":2,"exp":"包局、杀印相生、印带官才能当官；官杀无制、印被坏只是职员。","sec":"判断步骤","t":"rule"},{"q":"运岁里出现什么情况，银行命局会离岗或不顺？","opts":["寅申冲被运岁引动","丑未冲被引动","卯申合被引动","子穿未，或合坏丑未冲、卯申合"],"ans":3,"exp":"丑未冲、卯申合被运岁引动是升职或入行；被子穿未、合坏则离岗或不顺。","sec":"判断步骤","t":"rule"},{"q":"戊己印星杂透，在职业象上主什么？","opts":["金融与法律两种工作性质","军警与财务两种工作性质","建筑与地产两种工作性质","医药与教育两种工作性质"],"ans":0,"exp":"戊己印星杂透为双层职业：金融＋法律。","sec":"判断步骤","t":"xiang"}],"fine":[{"q":"在银行配套细节象中，「申、酉」两字除代表金融银行外，各自还有什么细象？","opts":["酉亦为眼睛视力，申又为文书档案","酉亦为单位与权力，申又为财的原神","酉亦为土木工程，申又为煤炭矿山","酉亦为高楼大厦，申又为火药枪支"],"ans":1,"exp":"申、酉主金融银行；细分之下，酉在命局中亦常代表单位与权力，申则又作为财的原神代表银行。","sec":"配套细节象","t":"xiang"},{"q":"银行命局中「印星」与「劫财」的取象有何不同，月令印被坏时会发生什么？","opts":["印为算盘（月令印被坏主升职），劫财主当行长","印为股票（月令印被坏主出国），劫财主文凭","印为单位（月令印被坏易丢工作），劫财主争财抢财","印为贷款（月令印被坏主发大财），劫财主单位"],"ans":2,"exp":"印星代表工作单位，月令印被坏则容易丢工作或换岗；劫财则代表争财、抢财（比肩争妻）。","sec":"配套细节象","t":"diff"},{"q":"判断银行命局第二步看做功方式时，由「印做功」与由「食伤做功」在岗位上有何区别？","opts":["印做功主下海经商，食伤做功主行政后勤","印做功主普通柜员，食伤做功主总行行长","印做功与食伤做功均主信贷业务员，无区别","印做功主职权管理，食伤做功主技术业务"],"ans":3,"exp":"看做功方式要区分是印做功还是食伤做功：印做功多主掌权管理（行长、经理），食伤做功偏技术或一线业务。","sec":"判断步骤","t":"step"},{"q":"银行行长命局若见「日主无根、甲己合、月令财星太重」，本主穷，为何反成高管富命？","opts":["包局形成后，所包之神都成一家为自己的财","日主无根便成从财格，只要走比劫运就能暴富","月令财星太重直接克死印星，反主掌管银行","甲己合把财星全部合走，代表不贪财而升官"],"ans":0,"exp":"一般日主无根、财重主穷，但一旦形成包局，所包之神都可理解成一家，代表自己的大财与大权。","sec":"二、命例详解","t":"rule"},{"q":"银行高管行「亥运」时遇「申亥穿（申代表银行）」，在职业变动上通常应什么事？","opts":["留在原银行不动，但因投资股票惨赔破产","离开银行系统（如调去政府企业管信贷）","辞去所有公职，改行开工厂做家具装修","在原银行连升两级，直接升任总行行长"],"ans":1,"exp":"申代表银行金融机构，行亥运见申亥穿，申被穿坏，主离开银行系统（如调到政府企业管信贷）。","sec":"二、命例详解","t":"rule"},{"q":"「丁亥自合（伤官合杀）」与「亥生卯财、卯申合」同时见于一局，为何指向银行部门经理？","opts":["伤官合杀主部队带兵，亥生卯财主下海搞建筑","伤官合杀主普通出纳，卯申合主一生无职务","伤官合杀主技能为单位用，亥运算生财配卯申收放","伤官合杀主自由职业，卯申合主完全离开金融"],"ans":2,"exp":"伤官合杀表示凭专业技能为公司服务；亥为运算生卯财兼有会计之象，卯申收放组合则明确指向银行。","sec":"二、命例详解","t":"diff"},{"q":"在比肩争妻的银行命局中，经历分手后，流年逢「乙酉（妻宫卯之乙到、卯酉冲）」为何能再处对象？","opts":["乙木生旺丁火官杀，代表领导主动帮忙介绍","酉金冲走夫妻宫，代表离开原单位去外地","乙酉流年合住比劫，使竞争对手彻底放弃","乙到卯到，卯酉冲把妻宫的财星冲回来"],"ans":3,"exp":"乙木透干代表坐支卯木妻星到位，流年卯酉冲把被争走的妻宫财星重新冲回主位，故能再处对象。","sec":"二、命例详解","t":"rule"},{"q":"银行部门经理行大运「辛卯伏吟」时，在工作状态与职务晋升上通常如何？","opts":["伏吟代表辛苦，职务不会很高","伏吟代表发财，投资地产赚数千万","伏吟代表轻松，必定升任总行行长","伏吟代表转行，彻底离开金融领域"],"ans":0,"exp":"辛卯日主行辛卯运，伏吟代表劳心辛苦、反复奔波，虽比前运平顺，但职务不会升得很高。","sec":"二、命例详解","t":"rule"},{"q":"日坐偏印本无用的命局，为何一旦构成「财库包局」反能成为银行营业部经理？","opts":["坐下偏印代表孤僻清高，主在银行只享虚名","财库包局单位都是钱，印有功且制财库主权力","偏印克制食神夺食，主在银行后台做纯体力活","财库包局把印星全部埋葬，主完全脱离机构单干"],"ans":1,"exp":"财库包局表示单位都是钱（银行），月干伤官被印制服且劫财帮日主共同制戌财库，印有功故主银行官员。","sec":"二、命例详解","t":"rule"},{"q":"男命妻星与妻宫相穿感情不好，为何早年「星包宫」不离，到「妻宫双现、丑运坏戌」终难守？","opts":["星包宫与妻宫双现均主白头偕老，绝无离婚可能","妻宫双现主一生独身，丑运坏戌主配偶升官发财","星包宫不易离，但妻宫双现主双婚且丑运坏戌必离","星包宫主必离三次，丑运坏戌反主夫妻破镜重圆"],"ans":2,"exp":"星包宫有包住不散之意故不易离婚；但妻宫双现本身主双婚，一旦行丑运刑穿坏掉戌土妻星，终难逃离婚。","sec":"二、命例详解","t":"diff"},{"q":"银行业务经理命局「年上癸丑食神戴杀帽，且癸水偏重不虚透」，为何职权不大？","opts":["丑土财库彻底被冲开，主辞职去开矿山酒店","癸水远隔日主完全无情，主终身只是普通柜员","食神戴杀帽主伤官见官，必定惹官非而丢职","杀星偏重不虚透主受别人领导，故职权不大"],"ans":3,"exp":"食神戴杀帽表示在单位有点小权，但癸水偏重、不虚透，说明头上还有领导压着、受人管束，故职权不大。","sec":"二、命例详解","t":"rule"},{"q":"女命原局「癸水夫星坐丑伏吟到夫妻宫，但癸水远隔且与日主不亲」，婚姻往往呈现什么状态？","opts":["婚姻稳定不易离，但感情不好常吵架","婚后不到一年必离，终身频繁换伴侣","夫妻恩爱无比，一生从未红过脸","丈夫长期驻外不归，两人名存实亡"],"ans":0,"exp":"夫星坐丑伏吟进夫妻宫，宫星相联故婚姻稳定；但癸水在年上远隔、与日主不亲合，故感情不好常吵架。","sec":"二、命例详解","t":"rule"},{"q":"以「丑未冲」一收一放做功的银行业务管理，行「丙子运」为何身体与工作都不顺？","opts":["子水冲开午火财库，导致下海经商彻底破产","子运合丑穿未破坏丑未冲，损功且水旺坏阳气","丙火虚透太旺焚木，导致与银行领导激烈冲突","丙子一柱代表调往总行，因工作太忙而累倒"],"ans":1,"exp":"原局全靠丑未冲（一收一放）做功，喜寅未之阳；行丙子运时子合丑穿未，既破坏丑未冲又阴湿损阳气，故俱不利。","sec":"二、命例详解","t":"rule"},{"q":"因大运「子合丑穿未」破坏原局「丑未冲」而辞离银行后，流年见什么字最有希望重回银行？","opts":["子年（子水伏吟，继续合住丑土财库）","辰年（辰土收水，把丑未全部埋入墓中）","寅年（寅代表未到，重新引动丑未冲）","亥年（亥水合寅，彻底化去未土燥气）"],"ans":2,"exp":"未代表寅（原局未为银行放贷端），流年逢寅年即寅代表未到位，重新引动丑未冲，故应回银行工作。","sec":"二、命例详解","t":"diff"},{"q":"命局地支出现「丑未戌三刑，坏日主木根」，在身体与婚姻方面常见何种不利？","opts":["幼时学业极差，但中年后必定成为亿万富翁","身体健康长寿，且夫妻恩爱白头偕老","只影响工作单位变动，对身体与婚姻毫无影响","不利身体（幼时伤病），且妻宫星犯三刑终不白头"],"ans":3,"exp":"丑未戌三刑坏了日主乙木之根，主幼时易有伤病（如头部重伤）；同时妻宫与妻星同犯三刑，婚姻终难白头。","sec":"三、其余五例要点","t":"rule"},{"q":"校对金融法律双层职业女命的时辰时，为何定为「丑时」而非「子时」？","opts":["丑未冲开财库、寅申冲为金融，子时则未穿坏印","子时合丑太旺主大贵，丑时则无学历无婚姻","子时主二十八岁结婚，丑时主终身孤寡无婚","子时代表银行行长，丑时代表普通出纳员"],"ans":0,"exp":"丑时则丑未冲开财库、寅申冲与丑未冲俱为金融象，戊己杂透主金融法律双职；若子时则印星未穿食神，无学历无稳职。","sec":"三、其余五例要点","t":"diff"},{"q":"银行支行行长命局「乙卯官克身临子女宫」，行「庚申运」合住乙卯却合坏食神，常应何事？","opts":["子女宫大旺，连生贵子且将来皆成金融高管","生育不利，易因医疗事故生出残疾孩子","食神生财有源，此运辞职下海赚得数亿身家","官星被彻底制伏，此运直接升任总行一把手"],"ans":1,"exp":"官杀克身临子女宫本身主孩子有毛病，庚申运乙庚合、卯申合虽把毛病合住，却合坏了子女宫食神，应医疗事故生残疾女儿。","sec":"三、其余五例要点","t":"rule"},{"q":"同为有职务的银行行长，为何生在广东等经商氛围浓的地区容易辞职下海，而北方多留任？","opts":["南方五行属火必克金，北方五行属水必生木","广东银行待遇远低于北方，故被迫下海谋生","伤官旺喜自由，且受地域经商风气影响而下海","北方有官命者不可经商，南方法律禁止做官"],"ans":2,"exp":"命局比劫伤官旺、伤官无印制，本就性格强悍喜自由；再遇经商气氛浓的地域（如广东），便易弃官下海。","sec":"三、其余五例要点","t":"diff"},{"q":"原银行女行长辞职下海后，行「壬戌运」遇「戌穿酉（酉为官杀）」并「寅戌拱火」，为何反发大财？","opts":["戌土生旺酉金官星，代表重新被银行返聘为高管","寅戌拱火彻底烧毁财库，代表先破大财后转运","壬戌运合住夫妻宫，代表全靠丈夫升官而发财","戌穿酉为制杀取财，寅戌拱火旺而制杀有力"],"ans":3,"exp":"酉为杀星，壬戌运中戌穿酉是制杀取财之功，且原局寅与戌拱旺火来穿酉制杀，制杀有力故下海能发大财。","sec":"三、其余五例要点","t":"rule"},{"q":"银行信贷员命局有「卯申伤官合印（收放）」在银行工作，为什么却「不能为官」？","opts":["月干己官透出成伤官见官，且时财午火破卯木","日主壬水身弱不胜财官，只能终身做普通柜员","卯申合把申金印星合坏，导致完全没有工作单位","原局没有见到财星与比劫，无法构成包局做功"],"ans":0,"exp":"虽有卯申合印为银行信贷，但一则月干透己官构成伤官见官，二则时支午火财星破卯木伤官格，两处坏局故不能为官。","sec":"三、其余五例要点","t":"rule"},{"q":"银行信贷员在丙子运遇「丙戌年」大客户信贷没签成、惹官非破财并分手，命理原因是什么？","opts":["戌土冲开辰土财库，导致资金全部被客户卷走","大运子卯破使戌引动卯无法合申，且丙壬冲日主","丙火合住辛金印星，导致自己主动辞职去创业","子水生旺卯木食伤，导致客户太多忙不过来"],"ans":1,"exp":"戌年本想引动卯去与申合，但大运子卯相破使卯申无法成合；同时流年丙火冲日主壬水，日主与太岁不和，故破财惹官非。","sec":"三、其余五例要点","t":"rule"},{"q":"信贷员行「乙亥运」，原局木多金少又逢大运「亥穿申」，为何赚钱变得格外辛苦？","opts":["乙木劫财合走申金，使银行彻底倒闭停业","亥卯未三合木局太旺，使日主必须转行做教师","木多需申金收木，亥穿申使日主与申印不和","亥水冲去午火财星，使所有客户贷款全部违约"],"ans":2,"exp":"木多金少需要申金收住木才旺财；行乙亥运时亥穿申，与申印不和，收放机制受阻，故赚钱辛苦。","sec":"三、其余五例要点","t":"rule"}]},{"n":114,"level":"高级","title":"职业象法九：地产商与建筑商","qs":[{"q":"下列干支柱中，哪一柱是戊土高岗取象高大建筑的象？","opts":["丁丑","乙卯","戊戌","己未"],"ans":2,"exp":"戊土为高岗，戊戌、戊申、戊辰、戊午参与做功取财，可以搞建筑；己未属木土组合一类，不是高岗象。","sec":"一、地产建筑命局的四类取象","t":"calc"},{"q":"卯戌合、卯未合、甲己合、寅未这类木土组合，取什么象？","opts":["钢筋水泥","酒店煤矿","高楼大厦","土木工程"],"ans":3,"exp":"木土组合＝土木工程；高楼取戊土，钢筋水泥取丑辰。","sec":"一、地产建筑命局的四类取象","t":"xiang"},{"q":"取「钢筋水泥」象的是哪两个地支，各藏什么？","opts":["丑中藏金、辰中藏乙","丑中藏金、戌中藏辛","辰中藏癸、戌中藏丁","辰中藏乙、未中藏乙"],"ans":0,"exp":"钢筋水泥取丑、辰两字：丑土中藏金，辰土中藏乙，丑辰参与做功。","sec":"一、地产建筑命局的四类取象","t":"xiang"},{"q":"十神中哪一个主房子，在地产命局里要参与做功？","opts":["比劫或比劫库","印或印库","官杀或官杀库","食伤或食伤库"],"ans":1,"exp":"四类象之一：印主房子，印或印库参与做功；辰为印库，辰戌冲就是印库做功。","sec":"一、地产建筑命局的四类取象","t":"rule"},{"q":"未、丑、戌三个地支，在地产类职业象里各代表什么？","opts":["未为煤矿，丑为酒店，戌为高楼矿山","未为矿山，丑为高楼，戌为酒店","未为酒店，丑为煤矿，戌为高楼矿山","未为高楼，丑为矿山，戌为煤矿"],"ans":2,"exp":"未代表酒店，丑为煤矿；戌代表高楼、矿山，戌在门户表地产建筑生意。","sec":"配套细节象","t":"xiang"},{"q":"财在墓库之中，被冲开、刑开，一般怎么论？","opts":["只有刑开才发财，冲开坏库","只有冲开才发财，刑开不发","冲刑开库都主破财","冲开、刑开都可以发财"],"ans":3,"exp":"只要财在墓库之中，冲开、刑开都可以发财。","sec":"配套细节象","t":"rule"},{"q":"丁印虚透，在地产命局里是什么象？","opts":["名誉，不是权力","房子，主置业","实权，掌管财权","学历，主读书"],"ans":0,"exp":"戊虚透、财虚透＝虚名、虚权；丁印虚透不是权力而是名誉。","sec":"配套细节象","t":"diff"},{"q":"木火燥土包局，又有印星参与，主什么？","opts":["不得财","能发大财","先富后破","官灾官司"],"ans":1,"exp":"木火燥土包局，印参与，能发大财；比劫夺财则先富后破。","sec":"配套细节象","t":"rule"},{"q":"原为官员的人下海经商，命局上常见什么原因？","opts":["比肩劫财得助，官星稳固","食神生财，印星被合","伤官配印格被破，财库被引动","官杀得制，印星旺透"],"ans":2,"exp":"原为官员下海，多是伤官配印格被破（如申亥相穿）、财库被引动，官位不久；打工起家多是印库（辰）加伤官配印。","sec":"判断步骤","t":"rule"},{"q":"判断地产建筑命局，走完找房子土木、看财库之后，第三步看什么？","opts":["大运是否冲开财库","婚姻星宫是否稳固","出身是官员还是打工","官杀与制化，能否制杀取财"],"ans":3,"exp":"步骤：先找房子与土木，再看财库，再看官杀与制化（制杀取财），再看出身，最后对运。","sec":"判断步骤","t":"step"},{"q":"地产命局里，哪种情形主先富后破？","opts":["杀无制、劫财夺财、比肩分财","印库被冲开","财库刑开发财","制杀取财成功"],"ans":0,"exp":"制杀取财成功可发大财；杀无制、劫财夺财、比肩分财则是先富后破。","sec":"判断步骤","t":"rule"}],"fine":[{"q":"在地产建筑命局的「制杀取财」结构中，若官杀「制不干净」时对取财有何影响？","opts":["制不干净只能领固定工资，绝不能做老板","必须制得绝对干净才能取财，否则必贫","制不干净也能取财","制不干净则官杀无制，必定引发牢狱之灾"],"ans":2,"exp":"在制杀取财的财富结构中，官杀制而取财，即使制不干净（如辰戌冲伤官库制杀库），依然可以发财。","sec":"配套细节象","t":"rule"},{"q":"从出身来源看，「原为官员下海」与「打工起家的建筑老板」在命局上各有何常见特征？","opts":["两者均必须原局无印星且日主坐下为伤官库","官员下海多比劫羊刃库发用，打工起家多财星虚透无印","官员下海多官杀无制合身，打工起家多财库永远闭塞","官员下海多伤官配印格被破，打工起家多印库辰加伤官配印"],"ans":3,"exp":"原为官员下海多因伤官配印格被破、财库被引动而官不久；打工起家则常见印库（辰）加伤官配印。","sec":"判断步骤","t":"diff"},{"q":"原局「未戌刑开火库、申金七杀被夹制」可制杀取财，但时柱逢「乙亥羊刃」有何隐患？","opts":["乙亥羊刃有劫争之意，走夺财运易功败垂成","乙亥羊刃冲开财库，主越到晚年财富积累越多","乙亥羊刃生旺火库，主终身在政府部门当高官","乙亥羊刃合住七杀，主一生不敢投资只能打工"],"ans":0,"exp":"时逢乙亥羊刃有比劫争夺之意，一旦行入比肩夺财、坏格的大运，极易功败垂成而大破财。","sec":"二、命例详解","t":"rule"},{"q":"靠「巳申合」制申金七杀取财的建筑商，行「甲辰运」逢「丁亥年」为何投资破财上千万？","opts":["亥水生旺木气太盛，导致身体突发严重疾病住院","甲比肩夺财、辰拱杀为反局，亥年坏火不能制杀","甲辰运合住戌土财库，导致所有工程款全部被冻结","丁亥年冲开辰土印库，导致被迫回到原单位上班"],"ans":1,"exp":"甲辰运甲比肩夺财、申辰拱杀星得助，已是反局大运；丁亥年见亥水坏火、无法制申金七杀，故投资破大财。","sec":"二、命例详解","t":"rule"},{"q":"地产商命局中「年月丑未冲，丑为印库代表房子」，「未冲丑」在地产销售上取什么象？","opts":["辞去公职与别人合股去开采煤矿","工程质量出问题被客户退房索赔","别人拿钱来购房（房子好卖）","自己掏钱去买地皮但手续受阻"],"ans":2,"exp":"丑为印库代表房子，未土财星来冲丑土印库，取象为别人拿钱来购房。","sec":"二、命例详解","t":"xiang"},{"q":"原局有「卯戌合、丑未冲」的地产商，行「己酉运」虽有己杀克身，为何房子反而很好卖？","opts":["酉金冲去卯木妻星，代表全部资金投入买地皮","己土生旺酉金印星，代表政府直接包销所有楼盘","己酉一柱合住日主，代表停止开发转行做银行","酉到代表丑印库到，卯酉冲、酉戌穿引动地产象"],"ans":3,"exp":"己酉运中酉金代表丑土印库到位，地支卯酉冲、酉戌穿引动了原局的房子与财库，故房子很好卖。","sec":"二、命例详解","t":"calc"},{"q":"富翁命局见「戌未刑开财库、戊戌在门户」，为何同样是产业，「丑为煤矿」却主合股经营？","opts":["丑占比肩代表合股，且丑入辰墓受别人控制","丑未冲太猛烈，代表煤矿必然发生坍塌事故","丑为阴中之阴，代表只能自己独资不能找合伙人","丑土生旺门户戊戌，代表煤矿利润远高于地产"],"ans":0,"exp":"戊戌在门户主地产建筑，未为自营酒店，而丑为煤矿因上面坐着比肩（辛），故主与他人合股，且入辰墓易受人控制。","sec":"二、命例详解","t":"xiang"},{"q":"合股开煤矿的富翁在「丁亥年」投资煤矿，为何到「戊子年」却发现资金无法收回而破财？","opts":["戊土劫财直接合走亥水，导致煤矿彻底被政府查封","子年合丑穿未破坏丑未冲，且丑落比肩下受人控制","戊子自合化为火局，导致合作伙伴携款潜逃国外","子水冲去午火印星，导致自己官司缠身无暇管理"],"ans":1,"exp":"丑为煤矿落在比肩下受别人控制，又丑入辰墓本就难冲未；戊子年子合丑、子穿未，彻底破坏了丑未之冲，故破财。","sec":"二、命例详解","t":"diff"},{"q":"地产商命局「壬寅为杀星带财主公门之人，三合局生起主位午火印星」，在人脉上主什么象？","opts":["早年曾任正处级官员后被迫下海经商","经常因行贿受贿被纪检部门立案调查","会处理政商关系，或高官给他带来财富","极度讨厌与官员打交道，全靠纯技术打拼"],"ans":2,"exp":"壬寅杀带财主公门高官，寅午戌三合局将杀财生入主位午火印星（企业），说明善处理政商关系，靠官员带来财富。","sec":"二、命例详解","t":"xiang"},{"q":"数十亿地产商在「丁亥年」花钱买虚官进入人大、政协，其命理上的标志是什么？","opts":["亥水冲破午火印库，代表用房子换取实权官位","丁壬合化木局生身，代表正式调回政府当厅官","亥卯未三合比肩局，代表与战友合伙承包大工程","丁印坐财星，印虚透不是权力而是名誉"],"ans":3,"exp":"丁印坐在亥水财星之上，印星虚透代表的是虚名与社会名誉，而不是实际行政权力，正应花钱买虚官之象。","sec":"二、命例详解","t":"rule"},{"q":"以「午火印星」为企业、时上见「戌土比肩」的先富后破地产商，行「己酉运」为何可能破产？","opts":["己为午印变劫财，酉午破印且卯酉冲伤官见官","己土合住甲木印星，导致银行贷款全部被提前抽回","己酉一柱伏吟夫妻宫，导致配偶离婚分走全部家产","酉金冲开戌土财库，导致投资煤矿全部血本无归"],"ans":0,"exp":"己是午火印星跑出变成劫财夺财；酉午相破破了自己的印星企业，卯酉冲伤官见官惹官司，加上戌土比肩归局必破尽。","sec":"二、命例详解","t":"rule"},{"q":"地产商命局「壬寅为大老婆、癸卯为二老婆（包在局中、戊癸合）」，这体现了怎样的婚姻象？","opts":["夫妻恩爱无比，一生绝无任何婚外情与二婚象","戊癸合为老少配，卯包在局中为金屋藏娇且不离","大老婆必定早逝，二老婆必定与人私奔而离婚","婚姻必离三次以上，且每次离婚皆因破产导致"],"ans":1,"exp":"壬寅、癸卯为双妻象；癸卯被包在局中有金屋藏娇之意，戊癸合为老少配，因局中包住故婚姻虽不好但不离婚。","sec":"二、命例详解","t":"diff"},{"q":"基础工程老板早年行「癸酉运」遇「卯酉冲」，为何只能干体力活、不怎么赚钱？","opts":["酉金合住辰土印库，导致考上大学后不愿去工地","癸水生旺卯木劫财，导致把所有工程款拿去赌博","丁癸冲伤官不配印，且官杀不制服反冲羊刃","酉金穿坏午火食神，导致长期生病卧床无法工作"],"ans":2,"exp":"癸酉运中丁癸冲使伤官不能配印；酉合辰虽有单位上班，但卯酉冲是官杀不能制服为财反冲羊刃，故干体力活不赚钱。","sec":"二、命例详解","t":"rule"},{"q":"工程老板在「乙亥运丁亥年」大起步，却因工地事故死伤几人赔百余万，其象理原因是什么？","opts":["亥水冲去巳火印星，导致政府强行查封施工现场","乙木透干合走庚金，导致合作伙伴卷走工程款项","丁火克伤辛金食神，导致施工图纸计算严重失误","卯为手足工人，亥生旺卯劫财强化卯辰穿致伤亡"],"ans":3,"exp":"亥从辰库出成伤官配印故业务大起步，但流年亥生助卯木劫财强化卯辰穿；卯在象上为手足、工人，穿而应工人伤亡。","sec":"二、命例详解","t":"xiang"},{"q":"工程老板在流年「己丑」赚数亿的同时却做了肺部手术，其中「丑午穿」如何取病象？","opts":["穿有手术之意，丑为肿块，丑中藏金主肺","丑土代表腿脚，午火代表心脏，穿主腿部骨折","午火代表肺部，丑土代表胃肠，穿主消化不良","己土代表皮肤，午火代表眼睛，穿主眼部手术"],"ans":0,"exp":"丑午穿穿到月令代表身体疾病，「穿」有动手术之象，丑土为肿块，丑中藏辛金主肺，故应肺部肿瘤手术。","sec":"二、命例详解","t":"xiang"},{"q":"男命第二任伴侣取「午火（带七杀、临伤官）」，在人物特征上如何直读？","opts":["带杀主未婚少女，临伤官主学历极高有博士学位","带杀主离过婚（带孩子），临伤官主年龄偏小","带杀主政府高官，临伤官主脾气暴躁难相处","带杀主外国国籍，临伤官主长期两地分居不见面"],"ans":1,"exp":"女命或妻星带杀常主离过婚（甚至带孩子），而临伤官则表示年龄比男方小很多。","sec":"二、命例详解","t":"xiang"},{"q":"原副处级公务员命局「戌穿酉」主有权，为何最终还是离职下海做地产与矿山？","opts":["原局比劫羊刃库太旺，被迫转业去企业当顾问","原局辰戌冲把酉金彻底冲灭，被单位开除公职","原局出现卯戌贪合而忘穿，后离职求财","原局财星虚透无根，为了还债而辞去职务下海"],"ans":2,"exp":"原局戌穿酉是坐下杀星发用有权，但时支卯木与戌构成「卯戌贪合而忘穿」，卯戌合木土组合遂离职下海求财。","sec":"三、其余四例要点","t":"rule"},{"q":"丁未运合伙做地产发财数千万的命局，从哪两个细节看出是「合伙发财」？","opts":["未土刑开戌库独享财富，且比肩远隔不与财接触","年上酉金独财生助官星，且日主坐下财库完全不开","卯戌合彻底合去劫财，且丁壬合全部归于日主一人","丁财合到比肩帮身取财，制杀的卯落劫财下"],"ans":3,"exp":"丁财合到比肩（帮身合财取财），且用来制杀的卯木落在时干癸水劫财之下，落于劫财下即代表与他人合伙发财。","sec":"三、其余四例要点","t":"diff"},{"q":"「印为房子，辛丑为财」，为何行「庚午运（午穿丑）」是替别人卖房，到「辛未运（未冲丑）」才自己做开发？","opts":["午代表寅是别人的房子，未是印库冲开财库自己开发","午运火太旺烧毁房子，未运土太燥只能做中介","午运属于官运只能上班，未运属于比劫运只能合伙","午运财库被彻底冲破，未运印星被合住不动"],"ans":0,"exp":"庚午运中，午代表年上寅印（别人的房子），午穿丑＝替别人卖房；辛未运未是印库冲开辛丑财库，用房子换财富自己开发。","sec":"三、其余四例要点","t":"diff"},{"q":"国企地产副总行「戊辰运」离开国企后反而赚很多钱，其命理原因是什么？","opts":["辰土生旺酉金官星，代表被民营企业聘为名誉董事长","辰冲坏戌权力致离职，但戊癸合且辰卯穿财发用","戊土劫财夺去辛金日主之财，代表转行做金融信贷","辰戌冲彻底破坏伤官配印格，代表靠投机股票暴富"],"ans":1,"exp":"辰冲坏年上戌土权力故离开国企；但戊癸合伤官配印依然成立，且辰代表亥到与坐支卯木相穿，财星发用故赚大钱。","sec":"三、其余四例要点","t":"rule"},{"q":"甲木日主财星偏旺本难发财，为何「两巳包局」且「巳火变丙虚透到年」反成包工头生意组合？","opts":["两巳火直接冲走子水印星，代表脱离文化行业搞建筑","巳火入墓于辰库不开，代表替国家单位看守工程资金","巳火由实变虚透到年上，是生意买卖成立的组合","丙火生旺己土财星，代表全部财富都靠配偶家里提供"],"ans":2,"exp":"甲日财旺本难发财，但两巳包局有食神配印之意，更喜巳火变丙火虚透到年上，这种由实变虚正是生意买卖成立的组合。","sec":"三、其余四例要点","t":"rule"},{"q":"承包工程老板在「丙戌年」项目全面开工，而次年「丁亥年」却谈不成项目，关键区别在于？","opts":["丙戌年官星合身得领导赏识，丁亥年伤官见官惹上官司","丙戌年合住夫妻宫稳固，丁亥年冲克子女宫导致分心","丙戌年财库闭塞不用花钱，丁亥年比劫夺财资金链断裂","戌冲辰为过河拆桥利开工，亥冲破巳申合故谈不成"],"ans":3,"exp":"丙戌年戌冲宾位辰土印库，属于过河拆桥之功，故项目全面开工；丁亥年亥水冲破大运与原局的巳申合，故项目谈不成。","sec":"三、其余四例要点","t":"diff"},{"q":"以「两巳包局、子印为用」的包工头，为何行「丁酉运」继续干工程必破财？","opts":["酉合化巳火变酉，酉破子坏印且合辰把钱倒出去","酉金冲走卯木劫财，导致工地上所有工人全部辞职","丁火克伤庚金七杀，导致政府招标项目全部停工","丁酉一柱合住甲木日主，导致自己患病无法下工地"],"ans":0,"exp":"丁酉运中酉金合化原局巳火使之变酉（败局），同时酉破子水坏印星、酉合辰土印库把钱倒出去，故继续干必破财。","sec":"三、其余四例要点","t":"rule"}]},{"n":153,"level":"专题","title":"体用与宾主作用专题","qs":[{"q":"看父母，宫与星怎样受损才断父母亡？","opts":["宫星任一受损即断亡","体用同时出问题才断，只坏一边不断","用坏即断，体坏只主病","体坏即断，用坏只主病"],"ans":1,"exp":"生身父母只有一个、一生不能换，所以必须体（宫）用（星）同坏才下重断。","sec":"1. 宫为体，星为用","t":"rule"},{"q":"妻宫为忌且受冲，而妻星为喜、旺相，论刑妻吗？","opts":["只在流年再冲时才克","要看妻星强弱才定","论，体为忌受冲则不论用都克妻","不论，妻星喜且旺则不克"],"ans":2,"exp":"妻宫为体、妻星为用；体为忌、受冲，则不论用是喜是忌、强弱，都会克妻。","sec":"1. 宫为体，星为用","t":"calc"},{"q":"子女的体、用受损，分别应什么？","opts":["体受损＝生后遇凶；用受损＝小产","体用都损才有子女之事","体受损＝晚年无子；用受损＝小产","体受损＝小产；用受损＝生后遇凶"],"ans":3,"exp":"子女受胎时看体（母体），出生后以用为主；故体损小产，用损生后遇凶。","sec":"1. 宫为体，星为用","t":"diff"},{"q":"体制用与制体所出之物，哪个为正局？","opts":["体制用的东西为正，制体所出为反","制体所出之物为正，制用为反","只要制住，都论正局","制官杀为反，制财为正"],"ans":0,"exp":"水是官杀（用的东西），体来制，天经地义是正局；水是体自身生出的伤官，宜用不宜制，制它则成反局。","sec":"1. 正局与反局：谁是体、谁是用","t":"diff"},{"q":"财旺却无功，须怎样财才聚、才作功？","opts":["须无官杀，财才不被分夺","须见官，官星统财才聚","须比劫帮身，身强任财","须食伤生财，财越旺越好"],"ans":1,"exp":"财旺不等于有功，财多本身没有用，须见官，官统财才能聚；也可财去印、去劫财、入库。","sec":"2. 财多无功：何时有功","t":"rule"},{"q":"财（水）极大时，制财宜用哪种方式？","opts":["三种制法效果相同","只有官星统财才行","合制或泄制，克制无功反害","克制为主，越克越净"],"ans":2,"exp":"制财之法有合制、克制、泄制；水大时克制无功反害，宜合制、泄制。","sec":"2. 财多无功：何时有功","t":"rule"},{"q":"木火局与金水局，哪个先天有功？","opts":["两者都先天有功","两者都先天无功","金水局先天有功，木火局先天无功","木火局先天有功，金水局先天无功"],"ans":3,"exp":"火炎上、水润下：木火成势时时上伤官也制得住；金水成势，伤官成废神，只能务农或当兵。","sec":"3. 木火局有功，金水局先天无功","t":"rule"},{"q":"「合用财星」与「合用官星」，看法的区别是？","opts":["合财看身强弱；合官看官下之支","两者都看所坐之支","两者都看身强弱","合官看身强弱；合财看财下之支"],"ans":0,"exp":"合财要看身之强弱（弱喜财虚透、旺喜财旺相）；合官没有这种说法，要看官下之支是什么。","sec":"4. 合用官星、合用财星","t":"diff"},{"q":"日支被制，哪类星可制？","opts":["正偏都不可制","偏的可制，正的一般不可制","正的可制，偏的不可制","正偏都可制"],"ans":1,"exp":"日支被制也是做功：杀坐支、偏的可制，制则做功；正的一般不可制，制则伤亲人。","sec":"5. 合禄局与日支被制","t":"rule"},{"q":"下列四柱，哪一柱干支同象（天干属性可与地支同看）？","opts":["己巳","乙亥","癸卯","壬申"],"ans":2,"exp":"凡天干生地支的柱子才同象：癸生卯；乙亥、己巳、壬申都是支生干，不同象。","sec":"4. 天干异性相克与同象","t":"calc"},{"q":"天干之间异性相克，功如何？","opts":["只在天干气弱时无功","有功，且大于同性相克","同性异性相克功相同","无功，除非合制"],"ans":3,"exp":"天干异性相克无功（除合制外）；同性相克功也不大，天干气弱则更小。","sec":"4. 天干异性相克与同象","t":"rule"},{"q":"看盘时，判断谁来作功的先后顺序是？","opts":["日主，再日支，再日主的延伸物","日支，再日主，再延伸物","月令，再日主，再日支","先定身强弱，再看从与不从"],"ans":0,"exp":"先看日主是否参与作功；不参与看日支；再不参与看延伸物。日主不参与就弃之不看，强弱无关紧要。","sec":"2. 看盘顺序","t":"step"}],"fine":[{"q":"看克子时，除了看官杀（子星）外，还必须重视哪一神及其原神？","opts":["比劫，比劫夺食伤才主子女有凶","财星，官杀与其原神都出问题才主子女有凶","食伤，食伤见枭神夺食才主子女有凶","印星，官杀受印泄太过才主子女有凶"],"ans":1,"exp":"子星不只看官杀，财也重要；须官杀与其原神（财）都有问题，子女才有问题。","sec":"1. 宫为体，星为用","t":"rule"},{"q":"六亲体用中，什么情况被称为「副妻宫」？","opts":["月支与日支同五行，主妻子姐妹同宫","日支坐偏财，主婚外另有偏房或暗情","妻宫之星原身多透（多现），主多妻或有克","妻星合入时支，主晚年再娶或二婚"],"ans":2,"exp":"妻宫之星「多现」（原身多透，如甲透多个）称为副妻宫，宫多则主多妻或有克。","sec":"1. 宫为体，星为用","t":"rule"},{"q":"乾造甲申、甲戌、丙寅、壬辰，年、月干两甲木看祖父排行与父宫，如何区分？","opts":["月柱为老大、年柱为老二，祖父排行第一而父亲排行第二","年月干同为甲木，不分祖父与父亲，统以申金为父星","年柱为父母宫、月柱为祖父宫，年甲为父、月甲为祖父","年柱为老大、月柱为老二，年甲为祖父宫、月甲为父宫"],"ans":3,"exp":"年干甲为祖父宫，年柱为老大、月柱为老二，祖父排行第二；月干甲为父宫，申为父星。","sec":"2. 命例：一造完整的六亲体用","t":"xiang"},{"q":"乾造甲申、甲戌、丙寅、壬辰，断其有「假哥哥」与假弟弟，原局象理何在？","opts":["月令戌中丁火临空亡为假哥，戌寅拱虚午为假弟","日支寅中丙火透出为假哥，月支戌冲辰土为假弟","年干甲木坐申绝地为假哥，时干壬水坐辰库为假弟","月干甲木逢空亡为假哥，年支申金冲寅木为假弟"],"ans":0,"exp":"父收养的孤儿为假兄弟：月令戌中丁火临空亡所以是假哥哥；戌寅拱出虚午，另有一个假弟弟。","sec":"2. 命例：一造完整的六亲体用","t":"xiang"},{"q":"大运的体用与原局相反，行「干运」时，体用与应事如何？","opts":["干为体、支为用，运干不动而支动，易功败垂成","支为体、干为用，运支不动而干动，做事顺手","干支皆为体，需流年冲刑方能引动大运之功","干支皆为用，原局日主为体，行运顺逆皆难主事"],"ans":1,"exp":"口诀：行干运，支为体、干为用。行干运时运支不动、干在动，干怎么做都顺手。","sec":"3. 体用的两条补充","t":"rule"},{"q":"大运行「支运」时，为什么往往做了很多事却容易功败垂成？","opts":["支为体、干为用，支不动而干动，干无根基难成事","支运不作用原局天干，所做之事皆属虚浮无根","干为体、支为用，干不动而支动，支受干象管束","支运必与原局日支相冲，导致主位体受损而败"],"ans":2,"exp":"行支运时，干不动、支动（干为体、支为用），支受干象所管，做了很多事也往往功败垂成。","sec":"3. 体用的两条补充","t":"rule"},{"q":"八字中官财之库（如未库吃进一片木）若不刑不冲，作何论？","opts":["暗中生旺，库中之物倍增而主暴富","化为食伤，虽不开库也能自然泄秀生财","自动开库，遇合年即可尽取库中之财","只吃不拉，库中之物积压而无用"],"ans":3,"exp":"官财之库不刑不冲就无用，好比只吃不拉，越积压越多而无法周转变现。","sec":"3. 体用的两条补充","t":"rule"},{"q":"坤造癸卯、乙卯、戊寅、己未，年柱癸卯看似官星，其实质如何定性？","opts":["官带财象，实质是财，戊癸合为做功核心","纯以正官论，卯木入未库即为官星归位得权","纯以正财论，癸水生乙木即为财生官而贵","财带官象，实质是官，乙木克己土为做功核心"],"ans":0,"exp":"癸卯一柱官带财象，看是官、实质是财；戊癸之合才是做功核心，乙木泄癸反把财换成货物。","sec":"3. 体用的两条补充","t":"xiang"},{"q":"乾造戊午、己未、庚辰、戊子，为何不能按「伤官佩印格」论贵？","opts":["子水伤官坐时支无力，不能泄庚金顽金之气","辰拱出子水伤官，制体所出之物成反局","戊土偏印透干太多，印多为病而夺去食神之秀","午未合土太过，印星焦燥不能生金反成克战"],"ans":1,"exp":"子水伤官出于日支辰，是主位体自身生出之物，宜用不宜制；辰拱子水而欲制之，反局成病。","sec":"1. 正局与反局：谁是体、谁是用","t":"calc"},{"q":"财旺无功时，除了见官星统财或财入库外，还有哪两种让财作功的方式？","opts":["食神泄秀（表才华）或印星护身","禄神合财（表俸禄）或羊刃敌杀","财去印（表有工作）或财去劫财","比劫分财（表合伙）或伤官生财"],"ans":2,"exp":"财作功除官星统财、入库外，还可财去印（表有工作）、财去劫财，关键是有矛盾转化与效果。","sec":"2. 财多无功：何时有功","t":"rule"},{"q":"乾造戊辰、辛酉、壬子、癸卯，时支卯木为何被定为「废神」？","opts":["因为壬水日主不喜木气，故卯木先天即属忌神","纯粹因为辰卯相穿，把卯木彻底穿坏而无用","因为酉金遥冲卯木，使卯木伤官根气尽断","卯木不长、子不太生它，且伤官心性不好不能泄秀"],"ans":3,"exp":"卯木是废神并非只因辰穿：卯不太长、子不太生它，又是伤官心性不好，不能泄秀便纯粹是废神。","sec":"3. 木火局有功，金水局先天无功","t":"calc"},{"q":"乾造辛卯、丙申、辛巳、丙申，称「巳被他合」，这里「他合」具体指哪一组？","opts":["日支巳与时支申的巳申合","年干辛与月干丙的丙辛合","年支卯与时支申的暗合","日干辛与日支巳的辛巳自合"],"ans":0,"exp":"丙辛合与辛巳自合都要看；「巳被他合」专指巳申合，年月干丙辛合不算他合。","sec":"4. 合用官星、合用财星","t":"calc"},{"q":"合用财星时，身弱与身旺对财星状态的喜忌有何不同？","opts":["身弱喜财星旺相；身旺喜财星虚透","身弱喜财星虚透；身旺喜财星旺相","不论身强身弱，合财皆喜财星旺相入库","不论身强身弱，合财皆喜财星虚透主才"],"ans":1,"exp":"合财两条规则：身弱合财喜财星虚透，财重则无财；身旺合财喜财星旺相，财虚不主财富（换象除外）。","sec":"4. 合用官星、合用财星","t":"diff"},{"q":"身旺合财时，若去财干净可以「换象」，换象后以什么当财看？","opts":["以官杀当财，财星旺相则主掌权","以印星当财，财星入库则主房产","以比劫当财，财星虚透则主才气","以食伤当财，财星受克则主技艺"],"ans":2,"exp":"身旺合财去财干净可以换象，即比劫当财；若财星虚透不主财富，主才气。","sec":"4. 合用官星、合用财星","t":"rule"},{"q":"八字中出现「合禄局」，若合局的中神（禄）在月令，通常主何职业定位？","opts":["专靠配偶家财过活，自己无需出门谋生","自立门户当老板，能统领他人为自己生财","归隐山林或自由职业，不受任何单位管束","为他人工作，自己参加其中而不能自当老板"],"ans":3,"exp":"合禄局中神在月令，是为他人工作，自己只是参加其中，不能自当老板。","sec":"5. 合禄局与日支被制","t":"xiang"},{"q":"日支为正星本不可制，若此正星遭遇「穿」（如子被未穿），则有何变化？","opts":["正星一穿即反，相当于偏星，反可制而婚姻无大碍","正星被穿则化为废神，既不作功也不伤亲人","正星被穿即转为比劫，主配偶外遇而离婚","正星被穿更凶，不仅破财且必主配偶早亡"],"ans":0,"exp":"日支正星一般不可制，制则伤亲人；但正星一穿即反，相当于偏星，故婚姻反无大问题。","sec":"5. 合禄局与日支被制","t":"rule"},{"q":"遇到「相克之穿」（穿与被穿）时，如何判断究竟是谁穿谁？","opts":["固定以主位穿宾位，主位永远占优势","看势在哪边，得势一方即能穿对方","固定以旺神穿衰神，不看全局气势偏向","固定以克者穿被克者，五行受克方必败"],"ans":1,"exp":"「穿与被穿」的关键：相克之穿看势在哪边，得势一方即能穿对方。","sec":"5. 合禄局与日支被制","t":"rule"},{"q":"宾主作用中，原则是「宾作用主」，但从「象」的角度看，主能否反克宾？","opts":["不能，主克宾称为犯上，必主命主自身遭灾","不能，大运流年为宾永远只单向作用原局","可以，主也可反克宾，应在象所代表的人身上","只有在日主身旺时主才反克宾，身弱则不能"],"ans":2,"exp":"大运流年为宾、原局为主，原则上宾作用主；但从象上说主也可「反克」宾，应在象所代表之人身上。","sec":"1. 主与客","t":"rule"},{"q":"关于父母、夫妻、子女星位在原局中的寻找范围，下列说法正确的是？","opts":["六亲星位都只能在各自对应的宫位上寻找","父母可在局中任何位置；夫妻只在日支寻找","父母夫妻只在年月找；子女只能在时柱找","父母只在年月找；夫妻子女可在局中任何位置"],"ans":3,"exp":"父母只在年月找；夫妻子女可在局中任何位置。宫位比星位重要，子女不育或克子女时宫位才显示。","sec":"1. 主与客","t":"diff"},{"q":"当遇到「日主有合」（如一丁合两壬）的命局时，看盘的核心切入点是？","opts":["日主有合，当以合为主看","先定身强身弱，身弱则合而不化作忌神看","弃合不看，专看日支与月令的冲刑关系","只看年月透干之壬，日主合者一律作争合论"],"ans":0,"exp":"日主有合，当以合为主看；如一丁两壬，壬为父，坐辰、坐寅表父的不同状态及父多婚。","sec":"3. 命例：日合二官，以合为主看","t":"rule"},{"q":"乾造癸卯、戊午、己酉、甲戌，年柱癸卯也是天干生支，为何不以癸卯同象当钱看？","opts":["因为只有日柱干生支才算同象，年柱不算同象","癸财虚透不当钱看，实以合官用劫及戌穿酉取财","因为卯戌相合化火，癸卯已变质为印星而非财","因为癸水被戊土合克，卯木被彻底孤立无根"],"ans":1,"exp":"癸财虚，不当钱看，与癸卯同象无关；此造合官用时上劫，食神当财，戌穿酉制之取财。","sec":"4. 天干异性相克与同象","t":"calc"},{"q":"看作功时，若「日主与日支意思不一致」，应以谁为主？构成什么局？","opts":["二者各自独立作功，互不干扰也不成反局","以日支为主，日主虚浮无力只作从属看","以日主为主，日支背离日主或势时常成反局","以月令为主，日主与日支皆需顺从月令气势"],"ans":2,"exp":"看盘顺序以日主为先，日主与日支意思不一致时以日主为主；日支若在势中坏日主所用，即成反局。","sec":"2. 看盘顺序","t":"rule"},{"q":"以「寅亥合」为例，从「强弱角度」与「作功角度」看有何区别？","opts":["强弱角度看寅克亥为身弱；作功角度看寅亥合旺有功","强弱角度与作功角度都以亥生寅木为吉，不可分开","强弱角度看寅亥相破；作功角度看亥水生禄有大功","强弱角度看亥生禄为身强；作功角度看寅亥合绊无功"],"ans":3,"exp":"寅亥合，亥生了禄是从强弱角度讲身强财旺；而寅亥合绊（不发挥作用）是从作功角度看，二者不可混。","sec":"4. 强弱角度与作功角度不同","t":"diff"},{"q":"差命中属于体力劳动者的一类，在作功上的典型特征是？","opts":["自己作功、消耗能量，但作功效率特别低","日柱完全不参与作功，一生清闲但贫穷","八字全无功神，但有大势顺从日主而无对手","专靠冲克作功，能量大且效率极高却不聚财"],"ans":0,"exp":"差命有两类：一类自己作功、耗能量，但效率特别低（如体力劳动者，辛苦赚钱少）；另一类日柱不作功。","sec":"5. 能量与效率","t":"rule"}]},{"n":154,"level":"专题","title":"应期与墓穿专题","qs":[{"q":"按盲派，流年在应期上管什么？","opts":["管年龄段，一柱管若干年","既管应期，也直接定吉凶","只管应期，吉凶由原局与大运定","只管吉凶，不管应期"],"ans":2,"exp":"流年只起引动作用，必须配合大运与原局才定吉凶；大运才是定吉凶的一层。","sec":"一、应期的基本框架（补充）","t":"rule"},{"q":"行地支大运时，体用怎么分？","opts":["干支皆为用，以原局为体","干支皆为体","天干为体，地支为用","地支为体，天干为用"],"ans":3,"exp":"行天干运天干为体、地支为用；行地支运则反过来，地支为体、天干为用。","sec":"一、应期的基本框架（补充）","t":"rule"},{"q":"原局有卯（木禄），流年见乙，和原局有未，流年见乙，两种情形的「虚到」分别怎么论？","opts":["乙代卯主虚透弱化；乙代未只主到位","两种都只主到位，不弱化","乙代卯只主到位；乙代未主虚透弱化","两种都主弱化"],"ans":0,"exp":"禄神虚到大运流年主虚而弱化；墓神或余气虚到不弱化，只表示到位。乙对应卯、未、辰。","sec":"一、应期的基本框架（补充）","t":"calc"},{"q":"按干支互应对照，庚、辛、壬三个天干在流年出现，各自主要应到哪些地支？","opts":["庚应申、酉；辛应酉；壬应亥、子","庚应申；辛应酉、丑；壬应亥、申","庚应申、丑；辛应酉、戌；壬应亥、申","庚应申；辛应酉；壬应亥、子"],"ans":1,"exp":"互应表：庚—申，辛—酉、丑，壬—亥、申。辛可应丑，壬可应申，是易漏处。","sec":"一、应期的基本框架（补充）","t":"calc"},{"q":"大运与八字有合时，流年冲大运，「当运」与「不当运」有何不同？","opts":["不当运为破合，当运为引动","不当运为冲去，当运为引动","不当运为引动，当运为冲去","无论当运与否都是冲去"],"ans":2,"exp":"冲运：不当运是引动，当运才是冲去；冲的若是八字中的字，应论破合。","sec":"一、应期的基本框架（补充）","t":"diff"},{"q":"子、午、酉、卯见各自的墓（如酉见丑），一般怎么论？","opts":["以破论，墓气外泄","一律以入墓论","以冲论，墓被冲开","因有半合局，以拱合论，不以墓论"],"ans":3,"exp":"子午酉卯见各自墓一般不以墓论；但中神已很弱要死时见墓才为应期，死、墓、绝三者为应。","sec":"六、墓的细则","t":"rule"},{"q":"年支午、月支戌，位置先后相对，在盲派里算什么？","opts":["拱，不是入墓","入墓，位置先后不影响","冲，午戌相对为冲","入墓，须年支在前"],"ans":0,"exp":"午戌、子辰之类位置相对是拱，不是入墓；寅申巳亥见墓入之、多而墓之才是入墓。","sec":"六、墓的细则","t":"diff"},{"q":"「害」对墓库起什么作用？","opts":["害可以开墓","害不能开墓","害能开墓但力量弱","害只能开阳库不能开阴库"],"ans":1,"exp":"占事盘里戌库与酉相害，害不能开墓，所以鸟出不了门；刑、冲才可开库。","sec":"六、墓的细则","t":"rule"},{"q":"禄神在八字中出现（含伏吟），什么情形下才算凶？","opts":["只要禄伏吟就凶","只要禄被财星见到就凶","禄无功、遭局中回制穿害，或单薄无助","禄为功神且合气势时才凶"],"ans":2,"exp":"禄是功神且局中是禄的气势，伏吟反而发迹；禄无功、被回制穿害、单薄无助，出现则凶。","sec":"六、墓的细则","t":"rule"},{"q":"八字中一方两个戌、一方一个辰（戌辰戌戌之类），戌冲辰结果如何？","opts":["双方相抵，辰戌皆无损","辰反冲戌，戌被冲坏","三戌拱辰，辰得保护","一方二、一方一不平衡，辰被冲坏"],"ans":3,"exp":"一方两个、一方一个，力量不平衡，少数一方坏；若夹在两边则是夹冲，与夹刑不同论。","sec":"六、墓的细则","t":"rule"}],"fine":[{"q":"八字中的字若以「禄、原身、藏干」形式出现在大运或流年，作用有何不同？","opts":["不论出现在大运还是流年，都直接主定吉凶","出现在大运只是引动；出现在流年被八字作用定吉凶","出现在大运被八字作用定吉凶；出现在流年只是引动","不论出现在大运还是流年，都只起引动作用"],"ans":2,"exp":"大运干支与原局作用定吉凶，八字之字以禄、原身、藏干现于大运亦定吉凶；现于流年只是引动。","sec":"1. 大限、大运、流年的分工","t":"diff"},{"q":"通过墓之气到位来「引动墓库」时，哪些地支可引动丑库、哪些可引动辰库？","opts":["亥、子可引动丑，申、酉可引动辰","寅、卯可引动丑，申、酉可引动辰","巳、午可引动丑，寅、卯可引动辰","申、酉可引动丑，亥、子可引动辰"],"ans":3,"exp":"通过合局、墓之气到位能引动墓库：丑为金库，申、酉可引动丑；辰为水库，亥、子可引动辰。","sec":"2. 应期的三种方式","t":"calc"},{"q":"按干支互应对照表，甲、乙、丙、丁四个天干各自应到的地支是？","opts":["甲应亥寅；乙应卯未辰；丙应寅巳；丁应午戌未","甲应寅；乙应卯、未；丙应巳、戌；丁应午、丑","甲应亥寅；乙应卯未；丙应巳午；丁应午戌","甲应寅卯；乙应卯辰；丙应巳午；丁应午未"],"ans":0,"exp":"干支互应表：甲—亥、寅；乙—卯、未、辰；丙—寅、巳；丁—午、戌、未。","sec":"3. 干支互应对照表","t":"calc"},{"q":"按干支互应对照表，戊、己、癸三个天干各自应到的地支是？","opts":["戊应巳戌；己应午丑；癸应子亥丑","戊应巳戌辰；己应午未丑；癸应子辰丑","戊应辰戌；己应丑未；癸应亥子","戊应午戌辰；己应巳未丑；癸应子申辰"],"ans":1,"exp":"干支互应表：戊—巳、戌、辰；己—午、未、丑；癸—子、辰、丑。","sec":"3. 干支互应对照表","t":"calc"},{"q":"判断天干在命局中的「干支虚实」，依据的标准是？","opts":["以月令是否得生得助来定天干虚实","以整个命局中该五行的旺衰多寡来定","以干所坐之支来定，不看整个命局该字强弱","以天干是否透出两个以上来定虚实"],"ans":2,"exp":"干支虚实以干所坐之支来定，不看整个命局该字强弱；如甲寅见申，仍属活木怕埋根之铁。","sec":"4. 两条答疑","t":"rule"},{"q":"乾造甲寅、丁卯、庚戌、丁亥，行庚午运至癸未年死亡，癸未年如何构成应期？","opts":["卯未半合木局生丁火，与日柱天地相合","未土燥克亥水，直接灭绝庚金食神之寿","癸水伤官泄庚金，未土刑戌土开火库","未为丁之半禄，癸冲丁使丁动而克庚"],"ans":3,"exp":"庚午运是庚出现为应期；癸未年未为丁火半禄（干应支），癸冲丁，丁动而克制庚金。","sec":"二、命例：出现为应期、引动为应期","t":"calc"},{"q":"乾造乙巳、己卯、戊辰、甲寅，乙亥运发财，为何不断己卯年破财而断壬午、甲申年破财？","opts":["乙当运克己故己卯不为害；午代表己、申合冲动财","己卯年辰卯穿开财库得财，壬午年午未合绊破财","己卯年卯木帮身得财，壬午年午火印星夺食破财","乙亥运己土彻底入墓，唯有壬水透干才引动劫财"],"ans":0,"exp":"乙亥运乙当运克制己土，故己卯年己不为害；壬午年午到代表己到且寅泄午，甲申年甲被己合且寅申冲破财。","sec":"二、命例：出现为应期、引动为应期","t":"calc"},{"q":"乾造甲辰、乙亥、癸未、丙辰，己卯运丙子年遇害，断其为外伤而非水淹的依据何在？","opts":["原局未土燥制亥水太过，缺水反主干燥火金之伤","卯应乙反被辰穿，穿死多应车祸等外伤而非水淹","子卯相破只主刀兵金铁之伤，水旺反主平安","丙火太阳透干照暖水局，水患已除故不断水淹"],"ans":1,"exp":"丙子年禄神出现、子卯破禄；卯应乙反被辰穿，穿死不是水淹，多应车祸，遇枪击则与职业有关。","sec":"二、命例：出现为应期、引动为应期","t":"xiang"},{"q":"原局地支卯辰子辰，以辰穿卯做功，为何行至甲申年反而犯牢灾？","opts":["甲木透干坐申绝地，日主身弱无力承担重财","申子半合水局太旺，水多木漂而使卯木失根","申子辰三合局与卯暗合，破坏了卯辰穿的组合","申金冲克卯木财星，导致财星彻底坏绝无救"],"ans":2,"exp":"原局辰穿卯是做功，甲申年申子辰三合局与卯暗合，破坏了卯辰穿的做功组合，成反局而犯牢灾。","sec":"二、命例：出现为应期、引动为应期","t":"calc"},{"q":"乾造乙巳、己丑、壬辰、辛丑，戌运发巨财，为何刚入乙酉运的乙运即坐牢？","opts":["乙木泄尽壬水日主元气，导致身弱不能任四亿巨财","乙木伤官透干克制己土正官，构成伤官见官之祸","乙巳伏吟引动年柱，驿马逢冲主远走他乡逃亡","乙既代表年乙又代表辰，乙透有克无生破坏功神辰"],"ans":3,"exp":"辰是要害功神；乙不仅代表年上乙，也代表辰，乙透干有克无生等于破坏了辰；酉运化阳为阴更凶。","sec":"三、干支应期的命例","t":"calc"},{"q":"乾造乙卯、戊子、乙未、己卯，乙酉运酉杀冲禄本不吉，为何辛巳年反主升官？","opts":["辛虚透坐巳火被制，杀制为吉，且巳等于戊土到","辛金偏官透干助旺酉金，官杀混杂反主威权大增","巳火伤官合住酉金七杀，化杀生财而主掌权","巳卯暗合引动禄神，禄神得火暖局而自然贵显"],"ans":0,"exp":"酉金杀冲禄本不吉，但辛巳年辛金虚透坐巳火被制，「杀制为吉」，且巳火等于戊土到了，原局戊作功。","sec":"四、综合应用的命例","t":"calc"},{"q":"乾造乙卯、癸未、辛未、辛卯，庚辰运之庚运一事无成，到辰运为何事业稳定？","opts":["庚运劫财无制破财；辰运土生金旺得印星护身","庚运乙庚合走财；辰运未入辰墓、卯辰穿有落脚处","庚运冲克乙木食神；辰运冲开未库放出大量财富","庚运天干克木太重；辰运合住卯木财星使财不跑"],"ans":1,"exp":"庚运是劫财运，别人合走了财（乙庚合）；辰运未入辰墓、卯辰穿，自己有了落脚之处而事业稳定。","sec":"四、综合应用的命例","t":"calc"},{"q":"乾造丁酉、甲辰、戊辰、甲寅，己运合绊甲木破财五年，为何不至于彻底破产？","opts":["丁火印星透干化杀生身，保住了戊土主位根基","酉金伤官暗合辰土，把破财之气转化为投资收益","原局有两甲木，己土只能合走一个，尚留一个","辰土水库深厚，暗中不断生发甲木使财源不绝"],"ans":2,"exp":"己运合绊甲木不利，寅申冲坏所用，破财严重；但因原局有两甲，己只能合一个，故不至于破产。","sec":"四、综合应用的命例","t":"calc"},{"q":"乾造壬寅、戊申、甲申、辛未，壬子运甲申年亥月病故，体现了什么木象规律？","opts":["木旺必须金克，亥月生木过旺导致无金可制而亡","死木喜火焚化，行水运润下反使木气腐朽致死","活木不怕埋根铁，但怕壬子水多漂浮而无土培","断根之木怕见生，甲申绝地冲禄又逢亥月水生反亡"],"ans":3,"exp":"两申冲破寅禄成断根之木，子运流动之水腐败寅木，甲申年亥月病故，正应「断根之木怕见生」。","sec":"四、综合应用的命例","t":"calc"},{"q":"己未、癸酉、丁巳、丁未（行辰运）与戊子、辛酉、壬戌、壬子（丙辰年），同为辰酉合而酉弱，为何吉凶截然相反？","opts":["前造火燥势，辰合护酉为反局；后造金水势，辰助水助死","前造辰酉合化金为忌；后造辰酉合化水为喜神","前造酉为财星不可合；后造酉为印星喜合而护之","前造辰为官杀库反克酉；后造辰为水库生扶酉金"],"ans":0,"exp":"两造酉都弱，区别在气势：前造火燥气势去财，辰合绊酉反而保护酉，是反局；后造金水气势，辰助水是酉之死地，助死去母。","sec":"五、合墓与气势","t":"diff"},{"q":"乾造乙未、乙酉、丙戌、己丑，原局酉被戌穿倒主早丧父，为何不应庚戌年而应癸丑年？","opts":["戌土为火库能生丙火，丑土为湿土晦火而克父星","酉入墓于丑，庚戌年刑开丑库不应，癸丑年库到为应","庚戌年庚金帮扶酉金父星，癸丑年癸水泄尽酉金","庚戌年乙庚合护住父星，癸丑年丑未冲动祖上宫"],"ans":1,"exp":"酉金财看父，原局酉入墓于丑，庚戌年正好刑开丑库所以不应；到癸丑年墓库到位，才是死父应期。","sec":"1. 入墓的两种","t":"calc"},{"q":"占事盘甲申、辛未、丁酉、庚戌问丢失小鸟，断其「出不了门且在家中西北角金属物上」的依据是？","opts":["庚金为西北金属，辛金合住丁火使小鸟无法飞出","戌土为火库生金，未戌相刑把门户锁死而无出口","丁坐酉金入戌门户库（西北），酉戌相害不能开墓","丁火坐酉为长生之地，申金驿马被未土合住不动"],"ans":2,"exp":"丁为小鸟坐酉（金属），入戌库（门户、西北），酉戌相害，害不能开墓，故出不了门，在家中西北角热水器上找到。","sec":"2. 占事盘：丢失小鸟","t":"xiang"},{"q":"乾造壬寅、己酉、乙卯、戊寅，原局酉金制不好不能当官，为何仍能大富？","opts":["戊土财星透出时干，财星虚透即主日进斗金之象","寅卯木旺成林，木多克土自然能聚戊己之大财","壬水正印透干化杀生身，印旺转而暗生卯木禄神","酉看似七杀实是财（戴财帽），运制或泄之即大富"],"ans":3,"exp":"酉金看似杀，实是财（头上戴着财帽）；原局制不好不能做官，行运制官杀或泄官杀生禄皆以发财论。","sec":"3. 大富命作功","t":"calc"},{"q":"关于盲派「禄」的喜忌口诀，下列哪一项概括最为准确？","opts":["禄喜静，不喜财，不喜冲、刑，不喜重见，不喜官杀","禄喜动，喜财星，喜刑冲开禄，喜官杀卫禄","禄喜静，喜见官杀制身，最喜重见以壮大日主","禄喜印生，最喜财星破印护禄，不喜食伤泄气"],"ans":0,"exp":"禄的喜忌口诀：禄喜静，不喜财，不喜冲、刑，不喜重见，不喜官杀。","sec":"5. 禄的几条","t":"rule"},{"q":"盲派中所谓「干禄」（干禄与支禄区别不大），只有哪两个时柱？","opts":["戊戌时、己丑时","丁未时、癸丑时","丙午时、壬子时","甲寅时、庚申时"],"ans":1,"exp":"日禄归时成禄格者条件严格；干禄只有丁未时（未为丁半禄）、癸丑时（丑为癸余气）两柱。","sec":"5. 禄的几条","t":"calc"},{"q":"盲派地支作用中，「夹刑」与「夹冲」在性质上是否相同？","opts":["完全相同，夹刑与夹冲都是二对一将中间之支坏掉","夹刑只论六亲不吉，夹冲只论破财而不伤六亲","不同，夹刑相当于挤压，刑的角度不同，不与冲同论","夹刑力量大于夹冲，夹刑必死而夹冲只主迁移"],"ans":2,"exp":"一方二、一方一，若夹在两边则是夹冲；夹刑相当于挤压，但刑的角度不同，不与冲同论。","sec":"6. 夹冲、夹刑","t":"diff"},{"q":"判断八字是否「作功」，除了「制」之外，还有哪些方式也算作功？","opts":["只有合制算作功，入墓与化掉皆属无功之象","必须日主亲自合克才算，地支入墓一概不算","只有冲、克、穿三种方式才算真正作功","入墓或化掉也算，主要看对财官的作用"],"ans":3,"exp":"不一定要制才作功，入墓或化掉也算；看是否作功主要看对财官（用）的作用，对伤官的作用可看一半。","sec":"7. 官杀库作功：不一定要制","t":"rule"}]},{"n":155,"level":"专题","title":"伤官、六亲与命格组合专题","qs":[{"q":"金水伤官的喜忌，按盲派口诀是哪一条？","opts":["喜见财官，怕见印","喜见印，怕见官，喜见杀","喜见印，怕见官","喜见官，怕见印"],"ans":3,"exp":"金水伤官喜官怕印；喜印怕官是土金伤官，喜财官怕印是水木伤官，别串口诀。","sec":"一、伤官诀","t":"rule"},{"q":"「金水伤官喜见官」这条口诀，用在原局和大运上有什么区别？","opts":["只适用原局，大运见官反而不好","原局大运都适用，见官皆吉","只适用大运，原局不论","原局忌官，大运喜官"],"ans":0,"exp":"金水伤官喜官只对原局成立；大运见官星（如午运）会出事，不能照搬。","sec":"一、伤官诀","t":"diff"},{"q":"土金伤官「怕见官」，原局与大运的口径是什么？","opts":["原局不忌，大运忌见官","原局忌见官，大运不忌","原局、大运都不忌见官","原局、大运都忌见官"],"ans":1,"exp":"土金伤官怕官是原局的忌，大运见官不忌（如癸卯运升总督）。","sec":"一、伤官诀","t":"diff"},{"q":"土金伤官原局里既有伤官、又有官星，但两者不相见（不在一起相碰），怎么论？","opts":["照样坏格，按伤官见官论","格局降一档，只能守财","不坏格，按伤官合官杀论","只看官星，伤官不论"],"ans":2,"exp":"伤官与官不「相见」就不坏格；相见才是伤官见官坏格。","sec":"一、伤官诀","t":"rule"},{"q":"土金伤官见官，官星以卯酉相见与以寅申相见，结论有何不同？","opts":["卯酉与寅申都只能做普通人","卯酉见者格可大，寅申见者格小","两者都不坏格，格局一样大","卯酉见者格小，寅申见者格可大但坏格"],"ans":3,"exp":"口诀总结：卯酉相见格小；寅申相见格可大，但仍是坏格。","sec":"一、伤官诀","t":"diff"},{"q":"水木伤官与土金伤官，对「官」的态度分别是？","opts":["水木伤官见官为吉，土金伤官怕见官","水木伤官怕见官，土金伤官喜见官","两者都怕见官","两者都喜见官"],"ans":0,"exp":"水木伤官喜见财官；土金伤官喜印怕官。两类对官的态度相反。","sec":"一、伤官诀","t":"diff"},{"q":"火土伤官里，哪种日主与伤官的组合较好？","opts":["丙火见己土","丁火见戊土，伤官佩制","丁火见己土","丙火见戊土"],"ans":1,"exp":"火土伤官看组合：丁见戊较好（制水有功），丙见己反而容易坏格。","sec":"一、伤官诀","t":"rule"},{"q":"丁火日主，按盲派「父星」标准（不论男女），下列哪个字可以当父星？","opts":["丁（比肩、禄）","甲（印）","辛（偏财）","己（食神）"],"ans":2,"exp":"财官杀为父：丁日财为庚辛、官杀为壬癸，辛是财；己食神、丁比劫属母星一路，甲是印不当父。","sec":"二、六亲","t":"calc"},{"q":"命中找到父母星，有父母相克的信息，却看不出任何一方死亡，按盲派口诀怎么断？","opts":["母亲早亡","父亲早亡","父母同住但不和","一定是父母离异"],"ans":3,"exp":"口诀：看到父母相克信息而看不出一方死亡，那一定是离异。","sec":"二、六亲","t":"rule"},{"q":"「父星双合、伏吟」与「母星双合」，各应什么？","opts":["父别娶；母改嫁","父改嫁；母别娶","父早亡；母早亡","父母都主离异但各自不再婚"],"ans":0,"exp":"口诀：父星双合、伏吟，父别娶；母星双合，母改嫁。","sec":"二、六亲","t":"diff"},{"q":"按盲派过河拆桥命格的基本原理，发大财的关键是什么？","opts":["主位官杀重，让财星透出","主位财重生宾位官杀，把官杀弄住","主位财轻，靠大运补财","宾位财重生主位官杀，把财弄住"],"ans":1,"exp":"主位财重生宾位官杀，官杀聚集财的能量，制住、合住或穿住官杀就发大财。","sec":"三、过河拆桥命格","t":"rule"},{"q":"过河拆桥命格里，「弄住」宾位官杀的功，原局与大运有何差别？","opts":["原局和大运功力一样大","只有大运弄住才算数","原局弄住功大，大运弄住功小","原局弄住功小，大运弄住功大"],"ans":2,"exp":"原局弄住的功大，大运弄住的功小。","sec":"三、过河拆桥命格","t":"diff"}],"fine":[{"q":"五类伤官的通用判断步骤，第一步与最后一步分别是？","opts":["先看身强身弱，最后看大运是否透出财星","先定格局高低，最后看原局有无印星泄秀","先看月令是否为伤官，最后看日支是否受刑","先定日主加伤官五行类别，最后看官与伤官是否相见"],"ans":3,"exp":"通用判断步骤：先定哪类伤官（日主＋伤官五行），再查喜忌口诀、分原局大运，最后看官伤是否相见。","sec":"一、伤官诀","t":"step"},{"q":"乾造庚子、庚辰、庚辰、戊寅（金水伤官），为何行官星午运反而差点丧命？","opts":["子水伤官与日主连体不敢坏，午运冲子，喜官只适用原局","因为庚金身弱无根，午火克身导致日主元气尽泄而亡","因为戊土偏印透干，午火生助戊土构成枭神夺食之祸","因为原局辰土太重，午火官星入墓于戌而无力制金"],"ans":0,"exp":"金水伤官喜见官只适用于原局，不适用于大运；此造子水伤官与日主连体不敢坏，午运冲子水故险丧命。","sec":"1. 金水伤官喜见官","t":"calc"},{"q":"乾造辛亥、辛丑、戊申、戊午，属土金伤官且时上见午印，为何仍做不了官只能取财？","opts":["因为丑土为湿土，直接把午火印星彻底熄灭","年上见财星（亥水），坏了印格","因为辛金伤官两透天干，泄尽戊土元气而无力","因为申金食神与午火相隔太远，无法发挥作用"],"ans":1,"exp":"土金伤官时上见印为吉，但不喜年上见财，财坏了印格，故做不了官，只能取财。","sec":"2. 土金伤官喜见印、怕见官","t":"calc"},{"q":"乾造戊申、甲寅、己未、辛未，既怕伤官见官又需寅申冲开库，应如何定吉凶？","opts":["寅申冲直接破了甲木正官之根，主一生贫寒无业","伤官见官坏格为重，主本人必有牢狱与官司之灾","主位开库为急，伤官见官在宾位不主本人，反克领导","未库被寅申遥冲无法打开，反主财官积压无用"],"ans":2,"exp":"主位开库为急，伤官见官在宾位，不主本人的事；庚运伤官见官克领导，自己反无事。","sec":"2. 土金伤官喜见印、怕见官","t":"calc"},{"q":"乾造辛卯、庚寅、己丑、癸酉，乙酉运发迹而甲申运却遭牢狱，原因在于甲申运的什么特征？","opts":["甲申运庚甲相克太过，导致印星受损无力护身","甲申运与日柱构成天地双冲，冲破了坐下丑库","甲申运申金冲克寅木正官，属于比劫夺财破格","甲申运构成伤官见官且天地全见，坏格致牢狱"],"ans":3,"exp":"土金伤官见官怕坏格：乙酉运伤官合杀、食神制杀而发迹；甲申运伤官见官天地全见，故有牢狱。","sec":"2. 土金伤官喜见印、怕见官","t":"calc"},{"q":"甲午、癸酉、癸未、癸酉（地委书记）与甲午、癸酉、癸未、癸亥（搞风水）同为水木伤官，为何层次悬殊？","opts":["后造坐支未杀被亥合走而无气，前造未杀合财气专","后造甲木伤官泄气太过，前造未土燥土克水太重","后造水太旺成木漂之势，前造金水相涵清纯贵气","后造时支亥水为羊刃夺财，前造时支酉金生水有情"],"ans":0,"exp":"水木伤官喜见财官：前造坐支未杀合财星，局象好而大贵；后造坐支未杀被时支亥合，杀星无气而降格。","sec":"3. 水木伤官喜见财官","t":"diff"},{"q":"坤造癸巳、甲子、癸卯、癸亥，大运辰运闲置五年而巳运利财，各是什么作用？","opts":["辰运合走子水禄神破财；巳运生助甲木伤官泄秀","辰运穿倒主位内食神卯；巳运远方财星冲到自己","辰运墓住癸水日主无气；巳运合住亥水羊刃护财","辰运构成官杀混杂压身；巳运化火为土生助官星"],"ans":1,"exp":"主位内食神卯木生年上巳火财官；辰运卯辰穿倒内食神而闲五年，巳运远方财星冲到自己故利财。","sec":"3. 水木伤官喜见财官","t":"calc"},{"q":"乾造乙未、丁亥、甲午、丙子（木火伤官），原局无官星反而当到县级市市长、局长，原因何在？","opts":["因为日支午火与时支子水相冲，冲出官星暗中掌权","因为年支未土暗藏乙木羊刃，羊刃驾杀反主掌大权","木火伤官不喜见官，无官则印当权力，亥子印制伤官","因为天干丙丁火食伤双透，食伤生财自然富贵双全"],"ans":2,"exp":"木火伤官喜见印、不喜见官，无官则有权，印当权力；局中亥子两印能制伤官，故权大。","sec":"4. 木火伤官喜见印","t":"calc"},{"q":"乾造己酉、甲戌、甲戌、丁卯，木火伤官不见印而有财，口诀如何断？象上应何职业？","opts":["伤官见官主口舌是非，应律师或法庭辩护人员","伤官生财主大富贵，应房地产或金融投资老板","木火通明主文章科甲，应大学教授或文化学者","无财无印守孤贫（有财无印也无福），应摇滚歌手"],"ans":3,"exp":"口诀「女命伤官福不真，无财无印守孤贫」，有财无印也无福；戌为夜总会、火克金为声音，是摇滚歌手。","sec":"4. 木火伤官喜见印","t":"xiang"},{"q":"乾造辛亥、壬辰、丁丑、戊申，其中戊土伤官在命局中代表什么？","opts":["戊等于丙火另一状态，主技能、头脑，在功制壬水","戊土为劫财替身，主一生钱财易被朋友兄弟分夺","戊土为官杀库之盖头，主中年必有官非或降职之忧","戊土为燥土晦火之神，主性格固执且妨碍事业发展"],"ans":0,"exp":"火土伤官丁见戊好：戊土等于丙火的另一状态，伤官主技能、头脑，伤官在功制壬水（画家、大学任教）。","sec":"5. 火土伤官看组合","t":"xiang"},{"q":"原局无财官时，盲派如何寻找「父星」？","opts":["以年柱纳音五行为父星","原局无财官时不看原局，以大运看","一律以日主之禄神为父星","以原局食神、伤官兼看父星"],"ans":1,"exp":"父星：不论男女，以正偏财、官杀为父；原局无财官时不看原局，以大运看。","sec":"1. 父星母星","t":"rule"},{"q":"按盲派六亲取星法，如何寻找「母星」？","opts":["男命以正印为母、女命以偏印为母；没有则看禄神","不论男女，一律以正印、偏印为母；没有则看财星","不论男女，以禄、食神、伤官为母；没有则看比劫","以月支所藏人元为母；没有则以年干合神看母"],"ans":2,"exp":"母星：不论男女，以禄、食神、伤官为母；没有则以比肩劫财看母。","sec":"1. 父星母星","t":"rule"},{"q":"看父母吉凶时，宫位与星位的主次关系及先后顺序是？","opts":["以星为主、宫为辅；先看父星母星旺衰，再看年月宫","以日时为主、年月为辅；先看日支是否刑冲父母星","宫星完全平等；只需看星是否入墓，不必管年月宫位","以宫为位、星为辅；先看年月宫位，再看星宫关系"],"ans":3,"exp":"年月是父母宫，以宫为位、星为辅；看父母要先看年月宫位是否被坏，再看星与宫的关系。","sec":"1. 父星母星","t":"step"},{"q":"克父母的常见组合中，所谓「患」指的是什么现象？","opts":["父母星多现而且杂现，易克父母","父母星自坐长生之地，反主子女自身多病多灾","父母星完全不现于原局，导致与父母缘分浅薄","父母宫逢空亡，主父母一生奔波劳碌而无固定居所"],"ans":0,"exp":"克父母组合第一条：父母星多现而且杂现，称为「患」，易克父母（如天干丁卯与丙午两父相破）。","sec":"2. 克父母的组合","t":"rule"},{"q":"乾造庚戌、戊寅、甲子、丙寅，原局戌土空亡，应父亲早死于庚辰运癸酉年的象理是？","opts":["丙火食神在酉年临死地，辰酉合化金克坏寅木禄神","财临库地父当早死，戌空为冷墓，辰运冲开、酉年引辰","庚金父星在辰运入墓，癸酉年酉金刃星劈甲木致死","戌土空亡代表父亲无寿，庚辰运庚金克甲木日主应凶"],"ans":1,"exp":"财临库地父当早死：原局戌土空亡代表冷备好的墓，到庚辰运墓到、冲戌土开墓，酉年引支辰为应期。","sec":"2. 克父母的组合","t":"calc"},{"q":"坤造甲寅、丁卯、戊辰、戊午，同样财临墓库，父死却不会太早（甲子运癸未年才死）的原因是？","opts":["因为丁火印星透干生扶戊土，保住了年上甲木七杀","因为卯辰相穿提前破坏了财库，父星反而不入墓","辰土财库坐于日支，且甲子运甲是子的病死之地","因为寅卯木旺成势，木多克土反而生助父星之寿"],"ans":2,"exp":"财临墓库年月无根，因坐于日支不会太早；甲子运父到当死，甲是子的病死之地，癸未年父到应期。","sec":"2. 克父母的组合","t":"calc"},{"q":"坤造壬戌、戊申、戊寅、癸丑，父母离异随母改嫁，原局中谁是亲父、亲母与继父？","opts":["寅木为亲父，壬水偏财为亲母，戊土为继父","戊戌为亲父，癸丑为亲母，寅木七杀为继父","癸水为亲父，申金食神为亲母，壬戌为继父","壬申为亲父，戊比肩为母（双现合癸），癸为继父"],"ans":3,"exp":"壬为父、申是壬长生当父；戊比肩当母，戊双现合癸，癸为继父；寅申冲离父，随母改嫁。","sec":"3. 父母离异的组合","t":"calc"},{"q":"父母弃养（过继、送人）的年月条件，除了「年月食神被坏、入墓」外，还有哪两类年月星被坏？","opts":["年月财星被坏（家贫），或年月印星被坏（失庇护）","年月官杀被坏（无管束），或年月比劫被坏（无手足）","年月羊刃被坏（无刚气），或年月驿马被坏（难出门）","年月禄神被坏（无俸禄），或年月孤辰寡宿临门"],"ans":0,"exp":"父母弃养三大年月条件：年月食神被坏入墓；年月财星被坏（家境太差）；年月印星被坏（失去庇护），且日时另有生机。","sec":"4. 父母弃养（过继、送人）","t":"rule"},{"q":"乾造壬午、辛亥、庚辰、丁亥，月令与时上食神皆入墓，为何能「过继给叔叔」？","opts":["辛金劫财透干生水，代表叔叔暗中资助食神出墓","丁壬合，将远方（年上）食神合到主位","亥水食神在年支午火暗合，说明父母主动送归宗族","辰土印库冲开午火官星，代表叔叔以权力收养自己"],"ans":1,"exp":"月令食神入墓、时上食神也入墓，但有丁壬合，远方食神合到主位，故过继给叔叔。","sec":"4. 父母弃养（过继、送人）","t":"calc"},{"q":"过河拆桥命格中，若属「升官型」（宾位官杀关联到主位），大运宜如何处理宾位官杀？","opts":["大运宜生旺宾位的官杀，官杀越旺则官职越高","大运宜将宾位官杀泄给食伤，化官为财方能掌权","大运宜将宾位的官杀制住，则可升官","大运宜把主位印星合走，让官杀直接克入日主"],"ans":2,"exp":"宾位官杀关联到主位，表示自己得到了宾位的权力；这时大运宜将宾位的官杀制住，则可升官。","sec":"1. 基本原理","t":"rule"},{"q":"乾造庚戌、己卯、戊子、癸亥，属过河拆桥发财型，为何在「巳运」开始发财数千万？","opts":["巳为戊土禄神，禄神到位直接合住卯木官星生财","巳丑拱金生旺亥子水，使主位财星源源不断","巳火印星化卯木官星生身，使日主有力量担财","巳能应戌，且巳亥冲去多余的财星"],"ans":3,"exp":"原局以卯戌合弄住统财的官星卯，用戌；应巳运者，巳能应戌，且冲去多余的财星（亥）。","sec":"2. 发财型","t":"calc"},{"q":"癸卯、壬戌、壬寅、乙巳与庚戌、己卯、戊子、癸亥同为过河拆桥发财，为何前者企业规模更大？","opts":["前者卯合戌还制戌，后者戌绊卯不制","前者水木伤官喜见官，后者土金伤官怕见官","前者行火运生助戌土，后者行金运泄尽戌土","前者主位巳火财星比后者子水财星更旺更聚"],"ans":0,"exp":"前者主位巳入戌墓，卯合戌还能制戌；后者戌绊卯不制。制之功大于单纯绊住，故规模更大。","sec":"2. 发财型","t":"diff"},{"q":"乾造癸卯、壬戌、癸巳、庚申，同是主位财生宾位官且被卯合住，为何不构成过河拆桥大富格？","opts":["因为时支申金合住日支巳火，把财星彻底合死无用","原局主位财轻，不符合过河拆桥先决条件","因为月支戌土太燥，直接把卯木食神泄气殆尽","因为年干癸水劫财透干，把主位之财全部夺走"],"ans":1,"exp":"过河拆桥需「主位财重」生宾位官杀；此造原局主位财轻，不符合条件，反喜门户印合财做小生意。","sec":"4. 反例","t":"calc"}]},{"n":156,"level":"专题","title":"象法与象的应用专题","qs":[{"q":"按盲派「体、用、象」框架，十个天干、十二个地支属于哪一项？","opts":["体","局","象","用"],"ans":0,"exp":"干支本身是体；五行生克、干支关系、十神宫位是用；体与用结合形成的具体判断是象。","sec":"一、体、用、象","t":"rule"},{"q":"下列哪一项属于「用」而不是「体」或「象」？","opts":["十个天干","十神与宫位","十二个地支","体与用结合后的具体结论"],"ans":1,"exp":"用指五行生克、干支关系、十神与宫位；干支是体，最后的结论才是象。","sec":"一、体、用、象","t":"diff"},{"q":"天干相合为反象：甲己合，谁喜谁不喜？","opts":["甲喜己合，己不喜甲合","两者都不喜","己喜甲合，甲不喜己合","两者都喜"],"ans":2,"exp":"尊卑之合，卑者被尊者所合则喜，尊者被卑者反合则不喜。","sec":"3. 天干合为反象","t":"rule"},{"q":"按干合反象，丁壬（大小之合）这一合里，谁喜谁不喜？","opts":["丁壬都喜","丁壬都不喜","壬喜丁合，丁不喜壬合","丁喜壬合，壬不喜丁合"],"ans":3,"exp":"口诀：丁壬大小之合，丁喜壬合，壬不喜丁合，被合者小者喜。","sec":"3. 天干合为反象","t":"calc"},{"q":"原局有两丙、两寅，没有别的眼睛象。看眼睛，按盲派对称性取象，可以怎么看？","opts":["对称的火可象眼睛","对称的水可象眼睛","对称的木可象眼睛","对称的金可象眼睛"],"ans":0,"exp":"凡对称性的火（两丙、两丁、两午、两戌、两巳、两寅）都可以象眼睛。","sec":"3. 命例","t":"calc"},{"q":"盲派说「亥为计算」，要取会计、出纳之象，亥要满足什么条件？","opts":["亥与官星相关，如合官、被官克","亥与财星相关，如合财、被财墓、本身是财","亥与比劫相关，如合比劫、临禄","亥与印星相关，如合印、生印"],"ans":1,"exp":"亥水与财星相关（合财、被财墓、本身是财、冲制财星等），多为会计出纳。","sec":"2. 各支取象（要点）","t":"rule"},{"q":"同样食神，卯木为食神与辛金为食神，各自喜食什么？","opts":["卯木食神喜食肉，辛金食神喜食面","卯木食神喜食米，辛金食神喜食面","卯木食神喜食面，辛金食神喜食米","卯木食神喜食面，辛金食神喜食肉"],"ans":2,"exp":"卯细长如面，故卯木食神喜食面；辛金食神喜食米。","sec":"2. 各支取象（要点）","t":"diff"},{"q":"盲派地支取象中，「辰」的关键象是什么？","opts":["律令","公门","思想","车"],"ans":3,"exp":"辰为车；寅为公门，巳为思想，申为律令、收敛。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"地支「寅」与「申」的关键象，下列哪组对？","opts":["寅为公门，申为律令、收敛","寅为思想，申为武库","寅为车，申为计算","寅为律令，申为公门"],"ans":0,"exp":"寅为公门（政府机关、组织），申为律令、收敛（司法、金融）。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"取象的几种方式里，「干支得墓库，有集团性、聚集性」属于哪一种？","opts":["换象","墓象","共象","带象"],"ans":1,"exp":"墓象指得墓库而有聚集性；共象是本象加十神象，换象是制与被制互换，带象是干支相生。","sec":"1. 取象的几种方式","t":"step"},{"q":"换象与带象的区别是哪项？","opts":["换象是本象加十神象；带象是相合而成","换象是得墓库聚集；带象是组合成局","换象是制过后互换；带象是干带支象","换象是干支相生；带象是制过后互换"],"ans":2,"exp":"换象：地支冲制、合制，被制方与制方可换象使用；带象：干支相生，干能带支象，支能带干歇脚。","sec":"1. 取象的几种方式","t":"diff"},{"q":"盲派「借象」的两种关系是什么？","opts":["天干通墓库，或同五行阴阳相同的字","天干通长生，或同阴阳五行不同的字","天干通合神，或相冲的两个字","天干通禄神，或同五行阴阳不同的字"],"ans":3,"exp":"借象口诀：天干通禄神、同五行但阴阳不同的字，可互借其象，如丙与巳、寅与卯。","sec":"4. 借象","t":"rule"}],"fine":[{"q":"十天干基本象口诀中，「戊」与「己」的象意分别是？","opts":["戊落日形盛，己阴影卑微折弯","戊高大直立如山，己圆润通达如水","戊太阳绚丽灿烂，己星光亮点微弱","戊变革肃杀刚猛，己尖针精细致密"],"ans":0,"exp":"十天干基本象口诀：戊落日形盛，己阴影卑微折弯。","sec":"1. 基本象","t":"xiang"},{"q":"十天干取象中，「庚」与「辛」在「形」上的区别是？","opts":["庚为方正，辛为圆润","庚为棱角，辛为致密","庚为致密，辛为棱角","庚为直立，辛为弯曲"],"ans":1,"exp":"庚主霜、顽铁、刚猛，其形为棱角；辛主珠宝、针、精细，其形为致密。","sec":"2. 各干取象","t":"xiang"},{"q":"十天干人体取象中，哪两个天干均与「眼睛（睛）」和「神经」直接对应？","opts":["庚金与辛金","戊土与己土","丙火与丁火","甲木与乙木"],"ans":2,"exp":"丙主睛眼、神经、大脑、血压、小肠；丁主睛、心脏、血管、神经（癸亦主肾脏、眼睛）。","sec":"2. 各干取象","t":"xiang"},{"q":"按天干合为反象口诀，乙庚（刚柔）、丙辛（日月）、戊癸（老少）三合中，喜被合的一方分别是？","opts":["乙喜庚合，丙喜辛合，戊喜癸合","乙喜庚合，辛喜丙合，戊喜癸合","庚喜乙合，丙喜辛合，癸喜戊合","庚喜乙合，辛喜丙合，癸喜戊合"],"ans":3,"exp":"乙庚刚柔之合庚喜乙，丙辛日月之合辛喜丙，戊癸老少之合癸喜戊；柔、小、少、月者喜被合。","sec":"3. 天干合为反象","t":"calc"},{"q":"乾造癸丑、癸亥、甲寅、丁卯，乙丑运癸酉年被劫毁容，其象理何在？","opts":["甲主头、丁主面，原局两癸冲丁，癸酉年冲克时柱","寅卯木主四肢，酉金冲卯木导致手脚骨折致残","亥水主肾脏血液，丑亥暗合导致体内中毒生疮","甲木为栋梁之材，乙木藤条缠甲导致头部受压"],"ans":0,"exp":"甲主头、丁主面，甲木生时上丁，原局两癸冲丁；乙丑运癸酉年与时柱天克地冲，被劫毁容。","sec":"4. 十干的命例","t":"xiang"},{"q":"乾造甲午、丁卯、丁卯、壬寅为大律师，其中「卯午破」「丁」「壬」的取象分别是？","opts":["卯是花草（卯午破为园艺），丁是香火，壬主航运水产","卯是条文（卯午破为破条文），丁是文字重点，壬主名誉","卯是车船（卯午破为撞车），丁是灯光，壬主贸易运输","卯是绳索（卯午破为捆绑），丁是心脏，壬主循环系统"],"ans":1,"exp":"卯是条文，卯午破为破条文（钻法律条文空子）；丁是文字、要点重点；壬是官虚主名誉。","sec":"4. 十干的命例","t":"xiang"},{"q":"乾造丁卯、癸卯、庚辰、丁丑为台球冠军，其「瞄准、球动、运动、落袋」对应的象理是？","opts":["癸为眼泪，庚为铁器，癸庚相生为瞄准，丁丑伏吟为失误","丁为灯光，辰为水池，丁辰相生为亮灯，卯丑冲为运动","丁为小点目标，癸为圆球，丁癸冲球动，卯辰穿运动，丑入辰落袋","庚为球杆，卯为台桌，庚卯暗合为击球，辰酉合为入袋"],"ans":2,"exp":"丁为目标小点（瞄准），癸为圆球，丁癸冲球动；卯辰穿为运动；丑入辰亦为球之落袋。","sec":"4. 十干的命例","t":"xiang"},{"q":"乾造甲辰、癸酉、庚辰、甲申，行子运五年脑子闷晕且犯牢狱，按十干象理如何解释？","opts":["辰土湿泥埋金，子辰半合水局导致脑溢血","甲木见酉金为伐木，脑部受金属冲克而头晕","申酉金旺克甲木，比劫夺财引发债务纠纷坐牢","庚顽铁见癸为生锈（脑子生锈），子带丙杀沉金为牢狱"],"ans":3,"exp":"庚为顽铁喜火炼，见癸水为生锈之意（脑子生锈闷晕）；子带丙杀，沉金为牢狱。","sec":"4. 十干的命例","t":"xiang"},{"q":"乾造癸巳、辛酉、己巳、戊辰（名医），为何日支旁的辰土劫财能取象为「中药」？","opts":["辰合食神（辛酉）便为中药，辛酉为针，针药并用","因为戊土透干坐辰，戊土代表一切草本植物药材","因为辰土本身在十二地支里固定专指西药与手术","因为癸水雨露滋润辰土，癸水直接化为汤药煎剂"],"ans":0,"exp":"辰本为劫财并无中药意思，但合食神便为中药；辛酉为针，见火为日落象征病人，针药并用。","sec":"4. 十干的命例","t":"xiang"},{"q":"乾造庚午、癸未、己卯、丙寅断其失明且从事玄学，象理各是什么？","opts":["午为心脏、卯为肝胆，肝火上炎冲克庚金致失明","丙为眼、癸为瞳仁，火土燥干癸水失明；癸为玄学","己为皮肤、未为脾胃，土重晦火致使丙火无光而盲","寅为头部、庚为骨骼，寅卯木旺顶撞庚金致失明"],"ans":1,"exp":"寅为头，丙为眼，癸为瞳仁，火土太燥癸水焦干故失明；又癸为玄学、伤官生癸水财故搞玄学。","sec":"4. 十干的命例","t":"xiang"},{"q":"十二地支对应人体及功能中，「阳之始，司疏泄，头、肝」与「阴之始，司清降，肠」分别是？","opts":["巳与亥","卯与酉","寅与申","子与午"],"ans":2,"exp":"寅为阳之始，司疏泄，头、肝；申为阴之始，司清降，肠。","sec":"1. 四季与人体","t":"diff"},{"q":"十二地支对应人体及功能中，四季末（辰戌丑未）统主什么？其中「丑」司什么？","opts":["四季末土主「藏」；丑为阴中阳，司脾胃、肌肉","四季末土主「长」；丑为阳之化，司心肺、血液","四季末土主「收」；丑为阳中阴，司膀胱、尿道","四季末土主「养」；丑为阴中至阴，司生殖、阴器"],"ans":3,"exp":"四季末（辰戌丑未）土主养；丑为阴中至阴，司生殖，阴器。","sec":"1. 四季与人体","t":"xiang"},{"q":"乾造壬申、辛亥、丙午、庚寅（左宗棠），性格激烈且能成将领，地支象理何在？","opts":["午为激烈；杀刃相合，且庚绝于寅（绝敌之命）","庚金为顽铁、辛金为剑戟，金旺成兵而主统兵","申为军队、亥为水泽，金水成势冲垮午火而立功","寅亥相合化木生火，食神生财提供充足军饷"],"ans":0,"exp":"午为激烈（性格激烈直来直去）；能成将领因杀刃相合、庚绝于寅（绝敌之命）。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"坤造庚申、乙酉、丙申、癸巳，何以断其男朋友多且喜欢躺在床上胡思乱想？","opts":["癸水正官坐巳绝地，主夫星无力而只能在床静养","巳为禄表身体，合禄主随便；巳为思想，申为床","庚申金旺为多夫，乙木正印合庚主性格懒惰好卧","酉金桃花临月令，丙火日主坐申主多情而多思虑"],"ans":1,"exp":"巳是禄表女人身体，合禄比较随便、男朋友多；巳为思想，申是床，巳合到申主喜欢躺床上胡思乱想。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"在盲派地支取象中，哪一地支同时具有「武库、文库、色情」三重关键象？","opts":["辰","丑","戌","未"],"ans":2,"exp":"戌为武库（枪弹军火）、文库（印库/食伤库为学校）、色情（男命比劫库象征生殖器）。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"乾造己戊丙丁／丑辰寅酉，何以取出「死人之象」并断为嗜血杀人？","opts":["丙丁火旺克死酉金，戊己土重埋葬寅木生机","辰为牢狱、丑为黑社会，丑辰相破主群殴致死","寅木为虎豹伤人，酉金为兵器砍伐寅木致流血","酉为死人病人，酉被丁伤、寅绝，丑为酉墓入辰库"],"ans":3,"exp":"酉为死人、病人；酉被丁伤、被寅绝，丑入辰墓且丑又是酉之墓，辰官杀库聚集无数死人之象。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"坤造辛酉、己亥、壬寅、辛丑，丑运乙酉年冬煤气中毒死，其象理何在？","opts":["辛酉与辛丑是密不透风的墙，寅炉被亥合烧不起来","壬水日主被己土浊水所克，丑运水土混杂窒息而亡","亥水毒药直接冲克巳火，乙木风邪入肺导致中毒","酉丑半合金局太冷，冻伤寅木四肢导致行动不能"],"ans":0,"exp":"辛酉与辛丑是密不透风的墙，寅为取暖的炉被亥合烧不起来，丑运乙酉年冬煤气中毒。","sec":"2. 各支取象（要点）","t":"xiang"},{"q":"取象方式中，从八字整体组合确定（如包局象、夹局象、孤阳孤阴象）属于哪一种？","opts":["化象","局象","带象","共象"],"ans":1,"exp":"局象：从八字整体组合确定，有包局象、夹局象、孤阳孤阴象等。","sec":"1. 取象的几种方式","t":"rule"},{"q":"常见组合象表中，「装潢」与「服装」各自对应的典型组合是？","opts":["装潢：丁卯、乙巳；服装：戌、己卯、丙生戊","装潢：亥入辰墓；服装：卯申合、见庚申辛酉","装潢：戌、己卯、丙生戊；服装：丁卯、乙巳、卯生巳","装潢：戊辰、己未；服装：己酉、甲辰、丙子"],"ans":2,"exp":"常见组合象表：装潢为戌、己卯、丙生戊；服装为丁卯、乙巳、卯生巳。","sec":"2. 常见组合象表","t":"calc"},{"q":"常见组合象表中，「地产」与「车」各自对应的典型组合是？","opts":["地产：丁卯、乙巳、卯生巳；车：戊辰、戊戌、己未","地产：庚、申、辛、酉；车：子未穿、见财星","地产：亥入辰墓、子未穿；车：戌、己卯、丙生戊","地产：戊辰、戊戌、己未、乙未等；车：己酉、甲辰、丙子等"],"ans":3,"exp":"地产组合：戊辰、戊戌、己未、乙未、卯戌合、辛丑、戊申、卯未合；车组合：己酉、甲辰、丙子、丙申、两酉。","sec":"2. 常见组合象表","t":"calc"},{"q":"坤造辛卯、辛丑、丙辰、甲午（刺绣厂车间主任），各字如何组合成「刺绣」之象？","opts":["木软为布丝线，丙午为漂亮，卯破午布破，辛金为针缝上","辛金为剪刀裁布，甲木为服装模特，午火为门市销售","辰土为厂房仓库，丑土为纺织机器，甲木为原料","丙火为色彩染料，辰丑湿土为浆洗，卯木为晾衣架"],"ans":0,"exp":"木弯曲柔软有服装、布、丝线意；午火丙火漂亮；卯破午布破开；辛金是针再缝上，辛丑是一排带针机器。","sec":"3. 命例","t":"xiang"},{"q":"乾造戊申、丙辰、乙丑、戊寅（公安机关处级干部），为何排除检察院与法院而专断公安？","opts":["因为寅木劫财在时柱，劫财代表警察而不代表法官","坐支丑土控制申金正官，丑有隐蔽之象，排除公开部门","因为申金正官在年柱，年柱主外勤执法不主庭审","因为丙火伤官透干，伤官只主武职刑侦而不主文职"],"ans":1,"exp":"申有军队、司法之象；坐支丑土控制申金正官，丑有隐蔽之象，排除检察院与法院等公开部门。","sec":"3. 命例","t":"xiang"},{"q":"乾造壬己己丁／戌酉酉卯，退学且成赛车手，按象法如何解读「退学」与「赛车」？","opts":["戌土燥土克水无润故不喜读书；酉金叠现主机械维修","己土坐酉泄气太重故厌学；壬水财星冲丁火主奔波","酉穿倒戌文库故退学；己酉为车、戌为发动机、穿主速度","丁火偏印被壬水合走故无学历；卯木为道路故成车手"],"ans":2,"exp":"酉穿倒戌，戌当文库、食神当思想，故与教育对抗而退学；己酉为车、己方向盘、戌发动机、穿主速度。","sec":"3. 命例","t":"xiang"},{"q":"坤造癸巳、甲寅、甲辰、丁卯，何以借象断出「儿子成了自己的情人」且非亲生？","opts":["甲木双透伏吟争夫，卯辰相穿导致子女宫与夫妻宫互换","辰土财库合住酉金官星，丁火伤官透干克官为情人","寅木禄神穿坏巳火食神，癸水正印合入时柱为非亲生","癸透巳庚为夫，借象丁与巳同为情人且落子女宫，卯穿己非亲生"],"ans":3,"exp":"癸是夫妻宫透干，巳中藏庚当夫；借象丁与巳同行，丁为情人，丁落子女宫是孩子；丁卯穿自己非亲生。","sec":"4. 借象","t":"xiang"}]},{"n":157,"level":"专题","title":"职业专题（一）：口才求财与会计","qs":[{"q":"按盲派，财星入库而库不开，职业上意味着什么？","opts":["钱是祖上的，靠继承家业过日子","钱是替别人管的，做会计业务打工","钱存得住，适合自己当老板做事","钱会被劫财分走，只能合伙经营"],"ans":1,"exp":"库不开则财不是自己的，只能替人管、替人干；库被冲开才可能自己赚到。","sec":"一、职业取象的总方法","t":"rule"},{"q":"用伤官、食神做功的技术类职业人，对投资的态度应是（　）。","opts":["可投资但只能合伙，不能独资干","宜投资，只要财星入库就不会破","不宜风险投资，投资劫财合财必破","宜投资，食伤生财越投越旺发"],"ans":2,"exp":"食伤做功靠技术口才吃饭，一投资引来劫财合财，必破。","sec":"一、职业取象的总方法","t":"rule"},{"q":"同样见子水、亥水，下面哪种情形才可以断会计？","opts":["子水亥水与比劫合化以后就可以断","八字里见到子水或亥水就可断会计","子水亥水只要入了墓库就可以断","数字之象、做功、单位三者俱备"],"ans":3,"exp":"见子亥不一定是会计，必须数字之象+做功+单位三者俱备。","sec":"三、会计与数字之象","t":"diff"},{"q":"按本教材，亥水、子水在八字里主什么象？","opts":["数字、计算、液体","电子、媒体、手","金属、针、牙、骨","药罐、化学、制药"],"ans":0,"exp":"亥子水主数字计算液体；午火主电子媒体手；酉金主金属针牙骨；辰为药罐化学。","sec":"一、职业取象的总方法","t":"xiang"},{"q":"按本教材，戌土主哪类象？","opts":["药罐、化学、制药一类的东西","火药刀枪学校，也主酒店娱乐场所","服务、体力、出力一类的行业","金属、针、牙、骨一类的东西"],"ans":1,"exp":"戌为火库，主火药刀枪学校；业务章里又主电器、娱乐场所、酒店。辰为药罐化学，未为服务体力。","sec":"一、职业取象的总方法","t":"xiang"},{"q":"财星虚透并带驿马，落在年或时，职业上多主什么？","opts":["财入墓库，适合专门做管账事","财在内，守着本地稳稳做生意","财在外，需出门求财，多跑动","财稳固，适合安坐办公室工作"],"ans":2,"exp":"财虚透带驿马在年时，财在外面，要出门求，多是业务、打工。","sec":"二、口才与业务求财","t":"rule"},{"q":"业务员命中「禄做功」与「用比劫制财」的职业含义，区别是（　）。","opts":["禄做功是打工，比劫制财是辛苦求财","两者都是自己当老板，只是辛苦不同","禄做功是自己当老板，比劫制财是打工","禄做功是辛苦求财，比劫制财是打工"],"ans":3,"exp":"规律小结：禄做功辛苦求财；用比劫制财是打工；财库不开不是自己的钱。","sec":"4. 规律小结","t":"diff"},{"q":"业务命中「合劫财而拿货」，按盲派取象是（　）。","opts":["从别人那里拿产品去卖","把货物卖给合伙的那个人","产品被劫财抢走，卖不出去","自己生产产品再卖给别人"],"ans":0,"exp":"合劫财是向别人拿东西，所以是拿货销售而非自己生产。","sec":"2. 行业落点","t":"rule"},{"q":"子、未两字相见，按盲派会计之象，应怎么论？","opts":["子未合，水土相合，主财库聚拢","子未穿，数字穿财做功，会计典型","子未穿，水土相克，只主脾胃毛病","子未冲，子水冲未土，主官司是非"],"ans":1,"exp":"子水为数字，未为财，穿为做功，是会计的典型组合。","sec":"2. 取象要点","t":"rule"},{"q":"会计命中，天干透甲木坐印、透食神，各表示什么？","opts":["甲木坐印是自己开业，透食神是打工","甲木坐印是办公室，透食神是打工","甲木坐印是打工，透食神是坐办公室","甲木坐印是做公职，透食神是业务"],"ans":2,"exp":"天干透甲木坐印，是打工之象；透食神，是坐办公室之象。","sec":"2. 取象要点","t":"rule"}],"fine":[{"q":"盲派判断命主职业时，正确的两步推演顺序是（　）。","opts":["先由地支字象定具体行业，再看日主强弱定高低","先由做功结构定大类，再由类象落具体行业","先看月令旺衰定用神，再看天干十神定行业","先看财官是否透干，再看大运顺逆定职业变动"],"ans":1,"exp":"职业判断分两步：先由做功结构定大类（打工、业务、技术、公职等），再由类象落到具体行业。","sec":"职业专题（一）：口才求财与会计","t":"step"},{"q":"从结构定职业大类时，哪种配置多主在单位或学校任职？","opts":["比劫重重并透出天干","财星虚透并临驿马","印星在月令为用","食伤在门户并生财"],"ans":2,"exp":"印星在月令为用，多是在单位或学校；食伤在门户生财多靠口才技术；官杀被制多主有权力。","sec":"一、职业取象的总方法","t":"rule"},{"q":"盲派职业取象中，辰土与未土各自主要代表什么象？","opts":["辰为火药、刀枪，未为数字、液体","辰为电子、媒体，未为金属、器材","辰为酒水、饮品，未为学校、娱乐","辰为药罐、化学，未为服务、体力"],"ans":3,"exp":"辰为药罐、化学；未为服务、体力；午火主电子、媒体、手；酉金主金属、针、牙、骨。","sec":"一、职业取象的总方法","t":"xiang"},{"q":"命局中见到亥水或子水，为何不能单凭一个字就断定是会计？","opts":["取象成立必须有结构配合，看是否与食神印星穿合做功","必须先看亥水或子水是否当令且为日主喜用神","必须亥子水双双透出天干并合化为木才算成立","必须日主坐下为财库且大运走北方水运才算成立"],"ans":0,"exp":"一个象成立必须有结构配合，见子水亥水要看是否与食神、印星构成穿、合做功，不能单凭一字下断。","sec":"一、职业取象的总方法","t":"rule"},{"q":"业务销售命局中，若「天干食伤高透，合了虚印而见财」，其核心特征是（　）。","opts":["权力大，靠行政审批求财","口才好，靠说服力求财","祖业厚，靠继承房产收租","手艺精，靠闭门研发求财"],"ans":1,"exp":"天干食伤高透合了虚印而见财，主口才好，靠说服力求财，是做业务、销售的典型配置之一。","sec":"1. 结构特征","t":"rule"},{"q":"伤官落在门户（年、时）时，除了主口才之外，还兼主什么象？","opts":["主孤克，说话容易得罪人而无法做销售","主固定，一辈子守在出生地不愿外出","主脸面，且包住自己时说话到哪都有说服力","主隐秘，性格内向不爱与人当面打交道"],"ans":2,"exp":"伤官在门户主口才，又主脸面；年时伤官“包住”自己，说话到哪里都有说服力。","sec":"1. 结构特征","t":"xiang"},{"q":"按口才与业务求财的结构规律，财星落在年柱上通常意味着什么？","opts":["是家里的财，适合坐守祖业或当家族企业老板","是公家的财，必在国家财政部门担任固定公职","是暗藏的财，不用出门跑动就能轻松赚到大钱","是外面的财，工作不稳或到处跑，多打工或做业务"],"ans":3,"exp":"财在年上是“外面的财”，工作不稳或到处跑的，多是打工或做业务。","sec":"1. 结构特征","t":"xiang"},{"q":"业务求财命局中，若呈现「火土伤官、丙丁戊同象」，最适合哪类行业？","opts":["美容、化妆品销售等美丽漂亮之象","水利、远洋运输等流动性液体行业","钢铁、机械五金等重工业器材销售","煤炭、地下矿产等深层挖掘类行业"],"ans":0,"exp":"火土伤官、丙丁戊同象有美丽、漂亮之象，适合美容、化妆品销售。","sec":"2. 行业落点","t":"xiang"},{"q":"在行业取象落点中，午火巳火与丙丁戊各自的典型偏向是（　）。","opts":["午火巳火主媒体影视，丙丁戊主化学药罐制药","午火巳火主电子产品，丙丁戊主媒体影视广告","午火巳火主酒店娱乐，丙丁戊主服务体力劳动","午火巳火主酒水饮品，丙丁戊主金属五金器材"],"ans":1,"exp":"午火、巳火主电子产品；丙丁戊主媒体、影视、广告；酉金主金属器材食品，金水主饮品酒水。","sec":"2. 行业落点","t":"diff"},{"q":"在行业落点中，「酉金」与「金水」组合分别偏向哪类商品销售？","opts":["酉金主美容化妆品，金水主酒店娱乐场所","酉金主软件计算，金水主服装日用百货","酉金主金属器材食品，金水主饮品酒水","酉金主饮品酒水，金水主电子产品广告"],"ans":2,"exp":"酉金主金属、器材、食品；金水主饮品、酒水；戌主电器、娱乐场所、酒店、夜总会。","sec":"2. 行业落点","t":"xiang"},{"q":"某男命满盘年月皆财、原局无比劫，日主合时上戊官而官坐午财，流年遇丙戌合财库时开公司，为何必是合伙而非独资？","opts":["流年丙戌冲破了日主禄神，必须找人分担劳力","日主合财库导致库门紧闭，只能借用他人名义","原局比劫太多，财星被群劫分夺无法独自掌控","原局无比劫，日主合官表示被管，官象同流年"],"ans":3,"exp":"原局无比劫，日主合官表示被管（合官当财看），官象戊土同流年丙戌，故必是与人合作而非独资。","sec":"3. 命例","t":"rule"},{"q":"女命八字无官星、以财当夫看时，若财坐劫财或地支比劫里全是财，婚姻上多应什么象？","opts":["找的男人多有家庭，易当第三者且男人花她钱","丈夫官运亨通且专一，能给命主带来丰厚家产","命主性格强势克夫，婚后丈夫必然早年离世","夫妻宫稳固不动，一生绝无感情波折与外遇"],"ans":0,"exp":"八字无官看财为夫，财坐劫财、周围全是财，所找男人多有家庭，易当第三者，且男人都花她的钱不助她。","sec":"3. 命例","t":"rule"},{"q":"女命命局出现「伤官制官」（如金水伤官冲克月上巳火官星）做功时，通常意味着什么？","opts":["伤官见官无药可救，只能出家或做纯体力苦力","不是自己当官，而是得财，主咨询销售或技术求财","必主官司缠身牢狱之灾，一辈子无法赚到钱财","必主自己手握重权，在公检法系统担任高官"],"ans":1,"exp":"女命伤官制官，不是当官，而是“得财”；伤官在门户主口才与技术，可断咨询、销售。","sec":"3. 命例","t":"diff"},{"q":"女命原局有子午冲且以财当夫看，大运未动时，最易在哪个流年应期成婚？","opts":["流年劫财透出再冲夫妻宫之年","流年逢比肩伏吟月令财星之年","流年财星合到夫妻宫（如壬午年）","流年食伤入墓且印星被合走之年"],"ans":2,"exp":"原局子午冲，流年逢合是应期；无官以财当夫看，财合到夫妻宫的流年应婚期。","sec":"3. 命例","t":"rule"},{"q":"业务求财与婚姻判断中，女命「比劫争夫」与「财坐劫财」各自对应的婚姻象是（　）。","opts":["两者都主夫妻白头偕老，只是婚后财务分开","两者都主丈夫早逝，命主必然一生独身守寡","比劫争夫多当第三者，财坐劫财主对象有别人","比劫争夫主对象有别人，财坐劫财多当第三者"],"ans":3,"exp":"规律小结指出：婚姻上，比劫争夫的，对象有别人；财坐劫财的女命，多当第三者。","sec":"4. 规律小结","t":"diff"},{"q":"会计命局的结构特征中，亥水子水「一穿一合」好比珠算，印星与门户食神分别代表什么？","opts":["印为单位，食神为头脑技术且在门户为办公室","印为老板，食神为客户且在门户为娱乐场所","印为资金，食神为体力且在门户为跑业务","印为数字，食神为股票且在门户为风险投资"],"ans":0,"exp":"亥子在八字里是数字之象，一穿一合有计算之意；印为单位，食神为头脑、技术，在门户为办公室。","sec":"1. 结构特征","t":"xiang"},{"q":"在会计与数字之象中，除了最典型的「子未穿」之外，还有哪些组合也可取计算之象？","opts":["午与未合、寅与亥合等组合","亥与巳冲、亥与午合等组合","寅与申冲、巳与申合等组合","卯与戌合、辰与戌冲等组合"],"ans":1,"exp":"“子未穿”是最典型的会计组合，此外亥与巳冲、亥与午合等，也可取计算之象。","sec":"2. 取象要点","t":"xiang"},{"q":"命局中出现「年上财入宾位的墓，且天干乙庚合」，这在职业上说明什么？","opts":["年上祖产丰厚归自己所有，适合继承家业当老板","乙庚合化金成官杀，必是军队或警察系统的武官","钱不是自己的而是公家的，适合做单位会计","财被外人合走，一生注定破产且无法进入单位"],"ans":2,"exp":"年上财入宾位的墓，且天干乙庚合，说明钱不是自己的，是公家的，所以是单位会计。","sec":"2. 取象要点","t":"rule"},{"q":"会计取象中「官当财看」时，如何区分「有单位」与「只是替人管财的位置」？","opts":["官重而财星生是替人管财；财星被官包局是有单位","官星入墓是有单位；官星透出天干是自己当老板","财星透干是有单位；财星入库则是自己开财务公司","财重而官星生是有单位；官星被财包局是替人管财"],"ans":3,"exp":"官当财看：财重而官星生，有单位；官星被财包局，只是“替人管财”的位置。","sec":"2. 取象要点","t":"diff"},{"q":"女命在日时或大运中，为何忌走「印、禄之运」？","opts":["印禄之运制了官杀，容易伤及夫宫","印禄之运冲克食神，导致口才变差无法做业务","印禄之运生旺财星，导致投资过度而破产","印禄之运合走比劫，导致工作失去贵人帮扶"],"ans":0,"exp":"女命日时或大运不能走印、禄之运，因为印禄之运制了官杀，伤了夫宫。","sec":"2. 取象要点","t":"rule"},{"q":"乙木日主（活木）用食神做计算类工作时，若大运走到酉运，为何容易工作不顺？","opts":["酉金生旺印星水局，导致水多木漂而去外地经商","活木怕金，酉金冲破食神且若逢丑午穿则生乱","活木喜金修剪，酉运太旺反而导致升职过快忙碌","酉金合走年上财星，导致命主辞职转行做风险投资"],"ans":1,"exp":"乙木为活木，活木见火喜食神，活木怕金；行乙酉运时，酉冲破食神，工作容易不顺。","sec":"3. 命例","t":"rule"},{"q":"某女命己丙甲辛／酉子戌未，行庚运庚甲相冲时，断其「下岗」而非「辞职」的原因是（　）。","opts":["伤官透干冲克官星，属于命主主动嫌弃领导","比劫透干合走财星，属于命主自己跳槽创业","官作用于辰印库克自己，属于被动失去单位","食神入墓于座下，属于命主身体原因主动退休"],"ans":2,"exp":"庚运庚甲相冲，官作用于辰印库，克自己，是被动受克，所以断下岗而非主动辞职。","sec":"3. 命例","t":"diff"},{"q":"女命癸水日主时坐子禄，命局出现「子未穿」且伤官坐子，除做会计外还主什么象？","opts":["禄被穿主出国定居海外，伤官坐子主父母长寿无病","禄被穿主配偶体格健壮，伤官坐子主房产越买越多","禄被穿主官位连升三级，伤官坐子主子女极富贵","禄被穿主身体做手术、破财，伤官坐子被穿主孩子体弱"],"ans":3,"exp":"子未穿既是会计之职，又因禄被穿主身体不好做过手术、破财；伤官坐子被穿，主孩子身体不好。","sec":"3. 命例","t":"xiang"},{"q":"某女命乙辛乙庚／巳巳亥辰，月令七杀坐伤官被制被冲且夫宫入墓，其婚姻特征是（　）。","opts":["夫宫入墓稳固且七杀被制冲，婚姻稳定不会二婚","夫宫入墓主配偶早逝，乙庚合则必再嫁他人","巳亥冲破印库，主夫妻长年分居两地最终离异","七杀被伤官制冲过头，必克夫且一生多婚难稳"],"ans":0,"exp":"夫宫入墓稳固，月令七杀坐伤官被制被冲（巳亥冲），且乙庚合有单位，婚姻稳定，不会二婚。","sec":"3. 命例","t":"rule"}]},{"n":158,"level":"专题","title":"职业专题（二）：医生、教师与军官","qs":[{"q":"按盲派取象，医生命局里官杀和食伤各代表什么？","opts":["官杀为药或刀，食伤为病人","官杀为医院，食伤为病人","官杀为病人，食伤为药或刀","官杀为药，印星为刀"],"ans":2,"exp":"伤官（食伤）制官杀，是医生；官杀制不了的，可以当病人看。","sec":"四、医生","t":"xiang"},{"q":"医生命局中，辛金与申金的取象有何不同？","opts":["辛、申都代表针头","辛金代表手术刀，申金代表针头","申金代表针头，辛金不代表","辛金代表针头，申金不代表"],"ans":3,"exp":"明文：辛金代表针头，申金则不代表。","sec":"四、医生","t":"xiang"},{"q":"医生命局中，制酉金、辰土、卯木分别主哪类医术？","opts":["制酉为牙科骨科，辰为药物研究，卯为中医","制酉为药物研究，辰为牙科骨科，卯为中医","制酉为中医，辰为牙科骨科，卯为药物研究","制酉为牙科骨科，辰为中医，卯为药物研究"],"ans":0,"exp":"酉主骨骼牙齿筋骨，辰为药罐汤水化学，卯为花草吃喝所以是中医。","sec":"四、医生","t":"xiang"},{"q":"时上食神坐丑，局中又有丑未相冲，是医生，按盲派最宜断哪一科？","opts":["牙科","妇产科","药物研究","骨科"],"ans":1,"exp":"食神在时上主女性、孩子，坐丑为子息宫、生殖系统，丑未冲是制丑，故为妇产科。","sec":"四、医生","t":"calc"},{"q":"用食神伤官做功的医生（或教师），在财运上有什么忌？","opts":["必须多投资，才能引动食伤","食伤是实的，才可搞风险投资","食伤是实的，不能搞风险投资","只忌官杀投资，食伤投资无碍"],"ans":2,"exp":"用食伤做功的人，食伤实则绝对不能风险投资；劫财高透坐食伤库更爱赌、十赌九输。","sec":"四、医生","t":"rule"},{"q":"医生的医术高低，按盲派主要看什么？","opts":["看官：官重坏印则医术一般","看印：印重则必然医术一般","看比劫：比劫重坏印则医术一般","看财：财重坏印则医术一般"],"ans":3,"exp":"财重坏印则医术一般；入墓的财库当食神看，医术就会提高。","sec":"四、医生","t":"rule"},{"q":"木火伤官制印，看似求官，为何教师命不论作官？","opts":["日主所求不是官，靠食伤在门户的口才吃饭","因为官星入墓，无法求官","因为伤官见官，必定是师","因为印星太旺，不需制官"],"ans":0,"exp":"官师分界：甲己合等告诉你不是当官的命，教师靠口才吃饭，不是官。","sec":"五、教师","t":"diff"},{"q":"教师命里，时上伤官坐财库，各取什么象？","opts":["伤官为校长，财库为学生","伤官为学生，财库为工作单位","伤官为单位，财库为学生","伤官为学生，财库为风险投资"],"ans":1,"exp":"时上伤官主孩子、学生，座财库，财库是工作单位；中学生是大点的孩子，小学生是小孩。","sec":"五、教师","t":"xiang"},{"q":"教师命里「官星两头合」与「卯午破」各象征什么？","opts":["两者都是学生不听话","两者都是学生听话","官星两头合为学生听话，卯午破为学生不听话","官星两头合为学生不听话，卯午破为学生听话"],"ans":2,"exp":"明文：官星两头合，听话；卯午破，学生不听话。","sec":"五、教师","t":"xiang"},{"q":"军官命里戌土取什么象？戌被刑冲打开主什么？","opts":["金库、财库；发财或破财","水库、药库；行医或买房","书库、文库；考学或升学","火药库、刀枪库；当兵或提升"],"ans":3,"exp":"带火药的字做功必是部队；戌土被刑冲打开，当兵或提升。","sec":"六、军官","t":"xiang"},{"q":"日主坐库，库「开」与「不开」分别如何论？","opts":["刑冲开则为库，不开则为墓","开与不开都是库","刑冲开则为墓，不开则为库","开与不开都是墓"],"ans":0,"exp":"日坐库一定要刑冲，刑冲开才为库，不开就成墓。","sec":"六、军官","t":"rule"},{"q":"下列哪组都是军官命里「提升」的应期规律？","opts":["官杀生印、印库被冲、财生杀、伤官合官","官杀被制、印库出现、杀库被冲、伤官合杀","官杀被制、印库被合、杀库被冲、食神制印","官杀被合、印被财生、杀库被填、食神合杀"],"ans":1,"exp":"提升应期：官杀被制、印被制、印库出现、财制印、杀库被冲、伤官合杀、食神合印。","sec":"六、军官","t":"step"}],"fine":[{"q":"医生命局除「食神伤官制官杀」外，下列哪项也是常见的医技结构配置？","opts":["比劫重重无制化，财星虚透在年柱临驿马","满盘纯水无土火，食伤入墓且印星被合走","金羊刃带库、火金组合或火土伤官刑冲财库","官杀混杂无食伤，日主坐下财库闭而不开"],"ans":2,"exp":"医生常见配置包括食伤制官杀、金羊刃带库、火金组合、食神合印、土金食伤带印、火土伤官刑冲财库。","sec":"1. 结构特征","t":"rule"},{"q":"医生取象中，「食神本为女，穿倒生男」，若时上伤官旺而逢丑未冲，多应什么象？","opts":["多主生双胞胎女孩","多主专治眼科疾病","多主终生无子息","多主生男孩"],"ans":3,"exp":"食神在时上坐丑为妇产科，食神本为女，穿倒生男，故伤官旺而丑未冲多主生男孩。","sec":"2. 取象要点","t":"calc"},{"q":"医生命局若「无印化杀，伤官制官」，在学业考证上通常应什么象？","opts":["求学不顺，常拿不到相关证书","虽无学历但必能考取最高行政职称","学业一帆风顺，年少必获博士学位","印星暗藏得力，考试逢凶化吉必过"],"ans":0,"exp":"无印化杀、伤官制官，求学不顺，常拿不到证书（如读医学院却未拿到证书）。","sec":"2. 取象要点","t":"rule"},{"q":"医生或技术类命局遇到「独阳的八字」时，最忌讳哪种情况？","opts":["独阳最喜被水局冲克，越冲越显名医风范","把独阳制掉主身体出问题，且午火独阳怕虚透","独阳最怕见印星生扶，印旺则无法行医","午火独阳最喜透出丙火，透干则生意兴隆"],"ans":1,"exp":"独阳的八字不能把阳制了，制则身体出问题；午火独阳怕虚透（如透丙则生意不行）。","sec":"2. 取象要点","t":"rule"},{"q":"命局「劫财高透坐食伤库」且用食伤做功时，在财务行为上有何典型表现？","opts":["天生精于风险对冲，投资金融市场必暴富","虽好投机但有食伤护财，小亏之后必大赚","爱赌博且十赌九输，绝对不可冒险投资","性格极度保守谨慎，绝不肯花一分钱投资"],"ans":2,"exp":"用食伤做功只要食伤实，绝对不能搞风险投资；劫财高透坐食伤库，爱赌，十赌九输；用之食伤不喜穿。","sec":"2. 取象要点","t":"rule"},{"q":"医生命局中「枭神夺食」与「官杀受制且食神被冲克」在收入上的后果分别是（　）。","opts":["两者都主名利双收，只是工作调动比较频繁","枭神夺食收入暴涨，官杀受制食神被冲克当院长","枭神夺食转做行政，官杀受制食神被冲克开诊所","枭神夺食吃不上饭，官杀受制食神被冲克收入难"],"ans":3,"exp":"医生命局中，枭神夺食主吃不上饭；官杀受制、食神被冲克，主收入难。","sec":"2. 取象要点","t":"diff"},{"q":"某男命庚己庚庚／辰丑午辰，属独阳八字且伤官库不开，断为药物研究西医的依据是（　）。","opts":["辰为药罐化学理科好，伤官库不开主研究学问","辰土主花草吃喝，适合坐堂开中药汤剂处方","丑土穿午主妇产，专攻女性生殖系统临床手术","午火主手术刀刃，专治牙科与骨骼筋骨疾病"],"ans":0,"exp":"辰为药罐、化学，理科好；伤官库不开，主研究学问，故为药物研究的西医。","sec":"3. 命例","t":"xiang"},{"q":"某女命丙壬乙丁／午辰未丑，为何可断为「拿手术刀的医生」？","opts":["酉金透干受火克制，专攻牙科与口腔修补","比劫羊刃做功，且比劫库冲制官杀库为权力","辰土药罐透干，专搞化学药物配比研究","卯木花草得水滋润，专攻传统中医把脉"],"ans":1,"exp":"比劫羊刃做功是拿手术刀的医生；木火伤官食神、比劫库冲制官杀库为权力，食神坐丑丑未冲为妇产科。","sec":"3. 命例","t":"xiang"},{"q":"某男命甲壬丁辛／申申卯亥，原局无食伤也能当医生，且丁丑运医术提高的原因是（　）。","opts":["丁丑运印星被财星彻底坏尽，反而激发出医术","丁丑运冲破官杀库，直接转行做外科手术名医","财合印以卯印为技术，丁丑运财入墓可当食神看","原局无食伤则以比劫当病人，丑运比劫透出得财"],"ans":2,"exp":"无食伤而财合印做功，卯印是技术且带亥水源为花草主中医；丁丑运财入墓可当食神看，医术提高。","sec":"3. 命例","t":"rule"},{"q":"教师命局的结构特征中，除木火通明、食伤在门户与印在月令外，还有哪种常见配置？","opts":["伤官见官无印且禄神被穿","满盘比劫争财且财库闭锁","七杀配羊刃并带戌火库","财星虚透在门户并合印"],"ans":3,"exp":"教师结构包括木火通明、食伤做功或在门户、金水伤官印库做功、印在月令为用、财星虚透在门户并合印。","sec":"1. 结构特征","t":"rule"},{"q":"教师命局取象时，如何区分所教对象是「中学生」还是「小学生」？","opts":["食伤库主大孩子为中学，食伤主小孩为小学","年柱食伤一律教小学，时柱食伤一律教大学","金水食伤一律教中学，火土食伤一律教小学","印星透干一律教中学，财星虚透一律教小学"],"ans":0,"exp":"时上伤官主孩子、学生，中学生是大点的孩子（如戌为火库、食伤库主中学），小学生是小孩。","sec":"2. 取象要点","t":"xiang"},{"q":"教师命局若木火主文，学科上「生物」如何取象？若不当老师又多是什么职业？","opts":["生物属于医科手术象，不当老师必开私人诊所","生物为理科带文科类象，不当老师也多是办公室文职","生物为纯文科类象，不当老师必进部队当带兵军官","生物为纯理科不含文象，不当老师必去跑市场业务"],"ans":1,"exp":"木火主文类，一定是文职工作；生物为理科但带文科类象（教理科带文）；不当老师也一定是办公室文职。","sec":"2. 取象要点","t":"diff"},{"q":"教师命中若有桃花，或女命教师出现「财库包局」但库不开，感情上通常如何？","opts":["桃花主必定离异三次以上；财库包局主配偶掌管兵权","桃花必化为偏财发大财；财库包局必早婚且极其专一","桃花多不做功；财库包局库不开则身边男人多但只是多","桃花主学生崇拜而升校长；财库不开主一生无人追求"],"ans":2,"exp":"老师若有桃花，也多不做功；财库包局的女命，身边男人多，库不开，也只是“多”。","sec":"2. 取象要点","t":"rule"},{"q":"男命戊戊甲己／午午子巳，属「独阴之字」且满盘食伤包局，对其寿命与婚姻有何提示？","opts":["子水越多越忌讳；婚后命主绝对掌权且克制妻子","最喜丑未冲坏子水；早婚最稳且夫妻各自自由","午火独阴不可见巳；命主一生桃花不断且不受管","不可坏子水；夫妻宫无用宜晚婚，老婆看死自己"],"ans":3,"exp":"独阴之字不可坏子水；满盘食伤包局主夫妻宫无用，宜晚婚（早婚会离），老婆要看死自己。","sec":"3. 命例","t":"rule"},{"q":"某女命己丙庚癸／未寅戌未，癸水伤官虚透不做功，为何不断销售而断老师？","opts":["未财库伏吟到时上带癸水伤官为学生，座财库为单位","癸水虚透主口才极差，只能去学校图书馆整理档案","戌未相刑打开财库，故断其辞去销售自己开办补习班","庚金日主见丙杀必然掌权，故断其为重点中学校长"],"ans":0,"exp":"癸水伤官虚透不做功故非销售；未财库伏吟到时上带癸水伤官（学生孩子）、座财库（单位），木火之象当老师。","sec":"3. 命例","t":"diff"},{"q":"某女命丁丙丙壬／巳午午辰，满盘火局地支不做功时，时柱壬辰在职业与财运上应如何看？","opts":["壬丙冲破了日主禄神，注定一生无法参加正式工作","天干水火交融主文化媒体，辰杀库不开可作食神看","地支不做功则一生贫寒，必须去部队当文职军官","辰杀库不开主必当大官，绝不可能下海做生意"],"ans":1,"exp":"地支不做功看天干，壬丙冲水火交融、丁壬合主文化媒体；辰是杀库不开可看作食神，制官杀当财看可做生意但不为官。","sec":"3. 命例","t":"rule"},{"q":"下列哪组配置组合，最典型地指向军警、军官职业？","opts":["木火通明、时上伤官坐财库、印星在月令为用","土金食伤带辰土药罐、金水伤官见卯木花草","七杀配羊刃、伤官制杀、官杀配比劫库、火金组合","食神生财带驿马、子未穿、财星虚透合虚印"],"ans":2,"exp":"军官常见配置：七杀配羊刃（或羊刃库）、伤官制杀（或杀库）、官杀配比劫（或比劫库）、火金或金水见火、带戌火库。","sec":"1. 结构特征","t":"rule"},{"q":"军官命局中，若呈现「比劫库制财制杀库」的结构，其职务特征通常是（　）。","opts":["纯后勤管账的财务文职，无兵权","部队医院的药剂师，只管制药研究","军校里的文化教员，只负责授课","掌实权的军官，专管带兵掌兵权"],"ans":3,"exp":"比劫库制财制杀库，是掌实权的军官，掌兵权（如戌制辰、丁制酉之类刀枪库制财结构）。","sec":"2. 取象与应期规律","t":"rule"},{"q":"在军官命局的流年大运推演中，通常由哪些要素被引动来应「当兵」之期？","opts":["驿马、杀库、比劫库或印星被引动","财库、食神库、桃花星或禄神被合住","夫妻宫被穿、子息宫入墓或偏财虚透","枭神夺食、比劫争财或伤官见官无印"],"ans":0,"exp":"当兵的应期：驿马、杀库、比劫库被引动，或印星被引动。","sec":"2. 取象与应期规律","t":"step"},{"q":"军官命局中，「财落门户，禄合财」与「卯辰穿」以及「甲己合」在仕途上分别对应什么象？","opts":["禄合财主一辈子死守部队，卯辰穿主立功受奖提升","前二者主转业下海或辞职求财，甲己合主提升靠送礼花钱","财落门户主升任师长，甲己合主清廉不花一分钱","甲己合主辞职下海经商，禄合财主送礼跑官失败"],"ans":1,"exp":"转业下海：财落门户，禄合财，会离开单位求财去；卯辰穿辞职。提升靠送礼的象：甲己合表示要送礼花钱。","sec":"2. 取象与应期规律","t":"diff"},{"q":"某男命丁辛己甲／未亥卯戌，走乙巳运逢巳亥冲、冲去官星的原神亥水（财），为何仕途反而更好？","opts":["亥水是伤官的忌神，冲去后立刻转为文职教师","巳亥冲破了夫妻宫，促使命主离婚后专心从商","制去官的原神财星等于过河拆桥，反利官位提升","财星被冲走后变成比劫，帮助命主转业下海发财"],"ans":2,"exp":"乙巳运巳亥冲去亥水，亥水是官的原神“财”，制财等于过河拆桥，所以仕途反而更好。","sec":"3. 命例","t":"rule"},{"q":"某男命丁壬甲戊／未子寅辰，以财制印、比劫羊刃库做功，为何走丁未大运能一路升到师级？","opts":["丁未大运伤官见官，靠辞职转业下海后反聘回部队","丁未大运印星生身太旺，靠学历文凭破格提拔","丁未大运合住比劫库，靠彻底放弃兵权转做后勤","丁未大运一路制印，财制印格局得力掌大权"],"ans":3,"exp":"此造为财制印格局、比劫羊刃库做功，丁未大运一路制印，故可到师级。","sec":"3. 命例","t":"rule"},{"q":"某男命己丙甲乙／未子寅丑，早年当兵，为何走到癸酉大运时不想在部队而想转业？","opts":["癸酉运印制不了、官杀旺，且劫财帮忙却帮不上","癸酉运财落门户、禄合财，在外经商已赚千万","癸酉运伤官库被彻底冲开，决定转行去开牙科诊所","癸酉运木火通明透干，被地方重点中学聘为教师"],"ans":0,"exp":"癸酉运印制不了，官杀旺，本人不想在部队想转业；子丑合找人办事但劫财帮不上，甲己合还需送礼花钱，心情不好。","sec":"3. 命例","t":"rule"}]},{"n":159,"level":"专题","title":"疾病专题","qs":[{"q":"按盲派看病，阴阳失衡时，失阳和阳亢的后果分别是什么？","opts":["失阴易死亡；失阳多血压高","失阳主代谢停止；阳亢主血瘀不通","失阳多血压高；阳亢易死亡","失阳易死亡；阳亢血压高"],"ans":3,"exp":"失阳者容易死亡；阳多阴少则血压高、心脏出问题。阴多阳少、灭阳才是代谢停止、水湿凝聚。","sec":"一、总纲：三条看病原则","t":"diff"},{"q":"日主左右两边都是克泄之神（如官杀或枭神夹日），按盲派主什么？","opts":["夭命大凶，依靠被运克即死期","主多病缠身，但逢印运可过关化解","主身弱多病，印运来时可解","主心脏病，应期在冲日支之年发作"],"ans":0,"exp":"凶神夹日主夭命大凶，命中唯一的依靠被大运克，就是死期。","sec":"一、总纲：三条看病原则","t":"rule"},{"q":"原局有「卯」与「午」两字，卯破午，主身体出什么问题？","opts":["血液凝滞不通，主血脂血稠","血管破裂出血，重则脑溢血","肝火伤心，主失眠心悸神乱","肝胆疏泄不力，主糖尿病症"],"ans":1,"exp":"卯为血管，午为心脏，卯破午即血管破、出血，重则脑出血、心肌梗死。","sec":"三、干支组合与病性","t":"calc"},{"q":"原局有「寅」「亥」相合，主什么病性？","opts":["火克金伤血，重则成白血病","湿土壅肺，哮喘咳嗽不止","水湿伤肝，血脂高、生痰","阳盛阴弱，血压升高心悸"],"ans":2,"exp":"寅亥合是水湿浸木，肝失疏泄，主风湿、血脂高、心脏病，水湿生痰重则精神怪病。","sec":"三、干支组合与病性","t":"calc"},{"q":"原局辰、丑两字相合化金，主哪个脏腑出毛病？","opts":["肾与膀胱，尿频尿急","肝郁气滞，头晕失眠","脾胃失调，消化不良","肺壅，哮喘、咳嗽"],"ans":3,"exp":"丑辰合金，辰丑为湿土壅住金水之肺，成肺壅、哮喘、咳嗽。","sec":"三、干支组合与病性","t":"calc"},{"q":"按盲派的身体象法，地支「酉」和「戌」分别主什么？","opts":["酉主肺耳；戌主心包心胃","酉为神经、面；戌为脾胃、体力","酉为肾、泌尿；戌为心脏、血压","酉为大肠、骨；戌为膀胱、淋巴"],"ans":0,"exp":"酉主肺、耳，戌主心包、心、胃、神经，所以酉戌穿伤肺、心、神明。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"按盲派的身体象法，子、丑、午三个地支分别主什么？","opts":["子主膀胱前列腺；丑主心包；午主血液肾","子主血肾；丑主生殖；午主心脏","子主管道关节；丑主肺；午主头面神经","子主心脏血压；丑主脾胃；午主肾泌尿"],"ans":1,"exp":"子为血液、肾、泌尿；丑为生殖器、妇科、肛门；午为心脏、阳亢、血压、神经。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"天干甲、庚、辛在身体上分别对应什么？","opts":["甲主颈、毛发；庚主肺；辛主大肠","甲主头胆；庚主小肠；辛主膀胱口","甲主头胆；庚主大肠；辛主肺齿","甲主胃鼻；庚主大肠；辛主肌肤腹"],"ans":2,"exp":"天干象：甲头胆，庚大肠，辛肺齿。乙才是颈、毛发，丙才是小肠。","sec":"二、干支象法对应身体","t":"xiang"},{"q":"按盲派，糖尿病的三种机制是什么？","opts":["金水不通、胃热消食、阴阳离决","土来浊水、阳亢血热、肝肾同源","胃热消食、肺壅湿滞、肝脾失调","土来浊水、胃热消食、肝脾失调"],"ans":3,"exp":"糖尿病三机制：水主血或尿、土主甜，土来浊水；胃热消食（消渴）；肝脾失调，多数与燥热有关。","sec":"九、糖尿病","t":"rule"},{"q":"盲派看疾病的判断步骤，正确顺序是什么？","opts":["先阴阳平衡，再找被坏字，后看运岁","先看日主旺衰，再找被坏的字，最后看用神有根无根","先看大运流年引动，再看阴阳平衡，最后找被坏的字","先找被坏的字，再看阴阳平衡，最后看运岁引动"],"ans":0,"exp":"先看阴阳是否平衡、有无阳亢灭阳凶神夹日，再查原局被坏的字对应部位，最后由大运流年引动定发病与应期。","sec":"十、判断步骤","t":"step"},{"q":"盲派看死亡应期，主要看什么年份？","opts":["印星入墓之年","唯一依靠被克绝、穿、合绊之年","大运交脱之年","日支被冲或被刑之年"],"ans":1,"exp":"死亡应期看用神（唯一的依靠）被克绝、被穿、被合绊之年。","sec":"十、判断步骤","t":"rule"}],"fine":[{"q":"阴阳失衡看病总纲中，「阴多阳少、灭阳」与「阳亢」各自对应的病理状态是（　）。","opts":["两者都主代谢亢进、脑血管破裂出血","阴多阳少灭阳主血压升高；阳亢主水湿凝聚","阴多阳少灭阳主脾胃燥热；阳亢主寒湿淋漓","阴多阳少灭阳主代谢停止、水湿凝聚；阳亢主血压高"],"ans":3,"exp":"阳亢（阳多阴少）则血压高、心脏出问题；阴多阳少、灭阳，则代谢停止、水湿凝聚。","sec":"一、总纲：三条看病原则","t":"rule"},{"q":"关注原局被穿、刑、破、冲坏的字时，除查身体部位外，还必须紧盯哪两个关键？","opts":["是否是用神所在之体，以及是否是连体日柱","是否是年柱祖先之根，以及是否带桃花驿马","是否是月令当令之神，以及是否被比劫合走","是否是天干透出之财，以及是否坐于长生之地"],"ans":0,"exp":"三条原则之三：被坏的字要看代表身体哪一部分，是不是用神所在之“体”、是否是“连体”（日柱）。","sec":"一、总纲：三条看病原则","t":"step"},{"q":"实战规则中，「地支死、墓、绝并现加枭神夹日」主什么？若枭神夺食，何运应凶？","opts":["主晚年富贵；大运再见食神生财即应凶","必短寿；枭神夺食时大运再见枭即应凶","主中风瘫痪；大运再见比劫羊刃即应凶","主长寿无忧；大运再见印星化杀即应凶"],"ans":1,"exp":"地支死、墓、绝并现加枭神夹日，必短寿；枭神夺食，运再见枭即应。","sec":"一、总纲：三条看病原则","t":"rule"},{"q":"盲派地支身体象法中，地支「卯」和「申」分别主要对应什么身体部位？","opts":["卯为生殖器、肛门；申为脾胃、饭食与体力","卯为头、肝胆；申为肺、耳与牙齿","卯为管道、血管、腰、肠、关节；申为大肠、骨、骨髓","卯为膀胱、淋巴；申为心脏、血压与神经"],"ans":2,"exp":"地支身体象：卯主管道、血管、腰、肠、关节；申主大肠、骨、骨髓；寅主头、肝胆。","sec":"1. 地支","t":"xiang"},{"q":"盲派地支身体象法中，「辰」与「亥」各自主要对应哪些脏腑或身体系统？","opts":["辰主心包、心、胃；亥主肺、耳与呼吸系统","辰主神经、齿、面；亥主脾胃、饭食与体力","辰主头、肝胆；亥主大肠、骨与骨髓系统","辰主膀胱、胰、淋巴、前列腺；亥主肾阴、血、寒湿"],"ans":3,"exp":"辰主膀胱、胰、淋巴、前列腺；亥主肾阴、血、寒湿；巳主神经、齿、面。","sec":"1. 地支","t":"xiang"},{"q":"盲派天干身体象法中，天干「乙、己、癸」分别主身体的哪些部位？","opts":["乙主颈毛发眉；己主肌肤腹唇；癸主肾眼耳","乙主小肠、面；己主大肠；癸主肺、齿","乙主头、胆；己主胃、鼻；癸主膀胱、口","乙主心、眼；己主脾胃；癸主管道、血管"],"ans":0,"exp":"天干象法：乙为颈、毛发、眉；己为肌肤、腹、通道、唇；癸为肾、眼、耳。","sec":"2. 天干","t":"xiang"},{"q":"按六淫与地支的对应关系，「湿淫」与「火淫」各自对应哪些地支或组合？","opts":["湿淫为巳午未；火淫为辰丑及寅亥合","湿淫为辰丑及寅亥合；火淫为戌午未","湿淫为戌未；火淫为寅卯","湿淫为亥子丑；火淫为巳午未"],"ans":1,"exp":"六淫对应：风淫寅卯，寒淫亥子丑，暑淫巳午未，湿淫辰丑及寅亥合，燥淫戌未，火淫戌午未。","sec":"3. 六淫与地支","t":"xiang"},{"q":"在宫位位置象中，年、月、日、时四柱分别对应身体的哪部分？","opts":["年主躯干，月主生殖泌尿，日主腿脚，时主腰脊五脏","年主腰脊五脏，月主头面手，日主躯干，时主腿脚遗传","年主腿脚遗传，月主躯干，日主腰脊五脏，时主头面手及生殖泌尿","年主头面五官，月主腿脚，日主生殖泌尿，时主躯干五脏"],"ans":2,"exp":"位置象：年主腿脚、遗传；月主躯干；日主腰脊、五脏；时主头面、手与生殖泌尿；门户对应耳鼻口五官、手。","sec":"4. 位置象","t":"xiang"},{"q":"在干支组合与病性中，「子卯破、卯午破带禄身」与「丑午穿」分别主什么病象？","opts":["前者主哮喘咳嗽；后者主肾阴不足夜尿多","前者主风湿血脂高；后者主白血病与造血障碍","前者主精神错乱；后者主神经性耳聋与哑巴","前者主手术或刀伤；后者主心慌惊悸，女命主妇科"],"ans":3,"exp":"子卯破、卯午破带禄身主手术或刀伤；丑午穿主心被伤（心慌惊悸），女命主妇科。","sec":"三、干支组合与病性","t":"diff"},{"q":"按干支组合与病性，哪种日干与地支组合最典型地主阳盛阴弱、高血压？","opts":["丙日见甲或寅，或甲木日主见丙旺","庚日见亥或子，或壬水日主见申旺","癸日见辰或丑，或辛金日主见酉旺","戊日见酉或申，或己土日主见丑旺"],"ans":0,"exp":"阳亢：丙日见甲或寅，甲木日主见丙旺，皆为阳盛阴弱，主高血压。","sec":"三、干支组合与病性","t":"rule"},{"q":"男命原局「丑午穿」，但午火得寅木生而旺故不得心脏病，行北方水地时最易得什么病？","opts":["丑为脾胃成消渴，行水运必发糖尿病","丑为肾与泌尿伤了阳，成寒湿之病如前列腺病","丑为肺壅成哮喘，行水运必发急性肺炎","丑为脑血管破裂，行水运必发脑溢血"],"ans":1,"exp":"丑午穿而午旺不伤心，则丑为肾与泌尿系统伤了阳，成寒湿之病，行水地易得前列腺病、尿频尿急。","sec":"四、妇科与泌尿","t":"rule"},{"q":"女命原局出现「丑戌相刑」且逢丑运戌年引动时，为何最易应严重的妇科问题（如宫外孕）？","opts":["丑为心脏，戌为血管，相刑导致心脏骤停","丑为肝胆，戌为脾胃，相刑导致肝硬化腹水","丑为生殖系统与子女宫，戌是子女星位相刑","丑为肺金，戌为燥土，相刑导致肺癌晚期"],"ans":2,"exp":"丑代表女性生殖系统、子女宫，戌是子女之星位，两者相刑主妇科问题（如宫外孕）。","sec":"四、妇科与泌尿","t":"calc"},{"q":"肺为华盖，除辰丑湿土壅住金水外，还有哪三种情况皆主伤肺？","opts":["水多木漂、寅亥合、卯辰穿","阳刃夹日、甲己合、寅巳穿","土来浊水、胃火旺、子未穿","火克金、酉被穿、辛被合克"],"ans":3,"exp":"肺为华盖；火克金、酉被穿、辛被合克，皆伤肺；辰丑湿土壅住则成肺壅、哮喘。","sec":"五、肺与呼吸系统","t":"rule"},{"q":"某男命己己辛辛／卯巳酉卯，原局本无肺病，为何在乙丑大运却得了肺病且过运就好？","opts":["乙丑运辛酉入丑，湿土壅肺引发肺病","乙丑运木火太旺克制辛金，导致血病","乙丑运引发酉戌相穿，导致精神失常","乙丑运丑卯相穿伤及血管，导致脑溢血"],"ans":0,"exp":"原局无肺病，乙丑运辛酉入丑，湿土壅肺，故得肺病，过运就好。","sec":"五、肺与呼吸系统","t":"rule"},{"q":"按中医与盲派对应，脑与心的体用关系是（　），故「戌」在疾病上主心肺？","opts":["脾为用，肾为体，心者归于肾，肝主神明","脑为用，心为体，脑者归于心，心主神明","心为用，脑为体，心者归于脑，肾主神明","肝为用，肺为体，脑者归于肝，肺主神明"],"ans":1,"exp":"中医讲脑者归于心，心主神明，脑为用，心为体，故戌主心肺（坏戌可应脑出血或心脑血管病）。","sec":"六、心脑血管","t":"rule"},{"q":"男命甲丁甲丁／辰丑戌卯，断为「神经错乱」精神疾病的依据是（　）。","opts":["丙丁双出干克制酉金，导致双目失明且神明受损","甲木头被辰土湿气浸泡，水多木漂导致走路如踩棉花","丁主神经出于戌，丁丑刑戌而丁卯合戌，一刑一合相反作用","卯辰穿破了夫妻宫，导致为情所困而陷入抑郁"],"ans":2,"exp":"甲主头，丁主神经出于戌（心主神明），丁丑刑戌、丁卯合戌，丁火代表的神经出现相反作用，主神经错乱。","sec":"七、精神与情志病","t":"xiang"},{"q":"在精神与情志病中，「阳刃夹穿戌」与「寅夹合亥且见湿土」分别易导致什么病症？","opts":["前者为脑溢血，后者为单纯性高血压","前者为糖尿病消渴，后者为渐冻症瘫痪","前者为尿毒症，后者为系统性红斑狼疮","前者神明失控为精神病，后者湿成痰为颠狂"],"ans":3,"exp":"阳刃夹穿戌（酉戌穿），神明不能控制肉体，主精神病；寅为头夹合亥，湿化成痰，易得颠狂症。","sec":"七、精神与情志病","t":"diff"},{"q":"脏腑病性中，「水湿之邪」与「火邪」各自主要伤害什么脏腑？","opts":["水湿之邪伤肺，火邪必伤肝","水湿之邪伤肝，火邪必伤肺","水湿之邪伤胃，火邪必伤脾","水湿之邪伤心，火邪必伤肾"],"ans":0,"exp":"死木乙木怕火旺，火邪必伤肝（如肝炎）；水湿之邪伤肺（如肺壅哮喘）。","sec":"八、肝、血、肾及杂症","t":"diff"},{"q":"同样是「辛酉之金被火克」，在什么条件下不主肺病而主「白血病」？","opts":["金水相连且见辰丑湿土时，主骨髓造血为白血病","凶神夹日且纯金被火克不连水，主骨髓造血","金入墓库且无火克制时，主骨髓造血为白血病","金旺木缺且见卯辰穿时，主骨髓造血为白血病"],"ans":1,"exp":"凶神夹日，辛酉之金被火克，不主肺，必主骨，骨髓造血，所以是白血病；如果金水相连，则可能是肺。","sec":"八、肝、血、肾及杂症","t":"diff"},{"q":"女命壬癸癸壬／戌卯丑戌（癸卯日主），断为系统性免疫病「红斑狼疮」的依据是（　）。","opts":["土来浊水主消渴，胃火炽盛主满脸雀斑","寅亥合主肝郁气滞，子卯破主尿短与肾气虚","壬癸透干，卯戌合主结节红斑，两戌包局刑丑热入血髓","酉戌穿主伤肺伤心，丑辰合金主肺壅哮喘"],"ans":2,"exp":"壬癸水透干，卯戌合结节故全身红斑，两戌包局、戌刑丑热入血髓（丑主骨），故为红斑狼疮。","sec":"八、肝、血、肾及杂症","t":"calc"},{"q":"口诀「饱禄遇禄食伤全，官杀灭绝体不完，如遇丙丁双出干，定主眼目不光辉」主什么象？若丁生巳成片且甲己合到头，主什么？","opts":["前者主耳聋哑巴，后者主头晕如踩棉花","前者主渐冻瘫痪，后者主严重抑郁症","前者主白血病，后者主系统性红斑狼疮","前者主盲人（眼目受损），后者主满脸麻子"],"ans":3,"exp":"该口诀定主眼目不光辉（盲人）；丁主点子，丁生巳成一片且甲己合到头上，主满脸麻子。","sec":"八、肝、血、肾及杂症","t":"xiang"},{"q":"男命癸辛甲癸／未酉辰酉，断为「耳聋、哑巴」的命理依据是（　）。","opts":["金多甲木头怕癸侵，肾通窍于耳，两癸长在头上表示耳","丙丁双出干克制辛金，导致五官眼耳俱损","酉戌相穿伤及肺耳，且辰酉合湿邪郁于体内","寅亥合湿化成痰，阻滞咽喉与头部神明"],"ans":0,"exp":"金多，甲木怕癸侵，甲主头，两癸长在头上，肾通窍于耳，两癸表示耳，故主耳聋、哑巴。","sec":"八、肝、血、肾及杂症","t":"xiang"},{"q":"某男命辛辛辛庚／巳丑酉寅，在戊戌运庚戌年患「渐冻症」坐轮椅，其命理机制是（　）。","opts":["酉丑合金壅住肺气，导致呼吸衰竭无法站立","戌引通巳与寅成两党穿禄，年主腿脚故站不起来","庚金劈甲引丁火，导致骨髓造血功能彻底衰竭","水多木漂落不住根，导致走路如踩棉花而瘫痪"],"ans":1,"exp":"戌引通年上巳与时上寅的关联，形成两党穿禄，年上巳火与禄对抗，年主腿脚，所以站不起来。","sec":"九、糖尿病","t":"rule"},{"q":"糖尿病判断中，「未」与「丑」以及「戌」在脾胃与消渴上各代表什么象？","opts":["未为胃阳、丑为心包，戌为肺金主燥热","未为肝胆、丑为大肠，戌为胰腺主痰湿","未为脾阳、丑为脾阴泌尿，戌为胃阳主消饥","未为肾阴、丑为脾阳，戌为膀胱主寒湿"],"ans":2,"exp":"在糖尿病机制中，未为脾阳，丑为脾阴（且丑主泌尿），戌主胃阳（主消饥、消渴），多数与燥热有关。","sec":"九、糖尿病","t":"diff"}]},{"n":160,"level":"专题","title":"婚姻问答专题","qs":[{"q":"看婚姻时，主次关系是（　）。","opts":["配偶宫（日支）为主，配偶星为辅","年柱为主，日支与配偶星同为辅","配偶星为主，配偶宫（日支）为辅","配偶宫与配偶星只看合冲，不分主次"],"ans":0,"exp":"婚姻以配偶宫（日支）为主，配偶星为辅，再抓配偶宫的延伸副宫。","sec":"一、看婚姻的要点","t":"rule"},{"q":"配偶宫与配偶星发生哪一类关系，表示婚姻出问题而不是有缘？","opts":["天干压地支、地支带天干","相穿、相刑、相破","相冲也属一种关联，不算出问题","相生、相合、拱合"],"ans":1,"exp":"生合拱为好缘；冲是关联；穿刑破表示婚姻出问题。","sec":"一、看婚姻的要点","t":"diff"},{"q":"下面哪一条属于好婚姻的条件？","opts":["夫妻宫多现，配偶星也多现","夫妻宫被刑冲，表示感情热烈","夫妻宫安静，不被刑冲穿破、不杂透多现","夫妻宫暗合配偶星以外的星"],"ans":2,"exp":"好婚姻要求宫安静：有用时不被刑冲破穿，不六合暗合他星，不杂透多现。","sec":"二、好婚姻的条件","t":"rule"},{"q":"女命丑为夫宫、寅为夫星，寅丑暗合，按盲派这表示（　）。","opts":["夫星合走夫宫，丈夫容易另有新欢","夫宫制夫星，女管丈夫但婚姻差","寅丑暗合为他合，婚姻不稳必离","夫星合到夫宫，丈夫只跟自己好"],"ans":3,"exp":"配偶星合到配偶宫，表示配偶只跟自己好；他合才是合走。","sec":"二、好婚姻的条件","t":"calc"},{"q":"夫妻宫被破坏的程度与离婚的关系是（　）。","opts":["破坏轻则不一定离，太重必离，宫未坏不离","只要宫被刑冲穿破，就一定离婚","宫未坏但有外遇分居，就必然离婚","宫被破坏即分居，外遇才是离婚"],"ans":0,"exp":"能否离婚看宫的破坏程度：轻者不一定离，重者必离，宫未坏即使分居、外遇也不离。","sec":"三、差婚姻的组合与离婚的程度","t":"rule"},{"q":"配偶的正星与偏星，对「制」的要求区别是（　）。","opts":["正星可以制，偏星不可制","偏星可以制，正星不可制","正星偏星都可制，只看力量","正星偏星都不可制，制必离婚"],"ans":1,"exp":"男命正财、女命正官为正星，受制则婚姻易出问题；偏财、七杀为偏星，可以制。","sec":"四、多婚的判断规则","t":"diff"},{"q":"因夫（妻）宫被坏而离婚的，判断婚姻次数应怎么数？","opts":["夫妻宫出现几次，就是几次婚姻","大运走几步配偶运，就是几次婚姻","坏宫的东西有几个，就是几次婚姻","夫妻星有几个，就是几次婚姻"],"ans":2,"exp":"宫被坏离婚的看坏它的东西有几个；星多现离婚的才看配偶星有几个。","sec":"四、多婚的判断规则","t":"step"},{"q":"「一星两宫」：夫星拱合夫宫，但命中有两个夫宫的字，怎么断？","opts":["必离婚，第二次一定白头到老","会有两次婚姻，两字在日时伏吟也一样","只有一次婚姻，两宫相合更稳","会有两次婚姻，若两字在日时伏吟则不算二婚"],"ans":3,"exp":"第一次合不到位，会有两次婚姻；两字日时伏吟则不表示二婚。","sec":"四、多婚的判断规则","t":"rule"},{"q":"女命夫宫坐偏印、时柱占禄，按盲派属于哪种命局组合？","opts":["独身组合","夫星合夫宫的组合","好婚姻组合","多婚组合"],"ans":0,"exp":"夫宫坐偏印、时占禄、日时逢禄印，日时不见财官而劫逢劫印，都是独身组合。","sec":"五、独身命","t":"rule"}],"fine":[{"q":"看婚姻时通常不太涉及做功与象法，但在什么情况下必须使用做功与象法？","opts":["要看配偶好坏以及配偶的职业时","只要看夫妻感情是否和睦、是否离婚时","只要分辨命局有几次婚姻以及是否独身时","只要判断命主早婚还是晚婚以及结婚流年时"],"ans":0,"exp":"婚姻不太涉及做功，涉及的象法很少，独立成章；只有要看配偶好坏、配偶的职业时，才用做功与象法。","sec":"一、看婚姻的要点","t":"rule"},{"q":"男命以财为妻，若原局无明财星且地支再无遁藏，同时又无法另取替代时，基本可断（　）。","opts":["早婚且夫妻白头到老","无婚或克配偶","妻子必然多现且富贵","必主先同居后奉子成婚"],"ans":1,"exp":"男命财为妻，女命官杀为夫；没有则另看，男命再无遁藏，基本可确定无婚或克配偶。","sec":"一、看婚姻的要点","t":"rule"},{"q":"某男命申宫为妻宫，透出庚辛副宫下压伤食财星，断「五次离婚」而非「二奶三奶」的原因是（　）。","opts":["因为天干透出比劫过多，把所有财星全部合走","因为时柱落了偏印与禄神，属于绝对独身组合","因为夫妻宫申金被巳合、寅冲而动摇不稳","因为原局没有官杀子女星，导致妻子无法留下"],"ans":2,"exp":"副宫下压伤食及财星主有关系的女人多；之所以是离婚而非外室，是因为夫妻宫被冲克不稳。","sec":"一、看婚姻的要点","t":"diff"},{"q":"男命天干合财、女命天干合官在婚姻判断上的边界含义是（　）。","opts":["说明配偶只跟自己好，一生绝无感情波折","只要天干相合就百分之百代表正式领证结婚","属于典型的克配偶信号，必然导致丧偶独身","也是婚姻或感情信息，但未必能走向正式婚姻"],"ans":3,"exp":"男命天干合财、女命天干合官，也是婚姻信息，但未必走向婚姻（可能只是恋爱或同居）。","sec":"一、看婚姻的要点","t":"rule"},{"q":"女命原局夫妻宫是所忌之神，若被夫星制住（如伤官亥冲去巳火忌神），其婚姻如何？","opts":["吉，婚姻较好（如女管丈夫但家道丰盈）","大凶，主配偶早逝且命主孤苦无依","必离，主夫妻水火不容且官司不断","独身，主一生连恋爱对象都找不到"],"ans":0,"exp":"原局夫妻宫是所忌之神，被夫星制，吉，婚姻较好；或宫制夫星忌神，女管丈夫但婚姻好。","sec":"二、好婚姻的条件","t":"rule"},{"q":"女命癸丙己丙／卯辰丑寅中，年上卯木杀星被辰土穿坏，为何不表示婚姻差？","opts":["丙火透干化掉了卯木的杀气，所以夫妻宫稳固","卯杀在年与夫宫丑无关，仅主婚前处过男友","卯木是女命偏星，偏星被穿倒一律主婚姻美满","辰土是夫宫丑土的余气，穿卯等于帮夫宫护主"],"ans":1,"exp":"丑为夫宫，寅丑暗合是夫星合到夫宫；年上卯木杀星被辰穿坏，与夫宫无关，只表示婚前处过男友。","sec":"二、好婚姻的条件","t":"diff"},{"q":"按好婚姻的特殊规则，甲乙木日主以「墓库土」为财星时，若墓库土逢刑冲，主几次婚姻？","opts":["墓库逢刑冲必主克妻再娶","有几次刑冲就有几次婚姻","都是一次婚姻","墓库土被冲开后必主一生独身"],"ans":2,"exp":"规则：甲乙木日主，墓库土为财时，土逢刑冲都是一次婚姻，不会离婚也无情人。","sec":"二、好婚姻的条件","t":"rule"},{"q":"乾造乙庚丁癸／酉辰未卯，局中卯辰穿、卯酉冲，为何一辈子不离？若换作「丁卯日」结果如何？","opts":["现局妻宫未土入辰墓护住，丁卯日也同样不离","现局乙庚合化金所以不离，丁卯日则主丧偶","现局财星太旺所以不离，丁卯日妻星更旺更稳","现局穿偏了只主不和，若丁卯日妻宫逢穿则必离"],"ans":3,"exp":"妻宫未土与财星安静且未入辰墓，卯辰穿是穿偏了，只是不和；若是丁卯日妻宫逢穿，则必离。","sec":"三、差婚姻的组合与离婚的程度","t":"rule"},{"q":"当夫妻宫是无用之神时，若在局中「作忌神无制」或「作用神被坏」，婚姻上主什么？","opts":["配偶帮不上忙，且夫妻感情差","虽然夫妻经常吵架，但配偶极其能干助己","命主一生必然独身，绝无任何异性缘分","配偶官居高位，能给命主带来丰厚家产"],"ans":0,"exp":"夫妻宫是无用之神，作忌神无制，或作用神被坏：配偶帮不上，感情差。","sec":"三、差婚姻的组合与离婚的程度","t":"rule"},{"q":"女命甲辰己庚／辰辰酉午，比劫林立且夫星甲木坐比劫，为何依然没有离婚？","opts":["甲木正官在年柱力量太弱，所以根本不算是夫星","比劫争夫主丈夫在外有女人，但辰酉合未坏故不离","辰土印星化掉了比劫的争抢，所以没有第三者","庚金伤官在时柱护住了酉金，所以丈夫极其专一"],"ans":1,"exp":"夫星坐比劫、比劫争夫，主丈夫不爱她与外边女人相好；但辰酉合（夫星合到夫宫）未坏，所以没离。","sec":"三、差婚姻的组合与离婚的程度","t":"diff"},{"q":"多婚判断规则中，若「夫妻宫逢穿，且夫妻宫穿了夫妻星的那个字」，结果通常是（　）。","opts":["只是夫妻口角多，一辈子绝对不离","说明配偶只对自己好，在外绝无桃花","必离婚，或配偶死亡","夫妻越吵越恩爱，越穿感情越牢固"],"ans":2,"exp":"夫妻宫逢穿，夫妻宫穿了夫妻星的那个字，必离婚，或配偶死亡。","sec":"四、多婚的判断规则","t":"rule"},{"q":"当夫妻宫本身落着夫妻星时，最忌讳哪种地支关系，一出现就容易导致合走而离婚？","opts":["不喜地支见禄神，一见禄神就立刻离婚","不喜天干透出正印生身，一透印就离婚","不喜自合，日主自合配偶星必导致离婚","不喜他合（六合、暗合配偶星以外的星）"],"ans":3,"exp":"夫妻宫落夫妻星时，不喜他合（六合、暗合），一合就容易合走，离婚者居多。","sec":"四、多婚的判断规则","t":"rule"},{"q":"某男命甲壬戊己／辰申子未，妻宫子水正财得位且旺相，为何却连克两任妻子、三婚才稳？","opts":["得正位配偶星忌被克破，局中未土与己土两土克制子水","申子辰三合水局把正财化为比劫，导致妻子跟人跑","甲木七杀透干克制日主，导致命主无力承担婚姻","子水正财太旺导致身弱不胜财，必须靠二婚化解"],"ans":0,"exp":"得正位的配偶星不敢被克破，克破必有婚姻问题；克制妻宫子水的有未土与己土两土，故克掉两妻。","sec":"四、多婚的判断规则","t":"rule"},{"q":"女命原局出现「夫宫合入夫星之墓」（如夫宫午合入夫星木之墓未），通常应什么凶象？","opts":["丈夫长寿富贵，且夫妻一生恩爱无波折","夫不死则离（夫寿有损或婚姻破裂）","命主自己克子嗣，但婚姻绝对稳固不变","丈夫官运亨通，能当上部队高级军官"],"ans":1,"exp":"夫宫合入夫星之墓（或合了夫星之墓），夫不死则离，主夫寿有损。","sec":"四、多婚的判断规则","t":"rule"},{"q":"男命坐下亥水妻星得正位，但月上寅木把妻星合走，行己巳运逢巳亥冲时易发生什么？","opts":["寅亥合化木帮身，行己巳运反而迎来初婚喜庆","亥水被冲走后立刻转为正官，主大运升职加薪","典型的二婚命，行己巳运冲走妻星亥水而离婚","妻星得正位绝不会离，己巳运只是夫妻短暂分居"],"ans":2,"exp":"坐下妻星得正位，不喜他支合走，是典型二婚；行己巳运巳火把妻星亥水冲走，离婚。","sec":"四、多婚的判断规则","t":"rule"},{"q":"按盲派分类，「独身命」在现实生活中有哪三种具体表现形态？","opts":["一婚离异二婚好、三婚白头到老、一生暗恋他人","终生出家为僧尼、晚年丧偶不再娶、异地分居不离","早婚必离再婚稳、中年丧夫守寡、只恋爱不生子","一生独身无性伴、有性伴但不结婚、短暂婚史后独身"],"ans":3,"exp":"独身命有三种：①一生独身且没有性伙伴；②有性伙伴但一生不结婚；③有过短暂婚史，最后独身。","sec":"五、独身命","t":"rule"},{"q":"日时逢禄印或劫逢劫印的「独身组合」，若年月干支透出财官，婚姻会如何发展？","opts":["有婚姻之象，遇运可婚，但随后又散","绝不可能结婚，连恋爱经历都不会有","彻底打破独身组合，结婚后必白头到老","早年必然同居生子，但绝不领结婚证"],"ans":0,"exp":"日时逢禄印等是独身组合；如果年月有财官，则有婚姻之象，遇运可婚，随后又散（终归独身）。","sec":"五、独身命","t":"rule"},{"q":"独身命中有一种「水中捞月」型（如坐下正星自合又见偏旺干挠），其核心心理与现实特征是（　）。","opts":["夫妻宫被严重穿破，导致每次谈恋爱都惨遭背叛","过分理想主义且有干挠星，连女友也没有、难成婚","身边情人无数且花心多变，所以不愿被婚姻束缚","命中财官太弱入墓不开，所以只能被迫打光棍"],"ans":1,"exp":"“水中捞月”型：夫妻宫坐正星天地相合，有理想配偶且无法摆脱，但局中有干挠星，过分理想主义而找不到。","sec":"五、独身命","t":"xiang"},{"q":"女命己丙壬己／丑寅午酉，夫宫午坐正财正官且天地相合，为何五十岁以上仍从未结婚？","opts":["壬水日主被己土比劫合走，导致没有异性缘分","寅木食神太旺克制了正官，导致官星绝迹","丑午穿坏了正星，且透干偏财丙火相当于偏官干挠","酉金印星落在时柱，属于绝对的日时禄印独身"],"ans":2,"exp":"虽天地相合，但丑午穿坏了正星；且透干偏财丙火，等同于偏官透出干挠，所以一生无婚。","sec":"五、独身命","t":"diff"},{"q":"同样是夫（妻）宫被局中反坏而致独身，男命丁癸丁辛／亥丑未亥乞食，而某女命子水被官旺反坏却是高薪会计，原因何在？","opts":["男命行运走北方水运太差，女命行运走南方火运极好","男命属比劫争妻所以破财，女命属财合印所以工作能力强","男命八字无财星所以穷困，女命八字财库大开所以富贵","男命未土是主位之体不可坏，女命子水伤官可去论吉"],"ans":3,"exp":"男命未土是主位的体，要用之做功，被局中制坏则一生穷困；女命子水伤官可去，去之论吉，所以工作能力极强。","sec":"五、独身命","t":"diff"},{"q":"在断命记录中，推断「兄弟几个」时，除看日主之外的同类字，还必须结合哪些维度？","opts":["四柱兼顾，并联系年月、童运与国运（如计划生育）","只看年柱印星旺衰，与比劫数量没有任何关系","只看天干透出的同类，地支藏干一律不计入内","只看月柱比劫数量，无需参考大运和出生年代"],"ans":0,"exp":"兄弟与我平等，看日主之外的“同类”字，应四柱兼顾，并联系年月、童运、国运来断人数。","sec":"六、断命记录：从一个命例推排行、结婚、子女与生年","t":"step"},{"q":"在断命记录中，推断子女个数的核心抓手是什么？如何分辨子女的男女？","opts":["死死抓住年柱并参考早运；男女之别在于天干阴干阳干","死死抓住时柱并参考中运；男女之别在于天干有根无根","死死抓住月柱并参考晚运；男女之别在于地支刑冲合害","死死抓住日支并参考大运；男女之别在于官杀旺衰强弱"],"ans":1,"exp":"子女须死死抓住时柱并参考中运；辛虚浮无根为嫁出之女，男女之别在根。","sec":"六、断命记录：从一个命例推排行、结婚、子女与生年","t":"step"},{"q":"断流年结婚信号时，「寅午半合」与「卯为夫根到原局位」在成婚进程上如何区分？","opts":["前者为正式领证拜堂，后者为婚后生子之年","前者为仅仅互相暗恋，后者为双方家长反对分手","前者为人已结合尚未拜堂，后者为夫根到位正式成婚","前者为订婚后立刻悔婚，后者为再婚之年"],"ans":2,"exp":"丙寅年寅午半合，人已结合，尚未拜堂；丁卯年卯为夫根到原局位，正式成婚。","sec":"六、断命记录：从一个命例推排行、结婚、子女与生年","t":"diff"},{"q":"针对「何以生女」的命理原理，十干十二支的阴阳与现实生男生女的关系是（　）。","opts":["日主为阳干必生男孩，日主为阴干必生女孩","食神一律固定生女孩，伤官一律固定生男孩","阳干阳支一律生男孩，阴干阴支一律生女孩","干支阴阳不等于男女，动阳静阴且阴阳动静反复迁变"],"ans":3,"exp":"十干十二支的阴阳不等于男女（否则何来阴男阳女之说）；动阳静阴，阴阳动静反复迁变，须通变。","sec":"六、断命记录：从一个命例推排行、结婚、子女与生年","t":"rule"}]},{"n":161,"level":"专题","title":"答疑汇编专题（一）：作功、体用、反局与合用","qs":[{"q":"盲派看八字，判断谁作功，先后顺序是哪个？","opts":["日支，其次月令，再看日主","日主，其次日支，再看日主的延伸物","月令，其次日主，再看时柱","用神，其次日主，再看日支"],"ans":1,"exp":"先看日主是否作功；不参与则看日柱（日支）；再不行看日主延伸物。不先看身强弱或从与不从。","sec":"2. 先看谁作功","t":"step"},{"q":"日主与日支表达的意思不一致时，以谁为主？","opts":["以日支为主","以势大的一方为主","以日主为主","以月令为主"],"ans":2,"exp":"作功顺序里明文：日主与日支意思不一致，以日主为主。","sec":"2. 先看谁作功","t":"rule"},{"q":"「木火局」与「金水局」的先天作功情况，下列哪个对？","opts":["木火与金水局都先天无功","金水局先天有功，木火局先天无功","木火与金水局都先天有功","木火局先天有功，金水局先天无功"],"ans":3,"exp":"木火「火炎上」，木见火燃烧本身就作功；金水「水润下」先天无功。","sec":"3. 好命与差命","t":"diff"},{"q":"财多的八字要作功，口诀说财作功有哪三式？","opts":["去印、去劫、入库","去食、去劫、合官","去印、去官、入库","去劫、生官、入库"],"ans":0,"exp":"口诀：财多无功要见官；财作功三式：去印、去劫、入库。","sec":"4. 学历、职业、财官怎么用作功看","t":"rule"},{"q":"日主身弱、水为财且很多而无功，要让财「入库」作功，需见下列哪个字？","opts":["丑","辰","未","戌"],"ans":1,"exp":"财多无功，入库是作功三式之一；辰是水库（本章以辰库收财为例）。","sec":"4. 学历、职业、财官怎么用作功看","t":"calc"},{"q":"体用关系中，「行干运」与「行支运」怎么分体用？","opts":["行干运与行支运都是大运为体","行干运干为体支为用；行支运支为体干为用","行干运支为体干为用；行支运干为体支为用","行干运与行支运都是原局为用"],"ans":2,"exp":"行干运，支为体，干为用；行支运，以干为体，支为用。","sec":"二、体用的多种用法","t":"rule"},{"q":"看六亲的体用，「宫位」与「星」哪个是体哪个是用？","opts":["两者都是体","两者都是用","星为体，宫位为用","宫位为体，星为用"],"ans":3,"exp":"宫位是定的，星可以变（如婚姻，家是定的，进来的女主人可变）。","sec":"二、体用的多种用法","t":"diff"},{"q":"盲派看父母，怎样才断父母过世？","opts":["体用同时出问题","仅用出问题","仅体出问题","印星被克"],"ans":0,"exp":"生身父母一生不能换，不像婚姻那样看；体用同时出问题，才断过世。","sec":"二、体用的多种用法","t":"rule"},{"q":"按同象规则，癸卯、丁丑、甲子、乙亥四柱，哪一柱天干与地支「同象」？","opts":["甲子、乙亥","癸卯、丁丑","丁丑、乙亥","癸卯、甲子"],"ans":1,"exp":"天干生地支的柱子同象（癸生卯、丁生丑）；支生干（子生甲、亥生乙）不算。","sec":"1. 同象","t":"calc"},{"q":"按盲派，天干异性相克（非合制）是什么结果？","opts":["功大","有功但会被冲坏","无功","功小"],"ans":2,"exp":"同性相克功不大；天干异性相克无功（除了合制）。","sec":"2. 虚实","t":"rule"},{"q":"反局的两种类型是什么？","opts":["合局反局与冲局反局","原局反局与流年反局","日主反局与月令反局","原局反局与大运反局"],"ans":3,"exp":"原局反局是日主或日柱意思与八字整体相反；大运反局是大运与原局意向对抗。","sec":"1. 反局的定义","t":"diff"},{"q":"日主合财，身弱与身旺各喜什么样的财星？","opts":["身弱喜财虚透，身旺喜财旺相","身弱身旺都喜财旺相","身弱喜财旺相，身旺喜财虚透","身弱身旺都喜财虚透"],"ans":0,"exp":"身弱合财，财重则无财，喜财星虚透；身旺合财，喜财旺相，财虚则不主财富（换象除外）。","sec":"五、日主合财的用法","t":"rule"}],"fine":[{"q":"在盲派命理中，「功神」的本质是什么？","opts":["天干透出的财星与官星","一种作用关系中的两个或多个神","专指日主和日支两个字","八字中最旺的那个十神"],"ans":1,"exp":"功神实际不是单一的某个神，而是参与冲刑合化生克墓等作用关系、产生效率的两个或多个神。","sec":"1. 什么是作功","t":"rule"},{"q":"当一个八字的功神较多时，分析命局的正确抓手是什么？","opts":["功神多反而分散力量，一律按废神看","只看年柱和月柱的功神，时柱不论","先抓核心功神，其余视为辅助功神","把所有功神平均分配权重逐一论断"],"ans":2,"exp":"功神多时要抓住核心功神，其余为辅助功神，如同成功者有左膀右臂协助作功。","sec":"1. 什么是作功","t":"rule"},{"q":"若日主在八字中不参与作功，盲派应如何处理？","opts":["立即转按传统身强身弱定喜忌","先判定是否构成化气格再论吉凶","直接断该八字一生无所作为","弃日主不看，专看日支与日主延伸物"],"ans":3,"exp":"日主不参与作用就弃之不看，专看日支；日主强弱与化气格均无关紧要，关键是有功无功。","sec":"2. 先看谁作功","t":"step"},{"q":"盲派认为「有大成就的八字」通常具备什么核心条件？","opts":["有势、势与主一致且该势有大功","日主身旺且财官印三奇透干","八字五行齐全、流通无克无冲","大运一路走印比帮身之运"],"ans":0,"exp":"大成就的八字往往有势（木火、金水等），势与主一致并由日柱主导或顺应，且须有制服的对手即大功。","sec":"3. 好命与差命","t":"diff"},{"q":"同样属于「差命」，哪两类人的表现明显不同？","opts":["一类废神太多，另一类功神全在日主身上","一类作功但效率极低，另一类日柱无作功之意","一类财多身弱，另一类印多身旺","一类木火成势，另一类金水成势"],"ans":1,"exp":"一类自己作功但效率极低，多为辛苦的体力劳动者；另一类日柱没有主动作功的意思，平淡无所追求。","sec":"3. 好命与差命","t":"diff"},{"q":"财多无功时，除了入辰库与官统财，用「制官」和「制印」来作功分别对应哪个地支？","opts":["见申制官、见子制印","见卯制官、见巳制印","见寅制官、见午制印","见戌制官、见未制印"],"ans":2,"exp":"在戊辛壬癸之类财多（水旺）局中，有寅则亥水制官有功，有午则水火制印有功，有辰库则财入库。","sec":"4. 学历、职业、财官怎么用作功看","t":"calc"},{"q":"看学历时，官杀印、食杀、伤配印、财配印等组合都能当学历，其前提条件是什么？","opts":["日主必须处于建禄或帝旺之地","这些十神必须全部透出天干","年柱和月柱不能出现任何冲克","该组合必须在局中真正有功"],"ans":3,"exp":"看学历不限于单一十神，关键是这些组合必须产生作用与效率，只有有功才能成事。","sec":"4. 学历、职业、财官怎么用作功看","t":"rule"},{"q":"乾造「乙乙戊乙／丑酉寅卯」中，卯酉冲与寅丑暗合的作功情况分别是？","opts":["卯酉冲无功全废，只有寅丑暗合有功","寅丑暗合无功，全靠卯酉冲制伤官","卯酉冲功最大，寅丑暗合次之","卯酉冲与寅丑暗合都算大功"],"ans":0,"exp":"此造卯酉冲一定无功、全废；只有寅丑暗合有功，且离得远、合不紧，功小，故为煤矿工人。","sec":"5. 命例：功有轻重，效率有高低","t":"calc"},{"q":"乾造「壬癸己丙／子丑酉寅」中，酉丑半合与寅丑暗合相比，效力如何？","opts":["酉丑半合直接把丑财带入日主，功最大","半合力不紧且在宾位，比六合弱、功小","半合在宾位完全不算作功，属于反局","半合力量大于六合，属于核心大功"],"ans":1,"exp":"酉丑半合力不紧，比六合还弱，功小；宾位作功虽多，但对日柱联系太弱，视为浪费。","sec":"5. 命例：功有轻重，效率有高低","t":"diff"},{"q":"乾造「戊辛壬癸／辰酉子卯」中，时支卯木为何被判为纯粹的废神？","opts":["因为辛金印星直接克死了卯木","因为时柱属于宾位，一律不参与作功","卯不长且子不太生，伤官不能泄秀","全因辰卯相穿把卯木彻底穿坏了"],"ans":2,"exp":"卯木本身不长、子不太生之，又有伤官心性不好，不能泄秀就是纯粹的废神，并非因为辰穿它。","sec":"5. 命例：功有轻重，效率有高低","t":"xiang"},{"q":"用体用关系断子女时，「体受损」与「用受损」分别应什么事？","opts":["体受损子女远行，用受损子女早婚","体受损生女儿，用受损生儿子","体受损无大碍，用受损主子女富贵","体受损会小产，用受损出生后逢凶"],"ans":3,"exp":"受胎时看体位，体受损会小产；出生后与母体无关、以用为主，用受损则出生后子女逢凶。","sec":"二、体用的多种用法","t":"diff"},{"q":"依「财官为用，印禄为体」的体用规则，亥未相拱应如何理解方向？","opts":["用的东西向体，是财拱到主位","财与印双向互拱，不分主宾方向","只看地支五行生克，不论拱向何方","体的东西向用，是印拱到宾位"],"ans":0,"exp":"用的东西向体、为体所用，而不是相反，故亥未拱是财拱到主位，而非印拱到宾位。","sec":"二、体用的多种用法","t":"rule"},{"q":"大运走「壬子」时，壬运与子运的体用状态有何不同？","opts":["壬运以壬为体，子运以子为体","壬运子不动而壬动，子运壬不动而子动","壬运与子运都是干支一起动，体用不变","壬运子动且子受壬管，子运壬动且壬受子管"],"ans":1,"exp":"行干运支为体干为用，壬运子不动壬在动、好办；行支运干为体支为用，子运子受壬象管，常功败垂成。","sec":"二、体用的多种用法","t":"calc"},{"q":"当八字里的伤官反克大运官杀时，在六亲上通常应验在谁身上？","opts":["应在父亲身上，不应在子女身上","同时应在父亲和母亲身上","应在子女身上，不应在父亲身上","应在配偶身上，不应在子女身上"],"ans":2,"exp":"八字为主、大运为宾，只能宾作用于主；伤官反克大运官杀是从象上讲，故应在子女而非父亲上。","sec":"二、体用的多种用法","t":"rule"},{"q":"乾造「甲甲丙壬／申戌寅辰」看婚姻，主多妻或有克的关键依据是什么？","opts":["时干透出壬水七杀直接克制日主","日柱丙寅自坐长生而力量过旺","月令戌土食神空亡导致妻星无根","妻宫寅之原身甲透干多现为副妻宫"],"ans":3,"exp":"申冲寅并不主要，关键是寅的原身甲木透干且多现，成为副妻宫，妻宫多现主多妻或有克。","sec":"命例：以六亲体用断一个命","t":"xiang"},{"q":"关于「活木怕埋根之铁」与天干虚实，下列说法哪个准确？","opts":["甲辰见酉、甲寅见申都算活木埋根之铁","天干异性相克即使非合制也功大","只有甲辰见酉才算，甲寅见申不算","地支金可以直接克死天干的甲木"],"ans":0,"exp":"「活木怕埋根之铁」不止甲辰见酉，甲寅见申等也是；地支不克天干，且天干异性非合制相克无功。","sec":"2. 虚实","t":"rule"},{"q":"对比「日主合官」与「日主合财」，两者的核心判断规则有何不同？","opts":["合官与合财都要先严格区分日主旺衰","合财要看身强弱，合官要看官下支是什么","合官要看身强弱，合财要看财下支是什么","合官与合财都不必看地支，只论天干五合"],"ans":1,"exp":"合财要看身强身弱，合官没有身强弱的说法，合官重点看官星下面的地支是什么。","sec":"五、日主合财的用法","t":"diff"},{"q":"乾造「辛丙辛丙／卯申巳申」日主合丙官用申劫，为何只是工人而非官命？","opts":["日主辛金坐申为帝旺，身旺不需要官星","丙辛合化水成功，官星完全变成食伤","申在宾位且巳被他合，两边合牵制难制官","卯木财星太旺，把申金劫财全部耗尽"],"ans":2,"exp":"申在宾位不得力，巳申合使巳被他合，年月干丙辛两边合相互牵制，无法制官，故只是管机器的工人。","sec":"2. 日主合官的两种境遇","t":"calc"},{"q":"在「合冲换象」中，什么时候相合必须换象，什么时候冲才能换象？","opts":["只有天干五合能换象；地支六冲一律不换","又合又冲时因为力量更大，最容易换象","合无论何种情况都不换象；见冲即换象","辨十神意思时合要换象；冲须冲制干净才换"],"ans":3,"exp":"辨别十神意思时合一定要换象才能认识该神；冲之换象须冲制干净，又合又冲不干净故不能换。","sec":"3. 合冲换象","t":"rule"},{"q":"原局合制干净，大运再来冲，按盲派应如何定性？","opts":["合制不喜冲，冲则局反了","冲开合神，刚好把象换成冲的象","冲能助合，使原局功神效率加倍","原局合制已成，大运来冲毫无影响"],"ans":0,"exp":"原局合制干净，大运来冲是局反了：合制不喜冲，冲则反局，不是象变了，而是局反了。","sec":"3. 合冲换象","t":"rule"},{"q":"盲派为什么不论传统命理的「从格」？","opts":["从格只适用于女命，男命一律不从","所谓从格实为主位日支起了决定作用","只要天干有比劫帮身就绝对不会从","因为盲派完全不承认五行的存在"],"ans":1,"exp":"从格由日主衰旺而来，本体系不论从格；看似从格实为主位（日支）起决定作用，日支无用则从格无意义。","sec":"4. 反用与弱制","t":"rule"},{"q":"坤造「戊壬甲辛／午戌子未」夫宫子水正星被制，为何婚姻不会有大问题？","opts":["日主甲木合辛官，完全不用夫宫子水","因为原局有戌土帮扶子水官星","正星子被未穿即反，相当于偏星可制","午戌拱火生旺子水，夫宫越制越旺"],"ans":2,"exp":"日支被制也是作功，正星一般不可制，但子被未穿后正星一穿即反、相当于偏星，故婚姻无大问题。","sec":"五、日主合财的用法","t":"xiang"},{"q":"关于「禄」的喜忌，禄神在什么情况下出现反而为凶？","opts":["只要日主身旺，大运见禄就一定为凶","禄神与食神同时存在时必主大凶","只要禄神落在时支，一出现就主凶","禄无功、遭回制穿害或单薄无助时"],"ans":3,"exp":"禄喜静，不喜财、冲刑、重见、官杀；当禄无功、遭局中回制穿害、单薄无助时，出现为凶。","sec":"六、财官、官印与禄","t":"rule"},{"q":"八字中没有官杀时，男命通常以什么六亲十神来看子女？","opts":["以财星为子女","直接断无子女","以比劫为子女","以印星为子女"],"ans":0,"exp":"八字无官杀时以财为子；若原局财星已有克，大运再逢冲则子女易有灾。","sec":"六、财官、官印与禄","t":"rule"}]},{"n":162,"level":"专题","title":"答疑汇编专题（二）：合冲穿、墓库、禄神与六亲位置","qs":[{"q":"按盲派，原局合制干净，大运又来冲，怎么论？","opts":["合被冲开，象就换成冲的象","冲开合神，反而更吉","合制不喜冲，冲则反局","冲运只是引动，原局不变"],"ans":2,"exp":"原局合制干净时，运来冲不是象变，而是整个局反了。","sec":"一、合与冲的细节","t":"rule"},{"q":"合之后又逢冲，能不能因此换象？","opts":["只要逢冲就换象","合神被冲开后，按冲论象","合在前冲在后，冲胜则换象","冲制不干净，不能换象"],"ans":3,"exp":"冲换象必须冲制干净；又合又冲一定不干净，所以不换。","sec":"一、合与冲的细节","t":"diff"},{"q":"年午、月戌两字相邻，问午入戌墓吗？","opts":["不入墓，午戌论拱","入墓，午火墓在戌","不入墓，按午戌半合火局论","入墓，但要有冲才算"],"ans":0,"exp":"入墓只有寅申巳亥见墓才成立；午戌论拱，不是入墓。","sec":"二、墓库的问题","t":"calc"},{"q":"按盲派，墓库里的东西什么时候才起作用？","opts":["库中本气一出就有用","逢冲刑开库才有用","逢合闭库才有用","入库即可用，冲反而破坏"],"ans":1,"exp":"官财之库不刑不冲没有用，冲刑开库才流动，近冲作功最大。","sec":"二、墓库的问题","t":"rule"},{"q":"子丑合与寅丑暗合，对丑库的处理有何不同？","opts":["子丑合不闭库；寅丑暗合闭土库","两者都闭库，只是闭的五行不同","子丑合闭金库；寅丑暗合不闭库，看谁制谁","两者都不闭库，只论五行生克"],"ans":2,"exp":"子丑合闭金库；寅丑暗合不闭库，只是制的意思，要看各自气势。","sec":"二、墓库的问题","t":"diff"},{"q":"墓库逢冲时，库里的气力量怎么排？","opts":["本气最大，余气次之，墓气最小","三气平分，看月令来定先后","余气最大，墓气居中，本气最小","墓库之气大于余气，本气未必更大"],"ans":3,"exp":"按力量排名，墓库之气＞余气，本气未必大过墓气。","sec":"二、墓库的问题","t":"rule"},{"q":"按盲派，干禄（日禄归时）的时柱只有哪两个？","opts":["丁未时与癸丑时","戊午时与己未时","丙午时与丁巳时","甲寅时与乙卯时"],"ans":0,"exp":"日禄归时中干禄只有丁未时、癸丑时，且成禄格的并不多。","sec":"三、禄、空亡与日禄归时","t":"rule"},{"q":"禄神伏吟（大运又见禄），什么情况不怕？","opts":["禄逢三合成局，力量加倍","禄为功神且局中是禄的气势","禄落在日支，直接帮身","日主身弱，需要帮扶"],"ans":1,"exp":"禄为功神且局中是禄的气势，不怕伏吟；禄无功、遭穿害、单薄无助才凶。","sec":"三、禄、空亡与日禄归时","t":"diff"},{"q":"断禄绊桃花时，禄要落在哪里才算？","opts":["只在月支","四支任何一处","日支或时支","年支或月支"],"ans":2,"exp":"日支、时支是主位，禄才代表日主本人；他支为宾位，不算。","sec":"三、禄、空亡与日禄归时","t":"rule"},{"q":"按盲派，六亲位置怎么找？","opts":["四亲都只在对应宫位里找","父母在时日，夫妻在年月","夫妻在日支，子女只在时柱","父母在年月，夫妻子女可在任何位置"],"ans":3,"exp":"除父母在年月找外，夫妻子女可在局中任何位置。","sec":"四、六亲的位置","t":"rule"},{"q":"看子女时，宫位什么情况才特别要看？","opts":["不生育或克子女时才显示宫位","宫位始终比星位重要","星位不现时才看宫位","只要时支逢冲就看宫位"],"ans":0,"exp":"子女只有不生育或克子女者宫位才显示，其他情况宫位不重要。","sec":"四、六亲的位置","t":"diff"},{"q":"按盲派，财怎样才算大财？","opts":["财透天干即为大财","财与日柱作了功，此财才较大","财多身旺就是大财","见财即为大财"],"ans":1,"exp":"凡财都是钱，只有财与日柱作了功才较大；无功只取旁财，仅够维持生活。","sec":"四、六亲的位置","t":"rule"}],"fine":[{"q":"天干五合中，什么情况下该字会「合而必化」（被合去）？","opts":["只要合神落在年柱或月柱就必化","月令恰好与化神五行相同即可","衰极之时，且该字的地支不扶","旺极之时，且地支有强根扶持"],"ans":2,"exp":"衰极之时合而必化，即该字地支不扶；依干支虚实看，如癸卯一柱为虚，流年戊来则癸被合去。","sec":"1. 天干五合与地支六合","t":"rule"},{"q":"下列哪组地支藏干之间的「暗合」在盲派里不成立？","opts":["寅中甲与丑中己、寅中丙与丑中辛","午中丁与亥中壬、午中己与亥中甲","卯中乙与申中庚、寅中戊与丑中癸","巳中戊与子中癸、戌中戊与子中癸"],"ans":3,"exp":"巳中戊与子中癸暗合不成立，戌中戊合子中癸也不成立，不可乱作戊癸暗合。","sec":"1. 天干五合与地支六合","t":"calc"},{"q":"「丁壬合」中壬子一柱合入主位丑，而丁在远处，这在心性喜好上怎么区分？","opts":["壬子与主位有关，丁远离主位不算自己喜好","壬子合入丑后完全失去原有心性内涵","丁与壬既然相合，丁也一定算自己喜好","远离主位的丁更能代表内心深处想法"],"ans":0,"exp":"壬子一柱合入主位丑则与主位有关，丁远离主位不能算自己的喜好；贴近日主或坐日支的食伤才关乎精神灵魂。","sec":"1. 天干五合与地支六合","t":"xiang"},{"q":"关于「辛巳自合」，下列哪项判断符合盲派细则？","opts":["辛巳自合无论见什么支，一律按凶论","只表官的性质，无辰泄巳杀则不能为官","只要柱见辛巳自合，必主有官职","辛巳自合等于劫财合杀，有午即可当官"],"ans":1,"exp":"辛巳自合只表示官的性质，无辰则不能为官；辰土印星主星入主，泄巳杀化忌为用才为官。","sec":"1. 天干五合与地支六合","t":"rule"},{"q":"乾造「壬庚壬癸／寅戌辰卯」中，卯戌合与辰戌冲并见，两者是什么关系？","opts":["冲神在合神中间，只论辰戌冲不论合","卯穿辰破了主位，此造彻底破格","卯戌合促其冲，贵在辰戌冲开财库","卯戌合解除了辰戌冲，财库无法打开"],"ans":2,"exp":"此造卯戌合制杀得权、促其冲，贵在辰戌冲开财库；卯在木火势中且辰用不在帮身，故卯穿辰无害。","sec":"2. 冲中有合","t":"calc"},{"q":"「夹冲（如三戌冲辰）」的结果是什么？「夹刑」能否与冲同论？","opts":["三戌冲辰反把戌冲坏；夹刑与冲同论","夹冲力量分散反而不坏；夹刑力量大于冲","被冲者越冲越旺；夹刑与夹冲完全一样","一方二一方一被冲者坏；夹刑不能与冲同论"],"ans":3,"exp":"一方两个、一方一个，不平衡，所以被冲者坏；夹刑是一种挤压，刑的角度不一样，不能与冲同论。","sec":"3. 夹冲、夹刑与三戌冲辰","t":"diff"},{"q":"冲大运时，「不当运」与「当运」各主什么不同结果？","opts":["不当运时为引动，当运时为冲去","无论当运与否，冲大运一律为冲去","不当运时为冲去，当运时为引动","不当运时为破合，当运时为合绊"],"ans":0,"exp":"不当运时冲运为引动，当运时为冲去；而冲八字中的字则是破合。","sec":"4. 冲运、冲流年","t":"diff"},{"q":"关于大运与命局之间的干支生克路径，下列哪项正确？","opts":["命局地支可以直接克制大运天干","只有同柱才能干支相生克，否则干论干支论支","大运天干可以直接生克命局地支","只要五行相克，干支隔柱也能直接生克"],"ans":1,"exp":"只有同一柱才能干支相生克；大运天干只作用命局天干，地支只作用地支，干支以禄与原身出现时才论反克。","sec":"4. 冲运、冲流年","t":"rule"},{"q":"原局出现六穿时，如何确定「谁穿了谁」（穿与被穿）？","opts":["一律以年支、月支穿日支、时支","一律以土穿水、以金穿木，不看气势","相克之穿看势在哪里，得势方穿对方","双方力量永远均等，不存在谁穿谁"],"ans":2,"exp":"原局确定穿与被穿，相克之穿看势在哪里，哪方得势即能穿了对方。","sec":"5. 穿与被穿","t":"rule"},{"q":"盲派认为「入墓」有哪两种情况？为何子午卯酉见各自之墓不以墓论？","opts":["只有寅申巳亥能入墓；四正见墓一律论冲","只有天干透出才入墓；四正见墓论相穿","四正见墓最易入墓；四长生见墓反论生","多而墓之及寅申巳亥见墓；四正有半合关系"],"ans":3,"exp":"入墓有二：多而墓之，寅申巳亥见墓入之；子午卯酉见各自之墓因有半合局关系，主要以拱合论。","sec":"二、墓库的问题","t":"diff"},{"q":"乾造「乙乙丙己／未酉戌丑」原局酉被戌穿倒，为何不死于庚戌年而死于癸丑年？","opts":["酉入墓于丑，戌年刑开丑库，丑年库到为应期","戌年只穿不墓，丑年才开始穿倒酉金","庚戌年有乙庚合解救，癸丑年乙木被克","庚戌年财星透干太旺，癸丑年土重埋金"],"ans":0,"exp":"父酉弱而见墓为应期；原局酉入墓于丑，戌年正好刑开丑库反而不死，到癸丑年库到才是应期。","sec":"二、墓库的问题","t":"calc"},{"q":"坤造「癸乙戊己／卯卯寅未」（开药房连锁后破财）重病在哪里？","opts":["大运走丙丁巳午火运，烧毁了所有草木","未库「只吃不拉」，无丑戌冲刑不开","癸水财星太旺，把戊土和己土冲散了","卯木官星太多，导致未土彻底被克碎"],"ans":1,"exp":"一片草木（药）落入未库（药房），但无丑戌冲刑开库，只吃不拉导致周转不灵，己未运败局已定。","sec":"二、墓库的问题","t":"xiang"},{"q":"关于「空亡」的用法，年柱空亡与日柱空亡相比，哪个更重要？","opts":["年柱比日柱更重要；算法最难，用法简单","只算年柱空亡，日柱空亡一概不论","都算空亡，但日柱更重要；用法最难","年柱与日柱空亡同等重要，全凭算法定吉凶"],"ans":2,"exp":"空亡日柱与年柱都算，日柱更重要；空亡的算法并不太重要，用法最难。","sec":"三、禄、空亡与日禄归时","t":"diff"},{"q":"乾造「乙己己庚／巳丑未午」为何不敢见禄运（午运）？","opts":["因为己土身太旺，见午禄会形成火炎土燥","因为原局用禄去财，怕禄神伏吟破财","因为庚金伤官坐午火，会伤官见官","禄为寿元星，禄出现时丑午相穿为凶"],"ans":3,"exp":"此造用比劫去财、不是直接用禄；午禄为寿元星，禄出现时丑午要穿，所以不敢见禄运。","sec":"三、禄、空亡与日禄归时","t":"calc"},{"q":"关于「关财门」，下列哪种认识符合盲派答疑？","opts":["伤官旺财也旺不关财门；大运坏财也是关","只要八字里伤官旺，无论财旺否都关财门","关财门专指财星入库，与大运好坏无关","只有原局见比劫夺财才叫关财门，大运不算"],"ans":0,"exp":"不一定伤官旺就关财门，若伤官旺财也旺就不会关财门；此外大运坏财也算关财门。","sec":"三、禄、空亡与日禄归时","t":"rule"},{"q":"女命找丈夫（配偶）时，宫位、星位与官星的判断先后是怎样的？","opts":["有杀先看杀，有官先看财，与宫位无关","宫位重于星位；有官先看官与夫妻宫关系","只看日支夫妻宫，局中官星一律不看","星位重于宫位；只看正官不管夫妻宫"],"ans":1,"exp":"妻（夫）是宫位与星位共同形成的关系，宫位比星位重要；局中有官先看官，官星与夫妻宫有关就以之为夫。","sec":"四、六亲的位置","t":"rule"},{"q":"「甲辛乙己／寅未亥卯」与「己丁乙癸／未卯亥未」同见亥卯未，为何前者得夫财而后者替人工作？","opts":["前者乙木坐亥长生，后者乙木坐卯太弱","前者有甲木劫财帮身，后者有丁火食神泄秀","前者禄在时归主位，后者中神在月且食外生","前者未土是财库，后者未土是空亡"],"ans":2,"exp":"前者归禄在时柱、局归主位，故得夫财；后者合局中神卯在月柱宾位，且食神向外生，故为他人服务。","sec":"四、六亲的位置","t":"diff"},{"q":"乾造「辛丙辛壬／丑申卯辰」中，「卯辰穿」为何被断为「妻不生男」？","opts":["辰为七杀代表男孩，被卯木克死在时支","因为妻宫卯木逢空亡，且申金克死了卯木","卯为食神代表男孩，被辰土合绊出不来","八字无杀以财为男，卯辰穿倒了妻宫的财"],"ans":3,"exp":"八字无官杀时以财为男孩，此造卯辰穿倒了妻宫的财，故主妻不生男。","sec":"四、六亲的位置","t":"xiang"},{"q":"「戊己庚戊／午未辰子」与「甲丁丙戊／辰卯辰子」同在主位见辰与子，为何前造差而后造贵？","opts":["前造子为伤官怕印制反局；后造体来制官杀用","前造庚金身弱不受生；后造丙火身旺能担官","前造子水在时支空亡；后造子水在时支得禄","前造午未合火克金；后造甲木印星生火"],"ans":0,"exp":"前造子水伤官出自辰体，若用印制伤官则辰助子水成反局；后造子水官杀是用，戊子合体来制用为正局。","sec":"四、六亲的位置","t":"diff"},{"q":"乾造「丁壬庚丁／巳寅戌丑」原局有盗贼之象，为何到「癸未年」才应验车被盗？","opts":["因为癸水伤官生寅木，寅木直接冲克了巳火","癸冲开丁壬合，且癸未与时柱天地冲、寅入未库","因为癸未年丑未相冲，把庚金的羊刃冲坏了","因为未土是劫财库，把年支巳火官星合走了"],"ans":1,"exp":"原局丁壬有合使贼不能作乱，待癸年冲开合便有失窃之应；癸未年与时柱天地冲且寅入未库，丢车又赔钱。","sec":"1. 车被盗的应期","t":"calc"},{"q":"乾造「壬壬丁辛／辰寅酉丑」中，寅丑暗合既带来巨财又导致败家，原因何在？","opts":["天干两壬争合丁火，导致日主意志不坚定","辰酉合把财库闭死，寅木想开库却力不从心","宾体取主用为反用得大财，但局去寅却用寅反局","寅木印星太弱，丑土财库太大，身弱不胜财"],"ans":2,"exp":"寅体在宾、丑用在主为反用，劫财取财得祖产；但局成金水势要去寅却想用寅，有反局之意故败家。","sec":"2. 赌博破产与继承遗产","t":"xiang"},{"q":"乾造「己丙丙戊／巳子寅戌」过亥运后当有牢狱之灾，其核心依据是什么？","opts":["因为日主丙火坐寅长生，比劫太重夺财","因为寅戌拱火太旺，把子水正官彻底熬干","因为己土伤官见了子水正官，必主牢狱","犯了「穿旺禄」大忌：官星生寅穿禄巳"],"ans":3,"exp":"最重要的是不能穿旺禄，此造官星生寅木穿巳禄，有牢狱之灾；亥运合寅解穿不应，过运当有。","sec":"3. 叛逆不读书","t":"rule"},{"q":"坤造「癸壬丁壬／卯戌未寅」做保险财务主管，「卯戌合」与「未戌刑」各象什么？","opts":["卯合戌象下属瞒财做小金库，未刑戌即打开管财","卯合戌象夫妻恩爱，未刑戌象婚姻破裂","卯合戌象投资亏损，未刑戌象变卖房产还债","卯合戌象自己贪污，未刑戌象遭到上司处分"],"ans":0,"exp":"卯合戌是包住戌中财，象下属隐瞒财务做小金库；未为丁半身，未戌刑制戌中辛财一刑就开，是管财的官。","sec":"4. 一个官命（保险公司财务主管）","t":"xiang"},{"q":"乾造「壬己乙戊／寅酉卯寅」见酉金病神，为何当不了官却能发大富？","opts":["因为日主乙木坐卯禄太旺，能用禄直接冲死酉金","原局官杀制不好不当官，大运泄官杀生禄发财","因为戊土正财透干，把酉金七杀合化为印星","因为酉金头上戴着乙木盖头，直接变成正财"],"ans":1,"exp":"酉金病神顶着己土财帽实为财；原局官杀无法制好不当官，行大运泄官杀生禄则以发财论。","sec":"5. 贵与富的几例","t":"calc"}]},{"n":163,"level":"专题","title":"命术轶闻断例精讲","qs":[{"q":"盲师一派断命，命局与大运流年各是什么关系？","opts":["先排大运定格局，再看命局喜忌","大运为根本，命局只是底子","命局大运各占一半，同等重要","命局为根本，大运流年只是应期"],"ans":3,"exp":"先从命局象看有无婚姻、发财、做官的信息，再排运流年定应期。","sec":"一、盲师一派的基本路数","t":"rule"},{"q":"八字里没有发财的信息，行财运会怎样？","opts":["未必能富，甚至行财运反而潦倒","财运多少只看运，原局不论","行财运必定发财","行财运小发，破财在后"],"ans":0,"exp":"八字是根本，行运是应期；原局无发财象，行财运也难发。","sec":"一、盲师一派的基本路数","t":"rule"},{"q":"长生十二宫（沐浴、临官、墓、绝、胎等）在盲派里怎么看？","opts":["是判断喜用神的依据","是描述事物从始到终的象，不是旺衰","是判断日主旺衰的标准","只用来断寿数，其他不看"],"ans":1,"exp":"长生十二宫是象，如乙在申为「胎」，应孩子与妻子一块来；不拿来定旺衰。","sec":"一、盲师一派的基本路数","t":"diff"},{"q":"盲师看妻（配偶）的取法，结婚前后有什么区别？","opts":["婚前婚后都只以财星为妻","婚前婚后都只以妻宫为妻","婚前以财为女朋友，婚后以妻宫为妻","婚前以妻宫为妻，婚后以财为妻"],"ans":2,"exp":"结婚前以财为女朋友，结婚后以妻宫（日支）为妻。","sec":"一、盲师一派的基本路数","t":"diff"},{"q":"女命官星在年上与官星在月上，所找对象有何不同？","opts":["官在年上找年纪大的，官在月上找年纪小的","官在年上找近处的，官在月上找远方的","官在年上主早婚，官在月上主晚婚","官在年上找远方的，官在月上找同学同事等近处的"],"ans":3,"exp":"年柱远、月柱近，官的位置定对象远近。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"diff"},{"q":"女命比劫旺，对象的年龄差一般是什么情况？","opts":["不是找年龄大很多的，就是找年龄小的","只找比自己小的","一般找比自己大一两岁的","多找年龄相当的"],"ans":0,"exp":"比劫旺定年龄差：不大就小，很少相当。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"rule"},{"q":"女命断婚时，七杀「管到」几岁？此前走财走官的流年可婚动。","opts":["十二岁","十六岁","二十岁","二十四岁"],"ans":1,"exp":"七杀管到十六岁；十六岁流年走财走官就结婚。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"rule"},{"q":"断子女时，食神与伤官各代表什么？刑克在食神，应什么？","opts":["食神为男、伤官为女；刑克食神克男","食神伤官都为女，刑克食神克女","食神为女、伤官为男；刑克食神克女","食神为女、伤官为男；刑克食神克子"],"ans":2,"exp":"食神为女，伤官为男；寅巳相刑刑在食神，所以克女儿。","sec":"二、断例一：癸巳 甲寅 甲辰 丁卯（孽情）","t":"diff"},{"q":"盲派里「违法星」是哪个字？它与官星相穿主什么？","opts":["丑；与官相穿，意为小人是非","戌；与官相合，意为官非","辰；与官相穿，意为官司缠身","戌；与官相穿，意为违反法律"],"ans":3,"exp":"核心看戌土，戌与官星相穿为违法；劫财伤官穿官是犯罪组合。","sec":"三、断例二：己酉 甲戌 甲申 乙丑（牢狱命定）","t":"rule"},{"q":"女命财官都入库、一直没婚姻，要等什么样的运才能成婚？","opts":["冲开库的运","比劫帮身的运","财官透干的运","印星当令的运"],"ans":0,"exp":"并非没有官财，而是入库不能用；冲开库之运才有婚。","sec":"四、断例三：辛卯 辛丑 丙辰 甲午（老姑娘）","t":"rule"},{"q":"「逢克论凶」速判法，原局克字多少代表什么？大运增加克字呢？","opts":["克字越多层次越高；运中增克则增吉","克字越多层次越低；运中增克则增凶","克字多少不论，只看生字多少","原局克多层次低；运中增克反而减凶"],"ans":1,"exp":"克代表破坏冲击，克字越多越凶；克数大于生数时应凶。","sec":"五、断例四：断“逢克论凶”的简易法","t":"rule"}],"fine":[{"q":"盲师一派断命时，「先断局、后排运」的具体操作顺序是什么？","opts":["先排大运流年看五行喜忌，再回头看原局结构","先定日主身强身弱，再排大运看用神是否得力","只看原局八个字即可断尽一生，绝不排大运流年","先从命局象断婚姻财官大事，再排运流年定应期"],"ans":3,"exp":"人一生的大事都以类象体现在命局中；先从命局断完婚姻、财官等大事，求问者追问哪年哪月时才排运查应期。","sec":"一、盲师一派的基本路数","t":"step"},{"q":"同是食神透干，有时断才华出众，有时却断此人很穷，盲派如何用「十神意向」解释？","opts":["见虚透无用财星，食神意向变为生财反做无用功","食神只要遇到官杀就一定变成贫穷之命","因为日主身弱不能泄秀，所以食神变成忌神","食神落在年柱主富贵，落在时柱主贫穷"],"ans":0,"exp":"十神在不同组合下意向不同：若局中见虚透无用的财星，食神意向变为生财，成了做无用功，反主贫穷。","sec":"一、盲师一派的基本路数","t":"xiang"},{"q":"乙木女友嫁给庚金男命，一入申位便断「孩子与妻子一块来」，用的是长生十二宫的哪一象？","opts":["乙在申为「长生」地","乙在申为「胎」地","乙在申为「沐浴」地","乙在申为「帝旺」地"],"ans":1,"exp":"长生十二宫是象而非旺衰：乙木在申为「胎」，故乙木女友一入申位，应了孩子与妻子一块来之象。","sec":"一、盲师一派的基本路数","t":"xiang"},{"q":"坤造「癸甲甲丁／巳寅辰卯」为何被断「四岁随娘改嫁，一个母亲两个父亲」？","opts":["因为日干甲木与月干甲木并透代表两个父亲","因为时支卯木直接冲克了年柱的印星","童运4岁起运很早，第一步运即见变动","因为年支巳火与月支寅木相刑克了父亲"],"ans":2,"exp":"此造童运起运早（4岁），第一步运便见变动，故断四岁随娘改嫁、一个母亲两个父亲。","sec":"1. 先断过去","t":"calc"},{"q":"坤造「癸甲甲丁／巳寅辰卯」4岁起运走卯运，「一进门就当后娘、首胎属兔」的依据是？","opts":["因为日支辰土是水库，库中藏有属兔的子女星","因为月干甲木坐寅禄，直接生出属兔的食神","因为年支巳火藏庚金七杀代表属兔的孩子","大运卯对应兔，子孙宫提前在婚前被引动"],"ans":3,"exp":"第一个大运走卯（对应属兔），走此运时还没结婚，子孙宫（时支卯）提前被引动，故第一个孩子属兔且在婚前。","sec":"1. 先断过去","t":"calc"},{"q":"坤造「癸甲甲丁／巳寅辰卯」到「己未大运」时，与年轻情人的关系为何仍在但不那么密切？","opts":["未中还有伤官丁火的余气","未土与日支辰土相刑，把情人刑走了","己土合绊住了年干癸水正印","未土是甲木日主的财库，把情人关进库里"],"ans":0,"exp":"丁火伤官代表儿子/年轻情人；到己未大运仍有那种关系但不密切，因为未中还有丁火余气。","sec":"2. 近年的隐情：情人是儿子","t":"calc"},{"q":"坤造「癸甲甲丁／巳寅辰卯」断「克死一个姑娘，儿子不错」，其命理依据是什么？","opts":["时支卯木羊刃冲克了月支寅木中的甲木","巳寅中丙火食神为女，寅巳相刑刑在食神","年干癸水正印直接克死了时干丁火伤官","日支辰土把年支巳火食神收入墓库之中"],"ans":1,"exp":"食神为女、伤官为男；巳中丙与寅中丙都是姑娘，寅巳相刑刑在食神所以克女；伤官丁火不受此刑故儿子不错。","sec":"3. 克女儿","t":"xiang"},{"q":"坤造「己甲甲乙／酉戌申丑」断「己巳年从南方发大财十万元」，其中「南方」与「十万」的依据分别是？","opts":["戌土为火库主南方；酉金正官主十万","巳火为离卦主十；申金七杀主南方","己坐巳火为南方；土财主五、十之数","乙木坐丑主南方；甲木合己主五、十"],"ans":2,"exp":"己巳年是甲己合财的应期，己坐巳火上故为南方之财；己土财星主五、十之数，故断十万元。","sec":"三、断例二：己酉 甲戌 甲申 乙丑（牢狱命定）","t":"calc"},{"q":"坤造「己甲甲乙／酉戌申丑」为何原局无牢狱，到「丁运」才出凶，且不是明火执仗式违法？","opts":["因为丁火正官在原局被酉金完全合住了","因为原局金水成势，丁运火来反局","因为丁运与年柱己酉形成天克地冲","原局丁隐不现，丁运支转干有生无制出凶"],"ans":3,"exp":"戌中伤官丁火隐而不现故非明火执仗；原局金旺火弱不明显对抗，到丁运「支转干」甲乙俱生丁、有生无制即出凶。","sec":"三、断例二：己酉 甲戌 甲申 乙丑（牢狱命定）","t":"rule"},{"q":"为何不能简单把八字十神分为「用神」和「忌神」？以「己酉 甲戌 甲申 乙丑」为例如何说明？","opts":["若分用忌，难同时解释从男人取财与犯牢狱","因为女命八字只能看夫宫，不能看官杀星","因为用神忌神每十年就会彻底颠倒一次","因为盲派根本不承认十神之间的生克关系"],"ans":0,"exp":"把八字简单分为用神忌神如同把人分敌友：若官杀为忌则难解从男人取财，若官杀为用则难解如何犯牢狱。","sec":"三、断例二：己酉 甲戌 甲申 乙丑（牢狱命定）","t":"rule"},{"q":"坤造「辛卯 辛丑 丙辰 甲午」虽为老姑娘，师父却断其「人很正派、本分」，依据是什么？","opts":["时柱甲午偏印坐羊刃，主性情刚直","正财辛金在天干且透干逢合","日支辰土是正印库，代表人品端正","年支卯木正印生丙火，主守礼本分"],"ans":1,"exp":"正财在天干，所以本分；「透干逢合」的表象只表示正直，但其财星生官和产生情欲的能力已因入丑墓而失去。","sec":"四、断例三：辛卯 辛丑 丙辰 甲午（老姑娘）","t":"xiang"},{"q":"从「老姑娘」命例总结出，一个在人生某方面有缺陷的八字，其命局共同特点是什么？","opts":["该十神必然落在年柱或时柱的空亡之地","命局八个字里彻底不见代表该事的十神","并非没有该星，而是有并占位却被坏或无用","日主身弱且该十神全部透出在天干之上"],"ans":2,"exp":"无婚姻的女命并非没有官杀星，而是有并占据其位却不能用（如入库）；人生某方面有缺陷皆是有而被坏或无用。","sec":"四、断例三：辛卯 辛丑 丙辰 甲午（老姑娘）","t":"rule"},{"q":"「逢克论凶」速判法在排查原局之「克」时，先后顺序是什么？","opts":["先看地支三合六合，再看天干五合","先用天干去克地支，再用地支去克天干","先看年柱与时柱遥克，再看同柱生克","先看同柱盖头截脚，再干论干、支论支"],"ans":3,"exp":"原局排查顺序：先看同柱有无盖头截脚；再天干和天干论，地支和地支论；大运流年流月同样按此与原局逐字论。","sec":"五、断例四：断“逢克论凶”的简易法","t":"step"},{"q":"按「逢克论凶」速判法的五行克数规则，如何区分「专旺格」与「从格」？","opts":["一种五行0个克为专旺，两种五行3个克为从格","两种五行0个克为专旺，三种五行4个克为从格","无论几种五行，只要克数大于生数就是从格","一种五行1个克为专旺，两种五行2个克为从格"],"ans":0,"exp":"只有一种五行时，0个克是专旺格；有两种五行时，3个克就是从格。该法约适用80%命局定性，最终仍须回作功体用。","sec":"五、断例四：断“逢克论凶”的简易法","t":"calc"},{"q":"「逢克论凶」速判法适用范围约80%，遇「克」时最终仍须回到什么来定性？","opts":["回到日主旺衰与调候用神来定性","回到作功、宾主、体用来定性","只需数清克与生的绝对差值即可","回到纳音五行与神煞吉凶来定性"],"ans":1,"exp":"「逢克论凶」只是速判法，并非适用所有命局，与作功论相互补充；遇到克时仍须回到做功、宾主、体用来定性。","sec":"五、断例四：断“逢克论凶”的简易法","t":"rule"},{"q":"天干重字断语中，「三戊」与「三乙」各主什么？","opts":["三戊天上贵，三乙多灾危","三戊富不长，三乙刃上亡","三戊家园败，三乙奔四方","三戊万里有田庄，三乙入火乡"],"ans":2,"exp":"天干重字诀：三甲天上贵，三壬富不长，三戊家园败，三丁多灾危，三庚是才郎、万里有田庄，三己入火乡，三乙奔四方。","sec":"1. 天干重字","t":"rule"},{"q":"地支重字断语中，「三辰」与「三戌」各主什么？","opts":["三辰婚事重，三戌孤独守","三辰阵上亡，三戌是和尚","三辰有残伤，三戌守空亡","三辰是和尚，三戌阵上亡"],"ans":3,"exp":"地支重字诀：三子婚事重，三丑孤独守，三寅四妻房，三卯凶恶多，三巳刑与害，三午克妻房，三辰是和尚，三戌阵上亡。","sec":"2. 地支重字","t":"rule"},{"q":"《断运篇》十二长生分属五行中，木与水各分属哪几个长生宫？","opts":["木属帝旺、墓；水属沐浴、病、绝、胎","木属冠带、衰；水属帝旺、墓","木属沐浴、病；水属长生、冠带","木属长生、衰；水属临官、死"],"ans":0,"exp":"十二长生分属五行：金属长生、衰；木属帝旺、墓；水属沐浴、病、绝、胎；火属临官、死；土属冠带、衰。","sec":"七、断运篇：长生十二宫的论断要点","t":"calc"},{"q":"《断运篇》「十二长生之克」中，少年、中年、老年三个阶段各最怕什么运？","opts":["少怕长生、中年怕建禄、老怕墓库之地","少怕衰、中年怕死绝胎、老怕帝旺与长生遇冲","少怕临官、中年怕养字、老怕衰病之地","少怕帝旺、中年怕长生、老怕沐浴冠带"],"ans":1,"exp":"「老怕帝旺少怕衰，中年最怕死绝胎」，且「老年就怕长生运，如遇刑冲难还阳」。","sec":"七、断运篇：长生十二宫的论断要点","t":"rule"},{"q":"《断运篇》中，长生、沐浴、冠带三步运各最怕遇到什么？","opts":["长生怕比肩，沐浴怕伤官，冠带怕正财","长生怕食神，沐浴怕正官，冠带怕羊刃","长生怕劫财，沐浴怕比肩，冠带怕建禄与伤官","长生怕正印，沐浴怕偏财，冠带怕七杀"],"ans":2,"exp":"「长生最怕劫财降，沐浴一见比肩亡，冠带最怕建禄灾……冠带最怕伤官透」。","sec":"七、断运篇：长生十二宫的论断要点","t":"rule"},{"q":"《五行取用诀》中，秋木与冬木在干支取用上有何不同？","opts":["秋木最喜壬癸水养，冬木最喜旺金削枝","秋木忌见丙丁火，冬木忌见戊己土","秋木冬木都只喜壬癸水泛，不喜火土","秋木干头爱丙丁，冬木须土与火温暖发根"],"ans":3,"exp":"秋木逢旺金，干头爱丙丁，忌金木相战；冬木枯冷怕金削，须有土相逢火温暖发根。","sec":"八、五行取用诀（按五行摘要）","t":"diff"},{"q":"《五行取用诀》中，夏火遇「火盛土燥」时，对壬水与癸水的喜忌如何？","opts":["宜壬不宜癸","壬癸同等大吉","壬癸一概忌见","宜癸不宜壬"],"ans":0,"exp":"夏火「火盛土燥，无水不好，宜壬不宜癸」；此外未戌多孤寡，丑辰是良才。","sec":"八、五行取用诀（按五行摘要）","t":"diff"},{"q":"《增补四言独步》中，伤官落在年、月、日、时四柱各主什么？","opts":["年月兄弟不完，月上南配良缘，日伤躯，时父母全","年月父母不全，月上兄弟不完，日良缘，时无传","年月贵不可言，月上富贵自来，日困监，时多产危","年月子孙无传，月上父母不全，日克妻，时良缘"],"ans":1,"exp":"《增补四言独步》：年月伤官父母不全，月上伤官兄弟不完，日上伤官南配良缘，时上伤官子孙无传。","sec":"九、增补四言独步（节要）","t":"rule"},{"q":"《增补四言独步》中，辰多、戌多、合多、冲多各主什么？","opts":["辰多富贵，戌多清贫，合多主贵，冲多主发","辰多好讼，戌多好斗，合多主凶，冲多主晦","辰多好斗，戌多好讼，合多主晦，冲多主凶","辰多主晦，戌多主凶，合多好斗，冲多好讼"],"ans":2,"exp":"《增补四言独步》关于库与冲合有言：「财官入库，不冲不发……辰多好斗，戌多好讼；合多主晦，冲多主凶。」","sec":"九、增补四言独步（节要）","t":"rule"}]}]};
